export const reportHtml = "<div id=\"dot-net-report\" class=\"body-content\">\n<div class=\"container-fluid\">\n    <div data-bind=\"template: {name: 'admin-mode-template'}, visible: allowAdmin\" style=\"display: none;\"></div>\n\n    <!--\n        The markup code below is related to presentation. You don't have to change it, unless you\n        intentionally want to change something in the Report Builder's behavior in your Application.\n        It's Recommended you use it as is. You will be responsible for managing and maintaining any changes.\n    -->\n    <!-- Folders/Report List -->\n    <div id=\"report-start\" data-bind=\"if: ReportMode() == 'start' || ReportMode() == 'generate'\">\n        <div class=\"card folder-panel\" data-bind=\"visible: true\" style=\"display: none;\">\n            <div class=\"card-header\">\n                <nav class=\"navbar navbar-expand-lg navbar-light bg-light\">\n                    <a class=\"navbar-brand\" href=\"#\" data-bind=\"click: function() {SelectedFolder(null); designingHeader(false); designingFooter(false); searchReports(''); $('#search-report').val([]).trigger('change'); }\">Manage Reports</a>\n                    <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#navbarSupportedContent\" aria-controls=\"navbarSupportedContent\" aria-expanded=\"false\" aria-label=\"Toggle navigation\">\n                        <span class=\"navbar-toggler-icon\"></span>\n                    </button>\n\n                    <div class=\"collapse navbar-collapse\" id=\"navbarSupportedContent\">\n                        <ul class=\"navbar-nav mr-auto\">\n                            <li class=\"nav-item\" data-bind=\"visible: (CanSaveReports() || adminMode()) && (!SelectedFolder() || SelectedFolder().canEdit || adminMode())\">\n                                <a href=\"#\" class=\"nav-link\" data-bind=\"click: createNewReport\" data-bs-toggle=\"modal\" data-bs-target=\"#modal-reportbuilder\">\n                                    <span class=\"fa fa-plus\"></span> New Report\n                                </a>\n                            </li>\n                            <li class=\"nav-item\" data-bind=\"visible: CanManageFolders() || adminMode()\">\n                                <a href=\"#\" class=\"nav-link\" data-bind=\"click: ManageFolder.newFolder\">\n                                    <span class=\"fa fa-folder-open\"></span> Add Folder\n                                </a>\n                            </li>\n                            <li class=\"nav-item dropdown\" data-bind=\"visible: (CanManageFolders() || adminMode()) && SelectedFolder()!=null && (SelectedFolder().canEdit || SelectedFolder().canDelete || adminMode())\">\n                                <a href=\"#\" class=\"nav-link dropdown-toggle\" role=\"button\" data-bs-toggle=\"dropdown\" aria-haspopup=\"true\" aria-expanded=\"false\">\n                                    <span class=\"fa fa-folder\"></span> Folder Options\n                                </a>\n                                <div class=\"dropdown-menu\">\n                                    <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: ManageFolder.editFolder, visible: SelectedFolder() && (SelectedFolder().canEdit || adminMode())\">Edit Selected Folder</a>\n                                    <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: ManageFolder.deleteFolder, visible: SelectedFolder() && (SelectedFolder().canDelete || adminMode())\">Delete Selected Folder</a>\n                                    <a class=\"dropdown-item\" href=\"#\"\n                                       data-bind=\"click: ManageFolder.addSubFolder, visible: SelectedFolder() && (SelectedFolder().canEdit || adminMode())\">\n                                        <span class=\"fa fa-folder\"></span> Add Sub Folder\n                                    </a>\n                                </div>\n                            </li>\n                            <li class=\"nav-item dropdown\" data-bind=\"visible: adminMode() && SelectedFolder() ==null\">\n                                <a href=\"#\" class=\"nav-link dropdown-toggle\" role=\"button\" data-bs-toggle=\"dropdown\" aria-haspopup=\"true\" aria-expanded=\"false\">\n                                    <span class=\"fa fa-window-maximize\"></span> Header / Footer\n                                </a>\n                                <div class=\"dropdown-menu\">\n                                    <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function(){ initHeaderDesigner(false); }\">\n                                        <span class=\"fa fa-arrow-up\"></span> Report Header\n                                    </a>\n                                    <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function(){ initFooterDesigner(false); }\">\n                                        <span class=\"fa fa-arrow-down\"></span> Report Footer\n                                    </a>\n                                </div>\n                            </li>\n                            <li class=\"nav-item dropdown\" data-bind=\"visible: appSettings.showImportExport() || adminMode()\">\n                                <a href=\"#\" class=\"nav-link dropdown-toggle\" role=\"button\" data-bs-toggle=\"dropdown\" aria-haspopup=\"true\" aria-expanded=\"false\">\n                                    <span class=\"fa fa-exchange\"></span> Import / Export\n                                </a>\n                                <div class=\"dropdown-menu\">\n                                    <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function(){ selectMode(!selectMode()); }\">\n                                        <span data-bind=\"css: selectMode() ? 'fa fa-check-square text-primary' : 'fa fa-square-o'\"></span>\n                                        <span data-bind=\"text: selectMode() ? 'Cancel Select Mode' : 'Select Mode'\"></span>\n                                    </a>\n                                    <div class=\"dropdown-divider\"></div>\n                                    <a class=\"dropdown-item\" href=\"#\" data-bs-toggle=\"modal\" data-bs-target=\"#uploadFileModal\" data-bind=\"visible: !selectMode()\" title=\"Import Report from JSON file\">\n                                        <span class=\"fa fa-upload\"></span> Import Reports\n                                    </a>\n                                    <a class=\"dropdown-item\" href=\"#\" data-bind=\"visible: selectMode, click: exportSelectedReportJson\">\n                                        <span class=\"fa fa-download\"></span> Export Selected Reports\n                                    </a>\n                                </div>\n                            </li>\n                        </ul>\n                        <div class=\"form-inline my-2 my-lg-0 ms-auto w-50\">\n                            <div class=\"input-group w-100\">\n                                <p id=\"search-input\" class=\"form-control search-input\" data-placeholder=\"Search Report by Name, Description or Data Field...\"></p>\n                                <span data-bind=\"click: searchForReports\" class=\"input-group-text\" style=\"height: 38px; cursor: pointer;\" title=\"Search\"><i class=\"fa fa-search\"></i></span>\n                                <span data-bind=\"click: function() {resetQuery(true, true);}\" class=\"input-group-text\" style=\"height: 38px; cursor: pointer;\" title=\"Clear Search\"><i class=\"fa fa-close\"></i></span>\n                                <span data-bind=\"visible: !selectMode(), click: function(){ onlyFavorites(!onlyFavorites()); }, css: { 'bg-warning-subtle': onlyFavorites() }, attr: { title: onlyFavorites() ? 'Showing only Favorites - click to show all' : 'Show only Favorites' }\"\n                                      class=\"input-group-text\" style=\"height: 38px; cursor: pointer;\">\n                                    <i data-bind=\"css: onlyFavorites() ? 'fa fa-star text-warning' : 'fa fa-star-o'\"></i>\n                                </span>\n                            </div>\n                        </div>\n                    </div>\n                </nav>\n            </div>\n            <div class=\"card-body\">\n                <div data-bind=\"visible: designingHeader, with: headerDesigner\" style=\"display: none;\" class=\"overflow-auto\">\n                    <div class=\"report-header-designer\">\n                        <div class=\"d-flex align-items-center flex-wrap mb-3\">\n                            <h6 class=\"mb-0 me-2\"><i class=\"fa fa-window-maximize text-primary\"></i> Report Headers</h6>\n                            <span class=\"text-muted small\">A client (or Global) can have several named headers. The one marked <b>Default</b> is used when a report doesn't pick one.</span>\n                        </div>\n\n                        <!-- Overall on/off for report headers -->\n                        <div class=\"form-check form-switch mb-2\">\n                            <input class=\"form-check-input\" type=\"checkbox\" id=\"rptHeaderUse\" data-bind=\"checked: UseReportHeader\">\n                            <label class=\"form-check-label\" for=\"rptHeaderUse\">Use report headers <span class=\"text-muted small\">(uncheck to stop applying headers in reports)</span></label>\n                        </div>\n\n                        <!-- Off state (use `if` so .d-flex !important can't override a hidden state) -->\n                        <div data-bind=\"if: !UseReportHeader()\">\n                            <div class=\"alert alert-secondary d-flex align-items-center justify-content-between py-2\">\n                                <span><i class=\"fa fa-eye-slash\"></i> Report headers are turned off and won't be applied in reports.</span>\n                                <button class=\"btn btn-primary btn-sm\" data-bind=\"click: saveHtmlHeader\"><i class=\"fa fa-save\"></i> Save</button>\n                            </div>\n                        </div>\n\n                        <!-- Designer (hidden when report headers are turned off) -->\n                        <div data-bind=\"visible: UseReportHeader\">\n                        <!-- Selection toolbar -->\n                        <div class=\"d-flex flex-wrap align-items-end gap-2 mb-3\">\n                            <div data-bind=\"visible: clientListIds().length > 0\">\n                                <label class=\"form-label small text-muted mb-1\">Client scope</label>\n                                <select class=\"form-select form-select-sm\" style=\"min-width: 200px;\"\n                                        data-bind=\"options: clientListIds,\n                                            value: selectedHeaderClientId,\n                                            optionsCaption: 'Global (all clients)',\n                                            event: { change: function () { loadHeadersList(); } }\">\n                                </select>\n                            </div>\n                            <div>\n                                <label class=\"form-label small text-muted mb-1\">Header</label>\n                                <select class=\"form-select form-select-sm\" style=\"min-width: 240px;\"\n                                        data-bind=\"options: headersList,\n                                            optionsText: 'label',\n                                            optionsValue: 'id',\n                                            value: selectedHeaderId,\n                                            event: { change: function () { loadHeaderById(); } }\">\n                                </select>\n                            </div>\n                            <div class=\"ms-auto d-flex gap-2\">\n                                <button class=\"btn btn-sm btn-outline-primary\" data-bind=\"click: newHeader\"><i class=\"fa fa-plus\"></i> New</button>\n                                <button class=\"btn btn-sm btn-outline-danger\" data-bind=\"click: deleteHeader, visible: selectedHeaderId() > 0\"><i class=\"fa fa-trash\"></i> Delete</button>\n                            </div>\n                        </div>\n\n                        <!-- Editor card -->\n                        <div class=\"card shadow-sm\">\n                            <div class=\"card-header bg-light py-2 d-flex align-items-center flex-wrap gap-2\">\n                                <div class=\"flex-grow-1\" style=\"min-width: 220px;\">\n                                    <input class=\"form-control form-control-sm fw-semibold\" type=\"text\" placeholder=\"Header name (e.g. Invoice header)\" data-bind=\"value: headerName\">\n                                </div>\n                                <div class=\"form-check mb-0\">\n                                    <input class=\"form-check-input\" type=\"checkbox\" id=\"rptHeaderDefault\" data-bind=\"checked: isDefault\">\n                                    <label class=\"form-check-label small\" for=\"rptHeaderDefault\">Default for this scope</label>\n                                </div>\n                            </div>\n                            <div class=\"card-body p-2\">\n                                <div class=\"d-flex flex-wrap align-items-center gap-3 mb-2\">\n                                    <div class=\"dropdown\">\n                                        <button type=\"button\" class=\"btn btn-sm btn-outline-secondary dropdown-toggle\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">\n                                            <i class=\"fa fa-code\"></i> Insert Variable\n                                        </button>\n                                        <ul class=\"dropdown-menu\">\n                                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { insertPlaceholder('{page.number}'); }\">Page Number</a></li>\n                                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { insertPlaceholder('{page.total}'); }\">Total Pages</a></li>\n                                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { insertPlaceholder('{current.user}'); }\">Current User</a></li>\n                                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { insertPlaceholder('{current.user.roles}'); }\">Current User Roles</a></li>\n                                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { insertPlaceholder('{current.datetime}'); }\">Current Date/Time</a></li>\n                                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { insertPlaceholder('{report.name}'); }\">Report Name</a></li>\n                                        </ul>\n                                    </div>\n                                    <div class=\"form-check mb-0\">\n                                        <input class=\"form-check-input\" type=\"checkbox\" id=\"rptHeaderEveryPage\" data-bind=\"checked: IncludeOnEveryPage\">\n                                        <label class=\"form-check-label small\" for=\"rptHeaderEveryPage\">Repeat on every page (PDF/Word)</label>\n                                    </div>\n                                </div>\n                                <textarea id=\"report-header-editor\"></textarea>\n                            </div>\n                            <div class=\"card-footer bg-white d-flex align-items-center flex-wrap gap-2 py-2\">\n                                <button type=\"button\" class=\"btn btn-sm btn-link text-decoration-none px-0\" data-bind=\"visible: !showClientScope(), click: function() { showClientScope(true); }\">\n                                    <i class=\"fa fa-user\"></i> <span data-bind=\"text: headerClientId() ? 'Change client (' + headerClientId() + ')' : 'Restrict to a Client Id'\"></span>\n                                </button>\n                                <div data-bind=\"visible: showClientScope\" class=\"input-group input-group-sm\" style=\"max-width: 400px;\">\n                                    <span class=\"input-group-text\">Client Id</span>\n                                    <input class=\"form-control\" type=\"text\" placeholder=\"Blank = Global\" data-bind=\"value: headerClientId, event: { change: function () { applyHeaderScope(); } }\">\n                                    <button class=\"btn btn-outline-secondary\" type=\"button\" data-bind=\"click: cancelHeaderScope\" title=\"Cancel\"><i class=\"fa fa-times\"></i></button>\n                                    <span class=\"input-group-text bg-white\" data-bs-toggle=\"tooltip\" data-placement=\"top\" title=\"Leave blank for a Global header. Changing this switches to that client's headers.\"><i class=\"fa fa-question-circle helptip\"></i></span>\n                                </div>\n                                <button class=\"btn btn-primary btn-sm ms-auto\" data-bind=\"click: saveHtmlHeader\">\n                                    <i class=\"fa fa-save\"></i> Save Header\n                                </button>\n                            </div>\n                        </div>\n                        </div>\n                    </div>\n                </div>\n                <div data-bind=\"visible: designingFooter, with: footerDesigner\" style=\"display: none;\" class=\"overflow-auto\">\n                    <div class=\"report-header-designer\">\n                        <div class=\"d-flex align-items-center flex-wrap mb-3\">\n                            <h6 class=\"mb-0 me-2\"><i class=\"fa fa-window-minimize text-primary\"></i> Report Footer</h6>\n                            <span class=\"text-muted small\">One footer per client (or Global), applied to reports where footers are turned on.</span>\n                        </div>\n\n                        <!-- Overall on/off for report footers -->\n                        <div class=\"form-check form-switch mb-2\">\n                            <input class=\"form-check-input\" type=\"checkbox\" id=\"rptFooterUse\" data-bind=\"checked: UseReportFooter\">\n                            <label class=\"form-check-label\" for=\"rptFooterUse\">Use report footers <span class=\"text-muted small\">(uncheck to stop applying footers in reports)</span></label>\n                        </div>\n\n                        <!-- Off state (use `if` so .d-flex !important can't override a hidden state) -->\n                        <div data-bind=\"if: !UseReportFooter()\">\n                            <div class=\"alert alert-secondary d-flex align-items-center justify-content-between py-2\">\n                                <span><i class=\"fa fa-eye-slash\"></i> Report footers are turned off and won't be applied in reports.</span>\n                                <button class=\"btn btn-primary btn-sm\" data-bind=\"click: saveHtmlFooter\"><i class=\"fa fa-save\"></i> Save</button>\n                            </div>\n                        </div>\n\n                        <!-- Designer (hidden when report footers are turned off) -->\n                        <div data-bind=\"visible: UseReportFooter\">\n                        <!-- Selection toolbar (footer has one per scope, so just the client scope) -->\n                        <div data-bind=\"visible: clientListIds().length > 0\" class=\"d-flex flex-wrap align-items-end gap-2 mb-3\">\n                            <div>\n                                <label class=\"form-label small text-muted mb-1\">Client scope</label>\n                                <select class=\"form-select form-select-sm\" style=\"min-width: 200px;\"\n                                        data-bind=\"options: clientListIds,\n                                            value: selectedFooterClientId,\n                                            optionsCaption: 'Global (all clients)',\n                                            event: { change: function () { loadHtmlFooter(false); } }\">\n                                </select>\n                            </div>\n                        </div>\n\n                        <!-- Editor card -->\n                        <div class=\"card shadow-sm\">\n                            <div class=\"card-body p-2\">\n                                <div class=\"d-flex flex-wrap align-items-center gap-3 mb-2\">\n                                    <div class=\"dropdown\">\n                                        <button type=\"button\" class=\"btn btn-sm btn-outline-secondary dropdown-toggle\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">\n                                            <i class=\"fa fa-code\"></i> Insert Variable\n                                        </button>\n                                        <ul class=\"dropdown-menu\">\n                                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { insertPlaceholder('{page.number}'); }\">Page Number</a></li>\n                                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { insertPlaceholder('{page.total}'); }\">Total Pages</a></li>\n                                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { insertPlaceholder('{current.user}'); }\">Current User</a></li>\n                                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { insertPlaceholder('{current.user.roles}'); }\">Current User Roles</a></li>\n                                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { insertPlaceholder('{current.datetime}'); }\">Current Date/Time</a></li>\n                                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { insertPlaceholder('{report.name}'); }\">Report Name</a></li>\n                                        </ul>\n                                    </div>\n                                    <div class=\"form-check mb-0\">\n                                        <input class=\"form-check-input\" type=\"checkbox\" id=\"rptFooterEveryPage\" data-bind=\"checked: IncludeOnEveryPage\">\n                                        <label class=\"form-check-label small\" for=\"rptFooterEveryPage\">Repeat on every page (PDF/Word)</label>\n                                    </div>\n                                </div>\n                                <textarea id=\"report-footer-editor\"></textarea>\n                            </div>\n                            <div class=\"card-footer bg-white d-flex align-items-center flex-wrap gap-2 py-2\">\n                                <button type=\"button\" class=\"btn btn-sm btn-link text-decoration-none px-0\" data-bind=\"visible: !showClientScope(), click: function() { showClientScope(true); }\">\n                                    <i class=\"fa fa-user\"></i> <span data-bind=\"text: footerClientId() ? 'Change client (' + footerClientId() + ')' : 'Restrict to a Client Id'\"></span>\n                                </button>\n                                <div data-bind=\"visible: showClientScope\" class=\"input-group input-group-sm\" style=\"max-width: 400px;\">\n                                    <span class=\"input-group-text\">Client Id</span>\n                                    <input class=\"form-control\" type=\"text\" placeholder=\"Blank = Global\" data-bind=\"value: footerClientId, event: { change: function () { applyFooterScope(); } }\">\n                                    <button class=\"btn btn-outline-secondary\" type=\"button\" data-bind=\"click: cancelFooterScope\" title=\"Cancel\"><i class=\"fa fa-times\"></i></button>\n                                    <span class=\"input-group-text bg-white\" data-bs-toggle=\"tooltip\" data-placement=\"top\" title=\"Leave blank for a Global footer. Changing this switches to that client's footer.\"><i class=\"fa fa-question-circle helptip\"></i></span>\n                                </div>\n                                <button class=\"btn btn-primary btn-sm ms-auto\" data-bind=\"click: saveHtmlFooter\">\n                                    <i class=\"fa fa-save\"></i> Save Footer\n                                </button>\n                            </div>\n                        </div>\n                        </div>\n                    </div>\n                </div>\n                <div data-bind=\"visible: !designingHeader() && !designingFooter()\">\n                    <div class=\"btn-group\" style=\"float: right\" role=\"group\">\n                        <button type=\"button\" class=\"btn btn-light\" data-bs-toggle=\"tooltip\" title=\"List View\"\n                                data-bind=\"css: { 'active': layout() === 'list' }, click: toggleLayout\">\n                            <span class=\"fa fa-list\"></span>\n                        </button>\n                        <button type=\"button\" class=\"btn btn-light\" data-bs-toggle=\"tooltip\" title=\"Icon View\"\n                                data-bind=\"css: { 'active': layout() === 'icons' }, click: toggleLayout\">\n                            <span class=\"fa fa-th-large\"></span>\n                        </button>\n                    </div>\n                    <div data-bind=\"if: layout()=='icons'\">\n                        <div data-bind=\"visible: !SelectedFolder() && !searchReports()\">\n                            <p>Please choose Folders below to view Reports</p>\n                            <ul class=\"folder-list\" data-bind=\"foreach: rootFolders\">\n                                <li data-bind=\"click: function(){ $parent.SelectedFolder($data); }\">\n                                    <span data-bind=\"visible: $root.selectMode, click: function(d,e){ isSelected(!isSelected()); e.stopPropagation(); },\n                                        css: isSelected() ? 'fa fa-check-square text-primary me-2' : 'fa fa-square-o me-2'\"></span>\n                                    <span class=\"fa fa-3x fa-folder text-secondary\"></span>\n                                    <span class=\"desc\" data-bind=\"text: FolderName\"></span>\n                                    <div data-bind=\"visible: $root.adminMode\" style=\"font-size: 0.75em; margin-top: 4px;\" onclick=\"event.stopPropagation()\">\n                                        <div data-bind=\"template: { name: 'access-badges', data: $data }\"></div>\n                                    </div>\n                                </li>\n                            </ul>\n                        </div>\n                        <div data-bind=\"visible: SelectedFolder() || searchReports()\">\n                            <div class=\"clearfix\">\n                                <p class=\"pull-left\">Please choose a Report from this Folder</p>\n                                <div class=\"pull-right\">\n                                    <a href=\"#\" class=\"btn btn-light\" data-bind=\"click: goBackFolder\">\n                                        <span data-bind=\"text: SelectedFolder() && SelectedFolder().ParentFolderId ? '..back to ' + (folderBreadcrumb().length > 1 ? folderBreadcrumb()[folderBreadcrumb().length - 2].FolderName : 'Folders') : '..back to Folders'\"></span>\n                                    </a>\n                                </div>\n                            </div>\n                            <div class=\"list-group list-overflow\">\n\n                                <!-- Empty states -->\n                                <div data-bind=\"if: SelectedFolder() != null\n                                    && reportsInFolder().length == 0\n                                    && subFoldersInFolder().length == 0\n                                    && !searchReports()\">\n                                    <p class=\"text-muted\">This folder is empty.</p>\n                                </div>\n                                <div data-bind=\"if: searchReports() && reportsInSearch().length==0 && foldersInSearch().length==0\">\n                                    No results found matching your search.\n                                </div>\n\n                                <!-- Search: matching folders -->\n                                <div data-bind=\"if: searchReports() && foldersInSearch().length > 0\">\n                                    <div class=\"mt-1 mb-1\"><strong><span class=\"fa fa-folder\"></span> Matching Folders</strong></div>\n                                    <ul class=\"folder-list\" data-bind=\"foreach: foldersInSearch\">\n                                        <li data-bind=\"click: function(){ $parent.SelectedFolder($data); $parent.searchReports(''); }\">\n                                            <span class=\"fa fa-3x fa-folder text-secondary\"></span>\n                                            <span class=\"desc\" data-bind=\"highlightedText: { text: FolderName, highlight: $parent.searchReports, css: 'highlight' }\"></span>\n                                            <div data-bind=\"visible: $root.adminMode\" style=\"font-size: 0.75em; margin-top: 4px;\" onclick=\"event.stopPropagation()\">\n                                                <div class=\"d-flex flex-wrap gap-1\">\n                                                    <div data-bind=\"template: { name: 'access-badges', data: $data }\"></div>\n                                                </div>\n                                            </div>\n                                        </li>\n                                    </ul>\n                                    <hr />\n                                </div>\n\n                                <!-- SUB-FOLDERS inside selected folder -->\n                                <div data-bind=\"if: !searchReports() && subFoldersInFolder().length > 0\">\n                                    <ul class=\"folder-list\" data-bind=\"foreach: subFoldersInFolder\">\n                                        <li data-bind=\"click: function(){ $parent.SelectedFolder($data); }\">\n                                            <span class=\"fa fa-3x fa-folder text-secondary\"></span>\n                                            <span class=\"desc\" data-bind=\"text: FolderName\"></span>\n                                            <div data-bind=\"visible: $root.adminMode\"\n                                                 style=\"font-size: 0.75em; margin-top: 4px;\"\n                                                 onclick=\"event.stopPropagation()\">\n                                                <div data-bind=\"template: { name: 'access-badges', data: $data }\"></div>\n                                            </div>\n                                        </li>\n                                    </ul>\n                                    <hr class=\"my-2\" />\n                                </div>\n                                \n                                <!-- REPORTS (icon view) -->\n                                <div class=\"list-group\"\n                                     data-bind=\"foreach: searchReports() ? reportsInSearch() : reportsInFolder()\">\n                                    <div class=\"list-group-item\">\n                                        <div class=\"row\">\n                                            <div class=\"col-sm-7\">\n                                                <input type=\"checkbox\" data-bind=\"visible: $root.selectMode, checked: isSelected\" class=\"float-start me-2\" />\n                                                <div class=\"fa fa-2x float-start\" data-bind=\"css: {'fa-file': reportType=='List', 'fa-th-list': reportType=='Summary', 'fa-bar-chart': reportType=='Bar', 'fa-pie-chart': reportType=='Pie',  'fa-line-chart': reportType=='Line', 'fa-globe': reportType.indexOf('Map')==0, 'fa-window-maximize': reportType=='Single', 'fa-random': reportType=='Pivot', 'fa-window-restore': reportType=='Treemap', 'fa-signal': reportType == 'Combo', 'fa-code': reportType == 'Html', 'fa-map': reportType == 'HeatMap'}\"></div>\n                                                <div class=\"float-start\">\n                                                    <h4>\n                                                        <a data-bind=\"click: runReport\" style=\"cursor: pointer\">\n                                                            <span data-bind=\"highlightedText: { text: reportName, highlight: $parent.searchReports, css: 'highlight' }\"></span>\n                                                        </a>\n                                                        <span class=\"fa favorite-hover-star ms-1\"\n                                                              data-bind=\"css: isFavorite() ? 'fa-star text-warning favorited' : 'fa-star-o',\n                                                                         click: $parent.toggleFavorite, clickBubble: false,\n                                                                         visible: !$root.selectMode()\"\n                                                              title=\"Add/Remove Favorite\"></span>\n                                                    </h4>\n                                                </div>\n                                                <div class=\"clearfix\"></div>\n                                                <p data-bind=\"text: reportDescription\"></p>\n                                                <p data-bind=\"if: $parent.searchReports()\">\n                                                    <span class=\"fa fa-folder\"></span> <span data-bind=\"text: folderName\"></span>\n                                                    <span>\n                                                        <span data-bind=\"text: message\" class=\"highlight small\"></span>\n                                                    </span>\n                                                </p>\n                                                <div data-bind=\"if: isSubReportOnly && isSubReportOnly()\">\n                                                    <span class=\"badge bg-warning text-dark mt-1\"><i class=\"fa fa-link\"></i> Sub Report Only</span>\n                                                </div>\n                                                <div data-bind=\"if: $parent.adminMode\">\n                                                    <div class=\"d-flex flex-wrap gap-1 align-items-center mt-1\">\n                                                        <div data-bind=\"template: { name: 'access-badges', data: $data }\"></div>\n                                                        <a data-bind=\"attr: {href: '/DotNetReport/?linkedreport=true&noparent=true&reportId=' + reportId }\" target=\"_blank\" title=\"Direct Link\"><span class=\"fa fa-link\"></span></a>\n                                                        <a href=\"#\" data-bind=\"click: function() { navigator && navigator.clipboard && navigator.clipboard.writeText('/DotNetReport?linkedreport=true&noparent=true&reportId=' + reportId) }\" title=\"Copy Link\"><span class=\"fa fa-copy\"></span></a>\n                                                    </div>\n                                                </div>\n                                            </div>\n                                            <div class=\"col-sm-5 right-align\">\n                                                <div class=\"d-none d-md-block\">\n                                                    <br />\n                                                    <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"visible: canEdit, click: openReport\" data-bs-toggle=\"modal\" data-bs-target=\"#modal-reportbuilder\">\n                                                        <span class=\"fa fa-edit\" aria-hidden=\"true\"></span> Edit\n                                                    </button>\n                                                    <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: copyReport, visible: (canEdit || $parent.appSettings.canCopyReport) && ($root.CanSaveReports() || $root.adminMode())\" data-bs-toggle=\"modal\" data-bs-target=\"#modal-reportbuilder\">\n                                                        <span class=\"fa fa-copy\" aria-hidden=\"true\"></span> Copy\n                                                    </button>\n                                                    <div class=\"btn-group\">\n                                                        <button type=\"button\" class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: runReport\">\n                                                            <span class=\"fa fa-gears\" aria-hidden=\"true\"></span> Run\n                                                        </button>\n                                                        <button type=\"button\" class=\"btn btn-sm btn-outline-secondary dropdown-toggle dropdown-toggle-split\" data-bs-toggle=\"dropdown\" style=\"margin-left: -4px;\">\n                                                            <span class=\"sr-only\"></span>\n                                                        </button>\n                                                        <div class=\"dropdown-menu dropdown-menu-right\">\n                                                            <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: $parent.toggleFavorite, visible: !$root.selectMode()\">\n                                                                <span data-bind=\"css: isFavorite() ? 'fa fa-star text-warning' : 'fa fa-star-o'\"></span>\n                                                                <span data-bind=\"text: isFavorite() ? 'Remove from Favorites' : 'Add to Favorites'\"></span>\n                                                            </a>\n                                                            <div class=\"dropdown-divider\" data-bind=\"visible: !$root.selectMode()\"></div>\n                                                            <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { exportReport(ko.unwrap($root.appSettings.useAltPdf) ? 'pdfalt' : 'pdf');}\">\n                                                                <span class=\"fas fa-file-pdf\"></span> Download PDF\n                                                            </a>\n                                                            <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() {exportReport('excel');}\">\n                                                                <span class=\"fas fa-file-excel\"></span> Download Excel\n                                                            </a>\n                                                            <a class=\"dropdown-item\" href=\"#\" data-bind=\"visible: hasDrilldown, click: function() {exportReport('excel-sub');}\">\n                                                                <span class=\"fas fa-file-excel\"></span> Download Excel (Expanded)\n                                                            </a>\n                                                            <div class=\"dropdown-divider\" data-bind=\"visible: !isSubReportOnly()\"></div>\n                                                            <a class=\"dropdown-item\" href=\"#\" data-bs-toggle=\"modal\" data-bs-target=\"#modal-schedule-report\" data-bind=\"visible: !isSubReportOnly(), click: function() { $parent.openScheduleModal($data); }\">\n                                                                <span class=\"fa fa-hourglass\"></span> Schedule Report\n                                                            </a>\n                                                        </div>\n                                                    </div>\n                                                    <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: deleteReport, visible: canDelete\">\n                                                        <span class=\"fa fa-trash\" aria-hidden=\"true\"></span> Delete\n                                                    </button>\n                                                    <br />\n                                                </div>\n\n                                                <div class=\"d-block d-md-none\">\n                                                    <button class=\"btn btn-sm btn-outline-secondary\" title=\"Edit\" data-bind=\"visible: canEdit, click: openReport\" data-bs-toggle=\"modal\" data-bs-target=\"#modal-reportbuilder\">\n                                                        <span class=\"fa fa-edit\" aria-hidden=\"true\"></span>\n                                                    </button>\n                                                    <button class=\"btn btn-sm btn-light\" data-bind=\"click: copyReport, visible: (canEdit || $parent.appSettings.canCopyReport) && ($root.CanSaveReports() || $root.adminMode())\" title=\"Copy Report\" data-bs-toggle=\"modal\" data-bs-target=\"#modal-reportbuilder\">\n                                                        <span class=\"fa fa-copy\" aria-hidden=\"true\"></span>\n                                                    </button>\n\n                                                    <div class=\"btn-group\">\n                                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: runReport\" title=\"Run Report\">\n                                                            <span class=\"fa fa-gears\" aria-hidden=\"true\"></span>\n                                                        </button>\n                                                        <button type=\"button\" class=\"btn btn-sm btn-outline-secondary dropdown-toggle dropdown-toggle-split\" data-bs-toggle=\"dropdown\" style=\"margin-left: -4px;\">\n                                                            <span class=\"sr-only\"></span>\n                                                        </button>\n                                                        <div class=\"dropdown-menu\">\n                                                            <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: $parent.toggleFavorite, visible: !$root.selectMode()\">\n                                                                <span data-bind=\"css: isFavorite() ? 'fa fa-star text-warning' : 'fa fa-star-o'\"></span>\n                                                                <span data-bind=\"text: isFavorite() ? 'Remove from Favorites' : 'Add to Favorites'\"></span>\n                                                            </a>\n                                                            <div class=\"dropdown-divider\" data-bind=\"visible: !$root.selectMode()\"></div>\n                                                            <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() {exportReport('excel');}\">\n                                                                <span class=\"fas fa-file-excel\"></span> Download Excel\n                                                            </a>\n                                                            <a class=\"dropdown-item\" href=\"#\" data-bind=\"visible: hasDrilldown, click: function() {exportReport('excel-sub');}\">\n                                                                <span class=\"fas fa-file-excel\"></span> Download Excel with inner rows\n                                                            </a>\n                                                            <div class=\"dropdown-divider\" data-bind=\"visible: !isSubReportOnly()\"></div>\n                                                            <a class=\"dropdown-item\" href=\"#\" data-bs-toggle=\"modal\" data-bs-target=\"#modal-schedule-report\" data-bind=\"visible: !isSubReportOnly(), click: function() { $parent.openScheduleModal($data); }\">\n                                                                <span class=\"fa fa-hourglass\"></span> Schedule Report\n                                                            </a>\n                                                        </div>\n                                                    </div>\n\n                                                    <button class=\"btn btn-sm btn-outline-secondary\" title=\"Delete Report\" data-bind=\"click: deleteReport, visible: canDelete\">\n                                                        <span class=\"fa fa-trash\" aria-hidden=\"true\"></span>\n                                                    </button>\n                                                </div>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                    <div data-bind=\"if: layout()=='list'\">\n                        <div class=\"file-explorer-container\">\n\n                            <!-- BREADCRUMB -->\n                            <nav aria-label=\"breadcrumb\">\n                                <ol class=\"breadcrumb\" data-bind=\"foreach: breadcrumbItems\">\n                                    <li class=\"breadcrumb-item\" data-bind=\"css: { 'active': isActive }\">\n                                        <a href=\"#\" data-bind=\"text: FolderName, click: onClick, visible: !isActive\"></a>\n                                        <span data-bind=\"text: FolderName, visible: isActive\"></span>\n                                    </li>\n                                </ol>\n                            </nav>\n\n                            <div data-bind=\"visible: !SelectedFolder() && !searchReports()\">\n                                <div class=\"container-fluid\">\n                                    <div class=\"row fw-bold border-bottom py-2 w-100\">\n                                        <div class=\"col-md-3\">Name</div>\n                                        <div class=\"col-md-1\"></div>\n                                        <div class=\"col-md-8\" data-bind=\"visible: adminMode\">Access</div>\n                                    </div>\n                                    <div class=\"\" data-bind=\"foreach: rootFolders\">\n                                        <div class=\"row py-2 border-bottom align-items-center w-100 row-hover\">\n                                            <div class=\"col-md-3 d-flex align-items-center clickable\" data-bind=\"click: function(){ $parent.SelectedFolder($data); }\">\n                                                <span data-bind=\"visible: $root.selectMode, click: function(d,e){ isSelected(!isSelected()); e.stopPropagation(); },\n                                                css: isSelected() ? 'fa fa-check-square text-primary me-2' : 'fa fa-square-o me-2'\"></span>\n                                                <span class=\"fa fa-folder text-secondary me-2\"></span>\n                                                <span data-bind=\"text: FolderName\"></span>\n                                            </div>\n                                            <div class=\"col-md-1\" onclick=\"event.stopPropagation()\">\n                                                <div class=\"dropdown hover-ellipsis\" data-bind=\"visible: ($root.CanManageFolders() || $root.adminMode()) && (canEdit || canDelete || $root.adminMode())\">\n                                                    <button class=\"btn btn-sm\" type=\"button\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">\n                                                        <span class=\"fa fa-ellipsis-h\"></span>\n                                                    </button>\n                                                    <ul class=\"dropdown-menu\">\n                                                        <li>\n                                                            <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function(){ $parent.SelectedFolder($data); $parent.ManageFolder.editFolder(); }, visible: canEdit || $root.adminMode()\">\n                                                                <span class=\"fa fa-edit\"></span> Edit Folder\n                                                            </a>\n                                                        </li>\n                                                        <li>\n                                                            <a class=\"dropdown-item text-danger\" href=\"#\" data-bind=\"click: function(){ $parent.SelectedFolder($data); $parent.ManageFolder.deleteFolder(); }, visible: canDelete || $root.adminMode()\">\n                                                                <span class=\"fa fa-trash\"></span> Delete Folder\n                                                            </a>\n                                                        </li>\n                                                        <li>\n                                                            <a class=\"dropdown-item\" href=\"#\"\n                                                               data-bind=\"click: function(){ $parent.ManageFolder.addSubFolder($data); },\n                                                                visible: canEdit || $root.adminMode()\">\n                                                                <span class=\"fa fa-folder\"></span> Add Sub Folder\n                                                            </a>\n                                                        </li>\n                                                        <li data-bind=\"visible: $root.adminMode() && Id\">\n                                                            <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function(){ $root.openFolderAccessModal($data); }\">\n                                                                <span class=\"fa fa-key\"></span> Manage Access\n                                                            </a>\n                                                        </li>\n                                                    </ul>\n                                                </div>\n                                            </div>\n                                            <div class=\"col-md-8\" data-bind=\"visible: $parent.adminMode\">\n                                                <div class=\"d-flex flex-wrap gap-1 align-items-center\">\n                                                    <div data-bind=\"template: { name: 'access-badges', data: $data }\"></div>\n                                                </div>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div data-bind=\"visible: SelectedFolder() || searchReports()\">\n                                <div class=\"container-fluid\">\n\n                                    <!-- Empty states -->\n                                    <div data-bind=\"if: SelectedFolder() != null\n                                        && reportsInFolder().length == 0\n                                        && subFoldersInFolder().length == 0\n                                        && !searchReports()\">\n                                        <p class=\"text-muted\">This folder is empty.</p>\n                                    </div>\n\n                                    <div data-bind=\"if: searchReports() && reportsInSearch().length==0 && foldersInSearch().length==0\">\n                                        <p class=\"text-center text-muted\">No results found matching your search.</p>\n                                    </div>\n                                    <!-- Folder search results (list view) -->\n                                    <div data-bind=\"if: searchReports() && foldersInSearch().length > 0\">\n                                        <div class=\"row fw-bold py-1 border-bottom mt-2 w-100\">\n                                            <div class=\"col-md-3\"><span class=\"fa fa-folder\"></span> Matching Folders</div>\n                                            <div class=\"col-md-1\"></div>\n                                            <div class=\"col-md-8\" data-bind=\"visible: $root.adminMode\">Access</div>\n                                        </div>\n                                        <div data-bind=\"foreach: foldersInSearch\">\n                                            <div class=\"row border-bottom py-2 align-items-center w-100\">\n                                                <div class=\"col-md-3 d-flex align-items-center\">\n                                                    <span class=\"fa fa-folder text-secondary me-2\"></span>\n                                                    <a href=\"#\" data-bind=\"click: function(){ $parent.SelectedFolder($data); $parent.searchReports(''); }, highlightedText: { text: FolderName, highlight: $parent.searchReports, css: 'highlight' }\" style=\"cursor: pointer\"></a>\n                                                </div>\n                                                <div class=\"col-md-1\" onclick=\"event.stopPropagation()\">\n                                                    <div class=\"dropdown hover-ellipsis\" data-bind=\"visible: ($root.CanManageFolders() || $root.adminMode()) && (canEdit || canDelete || $root.adminMode())\">\n                                                        <button class=\"btn btn-sm\" type=\"button\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">\n                                                            <span class=\"fa fa-ellipsis-h\"></span>\n                                                        </button>\n                                                        <ul class=\"dropdown-menu\">\n                                                            <li>\n                                                                <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function(){ $parent.SelectedFolder($data); $parent.ManageFolder.editFolder(); }, visible: canEdit || $root.adminMode()\">\n                                                                    <span class=\"fa fa-edit\"></span> Edit Folder\n                                                                </a>\n                                                            </li>\n                                                            <li>\n                                                                <a class=\"dropdown-item text-danger\" href=\"#\" data-bind=\"click: function(){ $parent.SelectedFolder($data); $parent.ManageFolder.deleteFolder(); }, visible: canDelete || $root.adminMode()\">\n                                                                    <span class=\"fa fa-trash\"></span> Delete Folder\n                                                                </a>\n                                                            </li>\n                                                            <li>\n                                                                <a class=\"dropdown-item\" href=\"#\"\n                                                                   data-bind=\"click: function(){ $parent.ManageFolder.addSubFolder($data); },\n                                                                    visible: canEdit || $root.adminMode()\">\n                                                                    <span class=\"fa fa-folder\"></span> Add Sub Folder\n                                                                </a>\n                                                            </li>\n                                                            <li data-bind=\"visible: $root.adminMode() && Id\">\n                                                                <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function(){ $root.openFolderAccessModal($data); }\">\n                                                                    <span class=\"fa fa-key\"></span> Manage Access\n                                                                </a>\n                                                            </li>\n                                                        </ul>\n                                                    </div>\n                                                </div>\n                                                <div class=\"col-md-8\" data-bind=\"visible: $root.adminMode\">\n                                                    <div class=\"small text-muted d-flex flex-wrap gap-1 align-items-center\">\n                                                        <div data-bind=\"template: { name: 'access-badges', data: $data }\"></div>\n                                                    </div>\n                                                </div>\n                                            </div>\n                                        </div>\n                                        <div class=\"mb-2\"></div>\n                                    </div>\n\n                                    <!-- FOLDERS + REPORTS (one unified list, folders first like a file explorer) -->\n                                    <div data-bind=\"if: (!searchReports() && subFoldersInFolder().length > 0) || reportsInFolder().length > 0 || reportsInSearch().length > 0\">\n                                        <div class=\"row fw-bold border-bottom py-2 w-100\">\n                                            <div class=\"col-md-3\">Name</div>\n                                            <div class=\"col-md-1\"></div>\n                                            <div class=\"col-md-2\">Modified</div>\n                                            <div class=\"col-md-2\">Modified By</div>\n                                            <div class=\"col-md-2\" data-bind=\"visible: searchReports()\">Folder</div>\n                                            <div class=\"col-md-2\" data-bind=\"visible: adminMode\">Access</div>\n                                            <div class=\"col-md-1\" data-bind=\"visible: adminMode\">Direct Link</div>\n                                        </div>\n\n                                        <!-- Sub folder rows (same column grid as report rows) -->\n                                        <div data-bind=\"foreach: !searchReports() ? subFoldersInFolder() : []\">\n                                            <div class=\"row border-bottom py-2 align-items-center w-100 row-hover\">\n                                                <div class=\"col-md-3 d-flex align-items-center clickable\"\n                                                     data-bind=\"click: function(){ $root.SelectedFolder($data); }\">\n                                                    <span class=\"fa fa-folder text-secondary me-2\"></span>\n                                                    <span data-bind=\"text: FolderName\"></span>\n                                                </div>\n                                                <div class=\"col-md-1\" onclick=\"event.stopPropagation()\">\n                                                    <div class=\"dropdown hover-ellipsis\"\n                                                         data-bind=\"visible: ($root.CanManageFolders() || $root.adminMode()) && (canEdit || canDelete || $root.adminMode())\">\n                                                        <button class=\"btn btn-sm\" type=\"button\"\n                                                                data-bs-toggle=\"dropdown\" aria-expanded=\"false\">\n                                                            <span class=\"fa fa-ellipsis-h\"></span>\n                                                        </button>\n                                                        <ul class=\"dropdown-menu\">\n                                                            <li>\n                                                                <a class=\"dropdown-item\" href=\"#\"\n                                                                   data-bind=\"click: function(){ $root.SelectedFolder($data); $root.ManageFolder.editFolder(); },\n                                                                    visible: canEdit || $root.adminMode()\">\n                                                                    <span class=\"fa fa-edit\"></span> Edit Folder\n                                                                </a>\n                                                            </li>\n                                                            <li>\n                                                                <a class=\"dropdown-item text-danger\" href=\"#\"\n                                                                   data-bind=\"click: function(){ $root.SelectedFolder($data); $root.ManageFolder.deleteFolder(); },\n                                                                    visible: canDelete || $root.adminMode()\">\n                                                                    <span class=\"fa fa-trash\"></span> Delete Folder\n                                                                </a>\n                                                            </li>\n                                                            <li>\n                                                                <a class=\"dropdown-item\" href=\"#\"\n                                                                   data-bind=\"click: function(){ $root.ManageFolder.addSubFolder($data); },\n                                                                    visible: canEdit || $root.adminMode()\">\n                                                                    <span class=\"fa fa-folder\"></span> Add Sub Folder\n                                                                </a>\n                                                            </li>\n                                                            <li data-bind=\"visible: $root.adminMode() && Id\">\n                                                                <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function(){ $root.openFolderAccessModal($data); }\">\n                                                                    <span class=\"fa fa-key\"></span> Manage Access\n                                                                </a>\n                                                            </li>\n                                                        </ul>\n                                                    </div>\n                                                </div>\n                                                <div class=\"col-md-2\"></div>\n                                                <div class=\"col-md-2\"></div>\n                                                <div class=\"col-md-2\" data-bind=\"visible: $root.adminMode\">\n                                                    <div class=\"d-flex flex-wrap gap-1 align-items-center\">\n                                                        <div data-bind=\"template: { name: 'access-badges', data: $data }\"></div>\n                                                    </div>\n                                                </div>\n                                                <div class=\"col-md-1\" data-bind=\"visible: $root.adminMode\"></div>\n                                            </div>\n                                        </div>\n\n                                        <div class=\"report-list\" data-bind=\"foreach: searchReports() ? reportsInSearch() : reportsInFolder()\">\n                                            <div class=\"row border-bottom py-2 align-items-center w-100 row-hover\">\n                                                <div class=\"col-md-3 d-flex align-items-center\">\n                                                    <input type=\"checkbox\" data-bind=\"visible: $root.selectMode, checked: isSelected\" class=\"me-2\" />\n                                                    <span class=\"fa\" data-bind=\"css: {\n                                                    'fa-file': reportType=='List',\n                                                    'fa-th-list': reportType=='Summary',\n                                                    'fa-bar-chart': reportType=='Bar',\n                                                    'fa-pie-chart': reportType=='Pie',\n                                                    'fa-line-chart': reportType=='Line',\n                                                    'fa-signal': reportType=='Combo',\n                                                    'fa-globe': reportType.indexOf('Map')==0,\n                                                    'fa-window-maximize': reportType=='Single',\n                                                    'fa-random': reportType=='Pivot',\n                                                    'fa-window-restore': reportType=='Treemap',\n                                                    'fa-code': reportType == 'Html',\n                                                    'fa-map': reportType == 'HeatMap'\n                                                    }\"></span>\n                                                    <a class=\"ms-2\" data-bind=\"click: runReport, highlightedText: { text: reportName, highlight: $parent.searchReports, css: 'highlight' }\" style=\"cursor: pointer\"></a>&nbsp;\n                                                    <span data-bind=\"text: message\" class=\"highlight small\"></span>\n                                                    <span class=\"row-hover-actions ms-2\" data-bind=\"css: { 'favorited': isFavorite() }, visible: !$root.selectMode()\">\n                                                        <a href=\"#\" data-bind=\"click: $parent.toggleFavorite, attr: { title: isFavorite() ? 'Remove from Favorites' : 'Add to Favorites' }\">\n                                                            <i data-bind=\"css: isFavorite() ? 'fa fa-star text-warning' : 'fa fa-star-o'\"></i>\n                                                        </a>\n                                                    </span>\n                                                    <span class=\"badge bg-warning text-dark ms-1\"\n                                                          title=\"This report is only used as a linked or sub report\"\n                                                          data-bind=\"visible: isSubReportOnly && isSubReportOnly()\">\n                                                        <i class=\"fa fa-link\"></i> Sub Report Only\n                                                    </span>\n                                                </div>\n\n                                                <div class=\"col-md-1\">\n                                                    <div class=\"dropdown hover-ellipsis\">\n                                                        <button class=\"btn btn-sm\" type=\"button\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">\n                                                            <span class=\"fa fa-ellipsis-h\"></span>\n                                                        </button>\n                                                        <ul class=\"dropdown-menu\">\n                                                            <li data-bind=\"visible: canEdit\">\n                                                                <a class=\"dropdown-item\" href=\"#\" data-bs-toggle=\"modal\" data-bs-target=\"#modal-reportbuilder\" data-bind=\"click: openReport\">\n                                                                    <span class=\"fa fa-edit\"></span> Edit\n                                                                </a>\n                                                            </li>\n                                                            <li>\n                                                                <a class=\"dropdown-item\" href=\"#\" data-bs-toggle=\"modal\" data-bs-target=\"#modal-reportbuilder\" data-bind=\"click: copyReport, visible:canEdit || $parent.appSettings.canCopyReport\">\n                                                                    <span class=\"fa fa-copy\"></span> Copy\n                                                                </a>\n                                                            </li>\n                                                            <li>\n                                                                <a class=\"dropdown-item text-danger\" href=\"#\" data-bind=\"click: deleteReport, visible: canDelete\">\n                                                                    <span class=\"fa fa-trash\"></span> Delete\n                                                                </a>\n                                                            </li>\n                                                            <li><hr class=\"dropdown-divider\"></li>\n                                                            <li>\n                                                                <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: runReport\">\n                                                                    <span class=\"fa fa-gears\"></span> Run Report\n                                                                </a>\n                                                            </li>\n                                                            <li class=\"dropdown-submenu\">\n                                                                <a class=\"dropdown-item dropdown-toggle\" href=\"#\"><span class=\"fa fa-download\"></span> Export</a>\n                                                                <ul class=\"dropdown-menu\">\n                                                                    <li>\n                                                                        <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() {exportReport(ko.unwrap($root.appSettings.useAltPdf) ? 'pdfalt' : 'pdf');}\">\n                                                                            <span class=\"fa fa-file-pdf-o\"></span> Download PDF\n                                                                        </a>\n                                                                    </li>\n                                                                    <li>\n                                                                        <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() {exportReport('excel');}\">\n                                                                            <span class=\"fa fa-file-excel-o\"></span> Download Excel\n                                                                        </a>\n                                                                    </li>\n                                                                    <li>\n                                                                        <a class=\"dropdown-item\" href=\"#\" data-bind=\"visible: hasDrilldown, click: function() {exportReport('excel-sub');}\">\n                                                                            <span class=\"fa fa-file-excel-o\"></span> Download Excel (Expanded)\n                                                                        </a>\n                                                                    </li>\n                                                                </ul>\n                                                            </li>\n                                                            <li data-bind=\"visible: !$root.selectMode() || !isSubReportOnly()\"><hr class=\"dropdown-divider\"></li>\n                                                            <li data-bind=\"visible: !$root.selectMode()\">\n                                                                <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: $parent.toggleFavorite\">\n                                                                    <span data-bind=\"css: isFavorite() ? 'fa fa-star text-warning' : 'fa fa-star-o'\"></span>\n                                                                    <span data-bind=\"text: isFavorite() ? 'Remove from Favorites' : 'Add to Favorites'\"></span>\n                                                                </a>\n                                                            </li>\n                                                            <li data-bind=\"visible: !isSubReportOnly()\">\n                                                                <a class=\"dropdown-item\" href=\"#\" data-bs-toggle=\"modal\" data-bs-target=\"#modal-schedule-report\" data-bind=\"click: function() { $parent.openScheduleModal($data); }\">\n                                                                    <span class=\"fa fa-hourglass\"></span> Schedule Report\n                                                                </a>\n                                                            </li>\n                                                            <li data-bind=\"visible: $root.adminMode\">\n                                                                <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { $root.openAccessModal($data); }\">\n                                                                    <span class=\"fa fa-key\"></span> Manage Access\n                                                                </a>\n                                                            </li>\n                                                        </ul>\n                                                    </div>\n                                                </div>\n\n                                                <div class=\"col-md-2 small text-muted\" data-bind=\"text: dateLastUpdated\"></div>\n                                                <div class=\"col-md-2 small text-muted text-truncate\" data-bind=\"text: modifiedBy || '', attr: { title: modifiedBy || '' }\"></div>\n                                                <div class=\"col-md-2\" data-bind=\"text: folderName, visible: $parent.searchReports()\"></div>\n                                                <div class=\"col-md-2\" data-bind=\"visible: $parent.adminMode\">\n                                                    <div class=\"d-flex flex-wrap gap-1 align-items-center mt-1\">\n                                                        <div data-bind=\"template: { name: 'access-badges', data: $data }\"></div>\n                                                    </div>\n                                                </div>\n                                                <div class=\"col-md-1\" data-bind=\"visible: $parent.adminMode\">\n                                                    <a data-bind=\"attr: {href: '/DotNetReport?linkedreport=true&noparent=true&reportId=' + reportId }\" target=\"_blank\"><span class=\"fa fa-link\"></span></a>\n                                                    &nbsp;\n                                                    <a href=\"#\" data-bind=\"click: function() { navigator && navigator.clipboard && navigator.clipboard.writeText('/DotNetReport?linkedreport=true&noparent=true&reportId=' + reportId) }\">\n                                                        <span class=\"fa fa-copy\" title=\"Copy Link\"></span>\n                                                    </a>\n                                                </div>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n   \n\n    <div data-bind=\"visible: (ReportMode() == 'execute' || ReportMode() == 'linked' || ReportMode() == 'design') && !isModalOpen()\">\n        <div class=\"card\" data-bind=\"visible: true;\" style=\"display: none;\">\n            <div class=\"card-header\">\n                <nav class=\"navbar navbar-expand-lg navbar-light bg-light\">\n                    <a class=\"navbar-brand\" href=\"#\">Viewing Report</a>\n                    <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#navbarSupportedContent\" aria-controls=\"navbarSupportedContent\" aria-expanded=\"false\" aria-label=\"Toggle navigation\">\n                        <span class=\"navbar-toggler-icon\"></span>\n                    </button>\n                    <div class=\"collapse navbar-collapse\" id=\"navbarSupportedContent\">\n                        <ul class=\"navbar-nav me-auto\"></ul>\n                        <div class=\"d-flex align-items-center gap-2\">\n                            <button class=\"btn btn-light btn-sm\" data-bind=\"click: function() {$root.ReportMode('start'); $root.textQuery.setupSearch();}\">\n                                <i class=\"fa fa-arrow-left\"></i>\n                                <span>Back to Reports</span>\n                            </button>\n                            <button class=\"btn btn-light btn-sm\" data-bind=\"visible: canGoBackToParent(), click: backToParentReport\">\n                                <i class=\"fa fa-arrow-circle-left\"></i>\n                                <span>Back to Parent Report</span>\n                            </button>\n                            <button class=\"btn btn-light btn-sm\" data-bind=\"visible: $root.CanEdit() && ReportID(), click: function(){ SaveReport(true); }\" data-bs-toggle=\"modal\" data-bs-target=\"#modal-reportbuilder\">\n                                <i class=\"fa fa-edit\"></i> Edit Report\n                            </button>\n\n                            <button class=\"btn btn-light btn-sm\" data-bind=\"click: RefreshReport, visible: false\">\n                                <i class=\"fa fa-refresh\"></i>\n                                <span>Refresh</span>\n                            </button>                            \n                            <span data-bind=\"visible: isDirty\" title=\"You have unsaved changes\">\n                                <i class=\"text-warning fa fa-exclamation-triangle\"></i>\n                            </span>\n                            <button class=\"btn btn-light btn-sm\" data-bind=\"visible: $root.CanEdit(), click: SaveWithoutRun\">\n                                <i class=\"fa fa-save\"></i>                                                                \n                                <span>Save Report</span>\n                            </button>\n                            <div class=\"dropdown\" data-bind=\"hidden: (DontExecuteOnRun() && !reportRan()) || !ReportID()\">\n                                <button type=\"button\" class=\"btn btn-light btn-sm dropdown-toggle\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">\n                                    <i class=\"fa fa-download\"></i>\n                                    <span>Export</span>\n                                </button>\n                                <ul class=\"dropdown-menu dropdown-menu-end\">                                    \n                                    <li data-bind=\"hidden: appSettings.useAltPdf\">\n                                        <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: appSettings.showPageSize\n                                              ? function() { PdfPage.isDebug = false; $('#pdfOptionsModal').modal('show'); }\n                                              : function() { downloadPdf(false); }\">\n                                            <i class=\"fa fa-file-pdf\"></i> Pdf\n                                        </a>\n                                    </li>\n                                    <li data-bind=\"visible: adminMode() && !appSettings.useAltPdf()\">\n                                        <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: appSettings.showPageSize\n                                              ? function() { PdfPage.isDebug = true; $('#pdfOptionsModal').modal('show'); }\n                                              : function() { downloadPdf(true); }\">\n                                            <i class=\"fa fa-file-pdf\"></i> Pdf (Debug)\n                                        </a>\n                                    </li>\n                                    <!-- Alt PDF, drilldown available (non-pivot, non-kpi) -> submenu -->\n                                    <li class=\"dropdown-submenu dropdown-submenu-left\" data-bind=\"visible: ko.unwrap(appSettings.useAltPdf) && canDrilldown() && !hasPivotColumn() && ReportType() != 'Single'\">\n                                        <a class=\"dropdown-item dropdown-toggle\" href=\"#\"><i class=\"fa fa-file-pdf-o\"></i> Pdf</a>\n                                        <ul class=\"dropdown-menu\">\n                                            <li>\n                                                <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: appSettings.showPageSize\n                                                      ? function() { PdfPage.isExpanded = false; $('#pdfOptionsModal').modal('show'); }\n                                                      : function() { downloadPdfAlt(); }\">Standard</a>\n                                            </li>\n                                            <li>\n                                                <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: appSettings.showPageSize\n                                                      ? function() { PdfPage.isExpanded = true; $('#pdfOptionsModal').modal('show'); }\n                                                      : function() { downloadPdfAltWithDrilldown('',''); }\">Expanded</a>\n                                            </li>\n                                        </ul>\n                                    </li>\n                                    <!-- Alt PDF, no drilldown / pivot / kpi -> flat (no expand) -->\n                                    <li data-bind=\"visible: ko.unwrap(appSettings.useAltPdf) && (!canDrilldown() || hasPivotColumn() || ReportType() == 'Single')\">\n                                        <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: appSettings.showPageSize\n                                              ? function() { PdfPage.isExpanded = false; $('#pdfOptionsModal').modal('show'); }\n                                              : function() { downloadPdfAlt(); }\">\n                                            <i class=\"fa fa-file-pdf\"></i> Pdf\n                                        </a>\n                                    </li>\n                                    <!-- Excel, drilldown available -> submenu -->\n                                    <li class=\"dropdown-submenu dropdown-submenu-left\" data-bind=\"visible: canDrilldown()\">\n                                        <a class=\"dropdown-item dropdown-toggle\" href=\"#\"><i class=\"fa fa-file-excel-o\"></i> Excel</a>\n                                        <ul class=\"dropdown-menu\">\n                                            <li><a href=\"#\" class=\"dropdown-item\" data-bind=\"click: downloadExcel\">Standard</a></li>\n                                            <li><a href=\"#\" class=\"dropdown-item\" data-bind=\"click: downloadExcelWithDrilldown\">Expanded</a></li>\n                                            <li data-bind=\"visible: hasSubReports()\"><a href=\"#\" class=\"dropdown-item\" data-bind=\"click: downloadExcelWithSubreport\">Excel with Subreport</a></li>\n                                        </ul>\n                                    </li>\n                                    <!-- Excel, no drilldown -> flat -->\n                                    <li data-bind=\"visible: !canDrilldown()\">\n                                        <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: downloadExcel\">\n                                            <i class=\"fas fa-file-excel\"></i> Excel\n                                        </a>\n                                    </li>\n                                    <li data-bind=\"visible:!canDrilldown() && hasSubReports()\">\n                                        <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: downloadExcelWithSubreport\">\n                                            <i class=\"fas fa-file-excel\"></i> Excel with Subreport\n                                        </a>\n                                    </li>\n                                    <li data-bind=\"hidden: appSettings.dontWordExport\">\n                                        <a class=\"dropdown-item\" data-bind=\"click: appSettings.showPageSize\n                                            ? function() { $('#wordOptionsModal').modal('show'); }\n                                            : function() { downloadWord(); }\">\n                                            <span class=\"fas fa-file-word\"></span> Word\n                                        </a>\n                                    </li>\n                                    <li>\n                                        <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: downloadCsv\">\n                                            <i class=\"fas fa-file-excel\"></i> Csv\n                                        </a>\n                                    </li>\n                                    <li data-bind=\"hidden: appSettings.dontXmlExport\">\n                                        <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: downloadXml\">\n                                            <i class=\"fa fa-file-code\"></i> Xml\n                                        </a>\n                                    </li>\n                                    <li>\n                                        <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: printReportPage\">\n                                            <i class=\"fas fa-print\"></i> Print\n                                        </a>\n                                    </li>\n                                </ul>\n                            </div>\n                        </div>\n                    </div>\n                </nav>\n            </div>\n            <div class=\"card-body\">\n                <div data-bind=\"with: ReportResult\" class=\"report-view\">\n                    <div data-bind=\"ifnot: HasError\">\n                        <div data-bind=\"with: $root\">\n                            <div>\n                                <div data-bind=\"if: EditFiltersOnReport\">\n                                    <div class=\"card\">\n                                        <div class=\"card-header\">\n                                            <a data-bs-toggle=\"collapse\" data-bs-target=\"#filter-panel\" href=\"#\">\n                                                <i class=\"fa fa-filter\"></i>Choose Filters\n                                            </a>\n                                        </div>\n                                        <div id=\"filter-panel\" class=\"card-body collapse\">\n                                            <div data-bind=\"if: useStoredProc\">\n                                                <div class=\"row\">\n                                                    <div data-bind=\"template: {name: 'filter-parameters'}\" class=\"col-md-12\"></div>\n                                                </div>\n                                            </div>\n                                            <div data-bind=\"ifnot: useStoredProc\">\n                                                <div class=\"row\">\n                                                    <div data-bind=\"template: {name: 'filter-group'}\" class=\"col-md-12\"></div>\n                                                </div>\n                                            </div>\n                                            <br />\n                                            <button class=\"btn btn-primary\" data-bind=\"click: SaveFilterAndRunReport\">Update Filters</button>\n                                        </div>\n                                    </div>\n                                    <br />\n                                </div>\n                                <div data-bind=\"ifnot: EditFiltersOnReport\">\n                                    <div data-bind=\"template: {name: 'fly-filter-template'}\"></div>\n                                    <br />\n                                </div>\n                            </div>\n                            <div class=\"report-render\" data-bind=\"css: { 'report-expanded': isExpanded }\">\n                                <div class=\"report-menubar bg-light\" data-bind=\"hidden: DontExecuteOnRun() && !reportRan()\">\n                                    <div class=\"col-xs-12 col-centered d-flex justify-content-between flex-wrap\" data-bind=\"with: pager\">\n                                        <div class=\"form-inline d-flex\" data-bind=\"visible: pages()\">\n                                            <div class=\"form-group pull-left total-records\">\n                                                <span data-bind=\"text: ' Total Records: ' + totalRecords()\"></span><br />\n                                            </div>\n                                            <div class=\"float-start\">\n                                                <button class=\"btn btn-secondary btn-sm\" data-bind=\"visible: !$root.isChart() || $root.ShowDataWithGraph(), click: $root.downloadExcel\" title=\"Export to Excel\">\n                                                    <span class=\"fas fa-file-excel\"></span>\n                                                </button>\n                                                <button class=\"btn btn-secondary btn-sm\" data-bind=\"click: $parent.toggleExpand\">\n                                                    <span class=\"fa\" data-bind=\"css: {'fa-expand': !$parent.isExpanded(), 'fa-compress': $parent.isExpanded() }\"></span>\n                                                </button>\n                                                <button class=\"btn btn-secondary btn-sm\" data-bind=\"visible: $parent.canDrilldown, click: $parent.ExpandAll\" title=\"Expand all rows\">\n                                                    <span class=\"fa fa-plus\"></span>\n                                                </button>\n                                                <button class=\"btn btn-secondary btn-sm\" data-bind=\"visible: $parent.canDrilldown, click: $parent.CollapseAll\" title=\"Collapse all rows\">\n                                                    <span class=\"fa fa-minus\"></span>\n                                                </button>\n                                                <button class=\"btn btn-secondary btn-sm\" title=\"Re-run Report\" data-bind=\"click: function() { $root.RunReport(false, true);}\">\n                                                    <i class=\"fa fa-play\"></i> \n                                                </button>\n                                                <div data-bind=\"with: $parent\" class=\"float-start\">\n                                                    <div class=\"dropdown-selected\" data-bind=\"click: toggleDropdown\">\n                                                        <div data-bind=\"with: selectedTableStyle\" class=\"btn btn-sm btn-secondary\" title=\"Format Table\">\n                                                            <span class=\"fa fa- fa-paint-brush\"></span>\n                                                        </div>\n                                                    </div>\n                                                    <div class=\"dropdown-content\" style=\"position: absolute;\" data-bind=\"visible: dropdownOpen\">\n                                                        <div data-bind=\"foreach: tableStyles\">\n                                                            <div class=\"dropdown-option\" data-bind=\"title: $data.name, click: $parent.selectStyle\">\n                                                                <div class=\"mini-table-preview\" data-bind=\"foreach: new Array(5)\">\n                                                                    <div class=\"mini-table-row\" data-bind=\"foreach: new Array(5)\">\n                                                                        <div class=\"mini-table-cell\" data-bind=\"style: { backgroundColor: $parentContext.$index() === 0 ? $parents[1].headerBg : ($parentContext.$index() % 2 === 0 ? $parents[1].altRowBg : $parents[1].rowBg), color: $parents[1].textColor }\"></div>\n\n                                                                    </div>\n                                                                </div>\n                                                            </div>\n                                                        </div>\n                                                    </div>\n                                                </div>\n                                            </div>\n                                        </div>\n                                        <div class=\"d-flex\">\n                                            <div class=\"btn-group btn-group-sm d-flex\" role=\"group\">\n                                                <button class=\"btn btn-light\" data-bs-toggle=\"modal\" data-bs-target=\"#sqlModal\" data-bind=\"visible: $parent.adminMode\">\n                                                    <i class=\"fa fa-code\"></i> View Report Code\n                                                </button>\n                                                <button class=\"btn btn-light\" data-bind=\"click: $parent.zoomOut\" data-bs-toggle=\"tooltip\" title=\"Zoom Out\">\n                                                    <i class=\"fa fa-search-minus\"></i>\n                                                </button>\n                                                <button class=\"btn btn-light\" data-bind=\"click: $parent.resetZoom\" data-bs-toggle=\"tooltip\" title=\"Reset Zoom\">\n                                                    <i class=\"fa fa-compress\"></i>\n                                                </button>\n                                                <button class=\"btn btn-light\" data-bind=\"click: $parent.zoomIn\" data-bs-toggle=\"tooltip\" title=\"Zoom In\">\n                                                    <i class=\"fa fa-search-plus\"></i>\n                                                </button>\n                                            </div>\n                                            <div class=\"form-inline d-flex\">\n                                                <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class=\"report-canvas\" data-bind=\"hidden: DontExecuteOnRun() && !reportRan()\">\n                                    <div class=\"report-container bg-light\">\n                                           <div class=\"report-inner\" data-bind=\"style: { backgroundColor: tableSettings().backColor || (ReportResult() && ReportResult().ReportData() && ReportResult().ReportData().BackColor ? ReportResult().ReportData().BackColor() : '#fff') }\">\n                                            <div data-bind=\"if: $root.CanEdit() && ReportType()!='Html' && ReportType()!='Single'\">\n                                                <div data-bind=\"template: 'chart-settings', data: $data\"></div>\n                                            </div>\n                                            <div data-bind=\"if: $root.CanEdit() && ReportType()=='Single'\">\n                                                <div data-bind=\"template: 'kpi-settings', data: $data\"></div>\n                                            </div>\n                                            <div data-bind=\"visible: headerDesigner.UseReportHeader\">\n                                                <div id=\"report-header\" width=\"900\" height=\"120\" data-bind=\"html: $root.substituteReportPlaceholders($root.headerDesigner.headerHtml())\"></div>\n                                            </div>\n                                            <h2 data-bind=\"text: ReportName\"></h2>\n                                            <p data-bind=\"html: ReportDescription\">\n                                            </p>\n                                            <div data-bind=\"template: 'filter-details-summary'\"></div>\n\n                                            <div data-bind=\"with: ReportResult\" class=\"report-expanded-scroll\">\n                                                <div data-bind=\"visible: !ReportData()\">\n                                                    <div class=\"report-spinner\"></div>\n                                                </div>\n                                                <div data-bind=\"template: 'report-template', data: $data\"></div>\n                                            </div>\n                                            <div data-bind=\"visible: footerDesigner.UseReportFooter\">\n                                                <div id=\"report-footer\" width=\"900\" data-bind=\"html: $root.substituteReportPlaceholders($root.footerDesigner.footerHtml())\"></div>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <br />\n                            <span>Report ran on: <span data-bind=\"text: new Date().toLocaleDateString() + ' ' + new Date().toLocaleTimeString()\"></span></span>\n                        </div>\n                    </div>\n                    <div data-bind=\"if: HasError\">\n                        <h2 data-bind=\"text: $root.ReportName\"></h2>\n                        <p data-bind=\"text: $root.ReportDescription\"></p>\n\n                        <h3>An unexpected error occured while running the Report</h3>\n                        <hr />\n                        <b>Error Details</b>\n                        <div data-bind=\"text: Exception\"></div>\n                        <br />\n                        <button class=\"btn btn-light\" data-bs-toggle=\"modal\" data-bs-target=\"#sqlModal\" data-bind=\"visible: $parent.adminMode\">\n                            <i class=\"fa fa-code\"></i> View Report Code\n                        </button>\n                        <button class=\"btn btn-light\" data-bind=\"click: function() { $root.RunReport(false, true);}\">\n                            <i class=\"fa fa-play\"></i> Re-run Report\n                        </button>\n                        <hr />\n                    </div>\n                </div>\n                </div><!-- /flex wrapper -->\n            </div>\n        </div>\n</div>\n\n<!-- Report Builder -->\n<div class=\"modal modal-fullscreen\" id=\"modal-reportbuilder\" role=\"dialog\" aria-labelledby=\"myModalLabel\" aria-hidden=\"true\" style=\"padding-right: 0px !important;\">\n    <div data-bind=\"template: {name: 'report-designer', data: $data}\"></div>\n</div>\n\n<!-- Field Options Modal -->\n<div class=\"modal\" id=\"fieldOptionsModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div data-bind=\"template: {name: 'report-field-options', data: $data}\"></div>\n</div>\n\n<!-- Link Edit Modal -->\n<div class=\"modal\" id=\"linkModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div data-bind=\"template: {name: 'report-link-edit', data: $data}\"></div>\n</div>\n\n<!-- Folder Edit Modal -->\n<div class=\"modal\" id=\"manage-access-modal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\" role=\"document\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\"><i class=\"fa fa-key\"></i> Manage Access <span class=\"text-muted ms-1\" data-bind=\"text: accessModalReport() ? accessModalReport().reportName : ''\"></span></h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <div data-bind=\"template: { name: 'manage-access-template', data: manageAccess }\"></div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: saveAccessModal\"><i class=\"fa fa-save\"></i> Save Access</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"folderModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog\" data-bind=\"css: {'modal-lg': adminMode}\">\n        <div class=\"modal-content\" data-bind=\"with: ManageFolder\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title  fs-5\">Manage Folder</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <div class=\"alert alert-info py-2 mb-3\"\n                     data-bind=\"visible: IsNew() && ParentFolderId()\">\n                    <span class=\"fa fa-folder me-1\"></span>\n                    Creating sub folder inside:\n                    <strong data-bind=\"text: ParentFolderName\"></strong>\n                </div>\n                <div class=\"alert alert-secondary py-2 mb-3\"\n                     data-bind=\"visible:!IsNew() &&ParentFolderId()\">\n                    <span class=\"fa fa-folder-open me-1\"></span>\n                    Sub folder of:\n                    <strong data-bind=\"text: ParentFolderName\"></strong>\n                </div>\n\n                <div class=\"form-group\">\n                    <label class=\"col-sm-4 col-md-4 control-label\">Folder Name</label>\n                    <div class=\"col-sm-8 col-md-8\">\n                        <input type=\"text\" class=\"form-control\" id=\"folderName\" required placeholder=\"Folder Name\" data-bind=\"value: FolderName\">\n                    </div>\n                </div>\n                <div data-bind=\"visible: $root.adminMode\" class=\"form-group\">\n                    <div class=\"form-check\">\n                        <input type=\"checkbox\" class=\"form-check-input\" id=\"showAdminOnly\" data-bind=\"checked: ShowAdminOnly\">\n                        <label class=\"form-check-label\" for=\"showAdminOnly\">\n                            Show Admin Only (Only visible when Admin Mode is ON)\n                        </label>\n                    </div>\n                </div>\n                <br />\n                <div data-bind=\"visible: $root.adminMode\" class=\"card card-body\">\n                    <div data-bind=\"template: {name: 'manage-access-template', data: $root.manageFolderAccess}\"></div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: saveFolder\">Save</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<!-- Import Json File Modal -->\n<div class=\"modal\" id=\"uploadFileModal\" tabindex=\"-1\" aria-labelledby=\"uploadFileModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog\">\n        <div class=\"modal-content\" data-bind=\"with: ManageJsonFile\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"uploadFileModalLabel\">Import previously Exported Reports</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n\n                <div class=\"alert alert-info small\">\n                    <strong>Instructions:</strong><br />\n                    • Select a <code>.json</code> file previously exported from Dotnet Report.<br />\n                    • The file may include multiple reports and their folders.<br />\n                    • Any missing folders will be created automatically.<br />\n                    • If a report with the same name already exists, you will be prompted to:\n                    <em>Skip</em>, <em>Overwrite</em>, or <em>Make a Copy</em>.<br />\n                    • Once uploaded, all imported reports will be available immediately.\n                </div>\n\n                <div id=\"dropzone\" class=\"dropzone\"\n                     data-bind=\"event: {click: triggerFileInput }\"\n                     style=\"border: 2px dashed #007bff; border-radius: 5px; padding: 30px; text-align: center; color: #007bff; cursor: pointer;\">\n                    Click here to select a JSON file\n                </div>\n\n                <input type=\"file\" id=\"fileInputJson\" accept=\".json\" style=\"display: none;\"\n                       data-bind=\"event: { change: handleFileSelect }\">\n\n                <div class=\"mt-3\" data-bind=\"visible: fileName\">\n                    <p><strong>Selected File:</strong> <span data-bind=\"text: fileName\"></span></p>\n                </div>\n\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Close</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: uploadFile\">Upload</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"wordOptionsModal\" tabindex=\"-1\" aria-labelledby=\"wordOptionsModalLabel\" aria-hidden=\"true\">\n    <div data-bind=\"template: { name: 'word-options-template', data: $data }\"></div>\n</div>\n<div class=\"modal\" id=\"pdfOptionsModal\" tabindex=\"-1\" aria-labelledby=\"pdfOptionsModalLabel\" aria-hidden=\"true\">\n    <div data-bind=\"template: { name: 'pdf-options-template', data: $data }\"></div>\n</div>\n\n<!-- This renders the template -->\n<div class=\"modal\" id=\"pdfOptionsScheduleModal\" tabindex=\"-1\" aria-labelledby=\"pdfOptionsScheduleModalLabel\" aria-hidden=\"true\">\n    <div data-bind=\"template: { name: 'pdf-options-schedule-template', data: $data }\"></div>\n</div>\n<!-- This renders the template -->\n<div class=\"modal\" id=\"wordOptionsScheduleModal\" tabindex=\"-1\" aria-labelledby=\"wordOptionsScheduleModalLabel\" aria-hidden=\"true\">\n    <div data-bind=\"template: { name: 'word-options-schedule-template', data: $data }\"></div>\n</div>\n\n<!-- Schedule Report Modal -->\n<div class=\"modal\" id=\"modal-schedule-report\" tabindex=\"-1\" aria-labelledby=\"scheduleReportModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\">\n        <div class=\"modal-content\" data-bind=\"with: scheduleReportModal\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"scheduleReportModalLabel\">\n                    <i class=\"fa fa-hourglass me-2\"></i> Schedule Report\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <h6 data-bind=\"text: reportName\" class=\"mb-3\"></h6>\n\n                <div class=\"text-center py-4\" data-bind=\"visible: loading\">\n                    <span class=\"fa fa-spinner fa-spin fa-2x text-secondary\"></span>\n                    <div class=\"text-muted small mt-2\">Loading schedules...</div>\n                </div>\n\n                <!-- all schedules for this report -->\n                <div data-bind=\"visible: viewMode() === 'list' && !loading()\">\n                    <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                        <strong>Schedules</strong>\n                        <button type=\"button\" class=\"btn btn-sm btn-primary\" data-bind=\"click: addSchedule\">\n                            <i class=\"fa fa-plus\"></i> Add Schedule\n                        </button>\n                    </div>\n                    <div class=\"text-muted small mb-2\" data-bind=\"visible: schedules().length === 0\">\n                        No schedules yet. Click \"Add Schedule\" to create one.\n                    </div>\n                    <table class=\"table table-sm align-middle\" data-bind=\"visible: schedules().length > 0\">\n                        <thead>\n                            <tr>\n                                <th>When</th>\n                                <th>Email</th>\n                                <th>Format</th>\n                                <th>Filter</th>\n                                <th class=\"text-end\"></th>\n                            </tr>\n                        </thead>\n                        <tbody data-bind=\"foreach: schedules\">\n                            <tr>\n                                <td data-bind=\"text: $parent.scheduleSummary($data)\"></td>\n                                <td data-bind=\"text: $root.scheduleBuilder.emailToDisplay($data)\"></td>\n                                <td data-bind=\"text: $parent.formatSummary($data)\"></td>\n                                <td class=\"small text-muted\" data-bind=\"text: $parent.filterSummary($data)\"></td>\n                                <td class=\"text-end text-nowrap\">\n                                    <div class=\"btn-group btn-group-sm\" role=\"group\">\n                                        <button type=\"button\" class=\"btn btn-outline-secondary\" title=\"Edit\" data-bind=\"click: function() { $parent.editSchedule($data); }\"><i class=\"fa fa-pencil\"></i></button>\n                                        <button type=\"button\" class=\"btn btn-outline-secondary\" title=\"Change Filter\" data-bind=\"click: function() { $parent.changeFilter($data); }\"><i class=\"fa fa-filter\"></i></button>\n                                        <button type=\"button\" class=\"btn btn-outline-danger\" title=\"Delete\" data-bind=\"click: function() { $parent.deleteSchedule($data); }\"><i class=\"fa fa-trash\"></i></button>\n                                    </div>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n                <div data-bind=\"visible: viewMode() === 'edit'\">\n                    <div data-bind=\"template: { name: 'report-schedule', data: $parent }\"></div>\n                </div>\n                <div id=\"schedule-filter-editor\" class=\"needs-validation\" data-bind=\"visible: viewMode() === 'filter'\">\n                    <strong>Filter for this schedule</strong>\n                    <div class=\"small text-muted mb-2\">\n                        When set, this schedule runs with <b>exactly these filters</b> instead of the report's saved filters and\n                        any filter changes made later on the report won't affect this schedule. Use <b>Report's Filters</b> to remove the\n                        override and follow the report's current filters again.\n                    </div>\n                    <div data-bind=\"template: { name: 'filter-group', data: $parent.scheduleFilterHost }\"></div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary\" data-bind=\"visible: viewMode() === 'list'\" data-bs-dismiss=\"modal\">Close</button>\n                <button type=\"button\" class=\"btn btn-secondary\" data-bind=\"visible: viewMode() === 'edit', click: backToList\">Back</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"visible: viewMode() === 'edit', click: saveSchedule\">Save Schedule</button>\n                <button type=\"button\" class=\"btn btn-secondary\" data-bind=\"visible: viewMode() === 'filter', click: backToList\">Back</button>\n                <button type=\"button\" class=\"btn btn-outline-secondary\" data-bind=\"visible: viewMode() === 'filter', click: resetScheduleFilter\" title=\"Remove this schedule's filter override and follow the report's saved filters\">Use Report's Filters</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"visible: viewMode() === 'filter', click: applyScheduleFilter\">Apply Filter</button>\n            </div>\n        </div>\n    </div>\n</div>\n<!-- Templates -->\n<!-- Dotnet Report HTML Templates -->\n<script type=\"text/html\" id=\"report-filter\">\n    <div class=\"form-group\" data-bind=\"attr: {id: 'filter-'+uiId }\">\n        <!-- ko if: !hasForeignKey-->\n        <!-- ko if: ['DateTime','Date','Time'].indexOf(fieldType) != -1 -->\n        <div style=\"display: flex; align-items: center; gap: 8px;\">\n            <!-- ko if: ['=','>','<','>=','<=', 'not equal'].indexOf($parent.Operator()) != -1 -->\n            <input class=\"form-control\" data-bind=\"datepicker: $parent.fmtValue, datepickerOptions: {value: $parent.Value, dateFormat: (['Date','Date and Time','Time'].indexOf(fieldFormat()) >= 0 && dateFormat() && dateFormat() !== 'Custom') ? $root.dateFormatMappings[dateFormat()] : $root.dateFormatMappings[($root.appSettings && $root.appSettings.defaultDateFormat) || 'United States']}\" required />\n            <!-- ko if: fieldType=='Time' || fieldFormat()=='Time' || fieldFormat()=='Date and Time'-->\n            <input class=\"form-control\" type=\"time\" data-bind=\"value:$parent.Valuetime\" required>\n            <!-- /ko -->\n            <!-- /ko -->\n        </div>\n        <!-- ko if: ['between'].indexOf($parent.Operator()) != -1 -->\n        From\n        <div style=\"display: flex; align-items: center; gap: 8px;\">\n            <input required class=\"form-control from-date\" data-bind=\"datepicker: $parent.fmtValue, datepickerOptions: {value: $parent.Value, dateFormat: (['Date','Date and Time','Time'].indexOf(fieldFormat()) >= 0 && dateFormat() && dateFormat() !== 'Custom') ? $root.dateFormatMappings[dateFormat()] : $root.dateFormatMappings[($root.appSettings && $root.appSettings.defaultDateFormat) || 'United States']}\" />\n            <!-- ko if:fieldType=='Time' || fieldFormat()=='Time' || fieldFormat()=='Date and Time'-->\n            <input class=\"form-control\" type=\"time\" data-bind=\"value:$parent.Valuetime\" required>\n            <!-- /ko -->\n        </div>\n        to\n        <div style=\"display: flex; align-items: center; gap: 8px;\">\n            <input data-bind=\"datepicker: $parent.fmtValue2, datepickerOptions: {value: $parent.Value2, dateFormat: (['Date','Date and Time','Time'].indexOf(fieldFormat()) >= 0 && dateFormat() && dateFormat() !== 'Custom') ? $root.dateFormatMappings[dateFormat()] : $root.dateFormatMappings[($root.appSettings && $root.appSettings.defaultDateFormat) || 'United States']}\" class=\"form-control to-date\" required />\n            <!-- ko if:fieldType=='Time' || fieldFormat()=='Time' || fieldFormat()=='Date and Time'-->\n            <input class=\"form-control\" type=\"time\" data-bind=\"value:$parent.Valuetime2\" required>\n            <!-- /ko -->\n        </div>\n        <!-- /ko -->\n        <!-- ko if: ['range'].indexOf($parent.Operator()) != -1 -->\n        <select data-bind=\"value: $parent.Value\" class=\"form-select\" required>\n            <option value=\"\"></option>\n            <option>Today</option>\n            <option>Today +</option>\n            <option>Today -</option>\n            <option>Yesterday</option>\n            <option>This Week</option>\n            <option>Last Week</option>\n            <option>This Month</option>\n            <option>Last Month</option>\n            <option>This Year</option>\n            <option>Last Year</option>\n            <option>This Week To Date</option>\n            <option>This Month To Date</option>\n            <option>This Year To Date</option>\n            <option>Last 30 Days</option>\n            <!--<option>This Month Last Year</option>\n            <option>Last Month Last Year</option>\n            <option>This Quarter</option>\n            <option>Last Quarter</option>\n            <option>First Quarter</option>\n            <option>Second Quarter</option>\n            <option>Third Quarter</option>\n            <option>Fourth Quarter</option>\n            <option>Next 6 Months</option>\n            <option>Last 6 Months</option>\n            <option>2 Years ago</option>\n            <option>3 Years ago</option>\n            <option>4 Years ago</option>\n            <option>5 Years ago</option>-->\n            <optgroup label=\"Comparison Options\">\n                <option>>= Today</option>\n                <option><= Today</option>\n                <option>>= Today +</option>\n                <option><= Today +</option>\n                <option>>= Today -</option>\n                <option><= Today -</option>\n            </optgroup>\n        </select>\n        <div data-bind=\"if: $parent.Value().indexOf('Today +') >= 0 || $parent.Value().indexOf('Today -') >= 0\" class=\"form-group float-start\" style=\"padding-top: 5px;\">\n            <input type=\"number\" class=\"form-control input-sm float-start\" style=\"width: 80px;\" data-bind=\"value: $parent.Value2\" required /><span style=\"padding: 5px 5px;\" class=\"float-start\"> days</span>\n        </div>\n        <!-- /ko -->\n        <!-- /ko -->\n        <!-- ko if: ['Int','Money','Float','Double'].indexOf(fieldType) != -1 -->\n            <!-- ko if: ['=','>','<','>=','<=', 'not equal'].indexOf($parent.Operator()) != -1 && ['is blank', 'is not blank', 'is null', 'is not null'].indexOf($parent.Operator()) == -1 -->\n            <input class=\"form-control\" type=\"number\" data-bind=\"value: $parent.Value, disable: $parent.Operator() == 'is default'\" required />\n            <!-- /ko -->\n             <!-- ko if: ['in', 'not in'].indexOf($parent.Operator()) != -1 -->\n            <input class=\"form-control\" type=\"text\" data-bind=\"value: $parent.Value\" required />\n            <!-- /ko -->\n            <!-- ko if: ['between'].indexOf($parent.Operator()) != -1 -->\n            From\n            <input class=\"form-control\" type=\"number\" data-bind=\"value: $parent.Value\" required />\n            To\n            <input class=\"form-control\" type=\"number\" data-bind=\"value: $parent.Value2\" required />\n        <!-- /ko -->\n        <!-- /ko -->\n        <!-- ko if: fieldType=='Boolean' && ['is blank', 'is not blank', 'is null', 'is not null'].indexOf($parent.Operator()) == -1 -->\n        <select required class=\"form-select\" data-bind=\"value: $parent.Value, disable: $parent.Operator() == 'is default'\">\n            <option value=\"1\">Yes</option>\n            <option value=\"0\">No</option>\n        </select>\n        <!-- /ko -->\n        <!-- ko if: ['Int','Money','Float','Double','Date','DateTime','Time','Boolean'].indexOf(fieldType) == -1 && ['is blank', 'is not blank', 'is null', 'is not null'].indexOf($parent.Operator()) == -1 -->\n        <input class=\"form-control\" type=\"text\" data-bind=\"value: $parent.Value, disable: $parent.Operator() == 'is default',attr: {id: 'ctl-' + $element.closest('[data-parentprefix]').getAttribute('data-parentprefix') + '-' + ($parent.uiId || uiId)}\" required />\n        <!-- /ko -->\n        <!-- /ko -->\n        <!-- ko if: hasForeignKey && $parent.Operator() != 'all' && $parent.Operator() != 'none' && $parent.Operator() != 'no filter' -->\n        <!-- ko if: hasForeignParentKey && $parent.showParentFilter() -->\n        <select multiple class=\"form-control\" data-bind=\"select2: { dropdownParent: '#filter-'+uiId, placeholder: 'Please Choose', allowClear: true }, lookupSearch: $parent.SearchParentList, options: $parent.ParentList, optionsText: 'text', optionsValue: $parent.IsConditionalFilter ? 'text': 'id', selectedOptions: $parent.ParentIn\"></select>\n        <!-- /ko -->\n        <!-- ko if: $parent.Operator()=='='-->\n        <select required class=\"form-control\" data-bind=\"select2: { dropdownParent: '#filter-'+uiId, placeholder: 'Please Choose', allowClear: true }, lookupSearch: $parent.SearchLookupList, options: $parent.LookupList, optionsText: 'text', optionsValue:   $parent.IsConditionalFilter ? 'text': 'id', value: $parent.Value, optionsCaption: 'Please Choose'\"></select>\n        <!-- /ko -->\n        <!-- ko if: $parent.Operator()=='in' || $parent.Operator()=='not in'-->\n        <select required multiple class=\"form-control\" data-bind=\"select2: { dropdownParent: '#filter-'+uiId, placeholder: 'Please Choose', allowClear: true }, lookupSearch: $parent.SearchLookupList, options: $parent.LookupList, optionsText: 'text', optionsValue: $parent.IsConditionalFilter ? 'text': 'id', selectedOptions: $parent.ValueIn\"></select>\n        <!-- /ko -->\n        <!-- /ko -->\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"pager-template\">\n    <div class=\"pager-container d-flex align-items-center flex-wrap gap-2\">\n\n        <!-- Rows per page -->\n        <div class=\"d-flex align-items-center gap-1 ms-1\">\n            <span class=\"text-muted small\">Page size:</span>\n            <select class=\"form-select form-select-sm w-auto\"\n                    data-bind=\"options: pageSizeOptions, value: pageSize\">\n            </select>\n        </div>\n\n        <!-- Inner border block for page navigation controls -->\n        <div class=\"d-flex align-items-center gap-1 ms-3\">\n            <a href=\"#\" title=\"First\" data-bind=\"click: first, enable: !isFirstPage()\"\n               class=\"btn btn-outline-secondary btn-sm pager-btn ms-1\" aria-label=\"First Page\">\n                <i class=\"fa fa-angle-double-left\"></i>\n            </a>\n\n            <a href=\"#\" title=\"Previous\" data-bind=\"click: previous, enable: !isFirstPage()\"\n               class=\"btn btn-outline-secondary btn-sm pager-btn\" aria-label=\"Previous Page\">\n                <i class=\"fa fa-angle-left\"></i>\n            </a>\n\n            <div class=\"d-flex align-items-center gap-1\">\n                <span class=\"text-muted small\">Page</span>\n                <input type=\"number\" min=\"1\" pattern=\"[0-9]*\"\n                       class=\"form-control form-control-sm text-center pager-input\"\n                       style=\"width: 60px;\"\n                       data-bind=\"value: currentPage, attr: { max: pages() }\">\n                <span class=\"text-muted small\">of</span>\n                <span class=\"text-muted small\" data-bind=\"text: pages\"></span>\n            </div>\n\n            <a href=\"#\" title=\"Next\" data-bind=\"click: next, enable: !isLastPage()\"\n               class=\"btn btn-outline-secondary btn-sm pager-btn\" aria-label=\"Next Page\">\n                <i class=\"fa fa-angle-right\"></i>\n            </a>\n\n            <a href=\"#\" title=\"Last\" data-bind=\"click: last, enable: !isLastPage()\"\n               class=\"btn btn-outline-secondary btn-sm pager-btn\" aria-label=\"Last Page\">\n                <i class=\"fa fa-angle-double-right\"></i>\n            </a>\n        </div>\n    </div>\n</script>\n\n\n\n<script type=\"text/html\" id=\"report-column-header\">\n    <!-- ko foreach: Columns -->\n    <th data-bind=\"attr: { id: !IsPivotField ? fieldId : 'pivot--' + fieldName }, style: {'text-align': fieldAlign() ? fieldAlign() : (IsNumeric ? 'right' : 'left'), 'background-color': headerBackColor }, hidden: outerGroup\" style=\"border-right: 1px solid;\">\n\n        <!-- ko if: !$parent.IsDrillDown() && !$parent.IsSubReport() -->\n        <div class=\"float-start\" style=\"padding-right: 5px;\">\n            <div class=\"dropup\">\n                <a href=\"#\" data-bs-toggle=\"dropdown\" aria-haspopup=\"false\" aria-expanded=\"false\">\n                    <span class=\"fa fa-ellipsis-v sortable\" title=\"Drag to reorder\"></span>\n                </a>\n                <ul data-bind=\"visible: !IsPivotField\" class=\"dropdown-menu field-quick-menu\" style=\"z-index: 1001; min-width: 170px;\">\n                    <li class=\"dropdown-item small px-2 py-1\">\n                        <div class=\"field-quick-row\">\n                            <span class=\"field-quick-label\">Align</span>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Align Left\"\n                                    data-bind=\"click: function(){ fieldAlign('Left'); }, css: {'active': fieldAlign() === 'Left'}, clickBubble: false\">\n                                <i class=\"fa fa-align-left\"></i>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Align Center\"\n                                    data-bind=\"click: function(){ fieldAlign('Center'); }, css: {'active': fieldAlign() === 'Center'}, clickBubble: false\">\n                                <i class=\"fa fa-align-center\"></i>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Align Right\"\n                                    data-bind=\"click: function(){ fieldAlign('Right'); }, css: {'active': fieldAlign() === 'Right'}, clickBubble: false\">\n                                <i class=\"fa fa-align-right\"></i>\n                            </button>\n                        </div>\n                    </li>\n                    <li class=\"dropdown-item small px-2 py-1\" data-bind=\"visible: IsNumeric\">\n                        <div class=\"field-quick-row\">\n                            <span class=\"field-quick-label\">Format</span>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Currency\"\n                                    data-bind=\"click: function(){ fieldFormat(fieldFormat() === 'Currency' ? 'Auto' : 'Currency'); }, css: {'active': fieldFormat() === 'Currency'}, clickBubble: false\">\n                                <i class=\"fa fa-dollar\"></i>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Percentage\"\n                                    data-bind=\"click: function(){ fieldFormat(fieldFormat() === 'Percentage' ? 'Auto' : 'Percentage'); }, css: {'active': fieldFormat() === 'Percentage'}, clickBubble: false\">\n                                <i class=\"fa fa-percent\"></i>\n                            </button>\n                        </div>\n                    </li>\n                    <li><hr class=\"dropdown-divider my-1\"></li>\n                    <li class=\"dropdown-item small\" data-bind=\"visible: !IsNumeric\">\n                        <a href=\"#\" data-bind=\"click: toggleOuterGroup\">\n                            <span class=\"fa fa-clone\"></span> Outer Group\n                        </a>\n                    </li>\n                    <li class=\"dropdown-item small\">\n                        <a href=\"#\" data-bind=\"click: setupFieldOptions\">\n                            <span class=\"fa fa-gear\"></span> More Settings\n                        </a>\n                    </li>\n                </ul>\n            </div>\n        </div>\n        <!-- /ko -->\n        <div data-bind=\"style: {'width': fieldWidth}\">\n            <!-- ko if: $parents[3].useStoredProc ? $parents[3].useStoredProc() : ($parents[5].useStoredProc ? $parents[5].useStoredProc() : false) -->\n            <span data-bind=\"text: fieldLabel() ? fieldLabel() : fieldName, style: {'color': headerFontColor, 'font-weight': headerFontBold() ? 'bold' : 'normal'}\"></span>\n            <!-- /ko -->\n            <!-- ko ifnot: $parents[3].useStoredProc ? $parents[3].useStoredProc() : ($parents[5].useStoredProc ? $parents[5].useStoredProc() : false)  -->\n            <a href=\"\" data-bind=\"click: function(){ if (!IsPivotField) { $parents[pagerIndex($parents)].changeSort(SqlField); } }, style: {'color': headerFontColor, 'font-weight': headerFontBold() ? 'bold' : 'normal'}\">\n                <span data-bind=\"text: $parent.IsDrillDown() && fieldLabel2() ? fieldLabel2() : (fieldLabel() ? fieldLabel() : fieldName)\"></span>\n                <span data-bind=\"text: $parents[pagerIndex($parents)].pager.sortColumn() === SqlField ? ($parents[pagerIndex($parents)].pager.sortDescending() ? '&#9660;' : '&#9650;') : ''\"></span>\n            </a>\n            <!-- /ko -->\n        </div>\n    </th>\n    <!-- /ko -->\n</script>\n\n<script type=\"text/html\" id=\"report-widget\">\n    <div data-bind=\"style: { 'font-size': (FontSize ? FontSize : '48px'),'text-align': Alignment ? Alignment : 'center','color': FontColor ? FontColor : '#000000','background-color':BackColor ? BackColor : '#fff' }\" style=\"width: 100%;\">\n        <span data-bind=\"visible: Rows.length < 1\" title=\"No data found\">/</span>\n\n        <div data-bind=\"if: Rows.length > 0\">\n            <div data-bind=\"with: $parent.rows[0].Items[0]\">\n                <span class=\"preserve-space\" data-bind=\"html: $parent.formatKpiValue(Value, formattedVal())\"></span>\n\n                <!-- ko if: $parent.Rows.length > 1 ? ($parents[$parents.length-2].showPriorInKpi != undefined ? $parents[$parents.length-2].showPriorInKpi() : $parents[$parents.length-1].showPriorInKpi()) : false -->\n                <div data-bind=\"style: {'font-size': '20px'}\" class=\"text-muted\">\n                    <span data-bind=\"text: $parent.comparisonLabel\"></span>: <span class=\"preserve-space\" data-bind=\"html: $parent.formatKpiValue($parent.Rows[1].Items[0].Value, $parent.Rows[1].Items[0].formattedVal)\"></span>\n                    <span data-bind=\"style: {'color': $parent.calculateRate() > 0 ? $parent.PositiveColor : $parent.NegativeColor, 'font-size': '20px'}\">\n                        <i data-bind=\"css: $parent.calculateRate() > 0 ? 'fa fa-arrow-up' : 'fa fa-arrow-down'\"></i>\n                        <span data-bind=\"html: Math.abs($parent.calculateRate()) + '%'\"></span>\n                    </span>\n                </div>\n                <!-- /ko -->\n\n            </div>\n        </div>\n    </div>\n\n</script>\n<script type=\"text/html\" id=\"kpi-settings\">\n    <div class=\"chart-container float-end\">\n        <button class=\"btn btn-light btn-sm d-flex align-items-center mt-2 chart-settings-btn\"\n                data-bind=\"click: toggleKpiSettings()\" title=\"KPI Settings\">\n            <i class=\"fa fa-cog\"></i>\n        </button>\n        <div class=\"kpi-settings-panel border p-2 shadow-sm bg-light\"\n             data-bind=\"visible: showKpiSettings\">\n            <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                <button class=\"btn btn-sm btn-close\" data-bind=\"click: toggleKpiSettings()\"></button>\n                <h6 class=\"mb-0\">KPI Settings</h6>\n            </div>\n            <ul class=\"nav nav-tabs nav-sm mb-2 small\">\n                <li class=\"nav-item\">\n                    <a class=\"nav-link active\"\n                       data-bs-toggle=\"tab\"\n                       data-bind=\"attr: { href: '#kpiTab-' + ReportID() }\">\n                        KPI\n                    </a>\n                </li>\n            </ul>\n            <div class=\"tab-content small\">\n                <!-- KPI Tab -->\n                <div class=\"tab-pane fade show active\"\n                     data-bind=\"attr: { id: 'kpiTab-' + ReportID() }\">\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Font Size</label>\n                        <input type=\"number\"\n                               class=\"form-control form-control-sm\"\n                               min=\"10\" max=\"100\"\n                               data-bind=\"value: kpiSettings().fontSize, event: { input: updateKpi }\">\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Alignment</label>\n                        <select class=\"form-select form-select-sm\"\n                                data-bind=\"value: kpiSettings().alignment, event: { change: updateKpi }\">\n                            <option value=\"left\">Left</option>\n                            <option value=\"center\">Center</option>\n                            <option value=\"right\">Right</option>\n                        </select>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Font Color</label>&nbsp;&nbsp;&nbsp;&nbsp;\n                        <label class=\"form-label small\">Back Color</label><br />\n                        <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: kpiSettings().fontColor,event: { change: updateKpi }\"/>\n                               &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n                        <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: kpiSettings().backColor,event: { change: updateKpi }\"/>\n                    </div>\n                    <div data-bind=\"visible:showPriorInKpi()\" class=\"mb-2\">\n                        <label class=\"form-label small\">Rate Color (+ / -)</label><br />\n                        <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: kpiSettings().positiveColor, event: { change: updateKpi }\"/> +\n                        <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: kpiSettings().negativeColor, event: { change: updateKpi }\"/> -\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Number Format</label>\n                        <select class=\"form-select form-select-sm\"\n                                data-bind=\"value: kpiSettings().numberFormat, event: { change: updateKpi }\">\n                            <option value=\"number\">Number</option>\n                            <option value=\"currency\">Currency</option>\n                            <option value=\"custom\">Custom Format</option>\n                        </select>\n                        <input type=\"text\"\n                               class=\"form-control form-control-sm mt-2\"\n                               placeholder=\"e.g. #,###.00\"\n                               data-bind=\"value: kpiSettings().customFormat,\n                                          visible: kpiSettings().numberFormat() === 'custom',\n                                          valueUpdate:'input',\n                                          event:{ input:updateKpi }\">\n                    </div>\n                    <div data-bind =\"visible: kpiSettings().numberFormat() === 'currency'\" class=\"mb-2\">\n                        <label class=\"form-label small\">Currency Symbol</label>\n                        <select class=\"form-select form-select-sm\"\n                                data-bind=\"value: kpiSettings().currencySymbol,event:{ change:updateKpi }\">\n                            <option value=\"$\">USD ($)</option>\n                            <option value=\"€\">Euro (€)</option>\n                            <option value=\"£\">Pound (£)</option>\n                            <option value=\"₹\">Indian Rupee (₹)</option>\n                            <option value=\"Rs\">Rupee (Rs)</option>\n                        </select>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Short Format</label>\n                        <select class=\"form-select form-select-sm\"\n                                data-bind=\"value: kpiSettings().shortFormat,event:{ change:updateKpi }\">\n                            <option value=\"none\">None</option>\n                            <option value=\"thousand\">Thousands (K)</option>\n                            <option value=\"million\">Millions (M)</option>\n                            <option value=\"billion\">Billions (B)</option>\n                        </select>\n                    </div>\n                    <div class=\"d-flex justify-content-end mb-2\">\n                        <button class=\"btn btn-sm\"\n                                data-bind=\"click: copyKpiFormat\"\n                                title=\"Copy Format\">\n                            <i class=\"fa fa-copy\"></i>\n                        </button>\n                        <button class=\"btn btn-sm\"\n                                data-bind=\"click: pasteKpiFormat\"\n                                title=\"Paste Format\">\n                            <i class=\"fa fa-paste\"></i>\n                        </button>\n                         <button class=\"btn btn-sm\"\n                                data-bind=\"click: clearKpiSettings\"\n                                title=\"Clear\">\n                                <i class=\"fa fa-close\"></i>\n                        </button>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"report-column\">\n    <!-- ko foreach: Items -->\n    <td data-bind=\"hidden: outerGroup, style: {'background-color': _backColor ?? backColor(), 'color': _fontColor ?? fontColor(), 'font-weight': fontBold() || _fontBold ? 'bold' : 'normal', 'text-align': fieldAlign() ? fieldAlign() : (Column.IsNumeric ? 'right' : 'left')}\">\n        <div data-bind=\"style: {'width': fieldWidth }, css: { 'text-wrap': fieldWidth }\">\n            <!-- ko if: LinkTo-->\n            <!-- ko if: $data._runLinkedReportInPlace -->\n            <a href=\"#\" data-bind=\"click: $data._runLinkedReportInPlace\"><span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span></a>\n            <!-- /ko -->\n            <!-- ko ifnot: $data._runLinkedReportInPlace -->\n            <a data-bind=\"attr: {href: LinkTo}\" target=\"_blank\"><span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span></a>\n            <!-- /ko -->\n            <!-- /ko-->\n            <!-- ko ifnot: LinkTo-->\n            <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n            <!-- /ko-->\n        </div>\n    </td>\n</script>\n\n<script type=\"text/html\" id=\"report-pivot\">\n    <div class=\"table-responsive\" data-bind=\"with: ReportData\">\n        <table class=\"table table-striped table-hover table-condensed\">\n            <thead style=\"position: sticky; top: -1px; z-index: 2;\">\n                <tr>\n                    <th></th>\n                    <!-- ko foreach: Rows -->\n                    <th>\n                        <span class=\"preserve-space\" data-bind=\"text: Items[0].FormattedValue\"></span>\n                    </th>\n                    <!-- /ko -->\n                </tr>\n            </thead>\n            <tbody data-bind=\"foreach: Columns\">\n                <tr>\n                    <!-- ko if: $index() > 0 -->\n                    <td>\n                        <span data-bind=\"text: fieldLabel || ColumnName\"></span>\n                    </td>\n                    <!-- ko foreach: $parent.Rows -->\n                    <td data-bind=\"style: {'background-color': $parent.backColor, 'color': $parent.fontColor, 'font-weight': $parent.fontBold() ? 'bold' : 'normal', 'text-align': $parent.fieldAlign ? $parent.fieldAlign : ($parent.IsNumeric ? 'right' : 'left') }\">\n                        <span class=\"preserve-space\" data-bind=\"text: Items[$parentContext.$index()].FormattedValue\"></span>\n                    </td>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                </tr>\n            </tbody>\n        </table>\n\n    </div>\n\n</script>\n\n<script type=\"text/html\" id=\"report-table\">\n    <div class=\"table-responsive\">\n        <table class=\"table table-hover table-condensed\" data-bind=\"attr: {class: 'table table-striped table-hover table-condensed ' + $parents[2].selectedStyle()}\">\n            <thead style=\"position: sticky; top: -1px; z-index: 2;\" data-bind=\"if: !$parents[2].noHeaderRow(), attr: {id: 'report-table-head' + $parents[2].ReportID()}\">\n                <tr class=\"no-highlight\" data-bind=\"sortableColumns: { handle: '.sortable', cursor: 'move', placeholder: 'drop-highlight',selectedFields: $parents[2].SelectedFields }\">\n                    <!-- ko if: $parentContext.$parentContext.$parent.canDrilldown() && !IsDrillDown() && !CanExpandOption() && (!$parents[2].hasPivotColumn() || ($parents[2].hasPivotColumn() && $parents[2].appSettings.useAltPivot)) -->\n                    <th style=\"width: 30px; border-left: 1px solid;\" data-bind=\"style: {'background-color': Columns[0].headerBackColor}\"></th>\n                    <!-- /ko -->\n                    <!-- ko template: 'report-column-header', data: $data -->\n                    <!-- /ko-->\n                </tr>\n            </thead>\n            <tbody data-bind=\"attr: {id: 'report-table-body' + $parents[2].ReportID()}\">\n                <tr style=\"display: none;\" data-bind=\"visible: Rows.length < 1\">\n                    <td data-bind=\"attr:{colspan: Columns.length + 1}\">\n                        No records found\n                    </td>\n                </tr>\n\n                <!-- ko if: !$parents[2].useRenderTable() -->\n                <!-- ko foreach: $parent.rows  -->\n                <tr>\n                    <!-- ko if: $parentContext.$parentContext.$parentContext.$parent.canDrilldown() && !$parent.IsDrillDown() && !$parent.CanExpandOption() && $parentContext.$parentContext.$parentContext.$parent.ReportType() != 'Single' -->\n                    <td style=\"width: 30px; vertical-align: middle;\" data-bind=\"style: {'background-color': Items[0]._backColor ?? Items[0].backColor(), 'color': Items[0]._fontColor ?? Items[0].fontColor()}\">\n                        <a href=\"#\" data-bind=\"click: function(){ toggle(); }\"><span class=\"fa\" data-bind=\"css: {'fa-plus': !isExpanded(), 'fa-minus': isExpanded()}\"></span></a>\n                    </td>\n                    <!-- /ko -->\n                    <!-- ko template: 'report-column', data: $data -->\n                    <!-- /ko-->\n                </tr>\n                <!-- ko if: isExpanded -->\n                <tr>\n                    <td style=\"width: 30px;\"></td>\n                    <td data-bind=\"attr:{colspan: $parent.Columns.length }\" style=\"padding-left: 0px;\">\n                        <div data-bind=\"visible: !DrillDownData()\">\n                            <div class=\"report-spinner\"></div>\n                        </div>\n                        <!-- ko if: DrillDownData -->\n                        <table class=\"table table-striped table-hover table-condensed\" data-bind=\"with: DrillDownData\">\n                            <thead>\n                                <tr class=\"no-highlight\">\n                                    <!-- ko template: 'report-column-header', data: $data -->\n                                    <!-- /ko-->\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <tr style=\"display: none;\" data-bind=\"visible: Rows && Rows.length < 1\">\n                                    <td data-bind=\"attr: {colspan: Columns.length}\">\n                                        No records found\n                                    </td>\n                                </tr>\n                                <!-- ko foreach: Rows  -->\n                                <tr>\n                                    <!-- ko template: 'report-column', data: $data -->\n                                    <!-- /ko-->\n                                </tr>\n                                <!-- /ko -->\n                            </tbody>\n                        </table>\n                        <div class=\"col-xs-12 col-centered\" data-bind=\"with: pager\">\n                            <div class=\"form-inline small text-muted\">\n                                <div class=\"float-start total-records\" data-bind=\"visible: pages()\">\n                                    <span data-bind=\"text: 'Total Records: ' + totalRecords()\"></span>\n                                </div>\n                                <div class=\"float-start total-records\">\n                                    &nbsp;\n                                    <a href=\"#\" title=\"Download Excel\" data-bind=\"click: $parent.exportExcel\"><span class=\"fas fa-file-excel\"></span></a>\n                                    &nbsp;\n                                    <a href=\"#\" title=\"View Code\" data-bs-toggle=\"modal\" data-bs-target=\"#sqlDrillDownModal\" data-bind=\"visible: $root.adminMode\">\n                                        <span class=\"fa fa-code\"></span>\n                                    </a>\n                                </div>\n                                <div class=\"form-group float-end\" data-bind=\"visible: pages()\">\n                                    <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                                </div>\n                            </div>\n                        </div>\n                        <!-- /ko -->\n                    </td>\n                </tr>\n                <!-- /ko -->\n                <!-- ko if: subReportsRan().length > 0 -->\n                <tr>\n                    <td data-bind=\"attr:{colspan: $parent.Columns.length }\" style=\"padding-left: 0px;\">\n                        <div data-bind=\"foreach: subReportsRan\">\n                            <div data-bind=\"template: { name: 'subreport-content', data: $data }\"></div>\n                        </div>\n                    </td>\n                </tr>\n                <!-- /ko -->\n                <!-- /ko -->\n                <!-- /ko-->\n            </tbody>\n            <!-- ko if: $parentContext.$parent.SubTotals().length == 1 && $parentContext.$parentContext.$parent.OuterGroupColumns().length == 0 && $parentContext.$parentContext.$parent.totalRowFormat() == 'row' -->\n            <tfoot data-bind=\"foreach: $parentContext.$parent.SubTotals\">\n                <tr class=\"sub-total\">\n                    <!-- ko if: $parentContext.$parentContext.$parentContext.$parent.canDrilldown() && !$parent.IsDrillDown() && !$parent.CanExpandOption() -->\n                    <td></td>\n                    <!-- /ko -->\n                    <!-- ko foreach: Items -->\n                    <!-- ko if: Value != 'NA' && Value != 'NaN' && !outerGroup() -->\n                    <td data-bind=\"style: {'background-color': _backColor ?? backColor(), 'color': _fontColor ?? fontColor(), 'font-weight': fontBold() || _fontBold ? 'bold' : 'normal', 'text-align': fieldAlign() ? fieldAlign() : 'right'}\">\n                        <div data-bind=\"style: {'width': fieldWidth }, attr: {'title': (Column.fieldLabel() || Column.ColumnName) + ' - ' +_aggregate }, visible:  _showInTotalRow != false\">\n                        <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n                        </div>\n                    </td>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                </tr>\n            </tfoot>\n            <!-- /ko -->\n            <!-- ko if: $parentContext.$parentContext.$parent.subTotalPerGroup() && $parentContext.$parent.perGroupSubTotals().length > 0 && $parentContext.$parentContext.$parent.totalRowFormat() == 'row' -->\n            <!-- ko if: $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex] && $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex].length > 0 -->\n            <tfoot>\n                <tr class=\"sub-total\" style=\"border-top: 2px solid #dee2e6;\">\n                    <!-- ko if: $parentContext.$parentContext.$parent.canDrilldown() && IsDrillDown() && CanExpandOption() -->\n                    <td></td>\n                    <!-- /ko -->\n                    <!-- ko foreach: $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex] -->\n                    <td data-bind=\"style: {'text-align': Column.IsNumeric ? 'right' : 'left', 'font-weight': 'bold'}\">\n                        <div data-bind=\"style: {'width': Column.fieldWidth}\">\n                            <span class=\"preserve-space\" data-bind=\"text: formattedVal\"></span>\n                        </div>\n                    </td>\n                    <!-- /ko -->\n                </tr>\n            </tfoot>\n            <!-- /ko -->\n            <!-- /ko -->\n        </table>\n        <!-- ko if: $parentContext.$parent.SubTotals().length > 0 && $parentContext.$parentContext.$parent.totalRowFormat() == 'table' && $parentContext.$parentContext.$parent.OuterGroupColumns().length == 0 -->\n        <div class=\"mt-3\" style=\"max-width: 450px;\">\n            <table class=\"table table-bordered table-sm\">\n                <thead>\n                    <tr>\n                        <th>Field</th>\n                        <th class=\"text-end\">Total</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <!-- ko foreach: $parentContext.$parent.SubTotals()[0].Items -->\n                    <!-- ko if: _showInTotalRow != false && Value != 'NA' && Value != 'NaN' -->\n                    <tr>\n                        <td data-bind=\"text: (Column.fieldLabel() || Column.ColumnName) + ' (' + _aggregate + ')'\"></td>\n                        <td class=\"text-end\">\n                            <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n                        </td>\n                    </tr>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                </tbody>\n            </table>\n        </div>\n        <!-- /ko -->\n        <!-- ko if: $parentContext.$parent.SubTotals().length > 0 && $parentContext.$parentContext.$parent.totalRowFormat() == 'table' && $parentContext.$parentContext.$parent.OuterGroupColumns().length > 0 && $parentContext.$parentContext.$parent.subTotalPerGroup() -->\n        <!-- ko if: $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex] && $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex].length > 0 -->\n        <div class=\"mt-3\" style=\"max-width: 450px;\">\n            <table class=\"table table-bordered table-sm\">\n                <thead>\n                    <tr>\n                        <th>Field</th>\n                        <th class=\"text-end\">Total</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <!-- ko foreach: $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex] -->\n                    <!-- ko if: _showInTotalRow != false -->\n                    <tr>\n                        <td data-bind=\"text: Column.fieldLabel() || Column.ColumnName\"></td>\n                        <td class=\"text-end\">\n                            <span class=\"preserve-space\" data-bind=\"text: formattedVal\"></span>\n                        </td>\n                    </tr>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                </tbody>\n            </table>\n        </div>\n        <!-- /ko -->\n        <!-- /ko -->\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"report-render\">\n    <div data-bind=\"with: ReportData\">\n        <div data-bind=\"foreach: Rows\">\n            <div data-bind=\"html: renderedHtml, css: { 'card-view': $parents[$parents.length-1].cardView }\"></div>\n\n            <div data-bind=\"foreach: subReportsRan\">\n                <!-- ko if: !_isInline -->\n                <div data-bind=\"template: { name: 'subreport-content', data: $data }\"></div>\n                <!-- /ko -->\n                <!-- ko if: _isInline -->\n                <div style=\"display:none\" data-bind=\"moveToInlineContainer: $data\"></div>\n                <!-- /ko -->\n            </div>\n        </div>\n    </div>\n    <div class=\"clearfix\"></div>\n</script>\n\n<script type=\"text/html\" id=\"subreport-content\">\n    <div class=\"\" style=\"padding-bottom: 20px; position: relative;\">\n        <a href=\"#\" class=\"text-muted\" title=\"Edit sub report\" style=\"position: absolute; right: 5px; top: 2px;\" data-bind=\"visible: CanEdit(), click: function() { var vm = _parentVM || $root; vm.editSubReport({ reportId: ReportID() }); }\">\n            <span class=\"fa fa-pencil\"></span>\n        </a>\n        <h2 data-bind=\"text: ReportName, visible: !_hideTitle\"></h2>\n        <div class=\"clearfix\"></div>\n        <div class=\"list-overflow-auto\" style=\"padding-top: 0; margin-top: 0;\">\n            <p data-bind=\"html: ReportDescription, visible: ReportDescription\"></p>\n            <div data-bind=\"with: ReportResult\" class=\"small\">\n                <div data-bind=\"visible: !ReportData()\">\n                    <div class=\"report-spinner\"></div>\n                </div>\n                <!-- ko if: !$parent._isPlaceholder -->\n                <div data-bind=\"template: 'report-template', data: $data\"></div>\n                <!-- /ko -->\n            </div>\n        </div>\n        <!-- ko if: !$data._isPlaceholder -->\n        <div class=\"form-inline\" data-bind=\"visible: !_hidePager\">\n            <div class=\"small\" data-bind=\"with: pager\">\n                <div class=\"form-group float-start total-records\" data-bind=\"if: totalRecords()>1 && $parent.ReportType() != 'Single'\">\n                    <span data-bind=\"text: 'Total Records: ' + totalRecords()\"></span><br />\n                </div>\n                <div class=\"form-group float-end\" data-bind=\"if: pages()>1 && $parent.ReportType() != 'Single'\">\n                    <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                </div>\n            </div>\n        </div>\n        <!-- /ko -->\n    </div>\n</script>\n\n\n<script type=\"text/html\" id=\"report-template\">\n    <div class=\"report-chart\" data-bind=\"attr: {id: 'chart_div_' + $parent.ReportID()}, visible: $parent.isChart\"></div>\n    <!-- ko if: $parent.ReportType() == 'Pivot' -->\n    <div data-bind=\"template: {name: 'report-pivot', data: $data }\"></div>\n    <!-- /ko -->\n\n    <!-- ko if: $parent.ReportType() == 'Html' -->\n    <div data-bind=\"template: {name: 'report-render', data: $data }\"></div>\n    <!-- /ko -->\n\n    <!-- ko if: $parent.ReportType() != 'Pivot' && $parent.ReportType() != 'Html' && (!$parent.isChart() || $parent.ShowDataWithGraph()) -->\n    <div class=\"float-end\" data-bind=\"if: $parent.OuterGroupColumns().length > 0\">\n        <a href=\"#\" data-bs-toggle=\"dropdown\" aria-haspopup=\"false\" aria-expanded=\"false\">\n            Manage Groups <span class=\"fa fa-ellipsis-v\"></span>\n        </a>\n        <ul class=\"dropdown-menu\" style=\"z-index: 1001;\" data-bind=\"foreach: $parent.OuterGroupColumns\">\n            <li class=\"dropdown-item small\">\n                <a href=\"#\" data-bind=\"click: remove\" title=\"Remove from Group\">\n                    <span class=\"fa fa-close\"></span> <span data-bind=\"text: fieldName\"></span>\n                </a>\n            </li>\n        </ul>\n    </div>\n    <div class=\"clear-fix\"></div>\n\n    <div data-bind=\"foreach: outerGroupData\">\n        <!-- ko if: rows.length > 0 || ($parent.outerGroupData && $parent.outerGroupData().length == 1) -->\n        <br />\n        <h6 style=\"font-weight: normal;\" data-bind=\"html: display\"></h6>\n        <div class=\"\" style=\"padding-top: 5px;\"></div>\n\n        <!-- ko if: $parents[1].ReportType() != 'Single'-->\n        <div data-bind=\"template: {name: 'report-table', data: $parent.ReportData }\"></div>\n        <!-- /ko -->\n        <!-- ko if: $parents[1].ReportType() == 'Single'-->\n        <div data-bind=\"template: {name: 'report-widget', data: $parent.ReportData }\"></div>\n        <!-- /ko -->\n        <!-- /ko -->\n    </div>\n    <!-- ko if: SubTotals().length > 0 && $parent.hasOuterGroupFields() && $parent.IncludeSubTotal() && $parent.totalRowFormat() == 'row' -->\n    <table class=\"table table-bordered table-sm mt-0\" style=\"border-top: 2px double #dee2e6; margin-bottom: 5px;\">\n         <thead>\n            <tr>\n                <th data-bind=\"attr: { colspan: SubTotals()[0].Items.length }\">Grand Total</th>                        \n            </tr>\n        </thead>\n        <tbody></tbody>\n            <tr>\n                <!-- ko if: $parent.canDrilldown() -->\n                <td style=\"width: 30px;\"></td>\n                <!-- /ko -->\n                <!-- ko foreach: SubTotals()[0].Items -->\n                <!-- ko if: _showInTotalRow != false -->\n                 <td data-bind=\"text: (Column.fieldLabel() || Column.ColumnName) + ' (' + _aggregate + ')'\"></td>\n                <!-- /ko -->\n                <!-- /ko -->\n            </tr>\n        \n            <tr class=\"sub-total\">\n                <!-- ko if: $parent.canDrilldown() -->\n                <td style=\"width: 30px;\"></td>\n                <!-- /ko -->\n                <!-- ko foreach: SubTotals()[0].Items -->\n                <!-- ko if: _showInTotalRow != false -->\n                <td data-bind=\"style: {'text-align': Column.IsNumeric ? 'right' : 'left', 'font-weight': 'bold'}\">\n                    <div data-bind=\"style: {'width': Column.fieldWidth}\">                        \n                        <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>                        \n                    </div>\n                </td>\n                <!-- /ko -->\n                <!-- /ko -->\n            </tr>\n        </tbody>\n    </table>\n    <!-- /ko -->\n    <!-- Grand Total: Table mode — Field/Total summary table -->\n    <!-- ko if: SubTotals().length > 0 && $parent.hasOuterGroupFields() && $parent.IncludeSubTotal() && $parent.totalRowFormat() != 'row' -->\n    <div class=\"mt-3\">\n        <!-- ko if: $parent.subTotalPerGroup() --><strong>Grand Total</strong><!-- /ko -->\n        <!-- ko ifnot: $parent.subTotalPerGroup() --><strong>Total</strong><!-- /ko -->\n        <table class=\"table table-bordered table-sm mt-2\" style=\"max-width: 450px;\">\n            <thead>\n                <tr>\n                    <th>Field</th>\n                    <th class=\"text-end\">Total</th>\n                </tr>\n            </thead>\n            <tbody>\n                <!-- ko foreach: SubTotals()[0].Items -->\n                <!-- ko if: _showInTotalRow != false && Value != 'NA' && Value != 'NaN' -->\n                <tr>\n                    <td data-bind=\"text: (Column.fieldLabel() || Column.ColumnName) + ' (' + _aggregate + ')'\"></td>\n                    <td class=\"text-end\">\n                        <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n                    </td>\n                </tr>\n                <!-- /ko -->\n                <!-- /ko -->\n            </tbody>\n        </table>\n    </div>\n    <!-- /ko -->\n    <!-- /ko -->\n</script>\n<script type=\"text/html\" id=\"admin-mode-template\">\n    <div class=\"row\">\n        <div class=\"d-flex justify-content-end align-items-center\" style=\"gap: 10px;\">\n            <div data-bind=\"visible: adminMode\">\n                <div class=\"alert alert-info d-inline-block\" style=\"font-size: 10pt; padding: 5px; max-width: 350px; white-space: normal; margin-bottom: 0;\">\n                    <i class=\"fa fa-user-circle\"></i> You can manage Reports/Dashboards for all users\n                </div>\n            </div>\n            <div data-bind=\"visible: adminMode\">\n                <div class=\"alert alert-info d-inline-block\" style=\"font-size: 10pt; padding: 5px; max-width: 350px; white-space: normal; margin-bottom: 0;\" title=\"Logged in user\">\n                    <i class=\"fa fa-id-badge\"></i>\n                    <span data-bind=\"text: currentUserName || currentUserId || 'Unknown User'\"></span>\n                    <!-- ko if: currentUserRole -->\n                    <span class=\"bubble-badge-separator\">|</span>\n                    Roles: <span data-bind=\"text: currentUserRole\"></span>\n                    <!-- /ko -->\n                    <!-- ko if: clientId -->\n                    <span class=\"bubble-badge-separator\">|</span>\n                    Client: <span data-bind=\"text: clientId\"></span>\n                    <!-- /ko -->\n                </div>\n            </div>\n            <div class=\"d-flex align-items-center\">\n                <div class=\"bubble-badge\">\n                    Admin Mode\n                    <div class=\"form-check form-switch ms-2\">\n                        <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: adminMode\">\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"manage-access-template\">\n    <h5><span class=\"fa fa-key\"></span>Manage Access</h5>\n    <div class=\"panel panel-default panel-body\" style=\"margin-left: 20px;\">\n\n        <div class=\"form-group row\">\n            <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"text: ($root.clientIdLabelText ? $root.clientIdLabelText() : 'Client Id') + ' to Restrict Access'\"></label>\n            <div class=\"col-md-6 col-sm-6\">\n                <!-- ko if: $root.clientIdOptions && $root.clientIdOptions().length > 0 -->\n                <select class=\"form-select form-select-sm\"\n                        data-bind=\"options: $root.clientIdOptions().filter(function(c){ return selectedClientIds().indexOf(c.id) < 0; }),\n                            optionsText: 'text', optionsValue: 'id', optionsCaption: 'Add to restrict access',\n                            value: clientIdToAdd, event: { change: function(){ addClientId(clientIdToAdd()); } }\"></select>\n                <!-- ko if: selectedClientIds().length > 0 -->\n                <div class=\"d-flex flex-wrap gap-1 mt-2\">\n                    <!-- ko foreach: selectedClientIds() -->\n                    <span class=\"badge bg-secondary d-inline-flex align-items-center\">\n                        <span data-bind=\"text: (function(){ var m = _.find($root.clientIdOptions(), function(c){ return c.id == $data; }); return m ? m.text : $data; })()\"></span>\n                        <button type=\"button\" class=\"btn btn-sm btn-link text-white p-0 ms-2 lh-1\" title=\"Remove\" data-bind=\"click: function(){ $parent.removeClientId($data); }\"><i class=\"fa fa-times\"></i></button>\n                    </span>\n                    <!-- /ko -->\n                </div>\n                <!-- /ko -->\n                <div class=\"form-text\" data-bind=\"visible: selectedClientIds().length === 0\">Not restricted, available to all.</div>\n                <!-- /ko -->\n                <!-- ko ifnot: $root.clientIdOptions && $root.clientIdOptions().length > 0 -->\n                <input class=\"form-control text-box single-line\" type=\"text\" placeholder=\"Comma separated, leave blank for all\" data-bind=\"value: clientId\">\n                <!-- ko if: selectedClientIds().length > 0 -->\n                <div class=\"d-flex flex-wrap gap-1 mt-2\">\n                    <!-- ko foreach: selectedClientIds() -->\n                    <span class=\"badge bg-secondary d-inline-flex align-items-center\">\n                        <span data-bind=\"text: $data\"></span>\n                        <button type=\"button\" class=\"btn btn-sm btn-link text-white p-0 ms-2 lh-1\" title=\"Remove\" data-bind=\"click: function(){ $parent.removeClientId($data); }\"><i class=\"fa fa-times\"></i></button>\n                    </span>\n                    <!-- /ko -->\n                </div>\n                <!-- /ko -->\n                <div class=\"form-text\" data-bind=\"visible: selectedClientIds().length === 0\">Not restricted, available to all.</div>\n                <!-- /ko -->\n            </div>\n            <div class=\"col-md-1 col-sm-1\">\n                <span data-bs-toggle=\"tooltip\" data-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"Leave blank to give Global access\"></span>\n            </div>\n        </div>\n        <div class=\"alert alert-info\">\n            <span class=\"fas fa-lightbulb fa-2x\"></span>&nbsp;User level rights override Role level rights. No selection for a rule implies report is available to all.\n        </div>\n\n        <div class=\"row small\">\n            <div class=\"col-md-6\">\n                <span class=\"clickable\" data-bind=\"click: toggleManageUsers\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showManageUsers(), 'fa-chevron-right': !showManageUsers() }\"></i> <b>Manage by User</b> (allow edit)</span>\n                <div data-bind=\"template: { name: 'access-selected-pills', data: { list: users, open: showManageUsers } }\"></div>\n                <div class=\"row container-fluid\" data-bind=\"visible: showManageUsers\">\n                    <!-- ko if: groupedUsers().length > 0 -->\n                    <!-- ko foreach: groupedUsers -->\n                    <div class=\"col-md-12\">\n                      <div class=\"category-header\" style=\"cursor: pointer;\" data-bind=\"click: function() { show(!show()); }\">\n                        <i class=\"fa toggle-icon\" data-bind=\"css: { 'fa-chevron-down': show(), 'fa-chevron-right': !show() }\"></i>\n                        <strong data-bind=\"text: category\"></strong>\n                      </div>\n                      <div class=\"row container-fluid\" data-bind=\"visible: show\">\n                        <!-- ko foreach: users -->\n                        <div class=\"float-start\">\n                          <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                              <input type=\"checkbox\" data-bind=\"checked: selected\"> &nbsp; <span data-bind=\"text: text\"></span>&nbsp; </label>\n                          </div>\n                        </div>\n                        <!-- /ko -->\n                      </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <!-- ko if: groupedUsers().length == 0 && users().length > 0 -->\n                    <!-- ko foreach: users -->\n                    <div class=\"float-start\">\n                        <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                                <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                            </label>\n                        </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <div data-bind=\"if: groupedUsers().length == 0 && users().length == 0\">\n                        Users list not populated or not applicable\n                    </div>\n                </div>\n                <br />\n                <span class=\"clickable\" data-bind=\"click: toggleViewUsers\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showViewUsers(), 'fa-chevron-right': !showViewUsers() }\"></i> <b>View only by User</b> (no edit/delete)</span>\n                <div data-bind=\"template: { name: 'access-selected-pills', data: { list: viewOnlyUsers, open: showViewUsers } }\"></div>\n                <div class=\"row container-fluid\" data-bind=\"visible: showViewUsers\">\n                    <!-- ko if: groupedViewOnlyUsers().length > 0 -->\n                    <!-- ko foreach: groupedViewOnlyUsers -->\n                    <div class=\"col-md-12\">\n                      <div class=\"category-header\" style=\"cursor: pointer;\" data-bind=\"click: function() { show(!show()); }\">\n                        <i class=\"fa toggle-icon\" data-bind=\"css: { 'fa-chevron-down': show(), 'fa-chevron-right': !show() }\"></i>\n                        <strong data-bind=\"text: category\"></strong>\n                      </div>\n                      <div class=\"row container-fluid\" data-bind=\"visible: show\">\n                        <!-- ko foreach: viewOnlyUsers -->\n                        <div class=\"float-start\">\n                          <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                              <input type=\"checkbox\" data-bind=\"checked: selected\"> &nbsp; <span data-bind=\"text: text\"></span>&nbsp; </label>\n                          </div>\n                        </div>\n                        <!-- /ko -->\n                      </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <!-- ko if: groupedViewOnlyUsers().length == 0 && viewOnlyUsers().length > 0 -->\n                    <!-- ko foreach: viewOnlyUsers -->\n                    <div class=\"float-start\">\n                        <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                                <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                            </label>\n                        </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <div data-bind=\"if: groupedViewOnlyUsers().length == 0 && viewOnlyUsers().length == 0\">\n                        Users list not populated or not applicable\n                    </div>\n                </div>\n                <br />\n                <div data-bind=\"ifnot: isDashboard\">\n                    <span class=\"clickable\" data-bind=\"click: toggleDeleteUsers\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showDeleteUsers(), 'fa-chevron-right': !showDeleteUsers() }\"></i> <b>Delete by User</b> (allow delete)</span>\n                    <div data-bind=\"template: { name: 'access-selected-pills', data: { list: deleteOnlyUsers, open: showDeleteUsers } }\"></div>\n                    <div class=\"row container-fluid\" data-bind=\"visible: showDeleteUsers\">\n                    <!-- ko if: groupedDeleteOnlyUsers().length > 0 -->\n                    <!-- ko foreach: groupedDeleteOnlyUsers -->\n                    <div class=\"col-md-12\">\n                      <div class=\"category-header\" style=\"cursor: pointer;\" data-bind=\"click: function() { show(!show()); }\">\n                        <i class=\"fa toggle-icon\" data-bind=\"css: { 'fa-chevron-down': show(), 'fa-chevron-right': !show() }\"></i>\n                        <strong data-bind=\"text: category\"></strong>\n                      </div>\n                      <div class=\"row container-fluid\" data-bind=\"visible: show\">\n                        <!-- ko foreach: deleteOnlyUsers -->\n                        <div class=\"float-start\">\n                          <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                              <input type=\"checkbox\" data-bind=\"checked: selected\"> &nbsp; <span data-bind=\"text: text\"></span>&nbsp; </label>\n                          </div>\n                        </div>\n                        <!-- /ko -->\n                      </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <!-- ko if: groupedDeleteOnlyUsers().length == 0 && deleteOnlyUsers().length > 0 -->\n                    <!-- ko foreach: deleteOnlyUsers -->\n                        <div class=\"float-start\">\n                            <div class=\"checkbox\">\n                                <label class=\"label label-info\">\n                                    <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                                </label>\n                            </div>\n                        </div>\n                        <!-- /ko -->\n                        <!-- /ko -->\n                        <div data-bind=\"if: groupedDeleteOnlyUsers().length == 0 && deleteOnlyUsers().length == 0\">\n                            Users list not populated or not applicable\n                        </div>\n                    </div>\n                    <br />\n                </div>\n            </div>\n            <div class=\"col-md-6\">\n                <span class=\"clickable\" data-bind=\"click: toggleManageRoles\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showManageRoles(), 'fa-chevron-right': !showManageRoles() }\"></i> <b>Manage by User Role</b> (allow edit)</span>\n                <div data-bind=\"template: { name: 'access-selected-pills', data: { list: userRoles, open: showManageRoles } }\"></div>\n                <div class=\"row container-fluid\" data-bind=\"visible: showManageRoles\">\n                    <!-- ko foreach: userRoles -->\n                    <div class=\"float-start\">\n                        <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                                <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                            </label>\n                        </div>\n                    </div>\n                    <!-- /ko -->\n                    <div data-bind=\"if: userRoles().length == 0\">\n                        User Roles list not populated or not applicable\n                    </div>\n                </div>\n                <br />\n                <span class=\"clickable\" data-bind=\"click: toggleViewRoles\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showViewRoles(), 'fa-chevron-right': !showViewRoles() }\"></i> <b>View only by User Role</b> (no edit/delete)</span>\n                <div data-bind=\"template: { name: 'access-selected-pills', data: { list: viewOnlyUserRoles, open: showViewRoles } }\"></div>\n                <div class=\"row container-fluid\" data-bind=\"visible: showViewRoles\">\n                    <!-- ko foreach: viewOnlyUserRoles -->\n                    <div class=\"float-start\">\n                        <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                                <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                            </label>\n                        </div>\n                    </div>\n                    <!-- /ko -->\n                    <div data-bind=\"if: viewOnlyUserRoles().length == 0\">\n                        User Roles list not populated or not applicable\n                    </div>\n                </div>\n                <div data-bind=\"ifnot: isDashboard\">\n                    <span class=\"clickable\" data-bind=\"click: toggleDeleteRoles\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showDeleteRoles(), 'fa-chevron-right': !showDeleteRoles() }\"></i> <b>Delete by User Role</b> (allow delete)</span>\n                    <div data-bind=\"template: { name: 'access-selected-pills', data: { list: deleteOnlyUserRoles, open: showDeleteRoles } }\"></div>\n                    <div class=\"row container-fluid\" data-bind=\"visible: showDeleteRoles\">\n                        <!-- ko foreach: deleteOnlyUserRoles -->\n                        <div class=\"float-start\">\n                            <div class=\"checkbox\">\n                                <label class=\"label label-info\">\n                                    <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                                </label>\n                            </div>\n                        </div>\n                        <!-- /ko -->\n                        <div data-bind=\"if: deleteOnlyUserRoles().length == 0\">\n                            User Roles list not populated or not applicable\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n\n<!-- Collapsed view of one access rule: who is selected, or that it is open to everyone. Hidden while the checkboxes are open. -->\n<script type=\"text/html\" id=\"access-selected-pills\">\n    <!-- ko ifnot: ko.unwrap(open) -->\n    <div class=\"d-flex flex-wrap gap-1 align-items-center my-1 ms-3\">\n        <!-- ko foreach: _.filter(list(), function (x) { return x.selected(); }) -->\n        <span class=\"badge bg-secondary d-inline-flex align-items-center\">\n            <span data-bind=\"text: text\"></span>\n            <button type=\"button\" class=\"btn btn-sm btn-link text-white p-0 ms-2 lh-1\" title=\"Remove\" data-bind=\"click: function(){ selected(false); }\"><i class=\"fa fa-times\"></i></button>\n        </span>\n        <!-- /ko -->\n        <span class=\"text-muted small\" data-bind=\"visible: !_.some(list(), function (x) { return x.selected(); })\"><i class=\"fa fa-globe\"></i> Everyone, not restricted</span>\n    </div>\n    <!-- /ko -->\n</script>\n<!-- Access summary badges for a report/folder/dashboard row (admin mode). Grey = restricted, outlined = open to all. -->\n<script type=\"text/html\" id=\"access-badges\">\n    <div class=\"d-flex flex-wrap gap-1 align-items-center\" data-bind=\"foreach: accessBadges($data, $root)\">\n        <span class=\"badge d-inline-flex align-items-center\" data-bind=\"attr: { title: title }, css: restricted ? 'bg-secondary' : 'bg-light text-muted border'\">\n            <!-- ko foreach: icons.split(' ') -->\n            <i class=\"fa me-1\" data-bind=\"css: $data\"></i>\n            <!-- /ko -->\n            <span data-bind=\"text: text\"></span>\n        </span>\n    </div>\n</script>\n<script type=\"text/html\" id=\"filter-group\">\n    <div class=\"query-builder form-inline\" data-bind=\"foreach: FilterGroups\">\n        <div class=\"rules-group-container\">\n            <div class=\"rules-group-header\" data-bind=\"attr: {parentdivid: generateUniqueId()}\">\n                <div data-bind=\"visible: !isRoot\">\n                    <div class=\"float-start\">\n                        <div class=\"btn-group btn-group-toggle btn-group-sm\" data-bs-toggle=\"buttons\" role=\"group\">\n                            <label class=\"btn btn-light active\" style=\"margin-right: 0px;\">\n                                <input type=\"radio\" data-bind=\"attr: { name: 'andOrGroup-' + $element.closest('.rules-group-header').getAttribute('parentdivid') }, checked: AndOr\" value=\"And\" /> And\n                            </label>\n                            <label class=\"btn btn-light active\">\n                                <input type=\"radio\" data-bind=\"attr: { name: 'andOrGroup-' + $element.closest('.rules-group-header').getAttribute('parentdivid') }, checked: AndOr\" value=\"Or\" /> Or\n                            </label>\n                        </div>\n                    </div>\n                    <div class=\"float-end\">\n                        <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parent.RemoveFilterGroup, visible: !isRoot\">Remove Group</button>&nbsp;\n                    </div>\n                </div>\n                <div data-bind=\"visible: isRoot\">\n                    <div class=\"float-start padded-div\">\n                        <label> &nbsp;Filter Conditions</label>\n                    </div>\n                </div>\n                <div class=\"clearfix\"></div>\n            </div>\n\n            <div class=\"rules-group-body\" data-bind=\"template: {name: 'filter-inner'}\"></div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"filter-details-summary\">\n    <!-- ko if: typeof ShowFilterDetails === 'function' && ShowFilterDetails() && typeof filterDetailsSummary === 'function' && filterDetailsSummary() -->\n    <div class=\"mb-2 py-1 small\" style=\"border-left: 3px solid #adb5bd; padding-left: 10px;\">\n        <i class=\"fa fa-filter\"></i>\n        <b>Filters:</b>\n        <span data-bind=\"html: filterDetailsSummary()\"></span>\n    </div>\n    <!-- /ko -->\n</script>\n\n<script type=\"text/html\" id=\"fly-filter-template\">\n    <div class=\"card\" data-bind=\"visible: FlyFilters().length>0 || DontExecuteOnRun\">\n        <div class=\"card-header\">\n            <a data-bs-toggle=\"collapse\" data-bind=\"attr: {'data-bs-target': '#filter-panel-' + ReportID() }\" href=\"#\">\n                <i class=\"fa fa-filter\"></i> Choose Filters\n            </a>\n        </div>\n        <div data-bind=\"attr: {id: 'filter-panel-' + ReportID() }, css: {collpased: !DontExecuteOnRun(), collapse: !DontExecuteOnRun()}\" class=\"card-body\">\n            <div>\n                <!-- ko foreach: FlyFilters -->\n                <div class=\"row\">\n                    <div class=\"col-sm-5 col-xs-4\">\n                        <div data-bind=\"with: Field\" class=\"checkbox\">\n                            <div class=\"checkbox\">\n                                <label>\n                                    <input type=\"checkbox\" title=\"Apply this filter\" data-bind=\"checked: $parent.Apply, disabled: forced\" /> <span data-bind=\"text: selectedFilterName\"></span>\n                                </label>\n                            </div>\n                        </div>\n                    </div>\n                    <div data-bind=\"with: Field\" class=\"col-sm-2 col-xs-3\">\n                        <div class=\"form-group\" data-bind=\"if: $parent.Apply\">\n                            <select class=\"form-select\" data-bind=\"options: fieldFilter, value: $parent.Operator\" required></select>\n                        </div>\n                    </div>\n                    <div data-bind=\"with: Field\" class=\"col-sm-5 col-xs-5\">\n                        <div data-bind=\"if: $parent.Apply\" data-parentprefix=\"F\" >\n                            <div data-bind=\"template: 'report-filter', data: $data\"></div>\n                        </div>\n                    </div>\n                </div>\n                <!-- /ko -->\n                <button class=\"btn btn-primary\" data-bind=\"click: ExecuteReport\">Run</button>\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"filter-inner\">\n    <div class=\"rules-list\">\n        <div class=\"rule-container\" data-bind=\"visible: Filters().length>0\">\n            <table class=\"table table-striped table-hover table-borderless\">\n                <thead>\n                    <tr>\n                        <th class=\"row\">\n                            <div class=\"col-md-1\"></div>\n                            <div class=\"col-md-4\">Field</div>\n                            <div class=\"col-md-2\"></div>\n                            <div class=\"col-md-4\">Filter</div>\n                            <div class=\"col-md-1\"></div>\n                        </th>\n                    </tr>\n                </thead>\n                <tbody data-bind=\"foreach: Filters\">\n                    <tr class=\"rule-container\">\n                        <td class=\"row\">\n                            <div class=\"col-md-1\">\n                                <select data-bind=\"value: AndOr, visible: $index()>0\" class=\"form-select\">\n                                    <option>And</option>\n                                    <option>Or</option>\n                                </select>\n                            </div>\n                            <div class=\"col-md-3\">\n                                <div class=\"form-group\">\n                                    <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"\n                                        options: $parents[$parents.length-2].selectedFieldsCanFilter != undefined\n                                                    ? $parents[$parents.length-2].selectedFieldsCanFilter\n                                                    : $parents[$parents.length-1].selectedFieldsCanFilter,\n                                        optionsText: 'selectedFieldName',\n                                        optionsCaption: 'Please Choose',\n                                        value: Field,\n                                        attr: {required: Field()==null?'required':false},\n                                        disable: Field() && Field().forced\"></select>\n                                </div>\n                            </div>\n                            <div class=\"col-md-2\">\n                                <div data-bind=\"with: Field\">\n                                    <div class=\"form-group\">\n                                        <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: fieldFilter, value: $parent.Operator\" required></select>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col-md-5\">\n                                <!-- ko ifnot: $data.useEmailListColumn && $data.useEmailListColumn() -->\n                                <div data-bind=\"with: Field\" data-parentprefix=\"M\">\n                                    <div data-bind=\"template: 'report-filter', data: $data\"></div>\n                                </div>\n                                <!-- /ko -->\n                                <!-- ko if: $root.scheduleEmailListColumns && $root.scheduleEmailListColumns().length > 0 -->\n                                <div class=\"form-check small mt-1\">\n                                    <label class=\"form-check-label text-muted\" title=\"Take this filter's value from the Email List query, one email per row\">\n                                        <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: useEmailListColumn\" /> Use value from Email List\n                                    </label>\n                                </div>\n                                <!-- ko if: $data.useEmailListColumn && $data.useEmailListColumn() -->\n                                <select class=\"form-select\" required data-bind=\"options: $root.scheduleEmailListColumns, optionsCaption: 'Choose Email List column...', value: EmailListColumn\"></select>\n                                <!-- /ko -->\n                                <!-- /ko -->\n                                <!-- ko if: Field() && Field().fieldType == 'DateTime' && Operator() == 'range' && $index()==0 -->\n                                <!-- ko if: $parents[$parents.length-2].canAddSeries != undefined && $parents[$parents.length-2].canAddSeries() -->\n                                <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parents[$parents.length-2].AddSeries.bind($data)\">Add Comparison</button>\n                                <!--/ko -->\n                                <!-- ko if: $parents[$parents.length-2].canAddSeries == undefined && $parentContext.$parent.canAddSeries != undefined && $parentContext.$parent.canAddSeries()-->\n                                <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parentContext.$parent.AddSeries.bind($data)\">Add Comparison</button>\n                                <!--/ko -->\n                                <!--/ko -->\n                                <span data-bind=\"visible: Field() && Field().forced\" class=\"badge bg-info\">Required Filter</span>\n                            </div>\n                            <div class=\"col-md-1\">\n                                <div style=\"display: flex; align-items: left;\">\n                                    <div class=\"form-group\" >\n                                        <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parent.RemoveFilter, hidden: Field() && Field().forced\" title=\"Remove\">\n                                            <i class=\"fa fa-trash\"></i>\n                                        </button>\n                                    </div>\n                                    <div class=\"form-group\" data-bind=\"with: Field, hidden: document.querySelector('#filter-panel.card-body.collapse') || ($root.scheduleFilterEditing && $root.scheduleFilterEditing())\">\n                                        <span class=\"btn btn-sm\" tabindex=\"0\" data-bind=\"click: function(){ filterOnFly(!filterOnFly()); }, css: {'btn-success': filterOnFly()==true, 'btn-secondary': !filterOnFly()}\">\n                                            <span class=\"fa fa-filter\" aria-hidden=\"true\" title=\"Filter on Report\"></span>\n                                        </span>\n                                    </div>\n                                </div>\n\n                            </div>\n                        </td>\n                    </tr>\n                    <!-- ko foreach: compareTo -->\n                    <tr>\n                        <td class=\"row\">\n                            <div class=\"col-md-6\">&nbsp;</div>\n                            <div class=\"col-md-2\">\n                                <span style=\"text-align: right\"><button class=\"btn btn-sm\" data-bind=\"click: $parents[2].RemoveSeries\"><span class=\"fa fa-trash\"></span></button></span>\n                                <span class=\"muted\">Compare to</span>\n                            </div>\n                            <div class=\"col-md-4\">\n                                <select class=\"form-select\" data-bind=\"options: Range, value: Value\" required></select>\n                            </div>\n                        </td>\n                    </tr>\n                    <!-- /ko -->\n                </tbody>\n            </table>\n        </div>\n\n        <div class=\"rule-container\">\n            <div data-bind=\"template: {name: 'filter-group'}\"></div>\n            <div>\n                <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: AddFilter\">Add Filter</button>\n                <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: AddFilterGroup\">Add Filter Group</button>\n            </div>\n        </div>\n    </div>\n\n</script>\n\n            <script type=\"text/html\" id=\"filter-parameters\">\n                <div class=\"table-responsive\">\n                        <span data-bind=\"hidden: showParameters\">No filters available to choose</span>\n                        <table class=\"table table-striped table-hover table-borderless\" data-bind=\"visible: showParameters\">\n                                <thead>\n                                        <tr>\n                                                <th style=\"width: 30%\">Filter</th>\n                                                <th style=\"width: 20%\"></th>\n                                                <th style=\"width: 30%\">Value</th>\n                                                <th style=\"width: 10%\"></th>\n                                        </tr>\n                                </thead>\n                                <tbody data-bind=\"foreach: Parameters\">\n                                        <tr data-bind=\"ifnot: Hidden\">\n                                                <td data-bind=\"text: DisplayName\"></td>\n                                                <td>\n                                                        <div class=\"form-group\">\n                                                                <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: operators, value: Operator\" required></select>\n                                                        </div>\n                                                </td>\n                                                <td data-bind=\"with: Field\" data-parentprefix=\"P\">\n                                                        <div data-bind=\"template: 'report-filter', data: $data\"></div>\n                                                </td>\n                                                <!-- CHANGED: was empty <td></td>, now has the fly-filter toggle -->\n                                                <td class=\"text-center\">\n                                                        <span class=\"btn btn-sm\" tabindex=\"0\"\n                                                            data-bind=\"click: function(){ filterOnFly(!filterOnFly()); },\n                                                                             css: {'btn-success': filterOnFly()==true, 'btn-secondary': !filterOnFly()}\">\n                                                                <span class=\"fa fa-filter\" aria-hidden=\"true\" title=\"Filter on Report\"></span>\n                                                        </span>\n                                                </td>\n                                        </tr>\n\n                                </tbody>\n                        </table>\n                </div>\n            </script>\n\n<script type=\"text/html\" id=\"report-schedule\">\n    <div data-bind=\"with: scheduleBuilder\" id=\"schedule-builder-div\">\n        <div class=\"form-check\">\n            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: hasSchedule\" id=\"scheduleReportCheckbox\">\n            <label class=\"form-check-label\" for=\"scheduleReportCheckbox\">\n                Set Schedule to send by Email\n            </label>\n        </div>\n        <div data-bind=\"if: hasSchedule\">\n            <div class=\"d-flex align-items-center\">\n                <div class=\"me-3 d-flex align-items-center\">\n                    <span data-bind=\"text: selectedOption() != 'once' ? 'Every ' : ''\"></span>&nbsp;\n                    <select class=\"form-select\" required data-bind=\"options: options, value: selectedOption\" style=\"min-width: 80px;\"></select>\n                </div>\n                <div data-bind=\"if: selectedOption() == 'once'\" class=\"me-3 d-flex align-items-center\">\n                    &nbsp;on&nbsp;<input data-bind=\"datepicker: selectedDate, datepickerOptions: {value: selectedDate}\" class=\"form-control\" required />\n                </div>\n                <div class=\"d-flex align-items-center\">\n                    <div data-bind=\"if: showDays\" class=\"d-flex align-items-center\">\n                        &nbsp;on&nbsp;\n                        <select multiple class=\"form-select ms-2\" required data-bind=\"select2: { placeholder: 'Choose Days', allowClear: true }, options: days, selectedOptions: selectedDays\"></select>\n                    </div>\n                    <div data-bind=\"if: showDates\" class=\"d-flex align-items-center\">\n                        &nbsp;on&nbsp;\n                        <select multiple class=\"form-select\" required data-bind=\"select2: { placeholder: 'Choose Dates', allowClear: true }, options: dates, selectedOptions: selectedDates\"></select>\n                    </div>\n                    <div data-bind=\"if: showMonths\" class=\"d-flex align-items-center\">\n                        &nbsp;on&nbsp;\n                        <select multiple class=\"form-select\" required data-bind=\"select2: { placeholder: 'Choose Months', allowClear: true }, options: months, selectedOptions: selectedMonths\"></select>\n                    </div>\n                    <div data-bind=\"if: showAtTime\" class=\"d-flex align-items-center ms-3\">\n                        &nbsp;at&nbsp;\n                        <select class=\"form-select me-2\" style=\"min-width: 60px;\" data-bind=\"options: hours, value: selectedHour\"></select>\n                        <select class=\"form-select me-2\" style=\"min-width: 60px;\" data-bind=\"options: minutes, value: selectedMinute\"></select>\n                        <select class=\"form-select\" style=\"min-width: 80px;\" data-bind=\"value: selectedAmPm\">\n                            <option>AM</option>\n                            <option>PM</option>\n                        </select>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"alert alert-info\">\n                Report will be run and emailed <span data-bind=\"text: selectedOption() != 'once' ? 'every' : ''\"></span> <span data-bind=\"text: selectedOption\"></span>\n                <span data-bind=\"if: selectedOption() == 'once'\">\n                    on <span class=\"error\" data-bind=\"visible: !selectedDate()\">Please pick a Date</span> <span data-bind=\"text: selectedDate\"></span>\n                </span>\n                <span data-bind=\"if: showDays\">\n                    on <span class=\"error\" data-bind=\"visible: selectedDays().length == 0\">Please pick Day(s)</span> <span data-bind=\"text: selectedDays\"></span>\n                </span>\n                <span data-bind=\"if: showDates\">\n                    on <span class=\"error\" data-bind=\"visible: selectedDates().length == 0\">Please pick Date(s)</span>\n                    <span data-bind=\"foreach: selectedDates\"><span data-bind=\"visible: $index()>0\">, </span><span data-bind=\"text: $data == 1 ? '1st': ($data == 2 ? '2nd' : ($data == 3 ? '3rd' : ($data == 31 ? '31st' : $data+'th')))\"></span></span>\n                </span>\n                <span data-bind=\"if: showMonths\">\n                    of <span class=\"error\" data-bind=\"visible: selectedMonths().length == 0\">Please pick Month(s)</span> <span data-bind=\"text: selectedMonths\"></span>\n                </span>\n                <span data-bind=\"if: showAtTime\">\n                    at <span data-bind=\"text: selectedHour\"></span>:<span data-bind=\"text: selectedMinute\"></span> <span data-bind=\"text: selectedAmPm\"></span>\n                </span>\n            </div>\n            <div class=\"mb-3\">\n                <div class=\"row g-2 align-items-center\">\n                    <div class=\"col-12 col-sm-3\">\n                        <label class=\"col-form-label pb-0\">Email to</label>\n                        <div class=\"form-check small\">\n                            <label class=\"form-check-label text-muted\" title=\"Send to a saved Email List instead of typing addresses\">\n                                <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: useEmailQuery\" />\n                                Email List\n                            </label>\n                        </div>\n                    </div>\n\n                    <div class=\"col-12 col-sm-6\">\n                        <!-- ko ifnot: useEmailQuery -->\n                        <input type=\"text\" class=\"form-control\"\n                               data-bind=\"value: emailTo\"\n                               placeholder=\"Enter Email Addresses separated by comma\" />\n                        <!-- /ko -->\n                        <!-- ko if: useEmailQuery -->\n                        <div class=\"d-flex align-items-center gap-2\">\n                            <select class=\"form-select\" data-bind=\"options: emailQueries, optionsText: 'name', optionsValue: 'id', value: emailQueryId, optionsCaption: 'Choose Email List...'\"></select>\n                            <button type=\"button\" class=\"btn btn-light btn-sm text-nowrap\"\n                                    data-bind=\"click: previewRecipients, enable: emailQueryId() > 0\"\n                                    title=\"Show who this Email List currently returns\">View</button>\n                        </div>\n                        <!-- /ko -->\n                    </div>\n\n                    <label class=\"col-6 col-sm-1 col-form-label\">Format</label>\n\n                    <div class=\"col-6 col-sm-2\">\n                        <select class=\"form-select\" data-bind=\"value: format,event: { change: onFormatChange }\">\n                            <option value=\"EXCEL\">Excel</option>\n                            <option data-bind=\"visible: $parent.canDrilldown && $parent.canDrilldown()\" value=\"EXCEL-SUB\">Excel (Expanded)</option>\n                            <option value=\"CSV\">CSV</option>\n                            <option value=\"PDF\">PDF</option>\n                            <option value=\"WORD\">Word</option>\n                            <option value=\"LINK\">Link</option>\n                        </select>\n                    </div>\n                </div>\n            </div>\n            <div class=\"mb-3\">\n                <div class=\"row g-2 align-items-center\">\n                    <label class=\"col-12 col-sm-3 col-form-label\">Pick Time Zone</label>\n\n                    <div class=\"col-12 col-sm-9\">\n                        <select class=\"form-select\"\n                                data-bind=\"options: timezonOption,\n                                           optionsText: 'displayName',\n                                           optionsValue: 'timeZoneId',\n                                           value: selectedTimezone,\n                                           select2: {dropdownParent: $element.closest('.modal'), allowClear: true, placeholder: 'Set a time zone'}\">\n                        </select>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"mb-3\">\n                <div class=\"row g-2\">\n                    <div class=\"col-6 col-sm-3\">\n                        <div class=\"form-check\" title=\"Set a date to start sending scheduled report\">\n                            <input class=\"form-check-input\" type=\"checkbox\"\n                                   data-bind=\"checked: hasScheduleStart\"\n                                   id=\"scheduleStartCheckbox\">\n                            <label class=\"form-check-label\" for=\"scheduleStartCheckbox\">\n                                Schedule Start Date\n                            </label>\n                        </div>\n                    </div>\n\n                    <div class=\"col-6 col-sm-4\" data-bind=\"if: hasScheduleStart\">\n                        <input type=\"text\" class=\"form-control\"\n                               data-bind=\"datepicker: scheduleStart, datepickerOptions: {value: scheduleStart}\"\n                               title=\"Scheduled Report will not be sent before this date\"\n                               required />\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"mb-3\">\n                <div class=\"row g-2\">\n                    <div class=\"col-6 col-sm-3\">\n                        <div class=\"form-check\"  title=\"Set a date to stop sending scheduled report\">\n                            <input class=\"form-check-input\" type=\"checkbox\"\n                                   data-bind=\"checked: hasScheduleEnd\"\n                                   id=\"scheduleEndCheckbox\">\n                            <label class=\"form-check-label\" for=\"scheduleEndCheckbox\">\n                                Schedule End Date\n                            </label>\n                        </div>\n                    </div>\n\n                    <div class=\"col-6 col-sm-4\" data-bind=\"if: hasScheduleEnd\">\n                        <input type=\"text\" class=\"form-control\"\n                               data-bind=\"datepicker: scheduleEnd, datepickerOptions: {value: scheduleEnd}\"\n                               title=\"Scheduled Report will not be sent after this date\"\n                               required />\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n\n</script>\n\n<script type=\"text/html\" id=\"report-field-options\">\n    <div class=\"modal-dialog\" style=\"max-width: 750px;\">\n        <div class=\"modal-content\" data-bind=\"with: editFieldOptions\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\"><span data-bind=\"text: fieldName\"></span> - Setup Additional Field Options</h5>\n            </div>\n            <div class=\"modal-body needs-validation\">\n                <div class=\"card card-body\">\n                    <b>Column Format Settings</b>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pick Data Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" data-bind=\"options: ['Days', 'Hours', 'Minutes', 'Seconds'].indexOf(fieldFormat()) >= 0 ? ['Days', 'Hours', 'Minutes', 'Seconds'] : $parents[1].fieldFormatTypes, value: fieldFormat\"></select>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: $parents[1].decimalFormatTypes.indexOf($data.fieldFormat())>=0\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pick Decimal Places</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"number\" class=\"form-control\" data-bind=\"value: decimalPlaces\" placeholder=\"\" />\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: fieldFormat()=='Currency'\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pick Currency Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" required data-bind=\"options: $parents[1].currencyFormats, optionsText: 'display',optionsValue: 'value', value: currencyFormat\"></select>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: fieldFormat()=='Date'\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pick Date Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" data-bind=\"options: $parents[1].dateFormats, value: dateFormat\"></select>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible:selectedAggregate()=='Pivot' && fieldFormat()=='Date'\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pivot Drilldown Date Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" data-bind=\"options: ['', 'Day', 'Month', 'Year', 'Month/Year'], value: drillDataFormat\"></select>\n                        </div>\n                    </div>\n\n                    <div class=\"form-group row\" data-bind=\"visible: fieldFormat()=='Date' && dateFormat()==='Custom'\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Enter Custom Date Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                        <div class=\"input-group\">\n                                <input type=\"text\" class=\"form-control\" data-bind=\"value: customDateFormat\" placeholder=\"dd/MM/yyyy\" />\n                                <button type=\"button\" class=\"btn btn-outline-secondary\" tabindex=\"-1\"\n                                  data-bind=\"bsPopover: { \n                                    trigger: 'focus', \n                                    placement: 'bottom', \n                                    html: true, \n                                    title: 'Date Format Tokens', \n                                    content:$root.dateFormatPopoverContent \n                                  }\">\n                                  <i class=\"fa fa-question-circle\"></i>\n                                </button>\n                            </div>\n                    </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Choose Column Label</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" data-bind=\"value: fieldLabel\" />\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Inner Column Label</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" data-bind=\"value: fieldLabel2\" />\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Choose Text Alignment</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" data-bind=\"options: $parents[1].fieldAlignments, value: fieldAlign\"></select>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Choose Width (leave blank for auto)</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" data-bind=\"value: fieldWidth\" />\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <div class=\"col-sm-12\">\n                            <div class=\"checkbox float-start\" >\n                                <label>\n                                    <input type=\"checkbox\" data-bind=\"checked: outerGroup\" />\n                                    <b>Outer Group</b> - Use this field as a group heading\n                                </label>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: $parents[1].IncludeSubTotal()\">\n                        <div class=\"col-sm-12 d-flex align-items-center\">\n                            <div class=\"checkbox\">\n                                <label>\n                                    <input type=\"checkbox\" data-bind=\"checked: dontSubTotal\" />\n                                    <b>Don't Show In Total Row</b>\n                                </label>\n                            </div>\n                            <button class=\"btn btn-sm btn-secondary ms-2\" title=\"Apply to all columns\" data-bind=\"click: function(){ applyAllDontSubTotal(!applyAllDontSubTotal()); }\">\n                                <span class=\"fa\" data-bind=\"css: applyAllDontSubTotal() ? 'fa-check' : 'fa-paste'\"></span>\n                            </button>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: $parents[1].IncludeSubTotal() && !dontSubTotal()\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Total Row Aggregate</label>\n                        <div class=\"col-sm-7 col-md-7 d-flex align-items-center\">\n                            <select class=\"form-select\" data-bind=\"options: totalRowAggregateOptions, value: totalRowAggregate\"></select>\n                            <button class=\"btn btn-sm btn-secondary ms-2\" title=\"Apply to all columns\" data-bind=\"click: function(){ applyAllTotalRowAggregate(!applyAllTotalRowAggregate()); }\">\n                                <span class=\"fa\" data-bind=\"css: applyAllTotalRowAggregate() ? 'fa-check' : 'fa-paste'\"></span>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n                <br />\n                <div data-bind=\"visible:$parent.ReportType() !='Html'\">\n                <div class=\"card card-body\">\n                    <div class=\"form-row align-items-center\">\n                        <div class=\"col-auto\">\n                            <b>Header Settings</b>\n                        </div>\n                    </div>\n                    <div class=\"row mb-3\">\n                        <div class=\"col\">\n                            <div class=\"mb-3\">\n                                <label class=\"form-label\">Pick Text Color</label>\n                                <div class=\"d-flex\">\n                                    <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: headerFontColor\" />\n                                    <input type=\"text\" style=\"width: 100px\" class=\"form-control me-2\" data-bind=\"value: headerFontColor\" />\n                                    <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllHeaderFontColor(!applyAllHeaderFontColor()); }\">\n                                        <span class=\"fa\" data-bind=\"css: applyAllHeaderFontColor() ? 'fa-check' : 'fa-paste'\"></span>\n                                    </button>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col\">\n                            <div class=\"mb-3\">\n                                <label class=\"form-label\">Pick Background Color</label>\n                                <div class=\"d-flex\">\n                                    <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: headerBackColor\" />\n                                    <input type=\"text\" style=\"width: 100px\" class=\"form-control me-2\" data-bind=\"value: headerBackColor\" />\n                                    <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllHeaderBackColor(!applyAllHeaderBackColor()); }\">\n                                        <span class=\"fa\" data-bind=\"css: applyAllHeaderBackColor() ? 'fa-check' : 'fa-paste'\"></span>\n                                    </button>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col d-flex align-items-center\">\n                            <div class=\"form-check me-3\">\n                                <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: headerFontBold\" id=\"headerFontBoldCheckbox\">\n                                <label class=\"form-check-label\" for=\"headerFontBoldCheckbox\">\n                                    Bold Text\n                                </label>\n                            </div>\n                            <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllHeaderBold(!applyAllHeaderBold()); }\">\n                                <span class=\"fa\" data-bind=\"css: applyAllHeaderBold() ? 'fa-check' : 'fa-paste'\"></span>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n                <br />\n                </div>\n                <div class=\"card card-body\">\n                    <div class=\"form-row align-items-center\">\n                        <div class=\"col-auto\">\n                            <b>Text Settings</b>\n                        </div>\n                    </div>\n                    <div class=\"row mb-3\">\n                        <div class=\"col\">\n                            <div class=\"mb-3\">\n                                <label class=\"form-label\">Pick Text Color</label>\n                                <div class=\"d-flex\">\n                                    <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: fontColor\" />\n                                    <input type=\"text\" style=\"width: 100px;\" class=\"form-control me-2\" data-bind=\"value: fontColor\" />\n                                    <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllFontColor(!applyAllFontColor()); }\">\n                                        <span class=\"fa\" data-bind=\"css: applyAllFontColor() ? 'fa-check' : 'fa-paste'\"></span>\n                                    </button>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col\">\n                            <div class=\"mb-3\">\n                                <label class=\"form-label\">Pick Background Color</label>\n                                <div class=\"d-flex\">\n                                    <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: backColor\" />\n                                    <input type=\"text\" style=\"width: 100px;\" class=\"form-control me-2\" data-bind=\"value: backColor\" />\n                                    <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllBackColor(!applyAllBackColor()); }\">\n                                        <span class=\"fa\" data-bind=\"css: applyAllBackColor() ? 'fa-check' : 'fa-paste'\"></span>\n                                    </button>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col d-flex align-items-center\">\n                            <div class=\"form-check me-3\">\n                                <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: fontBold\" id=\"fontBoldCheckbox\">\n                                <label class=\"form-check-label\" for=\"fontBoldCheckbox\">\n                                    Bold Text\n                                </label>\n                            </div>\n                            <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllBold(!applyAllBold()); }\">\n                                <span class=\"fa\" data-bind=\"css: applyAllBold() ? 'fa-check' : 'fa-paste'\"></span>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n                <div class=\"padded-div\">\n                    <button class=\"btn btn-sm btn-primary\" data-bind=\"click: function() {addConditionalFormatSetting(null)}\">Add Conditional Formatting</button>\n                </div>\n                <div data-bind=\"foreach: fieldCondtionalFormats\" style=\"padding-left: 40px;\">\n                    <div class=\"card card-body\">\n                        <div class=\"row m-2\">\n                            <div class=\"col d-flex justify-content-start\">\n                                <b>Conditional Format #<span data-bind=\"text: $index()+1\"></span></b>\n                            </div>\n                            <div class=\"col d-flex justify-content-end\">\n                                <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parent.removeSetting\">Remove</button>\n                            </div>\n                        </div>\n                        <div class=\"row mb-3\">\n                            <div class=\"col\">\n                                <div class=\"mb-3\">\n                                    <label class=\"form-label\">Pick Text Color</label>\n                                    <div class=\"d-flex\">\n                                        <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: fontColor\" />\n                                        <input type=\"text\" style=\"width: 100px;\" class=\"form-control me-2\" data-bind=\"value: fontColor\" />\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col\">\n                                <div class=\"mb-3\">\n                                    <label class=\"form-label\">Pick Background Color</label>\n                                    <div class=\"d-flex\">\n                                        <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: backColor\" />\n                                        <input type=\"text\" style=\"width: 100px;\" class=\"form-control me-2\" data-bind=\"value: backColor\" />\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col d-flex align-items-center\">\n                                <div class=\"form-check me-3\">\n                                    <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: fontBold\" id=\"fontBoldCheckbox\">\n                                    <label class=\"form-check-label\" for=\"fontBoldCheckbox\">\n                                        Bold Text\n                                    </label>\n                                </div>\n                            </div>\n                        </div>\n\n                        <div class=\"row m-2\" data-bind=\"foreach: filter.Filters\">\n                            <div class=\"col-md-2\">\n                                Value\n                            </div>\n                            <div class=\"col-md-4\">\n                                <div data-bind=\"with: Field\">\n                                    <div class=\"form-group\">\n                                        <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: fieldFilter, value: $parent.Operator\" required></select>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col-md-4\">\n                                <div data-bind=\"with: Field\" data-parentprefix=\"C\">\n                                    <div data-bind=\"template: 'report-filter', data: $data\"></div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <br />\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-danger\" data-bind=\"click: cancelFieldOptions\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: saveFieldOptions\">Save Changes</button>\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"report-link-edit\">\n    <div class=\"modal-dialog\" style=\"max-width: 750px;\">\n        <div class=\"modal-content\" data-bind=\"with: editLinkField\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\">Setup Link Field</h5>\n            </div>\n            <div class=\"modal-body needs-validation\" data-bind=\"with: linkFieldItem\">\n                <div class=\"form-group row\">\n                    <label class=\"col-sm-5 col-md-5 control-label\">This field will link to</label>\n                    <div class=\"col-sm-7 col-md-7\">\n                        <select class=\"form-select\" required data-bind=\"options: linkTypes, value: selectedLinkType\"></select>\n                    </div>\n                </div>\n                <div data-bind=\"if: LinksToReport\">\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Link to this Report</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <div class=\"d-flex gap-2 align-items-start\">\n                                <select class=\"form-select\" required data-bind=\"options: savedReportsWithFolder, optionsText: function(r) { return (r.folderName ? r.folderName + ' › ' : '') + r.reportName }, optionsValue: 'reportId', optionsCaption: '', value: LinkedToReportId, select2: { placeholder: 'Search reports or folders...', allowClear: true }\"></select>\n                                <button type=\"button\" class=\"btn btn-sm btn-outline-success text-nowrap\" title=\"Create a new report to link to\" data-bind=\"click: createNewLinkedReport\">\n                                    New\n                                </button>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"checkbox\" data-bind=\"if: LinkedToReportId\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: SendAsFilterParameter\" />\n                            Send field value as Report Filter Parameter\n                        </label>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"if: SendAsFilterParameter\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Link to this Report Filter</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" required data-bind=\"options: allFields, optionsText: function(f) { return (f.tableName ? f.tableName + ' › ' : '') + f.fieldName }, optionsValue: 'fieldId', value: SelectedFilterId, optionsCaption: 'Choose the Field to Filter by value'\"></select>\n                        </div>\n                    </div>\n                    <div data-bind=\"if: LinkedToReportId\">\n                        <div class=\"mt-2 mb-1\">\n                            <label class=\"form-check-label\">\n                                <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: isSubReportOnly, click: function() { toggleLinkedReportSubReportOnly(); return true; }\" />\n                                <span class=\"small\">Only use as sub/linked report</span>\n                            </label>\n                            <div class=\"small text-muted ms-4\">\n                                When checked, this report will be hidden from report folders and search results, and will only be run as a linked or sub report from the parent report.\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <div data-bind=\"ifnot: LinksToReport\">\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Link to this URL</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" required placeholder=\"Enter a url to open\" data-bind=\"value: LinkToUrl\" title=\"Valid URL needs to start with http:// or https://\">\n                        </div>\n                    </div>\n                    <div class=\"checkbox\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: SendAsQueryParameter\" />\n                            Send field value as Query Parameter\n                        </label>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"if: SendAsQueryParameter\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Parameter Name to use</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" required placeholder=\"Enter parameter name to send value as\" data-bind=\"value: QueryParameterName\">\n                        </div>\n                    </div>\n                    <br />\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-danger\" data-bind=\"click: removeLinkField\">Remove Link</button>\n                <button type=\"button\" class=\"btn btn-outline-primary\" data-bind=\"visible: linkFieldItem.LinksToReport() && linkFieldItem.LinkedToReportId(), click: function() { saveLinkField(); linkFieldItem.editLinkedReport(); }\">Edit Linked Report</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: saveLinkField\">Save Changes</button>\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-choose-visual\">\n    <div style=\"overflow-x: auto;\">\n    <div class=\"btn-group\" role=\"group\" aria-label=\"Visualization Options\" style=\"flex-wrap: nowrap; min-width: max-content;\">\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('List'); }, css: { active: ReportType()=='List' }, attr: { 'data-chart-id': 'List' }\">\n            <span class=\"fa fa-2x fa-list-alt\"></span>\n            <p>List</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Summary'); }, css: { active: ReportType()=='Summary',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Summary' }\">\n            <span class=\"fa fa-2x fa-table\"></span>\n            <p>Summary</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Bar'); }, css: { active: ReportType()=='Bar',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Bar' }\">\n            <span class=\"fa fa-2x fa-bar-chart\"></span>\n            <p>Bar</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Pie'); }, css: { active: ReportType()=='Pie',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Pie' }\">\n            <span class=\"fa fa-2x fa-pie-chart\"></span>\n            <p>Pie</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Line'); }, css: { active: ReportType()=='Line',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Line' }\">\n            <span class=\"fa fa-2x fa-line-chart\"></span>\n            <p>Line</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Combo'); }, css: { active: ReportType()=='Combo',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Combo' }\">\n            <span class=\"fa fa-2x fa-signal\"></span>\n            <p>Combo</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Html'); }, css: { active: ReportType()=='Html',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Html' }\">\n            <span class=\"fa fa-2x fa-code\"></span>\n            <p>Custom</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Map'); }, css: { active: ReportType().indexOf('Map')==0,disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Map' }\">\n            <span class=\"fa fa-2x fa-globe\"></span>\n            <p>Map</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Single'); }, css: { active: ReportType()=='Single',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Single' }\">\n            <span class=\"fa fa-2x fa-window-maximize\"></span>\n            <p>KPI</p>\n        </button>\n        <button class=\"btn btn-outline-secondary\" data-bind=\"click: showMoreCharts\" title=\"Explore more visualization options\">\n            <span class=\"fa fa-2x fa-th-large\"></span>\n            <p>More...</p>\n        </button>\n    </div>\n    </div>\n    <!-- Smart Suggestion -->\n    <div class=\"smart-suggestion mt-2\" data-bind=\"visible: smartSuggestion() && (showHints() || activeDesign())\">\n        <i class=\"fas fa-lightbulb text-warning\"></i>\n        <span data-bind=\"text: smartSuggestion\"></span>\n        <a href=\"#\" class=\"ms-2 small\" data-bind=\"click: applySuggestion\">\n            <i class=\"fa fa-check\"></i> Apply\n        </a>\n    </div>\n</script>\n\n<!-- ══════════════════ MORE CHARTS MODAL ══════════════════ -->\n<div class=\"modal\" id=\"moreChartsModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-xl modal-dialog-centered\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header py-2\">\n                <h5 class=\"modal-title\" id=\"moreChartsModalLabel\">\n                    <i class=\"fa fa-th-large\"></i> Choose a Visualization\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body p-0\" data-bind=\"stopBindings: true\">\n                <div class=\"d-flex more-charts-layout\">\n                    <!-- Left: Chart Type Grid (rendered programmatically by showMoreCharts) -->\n                    <div class=\"more-charts-grid-panel\" id=\"moreChartsGridPanel\"></div>\n                    <!-- Right: Detail Preview Panel (rendered programmatically by selectMoreChart) -->\n                    <div class=\"more-charts-detail-panel\" id=\"moreChartsDetailPanel\"></div>\n                </div>\n            </div>\n            <div class=\"modal-footer py-2\">\n                <button type=\"button\" class=\"btn btn-secondary btn-sm\" data-bs-dismiss=\"modal\">Close</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<script type=\"text/html\" id=\"designer-choose-data\">\n    <div>\n        <div class=\"float-start btn-group btn-group-toggle\" role=\"group\" data-bind=\"if: ReportID() <= 0\">\n            <label class=\"btn btn-sm btn-light\" style=\"margin-right: 0px;\" title=\"You can change the Data source only when creating a new report, changing this will clear all selections\" data-bind=\"css: { active: !useStoredProc() }\">\n                <input type=\"radio\" name=\"dataoption\" id=\"table\" checked data-bind=\"checked: useStoredProc, checkedValue: false\"> Dynamic\n            </label>\n            <label class=\"btn btn-sm btn-light\" data-bind=\"css: { active: useStoredProc() }\">\n                <input type=\"radio\" name=\"dataoption\" id=\"proc\" value=\"1\" data-bind=\"checked: useStoredProc, checkedValue: true\"> Predefined\n            </label>\n        </div>\n        <div class=\"float-end\">\n            <a href=\"#\" class=\"btn btn-sm\" style=\"font-size: 11px; padding: 3px 8px;\" title=\"Add Custom Field using Formula\" data-bind=\"hidden: isFunctionField() || useStoredProc(), click: cancelFormulaField, css: {'btn-primary': !isFormulaField(), 'btn-danger btn-sm': isFormulaField}\">\n                <!-- ko ifnot: isFormulaField() -->Custom Field<!-- /ko -->\n                <!-- ko if: isFormulaField() --><i class=\"fa fa-times\"></i><!-- /ko -->\n            </a>\n            <a href=\"#\" class=\"btn btn-sm\" style=\"font-size: 11px; padding: 3px 8px;\" title=\"Add Custom Field using Function\" data-bind=\"hidden:isFormulaField() || useStoredProc() || !ko.unwrap(appSettings.useFunctions) || ReportType() !== 'List' , click: function(){designFunctionField()}, css: {'btn-primary': !isFunctionField(), 'btn-danger btn-sm': isFunctionField}\">\n                <!-- ko ifnot: isFunctionField() -->Function Field<!-- /ko -->\n                <!-- ko if: isFunctionField() --><i class=\"fa fa-times\"></i><!-- /ko -->\n            </a>\n        </div>\n    </div>\n    <div class=\"clearfix\"></div>\n    <div class=\"row\">\n        <div class=\"col-md-12\" data-bind=\"disable: isFormulaField, hidden: useStoredProc\">\n            <div data-bind=\"with: textQuery.searchFields\">\n                <select class=\"form-control\" data-bind=\"select2: {dropdownParent: $root.activeDesign() ? $('#choose-data-design') : $('#choose-data-card'), placeholder: 'Search for a Data Field...', ajax: { url: url, dataType: 'json', data: query, processResults: processResults, headers: headers }, minimumInputLength: 2, allowClear: true }, value: selectedOption\"></select>\n            </div>\n        </div>\n\n        <div class=\"col-md-12\" data-bind=\"visible: useStoredProc\">\n            <div>\n                <select class=\"form-control\" data-bind=\"select2Value: {dropdownParent: $root.activeDesign() ? $('#choose-data-design') : $('#choose-data-card')}, options: Procs, optionsCaption: 'Choose Section...', optionsText: 'DisplayName', value: SelectedProc, visible: useStoredProc\"></select>\n            </div>\n        </div>\n        <div class=\"col-md-12\" data-bind=\"hidden: useStoredProc\">\n            <div class=\"d-flex justify-content-between align-items-center mb-2\" style=\"padding-top: 15px;\">\n                <span>\n                    Select Data to use in Report\n                    <i class=\"fa fa-info-circle text-muted\" data-toggle=\"tooltip\" title=\"Choose a table to show fields to select.\"></i>\n                </span>\n            </div>\n\n            <div class=\"data-select-tree\">\n                <!-- ko foreach: CategorizedTables -->\n                <div class=\"mb-3\">\n                    <div data-bind=\"click: function() { isExpanded(!isExpanded()); }, visible: categoryName\" style=\"cursor: pointer;\">\n                        <i class=\"fa\" data-bind=\"css: isExpanded() ? 'fa-chevron-down text-secondary' : 'fa-chevron-right text-secondary'\"></i>\n                        <i class=\"fa\" data-bind=\"css: isExpanded() ? 'fa-folder-open' : 'fa-folder'\"></i>\n                        <span data-bind=\"text: categoryName\" class=\"ml-2\"></span>\n                    </div>\n                    <div class=\"report-list\" data-bind=\"visible: isExpanded(), foreach: tables\" style=\"padding-left: 15px;\">\n                        <div class=\"row border-bottom py-2 w-100\">\n                            <div class=\"col-md-12\">\n                                <div class=\"float-start\" data-bind=\"click: function() { selectTable($data); }, css: {'text-muted': !isEnabled()}, style: {cursor: isEnabled() ? 'pointer' : ''}, attr: {title: !isEnabled() ? 'Cannot use table as joins do not exist': ''}\">\n                                    <span class=\"text-secondary fa\" data-bind=\"css: isEnabled() ? ($data === $parents[1].SelectedTable() ? 'fa-chevron-down' : 'fa-chevron-right') : 'fa-ban'\"></span>&nbsp;\n                                    <span class=\"fa fa-table\"></span>&nbsp;<span data-bind=\"text: tableName\" class=\"\"></span>\n                                </div>\n                                <div class=\"float-end\" data-bind=\"visible: $data === $parents[1].SelectedTable() && !$parents[1].isFormulaField() && !$parents[1].SelectedTable().dynamicColumns\">\n                                    <a href=\"#\" class=\"small text-muted\" data-bind=\"click: $parents[1].MoveAllFields\">Select all</a> |\n                                    <a href=\"#\" class=\"small text-muted\" data-bind=\"click: $parents[1].RemoveSelectedFields\">Remove all</a>\n                                </div>\n                            </div>\n\n                            <!-- Fields Expand Here -->\n                            <div data-bind=\"visible: $data === $parents[1].SelectedTable()\" style=\"padding-left: 30px;\">\n                                <!-- ko foreach: $parents[1].ChooseFields -->\n                                <div class=\"row border-bottom py-2 align-items-center w-100\">\n                                    <div class=\"checkbox\">\n                                        <label>\n                                            <input type=\"checkbox\" data-bind=\"checkedInArray: {array: $parents[2].isFormulaField() ? $parents[2].formulaFields : $parents[2].SelectedFields, value: $data}\">\n                                            <span data-bind=\"text: fieldName\"></span>\n                                        </label>\n                                    </div>\n                                </div>\n                                <!--/ko-->\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <!-- /ko -->\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-selected-data\">\n    <div data-bind=\"visible: SelectedFields().length == 0\">\n        Please choose data\n    </div>\n    <div data-bind=\"if: SelectedFields().length > 0\">\n        <div data-bind=\"visible: ReportType()=='Bar'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Bar Graph, the first field below will show on the x-axis. All other numeric fields will show on y-axis.\n            </div>\n            <div class=\"form-group row small\">\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: barChartHorizontal\" />\n                Horizontal Bar Chart\n                </label>\n            </div>\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: barChartStacked\" />\n                Stacked Bar Chart\n                </label>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Pie'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Pie Graph, the first field below will be grouped, and the first numeric field will show as the ratio.\n            </div>\n            <div class=\"form-group row small\">\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: pieChartDonut\" />\n                Donut Chart\n                </label>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Radar'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Radar chart, the first field is the category label. All other numeric fields become axes on the radar. Each row is a separate polygon.\n            </div>\n        </div>\n        <div data-bind=\"visible: ReportType()=='Polar'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Polar Stacked Bar, the first field is the category. Each numeric field becomes a stacked segment on the circular axis.\n            </div>\n        </div>\n        <div data-bind=\"visible: ReportType()=='Treemap'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Treemap, the data must be in a hierarchical format with 2nd column having parent and third column having a numeric value. The data must have a single root node having null as its parent as well.\n            </div>\n        </div>\n        <div data-bind=\"visible: ReportType()=='HeatMap'\" class=\"card card-body\">\n            <div class=\"alert alert-info mb-3\">\n                <span class=\"fas fa-lightbulb fa-2x\"></span>&nbsp;For HeatMap, the first two columns must be numeric values representing\n                <strong>Latitude</strong> and <strong>Longitude</strong>. At least one additional numeric column is required to provide the\n                <strong>intensity</strong> of each point.\n            </div>\n\n            <div class=\"form-group row mb-2\">\n                <div class=\"checkbox col-6\">\n                    <label>\n                        <input type=\"checkbox\" data-bind=\"checked: heatMapOptions.showMarker\" />\n                        Show Marker\n                    </label>\n                </div>\n            </div>\n\n            <div class=\"form-group row mb-3\">\n                <label class=\"col-12 fw-bold\">Heatmap Colors</label>\n\n                <div class=\"col-4 mb-2\">\n                    <input type=\"color\" class=\"color-picker\"\n                            data-bind=\"value: heatMapOptions.gradient1\" title=\"Gradient 1\" />\n                </div>\n                <div class=\"col-4 mb-2\">\n                    <input type=\"color\" class=\"color-picker\"\n                            data-bind=\"value: heatMapOptions.gradient2\" title=\"Gradient 2\" />\n                </div>\n                <div class=\"col-4 mb-2\">\n                    <input type=\"color\" class=\"color-picker\"\n                            data-bind=\"value: heatMapOptions.gradient3\" title=\"Gradient 3\" />\n                </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Line'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Line Graph, the first field below will show on the x-axis. All other fields will numeric fields will show on y-axis.\n            </div>\n            <div class=\"form-group row small\">\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: lineChartArea\" />\n                Area Chart\n                </label>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Combo'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Combo Graph, the first field below will show on the x-axis. All other numeric fields will show on y-axis, and you can choose display each series as line, bar or area.\n            </div>\n            <div class=\"form-group row small\">\n            <div class=\"col-6\">\n                <label>Default Series Type</label>\n                <select class=\"form-select form-select-sm\" data-bind=\"options: seriesTypes, optionsText: 'label', optionsValue: 'value', value: comboChartType\"></select>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Pivot'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Transpose, the first field below will be used to Transpose the rows as columns, and it must be grouped.\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Single'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;KPI is a single value report that is ideal for placing on a Dashboard. All fields except one must be hidden for Widgets.\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Html'\" class=\"card card-body\">\n            <div class=\"form-group row small\">\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: dontGroupCustom\" />\n                List (Don't Summarize)\n                </label>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Map'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Map Graph, the first field below has to be a Region name (e.g. Country) or use Latitude/Longitude columns for marker mode.\n            </div>\n            <div class=\"form-group row small\">\n            <label class=\"col-sm-3 control-label\">Map Display</label>\n            <div class=\"col-sm-5\">\n                <select class=\"form-select form-select-sm\" data-bind=\"options: mapRegions, value: mapRegion\"></select>\n            </div>\n            </div>\n            <div class=\"form-group row small\" data-bind=\"visible: mapRegion() == 'Other'\">\n            <label class=\"col-sm-3 control-label\">Region Name</label>\n            <div class=\"col-sm-5\">\n                <input type=\"text\" class=\"form-control form-control-sm\" placeholder=\"e.g. Texas, United Kingdom, Australia\" data-bind=\"value: otherMapRegion, valueUpdate: 'input'\" />\n            </div>\n            <div class=\"col-sm-4 small text-muted pt-1\">Enter any country, state, or region name</div>\n            </div>\n        </div>\n    </div>\n    <ul class=\"list-group\" data-bind=\"sortable: { data: SelectedFields, options: { handle: '.sortable', cursor: 'move', placeholder: 'drop-highlight' }, strategyMove: true }\">\n        <li class=\"list-group-item\">\n            <div class=\"row\">\n                <div class=\"col-5\">\n                    <span class=\"sortable float-start\" style=\"padding-right: 15px;\" data-bind=\"ifnot: $parent.useStoredProc\">\n                        <span class=\"fa fa-ellipsis-v\" aria-hidden=\"true\" title=\"Drag to reorder\"></span>\n                    </span>\n                    <span class=\"fa fa-columns\"></span>\n                    <span data-bind=\"text: selectedFieldName()\"></span>\n                    <span data-bind=\"text: isFormulaField() ? '(' + fieldFormat() + ')' : ''\"></span>\n                    <span data-bind=\"visible: !$parent.isFieldValidForYAxis($index(), fieldType || fieldFormat(), selectedAggregate()) && $parent.ReportType() !='Treemap' && $parent.isChart()\">\n                        <span class=\"badge bg-danger\" data-bind=\"visible: !groupInGraph()\">Will not show in <span data-bind=\"text: $parent.ReportType\"></span>Chart</span>\n                    </span>\n                    <span data-bind=\"visible: $parent.IsPivotFieldLastColumn($index(),selectedAggregate())\">\n                        <span class=\"badge bg-danger\" >Pivot field cannot be the last column.</span>\n                    </span>\n                    <span data-bind=\"visible: $parent.IsDynamicFieldFirstColumn($index())\">\n                        <span class=\"badge bg-danger\" >Dynamic cannot be first column.</span>\n                    </span>\n                </div>\n                <div class=\"col-7 d-flex flex-row-reverse\">\n                    <div style=\"margin-top: -5px;\" data-bind=\"if: $parent.AggregateReport() && !$parent.useStoredProc()\">\n                        <div class=\"d-flex align-items-center\">\n                            <select class=\"form-select form-control-sm\" data-bind=\"options: $parent.canDrilldown() && $index()>0 ? fieldAggregateWithDrilldown : fieldAggregate, value: selectedAggregate\"></select>\n                            <i class=\"fa fa-info-circle ms-1 text-muted aggregate-help-tip\" style=\"cursor:help; font-size:12px;\"\n                               data-bind=\"visible: $parent.showHints(), attr: { 'data-agg-tooltip': $parent.getAggregateTooltip($data) }\"></i>\n                        </div>\n                    </div>\n\n                    <div  style=\"padding-right: 10px;\" data-bind=\"ifnot: $parent.useStoredProc\">\n                        <span class=\"fa fa-trash\" title=\"Cannot Delete Required Filter\" data-bind=\"visible: forceFilterForTable\"></span>\n                        <span class=\"fa fa-trash\" style=\"cursor: pointer;\" aria-hidden=\"true\" title=\"Delete this Field\" data-bind=\"click: $parent.RemoveField, hidden: forceFilterForTable\"></span>\n                    </div>\n                    <!--<div  style=\"padding-right: 10px;\" data-bind=\"ifnot: $parent.useStoredProc\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: function(){ filterOnFly(!filterOnFly()); }, css: {active: filterOnFly()==true}\">\n                            <span class=\"fa fa-filter\" aria-hidden=\"true\" title=\"Filter by this field on the Report\"></span>\n                        </span>\n                    </div>-->\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.ReportType()!='Pivot'\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: toggleDisable\">\n                            <span data-bind=\"\n                                css: {\n                                    'fa': true,\n                                    'fa-close': disabled(),\n                                    'fa-check': !disabled(),\n                                    'text-danger': disabled()\n                                },\n                                attr: {\n                                    title: disabled() ? 'Excluded from the Report' : 'Included in the Report'\n                                }\n                            \" aria-hidden=\"true\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.ReportType()!='Pivot' && $parent.ReportType()!='List' && !$parent.useStoredProc()\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: function(){ hideInDetail(!hideInDetail()); }, css: {active: hideInDetail()==true}\">\n                            <span class=\"fa fa-eye-slash\" aria-hidden=\"true\" title=\"Hide in Details\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.isFieldValidForYAxis($index(), fieldType || fieldFormat(), selectedAggregate())  && $parent.isChart() && $index()>0\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: function(){ groupInGraph(!groupInGraph()); }, css: {active: groupInGraph()==false}\">\n                            <span class=\"fas fa-signal\" aria-hidden=\"true\" title=\"Include in series\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.ReportType()!='Pivot'\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: setupLinkField, css: {active: linkField()==true}\">\n                            <span class=\"fa fa-link\" aria-hidden=\"true\" title=\"Link to another Report or Url\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.ReportType()=='Combo' && $parent.isFieldValidForYAxis($index(), fieldType || fieldFormat(), selectedAggregate())  && $parent.isChart() && $index()>0\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: function(){ seriesType(seriesType() == 'line' ? 'area' : (seriesType()=='bars' ? 'line' : 'bars')); }\">\n                            <span class=\"fa\" aria-hidden=\"true\" data-bind=\"css: {'fa-line-chart': seriesType() == 'line', 'fa-bar-chart': seriesType() == 'bars', 'fa-area-chart': seriesType()=='area' }, attr: {title: seriesType}\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: setupFieldOptions\">\n                            <span class=\"fa fa-gear\" aria-hidden=\"true\" title=\"More Options\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"if: isFormulaField\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: editFormulaField\">\n                            <span class=\"fa fa-pencil\" aria-hidden=\"true\" title=\"Edit Formula Field\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"if: isFormulaField\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: duplicateFormulaField\">\n                            <span class=\"fa fa-copy\" aria-hidden=\"true\" title=\"Duplicate Formula Field\"></span>\n                        </span>\n                    </div>\n                </div>\n            </div>\n        </li>\n    </ul>\n</script>\n\n<script type=\"text/html\" id=\"designer-sub-report\">\n    <p class=\"text-muted mb-3\">\n        Linked reports are available to add as sub reports.\n        Selecting sub reports will restrict the report to <strong>one record per page</strong>.\n    </p>\n\n    <div class=\"mb-3\">\n        <select class=\"form-select\"\n                data-bind=\"options: linkedReportFields,\n                            optionsText: 'name',\n                            value: selectedSubReport,\n                            optionsCaption: 'Select a linked report...'\">\n        </select>\n    </div>\n    <ul class=\"list-group\"\n        data-bind=\"sortable: {\n                        data: subReports,\n                        options: { handle: '.sortable', cursor: 'move', placeholder: 'drop-highlight' }\n                    }\">\n        <li class=\"list-group-item\">\n            <div class=\"d-flex justify-content-between align-items-center\">\n                <span>\n                    <i class=\"fa fa-bars sortable me-2\" style=\"cursor:move;\"></i>\n                    <span data-bind=\"text: name\"></span>\n                </span>\n                <span>\n                    <button type=\"button\" class=\"btn btn-sm btn-outline-primary me-1\" title=\"Edit sub report\"\n                            data-bind=\"click: $parent.editSubReport\">\n                        <i class=\"fa fa-edit\"></i> Edit\n                    </button>\n                    <button type=\"button\" class=\"btn btn-sm btn-outline-danger\"\n                            data-bind=\"click: $parent.removeSubReport\">\n                        Delete\n                    </button>\n                </span>\n            </div>\n            <div class=\"mt-1 d-flex gap-3 align-items-center flex-wrap\">\n                <label class=\"form-check-label small\">\n                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: isSubReportOnly, click: function() { setTimeout(function() { $parent.toggleSubReportOnly($data); }, 0); return true; }\" />\n                    Sub report only\n                    <i class=\"fa fa-question-circle text-muted\" title=\"When checked, this report will be hidden from folders and search, and can only run as a child report from here\"></i>\n                </label>\n                <label class=\"form-check-label small\">\n                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: hideTitle\" />\n                    Hide title\n                </label>\n                <label class=\"form-check-label small\">\n                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: hidePager\" />\n                    Hide pager\n                </label>\n            </div>\n        </li>\n    </ul>\n</script>\n\n<script type=\"text/html\" id=\"designer-html\">\n    <div class=\"row align-items-center mb-1\">\n        <div class=\"col-md-4\">\n        <select class=\"form-select\" data-bind=\"options: SelectedFields, value: SelectFieldToInsert, optionsCaption: 'Select a field...', optionsText: 'selectedFieldName'\"></select>\n        </div>\n        <div class=\"col-auto dropdown\">\n            <button class=\"btn btn-outline-secondary btn-sm dropdown-toggle\" type=\"button\" data-bs-toggle=\"dropdown\">\n            <i class=\"fa fa-table\"></i> Insert as Table\n            </button>\n            <ul class=\"dropdown-menu\">\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertFieldTableTransposed\">Transposed</a></li>\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertFieldTableStandard\">Standard</a></li>\n                <!-- ko if: hasOuterGroupFields -->\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertGroupedTable\">Grouped</a></li>\n                <!-- /ko -->\n                <li><hr class=\"dropdown-divider\"></li>\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertHeaderBreak\">Add Header Break</a></li>\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertFooterBreak\">Add Footer Break</a></li>\n            </ul>\n        </div>\n        <!-- ko if: subReports().length > 0 -->\n        <div class=\"col-auto dropdown d-flex align-items-center gap-2\">\n            <button class=\"btn btn-outline-secondary btn-sm dropdown-toggle\" type=\"button\" data-bs-toggle=\"dropdown\" title=\"Insert a selected sub report inline at cursor position\">\n                <i class=\"fa fa-bookmark\"></i> Insert Sub Report\n            </button>\n            <i class=\"fa fa-info-circle text-muted\"\n               data-bs-toggle=\"tooltip\"\n               data-bs-placement=\"top\"\n               title=\"Note: If you insert Sub Reports in custom report, only inserted sub reports will show and other sub reports will not render\">\n            </i>\n\n            <ul class=\"dropdown-menu\" data-bind=\"foreach: subReports\">\n                <li>\n                    <a class=\"dropdown-item\" href=\"#\"\n                       data-bind=\"text: name, click: function() { $parent.insertSubReportPlaceholder($data); }\">\n                    </a>\n                </li>\n            </ul>\n        </div>\n        <!-- /ko -->\n        <div class=\"col-md-auto ms-auto\">\n        <label class=\"form-check-label\">\n            <input class=\"form-check-input me-2\" type=\"checkbox\" data-bind=\"checked: cardView\">\n            Card Layout\n        </label>\n        </div>\n    </div>\n    <div class=\"mb-3\">\n        <textarea data-bind=\"summernote: reportHtml\"></textarea>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-sort\">\n    <div data-bind=\"ifnot: useStoredProc\">\n         <div class=\"form-group row align-items-center flex-nowrap\">\n             <label class=\"col-auto control-label\">Sort By</label>\n             <div class=\"col\">\n                 <select class=\"form-select form-select-sm\"\n                     data-bind=\"options: FilteredFields, optionsText: 'selectedFieldName', optionsValue: 'fieldId', value: SortByField, optionsCaption: 'Select field to sort...', allowClear: true\">\n                 </select>\n             </div>\n             <div class=\"col-auto d-flex gap-1\">\n                 <button class=\"btn btn-sm btn-secondary\"\n                     data-bind=\"text: !SortDesc() ? '▲ Ascending' : 'Descending ▼', click: function() { SortDesc(!SortDesc()); return false; }\">\n                 </button>\n                 <button class=\"btn btn-sm btn-secondary\"\n                     data-bind=\"click: addSortField\">\n                     Add Sort\n                 </button>\n             </div>\n         </div>\n\n         <div data-bind=\"foreach: SortFields\">\n             <div class=\"form-group row align-items-center flex-nowrap\">\n                 <label class=\"col-auto control-label\">&nbsp;&nbsp;Then Sort By</label>\n                 <div class=\"col\">\n                     <select class=\"form-select form-select-sm\" required\n                         data-bind=\"options: $parent.FilteredFields, optionsText: 'selectedFieldName', optionsValue: 'fieldId', value: sortByFieldId\">\n                     </select>\n                 </div>\n                 <div class=\"col-auto d-flex gap-1\">\n                     <button class=\"btn btn-sm btn-secondary\"\n                         data-bind=\"click: remove\">\n                         Remove Sort\n                     </button>\n                     <button class=\"btn btn-sm btn-secondary\"\n                         data-bind=\"text: !sortDesc() ? '▲ Ascending' : 'Descending ▼', click: function() { sortDesc(!sortDesc()); return false; }\">\n                     </button>\n                     <button class=\"btn btn-sm btn-secondary\"\n                         data-bind=\"click: $parent.addSortField\">\n                         Add Sort\n                     </button>\n                 </div>\n             </div>\n         </div>\n     </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-header-footer\">\n    <div class=\"form-group mb-2\">\n        <label class=\"control-label small text-muted\"><i class=\"fa fa-window-maximize\"></i> Report Header</label>\n        <select class=\"form-select form-select-sm\" style=\"width: 100%;\"\n                data-bind=\"options: reportHeadersList, optionsText: 'label', optionsValue: 'id', value: ReportHeaderId\"></select>\n    </div>\n    <hr class=\"my-1\" />\n    <div class=\"form-group\">\n        <label class=\"control-label small text-muted\"><i class=\"fa fa-window-minimize\"></i> Report Footer</label>\n        <div class=\"form-check\">\n            <label class=\"form-check-label small\">\n                <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: UseReportFooterInReport\" />\n                Include the report footer in this report\n            </label>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-options\">\n    <div class=\"row\">\n        <div class=\"col-md-5\">\n            <div data-bind=\"visible: ReportType()!='Pivot' && ReportType()!='Custom'\">\n                <div class=\"checkbox\">\n                    <label>\n                        <input type=\"checkbox\" data-bind=\"checked: IncludeSubTotal\" />\n                        Include Total Row\n                    </label>\n                </div>\n                <div data-bind=\"visible: IncludeSubTotal()\" style=\"padding-left: 20px; margin-top: 4px; margin-bottom: 4px;\">\n                    <div class=\"form-check form-check-inline\">\n                        <input class=\"form-check-input\" type=\"radio\" data-bind=\"checked: totalRowFormat\" value=\"row\" />\n                        <label class=\"form-check-label\">As Total Row</label>\n                    </div>\n                    <div class=\"form-check form-check-inline\">\n                        <input class=\"form-check-input\" type=\"radio\" data-bind=\"checked: totalRowFormat\" value=\"table\" />\n                        <label class=\"form-check-label\">As Total Table</label>\n                    </div>\n                </div>\n                <div data-bind=\"visible: IncludeSubTotal() && hasOuterGroupFields()\" style=\"padding-left: 20px; margin-top: 2px; margin-bottom: 4px;\">\n                    <div class=\"checkbox\" style=\"margin-top: 0;\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: subTotalPerGroup\" />\n                            Sub Total Per Group\n                        </label>\n                    </div>\n                </div>\n                <div class=\"checkbox\" data-bind=\"visible: hasPivotColumn()\">\n                    <label>\n                        <input type=\"checkbox\" data-bind=\"checked: IncludeColumnTotal\" />\n                        Include Total Column\n                    </label>\n                </div>            \n            </div>\n            <div class=\"checkbox\" data-bind=\"hidden: AggregateReport\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowUniqueRecords\" />\n                    Show only Unique Records\n                </label>\n            </div>\n            <div class=\"checkbox\" data-bind=\"visible: ReportType()!='List'\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowExpandOption\" />\n                    Don't Show Expand Option\n                </label>\n            </div>\n                <div class=\"checkbox\" data-bind=\"visible: isChart\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowDataWithGraph\" />\n                    Show Data along with Graph\n                </label>\n            </div>\n            <!-- ko if: adminMode() -->\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: bypassEnabled\" />\n                    Bypass Data Filters\n                </label>\n            </div>\n            <!-- ko if: bypassEnabled() -->\n            <div style=\"padding-left: 20px;\">\n                <div class=\"radio\">\n                    <label>\n                        <input type=\"radio\" name=\"bypassMode\" value=\"all\" data-bind=\"checked: bypassMode\" />\n                        Bypass All Data Filters\n                    </label>\n                </div>\n                <div class=\"radio\">\n                    <label>\n                        <input type=\"radio\" name=\"bypassMode\" value=\"specific\" data-bind=\"checked: bypassMode\" />\n                        Bypass Specific Filters\n                    </label>\n                </div>\n                <!-- ko if: bypassMode() === 'specific' -->\n                <div style=\"padding-left: 20px;\">\n                    <!-- ko if: availableDataFilterIds().length > 0 -->\n                    <!-- ko foreach: availableDataFilterIds() -->\n                    <div class=\"checkbox\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: $parent.bypassSpecificIds, checkedValue: $data\" />\n                            <span data-bind=\"text: $data\"></span>\n                        </label>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <!-- ko if: availableDataFilterIds().length === 0 -->\n                    <div class=\"form-group mt-1\">\n                        <label class=\"text-muted small\">Enter filter column names (comma-separated):</label>\n                        <input type=\"text\" class=\"form-control form-control-sm\" placeholder=\"e.g. TenantId,UserId\" data-bind=\"value: bypassSpecificIdsText, valueUpdate: 'input'\" />\n                    </div>\n                    <!-- /ko -->\n                </div>\n                <!-- /ko -->\n            </div>\n            <!-- /ko -->\n            <!-- /ko -->\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: DontExecuteOnRun\" />\n                    Wait to Select Filters before Running Report\n                </label>\n            </div>\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowFilterDetails\" />\n                    Include Filter Details on Report\n                </label>\n            </div>\n            <div class=\"form-group row\">\n                <div class=\"checkbox col-md-5\">\n                    <label>\n                        <input type=\"checkbox\" data-bind=\"checked: maxRecords\" />\n                        Max Records\n                    </label>\n                </div>\n                <div class=\"col-md-5\" data-bind=\"if: maxRecords\">\n                    <input type=\"number\" style=\"width: 150px;\" class=\"form-control\" required placeholder=\"Only top n...\" data-bind=\"value: OnlyTop, visible: maxRecords\">\n                </div>\n            </div>\n            <div class=\"form-group row\">\n                <div class=\"checkbox col-md-5\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: changePageSize, disable: subReports().length > 0\" />\n                    Change Page Size\n                </label>\n                </div>\n                <div class=\"col-md-5\"\n                    data-bind=\"visible: changePageSize,\n                                css: { 'text-muted': subReports().length > 0 }\">\n                <select style=\"width: 150px;\" class=\"form-select\"\n                        data-bind=\"options: [1,10,30,50,100,150,200,500,1000],\n                                    value: DefaultPageSize,\n                                    disable: subReports().length > 0\">\n                </select>\n                </div>\n                <!-- Force default to 1 if sub reports selected -->\n                <div class=\"col-12 mt-1\" data-bind=\"visible: subReports().length > 0\">\n                    <small class=\"text-danger\">\n                        Page size is restricted to 1 when sub reports are selected.\n                    </small>\n                </div>\n            </div>\n        </div>\n        <div class=\"col-md-7\">\n            <p><span class=\"fa fa-paint-brush\"></span> Pick Report Format</p>\n            <div>\n                <!-- ko foreach: tableStyles -->\n                <div class=\"dropdown-option\" data-bind=\"title: $data.name, click: $parent.selectStyle, css: {'dropdown-option-selected': $parent.selectedStyle() == $data.colorscheme}\">\n                    <div class=\"mini-table-preview\" data-bind=\"foreach: new Array(5)\">\n                        <div class=\"mini-table-row\" data-bind=\"foreach: new Array(5)\">\n                            <div class=\"mini-table-cell\" data-bind=\"style: { backgroundColor: $parentContext.$index() === 0 ? $parents[1].headerBg : ($parentContext.$index() % 2 === 0 ? $parents[1].altRowBg : $parents[1].rowBg), color: $parents[1].textColor }\"></div>\n\n                        </div>\n                    </div>\n                </div>\n                <!-- /ko -->\n            </div>\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: noHeaderRow\" />\n                    No Header Row\n                </label>\n            </div>\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: noDashboardBorders\" />\n                    Borderless on Dashboard\n                </label>\n            </div>\n            <div class=\"checkbox\" data-bind=\"if: ReportType() == 'Single'\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: showPriorInKpi\" />\n                    Show previous comparision in KPI if applicable\n                </label>\n            </div>\n            <div data-bind=\"hidden: useStoredProc\" class=\"mt-2\">\n                <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: detectJoinsForReport\">\n                    <span class=\"fa fa-link\"></span> Configure Joins\n                </button>\n                <!-- ko if: customJoins().length > 0 -->\n                <span class=\"badge bg-success ms-1\"><span data-bind=\"text: customJoins().length\"></span> override(s)</span>\n                <button class=\"btn btn-sm btn-outline-danger ms-1\" data-bind=\"click: clearCustomJoins\" title=\"Remove all join overrides\">\n                    <span class=\"fa fa-times\"></span>\n                </button>\n                <!-- /ko -->\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"json-field-picker\">\n    <div data-bind=\"if: lastPickedField() && lastPickedField().fieldType == 'Json'\">\n        <br />\n        <div class=\"card\">\n            <div class=\"card-header\">\n                <h6>Select Data Fields from <span data-bind=\"text: lastPickedField().fieldName\"></span></h6>\n            </div>\n            <div class=\"card-body\">\n                <div class=\"row container-fluid\" data-bind=\"foreach: jsonFields\">\n                    <div class=\"col-md-3 col-sm-4 col-xs-6 list-group\">\n                        <div class=\"list-group-item\">\n                            <div class=\"checkbox\">\n                                <label>\n                                    <input type=\"checkbox\" data-bind=\"checkedInArray: {array: $parent.SelectedFields, value: $data}\">\n                                    <span data-bind=\"text: jsonColumnName\"></span>\n                                </label>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"custom-function-designer\">\n\n    <div class=\"row\">\n        <div class=\"col-md-12\" data-bind=\"visible: isFunctionField()\">\n            <div class=\"alert alert-info\">\n                You are now creating a Customized Field using Functions available.\n            </div>\n        </div>\n    </div>\n\n    <div class=\"form-group row\">\n        <label class=\"col-sm-2 control-label\">Field Label</label>\n        <div class=\"col-sm-10\">\n            <input type=\"text\" class=\"form-control form-control-sm\" data-bind=\"value: formulaFieldLabel\" required placeholder=\"Custom Field Label\" />\n        </div>\n    </div>\n    <div class=\"form-group row\">\n        <label class=\"col-sm-2 control-label\">Data Format</label>\n        <div class=\"col-sm-10\">\n            <select class=\"form-select form-control-sm\" data-bind=\"value: formulaDataFormat\" required>\n                <option>String</option>\n                <option>Integer</option>\n                <option>Decimal</option>\n                <option>Currency</option>\n                <option>Date</option>\n                <option value=\"DateTime\">Date and Time</option>\n            </select>\n        </div>\n    </div>\n    <div class=\"form-group row\" data-bind=\"visible: formulaDataFormat() == 'Decimal' || formulaDataFormat() == 'Currency'\">\n        <label class=\"col-sm-2 control-label\">Round to Decimal Places</label>\n        <div class=\"col-sm-10\">\n            <input type=\"number\" class=\"form-control\" data-bind=\"value: formulaDecimalPlaces\" placeholder=\"Choose Decimal places (leave blank to not use rounding)\" title=\"Choose Decimal places (leave blank to not use rounding)\" />\n        </div>\n    </div>\n\n    <div>\n        Define your Function:\n        <textarea id=\"function-code\"></textarea>\n    </div>\n    <div class=\"form-group row\" >\n        <div class=\"col-md-12 float-end\">\n            <hr />\n            <a href=\"#\" class=\"btn btn-primary btn-sm\" title=\"Save Custom Function Field\" data-bind=\"click: saveFunctionField, visible: isFunctionField\">Save</a>\n            <a href=\"#\" class=\"btn btn-sm\" title=\"Custom Field using Function\" data-bind=\"click: function(){isFunctionField(!isFunctionField())}, text: isFunctionField() ? 'Cancel': 'Function', css: {'btn-primary': !isFunctionField(), 'btn-danger': isFunctionField}\"></a>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"custom-field-designer\">\n    <div>\n        <div class=\"row\">\n            <div class=\"col-md-12\" data-bind=\"visible: isFormulaField()\">\n                <div class=\"alert alert-info\">\n                    You are now creating a Customized Field. Please select the fields you want to use in the calculation, then choose the operations you want to perform, and click \"Save\" to add your Custom field.\n                </div>\n            </div>\n        </div>\n        <div class=\"row\">\n            <div class=\"col-sm-6 small\">\n                Setup your Formula for calculating this Field\n            </div>\n            <div class=\"col-sm-6 right-align\" data-bind=\"visible: formulaType()=='build'\">\n                <a href=\"#\" class=\"btn btn-secondary btn-sm\" data-bind=\"click: addFormulaParentheses\">Add ( )</a>\n                <a href=\"#\" class=\"btn btn-secondary btn-sm\" title=\"Add Today\" data-bind=\"visible: formulaOnlyHasDateFields() || formulaFields().length == 0, click: addFormulaDateToday\">Add Today</a>\n                <a href=\"#\" class=\"btn btn-secondary btn-sm\" title=\"Add a Constant Value\" data-bind=\"click: addFormulaConstantValue\">Add Value</a>\n                <a href=\"#\" class=\"btn btn-secondary btn-sm\" data-bind=\"click: clearFormulaField\">Clear</a>\n            </div>\n        </div>\n        <div class=\"form-group-row\" data-bind=\"if: formulaOnlyHasDateFields\">\n            <div class=\"col-sm-12\">\n                <div class=\"alert alert-info\">\n                    For Dates Field calculation, you can only substract date fields and display the result as days, hours, minutes or seconds.\n                </div>\n            </div>\n        </div>\n        <div class=\"form-group row\">\n            <label class=\"col-sm-2 control-label\">Field Label</label>\n            <div class=\"col-sm-10\">\n                <input type=\"text\" class=\"form-control form-control-sm\" data-bind=\"value: formulaFieldLabel\" required placeholder=\"Custom Field Label\" />\n            </div>\n        </div>\n        <div class=\"form-group row\">\n            <label class=\"col-sm-2 control-label\">Data Format</label>\n            <div class=\"col-sm-10\">\n                <select class=\"form-select form-select-sm\" data-bind=\"value: formulaDataFormat\" required>\n                    <!-- ko ifnot: formulaOnlyHasDateFields -->\n                    <option>String</option>\n                    <option>Integer</option>\n                    <option>Decimal</option>\n                    <option>Currency</option>\n                    <!-- /ko -->\n                    <!-- ko if: formulaOnlyHasDateFields -->\n                    <option>Days</option>\n                    <option>Hours</option>\n                    <option>Minutes</option>\n                    <option>Seconds</option>\n                    <!-- /ko -->\n                </select>\n            </div>\n        </div>\n        <div class=\"form-group row\" data-bind=\"visible: formulaDataFormat() == 'Decimal' || formulaDataFormat() == 'Currency'\">\n            <label class=\"col-sm-2 control-label\">Round to Decimal Places</label>\n            <div class=\"col-sm-10\">\n                <input type=\"number\" class=\"form-control\" data-bind=\"value: formulaDecimalPlaces\" placeholder=\"Choose Decimal places (leave blank to not use rounding)\" title=\"Choose Decimal places (leave blank to not use rounding)\" />\n            </div>\n        </div>\n        <div class=\"form-group row\" data-bind=\"visible: appSettings.useSqlCustomField\">\n            <label class=\"col-sm-2 control-label\">Field Builder Type</label>\n            <div class=\"col-sm-10\">\n                <select class=\"form-select form-select-sm\" data-bind=\"value: formulaType\" required>\n                    <option value=\"build\">Simple Calculation</option>\n                    <option value=\"sql\">Advanced Expression</option>\n                </select>\n            </div>\n        </div>\n\n        <div class=\"form-group row\" data-bind=\"if: formulaType()=='build'\">\n            <label class=\"col-sm-2 control-label\">Field Formula</label>\n            <div class=\"col-sm-10\">\n                <div class=\"text-muted small\" data-bind=\"visible: formulaFields().length == 0\">Pick fields to build calculation</div>\n                <div class=\"d-flex align-items-center flex-wrap\" data-bind=\"foreach: formulaFields\">\n                    <h3 class=\"me-3\" data-bind=\"visible: setupFormula.isParenthesesStart\" style=\"margin-top: 0;\">(</h3>\n                    <div data-bind=\"if: !setupFormula.isParenthesesStart() && !setupFormula.isParenthesesEnd()\" class=\"list-group me-3\">\n                        <div class=\"list-group-item d-flex align-items-center formula-field-item\" style=\"margin-left: 15px; padding: 5px 15px\">\n                            <span data-bind=\"text: fieldName, visible: !setupFormula.isConstantValue()\"></span>\n                            <div data-bind=\"if: setupFormula.isConstantValue\" class=\"d-flex align-items-center\">\n                                <input data-bind=\"value: setupFormula.constantValue, visible: setupFormula.constantValue()!='|Today|'\" class=\"form-control form-control-sm me-2\" required />\n                                <span data-bind=\"visible: setupFormula.constantValue() == '|Today|'\"><b>Today</b></span>\n                            </div>\n                            <button class=\"btn btn-danger btn-sm ms-2\" data-bind=\"click: $parent.removeField\">\n                                <i class=\"fa fa-trash\"></i>\n                            </button>\n                        </div>\n                    </div>\n                    <h3 class=\"me-3\" data-bind=\"visible: setupFormula.isParenthesesEnd\" style=\"margin-top: 0;\">)</h3>\n                    <div class=\"me-3\" style=\"margin-left: 15px;\" data-bind=\"visible: $parent.showFormulaOperation($index())\">\n                        <select class=\"form-control form-control-sm\" style=\"max-width: 50px;\" data-bind=\"value: setupFormula.formulaOperation\">\n                            <!-- ko if: !$parent.formulaOnlyHasDateFields() || ($parent.formulaOnlyHasDateFields() && $parent.isConstantOperation($index())) -->\n                            <option>+</option>\n                            <!-- /ko -->\n                            <option>-</option>\n                            <!-- ko if: ['Integer','Money','Float','Double','Decimal','Currency'].indexOf($parent.formulaDataFormat()) != -1 -->\n                            <option>*</option>\n                            <option>/</option>\n                            <!-- /ko -->\n                        </select>\n                    </div>\n                </div>\n\n            </div>\n        </div>\n\n        <div data-bind=\"with: customSqlField, visible: formulaType()=='sql'\">\n            <div class=\"row\">\n                <div class=\"col-md-12\">\n\n                    <div class=\"mb-3\">\n                        <label class=\"form-label\">Select Data Operation:</label>\n                        <select class=\"form-select\" data-bind=\"select2: {\n                            dropdownParent: $root.activeDesign() ? $('#choose-data-design') : $('#choose-data-card'),\n                            placeholder: 'Select Function...',\n                            data: availableFunctionsGrouped(),\n                            templateResult: templateResult\n                        }, value: selectedSqlFunction\"></select>\n                    </div>\n\n                    <div class=\"mb-3\" data-bind=\"hidden: isConditionalFunction() || selectedSqlFunction() == 'Other'\">\n                        <label class=\"form-label\">Select the Data Field to use:</label>\n                        <select class=\"form-select\"\n                                data-bind=\"select2: {\n                                    dropdownParent: $root.activeDesign() ? $('#choose-data-design') : $('#choose-data-card'),\n                                    placeholder: 'Search Field...',\n                                    ajax: {\n                                        url: $parent.textQuery.searchFields.url,\n                                        dataType: 'json',\n                                        data: $parent.textQuery.searchFields.query,\n                                        processResults: $parent.textQuery.searchFields.processResults,\n                                        headers: $parent.textQuery.searchFields.headers\n                                    },\n                                    minimumInputLength: 2,\n                                    allowClear: true\n                                }, select2Text: selectedField,select2TableId:selectedFieldTableId\"></select>\n                        <div data-bind=\"with: selectedField\" class=\"small\">\n                                Selected: <span class=\"highlight\" data-bind=\"text: $data\"></span>\n                        </div>\n                    </div>\n\n                    <div class=\"mb-3\" data-bind=\"if: requiresValue\">\n                        <label for=\"inputValue\" class=\"form-label\">Provide the relevant value to use:</label>\n                        <input type=\"text\" id=\"inputValue\" class=\"form-control\" data-bind=\"value: inputValue\" required />\n                    </div>\n\n                    <div class=\"mb-3\" data-bind=\"visible: selectedSqlFunction() == 'Other'\">\n                        <label for=\"custom-sql\" class=\"form-label\">Custom SQL Expression:</label>\n                        <p class=\"text-muted\">\n                            Build your custom SQL Expression below by selecting data fields, adding calculations or using SQL keywords as needed. For string values, remember to enclose them in single quotes ('')\n                        </p>\n                        <p id=\"custom-sql\" class=\"hint-input\" contenteditable=\"true\" placeholder=\"Write your custom SQL\"></p>\n                    </div>\n                    <div data-bind=\"visible: isConditionalFunction\">\n                        <p class=\"text-muted\">\n                            Build your conditional logic below by selecting data fields, adding calculations and defining conditions as needed, and provide corresponding results. For string values, remember to enclose them in single quotes ('')\n                        </p>\n                        <div class=\"input-group mb-3\">\n                            <div class=\"flex-grow-1\">\n                                <p class=\"hint-input\" id=\"condition-field\" contenteditable=\"true\" placeholder=\"Field to compare\" title=\"Field to compare\"></p>\n                            </div>\n\n                            <div class=\"mx-2\" style=\"width: 120px;\">\n                                <select class=\"form-select form-select-sm\" data-bind=\"options: availableOperators, value: selectedOperator\"></select>\n                            </div>\n\n                            <div class=\"flex-grow-1\">\n                                <p class=\"hint-input\" id=\"condition-value\" contenteditable=\"true\" placeholder=\"Value to compare\" title=\"Value to compare\"></p>\n                            </div>\n\n                            <span class=\"input-group-text\" style=\"max-height: 32px;\">THEN</span>\n\n                            <div class=\"flex-grow-1\">\n                                <p class=\"hint-input\" id=\"condition-result\" contenteditable=\"true\" placeholder=\"Condition Result\" title=\"Condition Result\"></p>\n                            </div>\n                        </div>\n                        <button class=\"btn btn-outline-primary\" data-bind=\"click: addOrUpdateCondition,text: editingCondition() ? 'Update Condition' : 'Add Condition'\"></button>\n                        <ul class=\"list-group mt-3\" data-bind=\"foreach: conditions\">\n                            <li class=\"list-group-item d-flex justify-content-between align-items-center\">\n                                <span data-bind=\"text: conditionDisplay\"></span>\n                                <button class=\"btn btn-sm btn-secondary me-1\" data-bind=\"click: $parent.editCondition\">Edit</button>\n                                <button class=\"btn btn-sm btn-danger\" data-bind=\"click: $parent.removeCondition\">Remove</button>\n                            </li>\n                        </ul>\n\n                        <div class=\"input-group mb-3\" style=\"padding-top: 5px;\">\n                            <span class=\"input-group-text\" style=\"max-height: 32px;\">ELSE</span>\n                            <div class=\"flex-grow-1\">\n                                <p class=\"hint-input\" id=\"condition-else\" contenteditable=\"true\" placeholder=\"Default Result\" title=\"Default Result\"></p>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n        </div>\n\n        <div class=\"col-md-12\">\n            <hr />\n            <a href=\"#\" class=\"btn btn-primary btn-sm\" title=\"Save Custom Formula Field\" data-bind=\"click: saveFormulaField, visible: isFormulaField\">Save</a>\n            <a href=\"#\" class=\"btn btn-sm\" title=\"Custom Field using Formula\" data-bind=\"click: cancelFormulaField, text: isFormulaField()? 'Cancel': 'Customize', css: {'btn-primary': !isFormulaField(), 'btn-danger': isFormulaField}\"></a>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"report-designer-compact\">\n    <div class=\"designer-container compact-designer\" id=\"choose-data-design\" style=\"font-size:12px;\">\n\n      <div class=\"alert alert-info mb-2 py-2 px-3\" style=\"border-left: 4px solid #0d6efd; font-size: 13px;\" data-bind=\"visible: editingSubReportParentId()\">\n          <!-- ko if: _editingSubReportLoading() -->\n          <div class=\"d-flex align-items-center\">\n              <span class=\"fa fa-spinner fa-spin me-2\"></span>\n              <span>Loading sub report...</span>\n          </div>\n          <!-- /ko -->\n          <!-- ko ifnot: _editingSubReportLoading() -->\n          <div class=\"d-flex align-items-center justify-content-between\">\n              <span>\n                  <i class=\"fa fa-info-circle me-1\"></i>\n                  Editing sub report from <strong data-bind=\"text: editingSubReportParentName\"></strong>.\n              </span>\n              <button type=\"button\" class=\"btn btn-sm btn-outline-primary ms-2\" data-bind=\"click: returnToParentReport\">\n                  <i class=\"fa fa-arrow-left me-1\"></i> Back to parent\n              </button>\n          </div>\n          <!-- /ko -->\n      </div>\n\n      <!-- Visualization Toolbar -->\n      <div class=\"card p-1 mb-2\">\n         <div class=\"card-header p-1 d-flex justify-content-between align-items-center\">\n          <span><i class=\"fa fa-file\"></i> Visualization</span>\n          <button id=\"aiToggleBtn\"\n                class=\"btn btn-primary position-fixed bottom-0 end-0 m-3 rounded-circle shadow\"\n                style=\"width: 50px; height: 50px; z-index: 1050;\"\n                title=\"Chat with AI Assistant\"\n                data-bind=\"click: toggleAiChat, visible: appSettings.usePromptBuilder\">\n            <i class=\"fa fa-comment fa-lg\"></i>\n          </button>\n          <div>\n              <button type=\"button\" class=\"btn btn-sm btn-outline-secondary me-1\" data-bind=\"click: function() { RunReport(false, true, ReportMode()=='dashboard'); }\" title=\"Re-run Report\">\n                  <i class=\"fa fa-play\"></i>\n              </button>\n              <!-- Close for existing reports -->\n              <button type=\"button\" class=\"btn btn-sm btn-outline-secondary\" data-bind=\"visible: ReportID(), click: function() {activeDesign(false); if (isExpanded) isExpanded(false);}\" title=\"Close Designer\">\n                  <i class=\"fa fa-times\"></i>\n              </button>\n              <!-- Cancel for new reports -->\n              <button type=\"button\" class=\"btn btn-sm btn-danger\" data-bind=\"visible: !ReportID(), click: function() { if (ReportMode()=='dashboard') $parent.removeNewReport(); else cancelCreateReport(); }\" title=\"Cancel new report\">\n                  <i class=\"fa fa-times\"></i>\n              </button>\n          </div>\n        </div>\n        <div class=\"card-body p-1\" style=\"overflow-x: auto;\">\n          <div data-bind=\"template: 'designer-choose-visual'\"></div>\n        </div>\n      </div>\n\n      <!-- Main Grid -->\n      <div class=\"d-flex flex-row flex-wrap gap-2 compact-filters needs-validation\">\n\n        <!-- Data -->\n        <div class=\"card flex-fill expandable-panel\" id=\"dataPanel\" style=\"max-width: 300px\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('dataPanel')}\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('dataPanel')}\">\n            <i class=\"fa fa-database\"></i> Available Data\n          </div>\n\n          <div class=\"card-body p-1\">\n              <div data-bind=\"template: 'designer-choose-data'\"></div>\n          </div>\n        </div>\n\n        <!-- Selected -->\n        <div class=\"card flex-fill expandable-panel\" id=\"selectedPanel\" style=\"max-width: 400px\"\n         data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('selectedPanel')}\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('selectedPanel')}\">\n            <i class=\"fa fa-table\"></i> Selected data for the Report\n            <a href=\"#\" class=\"small text-muted float-end\"\n               data-bind=\"visible: SelectedFields().length, click:function(){SelectedFields([]);}\">Clear all</a>\n          </div>\n\n          <div class=\"card-body designer-auto-update p-1\">\n                <div style=\"max-height: 300px; overflow-y: auto;\">\n                    <div data-bind=\"template: 'designer-selected-data'\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"card flex-fill expandable-panel\" id=\"subReportsPanel\"\n                data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('subReportsPanel')}, visible: linkedReportFields().length > 0\">\n            <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('subReportsPanel')}\">\n            <i class=\"fa fa-bookmark\"></i> Sub Reports\n            </div>\n            <div class=\"card-body p-1\">\n            <div data-bind=\"template: 'designer-sub-report', data: $data\"></div>\n            </div>\n        </div>\n\n        <div class=\"card flex-fill expandable-panel\" id=\"htmlReportPanel\"\n                data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('htmlReportPanel')}, visible: ReportType()=='Html'\">\n            <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('htmlReportPanel')}\">\n            <i class=\"fa fa-pencil\"></i> Custom Design\n            </div>\n            <div class=\"card-body p-1\">\n            <div data-bind=\"template: 'designer-html', data: $data\"></div>\n            </div>\n        </div>\n\n        <div class=\"card flex-fill expandable-panel\" id=\"jsonFieldsPanel\" data-bind=\"visible: lastPickedField() && lastPickedField().fieldType == 'Json'\">\n            <div class=\"card-body\" data-bind=\"template: 'json-field-picker'\"></div>\n        </div>\n\n        <!-- Field Options Panel -->\n        <div id=\"fieldOptionsPanel\" class=\"card p-2 mt-2 collapse\">\n        <!-- dynamic field settings load here -->\n        </div>\n\n        <!-- Filters -->\n        <div class=\"card flex-fill expandable-panel\" id=\"filtersPanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('filtersPanel')}\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('filtersPanel')}\">\n            <i class=\"fa fa-filter\"></i> Filters\n          </div>\n          <div class=\"card-body p-1 designer-auto-update\" style=\"max-height:300px; overflow-y:auto;\">\n            <div data-bind=\"if:useStoredProc\"><div data-bind=\"template:{name:'filter-parameters'}\"></div></div>\n            <div data-bind=\"ifnot:useStoredProc\"><div data-bind=\"template:{name:'filter-group'}\"></div></div>\n          </div>\n        </div>\n\n        <!-- Sort -->\n        <div class=\"card flex-fill expandable-panel\" id=\"sortPanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('sortPanel')}, hidden: useStoredProc()\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('sortPanel')}\">\n            <i class=\"fa fa-sort\"></i> Sort\n          </div>\n          <div class=\"card-body p-1 designer-auto-update row\">\n            <div data-bind=\"template: 'designer-sort'\"></div>\n          </div>\n        </div>\n\n        <!-- Settings -->\n        <div class=\"card flex-fill expandable-panel\" id=\"settingsPanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('settingsPanel')}\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('settingsPanel')}\">\n            <i class=\"fa fa-gear\"></i>Options\n          </div>\n          <div class=\"card-body\">\n            <div class=\"form-group row\">\n                <label class=\"col-form-label h6\">\n                    <i class=\"fa fa-file\"></i> Report Name\n                </label>\n                <div>\n                    <input type=\"text\" class=\"form-control\" required placeholder=\"Report Name\" data-bind=\"value: ReportName\">\n                </div>\n            </div>\n            <div class=\"form-group row\">\n                <label class=\"control-label h6\">\n                    <i class=\"fa fa-info-circle\"></i> Report Description\n                </label>\n                <div>\n                    <textarea class=\"form-control\" style=\"width: 100%;\" rows=\"3\" placeholder=\"Additional details (optional)\" data-bind=\"value: ReportDescription\"></textarea>\n                </div>\n            </div>\n            <div class=\"checkbox\" data-bind=\"visible: canSaveCurrentReport()\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: SaveReport\">\n                    Save Report\n                </label>\n            </div>\n            <div class=\"checkbox\" data-bind=\"visible: adminMode() && ReportID()\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: isSubReportOnly, click: function() { setTimeout(function() { toggleIsSubReportOnly(); }, 0); return true; }\">\n                    Only use as sub report\n                </label>\n            </div>\n            <div class=\"checkbox\" data-bind=\"visible: adminMode()\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowAdminOnly\">\n                    Hide from reports unless Admin Mode is enabled\n                </label>\n            </div>\n            <div class=\"form-group row\" data-bind=\"visible: SaveReport\">\n                <label class=\"control-label h6\">\n                    <i class=\"fa fa-folder-open\"></i> Choose Folder\n                </label>\n                <div>\n                    <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: Folders, optionsText: function(f) { return f.FolderPath || f.FolderName; }, optionsValue: 'Id', value: FolderID, valueAllowUnset: true\"></select>\n                </div>\n            </div>\n            <hr />\n            <div data-bind=\"template: 'designer-options'\"></div>\n          </div>\n        </div>\n\n        <!-- Schedule -->\n        <div class=\"card flex-fill expandable-panel\" id=\"schedulePanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('schedulePanel')}, visible: SaveReport() && !ko.unwrap(appSettings.showScheduling) && !isSubReportOnly()\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('schedulePanel')}\">\n            <i class=\"fa fa-hourglass\"></i> Schedule\n          </div>\n          <div class=\"card-body p-1 designer-auto-update row\">\n            <div data-bind=\"template: {name: 'report-schedule'}\"></div>\n          </div>\n        </div>\n\n        <!-- Access -->\n        <div class=\"card flex-fill expandable-panel\" id=\"accessPanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('accessPanel')}, visible: adminMode() && !isFormulaField()\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('accessPanel')}\">\n            <i class=\"fa fa-key\"></i>Security\n          </div>\n\n          <div data-bind=\"\" class=\"card card-body\">\n            <div data-bind=\"template: {name: 'manage-access-template', data: manageAccess}\"></div>\n        </div>\n        </div>\n\n      </div>\n\n    </div>\n    <hr />\n    <!-- AI Assistant Popup -->\n    <div id=\"aiPopup\"\n         class=\"position-fixed bottom-0 end-0 m-3 shadow-lg bg-white border rounded-3 d-none d-flex flex-column\"\n         style=\"width: 340px; height: 460px; z-index: 1060; overflow: hidden;\">\n\n        <div class=\"d-flex justify-content-between align-items-center border-bottom bg-light p-2 px-3 flex-shrink-0\">\n            <h6 class=\"mb-0\">\n                <i class=\"fa fa-comments me-1\"></i> AI Report Assistant\n                <span class=\"alert alert-info\" title=\"This feature is still in intial release and might not alwways be accurate. You can turn it off from settings\" style=\"font-size: 10pt; padding: 5px; max-width: 350px; white-space: normal; margin-bottom: 0;\">\n                    <i class=\"fa fa-info-circle\"></i>\n                </span>\n            </h6>\n            <div>\n                <button class=\"btn btn-sm btn-outline-secondary me-2\" data-bind=\"click: clearAiChat\" title=\"Clear Chat\">\n                    <i class=\"fa fa-trash\"></i>\n                </button>\n                <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: toggleAiChat\" title=\"Close\">\n                    <i class=\"fa fa-times\"></i>\n                </button>\n            </div>\n        </div>\n\n        <div id=\"aiChatBody\"\n             class=\"flex-grow-1 overflow-auto p-3\"\n             style=\"background: #f8f9fa;\">\n            <div data-bind=\"foreach: aiMessages\">\n            <div class=\"mb-2\" data-bind=\"css: { 'text-end': role === 'user', 'text-start': role === 'assistant' }\">\n                <div data-bind=\"text: content, css: role === 'user' ? 'bg-primary text-white' : 'bg-light border'\"\n                     class=\"p-2 rounded-3 d-inline-block\"\n                     style=\"max-width: 85%; white-space: pre-wrap;\"></div>\n            </div>\n            </div>\n        </div>\n\n        <div class=\"border-top bg-white p-2 flex-shrink-0\">\n            <div class=\"w-100 mb-1 small text-muted\">\n                💡 Ask things like “Add a column for total orders” or “Show top salesperson this year”\n            </div>\n            <div class=\"form-check mb-2\">\n                <input type=\"checkbox\" class=\"form-check-input\"\n                       data-bind=\"checked: aiAutocompleteDisabled\">\n                <label class=\"form-check-label small text-muted\">\n                    Disable column autocomplete hints\n                    <span title=\"If you disable this, plesae select some data fields in the report designer, choosing data fields to use helps improve results\" style=\"font-size: 10pt; padding: 5px; max-width: 350px; white-space: normal; margin-bottom: 0;\">\n                        <i class=\"fa fa-info-circle\"></i>\n                    </span>\n                </label>\n            </div>\n\n            <div class=\"d-flex align-items-center w-100\">\n                <p id=\"query-input\"\n                   class=\"query-input flex-grow-1 mb-0 p-2 border rounded\"\n                   contenteditable=\"true\"\n                   style=\"min-height: 38px; overflow-y: auto;\"></p>\n                <button class=\"btn btn-primary ms-2\"\n                        data-bind=\"click: sendAiMessage\">\n                    <i class=\"fa fa-paper-plane\"></i>\n                </button>\n            </div>\n        </div>\n    </div>\n\n</script>\n\n<script type=\"text/html\" id=\"report-designer\">\n    <div class=\"modal-dialog modal-dialog-scrollable\" style=\"height: 100vh;\" id=\"report-designer-modal\">\n        <div class=\"modal-content\" style=\"display: flex; flex-direction: column; height: 100%;\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"myModalLabel\">\n                    <a title=\"Need help setting up a report?\" target=\"_blank\" href=\"https://dotnetreport.com/blogs/docs/designing-reports\"><span class=\"fa fa-question-circle\"></span></a>\n                    <!-- ko if: editingSubReportParentId() -->\n                    <i class=\"fa fa-link\"></i> Editing Sub Report\n                    <!-- /ko -->\n                    <!-- ko ifnot: editingSubReportParentId() -->\n                    Design your Report\n                    <!-- /ko -->\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" data-bind=\"click: onModalCloseClicked\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"alert alert-info mb-0 rounded-0 py-2 px-3\" style=\"border-left: 4px solid #0d6efd;\" data-bind=\"visible: editingSubReportParentId()\">\n                <!-- ko if: _editingSubReportLoading() -->\n                <div class=\"d-flex align-items-center py-1\">\n                    <span class=\"fa fa-spinner fa-spin me-2\"></span>\n                    <span>Loading sub report...</span>\n                </div>\n                <!-- /ko -->\n                <!-- ko ifnot: _editingSubReportLoading() -->\n                <div class=\"d-flex align-items-center justify-content-between\">\n                    <span>\n                        <i class=\"fa fa-info-circle me-1\"></i>\n                        You are editing a sub report linked from <strong data-bind=\"text: editingSubReportParentName\"></strong>.\n                    </span>\n                    <button type=\"button\" class=\"btn btn-sm btn-outline-primary ms-2\" data-bind=\"click: returnToParentReport\">\n                        <i class=\"fa fa-arrow-left me-1\"></i> Back to parent report\n                    </button>\n                </div>\n                <small class=\"text-muted\">When you save, you'll be returned to the parent report. You can also click \"Back to parent report\" to return without saving.</small>\n                <!-- /ko -->\n            </div>\n            <div class=\"modal-body needs-validation\" style=\"overflow-y: hidden; flex-grow: 1; display: flex; flex-direction: column;\">\n               <div class=\"row flex-grow-1\" style=\"min-height: 0;\">\n                    <!-- LEFT PANEL -->\n                    <div class=\"col-md-4 h-100\" style=\"overflow-y: auto;\">\n\n                        <!-- Designer Toolbar Toggles -->\n                        <div class=\"d-flex align-items-center flex-wrap gap-2 mb-2\">\n                            <div class=\"form-check form-switch mb-0\">\n                                <input class=\"form-check-input\" type=\"checkbox\" role=\"switch\" id=\"livePreviewSwitch\" data-bind=\"checked: activeDesign\">\n                                <label class=\"form-check-label fw-semibold\" for=\"livePreviewSwitch\">\n                                    <i class=\"fa fa-bolt text-warning\"></i> Live Preview\n                                </label>\n                            </div>\n                            <div class=\"form-check form-switch mb-0\" data-bind=\"visible: hasAiConfigured()\">\n                                <input class=\"form-check-input\" type=\"checkbox\" role=\"switch\" id=\"aiAssistSwitch\" data-bind=\"checked: aiAssistantEnabled\">\n                                <label class=\"form-check-label small\" for=\"aiAssistSwitch\">\n                                    <i class=\"fa fa-magic text-primary\"></i> AI Assist <span style=\"vertical-align: middle;\" title=\"This feature is still in intial release and might not alwways be accurate. You can turn it off from settings\" ><i class=\"fa fa-info-circle\"></i></span>\n                                </label>\n                            </div>                            \n                            <div class=\"form-check form-switch mb-0\" data-bind=\"visible: ko.unwrap(appSettings.showDesignerHints)\">\n                                <input class=\"form-check-input\" type=\"checkbox\" role=\"switch\" id=\"hintsSwitch\" data-bind=\"checked: showHints\">\n                                <label class=\"form-check-label small\" for=\"hintsSwitch\">\n                                    <i class=\"fa fa-question-circle text-info\"></i> Tips\n                                </label>\n                            </div>\n                            <button class=\"btn btn-sm btn-outline-primary ms-auto\" data-bind=\"visible: activeDesign(), click: function() { RunReport(false, true); }\" title=\"Re-run Report\">\n                                <i class=\"fa fa-play\"></i> Run\n                            </button>\n                        </div>\n\n                        <!-- AI Assistant Panel (visible in both modes) -->\n                        <div class=\"card mb-2 designer-panel ai-assistant-panel\" data-bind=\"visible: aiAssistantEnabled()\" style=\"display:none; font-size: 12px;\">\n                            <div class=\"card-header p-2 d-flex align-items-center bg-primary text-white\" style=\"cursor:pointer;\">\n                                <i class=\"fa fa-magic me-1\"></i> AI Report Builder\n                                <span class=\"badge bg-light text-primary ms-1\" data-bind=\"visible: aiReportApplied()\" style=\"font-size:9px;\">Modified</span>\n                                <button class=\"btn btn-sm btn-link text-white ms-auto p-0\" data-bind=\"click: clearAiAssistant\" title=\"Clear conversation\"><i class=\"fa fa-trash\"></i></button>\n                            </div>\n                            <div class=\"card-body p-0\">\n                                <!-- Messages -->\n                                <div class=\"ai-assist-messages\" data-bind=\"foreach: aiAssistantMessages\" style=\"max-height: 350px; overflow-y: auto; padding: 8px;\">\n                                    <div class=\"mb-2\" data-bind=\"css: { 'text-end': role === 'user', 'text-start': role !== 'user' }\">\n                                        <div class=\"ai-msg-bubble d-inline-block p-2 rounded-3\" style=\"max-width: 90%; white-space: pre-wrap; font-size: 12px;\"\n                                             data-bind=\"text: content, css: role === 'user' ? 'bg-primary text-white' : 'bg-light border'\"></div>\n                                    </div>\n                                </div>\n                                <!-- Loading -->\n                                <div class=\"text-center p-2\" data-bind=\"visible: aiAssistantLoading()\">\n                                    <div class=\"d-flex align-items-center justify-content-center gap-2\">\n                                        <i class=\"fa fa-spinner fa-spin text-primary\"></i>\n                                        <span class=\"small text-muted\">Building your report...</span>\n                                    </div>\n                                </div>\n                                <!-- Quick Actions (shown when no messages) -->\n                                <div class=\"p-2\" data-bind=\"visible: aiAssistantMessages().length === 0 && !aiAssistantLoading()\">\n                                    <div class=\"small text-muted mb-1\" style=\"font-style: italic;\">\n                                        Ask me anything about your report design, or click a quick action below.\n                                    </div>\n                                    <div class=\"small text-muted mb-2\">\n                                        <i class=\"fa fa-magic text-primary\"></i> Tell me what report to build, or try:\n                                    </div>\n                                    <div class=\"small text-muted mb-2\" style=\"background: #f0f7ff; padding: 6px 8px; border-radius: 4px; border-left: 3px solid #0d6efd;\">\n                                        <i class=\"fas fa-lightbulb text-warning\"></i> <strong>Tip:</strong> For best results, mention the data table name (e.g., \"build a report using the Orders table\")\n                                    </div>\n                                    <div class=\"d-flex flex-wrap gap-1\">\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function(){ aiAssistantInput('Build a sales summary report with a bar chart'); sendAiAssistantMessage(); }\">\n                                            <i class=\"fa fa-bar-chart\"></i> Sales summary\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function(){ aiAssistantInput('Create an invoice report using HTML template'); sendAiAssistantMessage(); }\">\n                                            <i class=\"fa fa-file-text-o\"></i> Invoice report\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function(){ aiAssistantInput('Show me a trend line chart of data over time'); sendAiAssistantMessage(); }\">\n                                            <i class=\"fa fa-line-chart\"></i> Trend analysis\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function(){ aiAssistantInput('Create a KPI dashboard widget showing a key metric'); sendAiAssistantMessage(); }\">\n                                            <i class=\"fa fa-tachometer\"></i> KPI widget\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: getAiRecommendation, visible: SelectedFields().length > 0\">\n                                            <i class=\"fas fa-lightbulb\"></i> Recommend chart\n                                        </button>\n                                    </div>\n                                </div>\n                                <!-- Chat Input -->\n                                <div class=\"d-flex align-items-center p-2 border-top\">\n                                    <input type=\"text\" class=\"form-control form-control-sm me-1\"\n                                           placeholder=\"Describe the report you want to build...\"\n                                           data-bind=\"value: aiAssistantInput, valueUpdate: 'afterkeydown',\n                                                      event: { keypress: function(d,e){ if(e.keyCode===13){ sendAiAssistantMessage(); return false; } return true; } },\n                                                      attr: { disabled: aiAssistantLoading() }\">\n                                    <button class=\"btn btn-sm btn-primary\" data-bind=\"click: sendAiAssistantMessage, enable: aiAssistantInput() && !aiAssistantLoading()\">\n                                        <i class=\"fa fa-paper-plane\"></i>\n                                    </button>\n                                </div>\n                                <!-- Follow-up suggestions (shown after AI applies a report) -->\n                                <div class=\"p-2 border-top\" data-bind=\"visible: aiReportApplied() && !aiAssistantLoading() && aiAssistantMessages().length > 0\" style=\"display:none;\">\n                                    <div class=\"small text-muted mb-1\"><i class=\"fa fa-comments\"></i> Follow-up:</div>\n                                    <div class=\"d-flex flex-wrap gap-1\">\n                                        <button class=\"btn btn-sm btn-outline-primary\" data-bind=\"click: function(){ aiAssistantInput('Add a filter for this year'); sendAiAssistantMessage(); }\">\n                                            + Filter this year\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-primary\" data-bind=\"click: function(){ aiAssistantInput('Change to a bar chart'); sendAiAssistantMessage(); }\">\n                                            Change chart type\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-primary\" data-bind=\"click: function(){ aiAssistantInput('Break it down by month'); sendAiAssistantMessage(); }\">\n                                            By month\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-primary\" data-bind=\"click: function(){ aiAssistantInput('Add a top 10 limit'); sendAiAssistantMessage(); }\">\n                                            Top 10\n                                        </button>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- ==================== STANDARD MODE (activeDesign OFF) ==================== -->\n                        <div data-bind=\"visible: !activeDesign()\">\n                            <div class=\"card card-body\" id=\"choose-data-card\" style=\"min-height: calc(100vh - 200px);\">\n                                <div class=\"form-group row align-items-center\">\n                                    <label class=\"col-sm-4 col-form-label h6\">\n                                        <i class=\"fa fa-file\"></i> Report Name\n                                    </label>\n                                    <div class=\"col-sm-8\">\n                                        <input type=\"text\" class=\"form-control\" required placeholder=\"Report Name\" data-bind=\"value: ReportName\">\n                                    </div>\n                                </div>\n                                <hr />\n                                <h5><span class=\"fa fa-database\"></span>&nbsp;Choose Data for Report</h5>\n                                <div data-bind=\"template: 'designer-choose-data'\"></div>\n                            </div>\n                            <br />\n                            <div class=\"card card-body\">\n                                <div class=\"form-group row\">\n                                    <label class=\"control-label h6\">\n                                        <i class=\"fa fa-info-circle\"></i> Report Description\n                                    </label>\n                                    <div>\n                                        <textarea class=\"form-control\" style=\"width: 100%;\" rows=\"3\" placeholder=\"Additional details (optional)\" data-bind=\"value: ReportDescription\"></textarea>\n                                    </div>\n                                </div>\n                                <div class=\"checkbox\" data-bind=\"visible: canSaveCurrentReport()\">\n                                    <label>\n                                        <input type=\"checkbox\" data-bind=\"checked: SaveReport\">\n                                        Save Report\n                                    </label>\n                                </div>\n                                <div class=\"checkbox\" data-bind=\"visible: adminMode() && ReportID()\">\n                                    <label>\n                                        <input type=\"checkbox\" data-bind=\"checked: isSubReportOnly, click: function() { setTimeout(function() { toggleIsSubReportOnly(); }, 0); return true; }\">\n                                        Only use as sub report\n                                    </label>\n                                </div>\n                                <div class=\"checkbox\" data-bind=\"visible: adminMode()\">\n                                    <label>\n                                        <input type=\"checkbox\" data-bind=\"checked: ShowAdminOnly\">\n                                        Hide from reports unless Admin Mode is enabled\n                                    </label>\n                                </div>\n                                <div class=\"form-group row\" data-bind=\"visible: SaveReport\">\n                                    <label class=\"control-label h6\">\n                                        <i class=\"fa fa-folder-open\"></i> Choose Folder\n                                    </label>\n                                    <div>\n                                        <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: Folders, optionsText: function(f) { return f.FolderPath || f.FolderName; }, optionsValue: 'Id', value: FolderID, valueAllowUnset: true\"></select>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- ==================== LIVE PREVIEW MODE (activeDesign ON) ==================== -->\n                        <div data-bind=\"visible: activeDesign()\" class=\"live-preview-designer\" style=\"font-size: 12px; display: none;\">\n\n                            <!-- Report Name (always visible at top in live preview) -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-body p-2\">\n                                    <div class=\"form-group row align-items-center mb-0\">\n                                        <label class=\"col-sm-4 col-form-label\"><i class=\"fa fa-file\"></i> Report Name</label>\n                                        <div class=\"col-sm-8\">\n                                            <input type=\"text\" class=\"form-control form-control-sm\" required placeholder=\"Report Name\" data-bind=\"value: ReportName\">\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <!-- Data -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-dataPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-database\"></i> Available Data\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>1. Pick a Table</b> from the dropdown &mdash; this is your data source.<br><b>2. Check fields</b> to add them to your report.<br><b>3. Join Tables:</b> If you need data from multiple tables, select additional tables and they&rsquo;ll be auto-joined if relationships exist.<br><b>Dynamic vs Stored Proc:</b> Dynamic builds SQL from your selections; Stored Proc calls a predefined database procedure.\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-dataPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-dataPanel')\">\n                                    <div data-bind=\"template: 'designer-choose-data'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Visualization -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-vizPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-bar-chart\"></i> Visualization\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>List:</b> Raw data rows &mdash; detail reports, exports.<br><b>Summary:</b> Grouped with totals (needs aggregate functions like Sum/Count).<br><b>Bar:</b> Compare categories side by side. Use <i>Stacked</i> or <i>Horizontal</i> in chart options.<br><b>Pie:</b> Proportions of a whole (best with &lt;8 slices). Enable <i>Donut</i> in options.<br><b>Line:</b> Trends over time. Great with date fields on x-axis.<br><b>KPI:</b> Single big number metric (needs one numeric field with aggregate).<br><b>More...</b> opens Scatter, Gauge, Funnel, Radar, and more.\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-vizPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-vizPanel')\" style=\"overflow-x: auto;\">\n                                    <div data-bind=\"template: 'designer-choose-visual'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Selected Data -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-selectedPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-table\"></i> Selected Data\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>Aggregate Functions</b> (for Summary/Charts):<br>&bull; <b>Group:</b> Group rows by this field (e.g., by Month, by Category)<br>&bull; <b>Sum:</b> Add up all values<br>&bull; <b>Count:</b> Count number of rows<br>&bull; <b>Avg:</b> Calculate average<br>&bull; <b>Min/Max:</b> Find smallest/largest value<br><br><b>Group in Graph:</b> Creates separate series/colors in charts (e.g., one line per product).<br><b>Field Settings</b> (click column &crarr; icon): Format as Currency/Percentage, set alignment, decimal places, conditional formatting, custom labels, and more.\"></i>\n                                    <a href=\"#\" class=\"small text-muted float-end me-3\" data-bind=\"visible: SelectedFields().length, click: function(){SelectedFields([]);}\">Clear all</a>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-selectedPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-auto-update\" data-bind=\"visible: !panels.isCollapsed('lp-selectedPanel')\" style=\"max-height: 300px; overflow-y: auto;\">\n                                    <div data-bind=\"template: 'designer-selected-data'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- JSON Field Picker -->\n                            <div data-bind=\"template: 'json-field-picker'\"></div>\n\n                            <!-- Sub Reports -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: linkedReportFields().length > 0\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-subReportsPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-bookmark\"></i> Sub Reports\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-subReportsPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-subReportsPanel')\">\n                                    <div data-bind=\"template: 'designer-sub-report'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- HTML Design -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: ReportType()=='Html'\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-htmlPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-pencil\"></i> Custom Design\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-htmlPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-htmlPanel')\">\n                                    <div data-bind=\"template: 'designer-html'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Filters -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-filtersPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-filter\"></i> Filters\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>Filter Operators:</b><br>&bull; <b>=, &gt;, &lt;, &ge;, &le;:</b> Standard comparisons<br>&bull; <b>Between:</b> Range (e.g., dates from/to)<br>&bull; <b>Like:</b> Pattern match (use % as wildcard)<br>&bull; <b>In / Not In:</b> Match a list of values<br>&bull; <b>Is Blank / Is Not Blank:</b> Null checks<br><br><b>Date Shortcuts:</b> Today, This Week, This Month, This Year, Last 30 Days, Last Year<br><br><b>AND/OR Logic:</b> Combine multiple filters. Add filter groups for complex logic like (A AND B) OR (C AND D).<br><br><b>Allow Filters on Report:</b> Check this to let viewers add their own filters when viewing.\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-filtersPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-auto-update\" data-bind=\"visible: !panels.isCollapsed('lp-filtersPanel')\" style=\"max-height: 300px; overflow-y: auto;\">\n                                    <div data-bind=\"visible: useStoredProc\"><div data-bind=\"template: {name: 'filter-parameters'}\"></div></div>\n                                    <div data-bind=\"visible: !useStoredProc()\"><div data-bind=\"template: {name: 'filter-group'}\"></div></div>\n                                    <div class=\"checkbox\">\n                                        <label>\n                                            <input type=\"checkbox\" data-bind=\"checked: EditFiltersOnReport\" />\n                                            Allow setting up and saving filters on Report\n                                        </label>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <!-- Sort -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: !useStoredProc()\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-sortPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-sort\"></i> Sort\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>Sort Order:</b> Drag fields to set priority. First sort is primary, second is tie-breaker, etc.<br><b>Ascending:</b> A&rarr;Z, 1&rarr;9, oldest&rarr;newest<br><b>Descending:</b> Z&rarr;A, 9&rarr;1, newest&rarr;oldest<br><br><b>For Charts:</b> Sort controls x-axis order (e.g., sort by date for chronological, by value for ranked bars).<br><b>Top N:</b> Combine sort descending + page size to show &ldquo;Top 10&rdquo; results.\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-sortPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-auto-update\" data-bind=\"visible: !panels.isCollapsed('lp-sortPanel')\">\n                                    <div data-bind=\"template: 'designer-sort'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Settings & Options -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-settingsPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-gear\"></i> Options\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>Options Available:</b><br>&bull; <b>Show Total Row:</b> Adds a totals row at the bottom (Sum/Count of numeric columns)<br>&bull; <b>Page Size:</b> Number of rows per page (affects List/Summary reports)<br>&bull; <b>Show Data with Graph:</b> Display both the chart AND a data table below it<br>&bull; <b>Max Records:</b> Limit total records returned (0 = no limit)<br>&bull; <b>No Header Sort:</b> Disable column header click-to-sort on the report page<br>&bull; <b>Chart Options:</b> Colors, legend position, axis labels, gridlines, stacking, horizontal orientation\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-settingsPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-options-wrap\" data-bind=\"visible: !panels.isCollapsed('lp-settingsPanel')\">\n                                    <div class=\"form-group row mb-2\">\n                                        <label class=\"control-label\"><i class=\"fa fa-info-circle\"></i> Description</label>\n                                        <div>\n                                            <textarea class=\"form-control form-control-sm\" rows=\"2\" placeholder=\"Optional\" data-bind=\"value: ReportDescription\"></textarea>\n                                        </div>\n                                    </div>\n                                    <div class=\"checkbox\" data-bind=\"visible: canSaveCurrentReport()\">\n                                        <label><input type=\"checkbox\" data-bind=\"checked: SaveReport\"> Save Report</label>\n                                    </div>\n                                    <div class=\"checkbox\" data-bind=\"visible: adminMode() && ReportID()\">\n                                        <label><input type=\"checkbox\" data-bind=\"checked: isSubReportOnly, click: function() { setTimeout(function() { toggleIsSubReportOnly(); }, 0); return true; }\"> Only use as sub report</label>\n                                    </div>\n                                    <div class=\"checkbox\" data-bind=\"visible: adminMode()\">\n                                       <label><input type=\"checkbox\" data-bind=\"checked: ShowAdminOnly\"> </label>\n                                        Hide from reports unless Admin Mode is enabled\n                                    </div>\n                                    <div class=\"form-group row mb-2\" data-bind=\"visible: SaveReport\">\n                                        <label class=\"control-label\"><i class=\"fa fa-folder-open\"></i> Folder</label>\n                                        <div>\n                                            <select class=\"form-select form-select-sm\" style=\"width: 100%;\" data-bind=\"options: Folders, optionsText: function(f) { return f.FolderPath || f.FolderName; }, optionsValue: 'Id', value: FolderID, valueAllowUnset: true\"></select>\n                                        </div>\n                                    </div>\n                                    <hr class=\"my-1\" />\n                                    <div data-bind=\"visible: !useStoredProc()\">\n                                        <div data-bind=\"template: 'designer-options'\"></div>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <!-- Header & Footer -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: SaveReport\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-headerFooterPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-window-maximize\"></i> Header &amp; Footer\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-headerFooterPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-headerFooterPanel')\">\n                                    <div data-bind=\"template: 'designer-header-footer'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Schedule -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: SaveReport() && !ko.unwrap(appSettings.showScheduling) && !isSubReportOnly()\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-schedulePanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-hourglass\"></i> Schedule\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-schedulePanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-auto-update\" data-bind=\"visible: !panels.isCollapsed('lp-schedulePanel')\">\n                                    <div data-bind=\"template: {name: 'report-schedule'}\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Access -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: adminMode()\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-accessPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-key\"></i> Security\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-accessPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-accessPanel')\">\n                                    <div data-bind=\"template: {name: 'manage-access-template', data: manageAccess}\"></div>\n                                </div>\n                            </div>\n\n                        </div>\n                    </div>\n\n                    <!-- RIGHT PANEL -->\n                    <div class=\"col-md-8 h-100\" style=\"overflow-y: auto;\">\n\n                        <!-- ==================== STANDARD MODE (activeDesign OFF) ==================== -->\n                        <div data-bind=\"visible: !activeDesign()\">\n                            <div class=\"card card-body\">\n                                <h5><span class=\"fa fa-file\"></span>&nbsp;Choose Visualization</h5>\n                                <div style=\"overflow-x: auto; white-space: nowrap;\">\n                                    <div data-bind=\"template: 'designer-choose-visual'\"></div>\n                                </div>\n                            </div>\n                            <div id=\"customFunctionSection\" data-bind=\"visible: isFunctionField() && ReportType() === 'List'\" class=\"custom-field-design\">\n                                <br />\n                                <div class=\"card\">\n                                    <div class=\"card-header\"><b>Build Custom Field</b></div>\n                                    <div class=\"card-body\" data-bind=\"template: 'custom-function-designer'\"></div>\n                                </div>\n                                <div class=\"clearfix\"></div>\n                            </div>\n                            <div data-bind=\"template: 'json-field-picker'\"></div>\n                            <div id=\"customFieldSection\" data-bind=\"visible: isFormulaField\" class=\"custom-field-design\">\n                                <br />\n                                <div class=\"card\">\n                                    <div class=\"card-header\"><b>Build Custom Field</b></div>\n                                    <div class=\"card-body\" data-bind=\"template: 'custom-field-designer'\"></div>\n                                </div>\n                                <div class=\"clearfix\"></div>\n                            </div>\n                            <br />\n                            <div class=\"card card-body\">\n                                <div class=\"row\">\n                                    <h5 class=\"col-8 float-start\"><span class=\"fa fa-table\"></span>&nbsp;Selected data for the Report</h5>\n                                    <div class=\"col-4 float-end right-align\">\n                                        <a href=\"#\" class=\"small text-muted\" data-bind=\"visible: SelectedFields().length, click: function() {SelectedFields([]);}\">Clear all</a>\n                                    </div>\n                                </div>\n                                <div data-bind=\"template: 'designer-selected-data'\"></div>\n                            </div>\n                            <div data-bind=\"visible: linkedReportFields().length > 0\">\n                                <br />\n                                <div class=\"card mb-4\">\n                                    <div class=\"card-header bg-light\">\n                                        <h5 class=\"mb-0\"><i class=\"fa fa-bookmark\"></i> Include Sub Reports</h5>\n                                    </div>\n                                    <div class=\"card-body\">\n                                        <div data-bind=\"template: 'designer-sub-report'\"></div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div data-bind=\"visible: ReportType()=='Html'\">\n                                <br />\n                                <div class=\"card mb-4\">\n                                    <div class=\"card-header bg-light\">\n                                        <h5 class=\"mb-0\"><i class=\"fa fa-pencil\"></i> Design your Report</h5>\n                                    </div>\n                                    <div class=\"card-body\">\n                                        <div data-bind=\"template: 'designer-html'\"></div>\n                                    </div>\n                                </div>\n                            </div>\n                            <br />\n                            <div class=\"card card-body\">\n                                <h5><span class=\"fa fa-filter\"></span>&nbsp;Choose Filters</h5>\n                                <div class=\"row\" style=\"padding: 10px 10px; overflow-x: auto;\">\n                                    <div data-bind=\"visible: useStoredProc\" class=\"col-md-12\">\n                                        <div data-bind=\"template: {name: 'filter-parameters'}\"></div>\n                                    </div>\n                                    <div data-bind=\"visible: !useStoredProc()\" class=\"col-md-12\">\n                                        <div data-bind=\"template: {name: 'filter-group'}\"></div>\n                                    </div>\n                                    <div class=\"checkbox col-12\">\n                                        <label>\n                                            <input type=\"checkbox\" data-bind=\"checked: EditFiltersOnReport\" />\n                                            Allow setting up and saving filters on Report\n                                        </label>\n                                    </div>\n                                    <br />\n                                </div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: !useStoredProc()\" class=\"card card-body\">\n                                <h5><span class=\"fa fa-sort\"></span>&nbsp;Choose Sorting</h5>\n                                <div data-bind=\"template: 'designer-sort'\"></div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: SaveReport() && !ko.unwrap(appSettings.showScheduling) && !isSubReportOnly()\" class=\"card card-body\">\n                                <h5><span class=\"fa fa-hourglass\"></span>&nbsp;Choose Schedule</h5>\n                                <div style=\"padding: 10px 10px\" data-bind=\"visible: SaveReport\">\n                                    <div data-bind=\"template: {name: 'report-schedule'}\"></div>\n                                </div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: !useStoredProc()\">\n                                <div class=\"card card-body\">\n                                    <div data-bind=\"template: 'designer-options'\"></div>\n                                </div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: SaveReport\" class=\"card card-body\">\n                                <h5><span class=\"fa fa-window-maximize\"></span>&nbsp;Header &amp; Footer</h5>\n                                <div data-bind=\"template: 'designer-header-footer'\"></div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: adminMode\" class=\"card card-body\">\n                                <div data-bind=\"template: {name: 'manage-access-template', data: manageAccess}\"></div>\n                            </div>\n                        </div>\n\n                        <!-- ==================== LIVE PREVIEW MODE (activeDesign ON) ==================== -->\n                        <div data-bind=\"css: {'d-flex': activeDesign(), 'd-none': !activeDesign()}\" class=\"live-preview-area flex-column\" style=\"height: 100%;\">\n                            <!-- Custom Field (shown above preview when active) -->\n                            <div data-bind=\"visible: isFormulaField()\" class=\"mb-2\">\n                                <div class=\"card custom-field-design\">\n                                    <div class=\"card-header py-1\"><i class=\"fa fa-magic\"></i> Build Custom Field</div>\n                                    <div class=\"card-body\" data-bind=\"template: 'custom-field-designer'\"></div>\n                                </div>\n                            </div>\n                            <!-- Custom Function (shown above preview when active) -->\n                            <div data-bind=\"visible: isFunctionField() && ReportType() === 'List'\" class=\"mb-2\">\n                                <div class=\"card custom-field-design\">\n                                    <div class=\"card-header py-1\"><i class=\"fa fa-magic\"></i> Build Custom Function</div>\n                                    <div class=\"card-body\" data-bind=\"template: 'custom-function-designer'\"></div>\n                                </div>\n                            </div>\n                            <div class=\"card flex-grow-1 d-flex flex-column\" style=\"min-height: 0;\">\n                                <div class=\"card-header py-2 d-flex align-items-center justify-content-between bg-light\">\n                                    <span><i class=\"fa fa-desktop\"></i> Live Preview</span>\n                                    <span class=\"text-muted small\" data-bind=\"visible: ReportName()\">\n                                        <span data-bind=\"text: ReportName\"></span>\n                                    </span>\n                                </div>\n                                <div class=\"card-body flex-grow-1\" style=\"overflow-y: auto; min-height: 0;\">\n                                    <div data-bind=\"if: typeof CanEdit === 'function' && CanEdit() && ReportType()!='Html' && ReportType()!='Single'\">\n                                        <div data-bind=\"template: 'chart-settings', data: $data\"></div>\n                                    </div>\n                                    <div data-bind=\"if: typeof CanEdit === 'function' && CanEdit() && ReportType()=='Single'\">\n                                        <div data-bind=\"template: 'kpi-settings', data: $data\"></div>\n                                    </div>\n                                    <p data-bind=\"html: ReportDescription, visible: ReportDescription\"></p>\n                                    <div data-bind=\"with: ReportResult\" class=\"small\">\n                                        <div data-bind=\"visible: !ReportData()\">\n                                            <div class=\"report-spinner\"></div>\n                                        </div>\n                                        <div data-bind=\"template: 'report-template', data: $data\"></div>\n                                    </div>\n                                </div>\n                                <div class=\"card-footer py-1\">\n                                    <div class=\"small d-flex align-items-center justify-content-between\" data-bind=\"with: pager\">\n                                        <div data-bind=\"visible: totalRecords() > 1 && $parent.ReportType() != 'Single'\">\n                                            <span data-bind=\"text: 'Total Records: ' + totalRecords()\"></span>\n                                        </div>\n                                        <div data-bind=\"visible: pages() > 1 && $parent.ReportType() != 'Single'\">\n                                            <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button class=\"btn btn-primary\" data-bind=\"visible: adminMode, click: RunReportSqlPreview\">\n                    <i class=\"fa fa-code\"></i> Preview Report Code\n                </button>\n                <button class=\"btn btn-outline-secondary\" type=\"button\" data-bind=\"visible: !SaveReport() || !ReportID(), click: startOverReport\" title=\"Clear everything and start a new report\">\n                    <i class=\"fa fa-refresh\"></i> Start Over\n                </button>\n                <a href=\"#\" class=\"btn btn-danger\" data-bind=\"click: cancelCreateReport\">Cancel editing Report</a>\n                <button class=\"btn btn-primary\" type=\"button\" data-bind=\"visible: SaveReport() && canSaveCurrentReport(), click: SaveWithoutRun, disable: savingReport() || savingAndRunning()\" style=\"padding-right: 10px;\">\n                    <!-- ko if: savingReport() --><span class=\"fa fa-spinner fa-spin me-1\"></span>Saving...<!-- /ko -->\n                    <!-- ko ifnot: savingReport() -->Save Report<!-- /ko -->\n                </button>\n                <button class=\"btn btn-primary\" type=\"button\" data-bind=\"click: SaveAndRunReport, visible: !editingSubReportParentId(), disable: savingReport() || savingAndRunning()\">\n                    <!-- ko if: savingAndRunning() --><span class=\"fa fa-spinner fa-spin me-1\"></span>Saving...<!-- /ko -->\n                    <!-- ko ifnot: savingAndRunning() --><!-- ko text: SaveReport() && canSaveCurrentReport()? 'Save & Run Report': 'Run Report' --><!-- /ko --><!-- /ko -->\n                </button>\n            </div>\n\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"chart-settings\">\n    <div class=\"chart-container float-end\">\n        <button class=\"btn btn-light btn-sm d-flex align-items-center mt-2 chart-settings-btn\"\n                data-bind=\"click: toggleChartSettings\" title=\"Report settings\">\n            <i class=\"fa fa-cog\"></i>\n        </button>\n\n        <div class=\"chart-settings-panel border p-2 shadow-sm bg-light\" data-bind=\"visible: showSettings\">\n            <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                <button class=\"btn btn-sm btn-close\" data-bind=\"click: toggleChartSettings\"></button>\n                <h6 class=\"mb-0\">Report Settings</h6>\n            </div>\n             <ul class=\"nav nav-tabs nav-sm mb-2 small\" data-bind=\"visible: ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line'\">\n                <li class=\"nav-item\">\n                    <a class=\"nav-link\"\n                       data-bs-toggle=\"tab\"\n                       data-bind=\"attr: { href: '#chartTab-' + ReportID() }, css: { active: ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line' }\">\n                        Chart\n                    </a>\n                </li>\n                <li class=\"nav-item\">\n                    <a class=\"nav-link\"\n                       data-bs-toggle=\"tab\"\n                       data-bind=\"attr: { href: '#tableTab-' + ReportID() }, css: { active: !(ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line') }\">\n                        Table\n                    </a>\n                </li>\n            </ul>\n            <div class=\"tab-content small\">\n                <div class=\"tab-pane fade\"\n                     data-bind=\"attr: { id: 'chartTab-' + ReportID() }, css: { 'show active': ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line' }\">\n                    <div class=\"mb-2\">\n                        <div class=\"btn-group\" role=\"group\" data-bind=\"visible: ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line'\">\n                            <button type=\"button\" class=\"btn btn-light\" data-bs-toggle=\"tooltip\" title=\"Bar Chart\"\n                                    data-bind=\"css: { 'active': ReportType() === 'Bar' }, click: function() { ReportType('Bar'); }\">\n                                <span class=\"fa fa-bar-chart\"></span>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-light\" data-bs-toggle=\"tooltip\" title=\"Pie Chart\"\n                                    data-bind=\"css: { 'active': ReportType() === 'Pie' }, click: function() { ReportType('Pie'); }\">\n                                <span class=\"fa fa-pie-chart\"></span>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-light\" data-bs-toggle=\"tooltip\" title=\"Line Chart\"\n                                    data-bind=\"css: { 'active': ReportType() === 'Line' }, click: function() { ReportType('Line'); }\">\n                                <span class=\"fa fa-line-chart\"></span>\n                            </button>\n                        </div>\n                    </div>\n                    <div data-bind=\"visible: ReportType()=='Bar'\">\n                        <div class=\"form-group row\">\n                            <div class=\"checkbox col-6\">\n                                <label><input type=\"checkbox\" data-bind=\"checked: barChartHorizontal\" /> Horizontal</label>\n                            </div>\n                            <div class=\"checkbox col-6\">\n                                <label><input type=\"checkbox\" data-bind=\"checked: barChartStacked\" /> Stacked</label>\n                            </div>\n                        </div>\n                    </div>\n                    <div data-bind=\"visible: ReportType()=='Pie'\">\n                        <div class=\"form-group row\">\n                            <div class=\"checkbox col-6\">\n                                <label><input type=\"checkbox\" data-bind=\"checked: pieChartDonut\" /> Donut</label>\n                            </div>\n                        </div>\n                    </div>\n                    <div data-bind=\"visible: ReportType()=='Line'\">\n                        <div class=\"form-group row\">\n                            <div class=\"checkbox col-6\">\n                                <label><input type=\"checkbox\" data-bind=\"checked: lineChartArea\" /> Area</label>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Background Color</label>\n                        <div class=\"d-flex align-items-center flex-wrap\">\n                            <input type=\"color\" class=\"color-picker\" data-bind=\"value: chartOptions().backgroundColor, attr: { placeholder: 'Select' }, event: { change: updateChart }\">\n                        </div>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Font Color</label>\n                        <div class=\"d-flex align-items-center flex-wrap\">\n                            <input type=\"color\" class=\"color-picker\" data-bind=\"value: chartOptions().fontColor, attr: { placeholder: 'Select' }, event: { change: updateChart }\">\n                        </div>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Series Colors</label>\n                        <div class=\"d-flex flex-wrap\" data-bind=\"foreach: chartOptions().seriesColors\">\n                            <div class=\"color-box me-2\">\n                                <input type=\"color\" class=\"color-picker\"\n                                       data-bind=\"value: $data, event: { input: function(data, event) { $parent.updateSeriesColor($index(), event.target.value); } }\">\n                                <button class=\"btn btn-sm btn-danger remove-color\" data-bind=\"click: $parent.removeSeriesColor\">&times;</button>\n                            </div>\n                        </div>\n                        <button class=\"color-box btn btn-sm btn-secondary\" data-bind=\"click: addSeriesColor\" title=\"Add Series Color\" style=\"margin-top: -7px;\">\n                            <i class=\"fa fa-plus\"></i>\n                        </button>\n                    </div>\n                    <div class=\"d-flex justify-content-between mb-1\">\n                        <div>\n                            <label class=\"form-label small\">Legend Position</label>\n                            <select class=\"form-select form-select-sm\" data-bind=\"value: chartOptions().legendPosition, event: { change: function(data, $event) { updateLegend($event.target.value); } }\">\n                                <option value=\"top\">Top</option>\n                                <option value=\"right\">Right</option>\n                                <option value=\"bottom\">Bottom</option>\n                                <option value=\"left\">Left</option>\n                                <option value=\"none\">None</option>\n                            </select>\n                        </div>\n                        <div>\n                            <label class=\"form-label small\">Font Size</label>\n                            <input type=\"number\" class=\"form-control form-control-sm font-size-input\" data-bind=\"value: chartOptions().fontSize, event: { change: updateChart }\">\n                        </div>\n                    </div>\n                    <div data-bind=\"visible: ReportType()!='Pie'\">\n                        <div class=\"form-check form-switch small mb-1\">\n                            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: chartOptions().showXAxisLabel, event: { change: updateChart }\">\n                            <label class=\"form-check-label\">X-Axis Label</label>\n                        </div>\n                        <div class=\"form-check form-switch small mb-1\">\n                            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: chartOptions().showYAxisLabel, event: { change: updateChart }\">\n                            <label class=\"form-check-label\">Y-Axis Label</label>\n                        </div>\n                        <div class=\"form-check form-switch small mb-1\" data-bind=\"visible: ReportType() !== 'Pie'\">\n                            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: chartOptions().showGridlines, event: { change: updateChart }\">\n                            <label class=\"form-check-label\">Gridlines</label>\n                        </div>\n                        <div class=\"form-check form-switch small mb-1\">\n                            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: chartOptions().showSmallValuesOnLabel, event: { change: updateChart }\">\n                            <label class=\"form-check-label\">Show Small Values On Label</label>\n                        </div>\n                        <div class=\"form-group small mb-1\">\n                            <label class=\"form-label\">Y-Axis Format</label>\n                            <select class=\"form-select form-select-sm\" data-bind=\"value: chartOptions().yAxisFormat, event: { change: function() { updateYAxisFormat(); updateChart(); } }\">\n                                <option value=\"\">Auto (from Field)</option>\n                                <option value=\"Currency\">Currency</option>\n                                <option value=\"Percentage\">Percentage</option>\n                                <option value=\"Decimal\">Decimal</option>\n                                <option value=\"Number\">Number</option>\n                            </select>\n                        </div>\n                        <div class=\"form-group small mb-1 d-flex gap-2\">\n                            <div class=\"w-50\">\n                                <label class=\"form-label\">Y-Axis Min</label>\n                                <input type=\"number\" class=\"form-control form-control-sm\" data-bind=\"value: chartOptions().yMin, event: { change: updateChart }\" />\n                            </div>\n                            <div class=\"w-50\">\n                                <label class=\"form-label\">Y-Axis Max</label>\n                                <input type=\"number\" class=\"form-control form-control-sm\" data-bind=\"value: chartOptions().yMax, event: { change: updateChart }\" />\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <div class=\"tab-pane fade\"\n                     data-bind=\"attr: { id: 'tableTab-' + ReportID() }, css: { 'show active': !(ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line') }\">\n                    <div class=\"form-group row\">\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Header Back Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()} , value: tableSettings().headerBackColor, event: { change: updateTable }\"/>\n                        </div>\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Header Font Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()} ,value: tableSettings().headerFontColor, event: { change: updateTable }\"/>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Row Back Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()} ,value: tableSettings().rowBackColor, event: { change: updateTable }\"/>\n                        </div>\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Row Font Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()} ,value: tableSettings().rowFontColor, event: { change: updateTable }\"/>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" style=\"display: none;\">\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Alt Row Back Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"value: tableSettings().altRowBackColor, event: { change: updateTable }\"/>\n                        </div>\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Alt Row Font Color</label>\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"value: tableSettings().altRowFontColor, event: { change: updateTable }\"/>\n                        </div>\n                    </div>\n                    <div class=\"form-group mb-2\" style=\"display: none;\">\n                        <label class=\"form-label small\">Borders</label>\n                        <div class=\"btn-group d-flex flex-wrap\">\n                            <button type=\"button\" class=\"btn btn-light btn-sm flex-fill\"\n                                    data-bind=\"click: function(){ tableSettings().border('none'); updateTable(); }, css: { active: tableSettings().border === 'none' }\">None</button>\n                            <button type=\"button\" class=\"btn btn-light btn-sm flex-fill\"\n                                    data-bind=\"click: function(){ tableSettings().border('all'); updateTable(); }, css: { active: tableSettings().border === 'all' }\">All</button>\n                            <button type=\"button\" class=\"btn btn-light btn-sm flex-fill\"\n                                    data-bind=\"click: function(){ tableSettings().border('outer'); updateTable(); }, css: { active: tableSettings().border === 'outer' }\">Outside</button>\n                            <button type=\"button\" class=\"btn btn-light btn-sm flex-fill\"\n                                    data-bind=\"click: function(){ tableSettings().border('inner'); updateTable(); }, css: { active: tableSettings().border === 'inner' }\">Inside</button>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <div class=\"mb-2 col-6\" style=\"display: none;\">\n                            <label class=\"form-label small\">Border Color</label>\n                            <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: tableSettings().borderColor, event: { change: updateTable }\"/>\n                        </div>\n                         <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Back Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()},value: tableSettings().backColor, event: { change: updateTable }\"/>\n                        </div>\n                        <div class=\"mb-2 col-6 d-flex align-items-end\">\n                            <button class=\"btn btn-sm small\"\n                                    data-bind=\"click: copyTableFormat\"\n                                    title=\"Copy Format\">\n                                <i class=\"fa fa-copy\"></i>\n                            </button>\n                            <button class=\"btn btn-sm small\"\n                                    data-bind=\"click: pasteTableFormat\"\n                                    title=\"Paste Format\">\n                                <i class=\"fa fa-paste\"></i>\n                            </button>\n                            <button class=\"btn btn-sm small\" data-bind=\"click: clearTableSettings\"\n                                title=\"Clear\">\n                                <i class=\"fa fa-close\"></i>\n                            </button>\n                        </div>\n                    </div>                    \n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n\n<div class=\"modal\" id=\"drilldownModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\">\n        <div class=\"modal-content\" data-bind=\"with: ChartDrillDownData\">\n            <div class=\"modal-header\">\n                <h4 class=\"modal-title\">Drilldown Data</h4>\n                <button type=\"button\" class=\"btn-close float-end\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <!-- ko if: DrillDownData -->\n            <div class=\"modal-body\">\n                <div style=\"overflow-x: auto; max-height: 500px; overflow-y: auto;\">\n                    <table class=\"table table-striped table-hover table-condensed\" data-bind=\"with: DrillDownData, attr: {class: 'table table-striped table-hover table-condensed ' + $parent.selectedStyle()}\">\n                        <thead style=\"position: sticky; top: -1px; z-index: 2;\">\n                            <tr class=\"no-highlight\">\n                                <!-- ko foreach: Columns -->\n                                <th data-bind=\"attr: { id: fieldId }, css: {'right-align': IsNumeric}, style: {'width': fieldWidth, 'background-color': headerBackColor }, hidden: outerGroup\" style=\"border-right: 1px solid;\">\n                                    <span data-bind=\"text: fieldLabel2() ? fieldLabel2() : (fieldLabel() ? fieldLabel() : fieldName), style: {'color': headerFontColor, 'font-weight': headerFontBold() ? 'bold' : 'normal'}\"></span>\n                                </th>\n                                <!-- /ko -->\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr style=\"display: none;\" data-bind=\"visible: Rows && Rows.length < 1\">\n                                <td data-bind=\"attr:{colspan: Columns.length}\">\n                                    No records found\n                                </td>\n                            </tr>\n                            <!-- ko foreach: Rows  -->\n                            <tr>\n                                <!-- ko foreach: Items -->\n                                <td data-bind=\"hidden: outerGroup, style: {'background-color': backColor, 'color': fontColor, 'font-weight': fontBold() ? 'bold' : 'normal' }\">\n                                    <div data-bind=\"style: {'width': fieldWidth }\">\n                                        <!-- ko if: LinkTo-->\n                                        <!-- ko if: $data._runLinkedReportInPlace -->\n                                        <a href=\"#\" data-bind=\"click: $data._runLinkedReportInPlace\"><span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span></a>\n                                        <!-- /ko -->\n                                        <!-- ko ifnot: $data._runLinkedReportInPlace -->\n                                        <a data-bind=\"attr: {href: LinkTo}\" target=\"_blank\"><span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span></a>\n                                        <!-- /ko -->\n                                        <!-- /ko-->\n                                        <!-- ko ifnot: LinkTo-->\n                                        <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n                                        <!-- /ko-->\n                                    </div>\n                                </td>\n                                <!-- /ko-->\n                            </tr>\n                            <!-- /ko -->\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <div class=\"col-xs-12 col-centered\" data-bind=\"with: pager\">\n                    <div class=\"form-inline small text-muted\">\n                        <div class=\"float-start total-records\" data-bind=\"visible: pages()\">\n                            <span data-bind=\"text: 'Total Records: ' + totalRecords()\"></span>\n                        </div>\n                        <div class=\"float-start\">\n                            <button class=\"btn btn-xs\" title=\"Download Excel\" data-bind=\"click: $parent.exportExcel\"><span class=\"fas fa-file-excel\"></span></button>\n                            <button class=\"btn btn-secondary btn-sm\" data-bs-toggle=\"modal\" data-bs-target=\"#sqlDrillDownModal\" data-bind=\"visible: $root.adminMode\">\n                                <span class=\"fa fa-code\"></span> View Code\n                            </button>\n                        </div>\n                        <div class=\"form-group float-end\" data-bind=\"visible: pages()\">\n                            <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <!-- /ko -->\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"sqlModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header d-flex justify-content-between align-items-center\">\n                <h4 class=\"modal-title\">Report Code</h4>\n                <button class=\"btn btn-outline-secondary btn-sm d-flex align-items-center\"\n                        data-bind=\"click: function(data, event) { copySqlToClipboard(event.target); }\">\n                    <i class=\"fa fa-clipboard\"></i>&nbsp;Copy\n                </button>\n                <button type=\"button\" class=\"btn-close float-end\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\" data-bind=\"with: ReportResult\">\n                <div id=\"reportSqlCode\" style=\"overflow-x: auto; max-height: 500px; overflow-y: scroll; border: 1px solid; padding: 10px;\" class=\"bg-dark text-light\">\n                    <pre><code data-bind=\"html: ReportSql\" style=\"white-space: pre-wrap;\"></code></pre>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"sqlDrillDownModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\">\n        <div class=\"modal-content\" data-bind=\"with:ChartDrillDownData\">\n            <div class=\"modal-header d-flex justify-content-between align-items-center\">\n                <h4 class=\"modal-title\">Drill Down Report Code</h4>\n                <button class=\"btn btn-outline-secondary btn-sm d-flex align-items-center\"\n                        data-bind=\"click: function(data, event) { copySqlToClipboard(event.target); }\">\n                    <i class=\"fa fa-clipboard\"></i>&nbsp;Copy\n                </button>\n                <button type=\"button\" class=\"btn-close float-end\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\" data-bind=\"with:DrillDownData\">\n                <div id=\"reportSqlCode\" style=\"overflow-x: auto; max-height: 500px; overflow-y: scroll; border: 1px solid; padding: 10px;\" class=\"bg-dark text-light\">\n                    <pre><code data-bind=\"html: ReportSql\" style=\"white-space: pre-wrap;\"></code></pre>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n<div class=\"modal\" id=\"noaccountModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n                <h4 class=\"modal-title\">Account not Setup</h4>\n            </div>\n            <div class=\"modal-body\">\n                <p class=\"alert alert-danger\">dotnet Report Account Configuration missing!</p>\n                <p>You do not have the neccessary initial configuration completed to use dotnet Report.</p>\n                <p>Please view the <a href=\"https://dotnetreport.com/blogs/getting-started-with-dotnet-report/\" target=\"_blank\">Getting Started Guide</a> to correctly configure dotnet Report.</p>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-default\" data-bs-dismiss=\"modal\">Close</button>\n            </div>\n        </div>\n    </div>\n</div>\n<script type=\"text/html\" id=\"pdf-options-schedule-template\">\n    <div class=\"modal-dialog modal-dialog-centered\">\n        <div class=\"modal-content\" data-bind=\"with: PdfPage\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"pdfOptionsScheduleModalLabel\">\n                    <i class=\"fas fa-file-pdf me-2\"></i> Set PDF Page Size\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body row g-0\">\n                <div class=\"col-md-5 d-flex justify-content-center align-items-center\">\n                    <div id=\"pagePreviewBox\" class=\"text-center\">\n                        <div data-bind=\"style: {\n                                     width: selectedWidth(),\n                                     height: selectedHeight(),\n                                     backgroundColor: selectedBackgroundStyle(),\n                                     transition: 'all 0.3s ease'\n                                 }\"\n                             class=\"shadow rounded mx-auto mb-2 border position-relative\">\n                            <span class=\"position-absolute top-50 start-50 translate-middle text-muted small\">Preview</span>\n                        </div>\n                        <div data-bind=\"text: selectedPageLabel\" class=\"fw-bold\"></div>\n                        <div data-bind=\"text: selectedPageDimension\" class=\"text-muted small\"></div>\n                    </div>\n                </div>\n                <div class=\"col-md-7\">\n                    <div class=\"mb-3\">\n                        <label for=\"pageSizeSelect\" class=\"form-label fw-bold\">Page Size:</label>\n                        <select class=\"form-select\" id=\"pageSizeSelect\"\n                                data-bind=\"options: availablePageSizes,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageSize\">\n                        </select>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"pageOrientationSelect\" class=\"form-label fw-bold\">Page Orientation:</label>\n                        <select class=\"form-select\" id=\"pageOrientationSelect\"\n                                data-bind=\"options: availablePageOrientation,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageOrientation\">\n                        </select>\n                    </div>\n                    <div class=\"alert alert-info p-2 small mt-2\">\n                        This PDF will be exported using the selected page size. Ensure your content fits well.\n                        If the content width exceeds the selected size, it will default to Letter.\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-success\" data-bs-dismiss=\"modal\" data-bind=\"click: save\">\n                     Save\n                </button>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"word-options-schedule-template\">\n    <div class=\"modal-dialog modal-dialog-centered\">\n        <div class=\"modal-content\" data-bind=\"with: WordPage\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"pdfOptionsScheduleModalLabel\">\n                    <i class=\"fas fa-file-pdf me-2\"></i> Set WORD Page Size\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body row g-0\">\n                <div class=\"col-md-5 d-flex justify-content-center align-items-center\">\n                    <div id=\"pagePreviewBox\" class=\"text-center\">\n                        <div data-bind=\"style: {\n                                     width: selectedWidth(),\n                                     height: selectedHeight(),\n                                     backgroundColor: selectedBackgroundStyle(),\n                                     transition: 'all 0.3s ease'\n                                 }\"\n                             class=\"shadow rounded mx-auto mb-2 border position-relative\">\n                            <span class=\"position-absolute top-50 start-50 translate-middle text-muted small\">Preview</span>\n                        </div>\n                        <div data-bind=\"text: selectedPageLabel\" class=\"fw-bold\"></div>\n                        <div data-bind=\"text: selectedPageDimension\" class=\"text-muted small\"></div>\n                    </div>\n                </div>\n                <div class=\"col-md-7\">\n                    <div class=\"mb-3\">\n                        <label for=\"pageSizeSelect\" class=\"form-label fw-bold\">Page Size:</label>\n                        <select class=\"form-select\" id=\"pageSizeSelect\"\n                                data-bind=\"options: availablePageSizes,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageSize\">\n                        </select>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"pageOrientationSelect\" class=\"form-label fw-bold\">Page Orientation:</label>\n                        <select class=\"form-select\" id=\"pageOrientationSelect\"\n                                data-bind=\"options: availablePageOrientation,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageOrientation\">\n                        </select>\n                    </div>\n                    <div class=\"alert alert-info p-2 small mt-2\">\n                        This WORD will be exported using the selected page size. Ensure your content fits well.\n                        If the content width exceeds the selected size, it will default to Letter.\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-success\" data-bs-dismiss=\"modal\" data-bind=\"click: save\">\n                     Save\n                </button>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"word-options-template\">\n        <div class=\"modal-dialog modal-dialog-centered\">\n        <div class=\"modal-content\" data-bind=\"with: WordPage\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"wordOptionsModalLabel\"><i class=\"fas fa-file-pdf me-2\"></i> Export to WORD</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body row g-0\">\n                <!-- Left Side: Page Preview SVG -->\n                <div class=\"col-md-5 d-flex justify-content-center align-items-center\">\n                    <div id=\"pagePreviewBox\" class=\"text-center\">\n                        <div data-bind=\"style: {\n                                     width: selectedWidth(),\n                                     height: selectedHeight(),\n                                     backgroundColor: selectedBackgroundStyle(),\n                                     transition: 'all 0.3s ease'\n                                 }\"\n                             class=\"shadow rounded mx-auto mb-2 border position-relative\">\n                            <span class=\"position-absolute top-50 start-50 translate-middle text-muted small\">Preview</span>\n                        </div>\n                        <div data-bind=\"text: selectedPageLabel\" class=\"fw-bold\"></div>\n                        <div data-bind=\"text: selectedPageDimension\" class=\"text-muted small\"></div>\n                    </div>\n                </div>\n\n                <!-- Right Side: Form Options -->\n                <div class=\"col-md-7\">\n                    <div class=\"mb-3\">\n                        <label for=\"pageSizeSelect\" class=\"form-label fw-bold\">Page Size:</label>\n                        <select class=\"form-select\" id=\"pageSizeSelect\"\n                                data-bind=\"options: availablePageSizes,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageSize\">\n                        </select>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"pageOrientationSelect\" class=\"form-label fw-bold\">Page Orientation:</label>\n                        <select class=\"form-select\" id=\"pageOrientationSelect\"\n                                data-bind=\"options: availablePageOrientation,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageOrientation\">\n                        </select>\n                    </div>\n                    <div class=\"alert alert-info p-2 small mt-2\">\n                        This Word will be exported using the selected page size. Ensure your content fits well.\n                        If the content width exceeds the selected size, it will default to Letter.\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-success\" data-bs-dismiss=\"modal\" data-bind=\"click: download\">\n                    <i class=\"fa fa-download me-1\"></i> Download Word\n                </button>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"pdf-options-template\">\n    <div class=\"modal-dialog modal-dialog-centered\">\n        <div class=\"modal-content\" data-bind=\"with: PdfPage\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"pdfOptionsModalLabel\"><i class=\"fas fa-file-pdf me-2\"></i> Export to PDF</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body row g-0\">\n                <!-- Left Side: Page Preview SVG -->\n                <div class=\"col-md-5 d-flex justify-content-center align-items-center\">\n                    <div id=\"pagePreviewBox\" class=\"text-center\">\n                        <div data-bind=\"style: {\n                                     width: selectedWidth(),\n                                     height: selectedHeight(),\n                                     backgroundColor: selectedBackgroundStyle(),\n                                     transition: 'all 0.3s ease'\n                                 }\"\n                             class=\"shadow rounded mx-auto mb-2 border position-relative\">\n                            <span class=\"position-absolute top-50 start-50 translate-middle text-muted small\">Preview</span>\n                        </div>\n                        <div data-bind=\"text: selectedPageLabel\" class=\"fw-bold\"></div>\n                        <div data-bind=\"text: selectedPageDimension\" class=\"text-muted small\"></div>\n                    </div>\n                </div>\n\n                <!-- Right Side: Form Options -->\n                <div class=\"col-md-7\">\n                    <div class=\"mb-3\">\n                        <label for=\"pageSizeSelect\" class=\"form-label fw-bold\">Page Size:</label>\n                        <select class=\"form-select\" id=\"pageSizeSelect\"\n                                data-bind=\"options: availablePageSizes,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageSize\">\n                        </select>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"pageOrientationSelect\" class=\"form-label fw-bold\">Page Orientation:</label>\n                        <select class=\"form-select\" id=\"pageOrientationSelect\"\n                                data-bind=\"options: availablePageOrientation,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageOrientation\">\n                        </select>\n                    </div>\n                    <div class=\"alert alert-info p-2 small mt-2\">\n                        This PDF will be exported using the selected page size. Ensure your content fits well.\n                        If the content width exceeds the selected size, it will default to Letter.\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-success\" data-bs-dismiss=\"modal\" data-bind=\"click: download\">\n                    <i class=\"fa fa-download me-1\"></i> Download PDF\n                </button>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"line-separator-template\">\n    <div class=\"grid-stack-item-content position-relative p-2\" data-bind=\"css: { card: $root.arrangeDashboard }\">\n        <hr data-bind=\"style: { borderTop: thickness() + 'px solid ' + color() }\" class=\"m-0\">\n        <div data-bind=\"visible: $root.arrangeDashboard\" class=\"dropdown position-absolute\" style=\"top:-5px; right:0; z-index:2000;\">\n            <button class=\"btn btn-sm btn-light\" type=\"button\" data-bs-toggle=\"dropdown\">\n                <i class=\"fa fa-ellipsis-v\"></i>\n            </button>\n               <ul class=\"dropdown-menu dropdown-menu-end p-2 bg-light small\">\n                    <li class=\"d-flex align-items-center gap-2 mb-2\">\n                        <label class=\"form-label small mb-0\">Line Color</label>\n                        <input type=\"color\" class=\"color-picker\" data-bind=\"value: color,valueUpdate: 'input',event: { change: () => $root.onWidgetChange($data)}\">\n                    </li>\n\n                    <li class=\"d-flex align-items-center gap-2 mb-2\">\n                        <label class=\"mb-0\">Thickness</label>\n                        <input type=\"number\"\n                               min=\"1\"\n                               max=\"10\"\n                               data-bind=\"value: thickness,valueUpdate: 'input',event: { change: () => $root.onWidgetChange($data)}\"\n                               class=\"form-control form-control-sm\"\n                               style=\"width:50px\">\n                    </li>\n\n                    <li>\n                        <button class=\"dropdown-item text-danger\" data-bind=\"click: deleteSeparator\">\n                            <i class=\"fa fa-trash me-2\"></i>\n                            Delete\n                        </button>\n                    </li>\n                </ul>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"text-widget-template\">\n    <div class=\"grid-stack-item-content position-relative p-2\" data-bind=\"css: { card: $root.arrangeDashboard }\">\n        <div data-bind=\"html: decodeURIComponent(text())\"></div>\n        <div class=\"position-absolute\" style=\"top:3px; right:4px; z-index:2000;\" data-bind=\"visible: $root.arrangeDashboard\">\n            <div class=\"dropdown\">\n                <button class=\"btn btn-sm btn-light\"\n                        type=\"button\"\n                        data-bs-toggle=\"dropdown\"\n                        aria-expanded=\"false\">\n                    <i class=\"fa fa-ellipsis-v\"></i>\n                </button>\n                <ul class=\"dropdown-menu dropdown-menu-end\">\n                    <li>\n                        <button class=\"dropdown-item\"\n                                data-bind=\"click: $root.openTextEditor\">\n                            <i class=\"fa fa-edit me-2\"></i>\n                            Edit\n                        </button>\n                    </li>\n                    <li>\n                        <button class=\"dropdown-item text-danger\"\n                                data-bind=\"click: deleteText\">\n                            <i class=\"fa fa-trash me-2\"></i>\n                            Delete\n                        </button>\n                    </li>\n                </ul>\n            </div>\n        </div>\n    </div>\n</script>\n\n<!-- Configure Joins Modal -->\n<div class=\"modal\" id=\"weightedmodal-configure-joins\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\" data-bind=\"with: selectedReport\">\n    <div class=\"modal-dialog modal-lg \">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"configureJoinsLabel\"><i class=\"fa fa-link\"></i> Configure Joins for Report</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <p class=\"text-muted small\">Override join types and drag to reorder for this report only.</p>\n\n                <!-- ko if: detectedJoins().length === 0 -->\n                <div class=\"alert alert-info\">\n                    <i class=\"fa fa-info-circle\"></i> No joins detected. Make sure you have selected fields from multiple tables.\n                </div>\n                <!-- /ko -->\n\n                <!-- ko if: detectedJoins().length > 0 -->\n                <div class=\"mb-3 p-2 bg-light rounded d-flex align-items-center\">\n                    <label class=\"fw-bold small me-2 text-nowrap\">FROM (First Table):</label>\n                    <select class=\"form-select form-select-sm\" style=\"max-width: 250px;\"\n                            data-bind=\"options: joinBaseTables, optionsText: 'name', optionsValue: 'id', value: baseTableIdOverride\"></select>\n                </div>\n\n                <div class=\"row fw-bold border-bottom pb-2 mb-1 small text-muted\">\n                    <div class=\"col-1\"></div>\n                    <div class=\"col-2\">Table</div>\n                    <div class=\"col-2\">Field</div>\n                    <div class=\"col-1\"></div>\n                    <div class=\"col-2\">Join Type</div>\n                    <div class=\"col-2\">Joined Table</div>\n                    <div class=\"col-2\">Join Field</div>\n                </div>\n                <div data-bind=\"sortable: { data: detectedJoins, options: { handle: '.report-join-drag-handle', cursor: 'move' }, afterMove: reportJoinSorted }\">\n                    <div class=\"row align-items-center border-bottom py-2\">\n                        <div class=\"col-1\">\n                            <span class=\"btn btn-sm btn-outline-secondary report-join-drag-handle\" title=\"Drag to reorder\"><i class=\"fa fa-bars\"></i></span>\n                        </div>\n                        <div class=\"col-2\">\n                            <span data-bind=\"text: tableName\"></span>\n                            <!-- ko if: isForeignKey -->\n                            <span class=\"badge bg-info ms-1\" title=\"Foreign Key Join\">FK</span>\n                            <!-- /ko -->\n                        </div>\n                        <div class=\"col-2\"><code data-bind=\"text: fieldName\"></code></div>\n                        <div class=\"col-1 text-center\">\n                            <button class=\"btn btn-sm btn-outline-primary\" title=\"Swap Table ↔ Joined Table\" data-bind=\"click: $parent.swapJoinDirection\">\n                                <i class=\"fa fa-exchange\"></i>\n                            </button>\n                        </div>\n                        <div class=\"col-2\">\n                            <select class=\"form-select form-select-sm\"\n                                    data-bind=\"options: ['INNER','LEFT','RIGHT','CROSS'], value: joinType\"></select>\n                        </div>\n                        <div class=\"col-2\" data-bind=\"text: joinedTableName\"></div>\n                        <div class=\"col-2\"><code data-bind=\"text: joinFieldName\"></code></div>\n                    </div>\n                </div>\n                <!-- /ko -->\n            </div>\n            <div class=\"modal-footer\">\n                <button class=\"btn btn-outline-secondary btn-sm\" data-bind=\"click: clearCustomJoins\">\n                    <i class=\"fa fa-times\"></i> Clear Overrides\n                </button>\n                <button class=\"btn btn-primary btn-sm\" data-bind=\"click: saveCustomJoins\">\n                    <i class=\"fa fa-check\"></i> Apply to Report\n                </button>\n            </div>\n        </div>\n    </div>\n</div>\n<!-- Templates -->\n</div>";
export const dashboardHtml = "<div id=\"dot-net-report\" class=\"body-content\">\n\n<div data-bind=\"template: {name: 'admin-mode-template'}, visible: allowAdmin\" style=\"display: none;\"></div>\n\n<nav class=\"navbar navbar-expand-lg navbar-light bg-light\" style=\"display:none; position:relative; z-index:1030;\" data-bind=\"visible: currentDashboard\">\n    <div class=\"container-fluid p-0\">\n        <ul class=\"nav nav-tabs me-auto\" id=\"dashboard-tabs\" data-bind=\"sortable: { data: dashboards, options: { cursor: 'move', placeholder: 'drop-highlight', axis: 'x' }, strategyMove: true, afterMove: function(arg) { saveDashboardOrder(); } }\">\n            <li class=\"nav-item nav-link d-flex align-items-center gap-1\" style=\"cursor:pointer;\" data-bind=\"attr: {'data-dashboard-id': id}, css: { 'active': $parent.currentDashboard().id === id }, click: function() { $parent.selectDashboard(id); }\">                \n                <div class=\"dropdown tab-hover-icon\" data-bind=\"visible: canManage || $parent.adminMode()\">\n                    <button type=\"button\" class=\"btn btn-link btn-sm p-0 text-muted\" data-bs-toggle=\"dropdown\" data-bind=\"click: function(){}, clickBubble: false\"><span class=\"fa fa-ellipsis-v\"></span></button>\n                    <ul class=\"dropdown-menu small\">\n                        <li><a href=\"#\" class=\"dropdown-item\" data-bind=\"click: function(){ $parent.editDashboardTab($data); }\"><span class=\"fa fa-pencil\"></span> Edit</a></li>\n                        <li><a href=\"#\" class=\"dropdown-item\" data-bind=\"click: function(){ $parent.openDashboardScheduleModal(); }\"><span class=\"fa fa-hourglass\"></span> Schedule</a></li>\n                        <li><a href=\"#\" class=\"dropdown-item\" data-bind=\"click: function(){ $parent.RefreshAllReports(); }\"><span class=\"fa fa-refresh\"></span> Refresh</a></li>\n                    </ul>\n                </div>\n                <span data-bind=\"text: name\"></span>\n            </li>\n        </ul>\n        <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#dashboardNavbar\" aria-controls=\"dashboardNavbar\" aria-expanded=\"false\" aria-label=\"Toggle navigation\">\n            <span class=\"navbar-toggler-icon\"></span>\n        </button>\n        <div class=\"collapse navbar-collapse\" id=\"dashboardNavbar\">\n            <div class=\"d-flex align-items-center gap-2 ms-auto\">\n                    <div class=\"btn-group btn-group-sm\" role=\"group\" data-bind=\"visible: hasDashboard()\">\n                        <button class=\"btn btn-light\" data-bind=\"click: zoomOutDashboard\" data-bs-toggle=\"tooltip\" title=\"Zoom Out\">\n                            <i class=\"fa fa-search-minus\"></i>\n                        </button>\n                        <button class=\"btn btn-light\" data-bind=\"click: resetZoomDashboard\" data-bs-toggle=\"tooltip\" title=\"Reset Zoom\">\n                            <i class=\"fa fa-compress\"></i>\n                        </button>\n                        <button class=\"btn btn-light\" data-bind=\"click: zoomInDashboard\" data-bs-toggle=\"tooltip\" title=\"Zoom In\">\n                            <i class=\"fa fa-search-plus\"></i>\n                        </button>\n                    </div>\n                    <div class=\"dropdown\">\n                        <button class=\"btn btn-light btn-sm dropdown-toggle\" type=\"button\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">\n                            <i class=\"fa fa-pencil-square\"></i>\n                            <span>Manage</span>\n                        </button>\n                        <ul class=\"dropdown-menu dropdown-menu-end small\">\n                            <li data-bind=\"visible: hasDashboard() && (currentDashboard().canManage || adminMode()) && (CanSaveReports() || adminMode())\">\n                                <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: function() { newReport() }\" title=\"Create a new report and add it to the Dashboard\">\n                                    <span class=\"fa fa-plus\"></span> Add New Report\n                                </a>\n                            </li>\n                            <li data-bind=\"visible: hasDashboard() && (currentDashboard().canManage || adminMode())\">\n                                <button class=\"dropdown-item\" data-bs-toggle=\"modal\" data-bs-target=\"#add-dashboard-modal\" data-bind=\"click: editDashboard\">\n                                    <i class=\"fa fa-pencil\"></i>\n                                    <span>Edit Dashboard</span>\n                                </button>\n                            </li>\n                            <li data-bind=\"visible: CanCreateDashboards() || adminMode()\">\n                                <button class=\"dropdown-item\" data-bs-toggle=\"modal\" data-bs-target=\"#add-dashboard-modal\" data-bind=\"click: newDashboard\">\n                                    <i class=\"fa fa-dashboard\"></i>\n                                    <span>Create a New Dashboard</span>\n                                </button>\n                            </li>\n                            <li data-bind=\"visible: hasDashboard()\">\n                                <button class=\"dropdown-item\" data-bind=\"click: RefreshAllReports\">\n                                    <i class=\"fa fa-refresh\"></i>\n                                    <span>Refresh</span>\n                                </button>\n                            </li>\n                            <li data-bind=\"visible: hasDashboard()\">\n                                <button class=\"dropdown-item\" data-bind=\"click: resetChartSizes\" title=\"Reset any charts you resized so they fit their widget again\">\n                                    <i class=\"fa fa-arrows-alt\"></i>\n                                    <span>Autofit Chart Sizes</span>\n                                </button>\n                            </li>\n                            <li data-bind=\"visible: hasDashboard() && (currentDashboard().canManage || adminMode())\"><hr class=\"dropdown-divider\"></li>\n                            <li data-bind=\"visible: hasDashboard() && (currentDashboard().canManage || adminMode())\">\n                                <button class=\"dropdown-item\" data-bind=\"click: addLineSeparator\">\n                                    <i class=\"fa fa-minus\"></i>\n                                    <span>Add Line Separator</span>\n                                </button>\n                            </li>\n                            <li data-bind=\"visible: hasDashboard() && (currentDashboard().canManage || adminMode())\">\n                                <button class=\"dropdown-item\" data-bind=\"click: openAddTextModal\">\n                                    <i class=\"fa fa-font\"></i>\n                                    <span>Add Text</span>\n                                </button>\n                            </li>\n                            <li data-bind=\"visible: hasDashboard()\">\n                                <button class=\"dropdown-item\" data-bind=\"click: openDashboardScheduleModal\">\n                                    <i class=\"fa fa-hourglass\"></i>\n                                    <span>Schedule</span>\n                                </button>\n                            </li>                            \n                            <li data-bind=\"visible: hasDashboard() && adminMode()\">\n                                <button class=\"dropdown-item\" data-bind=\"click: openDashboardAccessModal\">\n                                    <i class=\"fa fa-key\"></i>\n                                    <span>Manage Access</span>\n                                </button>\n                            </li>\n                        </ul>\n                    </div>\n                    <div class=\"dropdown\" data-bind=\"visible: hasDashboard()\">\n                        <button class=\"btn btn-light btn-sm dropdown-toggle\" type=\"button\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">\n                            <i class=\"fa fa-download\"></i>\n                            <span>Export</span>\n                        </button>\n                        <ul class=\"dropdown-menu dropdown-menu-end small\">\n                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { return appSettings.showPageSize ? ExportAllPdfReportsWithPageOption() : ExportAllPdfReports('',''); }, hidden: appSettings.useAltPdf\"><i class=\"fa fa-file-pdf\"></i> Pdf</a></li>\n                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { return appSettings.showPageSize ? ExportAllPdfAltReportsWithPageOption() : ExportAllPdfAltReports('',''); }, visible: appSettings.useAltPdf\"><i class=\"fa fa-file-pdf\"></i> Pdf</a></li>\n                            <li data-bind=\"visible: canDrilldown\"><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { return appSettings.showPageSize ? ExportAllExpendedPdfAltReportsWithPageOption() : ExportAllExpendedPdfAltReports('',''); }, visible: appSettings.useAltPdf\"><i class=\"fa fa-file-pdf\"></i> Pdf (Expanded)</a></li>\n                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: ExportAllExcelReports\"><i class=\"fa fa-file-excel\"></i> Excel</a></li>\n                            <li data-bind=\"visible: canDrilldown\"><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: ExportAllExcelExpandedReports\"><i class=\"fa fa-file-excel\"></i> Excel (Expanded)</a></li>\n                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { return appSettings.showPageSize ? ExportAllWordReportsWithPageOption() : ExportAllWordReports('','');}\"><i class=\"fa fa-file-word\"></i> Word</a></li>\n                            <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: PrintDashboard\"><i class=\"fa fa-print\"></i> Print</a></li>\n                        </ul>\n                    </div>\n                    <div data-bind=\"if: hasDashboard() && (currentDashboard().canManage || adminMode())\">\n                        <div class=\"btn btn-light btn-sm d-flex align-items-center gap-2\">\n                            <div class=\"form-check form-switch m-0\">\n                                <input class=\"form-check-input\" id=\"arrange-mode\" type=\"checkbox\" data-bind=\"checked: arrangeDashboard\">\n                            </div>\n                            <span>Arrange</span>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n</nav>\n\n<div class=\"d-flex justify-content-between\">\n    <div class=\"row\" style=\"display: none\" data-bind=\"visible: currentDashboard\">\n        <div data-bind=\"with: currentDashboard\">\n            <p data-bind=\"text: description\"></p>\n        </div>\n    </div>\n</div>\n\n<div class=\"padded-top\"></div>\n\n<div class=\"row\">\n    <div class=\"col-md-12\">\n        <div data-bind=\"template: {name: 'fly-filter-template'}\"></div>\n        <br />\n    </div>\n</div>\n\n<div class=\"centered\" style=\"display: none;\" data-bind=\"visible: dashboards().length == 0 && (CanCreateDashboards() || adminMode())\">\n    No Dashboards yet. Click below to Start<br />\n    <button class=\"btn btn-lg btn-primary\" data-bs-toggle=\"modal\" data-bs-target=\"#add-dashboard-modal\" data-bind=\"click: newDashboard\"><i class=\"fa fa-dashboard\"></i> Create a New Dashboard</button>\n</div>\n<div class=\"centered text-muted\" style=\"display: none;\" data-bind=\"visible: dashboards().length == 0 && !(CanCreateDashboards() || adminMode())\">\n    <i class=\"fa fa-dashboard fa-2x\"></i><br />\n    No Dashboards are available to you yet.\n</div>\n\n<div class=\"modal modal-fullscreen\" id=\"add-dashboard-modal\" tabindex=\"-1\" aria-labelledby=\"add-dashboard-modal-label\" aria-hidden=\"true\">\n    <div class=\"modal-dialog\" role=\"document\">\n        <div class=\"modal-content\" data-bind=\"with: dashboard\">\n            <div class=\"modal-header\">\n                <h4 class=\"modal-title\" id=\"add-dashboard-modal-label\"><span data-bind=\"text: Id() ? 'Edit' : 'Add'\"></span> Dashboard</h4>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" data-bind=\"click: $root.onModalCloseClicked\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <div class=\"row\">\n                <div class=\"col-md-4\">\n                <div class=\"mb-3 card card-body\">\n                    <div class=\"mb-3\">\n                        <label class=\"form-label h6\" for=\"add-dash-name\"><i class=\"fa fa-dashboard\"></i> Dashboard Name</label>\n                        <input class=\"form-control\" data-val=\"true\" data-val-required=\"Dashboard Name is required.\" type=\"text\" data-bind=\"value: Name\" placeholder=\"e.g. Sales, Accounting\" id=\"add-dash-name\" required />\n                    </div>\n                    <div>\n                        <label class=\"form-label h6\"><i class=\"fa fa-info-circle\"></i> Description</label>\n                        <textarea class=\"form-control\" rows=\"4\" data-bind=\"value: Description\" placeholder=\"Additional details (optional)\"></textarea>\n                    </div>\n                </div>\n                <div data-bind=\"visible:!$parent.appSettings.showScheduling\" class=\"card card-body mb-3\">\n                    <h5><i class=\"fa fa-hourglass\"></i>&nbsp;Choose Schedule</h5>\n                    <div data-bind=\"template: {name: 'report-schedule'}\"></div>\n                </div>\n                </div>\n                <div class=\"col-md-8\">\n                <div class=\"mb-3 card card-body\">\n                    <div class=\"d-flex flex-wrap align-items-center gap-2 mb-3\">\n                        <h6 class=\"mb-0 me-auto\"><i class=\"fa fa-paperclip\"></i> Choose Reports for the Dashboard\n                            <span class=\"badge bg-secondary ms-1\" data-bind=\"text: $parent.selectedReportCount(), attr: { title: $parent.selectedReportCount() + ' selected' }, visible: $parent.selectedReportCount() > 0\"></span>\n                        </h6>\n                        <div class=\"input-group input-group-sm\" style=\"max-width: 360px;\">\n                            <span class=\"input-group-text\"><i class=\"fa fa-search\"></i></span>\n                            <input type=\"text\" class=\"form-control\" placeholder=\"Search Report by Name or Description...\" data-bind=\"textInput: $parent.searchReports\" />\n                            <button class=\"btn btn-outline-secondary\" type=\"button\" title=\"Clear\" data-bind=\"visible: $parent.searchReports(), click: function() { $parent.searchReports(''); }\"><i class=\"fa fa-times\"></i></button>\n                        </div>\n                    </div>\n\n                    <div data-bind=\"if: $parent.searchReports() && $parent.reportsInSearch().length==0\">\n                        <div class=\"card card-body\">\n                            No reports found matching your search.\n                        </div>\n                    </div>\n                    <div data-bind=\"if: $parent.searchReports() &&  $parent.reportsInSearch().length>0\">\n                        <ul class=\"list-group\" data-bind=\"foreach: $parent.reportsInSearch\">\n                            <li class=\"list-group-item\">\n                                <div class=\"checkbox\">\n                                    <label class=\"list-group-item-heading\">\n                                        <input type=\"checkbox\" data-bind=\"checked: selected\">\n                                        <span class=\"fa\" data-bind=\"css: {'fa-file': reportType=='List', 'fa-th-list': reportType=='Summary', 'fa-bar-chart': reportType=='Bar', 'fa-pie-chart': reportType=='Pie', 'fa-line-chart': reportType=='Line', 'fa-globe': reportType =='Map', 'fa-window-restore': reportType=='Treemap', 'fa-code': reportType=='Html'}\" style=\"font-size: 14pt; color: #808080\"></span>\n                                        <span data-bind=\"highlightedText: { text: reportName, highlight: $parent.searchReports, css: 'highlight' }\"></span>\n                                    </label>\n                                </div>\n                                <p class=\"list-group-item-text small\" data-bind=\"text: reportDescription\"></p>\n                            </li>\n                        </ul>\n                    </div>\n\n                    <div data-bind=\"if: !$parent.searchReports()\" class=\"list-group mb-3\">\n                        <div data-bind=\"foreach: $parent.reportsAndFolders\">\n                            <div class=\"list-group-item\">\n                                <a role=\"button\" class=\"d-flex justify-content-between align-items-center text-body\" data-bs-toggle=\"collapse\" data-bind=\"attr: {href: '#folder-' + folderId }\" style=\"text-decoration: none; font-weight: normal;\">\n                                    <div class=\"d-flex align-items-center\" data-bind=\"style: { paddingLeft: (depth * 20) + 'px' }\">\n                                        <i class=\"fa fa-folder me-2 text-secondary\"></i>\n                                        <span class=\"text-nowrap\" data-bind=\"text: folder\"></span>\n                                        <span class=\"text-muted small ms-2 text-truncate\" style=\"max-width: 260px;\" data-bind=\"visible: depth > 0, text: folderPath, attr: { title: folderPath }\"></span>\n                                        <span class=\"badge rounded-pill bg-primary ms-2\" data-bind=\"text: _.filter(reports, function(r) { return r.selected(); }).length, visible: _.some(reports, function(r) { return r.selected(); })\"></span>\n                                        <span class=\"text-muted small ms-2\" data-bind=\"text: reports.length + (reports.length == 1 ? ' report' : ' reports')\"></span>\n                                    </div>\n                                    <i class=\"fa fa-chevron-down text-muted small\"></i>\n                                </a>\n                                <div class=\"collapse mt-2\" data-bind=\"attr: {id: 'folder-' + folderId }\">\n                                    <ul class=\"list-group list-group-flush\" data-bind=\"foreach: reports\">\n                                        <li class=\"list-group-item\">\n                                            <div class=\"form-check\">\n                                                <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: selected\">\n                                                <label class=\"form-check-label\">\n                                                    <i class=\"fa\" data-bind=\"css: {'fa-file': reportType=='List', 'fa-th-list': reportType=='Summary', 'fa-bar-chart': reportType=='Bar', 'fa-pie-chart': reportType=='Pie', 'fa-line-chart': reportType=='Line', 'fa-globe': reportType =='Map', 'fa-window-restore': reportType=='Treemap', 'fa-code': reportType=='Html'}\" style=\"font-size: 14pt; color: #808080\"></i>\n                                                    <span data-bind=\"text: reportName\"></span>\n                                                </label>\n                                            </div>\n                                            <small class=\"text-muted\" data-bind=\"text: reportDescription\"></small>\n                                        </li>\n                                    </ul>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n                <div data-bind=\"visible: $parent.adminMode\" class=\"card card-body mb-3\">\n                    <div data-bind=\"template: {name: 'manage-access-template', data: manageAccess}\"></div>\n                </div>\n                </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-outline-danger me-auto\" data-bind=\"click: $root.deleteDashboard, visible: Id\"><i class=\"fa fa-trash\"></i> Delete Dashboard</button>\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\" data-bind=\"click: $root.onModalCloseClicked\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: $root.saveDashboard\"><i class=\"fa fa-save\"></i> Save Dashboard</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"manage-access-modal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\" role=\"document\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\"><i class=\"fa fa-key\"></i> Manage Access <span class=\"text-muted ms-1\" data-bind=\"text: currentDashboard() ? currentDashboard().name : ''\"></span></h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <div data-bind=\"template: { name: 'manage-access-template', data: dashboard.manageAccess }\"></div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: saveDashboardAccess\"><i class=\"fa fa-save\"></i> Save Access</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n\n<div class=\"grid-stack\" style=\"display: none;\">\n    <!-- ko foreach: dashboardItems -->\n    <!-- ko if: type === 'report' -->\n    <div class=\"grid-stack-item\" data-bind=\"attr: {'gs-x': x, 'gs-y': y, 'gs-w': width, 'gs-h': height, 'gs-id': ReportID,'data-type':'report'}\">\n        <div class=\"card\" data-bind=\"attr: {class: 'card ' + panelStyle + ' grid-stack-item-content'}, css: { expanded: isExpanded }, style: { border: noDashboardBorders() ? 'none' : '', 'box-shadow': noDashboardBorders() ? 'none' : '','background-color': $parent.getCardBackground($data) }\" style=\"overflow-y: hidden;\">\n            <div class=\"padded-div flex-row\" style=\"padding-bottom: 0; margin-bottom: 0;\">\n                <div class=\"float-start\">\n                    <button type=\"button\" class=\"btn\" data-bs-toggle=\"dropdown\" aria-haspopup=\"false\" aria-expanded=\"false\">\n                        <span class=\"fa fa-ellipsis-v\"></span>\n                    </button>\n                    <ul class=\"dropdown-menu small\" style=\"z-index: 1001;\">\n                        <li data-bind=\"visible: FlyFilters().length > 0\">\n                            <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: toggleFlyFilters\">\n                                <span class=\"fa fa-filter\"></span> Filter\n                            </a>\n                        </li>\n                        <li>\n                            <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: openReport\">\n                                <span class=\"fa fa-pencil\"></span> Edit\n                            </a>\n                        </li>\n                        <li class=\"dropdown dropdown-hover\" data-bind=\"visible: ReportType()!='Single'\">\n                            <a href=\"#\" class=\"dropdown-toggle dropdown-item\">\n                                <span class=\"fa fa-download\"></span> Export\n                            </a>\n                            <ul class=\"dropdown-menu small\">\n                                <li>\n                                    <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: downloadExcel\">\n                                        <span class=\"fa fa-file-excel\"></span> Excel\n                                    </a>\n                                </li>\n                                <li data-bind=\"visible: canDrilldown\">\n                                    <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: downloadExcelWithDrilldown\">\n                                        <span class=\"fa fa-file-excel\"></span> Excel (Expanded)\n                                    </a>\n                                </li>\n                                <li>\n                                    <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: $parent.appSettings.showPageSize ? function() { loadPdfModel() } : function() { $parent.appSettings.useAltPdf ? downloadPdfAlt('','') : downloadPdf('','') }\">\n                                        <span class=\"fa fa-file-pdf\"></span> PDF\n                                    </a>\n                                </li>\n                                <li data-bind=\"visible: canDrilldown && appSettings.useAltPdf && !hasPivotColumn() && ReportType() != 'Single'\">\n                                    <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: $parent.appSettings.showPageSize ? function() { loadPdfModel() } : function() { $parent.appSettings.useAltPdf ? downloadPdfAlt('','',true) : downloadPdf(false,'','') }\">\n                                        <i class=\"fa fa-file-pdf\"></i> Pdf (Expanded)\n                                    </a>\n                                </li>\n                                <li>\n                                    <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: $parent.appSettings.showPageSize ? function() { loadWordModel()} : function() { downloadWord('',''); }\">\n                                        <span class=\"fa fa-file-word\"></span> Word\n                                    </a>\n                                </li>\n                            </ul>\n                        </li>\n                        <li data-bind=\"visible: ReportType()!='Single'\">\n                            <a class=\"dropdown-item\" data-bind=\"attr: {href: '/DotNetReport?linkedreport=true&noparent=true&reportId=' + ReportID() }\" target=\"_blank\">\n                                <span class=\"fa fa-folder-open\"></span> Open Report\n                            </a>\n                        </li>\n                        <li data-bind=\"visible: CanEdit() && CanSaveReports()\">\n                            <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: SaveWithoutRun\">\n                                <span class=\"fa fa-save\"></span> Save\n                            </a>\n                        </li>\n                        <li data-bind=\"visible: $parent.currentDashboard().canManage || $parent.adminMode()\">\n                            <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: function() { $parent.removeReportFromDashboard(ReportID()); }\">\n                                <span class=\"fa fa-close\"></span> Remove\n                            </a>\n                        </li>\n                        <li>\n                            <a href=\"#\" class=\"dropdown-item\" data-bind=\"click: function() { RefreshReport(ReportID()); }\">\n                                <span class=\"fa fa-refresh\"></span> Refresh\n                            </a>\n                        </li>\n                        <li>\n                            <a href=\"#\" class=\"dropdown-item\" data-bs-toggle=\"modal\" data-bs-target=\"#sqlModal\" data-bind=\"visible: $parent.adminMode, click: getCode\">\n                                <span class=\"fa fa-code\"></span> Report Code\n                            </a>\n                        </li>\n                    </ul>\n\n                </div>\n\n                <h2 class=\"float-start\" data-bind=\"text: ReportName\"></h2>\n                <a href=\"#\" class=\"btn btn-link btn-sm float-start\" data-bind=\"visible: canGoBackToParent(), click: backToParentReport\" title=\"Back to Parent Report\">\n                    <i class=\"fa fa-arrow-circle-left\"></i> Back to Parent\n                </a>\n                <div class=\"float-end\">\n                    <span data-bind=\"visible: isDirty\" class=\"text-warning small\" title=\"You have unsaved changes\">\n                        <i class=\"fa fa-exclamation-triangle\"></i>\n                    </span>\n                    <a class=\"btn btn-link\" data-bind=\"visible: CanEdit() && CanSaveReports() && isDirty(), click: SaveWithoutRun\">\n                        <span class=\"fa fa-save\"></span>\n                    </a>\n                    <a class=\"btn btn-link\" data-bind=\"visible:ReportType() != 'Single',click: toggleExpand\"><span class=\"fa\" data-bind=\"css: {'fa-expand': !isExpanded(), 'fa-minus': isExpanded() }, visible: ReportType() != 'Single' && !noDashboardBorders()\"></span></a>\n                </div>\n                <div data-bind=\"visible: $parent.arrangeDashboard\">\n                    <div class=\"float-end\" data-bind=\"if: ReportType()!='Single' && ReportType()!='Html' && CanEdit()\">\n                        <div data-bind=\"template: 'chart-settings', data: $data\"></div>\n                    </div>\n                    <div data-bind=\"if:ReportType() == 'Single' && CanEdit()\">\n                        <div data-bind=\"template: {name: 'kpi-settings', data: $data }\"></div>\n                    </div>\n                </div>\n            </div>\n            <div class=\"card-body list-overflow-auto\" style=\"padding-top: 0; margin-top: 0;\">\n                <p data-bind=\"html: ReportDescription, visible: ReportDescription\"></p>\n                <div data-bind=\"template: 'filter-details-summary'\"></div>\n                <div data-bind=\"template: {name: 'fly-filter-template'}, visible: showFlyFilters\"></div>\n                <div data-bind=\"with: ReportResult\" class=\"small\">\n                    <div data-bind=\"visible: !ReportData()\">\n                        <div class=\"report-spinner\"></div>\n                    </div>\n                    <div data-bind=\"template: 'report-template', data: $data\"></div>\n                </div>\n            </div>\n            <div class=\"form-inline report-total\" data-bind=\"visible: !noDashboardBorders()\">\n                <div class=\"small\" data-bind=\"with: pager\">\n                    <div class=\"form-group float-start total-records\" data-bind=\"visible: totalRecords()>1 && $parent.ReportType() != 'Single'\">\n                        <span data-bind=\"text: 'Total Records: ' + totalRecords()\"></span>\n                    </div>\n                    <div class=\"form-group float-end\" data-bind=\"visible: pages()>1 && $parent.ReportType() != 'Single'\">\n                        <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                    </div>\n                    <div class=\"clearfix\"></div>\n                </div>\n            </div>\n        </div>\n    </div>\n    <!-- /ko -->\n    <!-- ko if: type === 'separator' -->\n        <div class=\"grid-stack-item\" data-bind=\"attr: {'gs-x': x, 'gs-y': y, 'gs-w': width, 'gs-h': height, 'gs-id': id,'data-type':'separator'}\">\n            <div data-bind=\"template: { name: 'line-separator-template', data: $data }\"></div>\n        </div>\n    <!-- /ko -->\n    <!-- ko if: type === 'text' -->\n        <div class=\"grid-stack-item\" data-bind=\"attr: {'gs-x': x, 'gs-y': y, 'gs-w': width, 'gs-h': height,'gs-id': id,'data-type':'text'}\">\n            <div data-bind=\"template:{name:'text-widget-template', data:$data}\"></div>\n        </div>\n    <!-- /ko -->\n    <!-- /ko -->\n</div>\n\n\n<!-- Report Builder -->\n<div class=\"modal modal-fullscreen\" id=\"modal-reportbuilder\" role=\"dialog\" aria-labelledby=\"myModalLabel\" aria-hidden=\"true\" style=\"padding-right: 0px !important;\" data-bind=\"with: selectedReport\">\n    <div data-bind=\"template: {name: 'report-designer', data: $data}\"></div>\n</div>\n\n<!-- Field Options Modal -->\n<div class=\"modal\" id=\"fieldOptionsModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\" data-bind=\"with: selectedReport\">\n    <div data-bind=\"template: {name: 'report-field-options', data: $data}\"></div>\n</div>\n\n<!-- Link Edit Modal -->\n<div class=\"modal\" id=\"linkModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\" data-bind=\"with: selectedReport\">\n    <div data-bind=\"template: {name: 'report-link-edit', data: $data}\"></div>\n</div>\n\n<!-- This renders the template -->\n<div class=\"modal\" id=\"pdfOptionsScheduleModal\" tabindex=\"-1\" aria-labelledby=\"pdfOptionsScheduleModalLabel\" aria-hidden=\"true\" data-bind=\"with: dashboard\">\n    <div data-bind=\"template: { name: 'pdf-options-schedule-template', data: $data  }\"></div>\n</div>\n<!-- This renders the template -->\n<div class=\"modal\" id=\"wordOptionsScheduleModal\" tabindex=\"-1\" aria-labelledby=\"wordOptionsScheduleModalLabel\" aria-hidden=\"true\" data-bind=\"with: dashboard\">\n    <div data-bind=\"template: { name: 'word-options-schedule-template', data: $data }\"></div>\n</div>\n\n<div class=\"modal\" id=\"wordOptionsModal\" tabindex=\"-1\" aria-labelledby=\"wordOptionsModalLabel\" aria-hidden=\"true\" data-bind=\"with: selectedReport\">\n    <div data-bind=\"template: { name: 'word-options-template', data: $data  }\"></div>\n</div>\n<div class=\"modal\" id=\"pdfOptionsModal\" tabindex=\"-1\" aria-labelledby=\"pdfOptionsModalLabel\" aria-hidden=\"true\" data-bind=\"with: selectedReport\">\n    <div data-bind=\"template: { name: 'pdf-options-template', data: $data  }\"></div>\n</div>\n<div class=\"modal\" id=\"exportAllWordOptionsModal\" tabindex=\"-1\" aria-labelledby=\"exportAllWordOptionsModalLabel\" aria-hidden=\"true\" data-bind=\"with: dashboard\">\n    <div data-bind=\"template: { name: 'word-options-template', data: $data  }\"></div>\n</div>\n<div class=\"modal\" id=\"exportAllPdfOptionsModal\" tabindex=\"-1\" aria-labelledby=\"exportAllPdfOptionsModalLabel\" aria-hidden=\"true\" data-bind=\"with: dashboard\">\n    <div data-bind=\"template: { name: 'pdf-options-template', data: $data  }\"></div>\n</div>\n<!-- Schedule Dashboard Modal -->\n<div class=\"modal\" id=\"modal-schedule-dashboard\" tabindex=\"-1\" aria-labelledby=\"scheduleDashboardModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\">\n        <div class=\"modal-content\" data-bind=\"with: scheduleDashboardModal\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"scheduleDashboardModalLabel\">\n                    <i class=\"fa fa-hourglass me-2\"></i> Schedule Dashboard\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <h6 data-bind=\"text: dashboardName\" class=\"mb-3\"></h6>\n                <div data-bind=\"template: { name: 'report-schedule', data: $parent.dashboard }\"></div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: saveSchedule\">Save Schedule</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"textWidgetModal\" tabindex=\"-1\">\n    <div class=\"modal-dialog modal-lg\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" data-bind=\"text: textModalTitle\"></h5>\n                <button class=\"btn-close\" data-bs-dismiss=\"modal\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <textarea id=\"textEditor\"></textarea>\n            </div>\n            <div class=\"modal-footer\">\n                <button class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button class=\"btn btn-primary\" data-bind=\"click: saveTextWidget\">\n                    Save\n                </button>\n            </div>\n        </div>\n    </div>\n</div>\n\n\n<!-- Templates -->\n<!-- Dotnet Report HTML Templates -->\n<script type=\"text/html\" id=\"report-filter\">\n    <div class=\"form-group\" data-bind=\"attr: {id: 'filter-'+uiId }\">\n        <!-- ko if: !hasForeignKey-->\n        <!-- ko if: ['DateTime','Date','Time'].indexOf(fieldType) != -1 -->\n        <div style=\"display: flex; align-items: center; gap: 8px;\">\n            <!-- ko if: ['=','>','<','>=','<=', 'not equal'].indexOf($parent.Operator()) != -1 -->\n            <input class=\"form-control\" data-bind=\"datepicker: $parent.fmtValue, datepickerOptions: {value: $parent.Value, dateFormat: (['Date','Date and Time','Time'].indexOf(fieldFormat()) >= 0 && dateFormat() && dateFormat() !== 'Custom') ? $root.dateFormatMappings[dateFormat()] : $root.dateFormatMappings[($root.appSettings && $root.appSettings.defaultDateFormat) || 'United States']}\" required />\n            <!-- ko if: fieldType=='Time' || fieldFormat()=='Time' || fieldFormat()=='Date and Time'-->\n            <input class=\"form-control\" type=\"time\" data-bind=\"value:$parent.Valuetime\" required>\n            <!-- /ko -->\n            <!-- /ko -->\n        </div>\n        <!-- ko if: ['between'].indexOf($parent.Operator()) != -1 -->\n        From\n        <div style=\"display: flex; align-items: center; gap: 8px;\">\n            <input required class=\"form-control from-date\" data-bind=\"datepicker: $parent.fmtValue, datepickerOptions: {value: $parent.Value, dateFormat: (['Date','Date and Time','Time'].indexOf(fieldFormat()) >= 0 && dateFormat() && dateFormat() !== 'Custom') ? $root.dateFormatMappings[dateFormat()] : $root.dateFormatMappings[($root.appSettings && $root.appSettings.defaultDateFormat) || 'United States']}\" />\n            <!-- ko if:fieldType=='Time' || fieldFormat()=='Time' || fieldFormat()=='Date and Time'-->\n            <input class=\"form-control\" type=\"time\" data-bind=\"value:$parent.Valuetime\" required>\n            <!-- /ko -->\n        </div>\n        to\n        <div style=\"display: flex; align-items: center; gap: 8px;\">\n            <input data-bind=\"datepicker: $parent.fmtValue2, datepickerOptions: {value: $parent.Value2, dateFormat: (['Date','Date and Time','Time'].indexOf(fieldFormat()) >= 0 && dateFormat() && dateFormat() !== 'Custom') ? $root.dateFormatMappings[dateFormat()] : $root.dateFormatMappings[($root.appSettings && $root.appSettings.defaultDateFormat) || 'United States']}\" class=\"form-control to-date\" required />\n            <!-- ko if:fieldType=='Time' || fieldFormat()=='Time' || fieldFormat()=='Date and Time'-->\n            <input class=\"form-control\" type=\"time\" data-bind=\"value:$parent.Valuetime2\" required>\n            <!-- /ko -->\n        </div>\n        <!-- /ko -->\n        <!-- ko if: ['range'].indexOf($parent.Operator()) != -1 -->\n        <select data-bind=\"value: $parent.Value\" class=\"form-select\" required>\n            <option value=\"\"></option>\n            <option>Today</option>\n            <option>Today +</option>\n            <option>Today -</option>\n            <option>Yesterday</option>\n            <option>This Week</option>\n            <option>Last Week</option>\n            <option>This Month</option>\n            <option>Last Month</option>\n            <option>This Year</option>\n            <option>Last Year</option>\n            <option>This Week To Date</option>\n            <option>This Month To Date</option>\n            <option>This Year To Date</option>\n            <option>Last 30 Days</option>\n            <!--<option>This Month Last Year</option>\n            <option>Last Month Last Year</option>\n            <option>This Quarter</option>\n            <option>Last Quarter</option>\n            <option>First Quarter</option>\n            <option>Second Quarter</option>\n            <option>Third Quarter</option>\n            <option>Fourth Quarter</option>\n            <option>Next 6 Months</option>\n            <option>Last 6 Months</option>\n            <option>2 Years ago</option>\n            <option>3 Years ago</option>\n            <option>4 Years ago</option>\n            <option>5 Years ago</option>-->\n            <optgroup label=\"Comparison Options\">\n                <option>>= Today</option>\n                <option><= Today</option>\n                <option>>= Today +</option>\n                <option><= Today +</option>\n                <option>>= Today -</option>\n                <option><= Today -</option>\n            </optgroup>\n        </select>\n        <div data-bind=\"if: $parent.Value().indexOf('Today +') >= 0 || $parent.Value().indexOf('Today -') >= 0\" class=\"form-group float-start\" style=\"padding-top: 5px;\">\n            <input type=\"number\" class=\"form-control input-sm float-start\" style=\"width: 80px;\" data-bind=\"value: $parent.Value2\" required /><span style=\"padding: 5px 5px;\" class=\"float-start\"> days</span>\n        </div>\n        <!-- /ko -->\n        <!-- /ko -->\n        <!-- ko if: ['Int','Money','Float','Double'].indexOf(fieldType) != -1 -->\n            <!-- ko if: ['=','>','<','>=','<=', 'not equal'].indexOf($parent.Operator()) != -1 && ['is blank', 'is not blank', 'is null', 'is not null'].indexOf($parent.Operator()) == -1 -->\n            <input class=\"form-control\" type=\"number\" data-bind=\"value: $parent.Value, disable: $parent.Operator() == 'is default'\" required />\n            <!-- /ko -->\n             <!-- ko if: ['in', 'not in'].indexOf($parent.Operator()) != -1 -->\n            <input class=\"form-control\" type=\"text\" data-bind=\"value: $parent.Value\" required />\n            <!-- /ko -->\n            <!-- ko if: ['between'].indexOf($parent.Operator()) != -1 -->\n            From\n            <input class=\"form-control\" type=\"number\" data-bind=\"value: $parent.Value\" required />\n            To\n            <input class=\"form-control\" type=\"number\" data-bind=\"value: $parent.Value2\" required />\n        <!-- /ko -->\n        <!-- /ko -->\n        <!-- ko if: fieldType=='Boolean' && ['is blank', 'is not blank', 'is null', 'is not null'].indexOf($parent.Operator()) == -1 -->\n        <select required class=\"form-select\" data-bind=\"value: $parent.Value, disable: $parent.Operator() == 'is default'\">\n            <option value=\"1\">Yes</option>\n            <option value=\"0\">No</option>\n        </select>\n        <!-- /ko -->\n        <!-- ko if: ['Int','Money','Float','Double','Date','DateTime','Time','Boolean'].indexOf(fieldType) == -1 && ['is blank', 'is not blank', 'is null', 'is not null'].indexOf($parent.Operator()) == -1 -->\n        <input class=\"form-control\" type=\"text\" data-bind=\"value: $parent.Value, disable: $parent.Operator() == 'is default',attr: {id: 'ctl-' + $element.closest('[data-parentprefix]').getAttribute('data-parentprefix') + '-' + ($parent.uiId || uiId)}\" required />\n        <!-- /ko -->\n        <!-- /ko -->\n        <!-- ko if: hasForeignKey && $parent.Operator() != 'all' && $parent.Operator() != 'none' && $parent.Operator() != 'no filter' -->\n        <!-- ko if: hasForeignParentKey && $parent.showParentFilter() -->\n        <select multiple class=\"form-control\" data-bind=\"select2: { dropdownParent: '#filter-'+uiId, placeholder: 'Please Choose', allowClear: true }, lookupSearch: $parent.SearchParentList, options: $parent.ParentList, optionsText: 'text', optionsValue: $parent.IsConditionalFilter ? 'text': 'id', selectedOptions: $parent.ParentIn\"></select>\n        <!-- /ko -->\n        <!-- ko if: $parent.Operator()=='='-->\n        <select required class=\"form-control\" data-bind=\"select2: { dropdownParent: '#filter-'+uiId, placeholder: 'Please Choose', allowClear: true }, lookupSearch: $parent.SearchLookupList, options: $parent.LookupList, optionsText: 'text', optionsValue:   $parent.IsConditionalFilter ? 'text': 'id', value: $parent.Value, optionsCaption: 'Please Choose'\"></select>\n        <!-- /ko -->\n        <!-- ko if: $parent.Operator()=='in' || $parent.Operator()=='not in'-->\n        <select required multiple class=\"form-control\" data-bind=\"select2: { dropdownParent: '#filter-'+uiId, placeholder: 'Please Choose', allowClear: true }, lookupSearch: $parent.SearchLookupList, options: $parent.LookupList, optionsText: 'text', optionsValue: $parent.IsConditionalFilter ? 'text': 'id', selectedOptions: $parent.ValueIn\"></select>\n        <!-- /ko -->\n        <!-- /ko -->\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"pager-template\">\n    <div class=\"pager-container d-flex align-items-center flex-wrap gap-2\">\n\n        <!-- Rows per page -->\n        <div class=\"d-flex align-items-center gap-1 ms-1\">\n            <span class=\"text-muted small\">Page size:</span>\n            <select class=\"form-select form-select-sm w-auto\"\n                    data-bind=\"options: pageSizeOptions, value: pageSize\">\n            </select>\n        </div>\n\n        <!-- Inner border block for page navigation controls -->\n        <div class=\"d-flex align-items-center gap-1 ms-3\">\n            <a href=\"#\" title=\"First\" data-bind=\"click: first, enable: !isFirstPage()\"\n               class=\"btn btn-outline-secondary btn-sm pager-btn ms-1\" aria-label=\"First Page\">\n                <i class=\"fa fa-angle-double-left\"></i>\n            </a>\n\n            <a href=\"#\" title=\"Previous\" data-bind=\"click: previous, enable: !isFirstPage()\"\n               class=\"btn btn-outline-secondary btn-sm pager-btn\" aria-label=\"Previous Page\">\n                <i class=\"fa fa-angle-left\"></i>\n            </a>\n\n            <div class=\"d-flex align-items-center gap-1\">\n                <span class=\"text-muted small\">Page</span>\n                <input type=\"number\" min=\"1\" pattern=\"[0-9]*\"\n                       class=\"form-control form-control-sm text-center pager-input\"\n                       style=\"width: 60px;\"\n                       data-bind=\"value: currentPage, attr: { max: pages() }\">\n                <span class=\"text-muted small\">of</span>\n                <span class=\"text-muted small\" data-bind=\"text: pages\"></span>\n            </div>\n\n            <a href=\"#\" title=\"Next\" data-bind=\"click: next, enable: !isLastPage()\"\n               class=\"btn btn-outline-secondary btn-sm pager-btn\" aria-label=\"Next Page\">\n                <i class=\"fa fa-angle-right\"></i>\n            </a>\n\n            <a href=\"#\" title=\"Last\" data-bind=\"click: last, enable: !isLastPage()\"\n               class=\"btn btn-outline-secondary btn-sm pager-btn\" aria-label=\"Last Page\">\n                <i class=\"fa fa-angle-double-right\"></i>\n            </a>\n        </div>\n    </div>\n</script>\n\n\n\n<script type=\"text/html\" id=\"report-column-header\">\n    <!-- ko foreach: Columns -->\n    <th data-bind=\"attr: { id: !IsPivotField ? fieldId : 'pivot--' + fieldName }, style: {'text-align': fieldAlign() ? fieldAlign() : (IsNumeric ? 'right' : 'left'), 'background-color': headerBackColor }, hidden: outerGroup\" style=\"border-right: 1px solid;\">\n\n        <!-- ko if: !$parent.IsDrillDown() && !$parent.IsSubReport() -->\n        <div class=\"float-start\" style=\"padding-right: 5px;\">\n            <div class=\"dropup\">\n                <a href=\"#\" data-bs-toggle=\"dropdown\" aria-haspopup=\"false\" aria-expanded=\"false\">\n                    <span class=\"fa fa-ellipsis-v sortable\" title=\"Drag to reorder\"></span>\n                </a>\n                <ul data-bind=\"visible: !IsPivotField\" class=\"dropdown-menu field-quick-menu\" style=\"z-index: 1001; min-width: 170px;\">\n                    <li class=\"dropdown-item small px-2 py-1\">\n                        <div class=\"field-quick-row\">\n                            <span class=\"field-quick-label\">Align</span>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Align Left\"\n                                    data-bind=\"click: function(){ fieldAlign('Left'); }, css: {'active': fieldAlign() === 'Left'}, clickBubble: false\">\n                                <i class=\"fa fa-align-left\"></i>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Align Center\"\n                                    data-bind=\"click: function(){ fieldAlign('Center'); }, css: {'active': fieldAlign() === 'Center'}, clickBubble: false\">\n                                <i class=\"fa fa-align-center\"></i>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Align Right\"\n                                    data-bind=\"click: function(){ fieldAlign('Right'); }, css: {'active': fieldAlign() === 'Right'}, clickBubble: false\">\n                                <i class=\"fa fa-align-right\"></i>\n                            </button>\n                        </div>\n                    </li>\n                    <li class=\"dropdown-item small px-2 py-1\" data-bind=\"visible: IsNumeric\">\n                        <div class=\"field-quick-row\">\n                            <span class=\"field-quick-label\">Format</span>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Currency\"\n                                    data-bind=\"click: function(){ fieldFormat(fieldFormat() === 'Currency' ? 'Auto' : 'Currency'); }, css: {'active': fieldFormat() === 'Currency'}, clickBubble: false\">\n                                <i class=\"fa fa-dollar\"></i>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Percentage\"\n                                    data-bind=\"click: function(){ fieldFormat(fieldFormat() === 'Percentage' ? 'Auto' : 'Percentage'); }, css: {'active': fieldFormat() === 'Percentage'}, clickBubble: false\">\n                                <i class=\"fa fa-percent\"></i>\n                            </button>\n                        </div>\n                    </li>\n                    <li><hr class=\"dropdown-divider my-1\"></li>\n                    <li class=\"dropdown-item small\" data-bind=\"visible: !IsNumeric\">\n                        <a href=\"#\" data-bind=\"click: toggleOuterGroup\">\n                            <span class=\"fa fa-clone\"></span> Outer Group\n                        </a>\n                    </li>\n                    <li class=\"dropdown-item small\">\n                        <a href=\"#\" data-bind=\"click: setupFieldOptions\">\n                            <span class=\"fa fa-gear\"></span> More Settings\n                        </a>\n                    </li>\n                </ul>\n            </div>\n        </div>\n        <!-- /ko -->\n        <div data-bind=\"style: {'width': fieldWidth}\">\n            <!-- ko if: $parents[3].useStoredProc ? $parents[3].useStoredProc() : ($parents[5].useStoredProc ? $parents[5].useStoredProc() : false) -->\n            <span data-bind=\"text: fieldLabel() ? fieldLabel() : fieldName, style: {'color': headerFontColor, 'font-weight': headerFontBold() ? 'bold' : 'normal'}\"></span>\n            <!-- /ko -->\n            <!-- ko ifnot: $parents[3].useStoredProc ? $parents[3].useStoredProc() : ($parents[5].useStoredProc ? $parents[5].useStoredProc() : false)  -->\n            <a href=\"\" data-bind=\"click: function(){ if (!IsPivotField) { $parents[pagerIndex($parents)].changeSort(SqlField); } }, style: {'color': headerFontColor, 'font-weight': headerFontBold() ? 'bold' : 'normal'}\">\n                <span data-bind=\"text: $parent.IsDrillDown() && fieldLabel2() ? fieldLabel2() : (fieldLabel() ? fieldLabel() : fieldName)\"></span>\n                <span data-bind=\"text: $parents[pagerIndex($parents)].pager.sortColumn() === SqlField ? ($parents[pagerIndex($parents)].pager.sortDescending() ? '&#9660;' : '&#9650;') : ''\"></span>\n            </a>\n            <!-- /ko -->\n        </div>\n    </th>\n    <!-- /ko -->\n</script>\n\n<script type=\"text/html\" id=\"report-widget\">\n    <div data-bind=\"style: { 'font-size': (FontSize ? FontSize : '48px'),'text-align': Alignment ? Alignment : 'center','color': FontColor ? FontColor : '#000000','background-color':BackColor ? BackColor : '#fff' }\" style=\"width: 100%;\">\n        <span data-bind=\"visible: Rows.length < 1\" title=\"No data found\">/</span>\n\n        <div data-bind=\"if: Rows.length > 0\">\n            <div data-bind=\"with: $parent.rows[0].Items[0]\">\n                <span class=\"preserve-space\" data-bind=\"html: $parent.formatKpiValue(Value, formattedVal())\"></span>\n\n                <!-- ko if: $parent.Rows.length > 1 ? ($parents[$parents.length-2].showPriorInKpi != undefined ? $parents[$parents.length-2].showPriorInKpi() : $parents[$parents.length-1].showPriorInKpi()) : false -->\n                <div data-bind=\"style: {'font-size': '20px'}\" class=\"text-muted\">\n                    <span data-bind=\"text: $parent.comparisonLabel\"></span>: <span class=\"preserve-space\" data-bind=\"html: $parent.formatKpiValue($parent.Rows[1].Items[0].Value, $parent.Rows[1].Items[0].formattedVal)\"></span>\n                    <span data-bind=\"style: {'color': $parent.calculateRate() > 0 ? $parent.PositiveColor : $parent.NegativeColor, 'font-size': '20px'}\">\n                        <i data-bind=\"css: $parent.calculateRate() > 0 ? 'fa fa-arrow-up' : 'fa fa-arrow-down'\"></i>\n                        <span data-bind=\"html: Math.abs($parent.calculateRate()) + '%'\"></span>\n                    </span>\n                </div>\n                <!-- /ko -->\n\n            </div>\n        </div>\n    </div>\n\n</script>\n<script type=\"text/html\" id=\"kpi-settings\">\n    <div class=\"chart-container float-end\">\n        <button class=\"btn btn-light btn-sm d-flex align-items-center mt-2 chart-settings-btn\"\n                data-bind=\"click: toggleKpiSettings()\" title=\"KPI Settings\">\n            <i class=\"fa fa-cog\"></i>\n        </button>\n        <div class=\"kpi-settings-panel border p-2 shadow-sm bg-light\"\n             data-bind=\"visible: showKpiSettings\">\n            <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                <button class=\"btn btn-sm btn-close\" data-bind=\"click: toggleKpiSettings()\"></button>\n                <h6 class=\"mb-0\">KPI Settings</h6>\n            </div>\n            <ul class=\"nav nav-tabs nav-sm mb-2 small\">\n                <li class=\"nav-item\">\n                    <a class=\"nav-link active\"\n                       data-bs-toggle=\"tab\"\n                       data-bind=\"attr: { href: '#kpiTab-' + ReportID() }\">\n                        KPI\n                    </a>\n                </li>\n            </ul>\n            <div class=\"tab-content small\">\n                <!-- KPI Tab -->\n                <div class=\"tab-pane fade show active\"\n                     data-bind=\"attr: { id: 'kpiTab-' + ReportID() }\">\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Font Size</label>\n                        <input type=\"number\"\n                               class=\"form-control form-control-sm\"\n                               min=\"10\" max=\"100\"\n                               data-bind=\"value: kpiSettings().fontSize, event: { input: updateKpi }\">\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Alignment</label>\n                        <select class=\"form-select form-select-sm\"\n                                data-bind=\"value: kpiSettings().alignment, event: { change: updateKpi }\">\n                            <option value=\"left\">Left</option>\n                            <option value=\"center\">Center</option>\n                            <option value=\"right\">Right</option>\n                        </select>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Font Color</label>&nbsp;&nbsp;&nbsp;&nbsp;\n                        <label class=\"form-label small\">Back Color</label><br />\n                        <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: kpiSettings().fontColor,event: { change: updateKpi }\"/>\n                               &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n                        <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: kpiSettings().backColor,event: { change: updateKpi }\"/>\n                    </div>\n                    <div data-bind=\"visible:showPriorInKpi()\" class=\"mb-2\">\n                        <label class=\"form-label small\">Rate Color (+ / -)</label><br />\n                        <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: kpiSettings().positiveColor, event: { change: updateKpi }\"/> +\n                        <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: kpiSettings().negativeColor, event: { change: updateKpi }\"/> -\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Number Format</label>\n                        <select class=\"form-select form-select-sm\"\n                                data-bind=\"value: kpiSettings().numberFormat, event: { change: updateKpi }\">\n                            <option value=\"number\">Number</option>\n                            <option value=\"currency\">Currency</option>\n                            <option value=\"custom\">Custom Format</option>\n                        </select>\n                        <input type=\"text\"\n                               class=\"form-control form-control-sm mt-2\"\n                               placeholder=\"e.g. #,###.00\"\n                               data-bind=\"value: kpiSettings().customFormat,\n                                          visible: kpiSettings().numberFormat() === 'custom',\n                                          valueUpdate:'input',\n                                          event:{ input:updateKpi }\">\n                    </div>\n                    <div data-bind =\"visible: kpiSettings().numberFormat() === 'currency'\" class=\"mb-2\">\n                        <label class=\"form-label small\">Currency Symbol</label>\n                        <select class=\"form-select form-select-sm\"\n                                data-bind=\"value: kpiSettings().currencySymbol,event:{ change:updateKpi }\">\n                            <option value=\"$\">USD ($)</option>\n                            <option value=\"€\">Euro (€)</option>\n                            <option value=\"£\">Pound (£)</option>\n                            <option value=\"₹\">Indian Rupee (₹)</option>\n                            <option value=\"Rs\">Rupee (Rs)</option>\n                        </select>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Short Format</label>\n                        <select class=\"form-select form-select-sm\"\n                                data-bind=\"value: kpiSettings().shortFormat,event:{ change:updateKpi }\">\n                            <option value=\"none\">None</option>\n                            <option value=\"thousand\">Thousands (K)</option>\n                            <option value=\"million\">Millions (M)</option>\n                            <option value=\"billion\">Billions (B)</option>\n                        </select>\n                    </div>\n                    <div class=\"d-flex justify-content-end mb-2\">\n                        <button class=\"btn btn-sm\"\n                                data-bind=\"click: copyKpiFormat\"\n                                title=\"Copy Format\">\n                            <i class=\"fa fa-copy\"></i>\n                        </button>\n                        <button class=\"btn btn-sm\"\n                                data-bind=\"click: pasteKpiFormat\"\n                                title=\"Paste Format\">\n                            <i class=\"fa fa-paste\"></i>\n                        </button>\n                         <button class=\"btn btn-sm\"\n                                data-bind=\"click: clearKpiSettings\"\n                                title=\"Clear\">\n                                <i class=\"fa fa-close\"></i>\n                        </button>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"report-column\">\n    <!-- ko foreach: Items -->\n    <td data-bind=\"hidden: outerGroup, style: {'background-color': _backColor ?? backColor(), 'color': _fontColor ?? fontColor(), 'font-weight': fontBold() || _fontBold ? 'bold' : 'normal', 'text-align': fieldAlign() ? fieldAlign() : (Column.IsNumeric ? 'right' : 'left')}\">\n        <div data-bind=\"style: {'width': fieldWidth }, css: { 'text-wrap': fieldWidth }\">\n            <!-- ko if: LinkTo-->\n            <!-- ko if: $data._runLinkedReportInPlace -->\n            <a href=\"#\" data-bind=\"click: $data._runLinkedReportInPlace\"><span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span></a>\n            <!-- /ko -->\n            <!-- ko ifnot: $data._runLinkedReportInPlace -->\n            <a data-bind=\"attr: {href: LinkTo}\" target=\"_blank\"><span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span></a>\n            <!-- /ko -->\n            <!-- /ko-->\n            <!-- ko ifnot: LinkTo-->\n            <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n            <!-- /ko-->\n        </div>\n    </td>\n</script>\n\n<script type=\"text/html\" id=\"report-pivot\">\n    <div class=\"table-responsive\" data-bind=\"with: ReportData\">\n        <table class=\"table table-striped table-hover table-condensed\">\n            <thead style=\"position: sticky; top: -1px; z-index: 2;\">\n                <tr>\n                    <th></th>\n                    <!-- ko foreach: Rows -->\n                    <th>\n                        <span class=\"preserve-space\" data-bind=\"text: Items[0].FormattedValue\"></span>\n                    </th>\n                    <!-- /ko -->\n                </tr>\n            </thead>\n            <tbody data-bind=\"foreach: Columns\">\n                <tr>\n                    <!-- ko if: $index() > 0 -->\n                    <td>\n                        <span data-bind=\"text: fieldLabel || ColumnName\"></span>\n                    </td>\n                    <!-- ko foreach: $parent.Rows -->\n                    <td data-bind=\"style: {'background-color': $parent.backColor, 'color': $parent.fontColor, 'font-weight': $parent.fontBold() ? 'bold' : 'normal', 'text-align': $parent.fieldAlign ? $parent.fieldAlign : ($parent.IsNumeric ? 'right' : 'left') }\">\n                        <span class=\"preserve-space\" data-bind=\"text: Items[$parentContext.$index()].FormattedValue\"></span>\n                    </td>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                </tr>\n            </tbody>\n        </table>\n\n    </div>\n\n</script>\n\n<script type=\"text/html\" id=\"report-table\">\n    <div class=\"table-responsive\">\n        <table class=\"table table-hover table-condensed\" data-bind=\"attr: {class: 'table table-striped table-hover table-condensed ' + $parents[2].selectedStyle()}\">\n            <thead style=\"position: sticky; top: -1px; z-index: 2;\" data-bind=\"if: !$parents[2].noHeaderRow(), attr: {id: 'report-table-head' + $parents[2].ReportID()}\">\n                <tr class=\"no-highlight\" data-bind=\"sortableColumns: { handle: '.sortable', cursor: 'move', placeholder: 'drop-highlight',selectedFields: $parents[2].SelectedFields }\">\n                    <!-- ko if: $parentContext.$parentContext.$parent.canDrilldown() && !IsDrillDown() && !CanExpandOption() && (!$parents[2].hasPivotColumn() || ($parents[2].hasPivotColumn() && $parents[2].appSettings.useAltPivot)) -->\n                    <th style=\"width: 30px; border-left: 1px solid;\" data-bind=\"style: {'background-color': Columns[0].headerBackColor}\"></th>\n                    <!-- /ko -->\n                    <!-- ko template: 'report-column-header', data: $data -->\n                    <!-- /ko-->\n                </tr>\n            </thead>\n            <tbody data-bind=\"attr: {id: 'report-table-body' + $parents[2].ReportID()}\">\n                <tr style=\"display: none;\" data-bind=\"visible: Rows.length < 1\">\n                    <td data-bind=\"attr:{colspan: Columns.length + 1}\">\n                        No records found\n                    </td>\n                </tr>\n\n                <!-- ko if: !$parents[2].useRenderTable() -->\n                <!-- ko foreach: $parent.rows  -->\n                <tr>\n                    <!-- ko if: $parentContext.$parentContext.$parentContext.$parent.canDrilldown() && !$parent.IsDrillDown() && !$parent.CanExpandOption() && $parentContext.$parentContext.$parentContext.$parent.ReportType() != 'Single' -->\n                    <td style=\"width: 30px; vertical-align: middle;\" data-bind=\"style: {'background-color': Items[0]._backColor ?? Items[0].backColor(), 'color': Items[0]._fontColor ?? Items[0].fontColor()}\">\n                        <a href=\"#\" data-bind=\"click: function(){ toggle(); }\"><span class=\"fa\" data-bind=\"css: {'fa-plus': !isExpanded(), 'fa-minus': isExpanded()}\"></span></a>\n                    </td>\n                    <!-- /ko -->\n                    <!-- ko template: 'report-column', data: $data -->\n                    <!-- /ko-->\n                </tr>\n                <!-- ko if: isExpanded -->\n                <tr>\n                    <td style=\"width: 30px;\"></td>\n                    <td data-bind=\"attr:{colspan: $parent.Columns.length }\" style=\"padding-left: 0px;\">\n                        <div data-bind=\"visible: !DrillDownData()\">\n                            <div class=\"report-spinner\"></div>\n                        </div>\n                        <!-- ko if: DrillDownData -->\n                        <table class=\"table table-striped table-hover table-condensed\" data-bind=\"with: DrillDownData\">\n                            <thead>\n                                <tr class=\"no-highlight\">\n                                    <!-- ko template: 'report-column-header', data: $data -->\n                                    <!-- /ko-->\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <tr style=\"display: none;\" data-bind=\"visible: Rows && Rows.length < 1\">\n                                    <td data-bind=\"attr: {colspan: Columns.length}\">\n                                        No records found\n                                    </td>\n                                </tr>\n                                <!-- ko foreach: Rows  -->\n                                <tr>\n                                    <!-- ko template: 'report-column', data: $data -->\n                                    <!-- /ko-->\n                                </tr>\n                                <!-- /ko -->\n                            </tbody>\n                        </table>\n                        <div class=\"col-xs-12 col-centered\" data-bind=\"with: pager\">\n                            <div class=\"form-inline small text-muted\">\n                                <div class=\"float-start total-records\" data-bind=\"visible: pages()\">\n                                    <span data-bind=\"text: 'Total Records: ' + totalRecords()\"></span>\n                                </div>\n                                <div class=\"float-start total-records\">\n                                    &nbsp;\n                                    <a href=\"#\" title=\"Download Excel\" data-bind=\"click: $parent.exportExcel\"><span class=\"fas fa-file-excel\"></span></a>\n                                    &nbsp;\n                                    <a href=\"#\" title=\"View Code\" data-bs-toggle=\"modal\" data-bs-target=\"#sqlDrillDownModal\" data-bind=\"visible: $root.adminMode\">\n                                        <span class=\"fa fa-code\"></span>\n                                    </a>\n                                </div>\n                                <div class=\"form-group float-end\" data-bind=\"visible: pages()\">\n                                    <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                                </div>\n                            </div>\n                        </div>\n                        <!-- /ko -->\n                    </td>\n                </tr>\n                <!-- /ko -->\n                <!-- ko if: subReportsRan().length > 0 -->\n                <tr>\n                    <td data-bind=\"attr:{colspan: $parent.Columns.length }\" style=\"padding-left: 0px;\">\n                        <div data-bind=\"foreach: subReportsRan\">\n                            <div data-bind=\"template: { name: 'subreport-content', data: $data }\"></div>\n                        </div>\n                    </td>\n                </tr>\n                <!-- /ko -->\n                <!-- /ko -->\n                <!-- /ko-->\n            </tbody>\n            <!-- ko if: $parentContext.$parent.SubTotals().length == 1 && $parentContext.$parentContext.$parent.OuterGroupColumns().length == 0 && $parentContext.$parentContext.$parent.totalRowFormat() == 'row' -->\n            <tfoot data-bind=\"foreach: $parentContext.$parent.SubTotals\">\n                <tr class=\"sub-total\">\n                    <!-- ko if: $parentContext.$parentContext.$parentContext.$parent.canDrilldown() && !$parent.IsDrillDown() && !$parent.CanExpandOption() -->\n                    <td></td>\n                    <!-- /ko -->\n                    <!-- ko foreach: Items -->\n                    <!-- ko if: Value != 'NA' && Value != 'NaN' && !outerGroup() -->\n                    <td data-bind=\"style: {'background-color': _backColor ?? backColor(), 'color': _fontColor ?? fontColor(), 'font-weight': fontBold() || _fontBold ? 'bold' : 'normal', 'text-align': fieldAlign() ? fieldAlign() : 'right'}\">\n                        <div data-bind=\"style: {'width': fieldWidth }, attr: {'title': (Column.fieldLabel() || Column.ColumnName) + ' - ' +_aggregate }, visible:  _showInTotalRow != false\">\n                        <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n                        </div>\n                    </td>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                </tr>\n            </tfoot>\n            <!-- /ko -->\n            <!-- ko if: $parentContext.$parentContext.$parent.subTotalPerGroup() && $parentContext.$parent.perGroupSubTotals().length > 0 && $parentContext.$parentContext.$parent.totalRowFormat() == 'row' -->\n            <!-- ko if: $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex] && $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex].length > 0 -->\n            <tfoot>\n                <tr class=\"sub-total\" style=\"border-top: 2px solid #dee2e6;\">\n                    <!-- ko if: $parentContext.$parentContext.$parent.canDrilldown() && IsDrillDown() && CanExpandOption() -->\n                    <td></td>\n                    <!-- /ko -->\n                    <!-- ko foreach: $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex] -->\n                    <td data-bind=\"style: {'text-align': Column.IsNumeric ? 'right' : 'left', 'font-weight': 'bold'}\">\n                        <div data-bind=\"style: {'width': Column.fieldWidth}\">\n                            <span class=\"preserve-space\" data-bind=\"text: formattedVal\"></span>\n                        </div>\n                    </td>\n                    <!-- /ko -->\n                </tr>\n            </tfoot>\n            <!-- /ko -->\n            <!-- /ko -->\n        </table>\n        <!-- ko if: $parentContext.$parent.SubTotals().length > 0 && $parentContext.$parentContext.$parent.totalRowFormat() == 'table' && $parentContext.$parentContext.$parent.OuterGroupColumns().length == 0 -->\n        <div class=\"mt-3\" style=\"max-width: 450px;\">\n            <table class=\"table table-bordered table-sm\">\n                <thead>\n                    <tr>\n                        <th>Field</th>\n                        <th class=\"text-end\">Total</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <!-- ko foreach: $parentContext.$parent.SubTotals()[0].Items -->\n                    <!-- ko if: _showInTotalRow != false && Value != 'NA' && Value != 'NaN' -->\n                    <tr>\n                        <td data-bind=\"text: (Column.fieldLabel() || Column.ColumnName) + ' (' + _aggregate + ')'\"></td>\n                        <td class=\"text-end\">\n                            <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n                        </td>\n                    </tr>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                </tbody>\n            </table>\n        </div>\n        <!-- /ko -->\n        <!-- ko if: $parentContext.$parent.SubTotals().length > 0 && $parentContext.$parentContext.$parent.totalRowFormat() == 'table' && $parentContext.$parentContext.$parent.OuterGroupColumns().length > 0 && $parentContext.$parentContext.$parent.subTotalPerGroup() -->\n        <!-- ko if: $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex] && $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex].length > 0 -->\n        <div class=\"mt-3\" style=\"max-width: 450px;\">\n            <table class=\"table table-bordered table-sm\">\n                <thead>\n                    <tr>\n                        <th>Field</th>\n                        <th class=\"text-end\">Total</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <!-- ko foreach: $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex] -->\n                    <!-- ko if: _showInTotalRow != false -->\n                    <tr>\n                        <td data-bind=\"text: Column.fieldLabel() || Column.ColumnName\"></td>\n                        <td class=\"text-end\">\n                            <span class=\"preserve-space\" data-bind=\"text: formattedVal\"></span>\n                        </td>\n                    </tr>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                </tbody>\n            </table>\n        </div>\n        <!-- /ko -->\n        <!-- /ko -->\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"report-render\">\n    <div data-bind=\"with: ReportData\">\n        <div data-bind=\"foreach: Rows\">\n            <div data-bind=\"html: renderedHtml, css: { 'card-view': $parents[$parents.length-1].cardView }\"></div>\n\n            <div data-bind=\"foreach: subReportsRan\">\n                <!-- ko if: !_isInline -->\n                <div data-bind=\"template: { name: 'subreport-content', data: $data }\"></div>\n                <!-- /ko -->\n                <!-- ko if: _isInline -->\n                <div style=\"display:none\" data-bind=\"moveToInlineContainer: $data\"></div>\n                <!-- /ko -->\n            </div>\n        </div>\n    </div>\n    <div class=\"clearfix\"></div>\n</script>\n\n<script type=\"text/html\" id=\"subreport-content\">\n    <div class=\"\" style=\"padding-bottom: 20px; position: relative;\">\n        <a href=\"#\" class=\"text-muted\" title=\"Edit sub report\" style=\"position: absolute; right: 5px; top: 2px;\" data-bind=\"visible: CanEdit(), click: function() { var vm = _parentVM || $root; vm.editSubReport({ reportId: ReportID() }); }\">\n            <span class=\"fa fa-pencil\"></span>\n        </a>\n        <h2 data-bind=\"text: ReportName, visible: !_hideTitle\"></h2>\n        <div class=\"clearfix\"></div>\n        <div class=\"list-overflow-auto\" style=\"padding-top: 0; margin-top: 0;\">\n            <p data-bind=\"html: ReportDescription, visible: ReportDescription\"></p>\n            <div data-bind=\"with: ReportResult\" class=\"small\">\n                <div data-bind=\"visible: !ReportData()\">\n                    <div class=\"report-spinner\"></div>\n                </div>\n                <!-- ko if: !$parent._isPlaceholder -->\n                <div data-bind=\"template: 'report-template', data: $data\"></div>\n                <!-- /ko -->\n            </div>\n        </div>\n        <!-- ko if: !$data._isPlaceholder -->\n        <div class=\"form-inline\" data-bind=\"visible: !_hidePager\">\n            <div class=\"small\" data-bind=\"with: pager\">\n                <div class=\"form-group float-start total-records\" data-bind=\"if: totalRecords()>1 && $parent.ReportType() != 'Single'\">\n                    <span data-bind=\"text: 'Total Records: ' + totalRecords()\"></span><br />\n                </div>\n                <div class=\"form-group float-end\" data-bind=\"if: pages()>1 && $parent.ReportType() != 'Single'\">\n                    <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                </div>\n            </div>\n        </div>\n        <!-- /ko -->\n    </div>\n</script>\n\n\n<script type=\"text/html\" id=\"report-template\">\n    <div class=\"report-chart\" data-bind=\"attr: {id: 'chart_div_' + $parent.ReportID()}, visible: $parent.isChart\"></div>\n    <!-- ko if: $parent.ReportType() == 'Pivot' -->\n    <div data-bind=\"template: {name: 'report-pivot', data: $data }\"></div>\n    <!-- /ko -->\n\n    <!-- ko if: $parent.ReportType() == 'Html' -->\n    <div data-bind=\"template: {name: 'report-render', data: $data }\"></div>\n    <!-- /ko -->\n\n    <!-- ko if: $parent.ReportType() != 'Pivot' && $parent.ReportType() != 'Html' && (!$parent.isChart() || $parent.ShowDataWithGraph()) -->\n    <div class=\"float-end\" data-bind=\"if: $parent.OuterGroupColumns().length > 0\">\n        <a href=\"#\" data-bs-toggle=\"dropdown\" aria-haspopup=\"false\" aria-expanded=\"false\">\n            Manage Groups <span class=\"fa fa-ellipsis-v\"></span>\n        </a>\n        <ul class=\"dropdown-menu\" style=\"z-index: 1001;\" data-bind=\"foreach: $parent.OuterGroupColumns\">\n            <li class=\"dropdown-item small\">\n                <a href=\"#\" data-bind=\"click: remove\" title=\"Remove from Group\">\n                    <span class=\"fa fa-close\"></span> <span data-bind=\"text: fieldName\"></span>\n                </a>\n            </li>\n        </ul>\n    </div>\n    <div class=\"clear-fix\"></div>\n\n    <div data-bind=\"foreach: outerGroupData\">\n        <!-- ko if: rows.length > 0 || ($parent.outerGroupData && $parent.outerGroupData().length == 1) -->\n        <br />\n        <h6 style=\"font-weight: normal;\" data-bind=\"html: display\"></h6>\n        <div class=\"\" style=\"padding-top: 5px;\"></div>\n\n        <!-- ko if: $parents[1].ReportType() != 'Single'-->\n        <div data-bind=\"template: {name: 'report-table', data: $parent.ReportData }\"></div>\n        <!-- /ko -->\n        <!-- ko if: $parents[1].ReportType() == 'Single'-->\n        <div data-bind=\"template: {name: 'report-widget', data: $parent.ReportData }\"></div>\n        <!-- /ko -->\n        <!-- /ko -->\n    </div>\n    <!-- ko if: SubTotals().length > 0 && $parent.hasOuterGroupFields() && $parent.IncludeSubTotal() && $parent.totalRowFormat() == 'row' -->\n    <table class=\"table table-bordered table-sm mt-0\" style=\"border-top: 2px double #dee2e6; margin-bottom: 5px;\">\n         <thead>\n            <tr>\n                <th data-bind=\"attr: { colspan: SubTotals()[0].Items.length }\">Grand Total</th>                        \n            </tr>\n        </thead>\n        <tbody></tbody>\n            <tr>\n                <!-- ko if: $parent.canDrilldown() -->\n                <td style=\"width: 30px;\"></td>\n                <!-- /ko -->\n                <!-- ko foreach: SubTotals()[0].Items -->\n                <!-- ko if: _showInTotalRow != false -->\n                 <td data-bind=\"text: (Column.fieldLabel() || Column.ColumnName) + ' (' + _aggregate + ')'\"></td>\n                <!-- /ko -->\n                <!-- /ko -->\n            </tr>\n        \n            <tr class=\"sub-total\">\n                <!-- ko if: $parent.canDrilldown() -->\n                <td style=\"width: 30px;\"></td>\n                <!-- /ko -->\n                <!-- ko foreach: SubTotals()[0].Items -->\n                <!-- ko if: _showInTotalRow != false -->\n                <td data-bind=\"style: {'text-align': Column.IsNumeric ? 'right' : 'left', 'font-weight': 'bold'}\">\n                    <div data-bind=\"style: {'width': Column.fieldWidth}\">                        \n                        <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>                        \n                    </div>\n                </td>\n                <!-- /ko -->\n                <!-- /ko -->\n            </tr>\n        </tbody>\n    </table>\n    <!-- /ko -->\n    <!-- Grand Total: Table mode — Field/Total summary table -->\n    <!-- ko if: SubTotals().length > 0 && $parent.hasOuterGroupFields() && $parent.IncludeSubTotal() && $parent.totalRowFormat() != 'row' -->\n    <div class=\"mt-3\">\n        <!-- ko if: $parent.subTotalPerGroup() --><strong>Grand Total</strong><!-- /ko -->\n        <!-- ko ifnot: $parent.subTotalPerGroup() --><strong>Total</strong><!-- /ko -->\n        <table class=\"table table-bordered table-sm mt-2\" style=\"max-width: 450px;\">\n            <thead>\n                <tr>\n                    <th>Field</th>\n                    <th class=\"text-end\">Total</th>\n                </tr>\n            </thead>\n            <tbody>\n                <!-- ko foreach: SubTotals()[0].Items -->\n                <!-- ko if: _showInTotalRow != false && Value != 'NA' && Value != 'NaN' -->\n                <tr>\n                    <td data-bind=\"text: (Column.fieldLabel() || Column.ColumnName) + ' (' + _aggregate + ')'\"></td>\n                    <td class=\"text-end\">\n                        <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n                    </td>\n                </tr>\n                <!-- /ko -->\n                <!-- /ko -->\n            </tbody>\n        </table>\n    </div>\n    <!-- /ko -->\n    <!-- /ko -->\n</script>\n<script type=\"text/html\" id=\"admin-mode-template\">\n    <div class=\"row\">\n        <div class=\"d-flex justify-content-end align-items-center\" style=\"gap: 10px;\">\n            <div data-bind=\"visible: adminMode\">\n                <div class=\"alert alert-info d-inline-block\" style=\"font-size: 10pt; padding: 5px; max-width: 350px; white-space: normal; margin-bottom: 0;\">\n                    <i class=\"fa fa-user-circle\"></i> You can manage Reports/Dashboards for all users\n                </div>\n            </div>\n            <div data-bind=\"visible: adminMode\">\n                <div class=\"alert alert-info d-inline-block\" style=\"font-size: 10pt; padding: 5px; max-width: 350px; white-space: normal; margin-bottom: 0;\" title=\"Logged in user\">\n                    <i class=\"fa fa-id-badge\"></i>\n                    <span data-bind=\"text: currentUserName || currentUserId || 'Unknown User'\"></span>\n                    <!-- ko if: currentUserRole -->\n                    <span class=\"bubble-badge-separator\">|</span>\n                    Roles: <span data-bind=\"text: currentUserRole\"></span>\n                    <!-- /ko -->\n                    <!-- ko if: clientId -->\n                    <span class=\"bubble-badge-separator\">|</span>\n                    Client: <span data-bind=\"text: clientId\"></span>\n                    <!-- /ko -->\n                </div>\n            </div>\n            <div class=\"d-flex align-items-center\">\n                <div class=\"bubble-badge\">\n                    Admin Mode\n                    <div class=\"form-check form-switch ms-2\">\n                        <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: adminMode\">\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"manage-access-template\">\n    <h5><span class=\"fa fa-key\"></span>Manage Access</h5>\n    <div class=\"panel panel-default panel-body\" style=\"margin-left: 20px;\">\n\n        <div class=\"form-group row\">\n            <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"text: ($root.clientIdLabelText ? $root.clientIdLabelText() : 'Client Id') + ' to Restrict Access'\"></label>\n            <div class=\"col-md-6 col-sm-6\">\n                <!-- ko if: $root.clientIdOptions && $root.clientIdOptions().length > 0 -->\n                <select class=\"form-select form-select-sm\"\n                        data-bind=\"options: $root.clientIdOptions().filter(function(c){ return selectedClientIds().indexOf(c.id) < 0; }),\n                            optionsText: 'text', optionsValue: 'id', optionsCaption: 'Add to restrict access',\n                            value: clientIdToAdd, event: { change: function(){ addClientId(clientIdToAdd()); } }\"></select>\n                <!-- ko if: selectedClientIds().length > 0 -->\n                <div class=\"d-flex flex-wrap gap-1 mt-2\">\n                    <!-- ko foreach: selectedClientIds() -->\n                    <span class=\"badge bg-secondary d-inline-flex align-items-center\">\n                        <span data-bind=\"text: (function(){ var m = _.find($root.clientIdOptions(), function(c){ return c.id == $data; }); return m ? m.text : $data; })()\"></span>\n                        <button type=\"button\" class=\"btn btn-sm btn-link text-white p-0 ms-2 lh-1\" title=\"Remove\" data-bind=\"click: function(){ $parent.removeClientId($data); }\"><i class=\"fa fa-times\"></i></button>\n                    </span>\n                    <!-- /ko -->\n                </div>\n                <!-- /ko -->\n                <div class=\"form-text\" data-bind=\"visible: selectedClientIds().length === 0\">Not restricted, available to all.</div>\n                <!-- /ko -->\n                <!-- ko ifnot: $root.clientIdOptions && $root.clientIdOptions().length > 0 -->\n                <input class=\"form-control text-box single-line\" type=\"text\" placeholder=\"Comma separated, leave blank for all\" data-bind=\"value: clientId\">\n                <!-- ko if: selectedClientIds().length > 0 -->\n                <div class=\"d-flex flex-wrap gap-1 mt-2\">\n                    <!-- ko foreach: selectedClientIds() -->\n                    <span class=\"badge bg-secondary d-inline-flex align-items-center\">\n                        <span data-bind=\"text: $data\"></span>\n                        <button type=\"button\" class=\"btn btn-sm btn-link text-white p-0 ms-2 lh-1\" title=\"Remove\" data-bind=\"click: function(){ $parent.removeClientId($data); }\"><i class=\"fa fa-times\"></i></button>\n                    </span>\n                    <!-- /ko -->\n                </div>\n                <!-- /ko -->\n                <div class=\"form-text\" data-bind=\"visible: selectedClientIds().length === 0\">Not restricted, available to all.</div>\n                <!-- /ko -->\n            </div>\n            <div class=\"col-md-1 col-sm-1\">\n                <span data-bs-toggle=\"tooltip\" data-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"Leave blank to give Global access\"></span>\n            </div>\n        </div>\n        <div class=\"alert alert-info\">\n            <span class=\"fas fa-lightbulb fa-2x\"></span>&nbsp;User level rights override Role level rights. No selection for a rule implies report is available to all.\n        </div>\n\n        <div class=\"row small\">\n            <div class=\"col-md-6\">\n                <span class=\"clickable\" data-bind=\"click: toggleManageUsers\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showManageUsers(), 'fa-chevron-right': !showManageUsers() }\"></i> <b>Manage by User</b> (allow edit)</span>\n                <div data-bind=\"template: { name: 'access-selected-pills', data: { list: users, open: showManageUsers } }\"></div>\n                <div class=\"row container-fluid\" data-bind=\"visible: showManageUsers\">\n                    <!-- ko if: groupedUsers().length > 0 -->\n                    <!-- ko foreach: groupedUsers -->\n                    <div class=\"col-md-12\">\n                      <div class=\"category-header\" style=\"cursor: pointer;\" data-bind=\"click: function() { show(!show()); }\">\n                        <i class=\"fa toggle-icon\" data-bind=\"css: { 'fa-chevron-down': show(), 'fa-chevron-right': !show() }\"></i>\n                        <strong data-bind=\"text: category\"></strong>\n                      </div>\n                      <div class=\"row container-fluid\" data-bind=\"visible: show\">\n                        <!-- ko foreach: users -->\n                        <div class=\"float-start\">\n                          <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                              <input type=\"checkbox\" data-bind=\"checked: selected\"> &nbsp; <span data-bind=\"text: text\"></span>&nbsp; </label>\n                          </div>\n                        </div>\n                        <!-- /ko -->\n                      </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <!-- ko if: groupedUsers().length == 0 && users().length > 0 -->\n                    <!-- ko foreach: users -->\n                    <div class=\"float-start\">\n                        <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                                <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                            </label>\n                        </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <div data-bind=\"if: groupedUsers().length == 0 && users().length == 0\">\n                        Users list not populated or not applicable\n                    </div>\n                </div>\n                <br />\n                <span class=\"clickable\" data-bind=\"click: toggleViewUsers\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showViewUsers(), 'fa-chevron-right': !showViewUsers() }\"></i> <b>View only by User</b> (no edit/delete)</span>\n                <div data-bind=\"template: { name: 'access-selected-pills', data: { list: viewOnlyUsers, open: showViewUsers } }\"></div>\n                <div class=\"row container-fluid\" data-bind=\"visible: showViewUsers\">\n                    <!-- ko if: groupedViewOnlyUsers().length > 0 -->\n                    <!-- ko foreach: groupedViewOnlyUsers -->\n                    <div class=\"col-md-12\">\n                      <div class=\"category-header\" style=\"cursor: pointer;\" data-bind=\"click: function() { show(!show()); }\">\n                        <i class=\"fa toggle-icon\" data-bind=\"css: { 'fa-chevron-down': show(), 'fa-chevron-right': !show() }\"></i>\n                        <strong data-bind=\"text: category\"></strong>\n                      </div>\n                      <div class=\"row container-fluid\" data-bind=\"visible: show\">\n                        <!-- ko foreach: viewOnlyUsers -->\n                        <div class=\"float-start\">\n                          <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                              <input type=\"checkbox\" data-bind=\"checked: selected\"> &nbsp; <span data-bind=\"text: text\"></span>&nbsp; </label>\n                          </div>\n                        </div>\n                        <!-- /ko -->\n                      </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <!-- ko if: groupedViewOnlyUsers().length == 0 && viewOnlyUsers().length > 0 -->\n                    <!-- ko foreach: viewOnlyUsers -->\n                    <div class=\"float-start\">\n                        <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                                <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                            </label>\n                        </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <div data-bind=\"if: groupedViewOnlyUsers().length == 0 && viewOnlyUsers().length == 0\">\n                        Users list not populated or not applicable\n                    </div>\n                </div>\n                <br />\n                <div data-bind=\"ifnot: isDashboard\">\n                    <span class=\"clickable\" data-bind=\"click: toggleDeleteUsers\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showDeleteUsers(), 'fa-chevron-right': !showDeleteUsers() }\"></i> <b>Delete by User</b> (allow delete)</span>\n                    <div data-bind=\"template: { name: 'access-selected-pills', data: { list: deleteOnlyUsers, open: showDeleteUsers } }\"></div>\n                    <div class=\"row container-fluid\" data-bind=\"visible: showDeleteUsers\">\n                    <!-- ko if: groupedDeleteOnlyUsers().length > 0 -->\n                    <!-- ko foreach: groupedDeleteOnlyUsers -->\n                    <div class=\"col-md-12\">\n                      <div class=\"category-header\" style=\"cursor: pointer;\" data-bind=\"click: function() { show(!show()); }\">\n                        <i class=\"fa toggle-icon\" data-bind=\"css: { 'fa-chevron-down': show(), 'fa-chevron-right': !show() }\"></i>\n                        <strong data-bind=\"text: category\"></strong>\n                      </div>\n                      <div class=\"row container-fluid\" data-bind=\"visible: show\">\n                        <!-- ko foreach: deleteOnlyUsers -->\n                        <div class=\"float-start\">\n                          <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                              <input type=\"checkbox\" data-bind=\"checked: selected\"> &nbsp; <span data-bind=\"text: text\"></span>&nbsp; </label>\n                          </div>\n                        </div>\n                        <!-- /ko -->\n                      </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <!-- ko if: groupedDeleteOnlyUsers().length == 0 && deleteOnlyUsers().length > 0 -->\n                    <!-- ko foreach: deleteOnlyUsers -->\n                        <div class=\"float-start\">\n                            <div class=\"checkbox\">\n                                <label class=\"label label-info\">\n                                    <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                                </label>\n                            </div>\n                        </div>\n                        <!-- /ko -->\n                        <!-- /ko -->\n                        <div data-bind=\"if: groupedDeleteOnlyUsers().length == 0 && deleteOnlyUsers().length == 0\">\n                            Users list not populated or not applicable\n                        </div>\n                    </div>\n                    <br />\n                </div>\n            </div>\n            <div class=\"col-md-6\">\n                <span class=\"clickable\" data-bind=\"click: toggleManageRoles\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showManageRoles(), 'fa-chevron-right': !showManageRoles() }\"></i> <b>Manage by User Role</b> (allow edit)</span>\n                <div data-bind=\"template: { name: 'access-selected-pills', data: { list: userRoles, open: showManageRoles } }\"></div>\n                <div class=\"row container-fluid\" data-bind=\"visible: showManageRoles\">\n                    <!-- ko foreach: userRoles -->\n                    <div class=\"float-start\">\n                        <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                                <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                            </label>\n                        </div>\n                    </div>\n                    <!-- /ko -->\n                    <div data-bind=\"if: userRoles().length == 0\">\n                        User Roles list not populated or not applicable\n                    </div>\n                </div>\n                <br />\n                <span class=\"clickable\" data-bind=\"click: toggleViewRoles\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showViewRoles(), 'fa-chevron-right': !showViewRoles() }\"></i> <b>View only by User Role</b> (no edit/delete)</span>\n                <div data-bind=\"template: { name: 'access-selected-pills', data: { list: viewOnlyUserRoles, open: showViewRoles } }\"></div>\n                <div class=\"row container-fluid\" data-bind=\"visible: showViewRoles\">\n                    <!-- ko foreach: viewOnlyUserRoles -->\n                    <div class=\"float-start\">\n                        <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                                <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                            </label>\n                        </div>\n                    </div>\n                    <!-- /ko -->\n                    <div data-bind=\"if: viewOnlyUserRoles().length == 0\">\n                        User Roles list not populated or not applicable\n                    </div>\n                </div>\n                <div data-bind=\"ifnot: isDashboard\">\n                    <span class=\"clickable\" data-bind=\"click: toggleDeleteRoles\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showDeleteRoles(), 'fa-chevron-right': !showDeleteRoles() }\"></i> <b>Delete by User Role</b> (allow delete)</span>\n                    <div data-bind=\"template: { name: 'access-selected-pills', data: { list: deleteOnlyUserRoles, open: showDeleteRoles } }\"></div>\n                    <div class=\"row container-fluid\" data-bind=\"visible: showDeleteRoles\">\n                        <!-- ko foreach: deleteOnlyUserRoles -->\n                        <div class=\"float-start\">\n                            <div class=\"checkbox\">\n                                <label class=\"label label-info\">\n                                    <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                                </label>\n                            </div>\n                        </div>\n                        <!-- /ko -->\n                        <div data-bind=\"if: deleteOnlyUserRoles().length == 0\">\n                            User Roles list not populated or not applicable\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n\n<!-- Collapsed view of one access rule: who is selected, or that it is open to everyone. Hidden while the checkboxes are open. -->\n<script type=\"text/html\" id=\"access-selected-pills\">\n    <!-- ko ifnot: ko.unwrap(open) -->\n    <div class=\"d-flex flex-wrap gap-1 align-items-center my-1 ms-3\">\n        <!-- ko foreach: _.filter(list(), function (x) { return x.selected(); }) -->\n        <span class=\"badge bg-secondary d-inline-flex align-items-center\">\n            <span data-bind=\"text: text\"></span>\n            <button type=\"button\" class=\"btn btn-sm btn-link text-white p-0 ms-2 lh-1\" title=\"Remove\" data-bind=\"click: function(){ selected(false); }\"><i class=\"fa fa-times\"></i></button>\n        </span>\n        <!-- /ko -->\n        <span class=\"text-muted small\" data-bind=\"visible: !_.some(list(), function (x) { return x.selected(); })\"><i class=\"fa fa-globe\"></i> Everyone, not restricted</span>\n    </div>\n    <!-- /ko -->\n</script>\n<!-- Access summary badges for a report/folder/dashboard row (admin mode). Grey = restricted, outlined = open to all. -->\n<script type=\"text/html\" id=\"access-badges\">\n    <div class=\"d-flex flex-wrap gap-1 align-items-center\" data-bind=\"foreach: accessBadges($data, $root)\">\n        <span class=\"badge d-inline-flex align-items-center\" data-bind=\"attr: { title: title }, css: restricted ? 'bg-secondary' : 'bg-light text-muted border'\">\n            <!-- ko foreach: icons.split(' ') -->\n            <i class=\"fa me-1\" data-bind=\"css: $data\"></i>\n            <!-- /ko -->\n            <span data-bind=\"text: text\"></span>\n        </span>\n    </div>\n</script>\n<script type=\"text/html\" id=\"filter-group\">\n    <div class=\"query-builder form-inline\" data-bind=\"foreach: FilterGroups\">\n        <div class=\"rules-group-container\">\n            <div class=\"rules-group-header\" data-bind=\"attr: {parentdivid: generateUniqueId()}\">\n                <div data-bind=\"visible: !isRoot\">\n                    <div class=\"float-start\">\n                        <div class=\"btn-group btn-group-toggle btn-group-sm\" data-bs-toggle=\"buttons\" role=\"group\">\n                            <label class=\"btn btn-light active\" style=\"margin-right: 0px;\">\n                                <input type=\"radio\" data-bind=\"attr: { name: 'andOrGroup-' + $element.closest('.rules-group-header').getAttribute('parentdivid') }, checked: AndOr\" value=\"And\" /> And\n                            </label>\n                            <label class=\"btn btn-light active\">\n                                <input type=\"radio\" data-bind=\"attr: { name: 'andOrGroup-' + $element.closest('.rules-group-header').getAttribute('parentdivid') }, checked: AndOr\" value=\"Or\" /> Or\n                            </label>\n                        </div>\n                    </div>\n                    <div class=\"float-end\">\n                        <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parent.RemoveFilterGroup, visible: !isRoot\">Remove Group</button>&nbsp;\n                    </div>\n                </div>\n                <div data-bind=\"visible: isRoot\">\n                    <div class=\"float-start padded-div\">\n                        <label> &nbsp;Filter Conditions</label>\n                    </div>\n                </div>\n                <div class=\"clearfix\"></div>\n            </div>\n\n            <div class=\"rules-group-body\" data-bind=\"template: {name: 'filter-inner'}\"></div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"filter-details-summary\">\n    <!-- ko if: typeof ShowFilterDetails === 'function' && ShowFilterDetails() && typeof filterDetailsSummary === 'function' && filterDetailsSummary() -->\n    <div class=\"mb-2 py-1 small\" style=\"border-left: 3px solid #adb5bd; padding-left: 10px;\">\n        <i class=\"fa fa-filter\"></i>\n        <b>Filters:</b>\n        <span data-bind=\"html: filterDetailsSummary()\"></span>\n    </div>\n    <!-- /ko -->\n</script>\n\n<script type=\"text/html\" id=\"fly-filter-template\">\n    <div class=\"card\" data-bind=\"visible: FlyFilters().length>0 || DontExecuteOnRun\">\n        <div class=\"card-header\">\n            <a data-bs-toggle=\"collapse\" data-bind=\"attr: {'data-bs-target': '#filter-panel-' + ReportID() }\" href=\"#\">\n                <i class=\"fa fa-filter\"></i> Choose Filters\n            </a>\n        </div>\n        <div data-bind=\"attr: {id: 'filter-panel-' + ReportID() }, css: {collpased: !DontExecuteOnRun(), collapse: !DontExecuteOnRun()}\" class=\"card-body\">\n            <div>\n                <!-- ko foreach: FlyFilters -->\n                <div class=\"row\">\n                    <div class=\"col-sm-5 col-xs-4\">\n                        <div data-bind=\"with: Field\" class=\"checkbox\">\n                            <div class=\"checkbox\">\n                                <label>\n                                    <input type=\"checkbox\" title=\"Apply this filter\" data-bind=\"checked: $parent.Apply, disabled: forced\" /> <span data-bind=\"text: selectedFilterName\"></span>\n                                </label>\n                            </div>\n                        </div>\n                    </div>\n                    <div data-bind=\"with: Field\" class=\"col-sm-2 col-xs-3\">\n                        <div class=\"form-group\" data-bind=\"if: $parent.Apply\">\n                            <select class=\"form-select\" data-bind=\"options: fieldFilter, value: $parent.Operator\" required></select>\n                        </div>\n                    </div>\n                    <div data-bind=\"with: Field\" class=\"col-sm-5 col-xs-5\">\n                        <div data-bind=\"if: $parent.Apply\" data-parentprefix=\"F\" >\n                            <div data-bind=\"template: 'report-filter', data: $data\"></div>\n                        </div>\n                    </div>\n                </div>\n                <!-- /ko -->\n                <button class=\"btn btn-primary\" data-bind=\"click: ExecuteReport\">Run</button>\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"filter-inner\">\n    <div class=\"rules-list\">\n        <div class=\"rule-container\" data-bind=\"visible: Filters().length>0\">\n            <table class=\"table table-striped table-hover table-borderless\">\n                <thead>\n                    <tr>\n                        <th class=\"row\">\n                            <div class=\"col-md-1\"></div>\n                            <div class=\"col-md-4\">Field</div>\n                            <div class=\"col-md-2\"></div>\n                            <div class=\"col-md-4\">Filter</div>\n                            <div class=\"col-md-1\"></div>\n                        </th>\n                    </tr>\n                </thead>\n                <tbody data-bind=\"foreach: Filters\">\n                    <tr class=\"rule-container\">\n                        <td class=\"row\">\n                            <div class=\"col-md-1\">\n                                <select data-bind=\"value: AndOr, visible: $index()>0\" class=\"form-select\">\n                                    <option>And</option>\n                                    <option>Or</option>\n                                </select>\n                            </div>\n                            <div class=\"col-md-3\">\n                                <div class=\"form-group\">\n                                    <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"\n                                        options: $parents[$parents.length-2].selectedFieldsCanFilter != undefined\n                                                    ? $parents[$parents.length-2].selectedFieldsCanFilter\n                                                    : $parents[$parents.length-1].selectedFieldsCanFilter,\n                                        optionsText: 'selectedFieldName',\n                                        optionsCaption: 'Please Choose',\n                                        value: Field,\n                                        attr: {required: Field()==null?'required':false},\n                                        disable: Field() && Field().forced\"></select>\n                                </div>\n                            </div>\n                            <div class=\"col-md-2\">\n                                <div data-bind=\"with: Field\">\n                                    <div class=\"form-group\">\n                                        <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: fieldFilter, value: $parent.Operator\" required></select>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col-md-5\">\n                                <!-- ko ifnot: $data.useEmailListColumn && $data.useEmailListColumn() -->\n                                <div data-bind=\"with: Field\" data-parentprefix=\"M\">\n                                    <div data-bind=\"template: 'report-filter', data: $data\"></div>\n                                </div>\n                                <!-- /ko -->\n                                <!-- ko if: $root.scheduleEmailListColumns && $root.scheduleEmailListColumns().length > 0 -->\n                                <div class=\"form-check small mt-1\">\n                                    <label class=\"form-check-label text-muted\" title=\"Take this filter's value from the Email List query, one email per row\">\n                                        <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: useEmailListColumn\" /> Use value from Email List\n                                    </label>\n                                </div>\n                                <!-- ko if: $data.useEmailListColumn && $data.useEmailListColumn() -->\n                                <select class=\"form-select\" required data-bind=\"options: $root.scheduleEmailListColumns, optionsCaption: 'Choose Email List column...', value: EmailListColumn\"></select>\n                                <!-- /ko -->\n                                <!-- /ko -->\n                                <!-- ko if: Field() && Field().fieldType == 'DateTime' && Operator() == 'range' && $index()==0 -->\n                                <!-- ko if: $parents[$parents.length-2].canAddSeries != undefined && $parents[$parents.length-2].canAddSeries() -->\n                                <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parents[$parents.length-2].AddSeries.bind($data)\">Add Comparison</button>\n                                <!--/ko -->\n                                <!-- ko if: $parents[$parents.length-2].canAddSeries == undefined && $parentContext.$parent.canAddSeries != undefined && $parentContext.$parent.canAddSeries()-->\n                                <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parentContext.$parent.AddSeries.bind($data)\">Add Comparison</button>\n                                <!--/ko -->\n                                <!--/ko -->\n                                <span data-bind=\"visible: Field() && Field().forced\" class=\"badge bg-info\">Required Filter</span>\n                            </div>\n                            <div class=\"col-md-1\">\n                                <div style=\"display: flex; align-items: left;\">\n                                    <div class=\"form-group\" >\n                                        <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parent.RemoveFilter, hidden: Field() && Field().forced\" title=\"Remove\">\n                                            <i class=\"fa fa-trash\"></i>\n                                        </button>\n                                    </div>\n                                    <div class=\"form-group\" data-bind=\"with: Field, hidden: document.querySelector('#filter-panel.card-body.collapse') || ($root.scheduleFilterEditing && $root.scheduleFilterEditing())\">\n                                        <span class=\"btn btn-sm\" tabindex=\"0\" data-bind=\"click: function(){ filterOnFly(!filterOnFly()); }, css: {'btn-success': filterOnFly()==true, 'btn-secondary': !filterOnFly()}\">\n                                            <span class=\"fa fa-filter\" aria-hidden=\"true\" title=\"Filter on Report\"></span>\n                                        </span>\n                                    </div>\n                                </div>\n\n                            </div>\n                        </td>\n                    </tr>\n                    <!-- ko foreach: compareTo -->\n                    <tr>\n                        <td class=\"row\">\n                            <div class=\"col-md-6\">&nbsp;</div>\n                            <div class=\"col-md-2\">\n                                <span style=\"text-align: right\"><button class=\"btn btn-sm\" data-bind=\"click: $parents[2].RemoveSeries\"><span class=\"fa fa-trash\"></span></button></span>\n                                <span class=\"muted\">Compare to</span>\n                            </div>\n                            <div class=\"col-md-4\">\n                                <select class=\"form-select\" data-bind=\"options: Range, value: Value\" required></select>\n                            </div>\n                        </td>\n                    </tr>\n                    <!-- /ko -->\n                </tbody>\n            </table>\n        </div>\n\n        <div class=\"rule-container\">\n            <div data-bind=\"template: {name: 'filter-group'}\"></div>\n            <div>\n                <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: AddFilter\">Add Filter</button>\n                <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: AddFilterGroup\">Add Filter Group</button>\n            </div>\n        </div>\n    </div>\n\n</script>\n\n            <script type=\"text/html\" id=\"filter-parameters\">\n                <div class=\"table-responsive\">\n                        <span data-bind=\"hidden: showParameters\">No filters available to choose</span>\n                        <table class=\"table table-striped table-hover table-borderless\" data-bind=\"visible: showParameters\">\n                                <thead>\n                                        <tr>\n                                                <th style=\"width: 30%\">Filter</th>\n                                                <th style=\"width: 20%\"></th>\n                                                <th style=\"width: 30%\">Value</th>\n                                                <th style=\"width: 10%\"></th>\n                                        </tr>\n                                </thead>\n                                <tbody data-bind=\"foreach: Parameters\">\n                                        <tr data-bind=\"ifnot: Hidden\">\n                                                <td data-bind=\"text: DisplayName\"></td>\n                                                <td>\n                                                        <div class=\"form-group\">\n                                                                <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: operators, value: Operator\" required></select>\n                                                        </div>\n                                                </td>\n                                                <td data-bind=\"with: Field\" data-parentprefix=\"P\">\n                                                        <div data-bind=\"template: 'report-filter', data: $data\"></div>\n                                                </td>\n                                                <!-- CHANGED: was empty <td></td>, now has the fly-filter toggle -->\n                                                <td class=\"text-center\">\n                                                        <span class=\"btn btn-sm\" tabindex=\"0\"\n                                                            data-bind=\"click: function(){ filterOnFly(!filterOnFly()); },\n                                                                             css: {'btn-success': filterOnFly()==true, 'btn-secondary': !filterOnFly()}\">\n                                                                <span class=\"fa fa-filter\" aria-hidden=\"true\" title=\"Filter on Report\"></span>\n                                                        </span>\n                                                </td>\n                                        </tr>\n\n                                </tbody>\n                        </table>\n                </div>\n            </script>\n\n<script type=\"text/html\" id=\"report-schedule\">\n    <div data-bind=\"with: scheduleBuilder\" id=\"schedule-builder-div\">\n        <div class=\"form-check\">\n            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: hasSchedule\" id=\"scheduleReportCheckbox\">\n            <label class=\"form-check-label\" for=\"scheduleReportCheckbox\">\n                Set Schedule to send by Email\n            </label>\n        </div>\n        <div data-bind=\"if: hasSchedule\">\n            <div class=\"d-flex align-items-center\">\n                <div class=\"me-3 d-flex align-items-center\">\n                    <span data-bind=\"text: selectedOption() != 'once' ? 'Every ' : ''\"></span>&nbsp;\n                    <select class=\"form-select\" required data-bind=\"options: options, value: selectedOption\" style=\"min-width: 80px;\"></select>\n                </div>\n                <div data-bind=\"if: selectedOption() == 'once'\" class=\"me-3 d-flex align-items-center\">\n                    &nbsp;on&nbsp;<input data-bind=\"datepicker: selectedDate, datepickerOptions: {value: selectedDate}\" class=\"form-control\" required />\n                </div>\n                <div class=\"d-flex align-items-center\">\n                    <div data-bind=\"if: showDays\" class=\"d-flex align-items-center\">\n                        &nbsp;on&nbsp;\n                        <select multiple class=\"form-select ms-2\" required data-bind=\"select2: { placeholder: 'Choose Days', allowClear: true }, options: days, selectedOptions: selectedDays\"></select>\n                    </div>\n                    <div data-bind=\"if: showDates\" class=\"d-flex align-items-center\">\n                        &nbsp;on&nbsp;\n                        <select multiple class=\"form-select\" required data-bind=\"select2: { placeholder: 'Choose Dates', allowClear: true }, options: dates, selectedOptions: selectedDates\"></select>\n                    </div>\n                    <div data-bind=\"if: showMonths\" class=\"d-flex align-items-center\">\n                        &nbsp;on&nbsp;\n                        <select multiple class=\"form-select\" required data-bind=\"select2: { placeholder: 'Choose Months', allowClear: true }, options: months, selectedOptions: selectedMonths\"></select>\n                    </div>\n                    <div data-bind=\"if: showAtTime\" class=\"d-flex align-items-center ms-3\">\n                        &nbsp;at&nbsp;\n                        <select class=\"form-select me-2\" style=\"min-width: 60px;\" data-bind=\"options: hours, value: selectedHour\"></select>\n                        <select class=\"form-select me-2\" style=\"min-width: 60px;\" data-bind=\"options: minutes, value: selectedMinute\"></select>\n                        <select class=\"form-select\" style=\"min-width: 80px;\" data-bind=\"value: selectedAmPm\">\n                            <option>AM</option>\n                            <option>PM</option>\n                        </select>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"alert alert-info\">\n                Report will be run and emailed <span data-bind=\"text: selectedOption() != 'once' ? 'every' : ''\"></span> <span data-bind=\"text: selectedOption\"></span>\n                <span data-bind=\"if: selectedOption() == 'once'\">\n                    on <span class=\"error\" data-bind=\"visible: !selectedDate()\">Please pick a Date</span> <span data-bind=\"text: selectedDate\"></span>\n                </span>\n                <span data-bind=\"if: showDays\">\n                    on <span class=\"error\" data-bind=\"visible: selectedDays().length == 0\">Please pick Day(s)</span> <span data-bind=\"text: selectedDays\"></span>\n                </span>\n                <span data-bind=\"if: showDates\">\n                    on <span class=\"error\" data-bind=\"visible: selectedDates().length == 0\">Please pick Date(s)</span>\n                    <span data-bind=\"foreach: selectedDates\"><span data-bind=\"visible: $index()>0\">, </span><span data-bind=\"text: $data == 1 ? '1st': ($data == 2 ? '2nd' : ($data == 3 ? '3rd' : ($data == 31 ? '31st' : $data+'th')))\"></span></span>\n                </span>\n                <span data-bind=\"if: showMonths\">\n                    of <span class=\"error\" data-bind=\"visible: selectedMonths().length == 0\">Please pick Month(s)</span> <span data-bind=\"text: selectedMonths\"></span>\n                </span>\n                <span data-bind=\"if: showAtTime\">\n                    at <span data-bind=\"text: selectedHour\"></span>:<span data-bind=\"text: selectedMinute\"></span> <span data-bind=\"text: selectedAmPm\"></span>\n                </span>\n            </div>\n            <div class=\"mb-3\">\n                <div class=\"row g-2 align-items-center\">\n                    <div class=\"col-12 col-sm-3\">\n                        <label class=\"col-form-label pb-0\">Email to</label>\n                        <div class=\"form-check small\">\n                            <label class=\"form-check-label text-muted\" title=\"Send to a saved Email List instead of typing addresses\">\n                                <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: useEmailQuery\" />\n                                Email List\n                            </label>\n                        </div>\n                    </div>\n\n                    <div class=\"col-12 col-sm-6\">\n                        <!-- ko ifnot: useEmailQuery -->\n                        <input type=\"text\" class=\"form-control\"\n                               data-bind=\"value: emailTo\"\n                               placeholder=\"Enter Email Addresses separated by comma\" />\n                        <!-- /ko -->\n                        <!-- ko if: useEmailQuery -->\n                        <div class=\"d-flex align-items-center gap-2\">\n                            <select class=\"form-select\" data-bind=\"options: emailQueries, optionsText: 'name', optionsValue: 'id', value: emailQueryId, optionsCaption: 'Choose Email List...'\"></select>\n                            <button type=\"button\" class=\"btn btn-light btn-sm text-nowrap\"\n                                    data-bind=\"click: previewRecipients, enable: emailQueryId() > 0\"\n                                    title=\"Show who this Email List currently returns\">View</button>\n                        </div>\n                        <!-- /ko -->\n                    </div>\n\n                    <label class=\"col-6 col-sm-1 col-form-label\">Format</label>\n\n                    <div class=\"col-6 col-sm-2\">\n                        <select class=\"form-select\" data-bind=\"value: format,event: { change: onFormatChange }\">\n                            <option value=\"EXCEL\">Excel</option>\n                            <option data-bind=\"visible: $parent.canDrilldown && $parent.canDrilldown()\" value=\"EXCEL-SUB\">Excel (Expanded)</option>\n                            <option value=\"CSV\">CSV</option>\n                            <option value=\"PDF\">PDF</option>\n                            <option value=\"WORD\">Word</option>\n                            <option value=\"LINK\">Link</option>\n                        </select>\n                    </div>\n                </div>\n            </div>\n            <div class=\"mb-3\">\n                <div class=\"row g-2 align-items-center\">\n                    <label class=\"col-12 col-sm-3 col-form-label\">Pick Time Zone</label>\n\n                    <div class=\"col-12 col-sm-9\">\n                        <select class=\"form-select\"\n                                data-bind=\"options: timezonOption,\n                                           optionsText: 'displayName',\n                                           optionsValue: 'timeZoneId',\n                                           value: selectedTimezone,\n                                           select2: {dropdownParent: $element.closest('.modal'), allowClear: true, placeholder: 'Set a time zone'}\">\n                        </select>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"mb-3\">\n                <div class=\"row g-2\">\n                    <div class=\"col-6 col-sm-3\">\n                        <div class=\"form-check\" title=\"Set a date to start sending scheduled report\">\n                            <input class=\"form-check-input\" type=\"checkbox\"\n                                   data-bind=\"checked: hasScheduleStart\"\n                                   id=\"scheduleStartCheckbox\">\n                            <label class=\"form-check-label\" for=\"scheduleStartCheckbox\">\n                                Schedule Start Date\n                            </label>\n                        </div>\n                    </div>\n\n                    <div class=\"col-6 col-sm-4\" data-bind=\"if: hasScheduleStart\">\n                        <input type=\"text\" class=\"form-control\"\n                               data-bind=\"datepicker: scheduleStart, datepickerOptions: {value: scheduleStart}\"\n                               title=\"Scheduled Report will not be sent before this date\"\n                               required />\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"mb-3\">\n                <div class=\"row g-2\">\n                    <div class=\"col-6 col-sm-3\">\n                        <div class=\"form-check\"  title=\"Set a date to stop sending scheduled report\">\n                            <input class=\"form-check-input\" type=\"checkbox\"\n                                   data-bind=\"checked: hasScheduleEnd\"\n                                   id=\"scheduleEndCheckbox\">\n                            <label class=\"form-check-label\" for=\"scheduleEndCheckbox\">\n                                Schedule End Date\n                            </label>\n                        </div>\n                    </div>\n\n                    <div class=\"col-6 col-sm-4\" data-bind=\"if: hasScheduleEnd\">\n                        <input type=\"text\" class=\"form-control\"\n                               data-bind=\"datepicker: scheduleEnd, datepickerOptions: {value: scheduleEnd}\"\n                               title=\"Scheduled Report will not be sent after this date\"\n                               required />\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n\n</script>\n\n<script type=\"text/html\" id=\"report-field-options\">\n    <div class=\"modal-dialog\" style=\"max-width: 750px;\">\n        <div class=\"modal-content\" data-bind=\"with: editFieldOptions\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\"><span data-bind=\"text: fieldName\"></span> - Setup Additional Field Options</h5>\n            </div>\n            <div class=\"modal-body needs-validation\">\n                <div class=\"card card-body\">\n                    <b>Column Format Settings</b>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pick Data Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" data-bind=\"options: ['Days', 'Hours', 'Minutes', 'Seconds'].indexOf(fieldFormat()) >= 0 ? ['Days', 'Hours', 'Minutes', 'Seconds'] : $parents[1].fieldFormatTypes, value: fieldFormat\"></select>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: $parents[1].decimalFormatTypes.indexOf($data.fieldFormat())>=0\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pick Decimal Places</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"number\" class=\"form-control\" data-bind=\"value: decimalPlaces\" placeholder=\"\" />\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: fieldFormat()=='Currency'\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pick Currency Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" required data-bind=\"options: $parents[1].currencyFormats, optionsText: 'display',optionsValue: 'value', value: currencyFormat\"></select>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: fieldFormat()=='Date'\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pick Date Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" data-bind=\"options: $parents[1].dateFormats, value: dateFormat\"></select>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible:selectedAggregate()=='Pivot' && fieldFormat()=='Date'\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pivot Drilldown Date Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" data-bind=\"options: ['', 'Day', 'Month', 'Year', 'Month/Year'], value: drillDataFormat\"></select>\n                        </div>\n                    </div>\n\n                    <div class=\"form-group row\" data-bind=\"visible: fieldFormat()=='Date' && dateFormat()==='Custom'\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Enter Custom Date Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                        <div class=\"input-group\">\n                                <input type=\"text\" class=\"form-control\" data-bind=\"value: customDateFormat\" placeholder=\"dd/MM/yyyy\" />\n                                <button type=\"button\" class=\"btn btn-outline-secondary\" tabindex=\"-1\"\n                                  data-bind=\"bsPopover: { \n                                    trigger: 'focus', \n                                    placement: 'bottom', \n                                    html: true, \n                                    title: 'Date Format Tokens', \n                                    content:$root.dateFormatPopoverContent \n                                  }\">\n                                  <i class=\"fa fa-question-circle\"></i>\n                                </button>\n                            </div>\n                    </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Choose Column Label</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" data-bind=\"value: fieldLabel\" />\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Inner Column Label</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" data-bind=\"value: fieldLabel2\" />\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Choose Text Alignment</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" data-bind=\"options: $parents[1].fieldAlignments, value: fieldAlign\"></select>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Choose Width (leave blank for auto)</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" data-bind=\"value: fieldWidth\" />\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <div class=\"col-sm-12\">\n                            <div class=\"checkbox float-start\" >\n                                <label>\n                                    <input type=\"checkbox\" data-bind=\"checked: outerGroup\" />\n                                    <b>Outer Group</b> - Use this field as a group heading\n                                </label>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: $parents[1].IncludeSubTotal()\">\n                        <div class=\"col-sm-12 d-flex align-items-center\">\n                            <div class=\"checkbox\">\n                                <label>\n                                    <input type=\"checkbox\" data-bind=\"checked: dontSubTotal\" />\n                                    <b>Don't Show In Total Row</b>\n                                </label>\n                            </div>\n                            <button class=\"btn btn-sm btn-secondary ms-2\" title=\"Apply to all columns\" data-bind=\"click: function(){ applyAllDontSubTotal(!applyAllDontSubTotal()); }\">\n                                <span class=\"fa\" data-bind=\"css: applyAllDontSubTotal() ? 'fa-check' : 'fa-paste'\"></span>\n                            </button>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: $parents[1].IncludeSubTotal() && !dontSubTotal()\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Total Row Aggregate</label>\n                        <div class=\"col-sm-7 col-md-7 d-flex align-items-center\">\n                            <select class=\"form-select\" data-bind=\"options: totalRowAggregateOptions, value: totalRowAggregate\"></select>\n                            <button class=\"btn btn-sm btn-secondary ms-2\" title=\"Apply to all columns\" data-bind=\"click: function(){ applyAllTotalRowAggregate(!applyAllTotalRowAggregate()); }\">\n                                <span class=\"fa\" data-bind=\"css: applyAllTotalRowAggregate() ? 'fa-check' : 'fa-paste'\"></span>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n                <br />\n                <div data-bind=\"visible:$parent.ReportType() !='Html'\">\n                <div class=\"card card-body\">\n                    <div class=\"form-row align-items-center\">\n                        <div class=\"col-auto\">\n                            <b>Header Settings</b>\n                        </div>\n                    </div>\n                    <div class=\"row mb-3\">\n                        <div class=\"col\">\n                            <div class=\"mb-3\">\n                                <label class=\"form-label\">Pick Text Color</label>\n                                <div class=\"d-flex\">\n                                    <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: headerFontColor\" />\n                                    <input type=\"text\" style=\"width: 100px\" class=\"form-control me-2\" data-bind=\"value: headerFontColor\" />\n                                    <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllHeaderFontColor(!applyAllHeaderFontColor()); }\">\n                                        <span class=\"fa\" data-bind=\"css: applyAllHeaderFontColor() ? 'fa-check' : 'fa-paste'\"></span>\n                                    </button>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col\">\n                            <div class=\"mb-3\">\n                                <label class=\"form-label\">Pick Background Color</label>\n                                <div class=\"d-flex\">\n                                    <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: headerBackColor\" />\n                                    <input type=\"text\" style=\"width: 100px\" class=\"form-control me-2\" data-bind=\"value: headerBackColor\" />\n                                    <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllHeaderBackColor(!applyAllHeaderBackColor()); }\">\n                                        <span class=\"fa\" data-bind=\"css: applyAllHeaderBackColor() ? 'fa-check' : 'fa-paste'\"></span>\n                                    </button>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col d-flex align-items-center\">\n                            <div class=\"form-check me-3\">\n                                <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: headerFontBold\" id=\"headerFontBoldCheckbox\">\n                                <label class=\"form-check-label\" for=\"headerFontBoldCheckbox\">\n                                    Bold Text\n                                </label>\n                            </div>\n                            <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllHeaderBold(!applyAllHeaderBold()); }\">\n                                <span class=\"fa\" data-bind=\"css: applyAllHeaderBold() ? 'fa-check' : 'fa-paste'\"></span>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n                <br />\n                </div>\n                <div class=\"card card-body\">\n                    <div class=\"form-row align-items-center\">\n                        <div class=\"col-auto\">\n                            <b>Text Settings</b>\n                        </div>\n                    </div>\n                    <div class=\"row mb-3\">\n                        <div class=\"col\">\n                            <div class=\"mb-3\">\n                                <label class=\"form-label\">Pick Text Color</label>\n                                <div class=\"d-flex\">\n                                    <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: fontColor\" />\n                                    <input type=\"text\" style=\"width: 100px;\" class=\"form-control me-2\" data-bind=\"value: fontColor\" />\n                                    <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllFontColor(!applyAllFontColor()); }\">\n                                        <span class=\"fa\" data-bind=\"css: applyAllFontColor() ? 'fa-check' : 'fa-paste'\"></span>\n                                    </button>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col\">\n                            <div class=\"mb-3\">\n                                <label class=\"form-label\">Pick Background Color</label>\n                                <div class=\"d-flex\">\n                                    <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: backColor\" />\n                                    <input type=\"text\" style=\"width: 100px;\" class=\"form-control me-2\" data-bind=\"value: backColor\" />\n                                    <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllBackColor(!applyAllBackColor()); }\">\n                                        <span class=\"fa\" data-bind=\"css: applyAllBackColor() ? 'fa-check' : 'fa-paste'\"></span>\n                                    </button>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col d-flex align-items-center\">\n                            <div class=\"form-check me-3\">\n                                <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: fontBold\" id=\"fontBoldCheckbox\">\n                                <label class=\"form-check-label\" for=\"fontBoldCheckbox\">\n                                    Bold Text\n                                </label>\n                            </div>\n                            <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllBold(!applyAllBold()); }\">\n                                <span class=\"fa\" data-bind=\"css: applyAllBold() ? 'fa-check' : 'fa-paste'\"></span>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n                <div class=\"padded-div\">\n                    <button class=\"btn btn-sm btn-primary\" data-bind=\"click: function() {addConditionalFormatSetting(null)}\">Add Conditional Formatting</button>\n                </div>\n                <div data-bind=\"foreach: fieldCondtionalFormats\" style=\"padding-left: 40px;\">\n                    <div class=\"card card-body\">\n                        <div class=\"row m-2\">\n                            <div class=\"col d-flex justify-content-start\">\n                                <b>Conditional Format #<span data-bind=\"text: $index()+1\"></span></b>\n                            </div>\n                            <div class=\"col d-flex justify-content-end\">\n                                <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parent.removeSetting\">Remove</button>\n                            </div>\n                        </div>\n                        <div class=\"row mb-3\">\n                            <div class=\"col\">\n                                <div class=\"mb-3\">\n                                    <label class=\"form-label\">Pick Text Color</label>\n                                    <div class=\"d-flex\">\n                                        <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: fontColor\" />\n                                        <input type=\"text\" style=\"width: 100px;\" class=\"form-control me-2\" data-bind=\"value: fontColor\" />\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col\">\n                                <div class=\"mb-3\">\n                                    <label class=\"form-label\">Pick Background Color</label>\n                                    <div class=\"d-flex\">\n                                        <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: backColor\" />\n                                        <input type=\"text\" style=\"width: 100px;\" class=\"form-control me-2\" data-bind=\"value: backColor\" />\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col d-flex align-items-center\">\n                                <div class=\"form-check me-3\">\n                                    <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: fontBold\" id=\"fontBoldCheckbox\">\n                                    <label class=\"form-check-label\" for=\"fontBoldCheckbox\">\n                                        Bold Text\n                                    </label>\n                                </div>\n                            </div>\n                        </div>\n\n                        <div class=\"row m-2\" data-bind=\"foreach: filter.Filters\">\n                            <div class=\"col-md-2\">\n                                Value\n                            </div>\n                            <div class=\"col-md-4\">\n                                <div data-bind=\"with: Field\">\n                                    <div class=\"form-group\">\n                                        <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: fieldFilter, value: $parent.Operator\" required></select>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col-md-4\">\n                                <div data-bind=\"with: Field\" data-parentprefix=\"C\">\n                                    <div data-bind=\"template: 'report-filter', data: $data\"></div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <br />\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-danger\" data-bind=\"click: cancelFieldOptions\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: saveFieldOptions\">Save Changes</button>\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"report-link-edit\">\n    <div class=\"modal-dialog\" style=\"max-width: 750px;\">\n        <div class=\"modal-content\" data-bind=\"with: editLinkField\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\">Setup Link Field</h5>\n            </div>\n            <div class=\"modal-body needs-validation\" data-bind=\"with: linkFieldItem\">\n                <div class=\"form-group row\">\n                    <label class=\"col-sm-5 col-md-5 control-label\">This field will link to</label>\n                    <div class=\"col-sm-7 col-md-7\">\n                        <select class=\"form-select\" required data-bind=\"options: linkTypes, value: selectedLinkType\"></select>\n                    </div>\n                </div>\n                <div data-bind=\"if: LinksToReport\">\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Link to this Report</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <div class=\"d-flex gap-2 align-items-start\">\n                                <select class=\"form-select\" required data-bind=\"options: savedReportsWithFolder, optionsText: function(r) { return (r.folderName ? r.folderName + ' › ' : '') + r.reportName }, optionsValue: 'reportId', optionsCaption: '', value: LinkedToReportId, select2: { placeholder: 'Search reports or folders...', allowClear: true }\"></select>\n                                <button type=\"button\" class=\"btn btn-sm btn-outline-success text-nowrap\" title=\"Create a new report to link to\" data-bind=\"click: createNewLinkedReport\">\n                                    New\n                                </button>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"checkbox\" data-bind=\"if: LinkedToReportId\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: SendAsFilterParameter\" />\n                            Send field value as Report Filter Parameter\n                        </label>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"if: SendAsFilterParameter\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Link to this Report Filter</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" required data-bind=\"options: allFields, optionsText: function(f) { return (f.tableName ? f.tableName + ' › ' : '') + f.fieldName }, optionsValue: 'fieldId', value: SelectedFilterId, optionsCaption: 'Choose the Field to Filter by value'\"></select>\n                        </div>\n                    </div>\n                    <div data-bind=\"if: LinkedToReportId\">\n                        <div class=\"mt-2 mb-1\">\n                            <label class=\"form-check-label\">\n                                <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: isSubReportOnly, click: function() { toggleLinkedReportSubReportOnly(); return true; }\" />\n                                <span class=\"small\">Only use as sub/linked report</span>\n                            </label>\n                            <div class=\"small text-muted ms-4\">\n                                When checked, this report will be hidden from report folders and search results, and will only be run as a linked or sub report from the parent report.\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <div data-bind=\"ifnot: LinksToReport\">\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Link to this URL</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" required placeholder=\"Enter a url to open\" data-bind=\"value: LinkToUrl\" title=\"Valid URL needs to start with http:// or https://\">\n                        </div>\n                    </div>\n                    <div class=\"checkbox\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: SendAsQueryParameter\" />\n                            Send field value as Query Parameter\n                        </label>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"if: SendAsQueryParameter\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Parameter Name to use</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" required placeholder=\"Enter parameter name to send value as\" data-bind=\"value: QueryParameterName\">\n                        </div>\n                    </div>\n                    <br />\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-danger\" data-bind=\"click: removeLinkField\">Remove Link</button>\n                <button type=\"button\" class=\"btn btn-outline-primary\" data-bind=\"visible: linkFieldItem.LinksToReport() && linkFieldItem.LinkedToReportId(), click: function() { saveLinkField(); linkFieldItem.editLinkedReport(); }\">Edit Linked Report</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: saveLinkField\">Save Changes</button>\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-choose-visual\">\n    <div style=\"overflow-x: auto;\">\n    <div class=\"btn-group\" role=\"group\" aria-label=\"Visualization Options\" style=\"flex-wrap: nowrap; min-width: max-content;\">\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('List'); }, css: { active: ReportType()=='List' }, attr: { 'data-chart-id': 'List' }\">\n            <span class=\"fa fa-2x fa-list-alt\"></span>\n            <p>List</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Summary'); }, css: { active: ReportType()=='Summary',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Summary' }\">\n            <span class=\"fa fa-2x fa-table\"></span>\n            <p>Summary</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Bar'); }, css: { active: ReportType()=='Bar',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Bar' }\">\n            <span class=\"fa fa-2x fa-bar-chart\"></span>\n            <p>Bar</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Pie'); }, css: { active: ReportType()=='Pie',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Pie' }\">\n            <span class=\"fa fa-2x fa-pie-chart\"></span>\n            <p>Pie</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Line'); }, css: { active: ReportType()=='Line',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Line' }\">\n            <span class=\"fa fa-2x fa-line-chart\"></span>\n            <p>Line</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Combo'); }, css: { active: ReportType()=='Combo',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Combo' }\">\n            <span class=\"fa fa-2x fa-signal\"></span>\n            <p>Combo</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Html'); }, css: { active: ReportType()=='Html',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Html' }\">\n            <span class=\"fa fa-2x fa-code\"></span>\n            <p>Custom</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Map'); }, css: { active: ReportType().indexOf('Map')==0,disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Map' }\">\n            <span class=\"fa fa-2x fa-globe\"></span>\n            <p>Map</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Single'); }, css: { active: ReportType()=='Single',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Single' }\">\n            <span class=\"fa fa-2x fa-window-maximize\"></span>\n            <p>KPI</p>\n        </button>\n        <button class=\"btn btn-outline-secondary\" data-bind=\"click: showMoreCharts\" title=\"Explore more visualization options\">\n            <span class=\"fa fa-2x fa-th-large\"></span>\n            <p>More...</p>\n        </button>\n    </div>\n    </div>\n    <!-- Smart Suggestion -->\n    <div class=\"smart-suggestion mt-2\" data-bind=\"visible: smartSuggestion() && (showHints() || activeDesign())\">\n        <i class=\"fas fa-lightbulb text-warning\"></i>\n        <span data-bind=\"text: smartSuggestion\"></span>\n        <a href=\"#\" class=\"ms-2 small\" data-bind=\"click: applySuggestion\">\n            <i class=\"fa fa-check\"></i> Apply\n        </a>\n    </div>\n</script>\n\n<!-- ══════════════════ MORE CHARTS MODAL ══════════════════ -->\n<div class=\"modal\" id=\"moreChartsModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-xl modal-dialog-centered\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header py-2\">\n                <h5 class=\"modal-title\" id=\"moreChartsModalLabel\">\n                    <i class=\"fa fa-th-large\"></i> Choose a Visualization\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body p-0\" data-bind=\"stopBindings: true\">\n                <div class=\"d-flex more-charts-layout\">\n                    <!-- Left: Chart Type Grid (rendered programmatically by showMoreCharts) -->\n                    <div class=\"more-charts-grid-panel\" id=\"moreChartsGridPanel\"></div>\n                    <!-- Right: Detail Preview Panel (rendered programmatically by selectMoreChart) -->\n                    <div class=\"more-charts-detail-panel\" id=\"moreChartsDetailPanel\"></div>\n                </div>\n            </div>\n            <div class=\"modal-footer py-2\">\n                <button type=\"button\" class=\"btn btn-secondary btn-sm\" data-bs-dismiss=\"modal\">Close</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<script type=\"text/html\" id=\"designer-choose-data\">\n    <div>\n        <div class=\"float-start btn-group btn-group-toggle\" role=\"group\" data-bind=\"if: ReportID() <= 0\">\n            <label class=\"btn btn-sm btn-light\" style=\"margin-right: 0px;\" title=\"You can change the Data source only when creating a new report, changing this will clear all selections\" data-bind=\"css: { active: !useStoredProc() }\">\n                <input type=\"radio\" name=\"dataoption\" id=\"table\" checked data-bind=\"checked: useStoredProc, checkedValue: false\"> Dynamic\n            </label>\n            <label class=\"btn btn-sm btn-light\" data-bind=\"css: { active: useStoredProc() }\">\n                <input type=\"radio\" name=\"dataoption\" id=\"proc\" value=\"1\" data-bind=\"checked: useStoredProc, checkedValue: true\"> Predefined\n            </label>\n        </div>\n        <div class=\"float-end\">\n            <a href=\"#\" class=\"btn btn-sm\" style=\"font-size: 11px; padding: 3px 8px;\" title=\"Add Custom Field using Formula\" data-bind=\"hidden: isFunctionField() || useStoredProc(), click: cancelFormulaField, css: {'btn-primary': !isFormulaField(), 'btn-danger btn-sm': isFormulaField}\">\n                <!-- ko ifnot: isFormulaField() -->Custom Field<!-- /ko -->\n                <!-- ko if: isFormulaField() --><i class=\"fa fa-times\"></i><!-- /ko -->\n            </a>\n            <a href=\"#\" class=\"btn btn-sm\" style=\"font-size: 11px; padding: 3px 8px;\" title=\"Add Custom Field using Function\" data-bind=\"hidden:isFormulaField() || useStoredProc() || !ko.unwrap(appSettings.useFunctions) || ReportType() !== 'List' , click: function(){designFunctionField()}, css: {'btn-primary': !isFunctionField(), 'btn-danger btn-sm': isFunctionField}\">\n                <!-- ko ifnot: isFunctionField() -->Function Field<!-- /ko -->\n                <!-- ko if: isFunctionField() --><i class=\"fa fa-times\"></i><!-- /ko -->\n            </a>\n        </div>\n    </div>\n    <div class=\"clearfix\"></div>\n    <div class=\"row\">\n        <div class=\"col-md-12\" data-bind=\"disable: isFormulaField, hidden: useStoredProc\">\n            <div data-bind=\"with: textQuery.searchFields\">\n                <select class=\"form-control\" data-bind=\"select2: {dropdownParent: $root.activeDesign() ? $('#choose-data-design') : $('#choose-data-card'), placeholder: 'Search for a Data Field...', ajax: { url: url, dataType: 'json', data: query, processResults: processResults, headers: headers }, minimumInputLength: 2, allowClear: true }, value: selectedOption\"></select>\n            </div>\n        </div>\n\n        <div class=\"col-md-12\" data-bind=\"visible: useStoredProc\">\n            <div>\n                <select class=\"form-control\" data-bind=\"select2Value: {dropdownParent: $root.activeDesign() ? $('#choose-data-design') : $('#choose-data-card')}, options: Procs, optionsCaption: 'Choose Section...', optionsText: 'DisplayName', value: SelectedProc, visible: useStoredProc\"></select>\n            </div>\n        </div>\n        <div class=\"col-md-12\" data-bind=\"hidden: useStoredProc\">\n            <div class=\"d-flex justify-content-between align-items-center mb-2\" style=\"padding-top: 15px;\">\n                <span>\n                    Select Data to use in Report\n                    <i class=\"fa fa-info-circle text-muted\" data-toggle=\"tooltip\" title=\"Choose a table to show fields to select.\"></i>\n                </span>\n            </div>\n\n            <div class=\"data-select-tree\">\n                <!-- ko foreach: CategorizedTables -->\n                <div class=\"mb-3\">\n                    <div data-bind=\"click: function() { isExpanded(!isExpanded()); }, visible: categoryName\" style=\"cursor: pointer;\">\n                        <i class=\"fa\" data-bind=\"css: isExpanded() ? 'fa-chevron-down text-secondary' : 'fa-chevron-right text-secondary'\"></i>\n                        <i class=\"fa\" data-bind=\"css: isExpanded() ? 'fa-folder-open' : 'fa-folder'\"></i>\n                        <span data-bind=\"text: categoryName\" class=\"ml-2\"></span>\n                    </div>\n                    <div class=\"report-list\" data-bind=\"visible: isExpanded(), foreach: tables\" style=\"padding-left: 15px;\">\n                        <div class=\"row border-bottom py-2 w-100\">\n                            <div class=\"col-md-12\">\n                                <div class=\"float-start\" data-bind=\"click: function() { selectTable($data); }, css: {'text-muted': !isEnabled()}, style: {cursor: isEnabled() ? 'pointer' : ''}, attr: {title: !isEnabled() ? 'Cannot use table as joins do not exist': ''}\">\n                                    <span class=\"text-secondary fa\" data-bind=\"css: isEnabled() ? ($data === $parents[1].SelectedTable() ? 'fa-chevron-down' : 'fa-chevron-right') : 'fa-ban'\"></span>&nbsp;\n                                    <span class=\"fa fa-table\"></span>&nbsp;<span data-bind=\"text: tableName\" class=\"\"></span>\n                                </div>\n                                <div class=\"float-end\" data-bind=\"visible: $data === $parents[1].SelectedTable() && !$parents[1].isFormulaField() && !$parents[1].SelectedTable().dynamicColumns\">\n                                    <a href=\"#\" class=\"small text-muted\" data-bind=\"click: $parents[1].MoveAllFields\">Select all</a> |\n                                    <a href=\"#\" class=\"small text-muted\" data-bind=\"click: $parents[1].RemoveSelectedFields\">Remove all</a>\n                                </div>\n                            </div>\n\n                            <!-- Fields Expand Here -->\n                            <div data-bind=\"visible: $data === $parents[1].SelectedTable()\" style=\"padding-left: 30px;\">\n                                <!-- ko foreach: $parents[1].ChooseFields -->\n                                <div class=\"row border-bottom py-2 align-items-center w-100\">\n                                    <div class=\"checkbox\">\n                                        <label>\n                                            <input type=\"checkbox\" data-bind=\"checkedInArray: {array: $parents[2].isFormulaField() ? $parents[2].formulaFields : $parents[2].SelectedFields, value: $data}\">\n                                            <span data-bind=\"text: fieldName\"></span>\n                                        </label>\n                                    </div>\n                                </div>\n                                <!--/ko-->\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <!-- /ko -->\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-selected-data\">\n    <div data-bind=\"visible: SelectedFields().length == 0\">\n        Please choose data\n    </div>\n    <div data-bind=\"if: SelectedFields().length > 0\">\n        <div data-bind=\"visible: ReportType()=='Bar'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Bar Graph, the first field below will show on the x-axis. All other numeric fields will show on y-axis.\n            </div>\n            <div class=\"form-group row small\">\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: barChartHorizontal\" />\n                Horizontal Bar Chart\n                </label>\n            </div>\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: barChartStacked\" />\n                Stacked Bar Chart\n                </label>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Pie'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Pie Graph, the first field below will be grouped, and the first numeric field will show as the ratio.\n            </div>\n            <div class=\"form-group row small\">\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: pieChartDonut\" />\n                Donut Chart\n                </label>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Radar'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Radar chart, the first field is the category label. All other numeric fields become axes on the radar. Each row is a separate polygon.\n            </div>\n        </div>\n        <div data-bind=\"visible: ReportType()=='Polar'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Polar Stacked Bar, the first field is the category. Each numeric field becomes a stacked segment on the circular axis.\n            </div>\n        </div>\n        <div data-bind=\"visible: ReportType()=='Treemap'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Treemap, the data must be in a hierarchical format with 2nd column having parent and third column having a numeric value. The data must have a single root node having null as its parent as well.\n            </div>\n        </div>\n        <div data-bind=\"visible: ReportType()=='HeatMap'\" class=\"card card-body\">\n            <div class=\"alert alert-info mb-3\">\n                <span class=\"fas fa-lightbulb fa-2x\"></span>&nbsp;For HeatMap, the first two columns must be numeric values representing\n                <strong>Latitude</strong> and <strong>Longitude</strong>. At least one additional numeric column is required to provide the\n                <strong>intensity</strong> of each point.\n            </div>\n\n            <div class=\"form-group row mb-2\">\n                <div class=\"checkbox col-6\">\n                    <label>\n                        <input type=\"checkbox\" data-bind=\"checked: heatMapOptions.showMarker\" />\n                        Show Marker\n                    </label>\n                </div>\n            </div>\n\n            <div class=\"form-group row mb-3\">\n                <label class=\"col-12 fw-bold\">Heatmap Colors</label>\n\n                <div class=\"col-4 mb-2\">\n                    <input type=\"color\" class=\"color-picker\"\n                            data-bind=\"value: heatMapOptions.gradient1\" title=\"Gradient 1\" />\n                </div>\n                <div class=\"col-4 mb-2\">\n                    <input type=\"color\" class=\"color-picker\"\n                            data-bind=\"value: heatMapOptions.gradient2\" title=\"Gradient 2\" />\n                </div>\n                <div class=\"col-4 mb-2\">\n                    <input type=\"color\" class=\"color-picker\"\n                            data-bind=\"value: heatMapOptions.gradient3\" title=\"Gradient 3\" />\n                </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Line'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Line Graph, the first field below will show on the x-axis. All other fields will numeric fields will show on y-axis.\n            </div>\n            <div class=\"form-group row small\">\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: lineChartArea\" />\n                Area Chart\n                </label>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Combo'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Combo Graph, the first field below will show on the x-axis. All other numeric fields will show on y-axis, and you can choose display each series as line, bar or area.\n            </div>\n            <div class=\"form-group row small\">\n            <div class=\"col-6\">\n                <label>Default Series Type</label>\n                <select class=\"form-select form-select-sm\" data-bind=\"options: seriesTypes, optionsText: 'label', optionsValue: 'value', value: comboChartType\"></select>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Pivot'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Transpose, the first field below will be used to Transpose the rows as columns, and it must be grouped.\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Single'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;KPI is a single value report that is ideal for placing on a Dashboard. All fields except one must be hidden for Widgets.\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Html'\" class=\"card card-body\">\n            <div class=\"form-group row small\">\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: dontGroupCustom\" />\n                List (Don't Summarize)\n                </label>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Map'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Map Graph, the first field below has to be a Region name (e.g. Country) or use Latitude/Longitude columns for marker mode.\n            </div>\n            <div class=\"form-group row small\">\n            <label class=\"col-sm-3 control-label\">Map Display</label>\n            <div class=\"col-sm-5\">\n                <select class=\"form-select form-select-sm\" data-bind=\"options: mapRegions, value: mapRegion\"></select>\n            </div>\n            </div>\n            <div class=\"form-group row small\" data-bind=\"visible: mapRegion() == 'Other'\">\n            <label class=\"col-sm-3 control-label\">Region Name</label>\n            <div class=\"col-sm-5\">\n                <input type=\"text\" class=\"form-control form-control-sm\" placeholder=\"e.g. Texas, United Kingdom, Australia\" data-bind=\"value: otherMapRegion, valueUpdate: 'input'\" />\n            </div>\n            <div class=\"col-sm-4 small text-muted pt-1\">Enter any country, state, or region name</div>\n            </div>\n        </div>\n    </div>\n    <ul class=\"list-group\" data-bind=\"sortable: { data: SelectedFields, options: { handle: '.sortable', cursor: 'move', placeholder: 'drop-highlight' }, strategyMove: true }\">\n        <li class=\"list-group-item\">\n            <div class=\"row\">\n                <div class=\"col-5\">\n                    <span class=\"sortable float-start\" style=\"padding-right: 15px;\" data-bind=\"ifnot: $parent.useStoredProc\">\n                        <span class=\"fa fa-ellipsis-v\" aria-hidden=\"true\" title=\"Drag to reorder\"></span>\n                    </span>\n                    <span class=\"fa fa-columns\"></span>\n                    <span data-bind=\"text: selectedFieldName()\"></span>\n                    <span data-bind=\"text: isFormulaField() ? '(' + fieldFormat() + ')' : ''\"></span>\n                    <span data-bind=\"visible: !$parent.isFieldValidForYAxis($index(), fieldType || fieldFormat(), selectedAggregate()) && $parent.ReportType() !='Treemap' && $parent.isChart()\">\n                        <span class=\"badge bg-danger\" data-bind=\"visible: !groupInGraph()\">Will not show in <span data-bind=\"text: $parent.ReportType\"></span>Chart</span>\n                    </span>\n                    <span data-bind=\"visible: $parent.IsPivotFieldLastColumn($index(),selectedAggregate())\">\n                        <span class=\"badge bg-danger\" >Pivot field cannot be the last column.</span>\n                    </span>\n                    <span data-bind=\"visible: $parent.IsDynamicFieldFirstColumn($index())\">\n                        <span class=\"badge bg-danger\" >Dynamic cannot be first column.</span>\n                    </span>\n                </div>\n                <div class=\"col-7 d-flex flex-row-reverse\">\n                    <div style=\"margin-top: -5px;\" data-bind=\"if: $parent.AggregateReport() && !$parent.useStoredProc()\">\n                        <div class=\"d-flex align-items-center\">\n                            <select class=\"form-select form-control-sm\" data-bind=\"options: $parent.canDrilldown() && $index()>0 ? fieldAggregateWithDrilldown : fieldAggregate, value: selectedAggregate\"></select>\n                            <i class=\"fa fa-info-circle ms-1 text-muted aggregate-help-tip\" style=\"cursor:help; font-size:12px;\"\n                               data-bind=\"visible: $parent.showHints(), attr: { 'data-agg-tooltip': $parent.getAggregateTooltip($data) }\"></i>\n                        </div>\n                    </div>\n\n                    <div  style=\"padding-right: 10px;\" data-bind=\"ifnot: $parent.useStoredProc\">\n                        <span class=\"fa fa-trash\" title=\"Cannot Delete Required Filter\" data-bind=\"visible: forceFilterForTable\"></span>\n                        <span class=\"fa fa-trash\" style=\"cursor: pointer;\" aria-hidden=\"true\" title=\"Delete this Field\" data-bind=\"click: $parent.RemoveField, hidden: forceFilterForTable\"></span>\n                    </div>\n                    <!--<div  style=\"padding-right: 10px;\" data-bind=\"ifnot: $parent.useStoredProc\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: function(){ filterOnFly(!filterOnFly()); }, css: {active: filterOnFly()==true}\">\n                            <span class=\"fa fa-filter\" aria-hidden=\"true\" title=\"Filter by this field on the Report\"></span>\n                        </span>\n                    </div>-->\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.ReportType()!='Pivot'\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: toggleDisable\">\n                            <span data-bind=\"\n                                css: {\n                                    'fa': true,\n                                    'fa-close': disabled(),\n                                    'fa-check': !disabled(),\n                                    'text-danger': disabled()\n                                },\n                                attr: {\n                                    title: disabled() ? 'Excluded from the Report' : 'Included in the Report'\n                                }\n                            \" aria-hidden=\"true\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.ReportType()!='Pivot' && $parent.ReportType()!='List' && !$parent.useStoredProc()\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: function(){ hideInDetail(!hideInDetail()); }, css: {active: hideInDetail()==true}\">\n                            <span class=\"fa fa-eye-slash\" aria-hidden=\"true\" title=\"Hide in Details\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.isFieldValidForYAxis($index(), fieldType || fieldFormat(), selectedAggregate())  && $parent.isChart() && $index()>0\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: function(){ groupInGraph(!groupInGraph()); }, css: {active: groupInGraph()==false}\">\n                            <span class=\"fas fa-signal\" aria-hidden=\"true\" title=\"Include in series\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.ReportType()!='Pivot'\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: setupLinkField, css: {active: linkField()==true}\">\n                            <span class=\"fa fa-link\" aria-hidden=\"true\" title=\"Link to another Report or Url\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.ReportType()=='Combo' && $parent.isFieldValidForYAxis($index(), fieldType || fieldFormat(), selectedAggregate())  && $parent.isChart() && $index()>0\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: function(){ seriesType(seriesType() == 'line' ? 'area' : (seriesType()=='bars' ? 'line' : 'bars')); }\">\n                            <span class=\"fa\" aria-hidden=\"true\" data-bind=\"css: {'fa-line-chart': seriesType() == 'line', 'fa-bar-chart': seriesType() == 'bars', 'fa-area-chart': seriesType()=='area' }, attr: {title: seriesType}\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: setupFieldOptions\">\n                            <span class=\"fa fa-gear\" aria-hidden=\"true\" title=\"More Options\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"if: isFormulaField\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: editFormulaField\">\n                            <span class=\"fa fa-pencil\" aria-hidden=\"true\" title=\"Edit Formula Field\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"if: isFormulaField\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: duplicateFormulaField\">\n                            <span class=\"fa fa-copy\" aria-hidden=\"true\" title=\"Duplicate Formula Field\"></span>\n                        </span>\n                    </div>\n                </div>\n            </div>\n        </li>\n    </ul>\n</script>\n\n<script type=\"text/html\" id=\"designer-sub-report\">\n    <p class=\"text-muted mb-3\">\n        Linked reports are available to add as sub reports.\n        Selecting sub reports will restrict the report to <strong>one record per page</strong>.\n    </p>\n\n    <div class=\"mb-3\">\n        <select class=\"form-select\"\n                data-bind=\"options: linkedReportFields,\n                            optionsText: 'name',\n                            value: selectedSubReport,\n                            optionsCaption: 'Select a linked report...'\">\n        </select>\n    </div>\n    <ul class=\"list-group\"\n        data-bind=\"sortable: {\n                        data: subReports,\n                        options: { handle: '.sortable', cursor: 'move', placeholder: 'drop-highlight' }\n                    }\">\n        <li class=\"list-group-item\">\n            <div class=\"d-flex justify-content-between align-items-center\">\n                <span>\n                    <i class=\"fa fa-bars sortable me-2\" style=\"cursor:move;\"></i>\n                    <span data-bind=\"text: name\"></span>\n                </span>\n                <span>\n                    <button type=\"button\" class=\"btn btn-sm btn-outline-primary me-1\" title=\"Edit sub report\"\n                            data-bind=\"click: $parent.editSubReport\">\n                        <i class=\"fa fa-edit\"></i> Edit\n                    </button>\n                    <button type=\"button\" class=\"btn btn-sm btn-outline-danger\"\n                            data-bind=\"click: $parent.removeSubReport\">\n                        Delete\n                    </button>\n                </span>\n            </div>\n            <div class=\"mt-1 d-flex gap-3 align-items-center flex-wrap\">\n                <label class=\"form-check-label small\">\n                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: isSubReportOnly, click: function() { setTimeout(function() { $parent.toggleSubReportOnly($data); }, 0); return true; }\" />\n                    Sub report only\n                    <i class=\"fa fa-question-circle text-muted\" title=\"When checked, this report will be hidden from folders and search, and can only run as a child report from here\"></i>\n                </label>\n                <label class=\"form-check-label small\">\n                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: hideTitle\" />\n                    Hide title\n                </label>\n                <label class=\"form-check-label small\">\n                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: hidePager\" />\n                    Hide pager\n                </label>\n            </div>\n        </li>\n    </ul>\n</script>\n\n<script type=\"text/html\" id=\"designer-html\">\n    <div class=\"row align-items-center mb-1\">\n        <div class=\"col-md-4\">\n        <select class=\"form-select\" data-bind=\"options: SelectedFields, value: SelectFieldToInsert, optionsCaption: 'Select a field...', optionsText: 'selectedFieldName'\"></select>\n        </div>\n        <div class=\"col-auto dropdown\">\n            <button class=\"btn btn-outline-secondary btn-sm dropdown-toggle\" type=\"button\" data-bs-toggle=\"dropdown\">\n            <i class=\"fa fa-table\"></i> Insert as Table\n            </button>\n            <ul class=\"dropdown-menu\">\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertFieldTableTransposed\">Transposed</a></li>\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertFieldTableStandard\">Standard</a></li>\n                <!-- ko if: hasOuterGroupFields -->\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertGroupedTable\">Grouped</a></li>\n                <!-- /ko -->\n                <li><hr class=\"dropdown-divider\"></li>\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertHeaderBreak\">Add Header Break</a></li>\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertFooterBreak\">Add Footer Break</a></li>\n            </ul>\n        </div>\n        <!-- ko if: subReports().length > 0 -->\n        <div class=\"col-auto dropdown d-flex align-items-center gap-2\">\n            <button class=\"btn btn-outline-secondary btn-sm dropdown-toggle\" type=\"button\" data-bs-toggle=\"dropdown\" title=\"Insert a selected sub report inline at cursor position\">\n                <i class=\"fa fa-bookmark\"></i> Insert Sub Report\n            </button>\n            <i class=\"fa fa-info-circle text-muted\"\n               data-bs-toggle=\"tooltip\"\n               data-bs-placement=\"top\"\n               title=\"Note: If you insert Sub Reports in custom report, only inserted sub reports will show and other sub reports will not render\">\n            </i>\n\n            <ul class=\"dropdown-menu\" data-bind=\"foreach: subReports\">\n                <li>\n                    <a class=\"dropdown-item\" href=\"#\"\n                       data-bind=\"text: name, click: function() { $parent.insertSubReportPlaceholder($data); }\">\n                    </a>\n                </li>\n            </ul>\n        </div>\n        <!-- /ko -->\n        <div class=\"col-md-auto ms-auto\">\n        <label class=\"form-check-label\">\n            <input class=\"form-check-input me-2\" type=\"checkbox\" data-bind=\"checked: cardView\">\n            Card Layout\n        </label>\n        </div>\n    </div>\n    <div class=\"mb-3\">\n        <textarea data-bind=\"summernote: reportHtml\"></textarea>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-sort\">\n    <div data-bind=\"ifnot: useStoredProc\">\n         <div class=\"form-group row align-items-center flex-nowrap\">\n             <label class=\"col-auto control-label\">Sort By</label>\n             <div class=\"col\">\n                 <select class=\"form-select form-select-sm\"\n                     data-bind=\"options: FilteredFields, optionsText: 'selectedFieldName', optionsValue: 'fieldId', value: SortByField, optionsCaption: 'Select field to sort...', allowClear: true\">\n                 </select>\n             </div>\n             <div class=\"col-auto d-flex gap-1\">\n                 <button class=\"btn btn-sm btn-secondary\"\n                     data-bind=\"text: !SortDesc() ? '▲ Ascending' : 'Descending ▼', click: function() { SortDesc(!SortDesc()); return false; }\">\n                 </button>\n                 <button class=\"btn btn-sm btn-secondary\"\n                     data-bind=\"click: addSortField\">\n                     Add Sort\n                 </button>\n             </div>\n         </div>\n\n         <div data-bind=\"foreach: SortFields\">\n             <div class=\"form-group row align-items-center flex-nowrap\">\n                 <label class=\"col-auto control-label\">&nbsp;&nbsp;Then Sort By</label>\n                 <div class=\"col\">\n                     <select class=\"form-select form-select-sm\" required\n                         data-bind=\"options: $parent.FilteredFields, optionsText: 'selectedFieldName', optionsValue: 'fieldId', value: sortByFieldId\">\n                     </select>\n                 </div>\n                 <div class=\"col-auto d-flex gap-1\">\n                     <button class=\"btn btn-sm btn-secondary\"\n                         data-bind=\"click: remove\">\n                         Remove Sort\n                     </button>\n                     <button class=\"btn btn-sm btn-secondary\"\n                         data-bind=\"text: !sortDesc() ? '▲ Ascending' : 'Descending ▼', click: function() { sortDesc(!sortDesc()); return false; }\">\n                     </button>\n                     <button class=\"btn btn-sm btn-secondary\"\n                         data-bind=\"click: $parent.addSortField\">\n                         Add Sort\n                     </button>\n                 </div>\n             </div>\n         </div>\n     </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-header-footer\">\n    <div class=\"form-group mb-2\">\n        <label class=\"control-label small text-muted\"><i class=\"fa fa-window-maximize\"></i> Report Header</label>\n        <select class=\"form-select form-select-sm\" style=\"width: 100%;\"\n                data-bind=\"options: reportHeadersList, optionsText: 'label', optionsValue: 'id', value: ReportHeaderId\"></select>\n    </div>\n    <hr class=\"my-1\" />\n    <div class=\"form-group\">\n        <label class=\"control-label small text-muted\"><i class=\"fa fa-window-minimize\"></i> Report Footer</label>\n        <div class=\"form-check\">\n            <label class=\"form-check-label small\">\n                <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: UseReportFooterInReport\" />\n                Include the report footer in this report\n            </label>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-options\">\n    <div class=\"row\">\n        <div class=\"col-md-5\">\n            <div data-bind=\"visible: ReportType()!='Pivot' && ReportType()!='Custom'\">\n                <div class=\"checkbox\">\n                    <label>\n                        <input type=\"checkbox\" data-bind=\"checked: IncludeSubTotal\" />\n                        Include Total Row\n                    </label>\n                </div>\n                <div data-bind=\"visible: IncludeSubTotal()\" style=\"padding-left: 20px; margin-top: 4px; margin-bottom: 4px;\">\n                    <div class=\"form-check form-check-inline\">\n                        <input class=\"form-check-input\" type=\"radio\" data-bind=\"checked: totalRowFormat\" value=\"row\" />\n                        <label class=\"form-check-label\">As Total Row</label>\n                    </div>\n                    <div class=\"form-check form-check-inline\">\n                        <input class=\"form-check-input\" type=\"radio\" data-bind=\"checked: totalRowFormat\" value=\"table\" />\n                        <label class=\"form-check-label\">As Total Table</label>\n                    </div>\n                </div>\n                <div data-bind=\"visible: IncludeSubTotal() && hasOuterGroupFields()\" style=\"padding-left: 20px; margin-top: 2px; margin-bottom: 4px;\">\n                    <div class=\"checkbox\" style=\"margin-top: 0;\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: subTotalPerGroup\" />\n                            Sub Total Per Group\n                        </label>\n                    </div>\n                </div>\n                <div class=\"checkbox\" data-bind=\"visible: hasPivotColumn()\">\n                    <label>\n                        <input type=\"checkbox\" data-bind=\"checked: IncludeColumnTotal\" />\n                        Include Total Column\n                    </label>\n                </div>            \n            </div>\n            <div class=\"checkbox\" data-bind=\"hidden: AggregateReport\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowUniqueRecords\" />\n                    Show only Unique Records\n                </label>\n            </div>\n            <div class=\"checkbox\" data-bind=\"visible: ReportType()!='List'\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowExpandOption\" />\n                    Don't Show Expand Option\n                </label>\n            </div>\n                <div class=\"checkbox\" data-bind=\"visible: isChart\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowDataWithGraph\" />\n                    Show Data along with Graph\n                </label>\n            </div>\n            <!-- ko if: adminMode() -->\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: bypassEnabled\" />\n                    Bypass Data Filters\n                </label>\n            </div>\n            <!-- ko if: bypassEnabled() -->\n            <div style=\"padding-left: 20px;\">\n                <div class=\"radio\">\n                    <label>\n                        <input type=\"radio\" name=\"bypassMode\" value=\"all\" data-bind=\"checked: bypassMode\" />\n                        Bypass All Data Filters\n                    </label>\n                </div>\n                <div class=\"radio\">\n                    <label>\n                        <input type=\"radio\" name=\"bypassMode\" value=\"specific\" data-bind=\"checked: bypassMode\" />\n                        Bypass Specific Filters\n                    </label>\n                </div>\n                <!-- ko if: bypassMode() === 'specific' -->\n                <div style=\"padding-left: 20px;\">\n                    <!-- ko if: availableDataFilterIds().length > 0 -->\n                    <!-- ko foreach: availableDataFilterIds() -->\n                    <div class=\"checkbox\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: $parent.bypassSpecificIds, checkedValue: $data\" />\n                            <span data-bind=\"text: $data\"></span>\n                        </label>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <!-- ko if: availableDataFilterIds().length === 0 -->\n                    <div class=\"form-group mt-1\">\n                        <label class=\"text-muted small\">Enter filter column names (comma-separated):</label>\n                        <input type=\"text\" class=\"form-control form-control-sm\" placeholder=\"e.g. TenantId,UserId\" data-bind=\"value: bypassSpecificIdsText, valueUpdate: 'input'\" />\n                    </div>\n                    <!-- /ko -->\n                </div>\n                <!-- /ko -->\n            </div>\n            <!-- /ko -->\n            <!-- /ko -->\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: DontExecuteOnRun\" />\n                    Wait to Select Filters before Running Report\n                </label>\n            </div>\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowFilterDetails\" />\n                    Include Filter Details on Report\n                </label>\n            </div>\n            <div class=\"form-group row\">\n                <div class=\"checkbox col-md-5\">\n                    <label>\n                        <input type=\"checkbox\" data-bind=\"checked: maxRecords\" />\n                        Max Records\n                    </label>\n                </div>\n                <div class=\"col-md-5\" data-bind=\"if: maxRecords\">\n                    <input type=\"number\" style=\"width: 150px;\" class=\"form-control\" required placeholder=\"Only top n...\" data-bind=\"value: OnlyTop, visible: maxRecords\">\n                </div>\n            </div>\n            <div class=\"form-group row\">\n                <div class=\"checkbox col-md-5\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: changePageSize, disable: subReports().length > 0\" />\n                    Change Page Size\n                </label>\n                </div>\n                <div class=\"col-md-5\"\n                    data-bind=\"visible: changePageSize,\n                                css: { 'text-muted': subReports().length > 0 }\">\n                <select style=\"width: 150px;\" class=\"form-select\"\n                        data-bind=\"options: [1,10,30,50,100,150,200,500,1000],\n                                    value: DefaultPageSize,\n                                    disable: subReports().length > 0\">\n                </select>\n                </div>\n                <!-- Force default to 1 if sub reports selected -->\n                <div class=\"col-12 mt-1\" data-bind=\"visible: subReports().length > 0\">\n                    <small class=\"text-danger\">\n                        Page size is restricted to 1 when sub reports are selected.\n                    </small>\n                </div>\n            </div>\n        </div>\n        <div class=\"col-md-7\">\n            <p><span class=\"fa fa-paint-brush\"></span> Pick Report Format</p>\n            <div>\n                <!-- ko foreach: tableStyles -->\n                <div class=\"dropdown-option\" data-bind=\"title: $data.name, click: $parent.selectStyle, css: {'dropdown-option-selected': $parent.selectedStyle() == $data.colorscheme}\">\n                    <div class=\"mini-table-preview\" data-bind=\"foreach: new Array(5)\">\n                        <div class=\"mini-table-row\" data-bind=\"foreach: new Array(5)\">\n                            <div class=\"mini-table-cell\" data-bind=\"style: { backgroundColor: $parentContext.$index() === 0 ? $parents[1].headerBg : ($parentContext.$index() % 2 === 0 ? $parents[1].altRowBg : $parents[1].rowBg), color: $parents[1].textColor }\"></div>\n\n                        </div>\n                    </div>\n                </div>\n                <!-- /ko -->\n            </div>\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: noHeaderRow\" />\n                    No Header Row\n                </label>\n            </div>\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: noDashboardBorders\" />\n                    Borderless on Dashboard\n                </label>\n            </div>\n            <div class=\"checkbox\" data-bind=\"if: ReportType() == 'Single'\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: showPriorInKpi\" />\n                    Show previous comparision in KPI if applicable\n                </label>\n            </div>\n            <div data-bind=\"hidden: useStoredProc\" class=\"mt-2\">\n                <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: detectJoinsForReport\">\n                    <span class=\"fa fa-link\"></span> Configure Joins\n                </button>\n                <!-- ko if: customJoins().length > 0 -->\n                <span class=\"badge bg-success ms-1\"><span data-bind=\"text: customJoins().length\"></span> override(s)</span>\n                <button class=\"btn btn-sm btn-outline-danger ms-1\" data-bind=\"click: clearCustomJoins\" title=\"Remove all join overrides\">\n                    <span class=\"fa fa-times\"></span>\n                </button>\n                <!-- /ko -->\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"json-field-picker\">\n    <div data-bind=\"if: lastPickedField() && lastPickedField().fieldType == 'Json'\">\n        <br />\n        <div class=\"card\">\n            <div class=\"card-header\">\n                <h6>Select Data Fields from <span data-bind=\"text: lastPickedField().fieldName\"></span></h6>\n            </div>\n            <div class=\"card-body\">\n                <div class=\"row container-fluid\" data-bind=\"foreach: jsonFields\">\n                    <div class=\"col-md-3 col-sm-4 col-xs-6 list-group\">\n                        <div class=\"list-group-item\">\n                            <div class=\"checkbox\">\n                                <label>\n                                    <input type=\"checkbox\" data-bind=\"checkedInArray: {array: $parent.SelectedFields, value: $data}\">\n                                    <span data-bind=\"text: jsonColumnName\"></span>\n                                </label>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"custom-function-designer\">\n\n    <div class=\"row\">\n        <div class=\"col-md-12\" data-bind=\"visible: isFunctionField()\">\n            <div class=\"alert alert-info\">\n                You are now creating a Customized Field using Functions available.\n            </div>\n        </div>\n    </div>\n\n    <div class=\"form-group row\">\n        <label class=\"col-sm-2 control-label\">Field Label</label>\n        <div class=\"col-sm-10\">\n            <input type=\"text\" class=\"form-control form-control-sm\" data-bind=\"value: formulaFieldLabel\" required placeholder=\"Custom Field Label\" />\n        </div>\n    </div>\n    <div class=\"form-group row\">\n        <label class=\"col-sm-2 control-label\">Data Format</label>\n        <div class=\"col-sm-10\">\n            <select class=\"form-select form-control-sm\" data-bind=\"value: formulaDataFormat\" required>\n                <option>String</option>\n                <option>Integer</option>\n                <option>Decimal</option>\n                <option>Currency</option>\n                <option>Date</option>\n                <option value=\"DateTime\">Date and Time</option>\n            </select>\n        </div>\n    </div>\n    <div class=\"form-group row\" data-bind=\"visible: formulaDataFormat() == 'Decimal' || formulaDataFormat() == 'Currency'\">\n        <label class=\"col-sm-2 control-label\">Round to Decimal Places</label>\n        <div class=\"col-sm-10\">\n            <input type=\"number\" class=\"form-control\" data-bind=\"value: formulaDecimalPlaces\" placeholder=\"Choose Decimal places (leave blank to not use rounding)\" title=\"Choose Decimal places (leave blank to not use rounding)\" />\n        </div>\n    </div>\n\n    <div>\n        Define your Function:\n        <textarea id=\"function-code\"></textarea>\n    </div>\n    <div class=\"form-group row\" >\n        <div class=\"col-md-12 float-end\">\n            <hr />\n            <a href=\"#\" class=\"btn btn-primary btn-sm\" title=\"Save Custom Function Field\" data-bind=\"click: saveFunctionField, visible: isFunctionField\">Save</a>\n            <a href=\"#\" class=\"btn btn-sm\" title=\"Custom Field using Function\" data-bind=\"click: function(){isFunctionField(!isFunctionField())}, text: isFunctionField() ? 'Cancel': 'Function', css: {'btn-primary': !isFunctionField(), 'btn-danger': isFunctionField}\"></a>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"custom-field-designer\">\n    <div>\n        <div class=\"row\">\n            <div class=\"col-md-12\" data-bind=\"visible: isFormulaField()\">\n                <div class=\"alert alert-info\">\n                    You are now creating a Customized Field. Please select the fields you want to use in the calculation, then choose the operations you want to perform, and click \"Save\" to add your Custom field.\n                </div>\n            </div>\n        </div>\n        <div class=\"row\">\n            <div class=\"col-sm-6 small\">\n                Setup your Formula for calculating this Field\n            </div>\n            <div class=\"col-sm-6 right-align\" data-bind=\"visible: formulaType()=='build'\">\n                <a href=\"#\" class=\"btn btn-secondary btn-sm\" data-bind=\"click: addFormulaParentheses\">Add ( )</a>\n                <a href=\"#\" class=\"btn btn-secondary btn-sm\" title=\"Add Today\" data-bind=\"visible: formulaOnlyHasDateFields() || formulaFields().length == 0, click: addFormulaDateToday\">Add Today</a>\n                <a href=\"#\" class=\"btn btn-secondary btn-sm\" title=\"Add a Constant Value\" data-bind=\"click: addFormulaConstantValue\">Add Value</a>\n                <a href=\"#\" class=\"btn btn-secondary btn-sm\" data-bind=\"click: clearFormulaField\">Clear</a>\n            </div>\n        </div>\n        <div class=\"form-group-row\" data-bind=\"if: formulaOnlyHasDateFields\">\n            <div class=\"col-sm-12\">\n                <div class=\"alert alert-info\">\n                    For Dates Field calculation, you can only substract date fields and display the result as days, hours, minutes or seconds.\n                </div>\n            </div>\n        </div>\n        <div class=\"form-group row\">\n            <label class=\"col-sm-2 control-label\">Field Label</label>\n            <div class=\"col-sm-10\">\n                <input type=\"text\" class=\"form-control form-control-sm\" data-bind=\"value: formulaFieldLabel\" required placeholder=\"Custom Field Label\" />\n            </div>\n        </div>\n        <div class=\"form-group row\">\n            <label class=\"col-sm-2 control-label\">Data Format</label>\n            <div class=\"col-sm-10\">\n                <select class=\"form-select form-select-sm\" data-bind=\"value: formulaDataFormat\" required>\n                    <!-- ko ifnot: formulaOnlyHasDateFields -->\n                    <option>String</option>\n                    <option>Integer</option>\n                    <option>Decimal</option>\n                    <option>Currency</option>\n                    <!-- /ko -->\n                    <!-- ko if: formulaOnlyHasDateFields -->\n                    <option>Days</option>\n                    <option>Hours</option>\n                    <option>Minutes</option>\n                    <option>Seconds</option>\n                    <!-- /ko -->\n                </select>\n            </div>\n        </div>\n        <div class=\"form-group row\" data-bind=\"visible: formulaDataFormat() == 'Decimal' || formulaDataFormat() == 'Currency'\">\n            <label class=\"col-sm-2 control-label\">Round to Decimal Places</label>\n            <div class=\"col-sm-10\">\n                <input type=\"number\" class=\"form-control\" data-bind=\"value: formulaDecimalPlaces\" placeholder=\"Choose Decimal places (leave blank to not use rounding)\" title=\"Choose Decimal places (leave blank to not use rounding)\" />\n            </div>\n        </div>\n        <div class=\"form-group row\" data-bind=\"visible: appSettings.useSqlCustomField\">\n            <label class=\"col-sm-2 control-label\">Field Builder Type</label>\n            <div class=\"col-sm-10\">\n                <select class=\"form-select form-select-sm\" data-bind=\"value: formulaType\" required>\n                    <option value=\"build\">Simple Calculation</option>\n                    <option value=\"sql\">Advanced Expression</option>\n                </select>\n            </div>\n        </div>\n\n        <div class=\"form-group row\" data-bind=\"if: formulaType()=='build'\">\n            <label class=\"col-sm-2 control-label\">Field Formula</label>\n            <div class=\"col-sm-10\">\n                <div class=\"text-muted small\" data-bind=\"visible: formulaFields().length == 0\">Pick fields to build calculation</div>\n                <div class=\"d-flex align-items-center flex-wrap\" data-bind=\"foreach: formulaFields\">\n                    <h3 class=\"me-3\" data-bind=\"visible: setupFormula.isParenthesesStart\" style=\"margin-top: 0;\">(</h3>\n                    <div data-bind=\"if: !setupFormula.isParenthesesStart() && !setupFormula.isParenthesesEnd()\" class=\"list-group me-3\">\n                        <div class=\"list-group-item d-flex align-items-center formula-field-item\" style=\"margin-left: 15px; padding: 5px 15px\">\n                            <span data-bind=\"text: fieldName, visible: !setupFormula.isConstantValue()\"></span>\n                            <div data-bind=\"if: setupFormula.isConstantValue\" class=\"d-flex align-items-center\">\n                                <input data-bind=\"value: setupFormula.constantValue, visible: setupFormula.constantValue()!='|Today|'\" class=\"form-control form-control-sm me-2\" required />\n                                <span data-bind=\"visible: setupFormula.constantValue() == '|Today|'\"><b>Today</b></span>\n                            </div>\n                            <button class=\"btn btn-danger btn-sm ms-2\" data-bind=\"click: $parent.removeField\">\n                                <i class=\"fa fa-trash\"></i>\n                            </button>\n                        </div>\n                    </div>\n                    <h3 class=\"me-3\" data-bind=\"visible: setupFormula.isParenthesesEnd\" style=\"margin-top: 0;\">)</h3>\n                    <div class=\"me-3\" style=\"margin-left: 15px;\" data-bind=\"visible: $parent.showFormulaOperation($index())\">\n                        <select class=\"form-control form-control-sm\" style=\"max-width: 50px;\" data-bind=\"value: setupFormula.formulaOperation\">\n                            <!-- ko if: !$parent.formulaOnlyHasDateFields() || ($parent.formulaOnlyHasDateFields() && $parent.isConstantOperation($index())) -->\n                            <option>+</option>\n                            <!-- /ko -->\n                            <option>-</option>\n                            <!-- ko if: ['Integer','Money','Float','Double','Decimal','Currency'].indexOf($parent.formulaDataFormat()) != -1 -->\n                            <option>*</option>\n                            <option>/</option>\n                            <!-- /ko -->\n                        </select>\n                    </div>\n                </div>\n\n            </div>\n        </div>\n\n        <div data-bind=\"with: customSqlField, visible: formulaType()=='sql'\">\n            <div class=\"row\">\n                <div class=\"col-md-12\">\n\n                    <div class=\"mb-3\">\n                        <label class=\"form-label\">Select Data Operation:</label>\n                        <select class=\"form-select\" data-bind=\"select2: {\n                            dropdownParent: $root.activeDesign() ? $('#choose-data-design') : $('#choose-data-card'),\n                            placeholder: 'Select Function...',\n                            data: availableFunctionsGrouped(),\n                            templateResult: templateResult\n                        }, value: selectedSqlFunction\"></select>\n                    </div>\n\n                    <div class=\"mb-3\" data-bind=\"hidden: isConditionalFunction() || selectedSqlFunction() == 'Other'\">\n                        <label class=\"form-label\">Select the Data Field to use:</label>\n                        <select class=\"form-select\"\n                                data-bind=\"select2: {\n                                    dropdownParent: $root.activeDesign() ? $('#choose-data-design') : $('#choose-data-card'),\n                                    placeholder: 'Search Field...',\n                                    ajax: {\n                                        url: $parent.textQuery.searchFields.url,\n                                        dataType: 'json',\n                                        data: $parent.textQuery.searchFields.query,\n                                        processResults: $parent.textQuery.searchFields.processResults,\n                                        headers: $parent.textQuery.searchFields.headers\n                                    },\n                                    minimumInputLength: 2,\n                                    allowClear: true\n                                }, select2Text: selectedField,select2TableId:selectedFieldTableId\"></select>\n                        <div data-bind=\"with: selectedField\" class=\"small\">\n                                Selected: <span class=\"highlight\" data-bind=\"text: $data\"></span>\n                        </div>\n                    </div>\n\n                    <div class=\"mb-3\" data-bind=\"if: requiresValue\">\n                        <label for=\"inputValue\" class=\"form-label\">Provide the relevant value to use:</label>\n                        <input type=\"text\" id=\"inputValue\" class=\"form-control\" data-bind=\"value: inputValue\" required />\n                    </div>\n\n                    <div class=\"mb-3\" data-bind=\"visible: selectedSqlFunction() == 'Other'\">\n                        <label for=\"custom-sql\" class=\"form-label\">Custom SQL Expression:</label>\n                        <p class=\"text-muted\">\n                            Build your custom SQL Expression below by selecting data fields, adding calculations or using SQL keywords as needed. For string values, remember to enclose them in single quotes ('')\n                        </p>\n                        <p id=\"custom-sql\" class=\"hint-input\" contenteditable=\"true\" placeholder=\"Write your custom SQL\"></p>\n                    </div>\n                    <div data-bind=\"visible: isConditionalFunction\">\n                        <p class=\"text-muted\">\n                            Build your conditional logic below by selecting data fields, adding calculations and defining conditions as needed, and provide corresponding results. For string values, remember to enclose them in single quotes ('')\n                        </p>\n                        <div class=\"input-group mb-3\">\n                            <div class=\"flex-grow-1\">\n                                <p class=\"hint-input\" id=\"condition-field\" contenteditable=\"true\" placeholder=\"Field to compare\" title=\"Field to compare\"></p>\n                            </div>\n\n                            <div class=\"mx-2\" style=\"width: 120px;\">\n                                <select class=\"form-select form-select-sm\" data-bind=\"options: availableOperators, value: selectedOperator\"></select>\n                            </div>\n\n                            <div class=\"flex-grow-1\">\n                                <p class=\"hint-input\" id=\"condition-value\" contenteditable=\"true\" placeholder=\"Value to compare\" title=\"Value to compare\"></p>\n                            </div>\n\n                            <span class=\"input-group-text\" style=\"max-height: 32px;\">THEN</span>\n\n                            <div class=\"flex-grow-1\">\n                                <p class=\"hint-input\" id=\"condition-result\" contenteditable=\"true\" placeholder=\"Condition Result\" title=\"Condition Result\"></p>\n                            </div>\n                        </div>\n                        <button class=\"btn btn-outline-primary\" data-bind=\"click: addOrUpdateCondition,text: editingCondition() ? 'Update Condition' : 'Add Condition'\"></button>\n                        <ul class=\"list-group mt-3\" data-bind=\"foreach: conditions\">\n                            <li class=\"list-group-item d-flex justify-content-between align-items-center\">\n                                <span data-bind=\"text: conditionDisplay\"></span>\n                                <button class=\"btn btn-sm btn-secondary me-1\" data-bind=\"click: $parent.editCondition\">Edit</button>\n                                <button class=\"btn btn-sm btn-danger\" data-bind=\"click: $parent.removeCondition\">Remove</button>\n                            </li>\n                        </ul>\n\n                        <div class=\"input-group mb-3\" style=\"padding-top: 5px;\">\n                            <span class=\"input-group-text\" style=\"max-height: 32px;\">ELSE</span>\n                            <div class=\"flex-grow-1\">\n                                <p class=\"hint-input\" id=\"condition-else\" contenteditable=\"true\" placeholder=\"Default Result\" title=\"Default Result\"></p>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n        </div>\n\n        <div class=\"col-md-12\">\n            <hr />\n            <a href=\"#\" class=\"btn btn-primary btn-sm\" title=\"Save Custom Formula Field\" data-bind=\"click: saveFormulaField, visible: isFormulaField\">Save</a>\n            <a href=\"#\" class=\"btn btn-sm\" title=\"Custom Field using Formula\" data-bind=\"click: cancelFormulaField, text: isFormulaField()? 'Cancel': 'Customize', css: {'btn-primary': !isFormulaField(), 'btn-danger': isFormulaField}\"></a>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"report-designer-compact\">\n    <div class=\"designer-container compact-designer\" id=\"choose-data-design\" style=\"font-size:12px;\">\n\n      <div class=\"alert alert-info mb-2 py-2 px-3\" style=\"border-left: 4px solid #0d6efd; font-size: 13px;\" data-bind=\"visible: editingSubReportParentId()\">\n          <!-- ko if: _editingSubReportLoading() -->\n          <div class=\"d-flex align-items-center\">\n              <span class=\"fa fa-spinner fa-spin me-2\"></span>\n              <span>Loading sub report...</span>\n          </div>\n          <!-- /ko -->\n          <!-- ko ifnot: _editingSubReportLoading() -->\n          <div class=\"d-flex align-items-center justify-content-between\">\n              <span>\n                  <i class=\"fa fa-info-circle me-1\"></i>\n                  Editing sub report from <strong data-bind=\"text: editingSubReportParentName\"></strong>.\n              </span>\n              <button type=\"button\" class=\"btn btn-sm btn-outline-primary ms-2\" data-bind=\"click: returnToParentReport\">\n                  <i class=\"fa fa-arrow-left me-1\"></i> Back to parent\n              </button>\n          </div>\n          <!-- /ko -->\n      </div>\n\n      <!-- Visualization Toolbar -->\n      <div class=\"card p-1 mb-2\">\n         <div class=\"card-header p-1 d-flex justify-content-between align-items-center\">\n          <span><i class=\"fa fa-file\"></i> Visualization</span>\n          <button id=\"aiToggleBtn\"\n                class=\"btn btn-primary position-fixed bottom-0 end-0 m-3 rounded-circle shadow\"\n                style=\"width: 50px; height: 50px; z-index: 1050;\"\n                title=\"Chat with AI Assistant\"\n                data-bind=\"click: toggleAiChat, visible: appSettings.usePromptBuilder\">\n            <i class=\"fa fa-comment fa-lg\"></i>\n          </button>\n          <div>\n              <button type=\"button\" class=\"btn btn-sm btn-outline-secondary me-1\" data-bind=\"click: function() { RunReport(false, true, ReportMode()=='dashboard'); }\" title=\"Re-run Report\">\n                  <i class=\"fa fa-play\"></i>\n              </button>\n              <!-- Close for existing reports -->\n              <button type=\"button\" class=\"btn btn-sm btn-outline-secondary\" data-bind=\"visible: ReportID(), click: function() {activeDesign(false); if (isExpanded) isExpanded(false);}\" title=\"Close Designer\">\n                  <i class=\"fa fa-times\"></i>\n              </button>\n              <!-- Cancel for new reports -->\n              <button type=\"button\" class=\"btn btn-sm btn-danger\" data-bind=\"visible: !ReportID(), click: function() { if (ReportMode()=='dashboard') $parent.removeNewReport(); else cancelCreateReport(); }\" title=\"Cancel new report\">\n                  <i class=\"fa fa-times\"></i>\n              </button>\n          </div>\n        </div>\n        <div class=\"card-body p-1\" style=\"overflow-x: auto;\">\n          <div data-bind=\"template: 'designer-choose-visual'\"></div>\n        </div>\n      </div>\n\n      <!-- Main Grid -->\n      <div class=\"d-flex flex-row flex-wrap gap-2 compact-filters needs-validation\">\n\n        <!-- Data -->\n        <div class=\"card flex-fill expandable-panel\" id=\"dataPanel\" style=\"max-width: 300px\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('dataPanel')}\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('dataPanel')}\">\n            <i class=\"fa fa-database\"></i> Available Data\n          </div>\n\n          <div class=\"card-body p-1\">\n              <div data-bind=\"template: 'designer-choose-data'\"></div>\n          </div>\n        </div>\n\n        <!-- Selected -->\n        <div class=\"card flex-fill expandable-panel\" id=\"selectedPanel\" style=\"max-width: 400px\"\n         data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('selectedPanel')}\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('selectedPanel')}\">\n            <i class=\"fa fa-table\"></i> Selected data for the Report\n            <a href=\"#\" class=\"small text-muted float-end\"\n               data-bind=\"visible: SelectedFields().length, click:function(){SelectedFields([]);}\">Clear all</a>\n          </div>\n\n          <div class=\"card-body designer-auto-update p-1\">\n                <div style=\"max-height: 300px; overflow-y: auto;\">\n                    <div data-bind=\"template: 'designer-selected-data'\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"card flex-fill expandable-panel\" id=\"subReportsPanel\"\n                data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('subReportsPanel')}, visible: linkedReportFields().length > 0\">\n            <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('subReportsPanel')}\">\n            <i class=\"fa fa-bookmark\"></i> Sub Reports\n            </div>\n            <div class=\"card-body p-1\">\n            <div data-bind=\"template: 'designer-sub-report', data: $data\"></div>\n            </div>\n        </div>\n\n        <div class=\"card flex-fill expandable-panel\" id=\"htmlReportPanel\"\n                data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('htmlReportPanel')}, visible: ReportType()=='Html'\">\n            <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('htmlReportPanel')}\">\n            <i class=\"fa fa-pencil\"></i> Custom Design\n            </div>\n            <div class=\"card-body p-1\">\n            <div data-bind=\"template: 'designer-html', data: $data\"></div>\n            </div>\n        </div>\n\n        <div class=\"card flex-fill expandable-panel\" id=\"jsonFieldsPanel\" data-bind=\"visible: lastPickedField() && lastPickedField().fieldType == 'Json'\">\n            <div class=\"card-body\" data-bind=\"template: 'json-field-picker'\"></div>\n        </div>\n\n        <!-- Field Options Panel -->\n        <div id=\"fieldOptionsPanel\" class=\"card p-2 mt-2 collapse\">\n        <!-- dynamic field settings load here -->\n        </div>\n\n        <!-- Filters -->\n        <div class=\"card flex-fill expandable-panel\" id=\"filtersPanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('filtersPanel')}\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('filtersPanel')}\">\n            <i class=\"fa fa-filter\"></i> Filters\n          </div>\n          <div class=\"card-body p-1 designer-auto-update\" style=\"max-height:300px; overflow-y:auto;\">\n            <div data-bind=\"if:useStoredProc\"><div data-bind=\"template:{name:'filter-parameters'}\"></div></div>\n            <div data-bind=\"ifnot:useStoredProc\"><div data-bind=\"template:{name:'filter-group'}\"></div></div>\n          </div>\n        </div>\n\n        <!-- Sort -->\n        <div class=\"card flex-fill expandable-panel\" id=\"sortPanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('sortPanel')}, hidden: useStoredProc()\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('sortPanel')}\">\n            <i class=\"fa fa-sort\"></i> Sort\n          </div>\n          <div class=\"card-body p-1 designer-auto-update row\">\n            <div data-bind=\"template: 'designer-sort'\"></div>\n          </div>\n        </div>\n\n        <!-- Settings -->\n        <div class=\"card flex-fill expandable-panel\" id=\"settingsPanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('settingsPanel')}\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('settingsPanel')}\">\n            <i class=\"fa fa-gear\"></i>Options\n          </div>\n          <div class=\"card-body\">\n            <div class=\"form-group row\">\n                <label class=\"col-form-label h6\">\n                    <i class=\"fa fa-file\"></i> Report Name\n                </label>\n                <div>\n                    <input type=\"text\" class=\"form-control\" required placeholder=\"Report Name\" data-bind=\"value: ReportName\">\n                </div>\n            </div>\n            <div class=\"form-group row\">\n                <label class=\"control-label h6\">\n                    <i class=\"fa fa-info-circle\"></i> Report Description\n                </label>\n                <div>\n                    <textarea class=\"form-control\" style=\"width: 100%;\" rows=\"3\" placeholder=\"Additional details (optional)\" data-bind=\"value: ReportDescription\"></textarea>\n                </div>\n            </div>\n            <div class=\"checkbox\" data-bind=\"visible: canSaveCurrentReport()\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: SaveReport\">\n                    Save Report\n                </label>\n            </div>\n            <div class=\"checkbox\" data-bind=\"visible: adminMode() && ReportID()\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: isSubReportOnly, click: function() { setTimeout(function() { toggleIsSubReportOnly(); }, 0); return true; }\">\n                    Only use as sub report\n                </label>\n            </div>\n            <div class=\"checkbox\" data-bind=\"visible: adminMode()\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowAdminOnly\">\n                    Hide from reports unless Admin Mode is enabled\n                </label>\n            </div>\n            <div class=\"form-group row\" data-bind=\"visible: SaveReport\">\n                <label class=\"control-label h6\">\n                    <i class=\"fa fa-folder-open\"></i> Choose Folder\n                </label>\n                <div>\n                    <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: Folders, optionsText: function(f) { return f.FolderPath || f.FolderName; }, optionsValue: 'Id', value: FolderID, valueAllowUnset: true\"></select>\n                </div>\n            </div>\n            <hr />\n            <div data-bind=\"template: 'designer-options'\"></div>\n          </div>\n        </div>\n\n        <!-- Schedule -->\n        <div class=\"card flex-fill expandable-panel\" id=\"schedulePanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('schedulePanel')}, visible: SaveReport() && !ko.unwrap(appSettings.showScheduling) && !isSubReportOnly()\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('schedulePanel')}\">\n            <i class=\"fa fa-hourglass\"></i> Schedule\n          </div>\n          <div class=\"card-body p-1 designer-auto-update row\">\n            <div data-bind=\"template: {name: 'report-schedule'}\"></div>\n          </div>\n        </div>\n\n        <!-- Access -->\n        <div class=\"card flex-fill expandable-panel\" id=\"accessPanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('accessPanel')}, visible: adminMode() && !isFormulaField()\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('accessPanel')}\">\n            <i class=\"fa fa-key\"></i>Security\n          </div>\n\n          <div data-bind=\"\" class=\"card card-body\">\n            <div data-bind=\"template: {name: 'manage-access-template', data: manageAccess}\"></div>\n        </div>\n        </div>\n\n      </div>\n\n    </div>\n    <hr />\n    <!-- AI Assistant Popup -->\n    <div id=\"aiPopup\"\n         class=\"position-fixed bottom-0 end-0 m-3 shadow-lg bg-white border rounded-3 d-none d-flex flex-column\"\n         style=\"width: 340px; height: 460px; z-index: 1060; overflow: hidden;\">\n\n        <div class=\"d-flex justify-content-between align-items-center border-bottom bg-light p-2 px-3 flex-shrink-0\">\n            <h6 class=\"mb-0\">\n                <i class=\"fa fa-comments me-1\"></i> AI Report Assistant\n                <span class=\"alert alert-info\" title=\"This feature is still in intial release and might not alwways be accurate. You can turn it off from settings\" style=\"font-size: 10pt; padding: 5px; max-width: 350px; white-space: normal; margin-bottom: 0;\">\n                    <i class=\"fa fa-info-circle\"></i>\n                </span>\n            </h6>\n            <div>\n                <button class=\"btn btn-sm btn-outline-secondary me-2\" data-bind=\"click: clearAiChat\" title=\"Clear Chat\">\n                    <i class=\"fa fa-trash\"></i>\n                </button>\n                <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: toggleAiChat\" title=\"Close\">\n                    <i class=\"fa fa-times\"></i>\n                </button>\n            </div>\n        </div>\n\n        <div id=\"aiChatBody\"\n             class=\"flex-grow-1 overflow-auto p-3\"\n             style=\"background: #f8f9fa;\">\n            <div data-bind=\"foreach: aiMessages\">\n            <div class=\"mb-2\" data-bind=\"css: { 'text-end': role === 'user', 'text-start': role === 'assistant' }\">\n                <div data-bind=\"text: content, css: role === 'user' ? 'bg-primary text-white' : 'bg-light border'\"\n                     class=\"p-2 rounded-3 d-inline-block\"\n                     style=\"max-width: 85%; white-space: pre-wrap;\"></div>\n            </div>\n            </div>\n        </div>\n\n        <div class=\"border-top bg-white p-2 flex-shrink-0\">\n            <div class=\"w-100 mb-1 small text-muted\">\n                💡 Ask things like “Add a column for total orders” or “Show top salesperson this year”\n            </div>\n            <div class=\"form-check mb-2\">\n                <input type=\"checkbox\" class=\"form-check-input\"\n                       data-bind=\"checked: aiAutocompleteDisabled\">\n                <label class=\"form-check-label small text-muted\">\n                    Disable column autocomplete hints\n                    <span title=\"If you disable this, plesae select some data fields in the report designer, choosing data fields to use helps improve results\" style=\"font-size: 10pt; padding: 5px; max-width: 350px; white-space: normal; margin-bottom: 0;\">\n                        <i class=\"fa fa-info-circle\"></i>\n                    </span>\n                </label>\n            </div>\n\n            <div class=\"d-flex align-items-center w-100\">\n                <p id=\"query-input\"\n                   class=\"query-input flex-grow-1 mb-0 p-2 border rounded\"\n                   contenteditable=\"true\"\n                   style=\"min-height: 38px; overflow-y: auto;\"></p>\n                <button class=\"btn btn-primary ms-2\"\n                        data-bind=\"click: sendAiMessage\">\n                    <i class=\"fa fa-paper-plane\"></i>\n                </button>\n            </div>\n        </div>\n    </div>\n\n</script>\n\n<script type=\"text/html\" id=\"report-designer\">\n    <div class=\"modal-dialog modal-dialog-scrollable\" style=\"height: 100vh;\" id=\"report-designer-modal\">\n        <div class=\"modal-content\" style=\"display: flex; flex-direction: column; height: 100%;\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"myModalLabel\">\n                    <a title=\"Need help setting up a report?\" target=\"_blank\" href=\"https://dotnetreport.com/blogs/docs/designing-reports\"><span class=\"fa fa-question-circle\"></span></a>\n                    <!-- ko if: editingSubReportParentId() -->\n                    <i class=\"fa fa-link\"></i> Editing Sub Report\n                    <!-- /ko -->\n                    <!-- ko ifnot: editingSubReportParentId() -->\n                    Design your Report\n                    <!-- /ko -->\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" data-bind=\"click: onModalCloseClicked\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"alert alert-info mb-0 rounded-0 py-2 px-3\" style=\"border-left: 4px solid #0d6efd;\" data-bind=\"visible: editingSubReportParentId()\">\n                <!-- ko if: _editingSubReportLoading() -->\n                <div class=\"d-flex align-items-center py-1\">\n                    <span class=\"fa fa-spinner fa-spin me-2\"></span>\n                    <span>Loading sub report...</span>\n                </div>\n                <!-- /ko -->\n                <!-- ko ifnot: _editingSubReportLoading() -->\n                <div class=\"d-flex align-items-center justify-content-between\">\n                    <span>\n                        <i class=\"fa fa-info-circle me-1\"></i>\n                        You are editing a sub report linked from <strong data-bind=\"text: editingSubReportParentName\"></strong>.\n                    </span>\n                    <button type=\"button\" class=\"btn btn-sm btn-outline-primary ms-2\" data-bind=\"click: returnToParentReport\">\n                        <i class=\"fa fa-arrow-left me-1\"></i> Back to parent report\n                    </button>\n                </div>\n                <small class=\"text-muted\">When you save, you'll be returned to the parent report. You can also click \"Back to parent report\" to return without saving.</small>\n                <!-- /ko -->\n            </div>\n            <div class=\"modal-body needs-validation\" style=\"overflow-y: hidden; flex-grow: 1; display: flex; flex-direction: column;\">\n               <div class=\"row flex-grow-1\" style=\"min-height: 0;\">\n                    <!-- LEFT PANEL -->\n                    <div class=\"col-md-4 h-100\" style=\"overflow-y: auto;\">\n\n                        <!-- Designer Toolbar Toggles -->\n                        <div class=\"d-flex align-items-center flex-wrap gap-2 mb-2\">\n                            <div class=\"form-check form-switch mb-0\">\n                                <input class=\"form-check-input\" type=\"checkbox\" role=\"switch\" id=\"livePreviewSwitch\" data-bind=\"checked: activeDesign\">\n                                <label class=\"form-check-label fw-semibold\" for=\"livePreviewSwitch\">\n                                    <i class=\"fa fa-bolt text-warning\"></i> Live Preview\n                                </label>\n                            </div>\n                            <div class=\"form-check form-switch mb-0\" data-bind=\"visible: hasAiConfigured()\">\n                                <input class=\"form-check-input\" type=\"checkbox\" role=\"switch\" id=\"aiAssistSwitch\" data-bind=\"checked: aiAssistantEnabled\">\n                                <label class=\"form-check-label small\" for=\"aiAssistSwitch\">\n                                    <i class=\"fa fa-magic text-primary\"></i> AI Assist <span style=\"vertical-align: middle;\" title=\"This feature is still in intial release and might not alwways be accurate. You can turn it off from settings\" ><i class=\"fa fa-info-circle\"></i></span>\n                                </label>\n                            </div>                            \n                            <div class=\"form-check form-switch mb-0\" data-bind=\"visible: ko.unwrap(appSettings.showDesignerHints)\">\n                                <input class=\"form-check-input\" type=\"checkbox\" role=\"switch\" id=\"hintsSwitch\" data-bind=\"checked: showHints\">\n                                <label class=\"form-check-label small\" for=\"hintsSwitch\">\n                                    <i class=\"fa fa-question-circle text-info\"></i> Tips\n                                </label>\n                            </div>\n                            <button class=\"btn btn-sm btn-outline-primary ms-auto\" data-bind=\"visible: activeDesign(), click: function() { RunReport(false, true); }\" title=\"Re-run Report\">\n                                <i class=\"fa fa-play\"></i> Run\n                            </button>\n                        </div>\n\n                        <!-- AI Assistant Panel (visible in both modes) -->\n                        <div class=\"card mb-2 designer-panel ai-assistant-panel\" data-bind=\"visible: aiAssistantEnabled()\" style=\"display:none; font-size: 12px;\">\n                            <div class=\"card-header p-2 d-flex align-items-center bg-primary text-white\" style=\"cursor:pointer;\">\n                                <i class=\"fa fa-magic me-1\"></i> AI Report Builder\n                                <span class=\"badge bg-light text-primary ms-1\" data-bind=\"visible: aiReportApplied()\" style=\"font-size:9px;\">Modified</span>\n                                <button class=\"btn btn-sm btn-link text-white ms-auto p-0\" data-bind=\"click: clearAiAssistant\" title=\"Clear conversation\"><i class=\"fa fa-trash\"></i></button>\n                            </div>\n                            <div class=\"card-body p-0\">\n                                <!-- Messages -->\n                                <div class=\"ai-assist-messages\" data-bind=\"foreach: aiAssistantMessages\" style=\"max-height: 350px; overflow-y: auto; padding: 8px;\">\n                                    <div class=\"mb-2\" data-bind=\"css: { 'text-end': role === 'user', 'text-start': role !== 'user' }\">\n                                        <div class=\"ai-msg-bubble d-inline-block p-2 rounded-3\" style=\"max-width: 90%; white-space: pre-wrap; font-size: 12px;\"\n                                             data-bind=\"text: content, css: role === 'user' ? 'bg-primary text-white' : 'bg-light border'\"></div>\n                                    </div>\n                                </div>\n                                <!-- Loading -->\n                                <div class=\"text-center p-2\" data-bind=\"visible: aiAssistantLoading()\">\n                                    <div class=\"d-flex align-items-center justify-content-center gap-2\">\n                                        <i class=\"fa fa-spinner fa-spin text-primary\"></i>\n                                        <span class=\"small text-muted\">Building your report...</span>\n                                    </div>\n                                </div>\n                                <!-- Quick Actions (shown when no messages) -->\n                                <div class=\"p-2\" data-bind=\"visible: aiAssistantMessages().length === 0 && !aiAssistantLoading()\">\n                                    <div class=\"small text-muted mb-1\" style=\"font-style: italic;\">\n                                        Ask me anything about your report design, or click a quick action below.\n                                    </div>\n                                    <div class=\"small text-muted mb-2\">\n                                        <i class=\"fa fa-magic text-primary\"></i> Tell me what report to build, or try:\n                                    </div>\n                                    <div class=\"small text-muted mb-2\" style=\"background: #f0f7ff; padding: 6px 8px; border-radius: 4px; border-left: 3px solid #0d6efd;\">\n                                        <i class=\"fas fa-lightbulb text-warning\"></i> <strong>Tip:</strong> For best results, mention the data table name (e.g., \"build a report using the Orders table\")\n                                    </div>\n                                    <div class=\"d-flex flex-wrap gap-1\">\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function(){ aiAssistantInput('Build a sales summary report with a bar chart'); sendAiAssistantMessage(); }\">\n                                            <i class=\"fa fa-bar-chart\"></i> Sales summary\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function(){ aiAssistantInput('Create an invoice report using HTML template'); sendAiAssistantMessage(); }\">\n                                            <i class=\"fa fa-file-text-o\"></i> Invoice report\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function(){ aiAssistantInput('Show me a trend line chart of data over time'); sendAiAssistantMessage(); }\">\n                                            <i class=\"fa fa-line-chart\"></i> Trend analysis\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function(){ aiAssistantInput('Create a KPI dashboard widget showing a key metric'); sendAiAssistantMessage(); }\">\n                                            <i class=\"fa fa-tachometer\"></i> KPI widget\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: getAiRecommendation, visible: SelectedFields().length > 0\">\n                                            <i class=\"fas fa-lightbulb\"></i> Recommend chart\n                                        </button>\n                                    </div>\n                                </div>\n                                <!-- Chat Input -->\n                                <div class=\"d-flex align-items-center p-2 border-top\">\n                                    <input type=\"text\" class=\"form-control form-control-sm me-1\"\n                                           placeholder=\"Describe the report you want to build...\"\n                                           data-bind=\"value: aiAssistantInput, valueUpdate: 'afterkeydown',\n                                                      event: { keypress: function(d,e){ if(e.keyCode===13){ sendAiAssistantMessage(); return false; } return true; } },\n                                                      attr: { disabled: aiAssistantLoading() }\">\n                                    <button class=\"btn btn-sm btn-primary\" data-bind=\"click: sendAiAssistantMessage, enable: aiAssistantInput() && !aiAssistantLoading()\">\n                                        <i class=\"fa fa-paper-plane\"></i>\n                                    </button>\n                                </div>\n                                <!-- Follow-up suggestions (shown after AI applies a report) -->\n                                <div class=\"p-2 border-top\" data-bind=\"visible: aiReportApplied() && !aiAssistantLoading() && aiAssistantMessages().length > 0\" style=\"display:none;\">\n                                    <div class=\"small text-muted mb-1\"><i class=\"fa fa-comments\"></i> Follow-up:</div>\n                                    <div class=\"d-flex flex-wrap gap-1\">\n                                        <button class=\"btn btn-sm btn-outline-primary\" data-bind=\"click: function(){ aiAssistantInput('Add a filter for this year'); sendAiAssistantMessage(); }\">\n                                            + Filter this year\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-primary\" data-bind=\"click: function(){ aiAssistantInput('Change to a bar chart'); sendAiAssistantMessage(); }\">\n                                            Change chart type\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-primary\" data-bind=\"click: function(){ aiAssistantInput('Break it down by month'); sendAiAssistantMessage(); }\">\n                                            By month\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-primary\" data-bind=\"click: function(){ aiAssistantInput('Add a top 10 limit'); sendAiAssistantMessage(); }\">\n                                            Top 10\n                                        </button>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- ==================== STANDARD MODE (activeDesign OFF) ==================== -->\n                        <div data-bind=\"visible: !activeDesign()\">\n                            <div class=\"card card-body\" id=\"choose-data-card\" style=\"min-height: calc(100vh - 200px);\">\n                                <div class=\"form-group row align-items-center\">\n                                    <label class=\"col-sm-4 col-form-label h6\">\n                                        <i class=\"fa fa-file\"></i> Report Name\n                                    </label>\n                                    <div class=\"col-sm-8\">\n                                        <input type=\"text\" class=\"form-control\" required placeholder=\"Report Name\" data-bind=\"value: ReportName\">\n                                    </div>\n                                </div>\n                                <hr />\n                                <h5><span class=\"fa fa-database\"></span>&nbsp;Choose Data for Report</h5>\n                                <div data-bind=\"template: 'designer-choose-data'\"></div>\n                            </div>\n                            <br />\n                            <div class=\"card card-body\">\n                                <div class=\"form-group row\">\n                                    <label class=\"control-label h6\">\n                                        <i class=\"fa fa-info-circle\"></i> Report Description\n                                    </label>\n                                    <div>\n                                        <textarea class=\"form-control\" style=\"width: 100%;\" rows=\"3\" placeholder=\"Additional details (optional)\" data-bind=\"value: ReportDescription\"></textarea>\n                                    </div>\n                                </div>\n                                <div class=\"checkbox\" data-bind=\"visible: canSaveCurrentReport()\">\n                                    <label>\n                                        <input type=\"checkbox\" data-bind=\"checked: SaveReport\">\n                                        Save Report\n                                    </label>\n                                </div>\n                                <div class=\"checkbox\" data-bind=\"visible: adminMode() && ReportID()\">\n                                    <label>\n                                        <input type=\"checkbox\" data-bind=\"checked: isSubReportOnly, click: function() { setTimeout(function() { toggleIsSubReportOnly(); }, 0); return true; }\">\n                                        Only use as sub report\n                                    </label>\n                                </div>\n                                <div class=\"checkbox\" data-bind=\"visible: adminMode()\">\n                                    <label>\n                                        <input type=\"checkbox\" data-bind=\"checked: ShowAdminOnly\">\n                                        Hide from reports unless Admin Mode is enabled\n                                    </label>\n                                </div>\n                                <div class=\"form-group row\" data-bind=\"visible: SaveReport\">\n                                    <label class=\"control-label h6\">\n                                        <i class=\"fa fa-folder-open\"></i> Choose Folder\n                                    </label>\n                                    <div>\n                                        <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: Folders, optionsText: function(f) { return f.FolderPath || f.FolderName; }, optionsValue: 'Id', value: FolderID, valueAllowUnset: true\"></select>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- ==================== LIVE PREVIEW MODE (activeDesign ON) ==================== -->\n                        <div data-bind=\"visible: activeDesign()\" class=\"live-preview-designer\" style=\"font-size: 12px; display: none;\">\n\n                            <!-- Report Name (always visible at top in live preview) -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-body p-2\">\n                                    <div class=\"form-group row align-items-center mb-0\">\n                                        <label class=\"col-sm-4 col-form-label\"><i class=\"fa fa-file\"></i> Report Name</label>\n                                        <div class=\"col-sm-8\">\n                                            <input type=\"text\" class=\"form-control form-control-sm\" required placeholder=\"Report Name\" data-bind=\"value: ReportName\">\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <!-- Data -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-dataPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-database\"></i> Available Data\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>1. Pick a Table</b> from the dropdown &mdash; this is your data source.<br><b>2. Check fields</b> to add them to your report.<br><b>3. Join Tables:</b> If you need data from multiple tables, select additional tables and they&rsquo;ll be auto-joined if relationships exist.<br><b>Dynamic vs Stored Proc:</b> Dynamic builds SQL from your selections; Stored Proc calls a predefined database procedure.\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-dataPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-dataPanel')\">\n                                    <div data-bind=\"template: 'designer-choose-data'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Visualization -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-vizPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-bar-chart\"></i> Visualization\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>List:</b> Raw data rows &mdash; detail reports, exports.<br><b>Summary:</b> Grouped with totals (needs aggregate functions like Sum/Count).<br><b>Bar:</b> Compare categories side by side. Use <i>Stacked</i> or <i>Horizontal</i> in chart options.<br><b>Pie:</b> Proportions of a whole (best with &lt;8 slices). Enable <i>Donut</i> in options.<br><b>Line:</b> Trends over time. Great with date fields on x-axis.<br><b>KPI:</b> Single big number metric (needs one numeric field with aggregate).<br><b>More...</b> opens Scatter, Gauge, Funnel, Radar, and more.\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-vizPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-vizPanel')\" style=\"overflow-x: auto;\">\n                                    <div data-bind=\"template: 'designer-choose-visual'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Selected Data -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-selectedPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-table\"></i> Selected Data\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>Aggregate Functions</b> (for Summary/Charts):<br>&bull; <b>Group:</b> Group rows by this field (e.g., by Month, by Category)<br>&bull; <b>Sum:</b> Add up all values<br>&bull; <b>Count:</b> Count number of rows<br>&bull; <b>Avg:</b> Calculate average<br>&bull; <b>Min/Max:</b> Find smallest/largest value<br><br><b>Group in Graph:</b> Creates separate series/colors in charts (e.g., one line per product).<br><b>Field Settings</b> (click column &crarr; icon): Format as Currency/Percentage, set alignment, decimal places, conditional formatting, custom labels, and more.\"></i>\n                                    <a href=\"#\" class=\"small text-muted float-end me-3\" data-bind=\"visible: SelectedFields().length, click: function(){SelectedFields([]);}\">Clear all</a>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-selectedPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-auto-update\" data-bind=\"visible: !panels.isCollapsed('lp-selectedPanel')\" style=\"max-height: 300px; overflow-y: auto;\">\n                                    <div data-bind=\"template: 'designer-selected-data'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- JSON Field Picker -->\n                            <div data-bind=\"template: 'json-field-picker'\"></div>\n\n                            <!-- Sub Reports -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: linkedReportFields().length > 0\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-subReportsPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-bookmark\"></i> Sub Reports\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-subReportsPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-subReportsPanel')\">\n                                    <div data-bind=\"template: 'designer-sub-report'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- HTML Design -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: ReportType()=='Html'\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-htmlPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-pencil\"></i> Custom Design\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-htmlPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-htmlPanel')\">\n                                    <div data-bind=\"template: 'designer-html'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Filters -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-filtersPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-filter\"></i> Filters\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>Filter Operators:</b><br>&bull; <b>=, &gt;, &lt;, &ge;, &le;:</b> Standard comparisons<br>&bull; <b>Between:</b> Range (e.g., dates from/to)<br>&bull; <b>Like:</b> Pattern match (use % as wildcard)<br>&bull; <b>In / Not In:</b> Match a list of values<br>&bull; <b>Is Blank / Is Not Blank:</b> Null checks<br><br><b>Date Shortcuts:</b> Today, This Week, This Month, This Year, Last 30 Days, Last Year<br><br><b>AND/OR Logic:</b> Combine multiple filters. Add filter groups for complex logic like (A AND B) OR (C AND D).<br><br><b>Allow Filters on Report:</b> Check this to let viewers add their own filters when viewing.\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-filtersPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-auto-update\" data-bind=\"visible: !panels.isCollapsed('lp-filtersPanel')\" style=\"max-height: 300px; overflow-y: auto;\">\n                                    <div data-bind=\"visible: useStoredProc\"><div data-bind=\"template: {name: 'filter-parameters'}\"></div></div>\n                                    <div data-bind=\"visible: !useStoredProc()\"><div data-bind=\"template: {name: 'filter-group'}\"></div></div>\n                                    <div class=\"checkbox\">\n                                        <label>\n                                            <input type=\"checkbox\" data-bind=\"checked: EditFiltersOnReport\" />\n                                            Allow setting up and saving filters on Report\n                                        </label>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <!-- Sort -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: !useStoredProc()\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-sortPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-sort\"></i> Sort\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>Sort Order:</b> Drag fields to set priority. First sort is primary, second is tie-breaker, etc.<br><b>Ascending:</b> A&rarr;Z, 1&rarr;9, oldest&rarr;newest<br><b>Descending:</b> Z&rarr;A, 9&rarr;1, newest&rarr;oldest<br><br><b>For Charts:</b> Sort controls x-axis order (e.g., sort by date for chronological, by value for ranked bars).<br><b>Top N:</b> Combine sort descending + page size to show &ldquo;Top 10&rdquo; results.\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-sortPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-auto-update\" data-bind=\"visible: !panels.isCollapsed('lp-sortPanel')\">\n                                    <div data-bind=\"template: 'designer-sort'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Settings & Options -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-settingsPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-gear\"></i> Options\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>Options Available:</b><br>&bull; <b>Show Total Row:</b> Adds a totals row at the bottom (Sum/Count of numeric columns)<br>&bull; <b>Page Size:</b> Number of rows per page (affects List/Summary reports)<br>&bull; <b>Show Data with Graph:</b> Display both the chart AND a data table below it<br>&bull; <b>Max Records:</b> Limit total records returned (0 = no limit)<br>&bull; <b>No Header Sort:</b> Disable column header click-to-sort on the report page<br>&bull; <b>Chart Options:</b> Colors, legend position, axis labels, gridlines, stacking, horizontal orientation\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-settingsPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-options-wrap\" data-bind=\"visible: !panels.isCollapsed('lp-settingsPanel')\">\n                                    <div class=\"form-group row mb-2\">\n                                        <label class=\"control-label\"><i class=\"fa fa-info-circle\"></i> Description</label>\n                                        <div>\n                                            <textarea class=\"form-control form-control-sm\" rows=\"2\" placeholder=\"Optional\" data-bind=\"value: ReportDescription\"></textarea>\n                                        </div>\n                                    </div>\n                                    <div class=\"checkbox\" data-bind=\"visible: canSaveCurrentReport()\">\n                                        <label><input type=\"checkbox\" data-bind=\"checked: SaveReport\"> Save Report</label>\n                                    </div>\n                                    <div class=\"checkbox\" data-bind=\"visible: adminMode() && ReportID()\">\n                                        <label><input type=\"checkbox\" data-bind=\"checked: isSubReportOnly, click: function() { setTimeout(function() { toggleIsSubReportOnly(); }, 0); return true; }\"> Only use as sub report</label>\n                                    </div>\n                                    <div class=\"checkbox\" data-bind=\"visible: adminMode()\">\n                                       <label><input type=\"checkbox\" data-bind=\"checked: ShowAdminOnly\"> </label>\n                                        Hide from reports unless Admin Mode is enabled\n                                    </div>\n                                    <div class=\"form-group row mb-2\" data-bind=\"visible: SaveReport\">\n                                        <label class=\"control-label\"><i class=\"fa fa-folder-open\"></i> Folder</label>\n                                        <div>\n                                            <select class=\"form-select form-select-sm\" style=\"width: 100%;\" data-bind=\"options: Folders, optionsText: function(f) { return f.FolderPath || f.FolderName; }, optionsValue: 'Id', value: FolderID, valueAllowUnset: true\"></select>\n                                        </div>\n                                    </div>\n                                    <hr class=\"my-1\" />\n                                    <div data-bind=\"visible: !useStoredProc()\">\n                                        <div data-bind=\"template: 'designer-options'\"></div>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <!-- Header & Footer -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: SaveReport\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-headerFooterPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-window-maximize\"></i> Header &amp; Footer\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-headerFooterPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-headerFooterPanel')\">\n                                    <div data-bind=\"template: 'designer-header-footer'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Schedule -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: SaveReport() && !ko.unwrap(appSettings.showScheduling) && !isSubReportOnly()\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-schedulePanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-hourglass\"></i> Schedule\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-schedulePanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-auto-update\" data-bind=\"visible: !panels.isCollapsed('lp-schedulePanel')\">\n                                    <div data-bind=\"template: {name: 'report-schedule'}\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Access -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: adminMode()\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-accessPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-key\"></i> Security\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-accessPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-accessPanel')\">\n                                    <div data-bind=\"template: {name: 'manage-access-template', data: manageAccess}\"></div>\n                                </div>\n                            </div>\n\n                        </div>\n                    </div>\n\n                    <!-- RIGHT PANEL -->\n                    <div class=\"col-md-8 h-100\" style=\"overflow-y: auto;\">\n\n                        <!-- ==================== STANDARD MODE (activeDesign OFF) ==================== -->\n                        <div data-bind=\"visible: !activeDesign()\">\n                            <div class=\"card card-body\">\n                                <h5><span class=\"fa fa-file\"></span>&nbsp;Choose Visualization</h5>\n                                <div style=\"overflow-x: auto; white-space: nowrap;\">\n                                    <div data-bind=\"template: 'designer-choose-visual'\"></div>\n                                </div>\n                            </div>\n                            <div id=\"customFunctionSection\" data-bind=\"visible: isFunctionField() && ReportType() === 'List'\" class=\"custom-field-design\">\n                                <br />\n                                <div class=\"card\">\n                                    <div class=\"card-header\"><b>Build Custom Field</b></div>\n                                    <div class=\"card-body\" data-bind=\"template: 'custom-function-designer'\"></div>\n                                </div>\n                                <div class=\"clearfix\"></div>\n                            </div>\n                            <div data-bind=\"template: 'json-field-picker'\"></div>\n                            <div id=\"customFieldSection\" data-bind=\"visible: isFormulaField\" class=\"custom-field-design\">\n                                <br />\n                                <div class=\"card\">\n                                    <div class=\"card-header\"><b>Build Custom Field</b></div>\n                                    <div class=\"card-body\" data-bind=\"template: 'custom-field-designer'\"></div>\n                                </div>\n                                <div class=\"clearfix\"></div>\n                            </div>\n                            <br />\n                            <div class=\"card card-body\">\n                                <div class=\"row\">\n                                    <h5 class=\"col-8 float-start\"><span class=\"fa fa-table\"></span>&nbsp;Selected data for the Report</h5>\n                                    <div class=\"col-4 float-end right-align\">\n                                        <a href=\"#\" class=\"small text-muted\" data-bind=\"visible: SelectedFields().length, click: function() {SelectedFields([]);}\">Clear all</a>\n                                    </div>\n                                </div>\n                                <div data-bind=\"template: 'designer-selected-data'\"></div>\n                            </div>\n                            <div data-bind=\"visible: linkedReportFields().length > 0\">\n                                <br />\n                                <div class=\"card mb-4\">\n                                    <div class=\"card-header bg-light\">\n                                        <h5 class=\"mb-0\"><i class=\"fa fa-bookmark\"></i> Include Sub Reports</h5>\n                                    </div>\n                                    <div class=\"card-body\">\n                                        <div data-bind=\"template: 'designer-sub-report'\"></div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div data-bind=\"visible: ReportType()=='Html'\">\n                                <br />\n                                <div class=\"card mb-4\">\n                                    <div class=\"card-header bg-light\">\n                                        <h5 class=\"mb-0\"><i class=\"fa fa-pencil\"></i> Design your Report</h5>\n                                    </div>\n                                    <div class=\"card-body\">\n                                        <div data-bind=\"template: 'designer-html'\"></div>\n                                    </div>\n                                </div>\n                            </div>\n                            <br />\n                            <div class=\"card card-body\">\n                                <h5><span class=\"fa fa-filter\"></span>&nbsp;Choose Filters</h5>\n                                <div class=\"row\" style=\"padding: 10px 10px; overflow-x: auto;\">\n                                    <div data-bind=\"visible: useStoredProc\" class=\"col-md-12\">\n                                        <div data-bind=\"template: {name: 'filter-parameters'}\"></div>\n                                    </div>\n                                    <div data-bind=\"visible: !useStoredProc()\" class=\"col-md-12\">\n                                        <div data-bind=\"template: {name: 'filter-group'}\"></div>\n                                    </div>\n                                    <div class=\"checkbox col-12\">\n                                        <label>\n                                            <input type=\"checkbox\" data-bind=\"checked: EditFiltersOnReport\" />\n                                            Allow setting up and saving filters on Report\n                                        </label>\n                                    </div>\n                                    <br />\n                                </div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: !useStoredProc()\" class=\"card card-body\">\n                                <h5><span class=\"fa fa-sort\"></span>&nbsp;Choose Sorting</h5>\n                                <div data-bind=\"template: 'designer-sort'\"></div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: SaveReport() && !ko.unwrap(appSettings.showScheduling) && !isSubReportOnly()\" class=\"card card-body\">\n                                <h5><span class=\"fa fa-hourglass\"></span>&nbsp;Choose Schedule</h5>\n                                <div style=\"padding: 10px 10px\" data-bind=\"visible: SaveReport\">\n                                    <div data-bind=\"template: {name: 'report-schedule'}\"></div>\n                                </div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: !useStoredProc()\">\n                                <div class=\"card card-body\">\n                                    <div data-bind=\"template: 'designer-options'\"></div>\n                                </div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: SaveReport\" class=\"card card-body\">\n                                <h5><span class=\"fa fa-window-maximize\"></span>&nbsp;Header &amp; Footer</h5>\n                                <div data-bind=\"template: 'designer-header-footer'\"></div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: adminMode\" class=\"card card-body\">\n                                <div data-bind=\"template: {name: 'manage-access-template', data: manageAccess}\"></div>\n                            </div>\n                        </div>\n\n                        <!-- ==================== LIVE PREVIEW MODE (activeDesign ON) ==================== -->\n                        <div data-bind=\"css: {'d-flex': activeDesign(), 'd-none': !activeDesign()}\" class=\"live-preview-area flex-column\" style=\"height: 100%;\">\n                            <!-- Custom Field (shown above preview when active) -->\n                            <div data-bind=\"visible: isFormulaField()\" class=\"mb-2\">\n                                <div class=\"card custom-field-design\">\n                                    <div class=\"card-header py-1\"><i class=\"fa fa-magic\"></i> Build Custom Field</div>\n                                    <div class=\"card-body\" data-bind=\"template: 'custom-field-designer'\"></div>\n                                </div>\n                            </div>\n                            <!-- Custom Function (shown above preview when active) -->\n                            <div data-bind=\"visible: isFunctionField() && ReportType() === 'List'\" class=\"mb-2\">\n                                <div class=\"card custom-field-design\">\n                                    <div class=\"card-header py-1\"><i class=\"fa fa-magic\"></i> Build Custom Function</div>\n                                    <div class=\"card-body\" data-bind=\"template: 'custom-function-designer'\"></div>\n                                </div>\n                            </div>\n                            <div class=\"card flex-grow-1 d-flex flex-column\" style=\"min-height: 0;\">\n                                <div class=\"card-header py-2 d-flex align-items-center justify-content-between bg-light\">\n                                    <span><i class=\"fa fa-desktop\"></i> Live Preview</span>\n                                    <span class=\"text-muted small\" data-bind=\"visible: ReportName()\">\n                                        <span data-bind=\"text: ReportName\"></span>\n                                    </span>\n                                </div>\n                                <div class=\"card-body flex-grow-1\" style=\"overflow-y: auto; min-height: 0;\">\n                                    <div data-bind=\"if: typeof CanEdit === 'function' && CanEdit() && ReportType()!='Html' && ReportType()!='Single'\">\n                                        <div data-bind=\"template: 'chart-settings', data: $data\"></div>\n                                    </div>\n                                    <div data-bind=\"if: typeof CanEdit === 'function' && CanEdit() && ReportType()=='Single'\">\n                                        <div data-bind=\"template: 'kpi-settings', data: $data\"></div>\n                                    </div>\n                                    <p data-bind=\"html: ReportDescription, visible: ReportDescription\"></p>\n                                    <div data-bind=\"with: ReportResult\" class=\"small\">\n                                        <div data-bind=\"visible: !ReportData()\">\n                                            <div class=\"report-spinner\"></div>\n                                        </div>\n                                        <div data-bind=\"template: 'report-template', data: $data\"></div>\n                                    </div>\n                                </div>\n                                <div class=\"card-footer py-1\">\n                                    <div class=\"small d-flex align-items-center justify-content-between\" data-bind=\"with: pager\">\n                                        <div data-bind=\"visible: totalRecords() > 1 && $parent.ReportType() != 'Single'\">\n                                            <span data-bind=\"text: 'Total Records: ' + totalRecords()\"></span>\n                                        </div>\n                                        <div data-bind=\"visible: pages() > 1 && $parent.ReportType() != 'Single'\">\n                                            <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button class=\"btn btn-primary\" data-bind=\"visible: adminMode, click: RunReportSqlPreview\">\n                    <i class=\"fa fa-code\"></i> Preview Report Code\n                </button>\n                <button class=\"btn btn-outline-secondary\" type=\"button\" data-bind=\"visible: !SaveReport() || !ReportID(), click: startOverReport\" title=\"Clear everything and start a new report\">\n                    <i class=\"fa fa-refresh\"></i> Start Over\n                </button>\n                <a href=\"#\" class=\"btn btn-danger\" data-bind=\"click: cancelCreateReport\">Cancel editing Report</a>\n                <button class=\"btn btn-primary\" type=\"button\" data-bind=\"visible: SaveReport() && canSaveCurrentReport(), click: SaveWithoutRun, disable: savingReport() || savingAndRunning()\" style=\"padding-right: 10px;\">\n                    <!-- ko if: savingReport() --><span class=\"fa fa-spinner fa-spin me-1\"></span>Saving...<!-- /ko -->\n                    <!-- ko ifnot: savingReport() -->Save Report<!-- /ko -->\n                </button>\n                <button class=\"btn btn-primary\" type=\"button\" data-bind=\"click: SaveAndRunReport, visible: !editingSubReportParentId(), disable: savingReport() || savingAndRunning()\">\n                    <!-- ko if: savingAndRunning() --><span class=\"fa fa-spinner fa-spin me-1\"></span>Saving...<!-- /ko -->\n                    <!-- ko ifnot: savingAndRunning() --><!-- ko text: SaveReport() && canSaveCurrentReport()? 'Save & Run Report': 'Run Report' --><!-- /ko --><!-- /ko -->\n                </button>\n            </div>\n\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"chart-settings\">\n    <div class=\"chart-container float-end\">\n        <button class=\"btn btn-light btn-sm d-flex align-items-center mt-2 chart-settings-btn\"\n                data-bind=\"click: toggleChartSettings\" title=\"Report settings\">\n            <i class=\"fa fa-cog\"></i>\n        </button>\n\n        <div class=\"chart-settings-panel border p-2 shadow-sm bg-light\" data-bind=\"visible: showSettings\">\n            <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                <button class=\"btn btn-sm btn-close\" data-bind=\"click: toggleChartSettings\"></button>\n                <h6 class=\"mb-0\">Report Settings</h6>\n            </div>\n             <ul class=\"nav nav-tabs nav-sm mb-2 small\" data-bind=\"visible: ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line'\">\n                <li class=\"nav-item\">\n                    <a class=\"nav-link\"\n                       data-bs-toggle=\"tab\"\n                       data-bind=\"attr: { href: '#chartTab-' + ReportID() }, css: { active: ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line' }\">\n                        Chart\n                    </a>\n                </li>\n                <li class=\"nav-item\">\n                    <a class=\"nav-link\"\n                       data-bs-toggle=\"tab\"\n                       data-bind=\"attr: { href: '#tableTab-' + ReportID() }, css: { active: !(ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line') }\">\n                        Table\n                    </a>\n                </li>\n            </ul>\n            <div class=\"tab-content small\">\n                <div class=\"tab-pane fade\"\n                     data-bind=\"attr: { id: 'chartTab-' + ReportID() }, css: { 'show active': ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line' }\">\n                    <div class=\"mb-2\">\n                        <div class=\"btn-group\" role=\"group\" data-bind=\"visible: ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line'\">\n                            <button type=\"button\" class=\"btn btn-light\" data-bs-toggle=\"tooltip\" title=\"Bar Chart\"\n                                    data-bind=\"css: { 'active': ReportType() === 'Bar' }, click: function() { ReportType('Bar'); }\">\n                                <span class=\"fa fa-bar-chart\"></span>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-light\" data-bs-toggle=\"tooltip\" title=\"Pie Chart\"\n                                    data-bind=\"css: { 'active': ReportType() === 'Pie' }, click: function() { ReportType('Pie'); }\">\n                                <span class=\"fa fa-pie-chart\"></span>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-light\" data-bs-toggle=\"tooltip\" title=\"Line Chart\"\n                                    data-bind=\"css: { 'active': ReportType() === 'Line' }, click: function() { ReportType('Line'); }\">\n                                <span class=\"fa fa-line-chart\"></span>\n                            </button>\n                        </div>\n                    </div>\n                    <div data-bind=\"visible: ReportType()=='Bar'\">\n                        <div class=\"form-group row\">\n                            <div class=\"checkbox col-6\">\n                                <label><input type=\"checkbox\" data-bind=\"checked: barChartHorizontal\" /> Horizontal</label>\n                            </div>\n                            <div class=\"checkbox col-6\">\n                                <label><input type=\"checkbox\" data-bind=\"checked: barChartStacked\" /> Stacked</label>\n                            </div>\n                        </div>\n                    </div>\n                    <div data-bind=\"visible: ReportType()=='Pie'\">\n                        <div class=\"form-group row\">\n                            <div class=\"checkbox col-6\">\n                                <label><input type=\"checkbox\" data-bind=\"checked: pieChartDonut\" /> Donut</label>\n                            </div>\n                        </div>\n                    </div>\n                    <div data-bind=\"visible: ReportType()=='Line'\">\n                        <div class=\"form-group row\">\n                            <div class=\"checkbox col-6\">\n                                <label><input type=\"checkbox\" data-bind=\"checked: lineChartArea\" /> Area</label>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Background Color</label>\n                        <div class=\"d-flex align-items-center flex-wrap\">\n                            <input type=\"color\" class=\"color-picker\" data-bind=\"value: chartOptions().backgroundColor, attr: { placeholder: 'Select' }, event: { change: updateChart }\">\n                        </div>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Font Color</label>\n                        <div class=\"d-flex align-items-center flex-wrap\">\n                            <input type=\"color\" class=\"color-picker\" data-bind=\"value: chartOptions().fontColor, attr: { placeholder: 'Select' }, event: { change: updateChart }\">\n                        </div>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Series Colors</label>\n                        <div class=\"d-flex flex-wrap\" data-bind=\"foreach: chartOptions().seriesColors\">\n                            <div class=\"color-box me-2\">\n                                <input type=\"color\" class=\"color-picker\"\n                                       data-bind=\"value: $data, event: { input: function(data, event) { $parent.updateSeriesColor($index(), event.target.value); } }\">\n                                <button class=\"btn btn-sm btn-danger remove-color\" data-bind=\"click: $parent.removeSeriesColor\">&times;</button>\n                            </div>\n                        </div>\n                        <button class=\"color-box btn btn-sm btn-secondary\" data-bind=\"click: addSeriesColor\" title=\"Add Series Color\" style=\"margin-top: -7px;\">\n                            <i class=\"fa fa-plus\"></i>\n                        </button>\n                    </div>\n                    <div class=\"d-flex justify-content-between mb-1\">\n                        <div>\n                            <label class=\"form-label small\">Legend Position</label>\n                            <select class=\"form-select form-select-sm\" data-bind=\"value: chartOptions().legendPosition, event: { change: function(data, $event) { updateLegend($event.target.value); } }\">\n                                <option value=\"top\">Top</option>\n                                <option value=\"right\">Right</option>\n                                <option value=\"bottom\">Bottom</option>\n                                <option value=\"left\">Left</option>\n                                <option value=\"none\">None</option>\n                            </select>\n                        </div>\n                        <div>\n                            <label class=\"form-label small\">Font Size</label>\n                            <input type=\"number\" class=\"form-control form-control-sm font-size-input\" data-bind=\"value: chartOptions().fontSize, event: { change: updateChart }\">\n                        </div>\n                    </div>\n                    <div data-bind=\"visible: ReportType()!='Pie'\">\n                        <div class=\"form-check form-switch small mb-1\">\n                            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: chartOptions().showXAxisLabel, event: { change: updateChart }\">\n                            <label class=\"form-check-label\">X-Axis Label</label>\n                        </div>\n                        <div class=\"form-check form-switch small mb-1\">\n                            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: chartOptions().showYAxisLabel, event: { change: updateChart }\">\n                            <label class=\"form-check-label\">Y-Axis Label</label>\n                        </div>\n                        <div class=\"form-check form-switch small mb-1\" data-bind=\"visible: ReportType() !== 'Pie'\">\n                            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: chartOptions().showGridlines, event: { change: updateChart }\">\n                            <label class=\"form-check-label\">Gridlines</label>\n                        </div>\n                        <div class=\"form-check form-switch small mb-1\">\n                            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: chartOptions().showSmallValuesOnLabel, event: { change: updateChart }\">\n                            <label class=\"form-check-label\">Show Small Values On Label</label>\n                        </div>\n                        <div class=\"form-group small mb-1\">\n                            <label class=\"form-label\">Y-Axis Format</label>\n                            <select class=\"form-select form-select-sm\" data-bind=\"value: chartOptions().yAxisFormat, event: { change: function() { updateYAxisFormat(); updateChart(); } }\">\n                                <option value=\"\">Auto (from Field)</option>\n                                <option value=\"Currency\">Currency</option>\n                                <option value=\"Percentage\">Percentage</option>\n                                <option value=\"Decimal\">Decimal</option>\n                                <option value=\"Number\">Number</option>\n                            </select>\n                        </div>\n                        <div class=\"form-group small mb-1 d-flex gap-2\">\n                            <div class=\"w-50\">\n                                <label class=\"form-label\">Y-Axis Min</label>\n                                <input type=\"number\" class=\"form-control form-control-sm\" data-bind=\"value: chartOptions().yMin, event: { change: updateChart }\" />\n                            </div>\n                            <div class=\"w-50\">\n                                <label class=\"form-label\">Y-Axis Max</label>\n                                <input type=\"number\" class=\"form-control form-control-sm\" data-bind=\"value: chartOptions().yMax, event: { change: updateChart }\" />\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <div class=\"tab-pane fade\"\n                     data-bind=\"attr: { id: 'tableTab-' + ReportID() }, css: { 'show active': !(ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line') }\">\n                    <div class=\"form-group row\">\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Header Back Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()} , value: tableSettings().headerBackColor, event: { change: updateTable }\"/>\n                        </div>\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Header Font Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()} ,value: tableSettings().headerFontColor, event: { change: updateTable }\"/>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Row Back Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()} ,value: tableSettings().rowBackColor, event: { change: updateTable }\"/>\n                        </div>\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Row Font Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()} ,value: tableSettings().rowFontColor, event: { change: updateTable }\"/>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" style=\"display: none;\">\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Alt Row Back Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"value: tableSettings().altRowBackColor, event: { change: updateTable }\"/>\n                        </div>\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Alt Row Font Color</label>\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"value: tableSettings().altRowFontColor, event: { change: updateTable }\"/>\n                        </div>\n                    </div>\n                    <div class=\"form-group mb-2\" style=\"display: none;\">\n                        <label class=\"form-label small\">Borders</label>\n                        <div class=\"btn-group d-flex flex-wrap\">\n                            <button type=\"button\" class=\"btn btn-light btn-sm flex-fill\"\n                                    data-bind=\"click: function(){ tableSettings().border('none'); updateTable(); }, css: { active: tableSettings().border === 'none' }\">None</button>\n                            <button type=\"button\" class=\"btn btn-light btn-sm flex-fill\"\n                                    data-bind=\"click: function(){ tableSettings().border('all'); updateTable(); }, css: { active: tableSettings().border === 'all' }\">All</button>\n                            <button type=\"button\" class=\"btn btn-light btn-sm flex-fill\"\n                                    data-bind=\"click: function(){ tableSettings().border('outer'); updateTable(); }, css: { active: tableSettings().border === 'outer' }\">Outside</button>\n                            <button type=\"button\" class=\"btn btn-light btn-sm flex-fill\"\n                                    data-bind=\"click: function(){ tableSettings().border('inner'); updateTable(); }, css: { active: tableSettings().border === 'inner' }\">Inside</button>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <div class=\"mb-2 col-6\" style=\"display: none;\">\n                            <label class=\"form-label small\">Border Color</label>\n                            <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: tableSettings().borderColor, event: { change: updateTable }\"/>\n                        </div>\n                         <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Back Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()},value: tableSettings().backColor, event: { change: updateTable }\"/>\n                        </div>\n                        <div class=\"mb-2 col-6 d-flex align-items-end\">\n                            <button class=\"btn btn-sm small\"\n                                    data-bind=\"click: copyTableFormat\"\n                                    title=\"Copy Format\">\n                                <i class=\"fa fa-copy\"></i>\n                            </button>\n                            <button class=\"btn btn-sm small\"\n                                    data-bind=\"click: pasteTableFormat\"\n                                    title=\"Paste Format\">\n                                <i class=\"fa fa-paste\"></i>\n                            </button>\n                            <button class=\"btn btn-sm small\" data-bind=\"click: clearTableSettings\"\n                                title=\"Clear\">\n                                <i class=\"fa fa-close\"></i>\n                            </button>\n                        </div>\n                    </div>                    \n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n\n<div class=\"modal\" id=\"drilldownModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\">\n        <div class=\"modal-content\" data-bind=\"with: ChartDrillDownData\">\n            <div class=\"modal-header\">\n                <h4 class=\"modal-title\">Drilldown Data</h4>\n                <button type=\"button\" class=\"btn-close float-end\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <!-- ko if: DrillDownData -->\n            <div class=\"modal-body\">\n                <div style=\"overflow-x: auto; max-height: 500px; overflow-y: auto;\">\n                    <table class=\"table table-striped table-hover table-condensed\" data-bind=\"with: DrillDownData, attr: {class: 'table table-striped table-hover table-condensed ' + $parent.selectedStyle()}\">\n                        <thead style=\"position: sticky; top: -1px; z-index: 2;\">\n                            <tr class=\"no-highlight\">\n                                <!-- ko foreach: Columns -->\n                                <th data-bind=\"attr: { id: fieldId }, css: {'right-align': IsNumeric}, style: {'width': fieldWidth, 'background-color': headerBackColor }, hidden: outerGroup\" style=\"border-right: 1px solid;\">\n                                    <span data-bind=\"text: fieldLabel2() ? fieldLabel2() : (fieldLabel() ? fieldLabel() : fieldName), style: {'color': headerFontColor, 'font-weight': headerFontBold() ? 'bold' : 'normal'}\"></span>\n                                </th>\n                                <!-- /ko -->\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr style=\"display: none;\" data-bind=\"visible: Rows && Rows.length < 1\">\n                                <td data-bind=\"attr:{colspan: Columns.length}\">\n                                    No records found\n                                </td>\n                            </tr>\n                            <!-- ko foreach: Rows  -->\n                            <tr>\n                                <!-- ko foreach: Items -->\n                                <td data-bind=\"hidden: outerGroup, style: {'background-color': backColor, 'color': fontColor, 'font-weight': fontBold() ? 'bold' : 'normal' }\">\n                                    <div data-bind=\"style: {'width': fieldWidth }\">\n                                        <!-- ko if: LinkTo-->\n                                        <!-- ko if: $data._runLinkedReportInPlace -->\n                                        <a href=\"#\" data-bind=\"click: $data._runLinkedReportInPlace\"><span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span></a>\n                                        <!-- /ko -->\n                                        <!-- ko ifnot: $data._runLinkedReportInPlace -->\n                                        <a data-bind=\"attr: {href: LinkTo}\" target=\"_blank\"><span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span></a>\n                                        <!-- /ko -->\n                                        <!-- /ko-->\n                                        <!-- ko ifnot: LinkTo-->\n                                        <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n                                        <!-- /ko-->\n                                    </div>\n                                </td>\n                                <!-- /ko-->\n                            </tr>\n                            <!-- /ko -->\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <div class=\"col-xs-12 col-centered\" data-bind=\"with: pager\">\n                    <div class=\"form-inline small text-muted\">\n                        <div class=\"float-start total-records\" data-bind=\"visible: pages()\">\n                            <span data-bind=\"text: 'Total Records: ' + totalRecords()\"></span>\n                        </div>\n                        <div class=\"float-start\">\n                            <button class=\"btn btn-xs\" title=\"Download Excel\" data-bind=\"click: $parent.exportExcel\"><span class=\"fas fa-file-excel\"></span></button>\n                            <button class=\"btn btn-secondary btn-sm\" data-bs-toggle=\"modal\" data-bs-target=\"#sqlDrillDownModal\" data-bind=\"visible: $root.adminMode\">\n                                <span class=\"fa fa-code\"></span> View Code\n                            </button>\n                        </div>\n                        <div class=\"form-group float-end\" data-bind=\"visible: pages()\">\n                            <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <!-- /ko -->\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"sqlModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header d-flex justify-content-between align-items-center\">\n                <h4 class=\"modal-title\">Report Code</h4>\n                <button class=\"btn btn-outline-secondary btn-sm d-flex align-items-center\"\n                        data-bind=\"click: function(data, event) { copySqlToClipboard(event.target); }\">\n                    <i class=\"fa fa-clipboard\"></i>&nbsp;Copy\n                </button>\n                <button type=\"button\" class=\"btn-close float-end\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\" data-bind=\"with: ReportResult\">\n                <div id=\"reportSqlCode\" style=\"overflow-x: auto; max-height: 500px; overflow-y: scroll; border: 1px solid; padding: 10px;\" class=\"bg-dark text-light\">\n                    <pre><code data-bind=\"html: ReportSql\" style=\"white-space: pre-wrap;\"></code></pre>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"sqlDrillDownModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\">\n        <div class=\"modal-content\" data-bind=\"with:ChartDrillDownData\">\n            <div class=\"modal-header d-flex justify-content-between align-items-center\">\n                <h4 class=\"modal-title\">Drill Down Report Code</h4>\n                <button class=\"btn btn-outline-secondary btn-sm d-flex align-items-center\"\n                        data-bind=\"click: function(data, event) { copySqlToClipboard(event.target); }\">\n                    <i class=\"fa fa-clipboard\"></i>&nbsp;Copy\n                </button>\n                <button type=\"button\" class=\"btn-close float-end\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\" data-bind=\"with:DrillDownData\">\n                <div id=\"reportSqlCode\" style=\"overflow-x: auto; max-height: 500px; overflow-y: scroll; border: 1px solid; padding: 10px;\" class=\"bg-dark text-light\">\n                    <pre><code data-bind=\"html: ReportSql\" style=\"white-space: pre-wrap;\"></code></pre>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n<div class=\"modal\" id=\"noaccountModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n                <h4 class=\"modal-title\">Account not Setup</h4>\n            </div>\n            <div class=\"modal-body\">\n                <p class=\"alert alert-danger\">dotnet Report Account Configuration missing!</p>\n                <p>You do not have the neccessary initial configuration completed to use dotnet Report.</p>\n                <p>Please view the <a href=\"https://dotnetreport.com/blogs/getting-started-with-dotnet-report/\" target=\"_blank\">Getting Started Guide</a> to correctly configure dotnet Report.</p>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-default\" data-bs-dismiss=\"modal\">Close</button>\n            </div>\n        </div>\n    </div>\n</div>\n<script type=\"text/html\" id=\"pdf-options-schedule-template\">\n    <div class=\"modal-dialog modal-dialog-centered\">\n        <div class=\"modal-content\" data-bind=\"with: PdfPage\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"pdfOptionsScheduleModalLabel\">\n                    <i class=\"fas fa-file-pdf me-2\"></i> Set PDF Page Size\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body row g-0\">\n                <div class=\"col-md-5 d-flex justify-content-center align-items-center\">\n                    <div id=\"pagePreviewBox\" class=\"text-center\">\n                        <div data-bind=\"style: {\n                                     width: selectedWidth(),\n                                     height: selectedHeight(),\n                                     backgroundColor: selectedBackgroundStyle(),\n                                     transition: 'all 0.3s ease'\n                                 }\"\n                             class=\"shadow rounded mx-auto mb-2 border position-relative\">\n                            <span class=\"position-absolute top-50 start-50 translate-middle text-muted small\">Preview</span>\n                        </div>\n                        <div data-bind=\"text: selectedPageLabel\" class=\"fw-bold\"></div>\n                        <div data-bind=\"text: selectedPageDimension\" class=\"text-muted small\"></div>\n                    </div>\n                </div>\n                <div class=\"col-md-7\">\n                    <div class=\"mb-3\">\n                        <label for=\"pageSizeSelect\" class=\"form-label fw-bold\">Page Size:</label>\n                        <select class=\"form-select\" id=\"pageSizeSelect\"\n                                data-bind=\"options: availablePageSizes,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageSize\">\n                        </select>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"pageOrientationSelect\" class=\"form-label fw-bold\">Page Orientation:</label>\n                        <select class=\"form-select\" id=\"pageOrientationSelect\"\n                                data-bind=\"options: availablePageOrientation,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageOrientation\">\n                        </select>\n                    </div>\n                    <div class=\"alert alert-info p-2 small mt-2\">\n                        This PDF will be exported using the selected page size. Ensure your content fits well.\n                        If the content width exceeds the selected size, it will default to Letter.\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-success\" data-bs-dismiss=\"modal\" data-bind=\"click: save\">\n                     Save\n                </button>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"word-options-schedule-template\">\n    <div class=\"modal-dialog modal-dialog-centered\">\n        <div class=\"modal-content\" data-bind=\"with: WordPage\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"pdfOptionsScheduleModalLabel\">\n                    <i class=\"fas fa-file-pdf me-2\"></i> Set WORD Page Size\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body row g-0\">\n                <div class=\"col-md-5 d-flex justify-content-center align-items-center\">\n                    <div id=\"pagePreviewBox\" class=\"text-center\">\n                        <div data-bind=\"style: {\n                                     width: selectedWidth(),\n                                     height: selectedHeight(),\n                                     backgroundColor: selectedBackgroundStyle(),\n                                     transition: 'all 0.3s ease'\n                                 }\"\n                             class=\"shadow rounded mx-auto mb-2 border position-relative\">\n                            <span class=\"position-absolute top-50 start-50 translate-middle text-muted small\">Preview</span>\n                        </div>\n                        <div data-bind=\"text: selectedPageLabel\" class=\"fw-bold\"></div>\n                        <div data-bind=\"text: selectedPageDimension\" class=\"text-muted small\"></div>\n                    </div>\n                </div>\n                <div class=\"col-md-7\">\n                    <div class=\"mb-3\">\n                        <label for=\"pageSizeSelect\" class=\"form-label fw-bold\">Page Size:</label>\n                        <select class=\"form-select\" id=\"pageSizeSelect\"\n                                data-bind=\"options: availablePageSizes,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageSize\">\n                        </select>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"pageOrientationSelect\" class=\"form-label fw-bold\">Page Orientation:</label>\n                        <select class=\"form-select\" id=\"pageOrientationSelect\"\n                                data-bind=\"options: availablePageOrientation,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageOrientation\">\n                        </select>\n                    </div>\n                    <div class=\"alert alert-info p-2 small mt-2\">\n                        This WORD will be exported using the selected page size. Ensure your content fits well.\n                        If the content width exceeds the selected size, it will default to Letter.\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-success\" data-bs-dismiss=\"modal\" data-bind=\"click: save\">\n                     Save\n                </button>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"word-options-template\">\n        <div class=\"modal-dialog modal-dialog-centered\">\n        <div class=\"modal-content\" data-bind=\"with: WordPage\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"wordOptionsModalLabel\"><i class=\"fas fa-file-pdf me-2\"></i> Export to WORD</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body row g-0\">\n                <!-- Left Side: Page Preview SVG -->\n                <div class=\"col-md-5 d-flex justify-content-center align-items-center\">\n                    <div id=\"pagePreviewBox\" class=\"text-center\">\n                        <div data-bind=\"style: {\n                                     width: selectedWidth(),\n                                     height: selectedHeight(),\n                                     backgroundColor: selectedBackgroundStyle(),\n                                     transition: 'all 0.3s ease'\n                                 }\"\n                             class=\"shadow rounded mx-auto mb-2 border position-relative\">\n                            <span class=\"position-absolute top-50 start-50 translate-middle text-muted small\">Preview</span>\n                        </div>\n                        <div data-bind=\"text: selectedPageLabel\" class=\"fw-bold\"></div>\n                        <div data-bind=\"text: selectedPageDimension\" class=\"text-muted small\"></div>\n                    </div>\n                </div>\n\n                <!-- Right Side: Form Options -->\n                <div class=\"col-md-7\">\n                    <div class=\"mb-3\">\n                        <label for=\"pageSizeSelect\" class=\"form-label fw-bold\">Page Size:</label>\n                        <select class=\"form-select\" id=\"pageSizeSelect\"\n                                data-bind=\"options: availablePageSizes,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageSize\">\n                        </select>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"pageOrientationSelect\" class=\"form-label fw-bold\">Page Orientation:</label>\n                        <select class=\"form-select\" id=\"pageOrientationSelect\"\n                                data-bind=\"options: availablePageOrientation,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageOrientation\">\n                        </select>\n                    </div>\n                    <div class=\"alert alert-info p-2 small mt-2\">\n                        This Word will be exported using the selected page size. Ensure your content fits well.\n                        If the content width exceeds the selected size, it will default to Letter.\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-success\" data-bs-dismiss=\"modal\" data-bind=\"click: download\">\n                    <i class=\"fa fa-download me-1\"></i> Download Word\n                </button>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"pdf-options-template\">\n    <div class=\"modal-dialog modal-dialog-centered\">\n        <div class=\"modal-content\" data-bind=\"with: PdfPage\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"pdfOptionsModalLabel\"><i class=\"fas fa-file-pdf me-2\"></i> Export to PDF</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body row g-0\">\n                <!-- Left Side: Page Preview SVG -->\n                <div class=\"col-md-5 d-flex justify-content-center align-items-center\">\n                    <div id=\"pagePreviewBox\" class=\"text-center\">\n                        <div data-bind=\"style: {\n                                     width: selectedWidth(),\n                                     height: selectedHeight(),\n                                     backgroundColor: selectedBackgroundStyle(),\n                                     transition: 'all 0.3s ease'\n                                 }\"\n                             class=\"shadow rounded mx-auto mb-2 border position-relative\">\n                            <span class=\"position-absolute top-50 start-50 translate-middle text-muted small\">Preview</span>\n                        </div>\n                        <div data-bind=\"text: selectedPageLabel\" class=\"fw-bold\"></div>\n                        <div data-bind=\"text: selectedPageDimension\" class=\"text-muted small\"></div>\n                    </div>\n                </div>\n\n                <!-- Right Side: Form Options -->\n                <div class=\"col-md-7\">\n                    <div class=\"mb-3\">\n                        <label for=\"pageSizeSelect\" class=\"form-label fw-bold\">Page Size:</label>\n                        <select class=\"form-select\" id=\"pageSizeSelect\"\n                                data-bind=\"options: availablePageSizes,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageSize\">\n                        </select>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"pageOrientationSelect\" class=\"form-label fw-bold\">Page Orientation:</label>\n                        <select class=\"form-select\" id=\"pageOrientationSelect\"\n                                data-bind=\"options: availablePageOrientation,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageOrientation\">\n                        </select>\n                    </div>\n                    <div class=\"alert alert-info p-2 small mt-2\">\n                        This PDF will be exported using the selected page size. Ensure your content fits well.\n                        If the content width exceeds the selected size, it will default to Letter.\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-success\" data-bs-dismiss=\"modal\" data-bind=\"click: download\">\n                    <i class=\"fa fa-download me-1\"></i> Download PDF\n                </button>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"line-separator-template\">\n    <div class=\"grid-stack-item-content position-relative p-2\" data-bind=\"css: { card: $root.arrangeDashboard }\">\n        <hr data-bind=\"style: { borderTop: thickness() + 'px solid ' + color() }\" class=\"m-0\">\n        <div data-bind=\"visible: $root.arrangeDashboard\" class=\"dropdown position-absolute\" style=\"top:-5px; right:0; z-index:2000;\">\n            <button class=\"btn btn-sm btn-light\" type=\"button\" data-bs-toggle=\"dropdown\">\n                <i class=\"fa fa-ellipsis-v\"></i>\n            </button>\n               <ul class=\"dropdown-menu dropdown-menu-end p-2 bg-light small\">\n                    <li class=\"d-flex align-items-center gap-2 mb-2\">\n                        <label class=\"form-label small mb-0\">Line Color</label>\n                        <input type=\"color\" class=\"color-picker\" data-bind=\"value: color,valueUpdate: 'input',event: { change: () => $root.onWidgetChange($data)}\">\n                    </li>\n\n                    <li class=\"d-flex align-items-center gap-2 mb-2\">\n                        <label class=\"mb-0\">Thickness</label>\n                        <input type=\"number\"\n                               min=\"1\"\n                               max=\"10\"\n                               data-bind=\"value: thickness,valueUpdate: 'input',event: { change: () => $root.onWidgetChange($data)}\"\n                               class=\"form-control form-control-sm\"\n                               style=\"width:50px\">\n                    </li>\n\n                    <li>\n                        <button class=\"dropdown-item text-danger\" data-bind=\"click: deleteSeparator\">\n                            <i class=\"fa fa-trash me-2\"></i>\n                            Delete\n                        </button>\n                    </li>\n                </ul>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"text-widget-template\">\n    <div class=\"grid-stack-item-content position-relative p-2\" data-bind=\"css: { card: $root.arrangeDashboard }\">\n        <div data-bind=\"html: decodeURIComponent(text())\"></div>\n        <div class=\"position-absolute\" style=\"top:3px; right:4px; z-index:2000;\" data-bind=\"visible: $root.arrangeDashboard\">\n            <div class=\"dropdown\">\n                <button class=\"btn btn-sm btn-light\"\n                        type=\"button\"\n                        data-bs-toggle=\"dropdown\"\n                        aria-expanded=\"false\">\n                    <i class=\"fa fa-ellipsis-v\"></i>\n                </button>\n                <ul class=\"dropdown-menu dropdown-menu-end\">\n                    <li>\n                        <button class=\"dropdown-item\"\n                                data-bind=\"click: $root.openTextEditor\">\n                            <i class=\"fa fa-edit me-2\"></i>\n                            Edit\n                        </button>\n                    </li>\n                    <li>\n                        <button class=\"dropdown-item text-danger\"\n                                data-bind=\"click: deleteText\">\n                            <i class=\"fa fa-trash me-2\"></i>\n                            Delete\n                        </button>\n                    </li>\n                </ul>\n            </div>\n        </div>\n    </div>\n</script>\n\n<!-- Configure Joins Modal -->\n<div class=\"modal\" id=\"weightedmodal-configure-joins\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\" data-bind=\"with: selectedReport\">\n    <div class=\"modal-dialog modal-lg \">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"configureJoinsLabel\"><i class=\"fa fa-link\"></i> Configure Joins for Report</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <p class=\"text-muted small\">Override join types and drag to reorder for this report only.</p>\n\n                <!-- ko if: detectedJoins().length === 0 -->\n                <div class=\"alert alert-info\">\n                    <i class=\"fa fa-info-circle\"></i> No joins detected. Make sure you have selected fields from multiple tables.\n                </div>\n                <!-- /ko -->\n\n                <!-- ko if: detectedJoins().length > 0 -->\n                <div class=\"mb-3 p-2 bg-light rounded d-flex align-items-center\">\n                    <label class=\"fw-bold small me-2 text-nowrap\">FROM (First Table):</label>\n                    <select class=\"form-select form-select-sm\" style=\"max-width: 250px;\"\n                            data-bind=\"options: joinBaseTables, optionsText: 'name', optionsValue: 'id', value: baseTableIdOverride\"></select>\n                </div>\n\n                <div class=\"row fw-bold border-bottom pb-2 mb-1 small text-muted\">\n                    <div class=\"col-1\"></div>\n                    <div class=\"col-2\">Table</div>\n                    <div class=\"col-2\">Field</div>\n                    <div class=\"col-1\"></div>\n                    <div class=\"col-2\">Join Type</div>\n                    <div class=\"col-2\">Joined Table</div>\n                    <div class=\"col-2\">Join Field</div>\n                </div>\n                <div data-bind=\"sortable: { data: detectedJoins, options: { handle: '.report-join-drag-handle', cursor: 'move' }, afterMove: reportJoinSorted }\">\n                    <div class=\"row align-items-center border-bottom py-2\">\n                        <div class=\"col-1\">\n                            <span class=\"btn btn-sm btn-outline-secondary report-join-drag-handle\" title=\"Drag to reorder\"><i class=\"fa fa-bars\"></i></span>\n                        </div>\n                        <div class=\"col-2\">\n                            <span data-bind=\"text: tableName\"></span>\n                            <!-- ko if: isForeignKey -->\n                            <span class=\"badge bg-info ms-1\" title=\"Foreign Key Join\">FK</span>\n                            <!-- /ko -->\n                        </div>\n                        <div class=\"col-2\"><code data-bind=\"text: fieldName\"></code></div>\n                        <div class=\"col-1 text-center\">\n                            <button class=\"btn btn-sm btn-outline-primary\" title=\"Swap Table ↔ Joined Table\" data-bind=\"click: $parent.swapJoinDirection\">\n                                <i class=\"fa fa-exchange\"></i>\n                            </button>\n                        </div>\n                        <div class=\"col-2\">\n                            <select class=\"form-select form-select-sm\"\n                                    data-bind=\"options: ['INNER','LEFT','RIGHT','CROSS'], value: joinType\"></select>\n                        </div>\n                        <div class=\"col-2\" data-bind=\"text: joinedTableName\"></div>\n                        <div class=\"col-2\"><code data-bind=\"text: joinFieldName\"></code></div>\n                    </div>\n                </div>\n                <!-- /ko -->\n            </div>\n            <div class=\"modal-footer\">\n                <button class=\"btn btn-outline-secondary btn-sm\" data-bind=\"click: clearCustomJoins\">\n                    <i class=\"fa fa-times\"></i> Clear Overrides\n                </button>\n                <button class=\"btn btn-primary btn-sm\" data-bind=\"click: saveCustomJoins\">\n                    <i class=\"fa fa-check\"></i> Apply to Report\n                </button>\n            </div>\n        </div>\n    </div>\n</div>\n<!-- Templates -->\n\n</div>";
export const setupHtml = "<div id=\"dot-net-report\" class=\"body-content\">\n<div>\n    <h2>Manage Database</h2>\n    <p>\n        You can select and manage display names for the Tables and Columns you would like to allow in Dotnet Report Builder.\n    </p>\n    <div class=\"alert alert-danger d-flex justify-content-between align-items-center\">\n        <div>\n            Do not expose this Setup Tool to end users who should not have access to it. Ideally, only Developers should be given access to this utility.\n        </div>\n        <button class=\"btn btn-primary ms-3\" data-bind=\"click: refreshAll\" title=\"Reload all Table and Columns\">\n            <i class=\"fa fa-refresh\"></i> Refresh\n        </button>\n    </div>\n\n    <div data-bind=\"visible: false;\">\n        Loading...\n    </div>\n\n    <div class=\"d-flex justify-content-between align-items-center\">\n        <!-- Nav tabs -->\n        <ul class=\"nav nav-tabs flex-grow-1\" role=\"tablist\">\n            <li role=\"presentation\" class=\"nav-item\">\n                <a class=\"nav-link active\" href=\"#tablesfields\" aria-controls=\"home\" role=\"tab\" data-bs-toggle=\"tab\" data-bind=\"click: function() { customTableMode(false); activeTable(null);}\">\n                    <i class=\"fa fa-database\"></i> Database Tables\n                </a>\n            </li>\n            <li role=\"presentation\" class=\"nav-item\">\n                <a class=\"nav-link\" href=\"#tablesfields\" aria-controls=\"custom\" role=\"tab\" data-bs-toggle=\"tab\" data-bind=\"click: function() { customTableMode(true); activeTable(null); }\">\n                    <i class=\"fa fa-table\"></i> Custom Tables\n                </a>\n            </li>\n            <li role=\"presentation\" class=\"nav-item\">\n                <a class=\"nav-link\" href=\"#relations\" aria-controls=\"profile\" role=\"tab\" data-bs-toggle=\"tab\">\n                    <i class=\"fa fa-link\"></i> Relations\n                </a>\n            </li>\n            <li role=\"presentation\" class=\"nav-item\">\n                <a class=\"nav-link\" href=\"#procedure\" aria-controls=\"procedure\" role=\"tab\" data-bs-toggle=\"tab\">\n                    <i class=\"fa fa-code\"></i> Stored Procs\n                </a>\n            </li>\n            <li role=\"presentation\" class=\"nav-item\">\n                <a class=\"nav-link\" href=\"#usersroles\" aria-controls=\"usersroles\" role=\"tab\" data-bs-toggle=\"tab\" data-bind=\"click: function() { usersRoles.onTabOpen(); }\">\n                    <i class=\"fa fa-users\"></i> Users &amp; Roles\n                </a>\n            </li>\n            <li role=\"presentation\" class=\"nav-item\">\n                <a class=\"nav-link\" href=\"#schedules\" aria-controls=\"schedules\" role=\"tab\" data-bs-toggle=\"tab\">\n                    <i class=\"fa fa-clock\"></i> Schedules\n                </a>\n            </li>\n            <li role=\"presentation\" class=\"nav-item\">\n                <a class=\"nav-link\" href=\"#emailqueries\" aria-controls=\"emailqueries\" role=\"tab\" data-bs-toggle=\"tab\" data-bind=\"click: function() { emailQueries.load(); }\">\n                    <i class=\"fa fa-envelope\"></i> Email Lists\n                </a>\n            </li>\n            <li role=\"presentation\" class=\"nav-item\" style=\"display: none;\" data-bind=\"visible: settings.useFunctions\">\n                <a class=\"nav-link\" href=\"#functions\" aria-controls=\"functions\" role=\"tab\" data-bs-toggle=\"tab\">\n                    <i class=\"fa fa-cogs\"></i> Custom Functions\n                </a>\n            </li>\n            <li role=\"presentation\" class=\"nav-item\">\n                <a class=\"nav-link\" href=\"#manageaccess\" aria-controls=\"manageaccess\" role=\"tab\" data-bs-toggle=\"tab\">\n                    <i class=\"fa fa-folder\"></i> Manage Reports\n                </a>\n            </li>\n            <li role=\"presentation\" class=\"nav-item\">\n                <a class=\"nav-link\" href=\"#connection\" aria-controls=\"home\" role=\"tab\" data-bs-toggle=\"tab\">\n                    <i class=\"fa fa-plug\"></i> App Settings\n                </a>\n            </li>\n        </ul>\n\n    </div>\n    <br />\n</div>\n<!-- Tab panes -->\n<div class=\"fix-content\" style=\"display: none;\" data-bind=\"visible: true\">\n    <div class=\"tab-content\">\n        <div role=\"tabpanel\" class=\"tab-pane\" id=\"usersroles\">\n            <div data-bind=\"with: usersRoles\">\n            <b>Users, Roles &amp; <span data-bind=\"text: clientIdLabel() || 'Client Id'\"></span>s</b>\n            <p>\n                Choose where Dotnet Report gets the Users, Roles and <span data-bind=\"text: clientIdLabel() || 'Client Id'\"></span>s used to control access to Reports, Folders and Dashboards.\n            </p>\n            <div class=\"d-flex align-items-center flex-wrap gap-2 mb-3\">\n                <label class=\"control-label mb-0\">Source</label>\n                <select class=\"form-select form-select-sm\" style=\"width: 240px;\" data-bind=\"value: userSource\">\n                    <option value=\"code\">Application Code</option>\n                    <option value=\"sql\">SQL Query</option>\n                    <option value=\"portal\">Dotnet Report Managed</option>\n                </select>\n                <button class=\"btn btn-primary btn-sm\" data-bind=\"visible: userSource() === 'portal', click: loadPortal\"><i class=\"fa fa-refresh\"></i> Reload</button>\n                <button class=\"btn btn-primary btn-sm\" data-bind=\"click: saveSourceSettings\"><i class=\"fa fa-save\"></i> Save</button>\n                <span class=\"text-warning\" title=\"You have unsaved changes\" data-bind=\"visible: settingsDirty\"><i class=\"fa fa-exclamation-triangle\"></i></span>\n            </div>\n            <hr />\n\n            <div class=\"alert alert-info py-2 small mb-3\" data-bind=\"visible: userSource() === 'code'\">\n                <b><i class=\"fa fa-code\"></i> Application Code</b> - Your app supplies these in <code>GetSettings()</code>, settings are displayed here but can only be managed directly in code.\n            </div>\n            <div class=\"alert alert-info py-2 small mb-3\" data-bind=\"visible: userSource() === 'sql'\">\n                <b><i class=\"fa fa-database\"></i> SQL Query</b> - Read the lists straight from your own database to populate your Users and Roles.\n            </div>\n            <div class=\"alert alert-info py-2 small mb-3\" data-bind=\"visible: userSource() === 'portal'\">\n                <b><i class=\"fa fa-cloud\"></i> Dotnet Report Managed</b> - Setup users and roles in your Dotnet Report Account. You can manage users here or on our \n                <a href=\"https://dotnetreport.com/portal/Account/UsersAndRoles\" target=\"_blank\" rel=\"noopener\">portal <i class=\"fa fa-external-link\"></i></a>.\n            </div>\n\n            <ul class=\"nav nav-tabs\" id=\"usersRolesTabs\" role=\"tablist\">\n                <li class=\"nav-item\" role=\"presentation\">\n                    <button class=\"nav-link active\" data-bs-toggle=\"tab\" data-bs-target=\"#ur-users\" type=\"button\" role=\"tab\"><i class=\"fa fa-user\"></i> Users</button>\n                </li>\n                <li class=\"nav-item\" role=\"presentation\">\n                    <button class=\"nav-link\" data-bs-toggle=\"tab\" data-bs-target=\"#ur-roles\" type=\"button\" role=\"tab\"><i class=\"fa fa-shield\"></i> Roles</button>\n                </li>\n                <li class=\"nav-item\" role=\"presentation\">\n                    <button class=\"nav-link\" data-bs-toggle=\"tab\" data-bs-target=\"#ur-clients\" type=\"button\" role=\"tab\"><i class=\"fa fa-building-o\"></i> <span data-bind=\"text: clientIdLabel() || 'Client Ids'\"></span></button>\n                </li>\n                <li class=\"nav-item\" role=\"presentation\">\n                    <button class=\"nav-link\" data-bs-toggle=\"tab\" data-bs-target=\"#ur-code\" type=\"button\" role=\"tab\"><i class=\"fa fa-sign-in\"></i> Login</button>\n                </li>\n            </ul>\n            <div class=\"tab-content pt-3\">\n                <!-- USERS -->\n                <div class=\"tab-pane active\" id=\"ur-users\" role=\"tabpanel\">\n                    <p class=\"text-muted small\">Set the currently logged in user id or email in <code>settings.UserId</code>.</p>\n                    <div data-bind=\"template: { name: 'users-roles-sql-source', data: sqlUsers }\"></div>\n                    <div class=\"alert alert-light border py-2 small\" data-bind=\"visible: userSource() === 'portal'\">\n                        <i class=\"fa fa-info-circle\"></i> Users are created here without a password, set one via <b>Forgot Password</b> email.\n                    </div>\n                    <div data-bind=\"visible: userSource() === 'portal'\">\n                        <button class=\"btn btn-primary btn-sm mb-2\" data-bind=\"click: newUser\"><i class=\"fa fa-plus\"></i> Add User</button>\n                        <div class=\"card card-body mb-3\" data-bind=\"visible: editingUser() !== null, with: editingUser\">\n                            <div class=\"row g-3\">\n                                <div class=\"col-md-3\">\n                                    <label class=\"small fw-bold\">Name</label>\n                                    <input class=\"form-control form-control-sm\" placeholder=\"Name\" data-bind=\"value: name\">\n                                </div>\n                                <div class=\"col-md-3\">\n                                    <label class=\"small fw-bold\">Email</label>\n                                    <input class=\"form-control form-control-sm\" placeholder=\"Email\" data-bind=\"value: email, enable: !id()\">\n                                </div>\n                                <div class=\"col-md-3\">\n                                    <label class=\"small fw-bold\">Roles</label>\n                                    <div data-bind=\"foreach: roles\">\n                                        <label class=\"d-block small\"><input type=\"checkbox\" data-bind=\"checked: isSelected\"> <span data-bind=\"text: text\"></span></label>\n                                    </div>\n                                    <div class=\"small text-muted\" data-bind=\"visible: roles.length === 0\">No roles defined yet</div>\n                                </div>\n                                <div class=\"col-md-3\">\n                                    <label class=\"small fw-bold\" data-bind=\"text: $parent.clientIdLabel() || 'Client Ids'\"></label>\n                                    <div data-bind=\"foreach: clients\">\n                                        <label class=\"d-block small\"><input type=\"checkbox\" data-bind=\"checked: isSelected\"> <span data-bind=\"text: text\"></span></label>\n                                    </div>\n                                    <div class=\"small text-muted\" data-bind=\"visible: clients.length === 0\">None defined yet</div>\n                                </div>\n                            </div>\n                            <div class=\"mt-3\">\n                                <button class=\"btn btn-sm btn-primary me-2\" data-bind=\"click: $parent.saveUser\">Save User</button>\n                                <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: function() { $parent.editingUser(null); }\">Cancel</button>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"text-center py-3\" data-bind=\"visible: loadingUsers\"><span class=\"fa fa-spinner fa-spin fa-2x text-muted\"></span></div>\n                    <table class=\"table table-sm align-middle\" data-bind=\"visible: !loadingUsers()\">\n                        <thead class=\"table-light\">\n                            <tr>\n                                <th>Email / Id</th>\n                                <th>Name</th>\n                                <th>Roles</th>\n                                <th data-bind=\"text: clientIdLabel() || 'Client Ids'\"></th>\n                                <th style=\"width: 130px;\"></th>\n                            </tr>\n                        </thead>\n                        <!-- ko if: userSource() === 'portal' -->\n                        <tbody data-bind=\"foreach: portalUsers\">\n                            <tr>\n                                <td data-bind=\"text: email\"></td>\n                                <td data-bind=\"text: name\"></td>\n                                <td class=\"small\" data-bind=\"text: (roles || []).join(', ')\"></td>\n                                <td class=\"small\" data-bind=\"text: $parent.clientNames(clientIds)\"></td>\n                                <td class=\"text-end text-nowrap\" style=\"width: 130px;\">\n                                    <div class=\"btn-group btn-group-sm\" role=\"group\">\n                                        <button type=\"button\" class=\"btn btn-outline-secondary\" title=\"Edit User\" data-bind=\"click: $parent.editUser\"><i class=\"fa fa-pencil\"></i></button>\n                                        <button type=\"button\" class=\"btn btn-outline-secondary\" title=\"Email a link to set their portal password\" data-bind=\"click: $parent.sendPasswordSetup\"><i class=\"fa fa-envelope-o\"></i></button>\n                                        <button type=\"button\" class=\"btn btn-outline-danger\" data-bind=\"click: $parent.deleteUser, disable: isPrimary, attr: { title: isPrimary ? 'The primary account user cannot be deleted' : 'Delete User' }\"><i class=\"fa fa-trash\"></i></button>\n                                    </div>\n                                </td>\n                            </tr>\n                        </tbody>\n                        <!-- /ko -->\n                        <!-- ko if: userSource() === 'sql' -->\n                        <tbody data-bind=\"foreach: sqlUsers.rows\">\n                            <tr>\n                                <td data-bind=\"text: id\"></td>\n                                <td data-bind=\"text: text\"></td>\n                                <td class=\"small text-muted\"></td>\n                                <td class=\"small text-muted\"></td>\n                                <td></td>\n                            </tr>\n                        </tbody>\n                        <!-- /ko -->\n                        <!-- ko if: userSource() === 'code' -->\n                        <tbody data-bind=\"foreach: codeUsers\">\n                            <tr>\n                                <td data-bind=\"text: (typeof $data === 'object') ? ($data.id || '') : $data\"></td>\n                                <td data-bind=\"text: (typeof $data === 'object') ? ($data.text || '') : ''\"></td>\n                                <td class=\"small text-muted\"></td>\n                                <td class=\"small text-muted\"></td>\n                                <td></td>\n                            </tr>\n                        </tbody>\n                        <!-- /ko -->\n                    </table>\n                    <div class=\"text-muted\" data-bind=\"visible: !loadingUsers() && userSource() === 'portal' && portalUsers().length === 0\">\n                        <i class=\"fa fa-exclamation-circle\"></i> No Users found, click <b>Add User</b> to create one.\n                    </div>\n                    <!-- ko if: userSource() === 'sql' -->\n                    <div class=\"text-muted\" data-bind=\"visible: sqlUsers.loading\"><i class=\"fa fa-spinner fa-spin\"></i> Running the Users Query...</div>\n                    <div class=\"text-danger small\" data-bind=\"visible: sqlUsers.error, text: 'Users Query error: ' + sqlUsers.error()\"></div>\n                    <div class=\"text-muted\" data-bind=\"visible: !sqlUsers.loading() && !sqlUsers.error() && sqlUsers.rows().length === 0\">\n                        <i class=\"fa fa-exclamation-circle\"></i> No Users found, add a <b>Users Query</b> above.\n                    </div>\n                    <div class=\"text-muted small\" data-bind=\"visible: sqlUsers.rows().length > 0\">\n                        <span data-bind=\"text: sqlUsers.rows().length\"></span> users returned by the Users Query.\n                    </div>\n                    <!-- /ko -->\n                    <div class=\"text-muted\" data-bind=\"visible: !loadingUsers() && userSource() === 'code' && codeUsers().length === 0\">\n                        <i class=\"fa fa-exclamation-circle\"></i> No Users found, populate <code>settings.Users</code> in your code.\n                    </div>\n                </div>\n                <!-- ROLES -->\n                <div class=\"tab-pane\" id=\"ur-roles\" role=\"tabpanel\">\n                    <p class=\"text-muted small\">Set the currently logged in user role in <code>settings.CurrentUserRole</code>.</p>\n                    <div data-bind=\"template: { name: 'users-roles-sql-source', data: sqlRoles }\"></div>\n                    <!-- ko if: userSource() === 'portal' -->\n                    <div class=\"input-group input-group-sm mb-3\" style=\"max-width: 320px;\">\n                        <input class=\"form-control\" placeholder=\"New role name\" data-bind=\"value: newRoleName\">\n                        <button class=\"btn btn-primary btn-sm\" data-bind=\"click: addRole\"><i class=\"fa fa-plus\"></i> Add Role</button>\n                    </div>\n                    <!-- /ko -->\n                    <!-- ko if: userSource() === 'portal' -->\n                    <div class=\"d-flex flex-wrap gap-2\">\n                        <!-- ko foreach: portalRoles -->\n                        <span class=\"badge bg-light text-dark border py-2 d-inline-flex align-items-center\">\n                            <span data-bind=\"text: text\"></span>\n                            <button type=\"button\" class=\"btn btn-sm btn-link text-danger p-0 ms-2 lh-1\" title=\"Delete Role\" data-bind=\"click: $parent.deleteRole\"><i class=\"fa fa-times\"></i></button>\n                        </span>\n                        <!-- /ko -->\n                    </div>\n                    <div class=\"text-muted\" data-bind=\"visible: portalRoles().length === 0\"><i class=\"fa fa-exclamation-circle\"></i> No Roles found, add one above.</div>\n                    <!-- /ko -->\n                    <!-- ko if: userSource() === 'sql' -->\n                    <div class=\"d-flex flex-wrap gap-2\">\n                        <!-- ko foreach: sqlRoles.rows -->\n                        <span class=\"badge bg-light text-dark border py-2\" data-bind=\"text: text\"></span>\n                        <!-- /ko -->\n                    </div>\n                    <div class=\"text-muted\" data-bind=\"visible: sqlRoles.loading\"><i class=\"fa fa-spinner fa-spin\"></i> Running the Roles Query...</div>\n                    <div class=\"text-danger small\" data-bind=\"visible: sqlRoles.error, text: 'Roles Query error: ' + sqlRoles.error()\"></div>\n                    <div class=\"text-muted\" data-bind=\"visible: !sqlRoles.loading() && !sqlRoles.error() && sqlRoles.rows().length === 0\">\n                        <i class=\"fa fa-exclamation-circle\"></i> No Roles found, add a <b>Roles Query</b> above.\n                    </div>\n                    <!-- /ko -->\n                    <!-- ko if: userSource() === 'code' -->\n                    <div class=\"d-flex flex-wrap gap-2\">\n                        <!-- ko foreach: codeRoles -->\n                        <span class=\"badge bg-light text-dark border py-2\" data-bind=\"text: $data\"></span>\n                        <!-- /ko -->\n                    </div>\n                    <div class=\"text-muted\" data-bind=\"visible: codeRoles().length === 0\"><i class=\"fa fa-exclamation-circle\"></i> No Roles found, populate <code>settings.UserRoles</code> in your code.</div>\n                    <!-- /ko -->\n                </div>\n\n                <!-- CLIENT IDS -->\n                <div class=\"tab-pane\" id=\"ur-clients\" role=\"tabpanel\">\n                    <p class=\"text-muted small\">Restrict Reports, Folders and Dashboards by <span data-bind=\"text: (clientIdLabel() || 'Client Id').toLowerCase()\"></span>, set the currently logged in user's <span data-bind=\"text: (clientIdLabel() || 'Client Id').toLowerCase()\"></span> in <code>settings.ClientId</code>.</p>\n                    <div data-bind=\"template: { name: 'users-roles-sql-source', data: sqlClients }\"></div>\n                    <div class=\"alert alert-warning py-2 small\" data-bind=\"visible: userSource() === 'portal'\">\n                        <i class=\"fa fa-exclamation-triangle\"></i> Clients are not stored in your Dotnet Report account.\n                        Keep managing them here, or switch the source to SQL Query or Application Code.\n                    </div>\n                    <div class=\"mb-3 d-flex align-items-center gap-2 small\">\n                        <!-- ko ifnot: editingLabel -->\n                        <span class=\"text-muted\">Called</span>\n                        <b data-bind=\"text: clientIdLabel() || 'Client Id'\"></b>\n                        <span class=\"text-muted\">across the app.</span>\n                        <button type=\"button\" class=\"btn btn-sm btn-link p-0\" title=\"Change this wording\" data-bind=\"click: startEditLabel\"><i class=\"fa fa-pencil\"></i> Change</button>\n                        <!-- /ko -->\n                        <!-- ko if: editingLabel -->\n                        <input class=\"form-control form-control-sm\" style=\"width: 200px;\" placeholder=\"Client Id / Tenant\" data-bind=\"value: labelDraft, hasFocus: true\">\n                        <button type=\"button\" class=\"btn btn-sm btn-primary\" data-bind=\"click: applyLabel\">Save</button>\n                        <button type=\"button\" class=\"btn btn-sm btn-secondary\" data-bind=\"click: cancelLabel\">Cancel</button>\n                        <!-- /ko -->\n                    </div>\n\n                    <!-- ko if: userSource() === 'portal' -->\n                    <button class=\"btn btn-primary btn-sm mb-2\" data-bind=\"click: newClient\"><i class=\"fa fa-plus\"></i> Add <span data-bind=\"text: clientIdLabel() || 'Client Id'\"></span></button>\n                    <div class=\"card card-body mb-3\" style=\"max-width: 520px;\" data-bind=\"visible: editingClient() !== null, with: editingClient\">\n                        <div class=\"row g-3\">\n                            <div class=\"col-md-6\">\n                                <label class=\"small fw-bold\">Id</label>\n                                <input class=\"form-control form-control-sm\" placeholder=\"ACME\" data-bind=\"value: id, enable: !original\">\n                                <div class=\"form-text\">The value your app passes as <code>settings.ClientId</code>.</div>\n                            </div>\n                            <div class=\"col-md-6\">\n                                <label class=\"small fw-bold\">Display Name</label>\n                                <input class=\"form-control form-control-sm\" placeholder=\"Acme Corporation\" data-bind=\"value: text\">\n                                <div class=\"form-text\">Optional, defaults to the Id.</div>\n                            </div>\n                        </div>\n                        <div class=\"mt-3\">\n                            <button class=\"btn btn-sm btn-primary me-2\" data-bind=\"click: $parent.saveClient, text: original ? 'Save' : 'Add'\">Add</button>\n                            <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parent.cancelClient\">Cancel</button>\n                        </div>\n                    </div>\n                    <label class=\"form-label mb-1\"></label>\n                    <table class=\"table table-sm align-middle\" style=\"max-width: 520px;\" data-bind=\"visible: clientIds().length > 0\">\n                        <thead class=\"table-light\"><tr><th>Id</th><th>Display Name</th><th></th></tr></thead>\n                        <tbody data-bind=\"foreach: clientIds\">\n                            <tr>\n                                <td data-bind=\"text: $parent.clientKey($data)\"></td>\n                                <td data-bind=\"text: $parent.clientText($data)\"></td>\n                                <td class=\"text-end text-nowrap\" style=\"width: 90px;\">\n                                    <div class=\"btn-group btn-group-sm\" role=\"group\">\n                                        <button type=\"button\" class=\"btn btn-outline-secondary\" title=\"Edit\" data-bind=\"click: function() { $parent.editClient($data); }\"><i class=\"fa fa-pencil\"></i></button>\n                                        <button type=\"button\" class=\"btn btn-outline-danger\" title=\"Remove\" data-bind=\"click: function() { $parent.removeClientId($data); }\"><i class=\"fa fa-trash\"></i></button>\n                                    </div>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                    <div class=\"text-muted mb-3\" data-bind=\"visible: clientIds().length === 0\"><i class=\"fa fa-exclamation-circle\"></i> None added yet.</div>\n\n                    <!-- /ko -->\n\n                    <!-- ko if: userSource() === 'sql' -->\n                    <label class=\"form-label mb-1\">Current <span data-bind=\"text: clientIdLabel() || 'Client Ids'\"></span> <span class=\"text-muted fw-normal small\">from your query</span></label>\n                    <div class=\"d-flex flex-wrap gap-2\">\n                        <!-- ko foreach: sqlClients.rows -->\n                        <span class=\"badge bg-light text-dark border py-2\" data-bind=\"text: text\"></span>\n                        <!-- /ko -->\n                    </div>\n                    <div class=\"text-muted\" data-bind=\"visible: sqlClients.loading\"><i class=\"fa fa-spinner fa-spin\"></i> Running the Clients Query...</div>\n                    <div class=\"text-danger small\" data-bind=\"visible: sqlClients.error, text: 'Clients Query error: ' + sqlClients.error()\"></div>\n                    <div class=\"text-muted\" data-bind=\"visible: !sqlClients.loading() && !sqlClients.error() && sqlClients.rows().length === 0\">\n                        <i class=\"fa fa-exclamation-circle\"></i> No <span data-bind=\"text: clientIdLabel() || 'Client Ids'\"></span> found, add a <b>Clients Query</b> above.\n                    </div>\n                    <!-- /ko -->\n\n                    <!-- ko if: userSource() === 'code' -->\n                    <label class=\"form-label mb-1\">Current <span data-bind=\"text: clientIdLabel() || 'Client Ids'\"></span> <span class=\"text-muted fw-normal small\">from your code</span></label>\n                    <div class=\"d-flex flex-wrap gap-2\">\n                        <!-- ko foreach: codeClientIds -->\n                        <span class=\"badge bg-light text-dark border py-2\" data-bind=\"text: (typeof $data === 'object') ? ($data.text || $data.id) : $data\"></span>\n                        <!-- /ko -->\n                    </div>\n                    <div class=\"text-muted\" data-bind=\"visible: codeClientIds().length === 0\"><i class=\"fa fa-exclamation-circle\"></i> No <span data-bind=\"text: clientIdLabel() || 'Client Ids'\"></span> found, populate <code>settings.ClientIds</code> in your code.</div>\n                    <!-- /ko -->\n                </div>\n                <!-- SETUP CODE -->\n                <div class=\"tab-pane\" id=\"ur-code\" role=\"tabpanel\">\n                    <div class=\"card mb-3\" data-bind=\"css: { 'border-primary': loginMode() === 'embedded' }\">\n                        <div class=\"card-body py-3\">\n                            <div>\n                                <label class=\"form-check-label\">\n                                    <b><i class=\"fa fa-code\"></i> Embedded in your app <span class=\"badge bg-secondary ms-1\">Default</span></b>\n                                    <div class=\"small text-muted\">Your application already has a login. Dotnet Report runs inside it and trusts it, you specify who is signed in from C# and switch on <code>[Authorize]</code>.</div>\n                                    <div class=\"small mt-1\"><span class=\"text-muted\">Works with:</span> any source</div>\n                                </label>\n                            </div>\n                            <!-- ko if: loginMode() === 'embedded' -->\n                            <div class=\"mt-3 ps-4\">\n                                <div class=\"alert alert-warning py-2 small mb-2\">\n                                    <i class=\"fa fa-exclamation-triangle\"></i> <b>Turn authorization on.</b> <code>[Authorize]</code> ships commented out on\n                                    <code>DotNetReportController</code> and <code>DotNetReportApiController</code>, and <code>[Authorize(Roles = \"Administrator\")]</code> on\n                                    <code>DotNetSetupController</code>, so the default runs without a login. Uncomment them so only signed-in users reach reports\n                                    and only administrators reach this page.\n                                </div>\n                                <p class=\"text-muted small mb-1\">Tell Dotnet Report who is signed in, from <code>GetSettings()</code> in <code>Controllers/DotNetReportApiController.cs</code>:</p>\n                                <pre class=\"bg-light border rounded p-3 small mb-0\">\n                                settings.UserId          = User.Identity.Name;                          // currently logged in user\n                                settings.CurrentUserRole = new List&lt;string&gt; { \"Admin\" };          // currently logged in user's roles\n                                settings.ClientId        = \"ACME\";                                      // currently logged in user's tenant\n                                <!-- ko if: userSource() === 'code' -->\n                                settings.Users     = new List&lt;dynamic&gt; { \"jane@co.com\", \"joe@co.com\" }; // all users\n                                settings.UserRoles = new List&lt;string&gt; { \"Admin\", \"Viewer\" };            // all roles\n                                settings.ClientIds = new List&lt;string&gt; { \"ACME\", \"CONTOSO\" };            // all tenants<!-- /ko --></pre>\n                            </div>\n                            <!-- /ko -->\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n        </div>\n        <div role=\"tabpanel\" class=\"tab-pane\" id=\"connection\">\n            <b>Manage Data Connection</b>\n            <p>\n                Data Connection groups data schemas (including tables and stored procedures and other configuration), Reports, and Dashboards into a single environment. You can create multiple Data Connections and easily switch between them for separate environment management.\n            </p>\n            <hr />\n            <div class=\"form-row\" data-bind=\"visible: true\">\n                <div class=\"form-group\">\n                    <div class=\"control-group\">\n                        <select class=\"form-select\" style=\"width:25%\" data-bind=\"options: DataConnections, optionsText: 'DataConnectName', optionsValue: 'DataConnectGuid', value: currentConnectionKey\"></select>\n                        <div class=\"padded-top\"></div>\n                        <button class=\"btn btn-primary btn-sm\" data-bind=\"visible: false\" data-bs-toggle=\"modal\" data-bs-target=\"#connection-setup-modal\">Manage DB Connection</button>\n                        <button class=\"btn btn-primary btn-sm\" data-bind=\"click: switchConnection, visible: canSwitchConnection\">Switch Connection</button>\n                        <button class=\"btn btn-primary btn-sm\" data-bind=\"click: editDataConnectionModal, hidden: canSwitchConnection\" data-bs-toggle=\"modal\" data-bs-target=\"#add-connection-modal\">Edit Connection</button>\n                        <button class=\"btn btn-primary btn-sm\" data-bind=\"click: newDataConnectionModal\" data-bs-toggle=\"modal\" data-bs-target=\"#add-connection-modal\">Add New Connection</button>\n                        <button class=\"btn btn-primary btn-sm\" data-bind=\"click: exportAll, visible: false\">Export Connection</button>\n                        <button class=\"btn btn-primary btn-sm\" data-bind=\"click: importStart, visible: false\">Import Connection</button>\n                    </div>\n                    <div data-bind=\"visible: importingFile\">\n                        <br />\n                        <div class=\"alert alert-info\">\n                            Please select a file you have previously exported from this utility. The system will load the screen with the Data Connection setting in the file, however, it will <b>NOT</b> be saved until you press the Save All button or Save individual tables\n                            <br />\n                            <div class=\"input-group\">\n                                <input type=\"file\" accept=\".json\" id=\"import-file\" data-bind=\"event: { change: function() { importFile($element.files[0]) } }\" />\n                                <span class=\"input-group-btn\">\n                                    <button class=\"btn btn-link\" data-bind=\"click: importCancel\">Cancel</button>\n                                </span>\n                            </div>\n\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <br />\n            <br />\n            <div class=\"card\">\n                <div class=\"card-header\">\n                    <b>Account Level Settings</b>\n                </div>\n                <div class=\"card-body\">\n                    <div data-bind=\"with: settings\">\n                        <div class=\"row\">\n                            <div class=\"col-md-6\">\n                                <h6 class=\"mt-2 mb-2\">Admin Options</h6>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" id=\"useClientIdInAdmin\" data-bind=\"checked: useClientIdInAdmin\">\n                                    <label class=\"form-check-label\" for=\"useClientIdInAdmin\">Use Client ID in Admin mode</label>\n                                    <small class=\"text-muted d-block\">Enable this to respect client IDs even when in admin mode.</small>\n                                </div>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" id=\"useSqlBuilderInAdminMode\" data-bind=\"checked: useSqlBuilderInAdminMode\">\n                                    <label class=\"form-check-label\" for=\"useSqlBuilderInAdminMode\">Use SQL Builder in Admin Mode</label>\n                                    <small class=\"text-muted d-block\">Allows SQL query builder access <b>only</b> in admin mode.</small>\n                                </div>\n                                <h6 class=\"mt-3 mb-2\">Customization</h6>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" id=\"useSqlCustomField\" data-bind=\"checked: useSqlCustomField\">\n                                    <label class=\"form-check-label\" for=\"useSqlCustomField\">Use SQL in Custom Field</label>\n                                    <small class=\"text-muted d-block\">Allows the use of SQL expressions in custom fields.</small>\n                                </div>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: showDesignerHints\">\n                                    <label class=\"form-check-label\">Show Designer Tips &amp; Guidance</label>\n                                    <small class=\"text-muted d-block\">Display contextual tips and explanations throughout the report designer to help users understand available options.</small>\n                                </div>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: useAltPivot\">\n                                    <label class=\"form-check-label\">Pivot with Drilldown</label>\n                                    <small class=\"text-muted d-block\">Use alternate Pivot method that doesn’t use SQL’s PIVOT.<br>Allows drilldown, but may be slower.</small>\n                                </div>\n                                <div class=\"form-check\" data-bind=\"visible: isEnterprise\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: useFunctions\">\n                                    <label class=\"form-check-label\">Use Functions</label>\n                                    <small class=\"text-muted d-block\">\n                                        Enable calculated functions for List reports only.<br>\n                                        Available for Enterprise license users.\n                                    </small>\n                                </div>\n                                <div class=\"mb-2 mt-2\">\n                                    <label class=\"form-label mb-1\" for=\"defaultDateFormatSelect\">Default Date Format</label>\n                                    <select class=\"form-select form-select-sm\" id=\"defaultDateFormatSelect\" style=\"max-width: 220px;\"\n                                            data-bind=\"options: dateFormatOptions, value: defaultDateFormat\"></select>\n                                    <small class=\"text-muted d-block\">Date format used by all date pickers when a field doesn't override it. e.g. <em>New Zealand</em> uses <code>dd/mm/yyyy</code>.</small>\n                                </div>\n                                <h6 class=\"mt-3 mb-2\">Report Options</h6>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" id=\"allowUsersToCreateReports\" data-bind=\"checked: allowUsersToCreateReports\">\n                                    <label class=\"form-check-label\" for=\"allowUsersToCreateReports\">Allow All Users to Create Reports</label>\n                                    <small class=\"text-muted d-block\">Permits users to generate and customize reports.</small>\n                                </div>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" id=\"allowUsersToCreateDashboards\" data-bind=\"checked: allowUsersToCreateDashboards\">\n                                    <label class=\"form-check-label\" for=\"allowUsersToCreateDashboards\">Allow All Users to Create Dashboards</label>\n                                    <small class=\"text-muted d-block\">Permits users to generate and customize dashboards.</small>\n                                </div>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: showImportExport\">\n                                    <label class=\"form-check-label\">Allow All Users to export/import reports</label>\n                                    <small class=\"text-muted d-block\">\n                                        Allow non admin users to export and import Reports in the system.\n                                    </small>\n                                </div>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: canCopyReport\">\n                                    <label class=\"form-check-label\">Always allow users to copy reports</label>\n                                    <small class=\"text-muted d-block\">\n                                        Allow users with View Only access to copy Reports in the system.\n                                    </small>\n                                </div>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: showScheduling\">\n                                    <label class=\"form-check-label\">Hide Report/Dashboard Scheduling</label>\n                                    <small class=\"text-muted d-block\">\n                                        Removes scheduling in reports and dashboard, select only if you don't want to use scheduling feature.\n                                    </small>\n                                </div>\n                            </div>\n                            <div class=\"col-md-6\">\n                                <h6 class=\"mt-2 mb-2\">Folder Options</h6>\n                                <div class=\"form-check\" data-bind=\"visible: false\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" id=\"noFolders\" data-bind=\"checked: noFolders\">\n                                    <label class=\"form-check-label\" for=\"noFolders\">No Folders</label>\n                                    <small class=\"text-muted d-block\">Disables the use of folders in the application.</small>\n                                </div>\n                                <div class=\"form-check\" data-bind=\"visible: false\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" id=\"noDefaultFolder\" data-bind=\"checked: noDefaultFolder\">\n                                    <label class=\"form-check-label\" for=\"noDefaultFolder\">No Default Folder</label>\n                                    <small class=\"text-muted d-block\">Removes the Default folder.</small>\n                                </div>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: showEmptyFolders\">\n                                    <label class=\"form-check-label\">Show Empty Folders</label>\n                                    <small class=\"text-muted d-block\">Will show empty folders for non admin users.</small>\n                                </div>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" id=\"allowUsersToManageFolders\" data-bind=\"checked: allowUsersToManageFolders\">\n                                    <label class=\"form-check-label\" for=\"allowUsersToManageFolders\">Allow All Users to Manage Folders</label>\n                                    <small class=\"text-muted d-block\">Grants permission to organize and manage folders without admin mode.</small>\n                                </div>\n                                <h6 class=\"mt-3 mb-2\">Export Options</h6>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: useAltPdf\">\n                                    <label class=\"form-check-label\">PDF Export without Chromium</label>\n                                    <small class=\"text-muted d-block\">Use alternate PDF export method that doesn’t rely on Chromium.</small>\n                                </div>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: dontXmlExport\">\n                                    <label class=\"form-check-label\">Hide XML Export option</label>\n                                    <small class=\"text-muted d-block\">Remove XML Export option.</small>\n                                </div>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: dontWordExport\">\n                                    <label class=\"form-check-label\">Hide Word Export option</label>\n                                    <small class=\"text-muted d-block\">Remove Word Export option.</small>\n                                </div>\n                                <div class=\"form-check\">\n                                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: showPageSize\">\n                                    <label class=\"form-check-label\">Show Page Size on PDF & Word export</label>\n                                    <small class=\"text-muted d-block\">Display document dimensions in exported PDF & Word.</small>\n                                </div>\n\n                                <h6 class=\"mt-3 mb-2\">AI Assistant <span class=\"badge bg-warning text-dark\" style=\"font-size: 10px;\">BETA</span></h6>\n                                <div class=\"mb-2\">\n                                    <div class=\"form-check form-switch\">\n                                        <input class=\"form-check-input\" type=\"checkbox\" role=\"switch\" id=\"aiEnabledSwitch\"\n                                               data-bind=\"checked: aiEnabled\">\n                                        <label class=\"form-check-label\" for=\"aiEnabledSwitch\">Enable AI Report Assistant</label>\n                                    </div>\n                                    <small class=\"text-muted d-block\">When enabled, an AI-powered assistant will be available in the report designer to help build reports using natural language.</small>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"mt-3\">\n                            <button type=\"button\" id=\"saveAppSettings\" class=\"btn btn-primary\" data-bind=\"click: saveAppSettings\">Save</button>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div role=\"tabpanel\" class=\"tab-pane active\" id=\"tablesfields\">\n            <b data-bind=\"text: customTableMode() ? 'Custom Tables' : 'Database Tables'\"></b>\n            <p>\n                <span data-bind=\"visible: $root.customTableMode\">\n                    Define Custom Tables using SQL Select Query to use in Dotnet Report for Reporting and Analytics.\n                </span>\n                <span data-bind=\"hidden: $root.customTableMode\">\n                    Select Tables or Views from your Database to use in Dotnet Report for Reporting and Analytics.\n                </span>\n            </p>\n\n            <div data-bind=\"with: Tables\">\n                <input type=\"text\" class=\"form-control input-sm\" placeholder=\"Filter Tables...\" data-bind=\"value: tableFilter, valueUpdate: 'afterkeydown'\" style=\"float: left; width: 180px; margin-right: 5px;\">\n                <button class=\"btn btn-outline-secondary btn-sm\" data-bind=\"click: clearTableFilter,  visible: tableFilter()!='' && tableFilter()!=null\"><span class=\"fa fa-remove\"></span></button>\n                <button class=\"btn btn-outline-secondary btn-sm\" data-bind=\"click: toggleShowAll, hidden: $root.customTableMode() || $root.onlyApi(), text: usedOnly() ? 'Show all' : 'Show used only'\">Show used only</button>\n                <button class=\"btn btn-sm btn-primary\" data-bind=\"click: $root.customSql.addNewCustomSqlTable, visible: $root.customTableMode\">Add New Custom Table</button>\n                <button class=\"btn btn-sm btn-primary\" data-bind=\"click: $root.loadFromDatabase, hidden: $root.customTableMode() || !$root.onlyApi()\">\n                    <span class=\"fa fa-database\"></span> Load all Database Tables\n                </button>\n                <button class=\"btn btn-sm btn-primary\" data-bind=\"click: $root.visualizeJoins\"><span class=\"fa fa-arrows-h\"></span> Visualize Joins</button>\n                <button class=\"btn btn-sm btn-primary\" title=\"Manage Categories\" data-bs-toggle=\"modal\" data-bs-target=\"#category-modal\">\n                    <span class=\"fa fa-server\"></span> Manage Categories\n                </button>\n                <div class=\"btn-group btn-group-sm\" role=\"group\">\n                    <button type=\"button\" class=\"btn btn-primary dropdown-toggle\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">\n                        <span class=\"fa fa-exchange\"></span> Import / Export\n                    </button>\n                    <ul class=\"dropdown-menu\">\n                        <li>\n                            <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { exportTablesJson(true) }, visible: $root.customTableMode\">\n                                <span class=\"fa fa-download\"></span> Export Custom Tables\n                            </a>\n                            <a class=\"dropdown-item\" href=\"#\" data-bind=\"click: function() { exportTablesJson(false) }, visible: !$root.customTableMode()\">\n                                <span class=\"fa fa-download\"></span> Export Tables/Views\n                            </a>\n                        </li>\n                        <li>\n                            <a class=\"dropdown-item\" href=\"#\" data-bs-toggle=\"modal\" data-bs-target=\"#uploadTablesFileModal\">\n                                <span class=\"fa fa-upload\"></span> Import Tables/Views\n                            </a>\n                        </li>\n                    </ul>\n                </div>\n                <button type=\"button\" class=\"btn btn-sm btn-outline-secondary\"\n                        data-bind=\"click: function() { toggleSelectAll($root.customTableMode()) },\n                            text: allSelected($root.customTableMode()) ? 'UnSelect All' : 'Select All'\">Select All</button>\n                <button class=\"btn btn-sm btn-primary\" title=\"Saves the tables that are checked\" data-bind=\"click: function() { $root.saveChanges($root.customTableMode()) }\">\n                    <span class=\"fa fa-floppy\"></span> Save Selected Tables\n                </button>\n            </div>\n            <div class=\"clearfix\"></div>\n            <hr />\n\n            <div class=\"row\">\n                <div class=\"col-12 col-md-4 col-lg-3 border-end\" style=\"height: 100vh; overflow-y: auto;\">\n\n                    <div class=\"row\">\n                        <div data-bind=\"ifnot: $root.customTableMode\">\n                            <div class=\"alert alert-info\">\n                                <span data-bind=\"text: Tables.model().filter(t => !t.CustomTable()).length\"></span> Tables/Views\n                                <span data-bind=\"text: $root.onlyApi() ? 'configured and used' : 'read from database'\"></span>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"menu g-3\" data-bind=\"foreach: pagedTables\">\n                        <div class=\"menu-category card\">\n                            <div class=\"card-header clearfix\">\n                                <div class=\"checkbox float-start\">\n                                    <label>\n                                        <input type=\"checkbox\" data-bind=\"checked: Selected\" title=\"Check to use in Dotnet Report, uncheck to Remove\">\n                                        <span data-bind=\"text: TableName, attr: { title: TableName }, click: function() { $root.activeTable($data); }\" class=\"table-name-label\" style=\"cursor: pointer\"></span>\n                                        <span data-bind=\"visible: SchemaName, text: SchemaName\" title=\"schema\" class=\"text-muted small\"></span>\n                                        <span data-bind=\"visible: IsView\" class=\"label label-sm\">(view)</span>\n                                    </label>\n                                    <button class=\"btn btn-sm\" title=\"Save this Table\" data-bind=\"click: function() { saveTable($root.keys.AccountApiKey, $root.keys.DatabaseApiKey); }\">\n                                        <i class=\"fas fa-save\"></i>\n                                    </button>\n                                    <button class=\"btn btn-sm\" title=\"Preview this Table\" data-bind=\"click: function() { previewTable($root.keys.AccountApiKey, $root.keys.DatabaseApiKey); }\">\n                                        <i class=\"fa fa-table\"></i>\n                                    </button>\n                                </div>\n                                <a class=\"float-end\" data-bind=\"click: function() { $root.activeTable($data); }\">\n                                    <span class=\"fa fa-chevron-right\" style=\"cursor: pointer\"></span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"row mt-3\">\n                        <div class=\"d-flex flex-column col-md-12\" data-bind=\"with: pager\">\n                            <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                            <div class=\"text-muted small mt-0 pt-0\" style=\"padding-left: 3px\" data-bind=\"text: 'Total Records: ' + totalRecords()\"></div>\n                        </div>\n                    </div>\n                </div>\n\n                <div class=\"col-12 col-md-8 col-lg-9\" id=\"tableDetails\">\n                    <div data-bind=\"visible: pagedTables().length === 0\">\n                        <br />\n                        <svg style=\"width:40px;float:left;transform:rotate(-45deg) translateY(6px);transform-origin:center center;\" fill=\"#000000\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\" class=\"icon flat-line\"><g stroke-width=\"0\"></g><g stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke=\"#CCCCCC\" stroke-width=\"0.048\"></g><g><path d=\"M18,21A13.17,13.17,0,0,1,9,8.51V3\" style=\"fill:none;stroke:#000000;stroke-linecap:round;stroke-linejoin:round;stroke-width:2;\"></path><polyline points=\"12 6 9 3 6 6\" style=\"fill:none;stroke:#000000;stroke-linecap:round;stroke-linejoin:round;stroke-width:2;\"></polyline></g></svg>\n                        <div class=\"mt-3 fw-bold\" style=\"float:left; padding-left: 5px;\">No <span data-bind=\"visible: $root.customTableMode\">Custom </span> Tables added yet, click \"<span data-bind=\"text: customTableMode() ? 'Add New Custom Table' : 'Load All Tables'\"></span>\" to get started!</div>\n                    </div>\n\n                    <div data-bind=\"visible: !activeTable() && pagedTables().length > 0\">\n                        <br />\n                        <br />\n                        <svg style=\"width:40px;float:left;transform:rotate(-45deg) translateY(6px);transform-origin:center center;\" fill=\"#000000\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\" class=\"icon flat-line\"><g stroke-width=\"0\"></g><g stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke=\"#CCCCCC\" stroke-width=\"0.048\"></g><g><path d=\"M18,21A13.17,13.17,0,0,1,9,8.51V3\" style=\"fill:none;stroke:#000000;stroke-linecap:round;stroke-linejoin:round;stroke-width:2;\"></path><polyline points=\"12 6 9 3 6 6\" style=\"fill:none;stroke:#000000;stroke-linecap:round;stroke-linejoin:round;stroke-width:2;\"></polyline></g></svg>\n                        <div class=\"mt-3 fw-bold\" style=\"float:left; padding-left: 5px;\">Select a <span data-bind=\"visible: $root.customTableMode\">Custom </span> Table, or \"<span data-bind=\"text: customTableMode() ? 'Add New Custom Table' : 'Load All Tables'\"></span>\"</div>\n                    </div>\n\n                    <div data-bind=\"with: activeTable\">\n                        <div class=\"card my-3\">\n                            <div class=\"card-header\">\n                                <h5>\n                                    <input type=\"checkbox\" data-bind=\"checked: Selected\" title=\"Check to use in Dotnet Report, uncheck to Remove\">\n                                    <span data-bind=\"text: TableName\"></span>\n                                    <span data-bind=\"visible: IsView\" class=\"label-sm\">(view)</span>\n                                </h5>\n                                <button class=\"btn btn-sm\" title=\"Save this Table\" data-bind=\"click: function() { saveTable($root.keys.AccountApiKey, $root.keys.DatabaseApiKey); }\">\n                                    <i class=\"fas fa-save\"></i> Save Changes\n                                </button>\n                                <button class=\"btn btn-sm\" title=\"Preview this Table\" data-bind=\"click: function() { previewTable($root.keys.AccountApiKey, $root.keys.DatabaseApiKey); }\">\n                                    <i class=\"fa fa-table\"></i> Preview Data\n                                </button>\n                                <button class=\"btn btn-sm btn-danger\" title=\"Delete this Table\" data-bind=\"click: function() { deleteTable($root.keys.AccountApiKey, $root.keys.DatabaseApiKey); }\">\n                                    <i class=\"fa fa-trash\"></i> Remove Table\n                                </button>\n                            </div>\n                            <div class=\"card-body\">\n                                <p class=\"float-end\">\n                                    <button class=\"btn btn-sm\" title=\"Manage Category\" data-bs-toggle=\"modal\" data-bs-target=\"#category-manage-modal\" data-bind=\"click: $root.selectedCategory\">\n                                        <i class=\"fa fa-gear\"></i>\n                                    </button>\n                                    <button class=\"btn btn-sm\" title=\"Manage Role Access\" data-bs-toggle=\"modal\" data-bs-target=\"#role-access-modal\" data-bind=\"click: $root.selectAllowedRoles\">\n                                        <i class=\"fa fa-user\"></i>\n                                    </button>\n                                    <button class=\"btn btn-sm\" title=\"Export this Table\" data-bind=\"click: function() { exportTableJson(); }\">\n                                        <i class=\"fa fa-file\"></i>\n                                    </button>\n                                </p>\n                                <p>\n                                    <label class=\"label-sm\">Display Name</label><br />\n                                    <span data-bind=\"editable: DisplayName\"></span>\n                                </p>\n                                <p>\n                                    <label class=\"label-sm\">Schema Name</label><br />\n                                    <span data-bind=\"editable: SchemaName\"></span>\n                                </p>\n                                <p style=\"display: none;\">\n                                    <!-- deprecated -->\n                                    <label class=\"label-sm\">Account Id Field</label><br />\n                                    <span data-bind=\"editable: AccountIdField\"></span>\n                                </p>\n                                <div class=\"checkbox\">\n                                    <label>\n                                        <input class=\"check-box\" data-val=\"true\" type=\"checkbox\" value=\"true\" data-bind=\"checked: DoNotDisplay\">\n                                        Do Not Display\n                                    </label>\n                                </div>\n                                <div data-bind=\"if: CustomTable\">\n                                    <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $root.customSql.viewCustomSql.bind($data)\">View Custom SQL</button>\n                                </div>\n\n                                <div class=\"d-flex align-items-center justify-content-end gap-2\">\n                                    <button class=\"btn btn-sm btn-primary\"\n                                            data-bind=\"click: addNewColumn, visible: false\">\n                                        <i class=\"fa fa-plus\"></i> Add Column\n                                    </button>\n                                    <label class=\"label-sm m-0\"><span data-bind=\"text: Columns().length\"></span> Columns</label>\n                                    <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: autoFormat, visible: Selected\">Auto Format</button>\n                                    <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: autoSort, visible: Selected\">Auto Sort</button>\n                                    <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: unselectAllColumns, visible: Selected\">Unselect All</button>\n                                    <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: selectAllColumns, visible: Selected\">Select All</button>\n                                </div>\n                            </div>\n\n                            <div class=\"list-group\" data-bind=\"sortable: { data: Columns, options: { handle: '.sortable', cursor: 'move' }, afterMove: $root.Tables.columnSorted }\">\n                                <div class=\"list-group-item\">\n                                    <div data-bind=\"if: $parent.DynamicColumns()\">\n                                        <span data-bind=\"html: DisplayName, attr: { title: 'DB field is ' + ColumnName() }\"></span>\n                                    </div>\n                                    <div class=\"checkbox\" data-bind=\"if: !$parent.DynamicColumns()\">\n                                        <label>\n                                            <input type=\"checkbox\" data-bind=\"checked: Selected, enable: $parent.Selected()\">\n                                            <span data-bind=\"editable: DisplayName, attr: { title: 'DB field is ' + ColumnName() }\"></span>\n                                            <span class=\"badge text-bg-info text-white\" data-bind=\"text: FieldType\"></span>\n                                            <label data-bind=\"visible: PrimaryKey\" class=\"badge text-bg-primary\">Primary</label>\n                                            <label data-bind=\"visible: ForeignKey\" class=\"badge text-bg-info text-white\">Foreign</label>\n                                            <label class=\"badge text-bg-warning\" data-bind=\"visible: isNew\">New</label>\n                                        </label>\n                                        <button class=\"btn btn-sm float-end\" data-bs-toggle=\"modal\" data-bs-target=\"#column-modal\" title=\"All column options\" data-bind=\"click: $root.selectColumn.bind($data, false)\">...</button>\n                                        <div class=\"btn btn-sm float-end sortable\">\n                                            <span class=\"fa fa-arrows\" aria-hidden=\"true\" title=\"Drag to reorder\"></span>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n        <div role=\"tabpanel\" class=\"tab-pane\" id=\"relations\">\n            <b>Relations</b>\n            <p>\n                Setup your Database Relations for Dotnet Report to produce dynamic queries\n            </p>\n            <button class=\"btn btn-sm btn-primary\" data-bind=\"click: AddAllRelations\"><span class=\"fa fa-magic\"></span> Auto Add Joins</button>\n            <button class=\"btn btn-sm btn-primary\" data-bind=\"click: AddJoin\"><span class=\"fa fa-plus\"></span> Add new Join</button>&nbsp;\n            <button class=\"btn btn-sm btn-primary\" data-bind=\"click: SaveJoins\"><span class=\"fa fa-floppy-o\"></span> Save Joins</button>&nbsp;\n            <button class=\"btn btn-sm btn-primary\" data-bind=\"click: visualizeJoins\"><span class=\"fa fa-arrows-h\"></span> Visualize Joins</button>&nbsp;\n            <button class=\"btn btn-sm btn-primary\" data-bind=\"click: DeleteVisibleJoins\" title=\"Delete filtered Joins\"><span class=\"fa fa-trash\"></span> Delete Joins</button>&nbsp;\n            <button class=\"btn btn-sm btn-primary\" data-bind=\"click: ExportJoins\" title=\"Export filtered Joins\"><span class=\"fa fa-download\"></span> Export Joins</button>&nbsp;\n            <button class=\"btn btn-sm btn-primary\" data-bs-toggle=\"modal\" data-bs-target=\"#uploadJoinsFileModal\" aria-haspopup=\"true\" aria-expanded=\"false\">\n                <span class=\"fa fa-upload\"></span> Import Joins\n            </button>\n            <hr />\n            <div id=\"form-joins\">\n                <div class=\"alert alert-warning\" data-bind=\"visible: isDirty\">\n                    You have unsaved changes. Please be sure to click <b>Save Joins</b> to save your changes.\n                </div>\n\n                <div class=\"container-fluid\">\n                    <div class=\"row fw-bold bg-light border-bottom py-2\" data-bind=\"with: JoinFilters\">\n                        <!-- Repeat for each column header -->\n                        <div class=\"col-md-1\" style=\"max-width: 40px;\"></div>\n                        <div class=\"col-md-2\">\n                            Primary Table\n                            <div class=\"input-group input-group-sm\">\n                                <input type=\"text\" class=\"form-control\" data-bind=\"value: primaryTable, valueUpdate: 'afterkeydown'\" placeholder=\"Search...\" />\n                                <span class=\"input-group-text\"><i class=\"fa fa-filter\"></i></span>\n                            </div>\n                        </div>\n                        <div class=\"col-md-2\">\n                            Field\n                            <div class=\"input-group input-group-sm\">\n                                <input type=\"text\" class=\"form-control\" data-bind=\"value: primaryField, valueUpdate: 'afterkeydown'\" placeholder=\"Search...\" />\n                                <span class=\"input-group-text\"><i class=\"fa fa-filter\"></i></span>\n                            </div>\n                        </div>\n                        <div class=\"col-md-1\">\n                            Join Type\n                            <div class=\"input-group input-group-sm\">\n                                <input type=\"text\" class=\"form-control\" data-bind=\"value: joinType, valueUpdate: 'afterkeydown'\" placeholder=\"Search...\">\n                                <span class=\"input-group-text\"><i class=\"fa fa-filter\"></i></span>\n                            </div>\n                        </div>\n                        <div class=\"col-md-2\">\n                            Join Table\n                            <div class=\"input-group input-group-sm\">\n                                <input type=\"text\" class=\"form-control\" data-bind=\"value: joinTable, valueUpdate: 'afterkeydown'\" placeholder=\"Search...\">\n                                <span class=\"input-group-text\"><i class=\"fa fa-filter\"></i></span>\n                            </div>\n                        </div>\n                        <div class=\"col-md-2\">\n                            Field\n                            <div class=\"input-group input-group-sm\">\n                                <input type=\"text\" class=\"form-control\" data-bind=\"value: joinField, valueUpdate: 'afterkeydown'\" placeholder=\"Search...\">\n                                <span class=\"input-group-text\"><i class=\"fa fa-filter\"></i></span>\n                            </div>\n                        </div>\n                        <div class=\"col-md-2\"></div>\n                    </div>\n\n                    <!-- New Join Row -->\n                    <div class=\"row bg-info bg-opacity-25 p-2\" data-bind=\"visible: showNewJoinRow\">\n                        <div class=\"col-md-1\" style=\"max-width: 40px;\"></div>\n                        <div class=\"col-md-2\">\n                            <select class=\"form-select\" data-bind=\"options: Tables.availableTables, optionsText: 'DisplayName', value: NewJoin().JoinTable, optionsCaption: 'Pick a table...'\"></select>\n                        </div>\n                        <div class=\"col-md-2\" data-bind=\"with: NewJoin().JoinTable\">\n                            <select class=\"form-select\" data-bind=\"options: availableColumns, optionsText: 'DisplayName', optionsCaption: 'Pick a field...', optionsValue: 'ColumnName', value: $root.NewJoin().FieldName\"></select>\n                        </div>\n                        <div class=\"col-md-1\">\n                            <select class=\"form-select\" data-bind=\"options: $root.JoinTypes, value: NewJoin().JoinType\"></select>\n                        </div>\n                        <div class=\"col-md-2\">\n                            <select class=\"form-select\" data-bind=\"options: NewJoin().OtherTables, optionsText: 'DisplayName', value: NewJoin().OtherTable, optionsCaption: 'Pick a table...'\"></select>\n                        </div>\n                        <div class=\"col-md-2\" data-bind=\"with: NewJoin().OtherTable\">\n                            <select class=\"form-select\" data-bind=\"options: availableColumns, optionsText: 'DisplayName', optionsValue: 'ColumnName', value: $root.NewJoin().JoinFieldName, optionsCaption: 'Pick a field...'\"></select>\n                        </div>\n                        <div class=\"col-md-2 text-end\">\n                            <button class=\"btn btn-success btn-sm\" data-bind=\"click: ConfirmAddJoin\">+ Add Join</button>\n                        </div>\n                    </div>\n\n                    <!-- Existing Join Rows with drag reorder -->\n                    <div data-bind=\"sortable: { data: reorderableJoins, options: { handle: '.join-drag-handle', cursor: 'move' }, afterMove: $root.joinSorted }\">\n                        <div class=\"row align-items-center border-bottom py-2\">\n                            <div class=\"col-md-1 text-center\" style=\"max-width: 40px;\">\n                                <span class=\"btn btn-sm btn-outline-secondary join-drag-handle\" title=\"Drag to reorder\"><i class=\"fa fa-bars\"></i></span>\n                            </div>\n                            <div class=\"col-md-2\">\n                                <select class=\"form-select\" data-bind=\"options: $root.Tables.availableTables, optionsText: 'DisplayName', value: JoinTable\"></select>\n                            </div>\n                            <div class=\"col-md-2\" data-bind=\"with: JoinTable\">\n                                <select class=\"form-select\" data-bind=\"options: availableColumns, optionsText: 'DisplayName', optionsValue: 'ColumnName', value: $parent.FieldName\"></select>\n                            </div>\n                            <div class=\"col-md-1\">\n                                <select class=\"form-select\" data-bind=\"options: $root.JoinTypes, value: JoinType\"></select>\n                            </div>\n                            <div class=\"col-md-2\">\n                                <select class=\"form-select\" data-bind=\"options: OtherTables, optionsText: 'DisplayName', value: OtherTable\"></select>\n                            </div>\n                            <div class=\"col-md-2\" data-bind=\"with: OtherTable\">\n                                <select class=\"form-select\" data-bind=\"options: availableColumns, optionsText: 'DisplayName', optionsValue: 'ColumnName', value: $parent.JoinFieldName\"></select>\n                            </div>\n                            <div class=\"col-md-2 text-end\">\n                                <span class=\"badge bg-warning text-dark me-2\"\n                                      data-bind=\"visible: isNew\"\n                                      data-bs-toggle=\"tooltip\"\n                                      title=\"New record added or imported, not saved yet\">\n                                    <i class=\"fa fa-warning\"></i> New\n                                </span>\n                                <button class=\"btn btn-secondary btn-sm\" data-bind=\"click: DeleteJoin\">Delete</button>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <div class=\"row mt-3\">                    \n                    <div class=\"d-flex flex-row align-items-center col-md-12\" data-bind=\"with: joinsPager\">                        \n                        <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                        <div class=\"text-muted small mt-0 pt-0\" style=\"padding-left: 3px\" data-bind=\"text: 'Total Records: ' + totalRecords()\"></div>\n                    </div>\n                </div>\n            </div>\n            <br />\n            <br />\n        </div>\n        <div id=\"procedure\" class=\"tab-pane\">\n            <b>Stored Procedures</b>\n            <p>\n                Select and manage Stored Procedures to use in Dotnet Report for more complex and coded Reports\n            </p>\n            <button class=\"btn btn-sm btn-primary\" data-bs-toggle=\"modal\" data-bs-target=\"#procedure-modal\"><span class=\"fa fa-plus\"></span> Add Stored Procs from database</button>\n            <button class=\"btn btn-sm btn-primary\" data-bs-toggle=\"modal\" data-bs-target=\"#uploadStoredProceduresFileModal\" aria-haspopup=\"true\" aria-expanded=\"false\">\n                <span class=\"fa fa-file\"></span> Import Stored Procedures\n            </button>\n            <hr />\n            <div data-bind=\"if: Procedures.savedProcedures().length == 0\">\n                <br />\n                No Stored Procedures have been setup yet.\n            </div>\n            <div class=\"row\" data-bind=\"if: Procedures.savedProcedures().length > 0\">\n                <!-- Left Panel for Stored Procedure Names -->\n                <div class=\"col-12 col-md-4 col-lg-3 border-end\" style=\"height: 100vh; overflow-y: auto;\">\n                    <div class=\"menu g-3\" data-bind=\"foreach: Procedures.savedProcedures\">\n                        <div class=\"menu-category card\">\n                            <div class=\"card-header clearfix\">\n                                <div class=\"float-start\">\n                                    <label>\n                                        <span data-bind=\"text: TableName, click: function() { $root.activeProcedure($data); }\" style=\"cursor: pointer\"></span>\n                                    </label>\n                                    <button class=\"btn btn-sm\" title=\"Save this Procedure\" data-bind=\"click: function() { $root.saveProcedure($data.TableName, false); }\">\n                                        <span class=\"fa fa-save\"></span>\n                                    </button>\n                                    <button class=\"btn btn-sm\" title=\"Delete this Procedure\" data-bind=\"click: function() { $data.deleteTable($root.keys.AccountApiKey, $root.keys.DatabaseApiKey); }\">\n                                        <span class=\"fa fa-trash\"></span>\n                                    </button>\n                                </div>\n                                <!-- Click to activate procedure -->\n                                <a class=\"float-end\" data-bind=\"click: function() { $root.activeProcedure($data); }\">\n                                    <span class=\"fa fa-chevron-right\" style=\"cursor: pointer\"></span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Right Panel for Stored Procedure Details -->\n                <div class=\"col-12 col-md-8 col-lg-9\" id=\"procDetails\">\n                    <div data-bind=\"with: activeProcedure\">\n                        <div class=\"card my-3\">\n                            <div class=\"card-header\">\n                                <h5 data-bind=\"text: TableName\"></h5>\n                                <button class=\"btn btn-sm\" title=\"Save this Procedure\" data-bind=\"click: function() { $root.saveProcedure($data.TableName, false); }\">\n                                    <span class=\"fa fa-save\"></span> Save Changes\n                                </button>\n                                <button class=\"btn btn-sm\" title=\"Delete this Procedure\" data-bind=\"click: function() { $data.deleteTable($root.keys.AccountApiKey, $root.keys.DatabaseApiKey); }\">\n                                    <span class=\"fa fa-trash\"></span> Delete\n                                </button>\n                            </div>\n                            <div class=\"card-body\">\n                                <p class=\"float-end\">\n                                    <button class=\"btn btn-sm\" title=\"Manage Role Access\" data-bs-toggle=\"modal\" data-bs-target=\"#role-access-modal\" data-bind=\"click: $root.selectAllowedRoles\">\n                                        <i class=\"fa fa-user\"></i>\n                                    </button>\n                                    <button class=\"btn btn-sm\" title=\"Export this Procedure\" data-bind=\"click: function() { $root.exportProcedureJson($data.TableName); }\">\n                                        <i class=\"fa fa-file\"></i>\n                                    </button>\n                                </p>\n                                <p>\n                                    <label class=\"label-sm\">Display Name</label><br />\n                                    <span data-bind=\"editable: DisplayName\"></span>\n                                </p>\n                                <p>\n                                    <label class=\"label-sm\">Schema Name</label><br />\n                                    <span data-bind=\"editable: SchemaName\"></span>\n                                </p>\n                                <label class=\"small\">Columns</label>\n                                <div class=\"list-group\" data-bind=\"foreach: Columns\">\n                                    <div class=\"list-group-item\">\n                                        <label>\n                                            <span data-bind=\"editable: DisplayName, attr: { title: 'DB field is ' + ColumnName() }\"></span>\n                                            <span class=\"badge text-bg-info text-white\" data-bind=\"text: FieldType\"></span>\n                                        </label>\n                                        <button class=\"btn btn-sm float-end\" data-bs-toggle=\"modal\" data-bs-target=\"#column-modal\" title=\"All column options\" data-bind=\"click: $root.selectColumn.bind($data, true)\">...</button>\n                                    </div>\n                                </div>\n                                <label class=\"small\">Parameters</label>\n                                <div class=\"list-group\" data-bind=\"foreach: Parameters\">\n                                    <div class=\"list-group-item\">\n                                        <label>\n                                            <span data-bind=\"editable: DisplayName, attr: { title: 'DB field is ' + ParameterName() }\"></span>\n                                            <span class=\"badge text-bg-info text-white\" data-bind=\"text: ParameterDataTypeString\"></span>\n                                            &nbsp;&nbsp;\n                                            <button class=\"btn btn-sm btn-primary float-end\" data-bs-toggle=\"modal\" data-bs-target=\"#parameter-modal\" title=\"All Parameter options\" data-bind=\"click: $root.editParameter\">...</button>\n                                        </label>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n        </div>\n        <div id=\"manageaccess\" class=\"tab-pane\">\n            <ul class=\"nav nav-tabs\" id=\"accessTabs\" role=\"tablist\">\n                <li class=\"nav-item\" role=\"presentation\">\n                    <button class=\"nav-link active\" id=\"reports-tab\" data-bs-toggle=\"tab\" data-bs-target=\"#reportsAccess\" type=\"button\" role=\"tab\">Reports Access</button>\n                </li>\n                <li class=\"nav-item\" role=\"presentation\">\n                    <button class=\"nav-link\" id=\"folders-tab\" data-bs-toggle=\"tab\" data-bs-target=\"#foldersAccess\" type=\"button\" role=\"tab\">Folders Access</button>\n                </li>\n            </ul>\n            <div class=\"tab-content mt-3\">\n                <div class=\"tab-pane fade show active\" id=\"reportsAccess\" role=\"tabpanel\" aria-labelledby=\"reports-tab\">\n                    <b>Reports Access</b>\n                    <p>You can setup access to individual Reports here</p>\n                    <div class=\"mb-2 d-flex gap-2\">\n                        <div class=\"mb-2\">\n                            <button class=\"btn btn-sm btn-primary\" data-bind=\"click: function() { exportFoldersReportJson() }\">\n                                <span class=\"fa fa-download\"></span> Export Selected Reports\n                            </button>\n                        </div>     \n                        <div class=\"mb-2\">\n                            <button class=\"btn btn-sm btn-primary\" data-bs-toggle=\"modal\" data-bs-target=\"#uploadFileModal\">\n                                <span class=\"fa fa-upload\"></span> Import Reports\n                            </button>\n                        </div>\n                        <div class=\"mb-2\">\n                            <button class=\"btn btn-sm btn-primary\" data-bs-toggle=\"modal\" data-bs-target=\"#searchModal\">\n                                <span class=\"fa fa-tasks\"></span> Bulk Actions\n                            </button>\n                        </div>\n                    </div>\n                    <hr />\n                    <div data-bind=\"foreach: reportsAndFolders\" class=\"list-group\">\n                        <div class=\"list-group-item\">\n                            <div class=\"d-flex justify-content-between\">\n                                <div>\n                                    <input type=\"checkbox\" class=\"form-check-input\"\n                                           data-bind=\"checked: allReportsSelected\">\n                                    <label data-bind=\"style: { paddingLeft: (depth * 20) + 'px' }\">\n                                        <a data-bs-toggle=\"collapse\" data-bind=\"attr: {href: '#folder-' + folderId }\">\n                                            <i class=\"fa fa-folder\"></i>&nbsp;<span data-bind=\"text: folder\"></span>\n                                        </a>\n                                    <span class=\"text-muted small ms-2\" data-bind=\"visible: depth > 0, text: folderPath\"></span>\n                                    </label>\n                                </div>\n                            </div>\n                            <div class=\"collapse\" data-bind=\"attr: {id: 'folder-' + folderId }\">\n                                <div data-bind=\"if: reports.length == 0\">\n                                    No Reports found in this folder\n                                </div>\n                                <ul class=\"list-group\" data-bind=\"foreach: reports\">\n                                    <li class=\"list-group-item\">\n                                        <div class=\"row\">\n                                            <div class=\"col-md-6\">\n                                                <div class=\"form-check\">\n                                                    <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: isSelected\" />\n                                                    <label class=\"list-group-item-heading\">\n                                                        <span class=\"fa\" data-bind=\"css: {'fa-file': reportType=='List', 'fa-th-list': reportType=='Summary', 'fa-bar-chart': reportType=='Bar', 'fa-pie-chart': reportType=='Pie',  'fa-line-chart': reportType=='Line', 'fa-globe': reportType =='Map'}\" style=\"color: #808080\"></span>\n                                                        <span data-bind=\"text: reportName\"></span>\n                                                    </label>\n                                                </div>\n                                                <div class=\"small text-muted\" data-bind=\"text: reportDescription\"></div>\n                                            </div>\n                                            <div class=\"col-md-5\">\n                                                <div class=\"d-flex flex-wrap gap-1 align-items-center small\">\n                                                    <div data-bind=\"template: { name: 'access-badges', data: $data }\"></div>\n                                                </div>\n                                            </div>\n                                            <div class=\"col-md-1 text-end\">\n                                                <button type=\"button\" class=\"btn btn-sm btn-outline-secondary\" title=\"Manage Access\" data-bind=\"click: function() { $root.openAccessModal($data, false); }\"><i class=\"fa fa-key\"></i></button>\n                                            </div>\n                                        </div>\n                                    </li>\n                                </ul>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <div class=\"tab-pane fade\" id=\"foldersAccess\" role=\"tabpanel\" aria-labelledby=\"folders-tab\">\n                    <b>Folders Access</b>\n                    <p>You can setup access to individual Folders here</p>\n                    <hr />\n                    <div data-bind=\"foreach: Folders\" class=\"list-group\">\n                        <div class=\"list-group-item\">\n                            <div class=\"d-flex justify-content-between\">\n                                <div>\n                                    <a data-bs-toggle=\"collapse\" data-bind=\"attr: {href: '#folderAccess-' + Id }, style: { paddingLeft: ((Depth || 0) * 20) + 'px' }\">\n                                        <i class=\"fa fa-folder\"></i>&nbsp;<span data-bind=\"text: FolderName\"></span>\n                                    </a>\n                                    <span class=\"text-muted small ms-2\" data-bind=\"visible: (Depth || 0) > 0, text: FolderPath\"></span>\n                                </div>\n                            </div>\n                            <div class=\"collapse\" data-bind=\"attr: {id: 'folderAccess-' + Id }\">\n                                <div class=\"row align-items-center py-2\">\n                                    <div class=\"col-md-10\">\n                                        <div class=\"d-flex flex-wrap gap-1 align-items-center small\">\n                                            <div data-bind=\"template: { name: 'access-badges', data: $data }\"></div>\n                                        </div>\n                                    </div>\n                                    <div class=\"col-md-2 text-end\">\n                                        <button type=\"button\" class=\"btn btn-sm btn-outline-secondary\" title=\"Manage Access\" data-bind=\"click: function() { $root.openAccessModal($data, true); }\"><i class=\"fa fa-key\"></i> Manage Access</button>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"modal\" id=\"setup-access-modal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n                <div class=\"modal-dialog modal-lg\" role=\"document\">\n                    <div class=\"modal-content\">\n                        <div class=\"modal-header\">\n                            <h5 class=\"modal-title\"><i class=\"fa fa-key\"></i> Manage Access <span class=\"text-muted ms-1\" data-bind=\"text: accessTargetName\"></span></h5>\n                            <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n                        </div>\n                        <div class=\"modal-body\">\n                            <div data-bind=\"if: accessTarget()\">\n                                <div data-bind=\"template: { name: 'manage-access-template', data: $root.manageAccess }\"></div>\n                            </div>\n                        </div>\n                        <div class=\"modal-footer\">\n                            <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancel</button>\n                            <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: saveAccessModal\"><i class=\"fa fa-save\"></i> Save Access</button>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n        <div role=\"tabpanel\" class=\"tab-pane\" id=\"functions\" data-bind=\"with: Functions\">\n            <b>Custom Functions</b>\n            <p>\n                Create and manage Custom Function that you can use in building Reports and Dashboards\n            </p>\n            <button class=\"btn btn-sm btn-primary\" data-bind=\"visible: $root.settings.canAddFunction,click: createNewFunction\">Add new Function</button>\n            <button class=\"btn btn-sm btn-primary\" data-bind=\"click: buildCustomFunctions\">Rebuild Functions Library</button>\n            <br />\n            <hr />\n\n            <div class=\"container-fluid\">\n                <div class=\"row\">\n                    <div class=\"col-md-3 border-end\" style=\"height: 100vh; overflow-y: auto;\">\n                        <input id=\"searchInput\" class=\"form-control mb-2\" type=\"text\" placeholder=\"Search...\" data-bind=\"value: search, valueUpdate: 'input', visible: functions().length > 0\">\n                        <ul class=\"list-group\" data-bind=\"foreach: filteredFunctions\">\n                            <li class=\"list-group-item d-flex justify-content-between align-items-center\">\n                                <span data-bind=\"text: name\"></span>\n                                <div>\n                                    <button class=\"btn btn-primary btn-sm\" data-bind=\"click: $parent.selectFunction\">Edit</button>\n                                    <button class=\"btn btn-danger btn-sm\" data-bind=\"click: function() { $parent.deleteFunction($data) }\">Delete</button>\n                                </div>\n                            </li>\n                        </ul>\n                        <div data-bind=\"if: functions().length == 0\">\n                            No Functions found\n                        </div>\n                    </div>\n                    <div class=\"col-md-9\" data-bind=\"with: selectedFunction\">\n                        <div style=\"padding-left: 10px;\">\n                            <div class=\"card\">\n                                <div class=\"card-header\">\n                                    <b>Setup Function</b>\n                                </div>\n                                <div class=\"card-body\">\n                                    <div class=\"mb-3\" data-bind=\"validationElement: functionName\">\n                                        <label for=\"functionName\" class=\"form-label\">Function Name</label>\n                                        <input id=\"functionName\" class=\"form-control\" required data-bind=\"value: name, valueUpdate: 'input'\" />\n                                        <div class=\"invalid-feedback\">Function Name is required.</div>\n                                    </div>\n                                    <div class=\"mb-3\">\n                                        <label for=\"functionType\" class=\"form-label\">Function Type</label>\n                                        <select id=\"functionType\" class=\"form-control\" data-bind=\"value: functionType, event: { change: $parent.updateCodeEditorMode }\">\n                                            <option value=\"csharp\">C#</option>\n                                            <!--<option value=\"javascript\">JavaScript</option>\n                                            <option value=\"sql\">SQL</option>-->\n                                        </select>\n                                    </div>\n                                    <div class=\"mb-3\">\n                                        <label for=\"functionDescription\" class=\"form-label\">Description</label>\n                                        <textarea id=\"functionDescription\" class=\"form-control\" data-bind=\"value: description, valueUpdate: 'input'\" placeholder=\"Add any helpful description here for the user...\"></textarea>\n                                    </div>\n\n                                    <div>\n                                        <b>Arguments</b>\n                                        <table class=\"table table-bordered\">\n                                            <thead>\n                                                <tr>\n                                                    <th></th>\n                                                    <th>Name</th>\n                                                    <th>Description</th>\n                                                    <!--<th>Data Type</th>-->\n                                                    <th>Optional</th>\n                                                    <th></th>\n                                                </tr>\n                                            </thead>\n                                            <tbody data-bind=\"foreach: parameters, tableSortable: { data: parameters, placeholder: 'sortable-placeholder' }\" >\n                                            <tr>\n                                                <td> <span class=\"fa fa-ellipsis-v\" aria-hidden=\"true\" title=\"Drag to reorder\"></span></td>\n                                                <td>\n                                                    <input class=\"form-control\" data-bind=\"value: parameterName, valueUpdate: 'input'\" />\n                                                    <span class=\"text-danger\" data-bind=\"visible: name.hasError, text: name.validationMessage\"></span>\n                                                </td>\n                                                <td><input class=\"form-control\" data-bind=\"value: description, valueUpdate: 'input'\" placeholder=\"Friendly description for user...\" /></td>\n                                                <!--<td>\n                                                    <select class=\"form-select\" data-bind=\"value: datatype\">\n                                                        <option>object</option>\n                                                        <option>string</option>\n                                                        <option>int</option>\n                                                        <option>float</option>\n                                                        <option>bool</option>\n                                                    </select>\n                                                </td>-->\n                                                <td> <input type=\"checkbox\" data-bind=\"checked: required, checkedValue: false, uncheckedValue: true\" /></td>\n                                                <td><button class=\"btn btn-sm btn-danger\" data-bind=\"click: $parent.removeParameter\">Remove</button></td>\n                                            </tr>\n                                            </tbody>\n                                        </table>\n                                        <button class=\"btn btn-sm btn-primary\" data-bind=\"click: addParameter\">Add Argument</button>\n                                    </div>\n                                    <br />\n                                    <div class=\"mb-3\">\n                                        <label for=\"codeEditor\" class=\"form-label\">Write the <b>Code</b> for the function below:</label>\n                                        <div style=\"border: 1px solid\">\n                                            <textarea id=\"codeEditor\" class=\"code-editor form-control\" data-bind=\"value: code\"></textarea>\n                                        </div>\n                                    </div>\n                                    <button class=\"btn btn-primary\" data-bind=\"click: $parent.saveFunction\">Save</button>\n                                    <button class=\"btn btn-secondary\" data-bind=\"click: $parent.cancelEdit\">Cancel</button>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div role=\"tabpanel\" class=\"tab-pane\" id=\"emailqueries\" data-bind=\"with: emailQueries\">\n            <div class=\"d-flex align-items-center mb-2\">\n                <button class=\"btn btn-primary btn-sm\" data-bind=\"click: addQuery\"><i class=\"fa fa-plus\"></i> Add Email List</button>\n                <span class=\"ms-3 text-muted small\">Email lists for scheduled reports. Pick one when you schedule a report.</span>\n            </div>\n            <div class=\"alert alert-info py-2 small\" data-bind=\"visible: queries().length === 0\">No email lists yet.</div>\n            <table class=\"table table-striped table-sm\" data-bind=\"visible: queries().length > 0\">\n                <thead>\n                    <tr>\n                        <th style=\"width: 22%\">Name</th>\n                        <th style=\"width: 28%\">Description</th>\n                        <th style=\"width: 12%\">Client</th>\n                        <th style=\"width: 28%\">Query</th>\n                        <th style=\"width: 10%\"></th>\n                    </tr>\n                </thead>\n                <tbody data-bind=\"foreach: queries\">\n                    <tr>\n                        <td data-bind=\"text: name\"></td>\n                        <td data-bind=\"text: description\"></td>\n                        <td><span data-bind=\"text: clientId ? clientId : 'All Clients'\"></span></td>\n                        <td><code class=\"small text-truncate d-inline-block\" style=\"max-width: 320px;\" data-bind=\"text: sqlQuery\"></code></td>\n                        <td class=\"text-end\">\n                            <button class=\"btn btn-sm btn-light\" title=\"Show the emails this list returns\" data-bind=\"click: function() { $parent.previewQuery($data); }\"><i class=\"fa fa-search\"></i></button>\n                            <button class=\"btn btn-sm btn-light\" title=\"Edit\" data-bind=\"click: function() { $parent.editQuery($data); }\"><i class=\"fa fa-pencil\"></i></button>\n                            <button class=\"btn btn-sm btn-light text-danger\" title=\"Delete\" data-bind=\"click: function() { $parent.deleteQuery($data); }\"><i class=\"fa fa-trash\"></i></button>\n                        </td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <div role=\"tabpanel\" class=\"tab-pane\" id=\"schedules\">\n            <b>Scheduled Reports</b>\n            <p>\n                View Schedules setup for sending Reports and Dashboards\n            </p>\n            <button class=\"btn btn-sm btn-primary\" data-bs-toggle=\"modal\" data-bs-target=\"#sentHistoryModal\" data-bind=\"click: function() { loadSentHistory(1); }\">\n                <span class=\"fa fa-history\"></span> View Send History\n            </button>\n            <hr />\n\n            <div class=\"row\">\n                <div class=\"col-md-12\">\n                    <div data-bind=\"visible: schedules().length === 0\">\n                        <i class=\"fa fa-exclamation-circle\"></i> No scheduled Reports or Dashboards available.\n                    </div>\n                    <div class=\"table-responsive\" data-bind=\"if: schedules().length > 0\">\n                        <table class=\"table table-sm align-middle mb-0 scheduled-reports-table\">\n                            <thead class=\"table-light\">\n                                <tr>\n                                    <th><i class=\"fa fa-file-text-o\"></i> Report / Dashboard</th>\n                                    <th><i class=\"fa fa-clock-o\"></i> Schedule</th>\n                                    <th><i class=\"fa fa-envelope\"></i> Email To</th>\n                                    <th><i class=\"fa fa-file\"></i> Format</th>\n                                    <th><i class=\"fa fa-filter\"></i> Filter</th>\n                                    <th><i class=\"fa fa-history\"></i> Last Run</th>\n                                    <th><i class=\"fa fa-user\"></i> User ID</th>\n                                    <th><i class=\"fa fa-globe\"></i> Time Zone</th>\n                                    <th><i class=\"fa fa-cogs\"></i> Actions</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"border-top\" data-bind=\"foreach: scheduleRows\">\n                                <tr>\n                                    <td class=\"align-middle border-end bg-light\" data-bind=\"css: { 'border-top-0': !isFirst }\">\n                                        <span class=\"fw-bold\" data-bind=\"text: isFirst ? name : ''\"></span>\n                                        <span class=\"badge\" data-bind=\"visible: isFirst, css: isDashboard ? 'bg-info' : 'bg-secondary', text: isDashboard ? 'Dashboard' : 'Report'\"></span>\n                                    </td>\n                                    <td data-bind=\"text: item.ScheduleDisplay\"></td>\n                                    <td class=\"text-break\" data-bind=\"text: $root.emailQueries.emailToDisplay(item)\"></td>\n                                    <td data-bind=\"text: $root.formatDisplay(item.Format)\"></td>\n                                    <td class=\"small text-muted\" data-bind=\"text: item.FilterDisplay ? item.FilterDisplay : 'Report default filters'\"></td>\n                                    <td data-bind=\"text: item.LastRun\"></td>\n                                    <td data-bind=\"text: item.UserId ? item.UserId : 'N/A'\"></td>\n                                    <td data-bind=\"text: item.Timezone ? item.Timezone : 'N/A'\"></td>\n                                    <td>\n                                        <button class=\"btn btn-sm btn-danger\" data-bind=\"click: function() { $root.deleteSchedule(item); }\">\n                                            <i class=\"fa fa-trash\"></i> Delete\n                                        </button>\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n\n<!-- Modal -->\n<div class=\"modal\" id=\"column-modal\" role=\"dialog\" tabindex=\"-1\">\n    <div class=\"modal-dialog\" role=\"document\">\n        <div class=\"modal-content\" data-bind=\"with: editColumn()\">\n            <div class=\"modal-header\">\n                <h4 class=\"modal-title\" id=\"myModalLabel\">\n                    Manage\n                    <label data-bind=\"text: ColumnName\"></label>\n                </h4>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <p>Choose options that will determine how users interact with this column on Reports</p>\n                <div class=\"form-horizontal\">\n\n                    <ul class=\"nav nav-tabs\" role=\"tablist\" data-bind=\"if: $root.isStoredProcColumn() == false\">\n                        <li role=\"presentation\" class=\"nav-item\"><a class=\"nav-link active\" href=\"#column-main\" aria-controls=\"home\" role=\"tab\" data-bs-toggle=\"tab\">Main Options</a></li>\n                        <li role=\"presentation\" class=\"nav-item\"><a class=\"nav-link\" href=\"#column-foreign\" aria-controls=\"profile\" role=\"tab\" data-bs-toggle=\"tab\">Foreign Key Options</a></li>\n                        <li role=\"presentation\" class=\"nav-item\"><a class=\"nav-link\" href=\"#column-filter\" aria-controls=\"procedure\" role=\"tab\" data-bs-toggle=\"tab\">Filter Options</a></li>\n                    </ul>\n                    <div class=\"tab-content\">\n                        <br />\n                        <div role=\"tabpanel\" class=\"tab-pane active\" id=\"column-main\">\n                            <div class=\"control-group\">\n                                <div class=\"form-group row\">\n                                    <label class=\"col-md-3 col-sm-3 control-label\" for=\"Display_Name\" data-bind=\"attr:{placeholder:'Ex First Name'}\" placeholder=\"Ex First Name\">Display Name</label>\n                                    <div class=\"col-md-6 col-sm-6\">\n                                        <input class=\"form-control text-box single-line\" data-val=\"true\" data-val-required=\"The DisplayName field is required.\" id=\"DisplayName\" name=\"DisplayName\" type=\"text\" value=\"First Name\" data-bind=\"value: DisplayName, attr:{placeholder:'Ex First Name'}\" placeholder=\"Ex First Name\">\n                                    </div>\n                                    <div class=\"col-md-3 col-sm-3\">\n                                        <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"This is a friendly name to display to your users\"></span>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"control-group\" data-bind=\"if: $root.isStoredProcColumn() == false\">\n                                <div class=\"form-group row\">\n                                    <label class=\"col-md-3 col-sm-3 control-label\" for=\"Field_Type\" data-bind=\"\">Field Type</label>\n                                    <div class=\"col-md-6 col-sm-6\">\n                                        <select class=\"form-select\" id=\"FieldType_SelectedId\" name=\"FieldType.SelectedId\" data-bind=\"value: FieldType\">\n                                            <option value=\"Boolean\">Boolean</option>\n                                            <option value=\"DateTime\">Date Time</option>\n                                            <option value=\"Varchar\">Varchar</option>\n                                            <option value=\"Money\">Money</option>\n                                            <option value=\"Int\">Int</option>\n                                            <option value=\"Double\">Double</option>\n                                            <option value=\"Json\">Json</option>\n                                            <option value=\"Date\">Date Only</option>\n                                            <option value=\"Time\">Time Only</option>\n                                            <option value=\"Percentage\">Percentage</option>\n                                        </select>\n                                    </div>\n                                    <div class=\"col-md-3 col-sm-3\">\n                                        <span class=\"field-validation-valid help-inline indent\" data-valmsg-for=\"FieldType\" data-valmsg-replace=\"true\"></span>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"control-group\" data-bind=\"if: $root.isStoredProcColumn() == false\">\n                                <div class=\"form-group row\">\n                                    <label class=\"col-md-3 col-sm-3 control-label\" for=\"Primary_Key\" data-bind=\"\">Primary Key</label>\n                                    <div class=\"col-md-6 col-sm-6\">\n                                        <div class=\"checkbox\">\n                                            <label>\n                                                <input class=\"check-box\" data-val=\"true\" data-val-required=\"The PrimaryKey field is required.\" id=\"PrimaryKey\" name=\"PrimaryKey\" type=\"checkbox\" value=\"true\" data-bind=\"checked:PrimaryKey\"><input name=\"PrimaryKey\" type=\"hidden\" value=\"false\">\n                                            </label>\n                                        </div>\n                                    </div>\n                                    <div class=\"col-md-3 col-sm-3\">\n                                        <span class=\"field-validation-valid help-inline indent\" data-valmsg-for=\"PrimaryKey\" data-valmsg-replace=\"true\"></span>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"control-group\">\n                                <div class=\"form-group row\">\n                                    <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"\">Do Not Display</label>\n                                    <div class=\"col-md-6 col-sm-6\">\n                                        <div class=\"checkbox\">\n                                            <label>\n                                                <input class=\"check-box\" data-val=\"true\" type=\"checkbox\" value=\"true\" data-bind=\"checked:DoNotDisplay\">\n                                            </label>\n                                        </div>\n                                    </div>\n                                    <div class=\"col-md-3 col-sm-3\">\n                                        <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"If this is checked, the column will not be displayed on Report Designer, but can still be used on Global Data Filters\"></span>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div class=\"control-group\" data-bind=\"if: FieldType() == 'Json'\">\n                                <div class=\"form-group row\">\n                                    <label class=\"col-md-3 col-sm-3 control-label\">JSON Data Structure</label>\n                                    <div class=\"col-md-6 col-sm-6\">\n                                        <textarea class=\"form-control text-box single-line\" data-val=\"true\" data-val-required=\"The DisplayName field is required.\" data-bind=\"value: JsonStructure, attr:{placeholder:'Please paste in Sample Json with all columns for this JSON data field'}\" rows=\"5\"></textarea>\n                                    </div>\n                                    <div class=\"col-md-3 col-sm-3\">\n                                        <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"You can paste in a sample Json blob with all the columns you want to use in this field\"></span>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <div role=\"tabpanel\" class=\"tab-pane\" id=\"column-filter\">\n                            <div class=\"control-group\" data-bind=\"if: $root.isStoredProcColumn() == false\">\n                                <div class=\"form-group row\">\n                                    <label class=\"col-md-4 col-sm-4 control-label\" data-bind=\"\">Require Filter if Column is selected</label>\n                                    <div class=\"col-md-6 col-sm-6\">\n                                        <div class=\"checkbox\">\n                                            <label>\n                                                <input class=\"check-box\" data-val=\"true\" type=\"checkbox\" value=\"true\" data-bind=\"checked:ForceFilter\">\n                                            </label>\n                                        </div>\n                                    </div>\n                                    <div class=\"col-md-2 col-sm-2\">\n                                        <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"If this is checked, the column will always require the user to pick a filtered value\"></span>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"control-group\" data-bind=\"if: $root.isStoredProcColumn() == false\">\n                                <div class=\"form-group row\">\n                                    <label class=\"col-md-4 col-sm-4 control-label\" data-bind=\"\">Require Filter if Table is selected</label>\n                                    <div class=\"col-md-6 col-sm-6\">\n                                        <div class=\"checkbox\">\n                                            <label>\n                                                <input class=\"check-box\" data-val=\"true\" type=\"checkbox\" value=\"true\" data-bind=\"checked:ForceFilterForTable\">\n                                            </label>\n                                        </div>\n                                    </div>\n                                    <div class=\"col-md-2 col-sm-2\">\n                                        <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"If this is checked, the report will always require the user to pick a filter value if user picks the column in report\"></span>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"control-group\" data-bind=\"if: FieldType() == 'DateTime'\">\n                                <div class=\"form-group row\">\n                                    <label class=\"col-md-4 col-sm-4 control-label\" data-bind=\"\">Restrict Filter Date Range</label>\n                                    <div class=\"col-md-1 col-sm-1\">\n                                        <input class=\"check-box\" type=\"checkbox\" data-bind=\"checked: restrictDateRangeFilter\" />\n                                    </div>\n                                    <div class=\"col-md-2 col-sm-2\" data-bind=\"if: restrictDateRangeFilter\">\n                                        <input class=\"form-control\" type=\"number\" data-bind=\"value: restrictDateRangeNumber\" />\n                                    </div>\n                                    <div class=\"col-md-3 col-sm-3\" data-bind=\"if: restrictDateRangeFilter\">\n                                        <select class=\"form-select\" data-bind=\"value: restrictDateRangeValue\">\n                                            <option value=\"Days\">Day(s)</option>\n                                            <option value=\"Months\">Month(s)</option>\n                                            <option value=\"Years\">Year(s)</option>\n                                        </select>\n                                    </div>\n                                    <div class=\"col-md-2 col-sm-2\">\n                                        <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"If this is selected, user will not be able to pick date range larger than this selection\"></span>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <div role=\"tabpanel\" class=\"tab-pane\" id=\"column-foreign\">\n                            <div class=\"control-group\" data-bind=\"if: $root.isStoredProcColumn() == false\">\n                                <div class=\"form-group row\">\n                                    <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"\">Foreign Key</label>\n                                    <div class=\"col-md-6 col-sm-6\">\n                                        <div class=\"checkbox\">\n                                            <label>\n                                                <input class=\"check-box\" data-val=\"true\" data-val-required=\"The ForeignKey field is required.\" id=\"ForeignKey\" name=\"ForeignKey\" type=\"checkbox\" value=\"true\" data-bind=\"checked:ForeignKey\"><input name=\"ForeignKey\" type=\"hidden\" value=\"false\">\n                                            </label>\n                                        </div>\n                                    </div>\n                                    <div class=\"col-md-3 col-sm-3\">\n                                        <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"Foreign keys allows friendly selection in Filters using a Dropdown List\"></span>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"control-group\" data-bind=\"if: $root.isStoredProcColumn() == false\">\n                                <div class=\"form-group row\">\n                                    <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"visible:ForeignKey(), attr: {required: ForeignKey()?'True':null, placeholder: 'Ex tblEmployees'}\" placeholder=\"Ex tblEmployees\" style=\"display: none;\">Foreign Table</label>\n                                    <div class=\"col-md-6 col-sm-6\">\n                                        <select class=\"form-select\" data-bind=\"value: JoinTable, visible:ForeignKey(), options: $root.Tables.availableTables, optionsText: 'TableName'\" placeholder=\"Ex tblEmployees\" style=\"display: none;\"></select>\n\n                                    </div>\n                                    <div class=\"col-md-3 col-sm-3\">\n                                        <span class=\"field-validation-valid help-inline indent\" data-valmsg-for=\"ForeignTable\" data-valmsg-replace=\"true\"></span>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"control-group\" data-bind=\"if: $root.isStoredProcColumn() == false\">\n                                <div class=\"form-group row\">\n                                    <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"visible:ForeignKey(), attr: {required: ForeignKey()?'True':null}\" style=\"display: none;\">Foreign Join</label>\n                                    <div class=\"col-md-6 col-sm-6\">\n                                        <select class=\"form-select\" id=\"ForeignJoin_SelectedId\" name=\"ForeignJoin.SelectedId\" data-bind=\"value: ForeignJoin, visible:ForeignKey(), attr: {required: ForeignKey()?'True':null}\" style=\"display: none;\">\n                                            <option selected=\"selected\" value=\"Inner\">Inner</option>\n                                            <option value=\"Left\">Left</option>\n                                            <option value=\"Right\">Right</option>\n                                        </select>\n                                    </div>\n                                    <div class=\"col-md-3 col-sm-3\">\n                                        <span class=\"field-validation-valid help-inline indent\" data-valmsg-for=\"ForeignJoin\" data-valmsg-replace=\"true\"></span>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"control-group\" data-bind=\"if: $root.isStoredProcColumn() == false\">\n                                <div class=\"form-group row\">\n                                    <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"visible:ForeignKey(), attr: {required: ForeignKey()?'True':null, placeholder: 'Ex EmployeeId'}\" placeholder=\"Ex EmployeeId\" style=\"display: none;\">Foreign Key Field</label>\n                                    <div class=\"col-md-6 col-sm-6\">\n                                        <select class=\"form-select\" id=\"ForeignKeyField\" name=\"ForeignKeyField\" data-bind=\"options: JoinTable().Columns, optionsText: 'ColumnName', optionsValue: 'ColumnName', value: ForeignKeyField, visible:ForeignKey(), attr: {required: ForeignKey()?'True':null}\" placeholder=\"Ex EmployeeId\" style=\"display: none;\"></select>\n                                    </div>\n                                    <div class=\"col-md-3 col-sm-3\">\n                                        <span data-bind=\"visible:ForeignKey()\" data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" style=\"display: none;\" title=\"Foreign Key field is a Column from the Foreign table which is used as the Key field\"></span>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"control-group\" data-bind=\"if: $root.isStoredProcColumn() == false\">\n                                <div class=\"form-group row\">\n                                    <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"visible:ForeignKey(), attr: {required: ForeignKey()?'True':null, placeholder: 'Ex EmployeeName'}\" placeholder=\"Ex EmployeeName\" style=\"display: none;\">Foreign Value Field</label>\n                                    <div class=\"col-md-6 col-sm-6\">\n                                        <select class=\"form-select\" id=\"ForeignValueField\" name=\"ForeignValueField\" data-bind=\"options: JoinTable().Columns, optionsText: 'ColumnName', optionsValue: 'ColumnName', value: ForeignValueField, visible:ForeignKey(), attr: {required: ForeignKey()?'True':null}\" placeholder=\"Ex EmployeeName\" style=\"display: none;\"></select>\n                                    </div>\n                                    <div class=\"col-md-3 col-sm-3\">\n                                        <span data-bind=\"visible:ForeignKey()\" data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" style=\"display: none;\" title=\"Foreign Value field is a Column from the Foreign table which is used to display the value to the User in the Report Designer\"></span>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div data-bind=\"if: ForeignKey\">\n                                <div class=\"control-group\">\n                                    <div class=\"form-group row\">\n                                        <label class=\"col-md-3 col-sm-3 control-label\">Only for Filter?</label>\n                                        <div class=\"col-md-6 col-sm-6\">\n                                            <div class=\"checkbox\">\n                                                <label>\n                                                    <input class=\"check-box\" type=\"checkbox\" data-bind=\"checked:ForeignFilterOnly\">\n                                                </label>\n                                            </div>\n                                        </div>\n                                        <div class=\"col-md-3 col-sm-3\">\n                                            <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"Check this option if you would like to use this for Filtering only, and not for SQL Joins\"></span>\n                                        </div>\n                                    </div>\n                                </div>\n\n                                <div class=\"alert alert-info\">\n                                    You can setup a cascading filter by setting up a parent for the foreign key below\n                                </div>\n                                <div class=\"control-group\">\n                                    <div class=\"form-group row\">\n                                        <label class=\"col-md-3 col-sm-3 control-label\">Setup Foreign Key Parent?</label>\n                                        <div class=\"col-md-6 col-sm-6\">\n                                            <div class=\"checkbox\">\n                                                <label>\n                                                    <input class=\"check-box\" type=\"checkbox\" data-bind=\"checked:ForeignParentKey\">\n                                                </label>\n                                            </div>\n                                        </div>\n                                        <div class=\"col-md-3 col-sm-3\">\n                                            <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"Foreign keys parent allows cascading dropdown selection in Filters\"></span>\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class=\"control-group\">\n                                    <div class=\"form-group row\">\n                                        <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"visible:ForeignParentKey(), attr: {required: ForeignParentKey()?'True':null, placeholder: 'Ex tblEmployees'}\" placeholder=\"Ex tblEmployees\" style=\"display: none;\">Parent Table</label>\n                                        <div class=\"col-md-6 col-sm-6\">\n                                            <select class=\"form-select\" data-bind=\"value: ForeignJoinTable, visible:ForeignParentKey(), options: $root.Tables.model, optionsText: 'TableName'\" placeholder=\"Ex tblEmployees\" style=\"display: none;\"></select>\n\n                                        </div>\n                                        <div class=\"col-md-3 col-sm-3\">\n                                            <span class=\"field-validation-valid help-inline indent\" data-valmsg-for=\"ForeignJoinTable\" data-valmsg-replace=\"true\"></span>\n                                        </div>\n                                    </div>\n                                </div>\n\n                                <div class=\"control-group\" data-bind=\"visible:ForeignParentKey()\" style=\"display: none;\">\n                                    <div class=\"form-group row\">\n                                        <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"attr: {required: ForeignParentKey()?'True':null, placeholder: 'Ex EmployeeId'}\">Parent Key Field</label>\n                                        <div class=\"col-md-6 col-sm-6\">\n                                            <select class=\"form-select\" data-bind=\"options: ForeignJoinTable().Columns, optionsText: 'ColumnName', optionsValue: 'ColumnName', value: ForeignParentKeyField, attr: {required: ForeignParentKey()?'True':null}\" placeholder=\"Ex EmployeeId\"></select>\n                                        </div>\n                                        <div class=\"col-md-3 col-sm-3\">\n                                            <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"Parent Key field is a Column from the Parent table which is used as the key in cascading filters\"></span>\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class=\"control-group\" data-bind=\"visible:ForeignParentKey()\" style=\"display: none;\">\n                                    <div class=\"form-group row\">\n                                        <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"attr: {required: ForeignParentKey()?'True':null, placeholder: 'Ex EmployeeName'}\">Parent Value Field</label>\n                                        <div class=\"col-md-6 col-sm-6\">\n                                            <select class=\"form-select\" data-bind=\"options: ForeignJoinTable().Columns, optionsText: 'ColumnName', optionsValue: 'ColumnName', value: ForeignParentValueField, attr: {required: ForeignParentKey()?'True':null}\" placeholder=\"Ex EmployeeName\"></select>\n                                        </div>\n                                        <div class=\"col-md-3 col-sm-3\">\n                                            <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"Parent Value field is a Column from the Parent table which is used to display the value to the User in the Report Designer for cascading filters\"></span>\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class=\"control-group\" data-bind=\"visible:ForeignParentKey()\" style=\"display: none;\">\n                                    <div class=\"form-group row\">\n                                        <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"attr: {required: ForeignParentKey()?'True':null, placeholder: 'Ex EmployeeName'}\">Foreign Key Filter Field</label>\n                                        <div class=\"col-md-6 col-sm-6\">\n                                            <select class=\"form-select\" data-bind=\"options: JoinTable().Columns, optionsText: 'ColumnName', optionsValue: 'ColumnName', value: ForeignParentApplyTo, attr: {required: ForeignParentKey()?'True':null}\" placeholder=\"Ex EmployeeName\"></select>\n                                        </div>\n                                        <div class=\"col-md-3 col-sm-3\">\n                                            <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"Foreign Key Filter Value field is a Column from the Foreign table where the selected parent filter will be applied for cascading filters\"></span>\n                                        </div>\n                                    </div>\n                                </div>\n                                <!--<div class=\"control-group\">\n                                    <div class=\"form-group row\">\n                                        <label class=\"col-md-3 col-sm-3 control-label\">Require Foreign Key Parent?</label>\n                                        <div class=\"col-md-6 col-sm-6\">\n                                            <div class=\"checkbox\">\n                                                <label>\n                                                    <input class=\"check-box\" type=\"checkbox\" data-bind=\"checked:ForeignParentRequired\">\n                                                </label>\n                                            </div>\n                                        </div>\n                                        <div class=\"col-md-3 col-sm-3\">\n                                            <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"Foreign keys parent can be optional or set to required for cascading filters\"></span>\n                                        </div>\n                                    </div>\n                                </div>-->\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"modal-footer\">\n                        <button class=\"btn btn-secondary\" title=\"Manage Role Access\" data-bs-toggle=\"modal\" data-bs-target=\"#role-access-modal\" data-bind=\"click: $root.selectAllowedRoles\">\n                            <i class=\"fa fa-user\"></i>Manage Role Access\n                        </button>\n                        @* <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\" data-bind=\"click: function(){$root.saveColumn()}\">Done</button> *@\n                        <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Done</button>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n\n\n<div class=\"modal\" id=\"joinModal\" tabindex=\"-1\" role=\"dialog\">\n    <div class=\"modal-dialog modal-lg\" role=\"document\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\">Joins Diagram</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\" style=\"max-height:800px;overflow:auto;\">\n                <div id=\"joinDiagram\" style=\"width:2000px;height:1200px;position:relative;border:1px solid #ccc;\"></div>\n            </div>\n        </div>\n    </div>\n</div>\n\n\n<div class=\"modal\" id=\"procedure-modal\" role=\"dialog\" tabindex=\"-2\">\n    <div class=\"modal-dialog modal-lg\" role=\"document\">\n        <div class=\"modal-content \">\n            <div class=\"modal-header\">\n                <h4 class=\"modal-title\">Add Stored Proc</h4>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <div class=\"row\">\n                    <label class=\"col-md-2 control-label\">\n                        Search for\n                    </label>\n                    <div class=\"col-md-6\">\n                        <input type=\"text\" class=\"form-control\" data-bind=\"value: searchProcedureTerm\" placeholder=\"Search stored procedures by name\" />\n                    </div>\n                    <div class=\"col-md-2\">\n                        <button class=\"btn btn-primary\" data-bind=\"click: searchStoredProcedure\">Search</button>\n                    </div>\n                </div>\n                <br />\n                <div class=\"menu g-3\" style=\"margin-left: 20px;\" data-bind=\"foreach: foundProcedures\">\n                    <div class=\"menu-category card\" style=\"float:left\">\n                        <div class=\"card-header clearfix\" style=\"\">\n                            <div class=\"float-start\">\n                                <label>\n                                    <span data-bind=\"text: TableName\"></span>\n                                    <span class=\"label-xs\">Procedure</span>\n                                </label>\n                                <button class=\"btn btn-sm\" title=\"Save this Procedure\" data-bind=\"click: function(){$root.saveProcedure($data.TableName, true);}\">\n                                    <span class=\"fa fa-save\"></span>\n                                </button>\n                            </div>\n                            <a class=\"float-end\" data-bs-toggle=\"collapse\" data-bind=\"attr: {'data-bs-target': '#sp_'+$index()}\">\n                                <span class=\"fa fa-chevron-down\"></span>\n                            </a>\n                        </div>\n                        <div data-bind=\"attr: {id: 'sp_'+$index()}\" class=\"panel-collapse collapse in\">\n                            <div class=\"card-body\">\n                                Display Name<br />\n                                <span data-bind=\"editable: DisplayName\"></span>\n                                <label class=\"small\">Columns</label>\n\n                                <div class=\"list-group\" data-bind=\"foreach: Columns\">\n                                    <div class=\"list-group-item\">\n                                        <span data-bind=\"editable: DisplayName\"></span>\n                                        <span class=\"badge text-bg-info text-white\" data-bind=\"text: FieldType\"></span>\n                                    </div>\n                                </div>\n                                <label class=\"small\">Parameters</label>\n\n                                <div class=\"list-group\" data-bind=\"foreach: Parameters\">\n                                    <div class=\"list-group-item\">\n                                        <span data-bind=\"editable: DisplayName\"></span>\n                                        <span class=\"badge text-bg-info text-white\" data-bind=\"text: ParameterDataTypeString\"></span><br />\n                                        Default Value: <span data-bind=\"editable: ParameterValue\"></span>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-primary\" data-bs-dismiss=\"modal\">Done</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"parameter-modal\" role=\"dialog\" tabindex=\"-1\">\n    <div class=\"modal-dialog\" role=\"document\">\n        <div class=\"modal-content\" data-bind=\"with: editParameter()\">\n            <div class=\"modal-header\">\n                <h4 class=\"modal-title\" id=\"myModalLabel\">\n                    Manage\n                    <label data-bind=\"text: ParameterName\"></label>\n                </h4>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <p>Choose options that will determine how users interact with this parameter on Reports</p>\n                <div class=\"form-horizontal\">\n                    <div class=\"control-group\">\n                        <div class=\"form-group row\">\n                            <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"attr:{placeholder:'Ex First Name'}\" placeholder=\"Ex First Name\">Display Name</label>\n                            <div class=\"col-md-6 col-sm-6\">\n                                <input class=\"form-control text-box single-line\" data-val=\"true\" data-val-required=\"The DisplayName field is required.\" name=\"DisplayName\" type=\"text\" value=\"First Name\" data-bind=\"value: DisplayName, attr:{placeholder:'Ex First Name'}\" placeholder=\"Ex First Name\">\n                            </div>\n                            <div class=\"col-md-3 col-sm-3\">\n                                <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"This is a friendly name to display to your users\"></span>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"control-group\">\n                        <div class=\"form-group row\">\n                            <label class=\"col-md-3 col-sm-3 control-label\">Default Value</label>\n                            <div class=\"col-md-6 col-sm-6\">\n                                <span data-bind=\"editable: ParameterValue\"></span>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"control-group\">\n                        <div class=\"form-group row\">\n                            <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"\">Hidden Parameter</label>\n                            <div class=\"col-md-6 col-sm-6\">\n                                <div class=\"checkbox\">\n                                    <label>\n                                        <input class=\"check-box\" data-val=\"true\" type=\"checkbox\" value=\"true\" data-bind=\"checked: Hidden, enable: ParameterValue\">\n                                    </label>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"control-group\">\n                        <div class=\"form-group row\">\n                            <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"\">Required</label>\n                            <div class=\"col-md-6 col-sm-6\">\n                                <div class=\"checkbox\">\n                                    <label>\n                                        <input class=\"check-box\" data-val=\"true\" type=\"checkbox\" value=\"true\" data-bind=\"checked:Required\">\n                                    </label>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"control-group\">\n                        <div class=\"form-group row\">\n                            <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"\">Use Lookup Table</label>\n                            <div class=\"col-md-6 col-sm-6\">\n                                <div class=\"checkbox\">\n                                    <label>\n                                        <input class=\"check-box\" data-val=\"true\" name=\"ForeignKey\" type=\"checkbox\" value=\"true\" data-bind=\"checked:ForeignKey\"><input name=\"ForeignKey\" type=\"hidden\" value=\"false\">\n                                    </label>\n                                </div>\n                            </div>\n                            <div class=\"col-md-3 col-sm-3\">\n                                <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"Using lookup table allows friendly selection in report using a Dropdown List\"></span>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"control-group\">\n                        <div class=\"form-group row\">\n                            <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"visible:ForeignKey(), attr: {required: ForeignKey()?'True':null, placeholder: 'Ex tblEmployees'}\" placeholder=\"Ex tblEmployees\" style=\"display: none;\">Lookup Table</label>\n                            <div class=\"col-md-6 col-sm-6\">\n                                <select class=\"form-select\" data-bind=\"value: JoinTable, visible:ForeignKey(), options: $root.Procedures.tables, optionsText: 'TableName'\" placeholder=\"Ex tblEmployees\" style=\"display: none;\"></select>\n\n                            </div>\n                            <div class=\"col-md-3 col-sm-3\">\n                                <span class=\"field-validation-valid help-inline indent\" data-valmsg-for=\"ForeignTable\" data-valmsg-replace=\"true\"></span>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"control-group\">\n                        <div class=\"form-group row\">\n                            <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"visible:ForeignKey(), attr: {required: ForeignKey()?'True':null, placeholder: 'Ex EmployeeId'}\" placeholder=\"Ex EmployeeId\" style=\"display: none;\">Lookup Key Field</label>\n                            <div class=\"col-md-6 col-sm-6\">\n                                <select class=\"form-select\" name=\"ForeignKeyField\" data-bind=\"options: JoinTable().Columns, optionsText: 'ColumnName', optionsValue: 'ColumnName', value: ForeignKeyField, visible:ForeignKey(), attr: {required: ForeignKey()?'True':null}\" placeholder=\"Ex EmployeeId\" style=\"display: none;\"></select>\n                            </div>\n                            <div class=\"col-md-3 col-sm-3\">\n                                <span data-bind=\"visible:ForeignKey()\" data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" style=\"display: none;\" title=\"Foreign Key field is a Column from the Foreign table which is used as the Key field\"></span>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"control-group\">\n                        <div class=\"form-group row\">\n                            <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"visible:ForeignKey(), attr: {required: ForeignKey()?'True':null, placeholder: 'Ex EmployeeName'}\" placeholder=\"Ex EmployeeName\" style=\"display: none;\">Lookup Value Field</label>\n                            <div class=\"col-md-6 col-sm-6\">\n                                <select class=\"form-select\" name=\"ForeignValueField\" data-bind=\"options: JoinTable().Columns, optionsText: 'ColumnName', optionsValue: 'ColumnName', value: ForeignValueField, visible:ForeignKey(), attr: {required: ForeignKey()?'True':null}\" placeholder=\"Ex EmployeeName\" style=\"display: none;\"></select>\n                            </div>\n                            <div class=\"col-md-3 col-sm-3\">\n                                <span data-bind=\"visible:ForeignKey()\" data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" style=\"display: none;\" title=\"Lookup Value field is a Column from the Lookup table which is used to display the value to the User in the Report Designer\"></span>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Done</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n    <div class=\"modal\" id=\"role-access-modal\" role=\"dialog\" tabindex=\"-2\">\n        <div class=\"modal-dialog\" role=\"document\">\n            <div class=\"modal-content\" data-bind=\"with: editAllowedRoles\">\n                <div class=\"modal-header\">\n                    <h4 class=\"modal-title\">Manage Access by Roles</h4>\n                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n                </div>\n                <div class=\"modal-body\">\n                    <p>Choose User Roles that will have Access</p>\n                    <p class=\"small\">Note: All Users will have access if no restricted roles are setup</p>\n                    <div data-bind=\"if: $root.allRoles().length === 0\">\n                        <div class=\"alert alert-warning\">\n                            <strong>No roles available.</strong> Please add roles first.\n                        </div>\n                    </div>\n                    <div data-bind=\"if: $root.allRoles().length > 0\">\n                        <div class=\"list-group\" data-bind=\"foreach: $root.allRoles\">\n                            <div class=\"list-group-item\" style=\"padding: 2px 10px;\">\n                                <label>\n                                    <input type=\"checkbox\"\n                                           data-bind=\"value: $data,\n                                      checked: $root.editAllowedRoles().AllowedRoles\" />\n                                    <span data-bind=\"text: $data\"></span>\n                                </label>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <div class=\"modal-footer\">\n                    <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Done</button>\n                </div>\n            </div>\n        </div>\n    </div>\n    <div class=\"modal\" id=\"category-manage-modal\" role=\"dialog\" tabindex=\"-2\">\n        <div class=\"modal-dialog\" role=\"document\">\n            <div class=\"modal-content\" data-bind=\"with: manageCategories\">\n                <div class=\"modal-header\">\n                    <b class=\"modal-title\">Manage Categories for <span data-bind=\"text: TableName\"></span></b>\n                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n                </div>\n                <div class=\"modal-body\">\n                    <div data-bind=\"visble: $root.Categories().lenth == 0\">\n                        No categories have been set up yet.\n                    </div>\n                    <div class=\"list-group\" data-bind=\"foreach: $root.Categories\">\n                        <div class=\"checkbox list-group-item\" style=\"padding-top: 2px; padding-bottom: 2px;\">\n                            <label>\n                                <input type=\"checkbox\" data-bind=\"checked: $parent.Categories, checkedValue: $data\" />\n                                <span data-bind=\"text: Name\"></span> <!-- Display category name -->\n                            </label>\n                        </div>\n                    </div>\n                </div>\n                <div class=\"modal-footer\">\n                    <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Done</button>\n                </div>\n            </div>\n        </div>\n    </div>\n\n\n<div class=\"modal\" id=\"category-modal\" role=\"dialog\" tabindex=\"-2\">\n    <div class=\"modal-dialog\" role=\"document\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <b class=\"modal-title\">Manage Categories</b>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <p>\n                    You can organize the display of tables in the Report Designer by assigning categories here.\n                </p>\n                <!-- Table for Categories -->\n                <table class=\"table table-bordered\">\n                    <thead>\n                        <tr>\n                            <th>Category Name</th>\n                            <th>Description</th>\n                            <th>Actions</th>\n                        </tr>\n                    </thead>\n                    <tbody data-bind=\"foreach: $root.Categories\">\n                        <tr>\n                            <td>\n                                <input type=\"text\" data-bind=\"value: Name, visible: $root.editingCategoryIndex() === $index()\" class=\"form-control\" />\n                                <span id=\"cat-name\" data-bind=\"text: Name, visible: $root.editingCategoryIndex() !== $index(), attr: { id: Id ? 'cat-name-' + Id :undefined }\" style=\"color: #6c757d;\"></span>\n                            </td>\n                            <td>\n                                <input type=\"text\" data-bind=\"value: Description, visible: $root.editingCategoryIndex() === $index()\" class=\"form-control\" />\n                                <span id=\"cat-desc\" data-bind=\"text: Description, visible: $root.editingCategoryIndex() !== $index(), attr: { id: Id ? 'cat-desc-' + Id :undefined }\" style=\"color: #6c757d;\"></span>\n                            </td>\n                            <td class=\"d-flex\">\n                                <button class=\"btn btn-primary btn-sm\" data-bind=\"visible: $root.editingCategoryIndex() !== $index() && Id !== 0, click: function() { $root.toggleEdit($index()) }\">\n                                    <i class=\"fa fa-edit\"></i>\n                                </button>\n                                <button class=\"btn btn-success btn-sm\" data-bind=\"visible: $root.editingCategoryIndex() === $index() && Id !== 0, click: function() { $root.saveCategory($index()) }\" style=\"margin-left: 5px;\">\n                                    <i class=\"fa fa-save\"></i>\n                                </button>\n                                <button class=\"btn btn-danger btn-sm\" data-bind=\"click: $root.removeCategory\">\n                                    <i class=\"fa fa-trash\"></i>\n                                </button>\n                            </td>\n                        </tr>\n                    </tbody>\n                    <tfoot>\n                        <tr>\n                            <td>\n                                <input class=\"form-control\" type=\"text\" data-bind=\"value: $root.newCategoryName\" placeholder=\"Category Name\">\n                            </td>\n                            <td>\n                                <input class=\"form-control\" type=\"text\" data-bind=\"value: $root.newCategoryDescription\" placeholder=\"Description\">\n                            </td>\n                            <td>\n                                <button class=\"btn btn-primary btn-sm\" data-bind=\"click: $root.addCategory\">Add</button>\n                            </td>\n                        </tr>\n                    </tfoot>\n                </table>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: $root.saveCategories\">Save</button>\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Done</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<div class=\"clearfix\"></div>\n\n<div class=\"modal\" id=\"add-connection-modal\" role=\"dialog\">\n    <div class=\"modal-dialog\" role=\"document\">\n        <div class=\"modal-content\" data-bind=\"with: newDataConnection\">\n            <div class=\"modal-header\">\n                <h4 class=\"modal-title\"><span data-bind=\"text: $root.editingDataConnection() ? 'Edit' : 'Add a new'\"></span> Data Connection</h4>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <p>Choose User Roles that will have Access</p>\n                <p class=\"small\">Note: All Users will have access if no restricted roles are setup</p>\n\n                <div class=\"form-group row\">\n                    <label class=\"col-md-3 col-sm-3 control-label\">Connection Name</label>\n                    <div class=\"col-md-6 col-sm-6\">\n                        <input class=\"form-control text-box\" data-val=\"true\" data-val-required=\"Connection Name is required.\" type=\"text\" data-bind=\"value: Name\" placeholder=\"\" id=\"add-conn-name\">\n                    </div>\n                </div>\n                <div class=\"form-group row\">\n                    <label class=\"col-md-3 col-sm-3 control-label\">Connection Key</label>\n                    <div class=\"col-md-6 col-sm-6\">\n                        <input class=\"form-control text-box\" data-val=\"true\" data-val-required=\"Connection Key is required.\" type=\"text\" data-bind=\"value: ConnectionKey\" placeholder=\"\" id=\"add-conn-key\">\n                    </div>\n                    <div class=\"col-md-3 col-sm-3\">\n                        <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"This is the Connection Key in your application settings for your SQL Connection String\"></span>\n                    </div>\n                </div>\n                <div class=\"form-group row\" data-bind=\"visible: $root.editingDataConnection\">\n                    <div class=\"check-box col-md-9 col-sm-9\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: UseSchema\">\n                            Use Schema\n                        </label>\n                    </div>\n                    <div class=\"col-md-3 col-sm-3\">\n                        <span data-bs-toggle=\"tooltip\" data-bs-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"Use Schema in SQL when building query\"></span>\n                    </div>\n                </div>\n                <div class=\"form-group row\">\n                    <label class=\"col-md-3 col-sm-3 col-form-label\">Database Type</label>\n                    <div class=\"col-md-6 col-sm-6\">\n                        <select class=\"form-select\" data-bind=\"value: DatabaseType\" required>\n                            <option>MS SQL</option>\n                            <option>MySql</option>\n                            <option>PostgreSQL</option>\n                            <option>Oracle</option>\n                            <option value=\"OleDB\">OleDB/Others</option>\n                        </select>\n                    </div>\n                </div>\n\n                <div class=\"form-group row\" data-bind=\"hidden: $root.editingDataConnection\">\n                    <div class=\"check-box col-md-12\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: copySchema\">\n                            Copy Schema from existing Connection\n                        </label>\n                    </div>\n                </div>\n                <div class=\"form-group row\" data-bind=\"visible: copySchema\">\n                    <label class=\"col-md-3 col-sm-3 control-label\">Choose Connection</label>\n                    <div class=\"col-md-6 col-sm-6\">\n                        <select class=\"form-select\" style=\"max-width: 300px;\" data-bind=\"options: $root.DataConnections, optionsText: 'DataConnectName', optionsValue: 'DataConnectGuid', value: copyFrom\"></select>\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary\" data-bind=\"click: $root.updateDataConnection, visible: $root.editingDataConnection()\">Update</button>\n                <button type=\"button\" class=\"btn btn-secondary\" data-bind=\"click: $root.addDataConnection, visible: !$root.editingDataConnection()\">Create</button>\n            </div>\n        </div>\n    </div>\n</div>\n<div class=\"clearfix\"></div>\n\n<div class=\"modal\" id=\"data-preview-modal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\">\n        <div class=\"modal-content\" data-bind=\"with: previewData\">\n            <div class=\"modal-header\">\n                <h4 class=\"modal-title\">Preview Table</h4>\n                <button type=\"button\" class=\"btn-close float-end\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <div style=\"overflow-x: auto; max-height: 500px; overflow-y: auto;\">\n                    <table class=\"table table-striped table-hover table-condensed\">\n                        <thead style=\"position: sticky; top: -1px; z-index: 2; background-color: #f8f9fa;\">\n                            <tr data-bind=\"foreach: Columns\">\n                                <th>\n                                    <span data-bind=\"text: ColumnName, attr: { title: DataType.replace('System.', '') }\"></span>\n                                </th>\n                            </tr>\n                        </thead>\n                        <tbody data-bind=\"foreach: Rows\">\n                            <tr data-bind=\"foreach: Items\">\n                                <td>\n                                    <span data-bind=\"html: FormattedValue\"></span>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"custom-sql-modal\" tabindex=\"-1\" role=\"dialog\" aria-labelledby=\"myModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\" data-bind=\"with: customSql\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\">Enter Select SQL for your Data</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <div class=\"form-group\" data-bind=\"validationElement: customTableName\">\n                    <label for=\"custom-table-name\">Custom Table Name</label>\n                    <input type=\"text\" class=\"form-control\" name=\"customTableName\" placeholder=\"Enter table name\" data-bind=\"textInput: customTableName\" required>\n                    <div class=\"invalid-feedback\">Custom Table Name is required.</div>\n                </div>\n                <div data-bind=\"visible: useAi\">\n                    <p id=\"query-input\" class=\"query-input\">\n                        Show me&nbsp;\n                    </p>\n                    <button data-bind=\"click: buildSqlUsingAi\" class=\"btn btn-primary btn-sm\">Process with ChatGPT</button>\n                    <button data-bind=\"click: textQuery.resetQuery\" class=\"btn btn-secondary btn-sm\">Start over</button>\n                    <hr />\n                </div>\n\n                <div class=\"form-group\" data-bind=\"validationElement: customSql\">\n                    <label for=\"custom-sql\">Custom SQL</label> |\n                    <label>\n                        <input type=\"checkbox\" data-bind=\"checked: dynamicColumns\">\n                        <span title=\"Setup a table that returns dynamic columns to pick from\">Table with Dynamic Columns</span>\n                    </label> |\n                    <a href=\"#\" data-bind=\"click: beautifySql\">Beautify Sql</a>\n                    <textarea class=\"form-control\" style=\"height: 240px;\" name=\"customSql\" data-bind=\"textInput: customSql\" required></textarea>\n                    <div class=\"invalid-feedback\">Custom SQL is required.</div>\n\n                    <div data-bind=\"if: dynamicColumns\">\n                        <label>Add SQL code to use the dynamic column</label>\n                        <textarea class=\"form-control\" style=\"height: 240px;\" name=\"columnTranslation\" data-bind=\"textInput: columnTranslation\" required></textarea>\n                        <label>Pick Values Table</label>\n                        <select class=\"form-select input-medium\" data-bind=\"options: $root.Tables.availableTables, optionsText: 'DisplayName', optionsValue: 'Id', optionsCaption: 'Choose Values Table...', value: dynamicValuesTableId\"></select>\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: executeSql\">Save changes</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<!-- Import Tables/Views Json File Modal -->\n<div class=\"modal\" id=\"uploadTablesFileModal\" tabindex=\"-1\" aria-labelledby=\"uploadTablesFileModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog\">\n        <div class=\"modal-content\" data-bind=\"with: ManageTablesJsonFile\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"uploadTablesFileModalLabel\">Import Tables/Views (Previously Exported)</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <div id=\"dropzone\" class=\"dropzone\"\n                     data-bind=\"event: {click: triggerTablesFileInput }\"\n                     style=\"border: 2px dashed #007bff; border-radius: 5px; padding: 30px; text-align: center; color: #007bff; cursor: pointer;\">\n                    click to select Json file\n                </div>\n                <input type=\"file\" id=\"tablesFileInputJson\" accept=\".json\" style=\"display: none;\" data-bind=\"event: { change: handleTablesFileSelect }\">\n                <div data-bind=\"visible: fileName\">\n                    <p>Selected Tables/Views File: <span data-bind=\"text: fileName\"></span></p>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Close</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: uploadTablesFile\">Upload</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<!-- Import Joins Json File Modal -->\n<div class=\"modal\" id=\"uploadJoinsFileModal\" tabindex=\"-1\" aria-labelledby=\"uploadJoinsFileModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog\">\n        <div class=\"modal-content\" data-bind=\"with: ManageJoinsJsonFile\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"uploadJoinsFileModalLabel\">Import Joins (Previously Exported)</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <div id=\"dropzone\" class=\"dropzone\"\n                     data-bind=\"event: {click: triggerJoinsFileInput }\"\n                     style=\"border: 2px dashed #007bff; border-radius: 5px; padding: 30px; text-align: center; color: #007bff; cursor: pointer;\">\n                    click to select Json file\n                </div>\n                <input type=\"file\" id=\"joinsFileInputJson\" accept=\".json\" style=\"display: none;\" data-bind=\"event: { change: handleJoinsFileSelect }\">\n                <div data-bind=\"visible: fileName\">\n                    <p>Selected Joins File: <span data-bind=\"text: fileName\"></span></p>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Close</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: uploadJoinsFile\">Upload</button>\n            </div>\n        </div>\n    </div>\n</div>\n<!-- Import StoredProcedures Json File Modal -->\n<div class=\"modal\" id=\"uploadStoredProceduresFileModal\" tabindex=\"-1\" aria-labelledby=\"uploadStoredProceduresFileModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog\">\n        <div class=\"modal-content\" data-bind=\"with: ManageStoredProceduresJsonFile\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"uploadStoredProceduresFileModalLabel\">Import Stored Procedures (Previously Exported)</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <div id=\"dropzone\" class=\"dropzone\"\n                     data-bind=\"event: {click: triggerStoredProceduresFileInput }\"\n                     style=\"border: 2px dashed #007bff; border-radius: 5px; padding: 30px; text-align: center; color: #007bff; cursor: pointer;\">\n                    click to select Json file\n                </div>\n                <input type=\"file\" id=\"storedProceduresFileInputJson\" accept=\".json\" style=\"display: none;\" data-bind=\"event: { change: handleStoredProceduresFileSelect }\">\n                <div data-bind=\"visible: fileName\">\n                    <p>Selected Stored Procedures File: <span data-bind=\"text: fileName\"></span></p>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Close</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: uploadStoredProceduresFile\">Upload</button>\n            </div>\n        </div>\n    </div>\n</div>\n<div class=\"modal\" id=\"searchModal\" tabindex=\"-1\" aria-hidden=\"true\" data-bind=\"with: $root\">\n    <div class=\"modal-dialog modal-xl modal-dialog-scrollable\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\">Bulk Manage Reports Access and Export</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <div class=\"d-flex gap-2 mb-4 align-items-center\">\n                    <input type=\"text\" class=\"form-control\" placeholder=\"Search Reports\"\n                           data-bind=\"value: searchQuery, valueUpdate: 'input'\">\n                    <button class=\"btn btn-sm btn-outline-primary flex-shrink-0\" title=\"Select all Filtered\"\n                            data-bind=\"click: selectAllFiltered\">\n                        Select All\n                    </button>\n                    <button class=\"btn btn-sm btn-outline-secondary flex-shrink-0\" title=\"Deselect all Filtered\"\n                            data-bind=\"click: deselectAllFiltered\">\n                        Deselect All\n                    </button>\n                </div>\n                <div data-bind=\"foreach: filteredReportsAndFolders\">\n                    <div class=\"card mb-3\">\n                        <div class=\"card-header\">\n                            <div class=\"d-flex fw-bold\">\n                                <div class=\"w-50 flex-grow-1\">\n                                    <input type=\"checkbox\" data-bind=\"checked: allReportsSelected\">\n                                    <span data-bind=\"text: folder\"></span>\n                                </div>\n                                <div class=\"w-25\">View</div>\n                                <div class=\"w-25\">Manage</div>\n                                <div class=\"w-25\">Delete</div>\n                                <div class=\"w-25\">Client ID</div>\n                            </div>\n                        </div>\n                        <!-- Reports List -->\n                        <ul class=\"list-group list-group-flush\" data-bind=\"foreach: reports\">\n                            <li class=\"list-group-item\">\n                                <div class=\"d-flex align-items-center\">\n                                    <div class=\"w-50 flex-grow-1\">\n                                        <input type=\"checkbox\" data-bind=\"checked: isSelected\">\n                                        <span data-bind=\"text: reportName\"></span>\n                                    </div>\n                                    <div class=\"w-25\">\n                                        <span class=\"badge text-bg-info text-white\" data-bind=\"text: viewOnlyUserRole ? viewOnlyUserRole: 'Any User'\"></span>\n                                    </div>\n                                    <div class=\"w-25\">\n                                        <span class=\"badge text-bg-info text-white\" data-bind=\"text: userRole ? userRole : 'Any User'\"></span>\n                                    </div>\n                                    <div class=\"w-25\">\n                                        <span class=\"badge text-bg-info text-white\" data-bind=\"text: deleteOnlyUserRole ? deleteOnlyUserRole : 'Any User'\"></span>\n                                    </div>\n                                    <div class=\"w-25\">\n                                        <span class=\"badge text-bg-info text-white\" data-bind=\"text: clientId ? clientId : 'Any User'\"></span>\n                                    </div>\n                                </div>\n                            </li>\n                        </ul>\n                        <div class=\"p-2 text-muted\" data-bind=\"visible: reports.length === 0\">\n                            No matching reports found\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Close</button>\n                <button class=\"btn btn-success\" data-bind=\"click: exportFoldersReportJson\">Export Selected</button>\n                <button class=\"btn btn-primary\" data-bind=\"click: $root.openApplySecurityModal, enable: $root.anyReportSelected\">Apply Security to All Selected</button>\n                <button class=\"btn btn-primary\" data-bind=\"click: $root.deleteSelectedItems, enable: $root.anyReportSelected\">Delete All Selected</button>\n            </div>\n        </div>\n    </div>\n</div>\n<div class=\"modal\" id=\"applySecurityModal\" tabindex=\"-1\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\" data-bind=\"if: $root.anyReportSelected\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\">Apply Security to All Selected</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <div data-bind=\"template: { name: 'manage-access-template', data: $root.manageAccess }\"></div>\n            </div>\n            <div class=\"modal-footer\">\n                <button class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Close</button>\n                <button class=\"btn btn-primary\" data-bind=\"click: $root.applySecurityToAll\">Apply to All</button>\n            </div>\n        </div>\n    </div>\n</div>\n<!-- Import Json File Modal -->\n<div class=\"modal\" id=\"uploadFileModal\" tabindex=\"-1\" aria-labelledby=\"uploadFileModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog\">\n        <div class=\"modal-content\" data-bind=\"with: ManageJsonFile\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"uploadFileModalLabel\">Import previously Exported Reports</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n\n                <div class=\"alert alert-info small\">\n                    <strong>Instructions:</strong><br />\n                    • Select a <code>.json</code> file previously exported from Dotnet Report.<br />\n                    • The file may include multiple reports and their folders.<br />\n                    • Any missing folders will be created automatically.<br />\n                    • If a report with the same name already exists, you will be prompted to:\n                    <em>Skip</em>, <em>Overwrite</em>, or <em>Make a Copy</em>.<br />\n                    • Once uploaded, all imported reports will be available immediately.\n                </div>\n\n                <div id=\"dropzone\" class=\"dropzone\"\n                     data-bind=\"event: {click: triggerFileInput }\"\n                     style=\"border: 2px dashed #007bff; border-radius: 5px; padding: 30px; text-align: center; color: #007bff; cursor: pointer;\">\n                    Click here to select a JSON file\n                </div>\n\n                <input type=\"file\" id=\"fileInputJson\" accept=\".json\" style=\"display: none;\"\n                       data-bind=\"event: { change: handleFileSelect }\">\n\n                <div class=\"mt-3\" data-bind=\"visible: fileName\">\n                    <p><strong>Selected File:</strong> <span data-bind=\"text: fileName\"></span></p>\n                </div>\n\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Close</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: uploadFile\">Upload</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"sentHistoryModal\" tabindex=\"-1\" role=\"dialog\">\n    <div class=\"modal-dialog modal-xl modal-dialog-scrollable\" role=\"document\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\"><i class=\"fa fa-history\"></i> Schedule Send History</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <div class=\"row g-2 align-items-end mb-3 border-bottom pb-2\">\n                    <div class=\"col-sm-3\">\n                        <label class=\"form-label small mb-0\">From</label>\n                        <input type=\"date\" class=\"form-control form-control-sm\" data-bind=\"value: sentHistoryStartDate\" />\n                    </div>\n                    <div class=\"col-sm-3\">\n                        <label class=\"form-label small mb-0\">To</label>\n                        <input type=\"date\" class=\"form-control form-control-sm\" data-bind=\"value: sentHistoryEndDate\" />\n                    </div>\n                    <div class=\"col-sm-auto\">\n                        <button class=\"btn btn-sm btn-primary\" data-bind=\"click: function() { loadSentHistory(1); }, enable: !sentHistoryLoading()\">Search</button>\n                        <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: function() { sentHistoryStartDate(''); sentHistoryEndDate(''); loadSentHistory(1); }, enable: !sentHistoryLoading()\">Clear</button>\n                    </div>\n                </div>\n                <div data-bind=\"visible: sentHistoryLoading() && sentHistory().length === 0\" class=\"text-center py-3 text-muted\">\n                    <i class=\"fa fa-spinner fa-spin\"></i> Loading...\n                </div>\n                <div data-bind=\"visible: !sentHistoryLoading() && sentHistory().length === 0\" class=\"text-center py-3 text-muted\">\n                    <i class=\"fa fa-inbox\"></i> No history for this range.\n                </div>\n                <div data-bind=\"visible: sentHistory().length > 0\">\n                    <table class=\"table table-sm table-striped\">\n                        <thead>\n                            <tr>\n                                <th>When</th>\n                                <th>Type</th>\n                                <th>Name</th>\n                                <th>Sent To</th>\n                                <th>Format</th>\n                                <th>Result</th>\n                                <th>Message</th>\n                            </tr>\n                        </thead>\n                        <tbody data-bind=\"foreach: sentHistory\">\n                            <tr>\n                                <td><small data-bind=\"text: created\"></small></td>\n                                <td><span class=\"badge bg-secondary\" data-bind=\"text: itemType\"></span></td>\n                                <td data-bind=\"text: itemName || ('#' + (itemId || ''))\"></td>\n                                <td><small data-bind=\"text: sentTo\"></small></td>\n                                <td data-bind=\"text: format\"></td>\n                                <td>\n                                    <span data-bind=\"css: isError ? 'badge bg-danger' : (result === 'Triggered' ? 'badge bg-info' : 'badge bg-success'), text: result\"></span>\n                                </td>\n                                <td><small class=\"text-muted\" data-bind=\"text: message\"></small></td>\n                            </tr>\n                        </tbody>\n                    </table>\n                    <div class=\"d-flex justify-content-between align-items-center mt-2\">\n                        <small class=\"text-muted\">\n                            Page <span data-bind=\"text: sentHistoryPage\"></span> of <span data-bind=\"text: sentHistoryTotalPages\"></span>\n                            (<span data-bind=\"text: sentHistoryTotal\"></span> total)\n                        </small>\n                        <div>\n                            <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function() { loadSentHistory(sentHistoryPage() - 1); }, enable: sentHistoryPage() > 1 && !sentHistoryLoading()\">\n                                <i class=\"fa fa-chevron-left\"></i> Prev\n                            </button>\n                            <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function() { loadSentHistory(sentHistoryPage() + 1); }, enable: sentHistoryPage() < sentHistoryTotalPages() && !sentHistoryLoading()\">\n                                Next <i class=\"fa fa-chevron-right\"></i>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: function() { loadSentHistory(sentHistoryPage()); }\">\n                    <span class=\"fa fa-refresh\"></span> Refresh\n                </button>\n                <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Close</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n\n\n<div class=\"modal\" id=\"email-query-modal\" role=\"dialog\" tabindex=\"-1\" data-bind=\"with: emailQueries\">\n    <div class=\"modal-dialog modal-lg\" role=\"document\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" data-bind=\"text: current().id() > 0 ? 'Edit Email List' : 'Add Email List'\"></h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body needs-validation\" data-bind=\"with: current\">\n                <div class=\"mb-3 form-group\">\n                    <label class=\"form-label\">Name</label>\n                    <input type=\"text\" class=\"form-control\" name=\"emailQueryName\" data-bind=\"textInput: name\" placeholder=\"e.g. Site Managers\" required />\n                    <div class=\"invalid-feedback\">Name is required.</div>\n                </div>\n                <div class=\"mb-3\">\n                    <label class=\"form-label\">Description</label>\n                    <input type=\"text\" class=\"form-control\" data-bind=\"value: description\" placeholder=\"Optional\" />\n                </div>\n                <div class=\"mb-3\">\n                    <label class=\"form-label\">Client Id</label>\n                    <input type=\"text\" class=\"form-control\" data-bind=\"value: clientId\" placeholder=\"Leave blank to make this available to all clients\" />\n                </div>\n                <div class=\"mb-2 form-group\">\n                    <label class=\"form-label\">SQL Query</label>\n                    <textarea class=\"form-control\" rows=\"8\" style=\"font-family: monospace;\" name=\"emailQuerySql\" data-bind=\"textInput: sqlQuery\" placeholder=\"SELECT Email FROM Users WHERE IsActive = 1\" required></textarea>\n                    <div class=\"invalid-feedback\">SQL Query is required.</div>\n                    <div class=\"form-text\">Read only SELECT returning one row per email, with an <code>Email</code> column.</div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light btn-sm me-auto\" data-bind=\"click: previewCurrentQuery\"\n                        title=\"Run the query above and show the emails it returns\">\n                    <i class=\"fa fa-search\"></i> Preview Emails\n                </button>\n                <button type=\"button\" class=\"btn btn-secondary btn-sm\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-primary btn-sm\" data-bind=\"click: saveQuery\">Save</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n\n\n\n<div class=\"modal\" id=\"users-roles-sql-modal\" role=\"dialog\" tabindex=\"-1\" data-bind=\"with: usersRoles\">\n    <div class=\"modal-dialog modal-lg\" role=\"document\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\"><span data-bind=\"text: currentSql().savedId() > 0 ? 'Edit' : 'Add'\"></span> <span data-bind=\"text: currentSql().title\"></span></h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body needs-validation\" data-bind=\"with: currentSql\">\n                <div class=\"mb-2 form-group\">\n                    <label class=\"form-label\">SQL Query</label>\n                    <textarea class=\"form-control\" rows=\"10\" style=\"font-family: monospace;\" name=\"usersRolesSql\"\n                        data-bind=\"textInput: draft, attr: { placeholder: placeholder }\" required></textarea>\n                    <div class=\"invalid-feedback\">SQL Query is required.</div>\n                    <div class=\"form-text\">Read only SELECT. <span data-bind=\"text: hint\"></span></div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light btn-sm me-auto\" data-bind=\"click: previewCurrentSql\"\n                    title=\"Run the query above and show the rows it returns\">\n                    <i class=\"fa fa-search\"></i> Preview\n                </button>\n                <button type=\"button\" class=\"btn btn-light btn-sm\" data-bind=\"click: beautifyCurrentSql\" title=\"Format the SQL above\">\n                    <i class=\"fa fa-magic\"></i> Beautify Sql\n                </button>\n                <button type=\"button\" class=\"btn btn-secondary btn-sm\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-primary btn-sm\" data-bind=\"click: saveSqlSource\">Save</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<!-- Templates -->\n<!-- Dotnet Report HTML Templates -->\n<script type=\"text/html\" id=\"report-filter\">\n    <div class=\"form-group\" data-bind=\"attr: {id: 'filter-'+uiId }\">\n        <!-- ko if: !hasForeignKey-->\n        <!-- ko if: ['DateTime','Date','Time'].indexOf(fieldType) != -1 -->\n        <div style=\"display: flex; align-items: center; gap: 8px;\">\n            <!-- ko if: ['=','>','<','>=','<=', 'not equal'].indexOf($parent.Operator()) != -1 -->\n            <input class=\"form-control\" data-bind=\"datepicker: $parent.fmtValue, datepickerOptions: {value: $parent.Value, dateFormat: (['Date','Date and Time','Time'].indexOf(fieldFormat()) >= 0 && dateFormat() && dateFormat() !== 'Custom') ? $root.dateFormatMappings[dateFormat()] : $root.dateFormatMappings[($root.appSettings && $root.appSettings.defaultDateFormat) || 'United States']}\" required />\n            <!-- ko if: fieldType=='Time' || fieldFormat()=='Time' || fieldFormat()=='Date and Time'-->\n            <input class=\"form-control\" type=\"time\" data-bind=\"value:$parent.Valuetime\" required>\n            <!-- /ko -->\n            <!-- /ko -->\n        </div>\n        <!-- ko if: ['between'].indexOf($parent.Operator()) != -1 -->\n        From\n        <div style=\"display: flex; align-items: center; gap: 8px;\">\n            <input required class=\"form-control from-date\" data-bind=\"datepicker: $parent.fmtValue, datepickerOptions: {value: $parent.Value, dateFormat: (['Date','Date and Time','Time'].indexOf(fieldFormat()) >= 0 && dateFormat() && dateFormat() !== 'Custom') ? $root.dateFormatMappings[dateFormat()] : $root.dateFormatMappings[($root.appSettings && $root.appSettings.defaultDateFormat) || 'United States']}\" />\n            <!-- ko if:fieldType=='Time' || fieldFormat()=='Time' || fieldFormat()=='Date and Time'-->\n            <input class=\"form-control\" type=\"time\" data-bind=\"value:$parent.Valuetime\" required>\n            <!-- /ko -->\n        </div>\n        to\n        <div style=\"display: flex; align-items: center; gap: 8px;\">\n            <input data-bind=\"datepicker: $parent.fmtValue2, datepickerOptions: {value: $parent.Value2, dateFormat: (['Date','Date and Time','Time'].indexOf(fieldFormat()) >= 0 && dateFormat() && dateFormat() !== 'Custom') ? $root.dateFormatMappings[dateFormat()] : $root.dateFormatMappings[($root.appSettings && $root.appSettings.defaultDateFormat) || 'United States']}\" class=\"form-control to-date\" required />\n            <!-- ko if:fieldType=='Time' || fieldFormat()=='Time' || fieldFormat()=='Date and Time'-->\n            <input class=\"form-control\" type=\"time\" data-bind=\"value:$parent.Valuetime2\" required>\n            <!-- /ko -->\n        </div>\n        <!-- /ko -->\n        <!-- ko if: ['range'].indexOf($parent.Operator()) != -1 -->\n        <select data-bind=\"value: $parent.Value\" class=\"form-select\" required>\n            <option value=\"\"></option>\n            <option>Today</option>\n            <option>Today +</option>\n            <option>Today -</option>\n            <option>Yesterday</option>\n            <option>This Week</option>\n            <option>Last Week</option>\n            <option>This Month</option>\n            <option>Last Month</option>\n            <option>This Year</option>\n            <option>Last Year</option>\n            <option>This Week To Date</option>\n            <option>This Month To Date</option>\n            <option>This Year To Date</option>\n            <option>Last 30 Days</option>\n            <!--<option>This Month Last Year</option>\n            <option>Last Month Last Year</option>\n            <option>This Quarter</option>\n            <option>Last Quarter</option>\n            <option>First Quarter</option>\n            <option>Second Quarter</option>\n            <option>Third Quarter</option>\n            <option>Fourth Quarter</option>\n            <option>Next 6 Months</option>\n            <option>Last 6 Months</option>\n            <option>2 Years ago</option>\n            <option>3 Years ago</option>\n            <option>4 Years ago</option>\n            <option>5 Years ago</option>-->\n            <optgroup label=\"Comparison Options\">\n                <option>>= Today</option>\n                <option><= Today</option>\n                <option>>= Today +</option>\n                <option><= Today +</option>\n                <option>>= Today -</option>\n                <option><= Today -</option>\n            </optgroup>\n        </select>\n        <div data-bind=\"if: $parent.Value().indexOf('Today +') >= 0 || $parent.Value().indexOf('Today -') >= 0\" class=\"form-group float-start\" style=\"padding-top: 5px;\">\n            <input type=\"number\" class=\"form-control input-sm float-start\" style=\"width: 80px;\" data-bind=\"value: $parent.Value2\" required /><span style=\"padding: 5px 5px;\" class=\"float-start\"> days</span>\n        </div>\n        <!-- /ko -->\n        <!-- /ko -->\n        <!-- ko if: ['Int','Money','Float','Double'].indexOf(fieldType) != -1 -->\n            <!-- ko if: ['=','>','<','>=','<=', 'not equal'].indexOf($parent.Operator()) != -1 && ['is blank', 'is not blank', 'is null', 'is not null'].indexOf($parent.Operator()) == -1 -->\n            <input class=\"form-control\" type=\"number\" data-bind=\"value: $parent.Value, disable: $parent.Operator() == 'is default'\" required />\n            <!-- /ko -->\n             <!-- ko if: ['in', 'not in'].indexOf($parent.Operator()) != -1 -->\n            <input class=\"form-control\" type=\"text\" data-bind=\"value: $parent.Value\" required />\n            <!-- /ko -->\n            <!-- ko if: ['between'].indexOf($parent.Operator()) != -1 -->\n            From\n            <input class=\"form-control\" type=\"number\" data-bind=\"value: $parent.Value\" required />\n            To\n            <input class=\"form-control\" type=\"number\" data-bind=\"value: $parent.Value2\" required />\n        <!-- /ko -->\n        <!-- /ko -->\n        <!-- ko if: fieldType=='Boolean' && ['is blank', 'is not blank', 'is null', 'is not null'].indexOf($parent.Operator()) == -1 -->\n        <select required class=\"form-select\" data-bind=\"value: $parent.Value, disable: $parent.Operator() == 'is default'\">\n            <option value=\"1\">Yes</option>\n            <option value=\"0\">No</option>\n        </select>\n        <!-- /ko -->\n        <!-- ko if: ['Int','Money','Float','Double','Date','DateTime','Time','Boolean'].indexOf(fieldType) == -1 && ['is blank', 'is not blank', 'is null', 'is not null'].indexOf($parent.Operator()) == -1 -->\n        <input class=\"form-control\" type=\"text\" data-bind=\"value: $parent.Value, disable: $parent.Operator() == 'is default',attr: {id: 'ctl-' + $element.closest('[data-parentprefix]').getAttribute('data-parentprefix') + '-' + ($parent.uiId || uiId)}\" required />\n        <!-- /ko -->\n        <!-- /ko -->\n        <!-- ko if: hasForeignKey && $parent.Operator() != 'all' && $parent.Operator() != 'none' && $parent.Operator() != 'no filter' -->\n        <!-- ko if: hasForeignParentKey && $parent.showParentFilter() -->\n        <select multiple class=\"form-control\" data-bind=\"select2: { dropdownParent: '#filter-'+uiId, placeholder: 'Please Choose', allowClear: true }, lookupSearch: $parent.SearchParentList, options: $parent.ParentList, optionsText: 'text', optionsValue: $parent.IsConditionalFilter ? 'text': 'id', selectedOptions: $parent.ParentIn\"></select>\n        <!-- /ko -->\n        <!-- ko if: $parent.Operator()=='='-->\n        <select required class=\"form-control\" data-bind=\"select2: { dropdownParent: '#filter-'+uiId, placeholder: 'Please Choose', allowClear: true }, lookupSearch: $parent.SearchLookupList, options: $parent.LookupList, optionsText: 'text', optionsValue:   $parent.IsConditionalFilter ? 'text': 'id', value: $parent.Value, optionsCaption: 'Please Choose'\"></select>\n        <!-- /ko -->\n        <!-- ko if: $parent.Operator()=='in' || $parent.Operator()=='not in'-->\n        <select required multiple class=\"form-control\" data-bind=\"select2: { dropdownParent: '#filter-'+uiId, placeholder: 'Please Choose', allowClear: true }, lookupSearch: $parent.SearchLookupList, options: $parent.LookupList, optionsText: 'text', optionsValue: $parent.IsConditionalFilter ? 'text': 'id', selectedOptions: $parent.ValueIn\"></select>\n        <!-- /ko -->\n        <!-- /ko -->\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"pager-template\">\n    <div class=\"pager-container d-flex align-items-center flex-wrap gap-2\">\n\n        <!-- Rows per page -->\n        <div class=\"d-flex align-items-center gap-1 ms-1\">\n            <span class=\"text-muted small\">Page size:</span>\n            <select class=\"form-select form-select-sm w-auto\"\n                    data-bind=\"options: pageSizeOptions, value: pageSize\">\n            </select>\n        </div>\n\n        <!-- Inner border block for page navigation controls -->\n        <div class=\"d-flex align-items-center gap-1 ms-3\">\n            <a href=\"#\" title=\"First\" data-bind=\"click: first, enable: !isFirstPage()\"\n               class=\"btn btn-outline-secondary btn-sm pager-btn ms-1\" aria-label=\"First Page\">\n                <i class=\"fa fa-angle-double-left\"></i>\n            </a>\n\n            <a href=\"#\" title=\"Previous\" data-bind=\"click: previous, enable: !isFirstPage()\"\n               class=\"btn btn-outline-secondary btn-sm pager-btn\" aria-label=\"Previous Page\">\n                <i class=\"fa fa-angle-left\"></i>\n            </a>\n\n            <div class=\"d-flex align-items-center gap-1\">\n                <span class=\"text-muted small\">Page</span>\n                <input type=\"number\" min=\"1\" pattern=\"[0-9]*\"\n                       class=\"form-control form-control-sm text-center pager-input\"\n                       style=\"width: 60px;\"\n                       data-bind=\"value: currentPage, attr: { max: pages() }\">\n                <span class=\"text-muted small\">of</span>\n                <span class=\"text-muted small\" data-bind=\"text: pages\"></span>\n            </div>\n\n            <a href=\"#\" title=\"Next\" data-bind=\"click: next, enable: !isLastPage()\"\n               class=\"btn btn-outline-secondary btn-sm pager-btn\" aria-label=\"Next Page\">\n                <i class=\"fa fa-angle-right\"></i>\n            </a>\n\n            <a href=\"#\" title=\"Last\" data-bind=\"click: last, enable: !isLastPage()\"\n               class=\"btn btn-outline-secondary btn-sm pager-btn\" aria-label=\"Last Page\">\n                <i class=\"fa fa-angle-double-right\"></i>\n            </a>\n        </div>\n    </div>\n</script>\n\n\n\n<script type=\"text/html\" id=\"report-column-header\">\n    <!-- ko foreach: Columns -->\n    <th data-bind=\"attr: { id: !IsPivotField ? fieldId : 'pivot--' + fieldName }, style: {'text-align': fieldAlign() ? fieldAlign() : (IsNumeric ? 'right' : 'left'), 'background-color': headerBackColor }, hidden: outerGroup\" style=\"border-right: 1px solid;\">\n\n        <!-- ko if: !$parent.IsDrillDown() && !$parent.IsSubReport() -->\n        <div class=\"float-start\" style=\"padding-right: 5px;\">\n            <div class=\"dropup\">\n                <a href=\"#\" data-bs-toggle=\"dropdown\" aria-haspopup=\"false\" aria-expanded=\"false\">\n                    <span class=\"fa fa-ellipsis-v sortable\" title=\"Drag to reorder\"></span>\n                </a>\n                <ul data-bind=\"visible: !IsPivotField\" class=\"dropdown-menu field-quick-menu\" style=\"z-index: 1001; min-width: 170px;\">\n                    <li class=\"dropdown-item small px-2 py-1\">\n                        <div class=\"field-quick-row\">\n                            <span class=\"field-quick-label\">Align</span>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Align Left\"\n                                    data-bind=\"click: function(){ fieldAlign('Left'); }, css: {'active': fieldAlign() === 'Left'}, clickBubble: false\">\n                                <i class=\"fa fa-align-left\"></i>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Align Center\"\n                                    data-bind=\"click: function(){ fieldAlign('Center'); }, css: {'active': fieldAlign() === 'Center'}, clickBubble: false\">\n                                <i class=\"fa fa-align-center\"></i>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Align Right\"\n                                    data-bind=\"click: function(){ fieldAlign('Right'); }, css: {'active': fieldAlign() === 'Right'}, clickBubble: false\">\n                                <i class=\"fa fa-align-right\"></i>\n                            </button>\n                        </div>\n                    </li>\n                    <li class=\"dropdown-item small px-2 py-1\" data-bind=\"visible: IsNumeric\">\n                        <div class=\"field-quick-row\">\n                            <span class=\"field-quick-label\">Format</span>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Currency\"\n                                    data-bind=\"click: function(){ fieldFormat(fieldFormat() === 'Currency' ? 'Auto' : 'Currency'); }, css: {'active': fieldFormat() === 'Currency'}, clickBubble: false\">\n                                <i class=\"fa fa-dollar\"></i>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary field-quick-btn\" title=\"Percentage\"\n                                    data-bind=\"click: function(){ fieldFormat(fieldFormat() === 'Percentage' ? 'Auto' : 'Percentage'); }, css: {'active': fieldFormat() === 'Percentage'}, clickBubble: false\">\n                                <i class=\"fa fa-percent\"></i>\n                            </button>\n                        </div>\n                    </li>\n                    <li><hr class=\"dropdown-divider my-1\"></li>\n                    <li class=\"dropdown-item small\" data-bind=\"visible: !IsNumeric\">\n                        <a href=\"#\" data-bind=\"click: toggleOuterGroup\">\n                            <span class=\"fa fa-clone\"></span> Outer Group\n                        </a>\n                    </li>\n                    <li class=\"dropdown-item small\">\n                        <a href=\"#\" data-bind=\"click: setupFieldOptions\">\n                            <span class=\"fa fa-gear\"></span> More Settings\n                        </a>\n                    </li>\n                </ul>\n            </div>\n        </div>\n        <!-- /ko -->\n        <div data-bind=\"style: {'width': fieldWidth}\">\n            <!-- ko if: $parents[3].useStoredProc ? $parents[3].useStoredProc() : ($parents[5].useStoredProc ? $parents[5].useStoredProc() : false) -->\n            <span data-bind=\"text: fieldLabel() ? fieldLabel() : fieldName, style: {'color': headerFontColor, 'font-weight': headerFontBold() ? 'bold' : 'normal'}\"></span>\n            <!-- /ko -->\n            <!-- ko ifnot: $parents[3].useStoredProc ? $parents[3].useStoredProc() : ($parents[5].useStoredProc ? $parents[5].useStoredProc() : false)  -->\n            <a href=\"\" data-bind=\"click: function(){ if (!IsPivotField) { $parents[pagerIndex($parents)].changeSort(SqlField); } }, style: {'color': headerFontColor, 'font-weight': headerFontBold() ? 'bold' : 'normal'}\">\n                <span data-bind=\"text: $parent.IsDrillDown() && fieldLabel2() ? fieldLabel2() : (fieldLabel() ? fieldLabel() : fieldName)\"></span>\n                <span data-bind=\"text: $parents[pagerIndex($parents)].pager.sortColumn() === SqlField ? ($parents[pagerIndex($parents)].pager.sortDescending() ? '&#9660;' : '&#9650;') : ''\"></span>\n            </a>\n            <!-- /ko -->\n        </div>\n    </th>\n    <!-- /ko -->\n</script>\n\n<script type=\"text/html\" id=\"report-widget\">\n    <div data-bind=\"style: { 'font-size': (FontSize ? FontSize : '48px'),'text-align': Alignment ? Alignment : 'center','color': FontColor ? FontColor : '#000000','background-color':BackColor ? BackColor : '#fff' }\" style=\"width: 100%;\">\n        <span data-bind=\"visible: Rows.length < 1\" title=\"No data found\">/</span>\n\n        <div data-bind=\"if: Rows.length > 0\">\n            <div data-bind=\"with: $parent.rows[0].Items[0]\">\n                <span class=\"preserve-space\" data-bind=\"html: $parent.formatKpiValue(Value, formattedVal())\"></span>\n\n                <!-- ko if: $parent.Rows.length > 1 ? ($parents[$parents.length-2].showPriorInKpi != undefined ? $parents[$parents.length-2].showPriorInKpi() : $parents[$parents.length-1].showPriorInKpi()) : false -->\n                <div data-bind=\"style: {'font-size': '20px'}\" class=\"text-muted\">\n                    <span data-bind=\"text: $parent.comparisonLabel\"></span>: <span class=\"preserve-space\" data-bind=\"html: $parent.formatKpiValue($parent.Rows[1].Items[0].Value, $parent.Rows[1].Items[0].formattedVal)\"></span>\n                    <span data-bind=\"style: {'color': $parent.calculateRate() > 0 ? $parent.PositiveColor : $parent.NegativeColor, 'font-size': '20px'}\">\n                        <i data-bind=\"css: $parent.calculateRate() > 0 ? 'fa fa-arrow-up' : 'fa fa-arrow-down'\"></i>\n                        <span data-bind=\"html: Math.abs($parent.calculateRate()) + '%'\"></span>\n                    </span>\n                </div>\n                <!-- /ko -->\n\n            </div>\n        </div>\n    </div>\n\n</script>\n<script type=\"text/html\" id=\"kpi-settings\">\n    <div class=\"chart-container float-end\">\n        <button class=\"btn btn-light btn-sm d-flex align-items-center mt-2 chart-settings-btn\"\n                data-bind=\"click: toggleKpiSettings()\" title=\"KPI Settings\">\n            <i class=\"fa fa-cog\"></i>\n        </button>\n        <div class=\"kpi-settings-panel border p-2 shadow-sm bg-light\"\n             data-bind=\"visible: showKpiSettings\">\n            <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                <button class=\"btn btn-sm btn-close\" data-bind=\"click: toggleKpiSettings()\"></button>\n                <h6 class=\"mb-0\">KPI Settings</h6>\n            </div>\n            <ul class=\"nav nav-tabs nav-sm mb-2 small\">\n                <li class=\"nav-item\">\n                    <a class=\"nav-link active\"\n                       data-bs-toggle=\"tab\"\n                       data-bind=\"attr: { href: '#kpiTab-' + ReportID() }\">\n                        KPI\n                    </a>\n                </li>\n            </ul>\n            <div class=\"tab-content small\">\n                <!-- KPI Tab -->\n                <div class=\"tab-pane fade show active\"\n                     data-bind=\"attr: { id: 'kpiTab-' + ReportID() }\">\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Font Size</label>\n                        <input type=\"number\"\n                               class=\"form-control form-control-sm\"\n                               min=\"10\" max=\"100\"\n                               data-bind=\"value: kpiSettings().fontSize, event: { input: updateKpi }\">\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Alignment</label>\n                        <select class=\"form-select form-select-sm\"\n                                data-bind=\"value: kpiSettings().alignment, event: { change: updateKpi }\">\n                            <option value=\"left\">Left</option>\n                            <option value=\"center\">Center</option>\n                            <option value=\"right\">Right</option>\n                        </select>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Font Color</label>&nbsp;&nbsp;&nbsp;&nbsp;\n                        <label class=\"form-label small\">Back Color</label><br />\n                        <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: kpiSettings().fontColor,event: { change: updateKpi }\"/>\n                               &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n                        <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: kpiSettings().backColor,event: { change: updateKpi }\"/>\n                    </div>\n                    <div data-bind=\"visible:showPriorInKpi()\" class=\"mb-2\">\n                        <label class=\"form-label small\">Rate Color (+ / -)</label><br />\n                        <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: kpiSettings().positiveColor, event: { change: updateKpi }\"/> +\n                        <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: kpiSettings().negativeColor, event: { change: updateKpi }\"/> -\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Number Format</label>\n                        <select class=\"form-select form-select-sm\"\n                                data-bind=\"value: kpiSettings().numberFormat, event: { change: updateKpi }\">\n                            <option value=\"number\">Number</option>\n                            <option value=\"currency\">Currency</option>\n                            <option value=\"custom\">Custom Format</option>\n                        </select>\n                        <input type=\"text\"\n                               class=\"form-control form-control-sm mt-2\"\n                               placeholder=\"e.g. #,###.00\"\n                               data-bind=\"value: kpiSettings().customFormat,\n                                          visible: kpiSettings().numberFormat() === 'custom',\n                                          valueUpdate:'input',\n                                          event:{ input:updateKpi }\">\n                    </div>\n                    <div data-bind =\"visible: kpiSettings().numberFormat() === 'currency'\" class=\"mb-2\">\n                        <label class=\"form-label small\">Currency Symbol</label>\n                        <select class=\"form-select form-select-sm\"\n                                data-bind=\"value: kpiSettings().currencySymbol,event:{ change:updateKpi }\">\n                            <option value=\"$\">USD ($)</option>\n                            <option value=\"€\">Euro (€)</option>\n                            <option value=\"£\">Pound (£)</option>\n                            <option value=\"₹\">Indian Rupee (₹)</option>\n                            <option value=\"Rs\">Rupee (Rs)</option>\n                        </select>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Short Format</label>\n                        <select class=\"form-select form-select-sm\"\n                                data-bind=\"value: kpiSettings().shortFormat,event:{ change:updateKpi }\">\n                            <option value=\"none\">None</option>\n                            <option value=\"thousand\">Thousands (K)</option>\n                            <option value=\"million\">Millions (M)</option>\n                            <option value=\"billion\">Billions (B)</option>\n                        </select>\n                    </div>\n                    <div class=\"d-flex justify-content-end mb-2\">\n                        <button class=\"btn btn-sm\"\n                                data-bind=\"click: copyKpiFormat\"\n                                title=\"Copy Format\">\n                            <i class=\"fa fa-copy\"></i>\n                        </button>\n                        <button class=\"btn btn-sm\"\n                                data-bind=\"click: pasteKpiFormat\"\n                                title=\"Paste Format\">\n                            <i class=\"fa fa-paste\"></i>\n                        </button>\n                         <button class=\"btn btn-sm\"\n                                data-bind=\"click: clearKpiSettings\"\n                                title=\"Clear\">\n                                <i class=\"fa fa-close\"></i>\n                        </button>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"report-column\">\n    <!-- ko foreach: Items -->\n    <td data-bind=\"hidden: outerGroup, style: {'background-color': _backColor ?? backColor(), 'color': _fontColor ?? fontColor(), 'font-weight': fontBold() || _fontBold ? 'bold' : 'normal', 'text-align': fieldAlign() ? fieldAlign() : (Column.IsNumeric ? 'right' : 'left')}\">\n        <div data-bind=\"style: {'width': fieldWidth }, css: { 'text-wrap': fieldWidth }\">\n            <!-- ko if: LinkTo-->\n            <!-- ko if: $data._runLinkedReportInPlace -->\n            <a href=\"#\" data-bind=\"click: $data._runLinkedReportInPlace\"><span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span></a>\n            <!-- /ko -->\n            <!-- ko ifnot: $data._runLinkedReportInPlace -->\n            <a data-bind=\"attr: {href: LinkTo}\" target=\"_blank\"><span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span></a>\n            <!-- /ko -->\n            <!-- /ko-->\n            <!-- ko ifnot: LinkTo-->\n            <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n            <!-- /ko-->\n        </div>\n    </td>\n</script>\n\n<script type=\"text/html\" id=\"report-pivot\">\n    <div class=\"table-responsive\" data-bind=\"with: ReportData\">\n        <table class=\"table table-striped table-hover table-condensed\">\n            <thead style=\"position: sticky; top: -1px; z-index: 2;\">\n                <tr>\n                    <th></th>\n                    <!-- ko foreach: Rows -->\n                    <th>\n                        <span class=\"preserve-space\" data-bind=\"text: Items[0].FormattedValue\"></span>\n                    </th>\n                    <!-- /ko -->\n                </tr>\n            </thead>\n            <tbody data-bind=\"foreach: Columns\">\n                <tr>\n                    <!-- ko if: $index() > 0 -->\n                    <td>\n                        <span data-bind=\"text: fieldLabel || ColumnName\"></span>\n                    </td>\n                    <!-- ko foreach: $parent.Rows -->\n                    <td data-bind=\"style: {'background-color': $parent.backColor, 'color': $parent.fontColor, 'font-weight': $parent.fontBold() ? 'bold' : 'normal', 'text-align': $parent.fieldAlign ? $parent.fieldAlign : ($parent.IsNumeric ? 'right' : 'left') }\">\n                        <span class=\"preserve-space\" data-bind=\"text: Items[$parentContext.$index()].FormattedValue\"></span>\n                    </td>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                </tr>\n            </tbody>\n        </table>\n\n    </div>\n\n</script>\n\n<script type=\"text/html\" id=\"report-table\">\n    <div class=\"table-responsive\">\n        <table class=\"table table-hover table-condensed\" data-bind=\"attr: {class: 'table table-striped table-hover table-condensed ' + $parents[2].selectedStyle()}\">\n            <thead style=\"position: sticky; top: -1px; z-index: 2;\" data-bind=\"if: !$parents[2].noHeaderRow(), attr: {id: 'report-table-head' + $parents[2].ReportID()}\">\n                <tr class=\"no-highlight\" data-bind=\"sortableColumns: { handle: '.sortable', cursor: 'move', placeholder: 'drop-highlight',selectedFields: $parents[2].SelectedFields }\">\n                    <!-- ko if: $parentContext.$parentContext.$parent.canDrilldown() && !IsDrillDown() && !CanExpandOption() && (!$parents[2].hasPivotColumn() || ($parents[2].hasPivotColumn() && $parents[2].appSettings.useAltPivot)) -->\n                    <th style=\"width: 30px; border-left: 1px solid;\" data-bind=\"style: {'background-color': Columns[0].headerBackColor}\"></th>\n                    <!-- /ko -->\n                    <!-- ko template: 'report-column-header', data: $data -->\n                    <!-- /ko-->\n                </tr>\n            </thead>\n            <tbody data-bind=\"attr: {id: 'report-table-body' + $parents[2].ReportID()}\">\n                <tr style=\"display: none;\" data-bind=\"visible: Rows.length < 1\">\n                    <td data-bind=\"attr:{colspan: Columns.length + 1}\">\n                        No records found\n                    </td>\n                </tr>\n\n                <!-- ko if: !$parents[2].useRenderTable() -->\n                <!-- ko foreach: $parent.rows  -->\n                <tr>\n                    <!-- ko if: $parentContext.$parentContext.$parentContext.$parent.canDrilldown() && !$parent.IsDrillDown() && !$parent.CanExpandOption() && $parentContext.$parentContext.$parentContext.$parent.ReportType() != 'Single' -->\n                    <td style=\"width: 30px; vertical-align: middle;\" data-bind=\"style: {'background-color': Items[0]._backColor ?? Items[0].backColor(), 'color': Items[0]._fontColor ?? Items[0].fontColor()}\">\n                        <a href=\"#\" data-bind=\"click: function(){ toggle(); }\"><span class=\"fa\" data-bind=\"css: {'fa-plus': !isExpanded(), 'fa-minus': isExpanded()}\"></span></a>\n                    </td>\n                    <!-- /ko -->\n                    <!-- ko template: 'report-column', data: $data -->\n                    <!-- /ko-->\n                </tr>\n                <!-- ko if: isExpanded -->\n                <tr>\n                    <td style=\"width: 30px;\"></td>\n                    <td data-bind=\"attr:{colspan: $parent.Columns.length }\" style=\"padding-left: 0px;\">\n                        <div data-bind=\"visible: !DrillDownData()\">\n                            <div class=\"report-spinner\"></div>\n                        </div>\n                        <!-- ko if: DrillDownData -->\n                        <table class=\"table table-striped table-hover table-condensed\" data-bind=\"with: DrillDownData\">\n                            <thead>\n                                <tr class=\"no-highlight\">\n                                    <!-- ko template: 'report-column-header', data: $data -->\n                                    <!-- /ko-->\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <tr style=\"display: none;\" data-bind=\"visible: Rows && Rows.length < 1\">\n                                    <td data-bind=\"attr: {colspan: Columns.length}\">\n                                        No records found\n                                    </td>\n                                </tr>\n                                <!-- ko foreach: Rows  -->\n                                <tr>\n                                    <!-- ko template: 'report-column', data: $data -->\n                                    <!-- /ko-->\n                                </tr>\n                                <!-- /ko -->\n                            </tbody>\n                        </table>\n                        <div class=\"col-xs-12 col-centered\" data-bind=\"with: pager\">\n                            <div class=\"form-inline small text-muted\">\n                                <div class=\"float-start total-records\" data-bind=\"visible: pages()\">\n                                    <span data-bind=\"text: 'Total Records: ' + totalRecords()\"></span>\n                                </div>\n                                <div class=\"float-start total-records\">\n                                    &nbsp;\n                                    <a href=\"#\" title=\"Download Excel\" data-bind=\"click: $parent.exportExcel\"><span class=\"fas fa-file-excel\"></span></a>\n                                    &nbsp;\n                                    <a href=\"#\" title=\"View Code\" data-bs-toggle=\"modal\" data-bs-target=\"#sqlDrillDownModal\" data-bind=\"visible: $root.adminMode\">\n                                        <span class=\"fa fa-code\"></span>\n                                    </a>\n                                </div>\n                                <div class=\"form-group float-end\" data-bind=\"visible: pages()\">\n                                    <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                                </div>\n                            </div>\n                        </div>\n                        <!-- /ko -->\n                    </td>\n                </tr>\n                <!-- /ko -->\n                <!-- ko if: subReportsRan().length > 0 -->\n                <tr>\n                    <td data-bind=\"attr:{colspan: $parent.Columns.length }\" style=\"padding-left: 0px;\">\n                        <div data-bind=\"foreach: subReportsRan\">\n                            <div data-bind=\"template: { name: 'subreport-content', data: $data }\"></div>\n                        </div>\n                    </td>\n                </tr>\n                <!-- /ko -->\n                <!-- /ko -->\n                <!-- /ko-->\n            </tbody>\n            <!-- ko if: $parentContext.$parent.SubTotals().length == 1 && $parentContext.$parentContext.$parent.OuterGroupColumns().length == 0 && $parentContext.$parentContext.$parent.totalRowFormat() == 'row' -->\n            <tfoot data-bind=\"foreach: $parentContext.$parent.SubTotals\">\n                <tr class=\"sub-total\">\n                    <!-- ko if: $parentContext.$parentContext.$parentContext.$parent.canDrilldown() && !$parent.IsDrillDown() && !$parent.CanExpandOption() -->\n                    <td></td>\n                    <!-- /ko -->\n                    <!-- ko foreach: Items -->\n                    <!-- ko if: Value != 'NA' && Value != 'NaN' && !outerGroup() -->\n                    <td data-bind=\"style: {'background-color': _backColor ?? backColor(), 'color': _fontColor ?? fontColor(), 'font-weight': fontBold() || _fontBold ? 'bold' : 'normal', 'text-align': fieldAlign() ? fieldAlign() : 'right'}\">\n                        <div data-bind=\"style: {'width': fieldWidth }, attr: {'title': (Column.fieldLabel() || Column.ColumnName) + ' - ' +_aggregate }, visible:  _showInTotalRow != false\">\n                        <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n                        </div>\n                    </td>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                </tr>\n            </tfoot>\n            <!-- /ko -->\n            <!-- ko if: $parentContext.$parentContext.$parent.subTotalPerGroup() && $parentContext.$parent.perGroupSubTotals().length > 0 && $parentContext.$parentContext.$parent.totalRowFormat() == 'row' -->\n            <!-- ko if: $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex] && $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex].length > 0 -->\n            <tfoot>\n                <tr class=\"sub-total\" style=\"border-top: 2px solid #dee2e6;\">\n                    <!-- ko if: $parentContext.$parentContext.$parent.canDrilldown() && IsDrillDown() && CanExpandOption() -->\n                    <td></td>\n                    <!-- /ko -->\n                    <!-- ko foreach: $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex] -->\n                    <td data-bind=\"style: {'text-align': Column.IsNumeric ? 'right' : 'left', 'font-weight': 'bold'}\">\n                        <div data-bind=\"style: {'width': Column.fieldWidth}\">\n                            <span class=\"preserve-space\" data-bind=\"text: formattedVal\"></span>\n                        </div>\n                    </td>\n                    <!-- /ko -->\n                </tr>\n            </tfoot>\n            <!-- /ko -->\n            <!-- /ko -->\n        </table>\n        <!-- ko if: $parentContext.$parent.SubTotals().length > 0 && $parentContext.$parentContext.$parent.totalRowFormat() == 'table' && $parentContext.$parentContext.$parent.OuterGroupColumns().length == 0 -->\n        <div class=\"mt-3\" style=\"max-width: 450px;\">\n            <table class=\"table table-bordered table-sm\">\n                <thead>\n                    <tr>\n                        <th>Field</th>\n                        <th class=\"text-end\">Total</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <!-- ko foreach: $parentContext.$parent.SubTotals()[0].Items -->\n                    <!-- ko if: _showInTotalRow != false && Value != 'NA' && Value != 'NaN' -->\n                    <tr>\n                        <td data-bind=\"text: (Column.fieldLabel() || Column.ColumnName) + ' (' + _aggregate + ')'\"></td>\n                        <td class=\"text-end\">\n                            <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n                        </td>\n                    </tr>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                </tbody>\n            </table>\n        </div>\n        <!-- /ko -->\n        <!-- ko if: $parentContext.$parent.SubTotals().length > 0 && $parentContext.$parentContext.$parent.totalRowFormat() == 'table' && $parentContext.$parentContext.$parent.OuterGroupColumns().length > 0 && $parentContext.$parentContext.$parent.subTotalPerGroup() -->\n        <!-- ko if: $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex] && $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex].length > 0 -->\n        <div class=\"mt-3\" style=\"max-width: 450px;\">\n            <table class=\"table table-bordered table-sm\">\n                <thead>\n                    <tr>\n                        <th>Field</th>\n                        <th class=\"text-end\">Total</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <!-- ko foreach: $parentContext.$parent.perGroupSubTotals()[$parentContext.$data.groupIndex] -->\n                    <!-- ko if: _showInTotalRow != false -->\n                    <tr>\n                        <td data-bind=\"text: Column.fieldLabel() || Column.ColumnName\"></td>\n                        <td class=\"text-end\">\n                            <span class=\"preserve-space\" data-bind=\"text: formattedVal\"></span>\n                        </td>\n                    </tr>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                </tbody>\n            </table>\n        </div>\n        <!-- /ko -->\n        <!-- /ko -->\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"report-render\">\n    <div data-bind=\"with: ReportData\">\n        <div data-bind=\"foreach: Rows\">\n            <div data-bind=\"html: renderedHtml, css: { 'card-view': $parents[$parents.length-1].cardView }\"></div>\n\n            <div data-bind=\"foreach: subReportsRan\">\n                <!-- ko if: !_isInline -->\n                <div data-bind=\"template: { name: 'subreport-content', data: $data }\"></div>\n                <!-- /ko -->\n                <!-- ko if: _isInline -->\n                <div style=\"display:none\" data-bind=\"moveToInlineContainer: $data\"></div>\n                <!-- /ko -->\n            </div>\n        </div>\n    </div>\n    <div class=\"clearfix\"></div>\n</script>\n\n<script type=\"text/html\" id=\"subreport-content\">\n    <div class=\"\" style=\"padding-bottom: 20px; position: relative;\">\n        <a href=\"#\" class=\"text-muted\" title=\"Edit sub report\" style=\"position: absolute; right: 5px; top: 2px;\" data-bind=\"visible: CanEdit(), click: function() { var vm = _parentVM || $root; vm.editSubReport({ reportId: ReportID() }); }\">\n            <span class=\"fa fa-pencil\"></span>\n        </a>\n        <h2 data-bind=\"text: ReportName, visible: !_hideTitle\"></h2>\n        <div class=\"clearfix\"></div>\n        <div class=\"list-overflow-auto\" style=\"padding-top: 0; margin-top: 0;\">\n            <p data-bind=\"html: ReportDescription, visible: ReportDescription\"></p>\n            <div data-bind=\"with: ReportResult\" class=\"small\">\n                <div data-bind=\"visible: !ReportData()\">\n                    <div class=\"report-spinner\"></div>\n                </div>\n                <!-- ko if: !$parent._isPlaceholder -->\n                <div data-bind=\"template: 'report-template', data: $data\"></div>\n                <!-- /ko -->\n            </div>\n        </div>\n        <!-- ko if: !$data._isPlaceholder -->\n        <div class=\"form-inline\" data-bind=\"visible: !_hidePager\">\n            <div class=\"small\" data-bind=\"with: pager\">\n                <div class=\"form-group float-start total-records\" data-bind=\"if: totalRecords()>1 && $parent.ReportType() != 'Single'\">\n                    <span data-bind=\"text: 'Total Records: ' + totalRecords()\"></span><br />\n                </div>\n                <div class=\"form-group float-end\" data-bind=\"if: pages()>1 && $parent.ReportType() != 'Single'\">\n                    <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                </div>\n            </div>\n        </div>\n        <!-- /ko -->\n    </div>\n</script>\n\n\n<script type=\"text/html\" id=\"report-template\">\n    <div class=\"report-chart\" data-bind=\"attr: {id: 'chart_div_' + $parent.ReportID()}, visible: $parent.isChart\"></div>\n    <!-- ko if: $parent.ReportType() == 'Pivot' -->\n    <div data-bind=\"template: {name: 'report-pivot', data: $data }\"></div>\n    <!-- /ko -->\n\n    <!-- ko if: $parent.ReportType() == 'Html' -->\n    <div data-bind=\"template: {name: 'report-render', data: $data }\"></div>\n    <!-- /ko -->\n\n    <!-- ko if: $parent.ReportType() != 'Pivot' && $parent.ReportType() != 'Html' && (!$parent.isChart() || $parent.ShowDataWithGraph()) -->\n    <div class=\"float-end\" data-bind=\"if: $parent.OuterGroupColumns().length > 0\">\n        <a href=\"#\" data-bs-toggle=\"dropdown\" aria-haspopup=\"false\" aria-expanded=\"false\">\n            Manage Groups <span class=\"fa fa-ellipsis-v\"></span>\n        </a>\n        <ul class=\"dropdown-menu\" style=\"z-index: 1001;\" data-bind=\"foreach: $parent.OuterGroupColumns\">\n            <li class=\"dropdown-item small\">\n                <a href=\"#\" data-bind=\"click: remove\" title=\"Remove from Group\">\n                    <span class=\"fa fa-close\"></span> <span data-bind=\"text: fieldName\"></span>\n                </a>\n            </li>\n        </ul>\n    </div>\n    <div class=\"clear-fix\"></div>\n\n    <div data-bind=\"foreach: outerGroupData\">\n        <!-- ko if: rows.length > 0 || ($parent.outerGroupData && $parent.outerGroupData().length == 1) -->\n        <br />\n        <h6 style=\"font-weight: normal;\" data-bind=\"html: display\"></h6>\n        <div class=\"\" style=\"padding-top: 5px;\"></div>\n\n        <!-- ko if: $parents[1].ReportType() != 'Single'-->\n        <div data-bind=\"template: {name: 'report-table', data: $parent.ReportData }\"></div>\n        <!-- /ko -->\n        <!-- ko if: $parents[1].ReportType() == 'Single'-->\n        <div data-bind=\"template: {name: 'report-widget', data: $parent.ReportData }\"></div>\n        <!-- /ko -->\n        <!-- /ko -->\n    </div>\n    <!-- ko if: SubTotals().length > 0 && $parent.hasOuterGroupFields() && $parent.IncludeSubTotal() && $parent.totalRowFormat() == 'row' -->\n    <table class=\"table table-bordered table-sm mt-0\" style=\"border-top: 2px double #dee2e6; margin-bottom: 5px;\">\n         <thead>\n            <tr>\n                <th data-bind=\"attr: { colspan: SubTotals()[0].Items.length }\">Grand Total</th>                        \n            </tr>\n        </thead>\n        <tbody></tbody>\n            <tr>\n                <!-- ko if: $parent.canDrilldown() -->\n                <td style=\"width: 30px;\"></td>\n                <!-- /ko -->\n                <!-- ko foreach: SubTotals()[0].Items -->\n                <!-- ko if: _showInTotalRow != false -->\n                 <td data-bind=\"text: (Column.fieldLabel() || Column.ColumnName) + ' (' + _aggregate + ')'\"></td>\n                <!-- /ko -->\n                <!-- /ko -->\n            </tr>\n        \n            <tr class=\"sub-total\">\n                <!-- ko if: $parent.canDrilldown() -->\n                <td style=\"width: 30px;\"></td>\n                <!-- /ko -->\n                <!-- ko foreach: SubTotals()[0].Items -->\n                <!-- ko if: _showInTotalRow != false -->\n                <td data-bind=\"style: {'text-align': Column.IsNumeric ? 'right' : 'left', 'font-weight': 'bold'}\">\n                    <div data-bind=\"style: {'width': Column.fieldWidth}\">                        \n                        <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>                        \n                    </div>\n                </td>\n                <!-- /ko -->\n                <!-- /ko -->\n            </tr>\n        </tbody>\n    </table>\n    <!-- /ko -->\n    <!-- Grand Total: Table mode — Field/Total summary table -->\n    <!-- ko if: SubTotals().length > 0 && $parent.hasOuterGroupFields() && $parent.IncludeSubTotal() && $parent.totalRowFormat() != 'row' -->\n    <div class=\"mt-3\">\n        <!-- ko if: $parent.subTotalPerGroup() --><strong>Grand Total</strong><!-- /ko -->\n        <!-- ko ifnot: $parent.subTotalPerGroup() --><strong>Total</strong><!-- /ko -->\n        <table class=\"table table-bordered table-sm mt-2\" style=\"max-width: 450px;\">\n            <thead>\n                <tr>\n                    <th>Field</th>\n                    <th class=\"text-end\">Total</th>\n                </tr>\n            </thead>\n            <tbody>\n                <!-- ko foreach: SubTotals()[0].Items -->\n                <!-- ko if: _showInTotalRow != false && Value != 'NA' && Value != 'NaN' -->\n                <tr>\n                    <td data-bind=\"text: (Column.fieldLabel() || Column.ColumnName) + ' (' + _aggregate + ')'\"></td>\n                    <td class=\"text-end\">\n                        <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n                    </td>\n                </tr>\n                <!-- /ko -->\n                <!-- /ko -->\n            </tbody>\n        </table>\n    </div>\n    <!-- /ko -->\n    <!-- /ko -->\n</script>\n<script type=\"text/html\" id=\"admin-mode-template\">\n    <div class=\"row\">\n        <div class=\"d-flex justify-content-end align-items-center\" style=\"gap: 10px;\">\n            <div data-bind=\"visible: adminMode\">\n                <div class=\"alert alert-info d-inline-block\" style=\"font-size: 10pt; padding: 5px; max-width: 350px; white-space: normal; margin-bottom: 0;\">\n                    <i class=\"fa fa-user-circle\"></i> You can manage Reports/Dashboards for all users\n                </div>\n            </div>\n            <div data-bind=\"visible: adminMode\">\n                <div class=\"alert alert-info d-inline-block\" style=\"font-size: 10pt; padding: 5px; max-width: 350px; white-space: normal; margin-bottom: 0;\" title=\"Logged in user\">\n                    <i class=\"fa fa-id-badge\"></i>\n                    <span data-bind=\"text: currentUserName || currentUserId || 'Unknown User'\"></span>\n                    <!-- ko if: currentUserRole -->\n                    <span class=\"bubble-badge-separator\">|</span>\n                    Roles: <span data-bind=\"text: currentUserRole\"></span>\n                    <!-- /ko -->\n                    <!-- ko if: clientId -->\n                    <span class=\"bubble-badge-separator\">|</span>\n                    Client: <span data-bind=\"text: clientId\"></span>\n                    <!-- /ko -->\n                </div>\n            </div>\n            <div class=\"d-flex align-items-center\">\n                <div class=\"bubble-badge\">\n                    Admin Mode\n                    <div class=\"form-check form-switch ms-2\">\n                        <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: adminMode\">\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"manage-access-template\">\n    <h5><span class=\"fa fa-key\"></span>Manage Access</h5>\n    <div class=\"panel panel-default panel-body\" style=\"margin-left: 20px;\">\n\n        <div class=\"form-group row\">\n            <label class=\"col-md-3 col-sm-3 control-label\" data-bind=\"text: ($root.clientIdLabelText ? $root.clientIdLabelText() : 'Client Id') + ' to Restrict Access'\"></label>\n            <div class=\"col-md-6 col-sm-6\">\n                <!-- ko if: $root.clientIdOptions && $root.clientIdOptions().length > 0 -->\n                <select class=\"form-select form-select-sm\"\n                        data-bind=\"options: $root.clientIdOptions().filter(function(c){ return selectedClientIds().indexOf(c.id) < 0; }),\n                            optionsText: 'text', optionsValue: 'id', optionsCaption: 'Add to restrict access',\n                            value: clientIdToAdd, event: { change: function(){ addClientId(clientIdToAdd()); } }\"></select>\n                <!-- ko if: selectedClientIds().length > 0 -->\n                <div class=\"d-flex flex-wrap gap-1 mt-2\">\n                    <!-- ko foreach: selectedClientIds() -->\n                    <span class=\"badge bg-secondary d-inline-flex align-items-center\">\n                        <span data-bind=\"text: (function(){ var m = _.find($root.clientIdOptions(), function(c){ return c.id == $data; }); return m ? m.text : $data; })()\"></span>\n                        <button type=\"button\" class=\"btn btn-sm btn-link text-white p-0 ms-2 lh-1\" title=\"Remove\" data-bind=\"click: function(){ $parent.removeClientId($data); }\"><i class=\"fa fa-times\"></i></button>\n                    </span>\n                    <!-- /ko -->\n                </div>\n                <!-- /ko -->\n                <div class=\"form-text\" data-bind=\"visible: selectedClientIds().length === 0\">Not restricted, available to all.</div>\n                <!-- /ko -->\n                <!-- ko ifnot: $root.clientIdOptions && $root.clientIdOptions().length > 0 -->\n                <input class=\"form-control text-box single-line\" type=\"text\" placeholder=\"Comma separated, leave blank for all\" data-bind=\"value: clientId\">\n                <!-- ko if: selectedClientIds().length > 0 -->\n                <div class=\"d-flex flex-wrap gap-1 mt-2\">\n                    <!-- ko foreach: selectedClientIds() -->\n                    <span class=\"badge bg-secondary d-inline-flex align-items-center\">\n                        <span data-bind=\"text: $data\"></span>\n                        <button type=\"button\" class=\"btn btn-sm btn-link text-white p-0 ms-2 lh-1\" title=\"Remove\" data-bind=\"click: function(){ $parent.removeClientId($data); }\"><i class=\"fa fa-times\"></i></button>\n                    </span>\n                    <!-- /ko -->\n                </div>\n                <!-- /ko -->\n                <div class=\"form-text\" data-bind=\"visible: selectedClientIds().length === 0\">Not restricted, available to all.</div>\n                <!-- /ko -->\n            </div>\n            <div class=\"col-md-1 col-sm-1\">\n                <span data-bs-toggle=\"tooltip\" data-placement=\"right\" class=\"fa fa-question-circle helptip\" title=\"Leave blank to give Global access\"></span>\n            </div>\n        </div>\n        <div class=\"alert alert-info\">\n            <span class=\"fas fa-lightbulb fa-2x\"></span>&nbsp;User level rights override Role level rights. No selection for a rule implies report is available to all.\n        </div>\n\n        <div class=\"row small\">\n            <div class=\"col-md-6\">\n                <span class=\"clickable\" data-bind=\"click: toggleManageUsers\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showManageUsers(), 'fa-chevron-right': !showManageUsers() }\"></i> <b>Manage by User</b> (allow edit)</span>\n                <div data-bind=\"template: { name: 'access-selected-pills', data: { list: users, open: showManageUsers } }\"></div>\n                <div class=\"row container-fluid\" data-bind=\"visible: showManageUsers\">\n                    <!-- ko if: groupedUsers().length > 0 -->\n                    <!-- ko foreach: groupedUsers -->\n                    <div class=\"col-md-12\">\n                      <div class=\"category-header\" style=\"cursor: pointer;\" data-bind=\"click: function() { show(!show()); }\">\n                        <i class=\"fa toggle-icon\" data-bind=\"css: { 'fa-chevron-down': show(), 'fa-chevron-right': !show() }\"></i>\n                        <strong data-bind=\"text: category\"></strong>\n                      </div>\n                      <div class=\"row container-fluid\" data-bind=\"visible: show\">\n                        <!-- ko foreach: users -->\n                        <div class=\"float-start\">\n                          <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                              <input type=\"checkbox\" data-bind=\"checked: selected\"> &nbsp; <span data-bind=\"text: text\"></span>&nbsp; </label>\n                          </div>\n                        </div>\n                        <!-- /ko -->\n                      </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <!-- ko if: groupedUsers().length == 0 && users().length > 0 -->\n                    <!-- ko foreach: users -->\n                    <div class=\"float-start\">\n                        <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                                <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                            </label>\n                        </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <div data-bind=\"if: groupedUsers().length == 0 && users().length == 0\">\n                        Users list not populated or not applicable\n                    </div>\n                </div>\n                <br />\n                <span class=\"clickable\" data-bind=\"click: toggleViewUsers\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showViewUsers(), 'fa-chevron-right': !showViewUsers() }\"></i> <b>View only by User</b> (no edit/delete)</span>\n                <div data-bind=\"template: { name: 'access-selected-pills', data: { list: viewOnlyUsers, open: showViewUsers } }\"></div>\n                <div class=\"row container-fluid\" data-bind=\"visible: showViewUsers\">\n                    <!-- ko if: groupedViewOnlyUsers().length > 0 -->\n                    <!-- ko foreach: groupedViewOnlyUsers -->\n                    <div class=\"col-md-12\">\n                      <div class=\"category-header\" style=\"cursor: pointer;\" data-bind=\"click: function() { show(!show()); }\">\n                        <i class=\"fa toggle-icon\" data-bind=\"css: { 'fa-chevron-down': show(), 'fa-chevron-right': !show() }\"></i>\n                        <strong data-bind=\"text: category\"></strong>\n                      </div>\n                      <div class=\"row container-fluid\" data-bind=\"visible: show\">\n                        <!-- ko foreach: viewOnlyUsers -->\n                        <div class=\"float-start\">\n                          <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                              <input type=\"checkbox\" data-bind=\"checked: selected\"> &nbsp; <span data-bind=\"text: text\"></span>&nbsp; </label>\n                          </div>\n                        </div>\n                        <!-- /ko -->\n                      </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <!-- ko if: groupedViewOnlyUsers().length == 0 && viewOnlyUsers().length > 0 -->\n                    <!-- ko foreach: viewOnlyUsers -->\n                    <div class=\"float-start\">\n                        <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                                <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                            </label>\n                        </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <div data-bind=\"if: groupedViewOnlyUsers().length == 0 && viewOnlyUsers().length == 0\">\n                        Users list not populated or not applicable\n                    </div>\n                </div>\n                <br />\n                <div data-bind=\"ifnot: isDashboard\">\n                    <span class=\"clickable\" data-bind=\"click: toggleDeleteUsers\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showDeleteUsers(), 'fa-chevron-right': !showDeleteUsers() }\"></i> <b>Delete by User</b> (allow delete)</span>\n                    <div data-bind=\"template: { name: 'access-selected-pills', data: { list: deleteOnlyUsers, open: showDeleteUsers } }\"></div>\n                    <div class=\"row container-fluid\" data-bind=\"visible: showDeleteUsers\">\n                    <!-- ko if: groupedDeleteOnlyUsers().length > 0 -->\n                    <!-- ko foreach: groupedDeleteOnlyUsers -->\n                    <div class=\"col-md-12\">\n                      <div class=\"category-header\" style=\"cursor: pointer;\" data-bind=\"click: function() { show(!show()); }\">\n                        <i class=\"fa toggle-icon\" data-bind=\"css: { 'fa-chevron-down': show(), 'fa-chevron-right': !show() }\"></i>\n                        <strong data-bind=\"text: category\"></strong>\n                      </div>\n                      <div class=\"row container-fluid\" data-bind=\"visible: show\">\n                        <!-- ko foreach: deleteOnlyUsers -->\n                        <div class=\"float-start\">\n                          <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                              <input type=\"checkbox\" data-bind=\"checked: selected\"> &nbsp; <span data-bind=\"text: text\"></span>&nbsp; </label>\n                          </div>\n                        </div>\n                        <!-- /ko -->\n                      </div>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <!-- ko if: groupedDeleteOnlyUsers().length == 0 && deleteOnlyUsers().length > 0 -->\n                    <!-- ko foreach: deleteOnlyUsers -->\n                        <div class=\"float-start\">\n                            <div class=\"checkbox\">\n                                <label class=\"label label-info\">\n                                    <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                                </label>\n                            </div>\n                        </div>\n                        <!-- /ko -->\n                        <!-- /ko -->\n                        <div data-bind=\"if: groupedDeleteOnlyUsers().length == 0 && deleteOnlyUsers().length == 0\">\n                            Users list not populated or not applicable\n                        </div>\n                    </div>\n                    <br />\n                </div>\n            </div>\n            <div class=\"col-md-6\">\n                <span class=\"clickable\" data-bind=\"click: toggleManageRoles\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showManageRoles(), 'fa-chevron-right': !showManageRoles() }\"></i> <b>Manage by User Role</b> (allow edit)</span>\n                <div data-bind=\"template: { name: 'access-selected-pills', data: { list: userRoles, open: showManageRoles } }\"></div>\n                <div class=\"row container-fluid\" data-bind=\"visible: showManageRoles\">\n                    <!-- ko foreach: userRoles -->\n                    <div class=\"float-start\">\n                        <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                                <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                            </label>\n                        </div>\n                    </div>\n                    <!-- /ko -->\n                    <div data-bind=\"if: userRoles().length == 0\">\n                        User Roles list not populated or not applicable\n                    </div>\n                </div>\n                <br />\n                <span class=\"clickable\" data-bind=\"click: toggleViewRoles\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showViewRoles(), 'fa-chevron-right': !showViewRoles() }\"></i> <b>View only by User Role</b> (no edit/delete)</span>\n                <div data-bind=\"template: { name: 'access-selected-pills', data: { list: viewOnlyUserRoles, open: showViewRoles } }\"></div>\n                <div class=\"row container-fluid\" data-bind=\"visible: showViewRoles\">\n                    <!-- ko foreach: viewOnlyUserRoles -->\n                    <div class=\"float-start\">\n                        <div class=\"checkbox\">\n                            <label class=\"label label-info\">\n                                <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                            </label>\n                        </div>\n                    </div>\n                    <!-- /ko -->\n                    <div data-bind=\"if: viewOnlyUserRoles().length == 0\">\n                        User Roles list not populated or not applicable\n                    </div>\n                </div>\n                <div data-bind=\"ifnot: isDashboard\">\n                    <span class=\"clickable\" data-bind=\"click: toggleDeleteRoles\"><i class=\"toggle-icon fa\" data-bind=\"css: { 'fa-chevron-down': showDeleteRoles(), 'fa-chevron-right': !showDeleteRoles() }\"></i> <b>Delete by User Role</b> (allow delete)</span>\n                    <div data-bind=\"template: { name: 'access-selected-pills', data: { list: deleteOnlyUserRoles, open: showDeleteRoles } }\"></div>\n                    <div class=\"row container-fluid\" data-bind=\"visible: showDeleteRoles\">\n                        <!-- ko foreach: deleteOnlyUserRoles -->\n                        <div class=\"float-start\">\n                            <div class=\"checkbox\">\n                                <label class=\"label label-info\">\n                                    <input type=\"checkbox\" data-bind=\"checked: selected\">&nbsp;<span data-bind=\"text: text\"></span>&nbsp;\n                                </label>\n                            </div>\n                        </div>\n                        <!-- /ko -->\n                        <div data-bind=\"if: deleteOnlyUserRoles().length == 0\">\n                            User Roles list not populated or not applicable\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n\n<!-- Collapsed view of one access rule: who is selected, or that it is open to everyone. Hidden while the checkboxes are open. -->\n<script type=\"text/html\" id=\"access-selected-pills\">\n    <!-- ko ifnot: ko.unwrap(open) -->\n    <div class=\"d-flex flex-wrap gap-1 align-items-center my-1 ms-3\">\n        <!-- ko foreach: _.filter(list(), function (x) { return x.selected(); }) -->\n        <span class=\"badge bg-secondary d-inline-flex align-items-center\">\n            <span data-bind=\"text: text\"></span>\n            <button type=\"button\" class=\"btn btn-sm btn-link text-white p-0 ms-2 lh-1\" title=\"Remove\" data-bind=\"click: function(){ selected(false); }\"><i class=\"fa fa-times\"></i></button>\n        </span>\n        <!-- /ko -->\n        <span class=\"text-muted small\" data-bind=\"visible: !_.some(list(), function (x) { return x.selected(); })\"><i class=\"fa fa-globe\"></i> Everyone, not restricted</span>\n    </div>\n    <!-- /ko -->\n</script>\n<!-- Access summary badges for a report/folder/dashboard row (admin mode). Grey = restricted, outlined = open to all. -->\n<script type=\"text/html\" id=\"access-badges\">\n    <div class=\"d-flex flex-wrap gap-1 align-items-center\" data-bind=\"foreach: accessBadges($data, $root)\">\n        <span class=\"badge d-inline-flex align-items-center\" data-bind=\"attr: { title: title }, css: restricted ? 'bg-secondary' : 'bg-light text-muted border'\">\n            <!-- ko foreach: icons.split(' ') -->\n            <i class=\"fa me-1\" data-bind=\"css: $data\"></i>\n            <!-- /ko -->\n            <span data-bind=\"text: text\"></span>\n        </span>\n    </div>\n</script>\n<script type=\"text/html\" id=\"filter-group\">\n    <div class=\"query-builder form-inline\" data-bind=\"foreach: FilterGroups\">\n        <div class=\"rules-group-container\">\n            <div class=\"rules-group-header\" data-bind=\"attr: {parentdivid: generateUniqueId()}\">\n                <div data-bind=\"visible: !isRoot\">\n                    <div class=\"float-start\">\n                        <div class=\"btn-group btn-group-toggle btn-group-sm\" data-bs-toggle=\"buttons\" role=\"group\">\n                            <label class=\"btn btn-light active\" style=\"margin-right: 0px;\">\n                                <input type=\"radio\" data-bind=\"attr: { name: 'andOrGroup-' + $element.closest('.rules-group-header').getAttribute('parentdivid') }, checked: AndOr\" value=\"And\" /> And\n                            </label>\n                            <label class=\"btn btn-light active\">\n                                <input type=\"radio\" data-bind=\"attr: { name: 'andOrGroup-' + $element.closest('.rules-group-header').getAttribute('parentdivid') }, checked: AndOr\" value=\"Or\" /> Or\n                            </label>\n                        </div>\n                    </div>\n                    <div class=\"float-end\">\n                        <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parent.RemoveFilterGroup, visible: !isRoot\">Remove Group</button>&nbsp;\n                    </div>\n                </div>\n                <div data-bind=\"visible: isRoot\">\n                    <div class=\"float-start padded-div\">\n                        <label> &nbsp;Filter Conditions</label>\n                    </div>\n                </div>\n                <div class=\"clearfix\"></div>\n            </div>\n\n            <div class=\"rules-group-body\" data-bind=\"template: {name: 'filter-inner'}\"></div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"filter-details-summary\">\n    <!-- ko if: typeof ShowFilterDetails === 'function' && ShowFilterDetails() && typeof filterDetailsSummary === 'function' && filterDetailsSummary() -->\n    <div class=\"mb-2 py-1 small\" style=\"border-left: 3px solid #adb5bd; padding-left: 10px;\">\n        <i class=\"fa fa-filter\"></i>\n        <b>Filters:</b>\n        <span data-bind=\"html: filterDetailsSummary()\"></span>\n    </div>\n    <!-- /ko -->\n</script>\n\n<script type=\"text/html\" id=\"fly-filter-template\">\n    <div class=\"card\" data-bind=\"visible: FlyFilters().length>0 || DontExecuteOnRun\">\n        <div class=\"card-header\">\n            <a data-bs-toggle=\"collapse\" data-bind=\"attr: {'data-bs-target': '#filter-panel-' + ReportID() }\" href=\"#\">\n                <i class=\"fa fa-filter\"></i> Choose Filters\n            </a>\n        </div>\n        <div data-bind=\"attr: {id: 'filter-panel-' + ReportID() }, css: {collpased: !DontExecuteOnRun(), collapse: !DontExecuteOnRun()}\" class=\"card-body\">\n            <div>\n                <!-- ko foreach: FlyFilters -->\n                <div class=\"row\">\n                    <div class=\"col-sm-5 col-xs-4\">\n                        <div data-bind=\"with: Field\" class=\"checkbox\">\n                            <div class=\"checkbox\">\n                                <label>\n                                    <input type=\"checkbox\" title=\"Apply this filter\" data-bind=\"checked: $parent.Apply, disabled: forced\" /> <span data-bind=\"text: selectedFilterName\"></span>\n                                </label>\n                            </div>\n                        </div>\n                    </div>\n                    <div data-bind=\"with: Field\" class=\"col-sm-2 col-xs-3\">\n                        <div class=\"form-group\" data-bind=\"if: $parent.Apply\">\n                            <select class=\"form-select\" data-bind=\"options: fieldFilter, value: $parent.Operator\" required></select>\n                        </div>\n                    </div>\n                    <div data-bind=\"with: Field\" class=\"col-sm-5 col-xs-5\">\n                        <div data-bind=\"if: $parent.Apply\" data-parentprefix=\"F\" >\n                            <div data-bind=\"template: 'report-filter', data: $data\"></div>\n                        </div>\n                    </div>\n                </div>\n                <!-- /ko -->\n                <button class=\"btn btn-primary\" data-bind=\"click: ExecuteReport\">Run</button>\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"filter-inner\">\n    <div class=\"rules-list\">\n        <div class=\"rule-container\" data-bind=\"visible: Filters().length>0\">\n            <table class=\"table table-striped table-hover table-borderless\">\n                <thead>\n                    <tr>\n                        <th class=\"row\">\n                            <div class=\"col-md-1\"></div>\n                            <div class=\"col-md-4\">Field</div>\n                            <div class=\"col-md-2\"></div>\n                            <div class=\"col-md-4\">Filter</div>\n                            <div class=\"col-md-1\"></div>\n                        </th>\n                    </tr>\n                </thead>\n                <tbody data-bind=\"foreach: Filters\">\n                    <tr class=\"rule-container\">\n                        <td class=\"row\">\n                            <div class=\"col-md-1\">\n                                <select data-bind=\"value: AndOr, visible: $index()>0\" class=\"form-select\">\n                                    <option>And</option>\n                                    <option>Or</option>\n                                </select>\n                            </div>\n                            <div class=\"col-md-3\">\n                                <div class=\"form-group\">\n                                    <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"\n                                        options: $parents[$parents.length-2].selectedFieldsCanFilter != undefined\n                                                    ? $parents[$parents.length-2].selectedFieldsCanFilter\n                                                    : $parents[$parents.length-1].selectedFieldsCanFilter,\n                                        optionsText: 'selectedFieldName',\n                                        optionsCaption: 'Please Choose',\n                                        value: Field,\n                                        attr: {required: Field()==null?'required':false},\n                                        disable: Field() && Field().forced\"></select>\n                                </div>\n                            </div>\n                            <div class=\"col-md-2\">\n                                <div data-bind=\"with: Field\">\n                                    <div class=\"form-group\">\n                                        <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: fieldFilter, value: $parent.Operator\" required></select>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col-md-5\">\n                                <!-- ko ifnot: $data.useEmailListColumn && $data.useEmailListColumn() -->\n                                <div data-bind=\"with: Field\" data-parentprefix=\"M\">\n                                    <div data-bind=\"template: 'report-filter', data: $data\"></div>\n                                </div>\n                                <!-- /ko -->\n                                <!-- ko if: $root.scheduleEmailListColumns && $root.scheduleEmailListColumns().length > 0 -->\n                                <div class=\"form-check small mt-1\">\n                                    <label class=\"form-check-label text-muted\" title=\"Take this filter's value from the Email List query, one email per row\">\n                                        <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: useEmailListColumn\" /> Use value from Email List\n                                    </label>\n                                </div>\n                                <!-- ko if: $data.useEmailListColumn && $data.useEmailListColumn() -->\n                                <select class=\"form-select\" required data-bind=\"options: $root.scheduleEmailListColumns, optionsCaption: 'Choose Email List column...', value: EmailListColumn\"></select>\n                                <!-- /ko -->\n                                <!-- /ko -->\n                                <!-- ko if: Field() && Field().fieldType == 'DateTime' && Operator() == 'range' && $index()==0 -->\n                                <!-- ko if: $parents[$parents.length-2].canAddSeries != undefined && $parents[$parents.length-2].canAddSeries() -->\n                                <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parents[$parents.length-2].AddSeries.bind($data)\">Add Comparison</button>\n                                <!--/ko -->\n                                <!-- ko if: $parents[$parents.length-2].canAddSeries == undefined && $parentContext.$parent.canAddSeries != undefined && $parentContext.$parent.canAddSeries()-->\n                                <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parentContext.$parent.AddSeries.bind($data)\">Add Comparison</button>\n                                <!--/ko -->\n                                <!--/ko -->\n                                <span data-bind=\"visible: Field() && Field().forced\" class=\"badge bg-info\">Required Filter</span>\n                            </div>\n                            <div class=\"col-md-1\">\n                                <div style=\"display: flex; align-items: left;\">\n                                    <div class=\"form-group\" >\n                                        <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parent.RemoveFilter, hidden: Field() && Field().forced\" title=\"Remove\">\n                                            <i class=\"fa fa-trash\"></i>\n                                        </button>\n                                    </div>\n                                    <div class=\"form-group\" data-bind=\"with: Field, hidden: document.querySelector('#filter-panel.card-body.collapse') || ($root.scheduleFilterEditing && $root.scheduleFilterEditing())\">\n                                        <span class=\"btn btn-sm\" tabindex=\"0\" data-bind=\"click: function(){ filterOnFly(!filterOnFly()); }, css: {'btn-success': filterOnFly()==true, 'btn-secondary': !filterOnFly()}\">\n                                            <span class=\"fa fa-filter\" aria-hidden=\"true\" title=\"Filter on Report\"></span>\n                                        </span>\n                                    </div>\n                                </div>\n\n                            </div>\n                        </td>\n                    </tr>\n                    <!-- ko foreach: compareTo -->\n                    <tr>\n                        <td class=\"row\">\n                            <div class=\"col-md-6\">&nbsp;</div>\n                            <div class=\"col-md-2\">\n                                <span style=\"text-align: right\"><button class=\"btn btn-sm\" data-bind=\"click: $parents[2].RemoveSeries\"><span class=\"fa fa-trash\"></span></button></span>\n                                <span class=\"muted\">Compare to</span>\n                            </div>\n                            <div class=\"col-md-4\">\n                                <select class=\"form-select\" data-bind=\"options: Range, value: Value\" required></select>\n                            </div>\n                        </td>\n                    </tr>\n                    <!-- /ko -->\n                </tbody>\n            </table>\n        </div>\n\n        <div class=\"rule-container\">\n            <div data-bind=\"template: {name: 'filter-group'}\"></div>\n            <div>\n                <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: AddFilter\">Add Filter</button>\n                <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: AddFilterGroup\">Add Filter Group</button>\n            </div>\n        </div>\n    </div>\n\n</script>\n\n            <script type=\"text/html\" id=\"filter-parameters\">\n                <div class=\"table-responsive\">\n                        <span data-bind=\"hidden: showParameters\">No filters available to choose</span>\n                        <table class=\"table table-striped table-hover table-borderless\" data-bind=\"visible: showParameters\">\n                                <thead>\n                                        <tr>\n                                                <th style=\"width: 30%\">Filter</th>\n                                                <th style=\"width: 20%\"></th>\n                                                <th style=\"width: 30%\">Value</th>\n                                                <th style=\"width: 10%\"></th>\n                                        </tr>\n                                </thead>\n                                <tbody data-bind=\"foreach: Parameters\">\n                                        <tr data-bind=\"ifnot: Hidden\">\n                                                <td data-bind=\"text: DisplayName\"></td>\n                                                <td>\n                                                        <div class=\"form-group\">\n                                                                <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: operators, value: Operator\" required></select>\n                                                        </div>\n                                                </td>\n                                                <td data-bind=\"with: Field\" data-parentprefix=\"P\">\n                                                        <div data-bind=\"template: 'report-filter', data: $data\"></div>\n                                                </td>\n                                                <!-- CHANGED: was empty <td></td>, now has the fly-filter toggle -->\n                                                <td class=\"text-center\">\n                                                        <span class=\"btn btn-sm\" tabindex=\"0\"\n                                                            data-bind=\"click: function(){ filterOnFly(!filterOnFly()); },\n                                                                             css: {'btn-success': filterOnFly()==true, 'btn-secondary': !filterOnFly()}\">\n                                                                <span class=\"fa fa-filter\" aria-hidden=\"true\" title=\"Filter on Report\"></span>\n                                                        </span>\n                                                </td>\n                                        </tr>\n\n                                </tbody>\n                        </table>\n                </div>\n            </script>\n\n<script type=\"text/html\" id=\"report-schedule\">\n    <div data-bind=\"with: scheduleBuilder\" id=\"schedule-builder-div\">\n        <div class=\"form-check\">\n            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: hasSchedule\" id=\"scheduleReportCheckbox\">\n            <label class=\"form-check-label\" for=\"scheduleReportCheckbox\">\n                Set Schedule to send by Email\n            </label>\n        </div>\n        <div data-bind=\"if: hasSchedule\">\n            <div class=\"d-flex align-items-center\">\n                <div class=\"me-3 d-flex align-items-center\">\n                    <span data-bind=\"text: selectedOption() != 'once' ? 'Every ' : ''\"></span>&nbsp;\n                    <select class=\"form-select\" required data-bind=\"options: options, value: selectedOption\" style=\"min-width: 80px;\"></select>\n                </div>\n                <div data-bind=\"if: selectedOption() == 'once'\" class=\"me-3 d-flex align-items-center\">\n                    &nbsp;on&nbsp;<input data-bind=\"datepicker: selectedDate, datepickerOptions: {value: selectedDate}\" class=\"form-control\" required />\n                </div>\n                <div class=\"d-flex align-items-center\">\n                    <div data-bind=\"if: showDays\" class=\"d-flex align-items-center\">\n                        &nbsp;on&nbsp;\n                        <select multiple class=\"form-select ms-2\" required data-bind=\"select2: { placeholder: 'Choose Days', allowClear: true }, options: days, selectedOptions: selectedDays\"></select>\n                    </div>\n                    <div data-bind=\"if: showDates\" class=\"d-flex align-items-center\">\n                        &nbsp;on&nbsp;\n                        <select multiple class=\"form-select\" required data-bind=\"select2: { placeholder: 'Choose Dates', allowClear: true }, options: dates, selectedOptions: selectedDates\"></select>\n                    </div>\n                    <div data-bind=\"if: showMonths\" class=\"d-flex align-items-center\">\n                        &nbsp;on&nbsp;\n                        <select multiple class=\"form-select\" required data-bind=\"select2: { placeholder: 'Choose Months', allowClear: true }, options: months, selectedOptions: selectedMonths\"></select>\n                    </div>\n                    <div data-bind=\"if: showAtTime\" class=\"d-flex align-items-center ms-3\">\n                        &nbsp;at&nbsp;\n                        <select class=\"form-select me-2\" style=\"min-width: 60px;\" data-bind=\"options: hours, value: selectedHour\"></select>\n                        <select class=\"form-select me-2\" style=\"min-width: 60px;\" data-bind=\"options: minutes, value: selectedMinute\"></select>\n                        <select class=\"form-select\" style=\"min-width: 80px;\" data-bind=\"value: selectedAmPm\">\n                            <option>AM</option>\n                            <option>PM</option>\n                        </select>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"alert alert-info\">\n                Report will be run and emailed <span data-bind=\"text: selectedOption() != 'once' ? 'every' : ''\"></span> <span data-bind=\"text: selectedOption\"></span>\n                <span data-bind=\"if: selectedOption() == 'once'\">\n                    on <span class=\"error\" data-bind=\"visible: !selectedDate()\">Please pick a Date</span> <span data-bind=\"text: selectedDate\"></span>\n                </span>\n                <span data-bind=\"if: showDays\">\n                    on <span class=\"error\" data-bind=\"visible: selectedDays().length == 0\">Please pick Day(s)</span> <span data-bind=\"text: selectedDays\"></span>\n                </span>\n                <span data-bind=\"if: showDates\">\n                    on <span class=\"error\" data-bind=\"visible: selectedDates().length == 0\">Please pick Date(s)</span>\n                    <span data-bind=\"foreach: selectedDates\"><span data-bind=\"visible: $index()>0\">, </span><span data-bind=\"text: $data == 1 ? '1st': ($data == 2 ? '2nd' : ($data == 3 ? '3rd' : ($data == 31 ? '31st' : $data+'th')))\"></span></span>\n                </span>\n                <span data-bind=\"if: showMonths\">\n                    of <span class=\"error\" data-bind=\"visible: selectedMonths().length == 0\">Please pick Month(s)</span> <span data-bind=\"text: selectedMonths\"></span>\n                </span>\n                <span data-bind=\"if: showAtTime\">\n                    at <span data-bind=\"text: selectedHour\"></span>:<span data-bind=\"text: selectedMinute\"></span> <span data-bind=\"text: selectedAmPm\"></span>\n                </span>\n            </div>\n            <div class=\"mb-3\">\n                <div class=\"row g-2 align-items-center\">\n                    <div class=\"col-12 col-sm-3\">\n                        <label class=\"col-form-label pb-0\">Email to</label>\n                        <div class=\"form-check small\">\n                            <label class=\"form-check-label text-muted\" title=\"Send to a saved Email List instead of typing addresses\">\n                                <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: useEmailQuery\" />\n                                Email List\n                            </label>\n                        </div>\n                    </div>\n\n                    <div class=\"col-12 col-sm-6\">\n                        <!-- ko ifnot: useEmailQuery -->\n                        <input type=\"text\" class=\"form-control\"\n                               data-bind=\"value: emailTo\"\n                               placeholder=\"Enter Email Addresses separated by comma\" />\n                        <!-- /ko -->\n                        <!-- ko if: useEmailQuery -->\n                        <div class=\"d-flex align-items-center gap-2\">\n                            <select class=\"form-select\" data-bind=\"options: emailQueries, optionsText: 'name', optionsValue: 'id', value: emailQueryId, optionsCaption: 'Choose Email List...'\"></select>\n                            <button type=\"button\" class=\"btn btn-light btn-sm text-nowrap\"\n                                    data-bind=\"click: previewRecipients, enable: emailQueryId() > 0\"\n                                    title=\"Show who this Email List currently returns\">View</button>\n                        </div>\n                        <!-- /ko -->\n                    </div>\n\n                    <label class=\"col-6 col-sm-1 col-form-label\">Format</label>\n\n                    <div class=\"col-6 col-sm-2\">\n                        <select class=\"form-select\" data-bind=\"value: format,event: { change: onFormatChange }\">\n                            <option value=\"EXCEL\">Excel</option>\n                            <option data-bind=\"visible: $parent.canDrilldown && $parent.canDrilldown()\" value=\"EXCEL-SUB\">Excel (Expanded)</option>\n                            <option value=\"CSV\">CSV</option>\n                            <option value=\"PDF\">PDF</option>\n                            <option value=\"WORD\">Word</option>\n                            <option value=\"LINK\">Link</option>\n                        </select>\n                    </div>\n                </div>\n            </div>\n            <div class=\"mb-3\">\n                <div class=\"row g-2 align-items-center\">\n                    <label class=\"col-12 col-sm-3 col-form-label\">Pick Time Zone</label>\n\n                    <div class=\"col-12 col-sm-9\">\n                        <select class=\"form-select\"\n                                data-bind=\"options: timezonOption,\n                                           optionsText: 'displayName',\n                                           optionsValue: 'timeZoneId',\n                                           value: selectedTimezone,\n                                           select2: {dropdownParent: $element.closest('.modal'), allowClear: true, placeholder: 'Set a time zone'}\">\n                        </select>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"mb-3\">\n                <div class=\"row g-2\">\n                    <div class=\"col-6 col-sm-3\">\n                        <div class=\"form-check\" title=\"Set a date to start sending scheduled report\">\n                            <input class=\"form-check-input\" type=\"checkbox\"\n                                   data-bind=\"checked: hasScheduleStart\"\n                                   id=\"scheduleStartCheckbox\">\n                            <label class=\"form-check-label\" for=\"scheduleStartCheckbox\">\n                                Schedule Start Date\n                            </label>\n                        </div>\n                    </div>\n\n                    <div class=\"col-6 col-sm-4\" data-bind=\"if: hasScheduleStart\">\n                        <input type=\"text\" class=\"form-control\"\n                               data-bind=\"datepicker: scheduleStart, datepickerOptions: {value: scheduleStart}\"\n                               title=\"Scheduled Report will not be sent before this date\"\n                               required />\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"mb-3\">\n                <div class=\"row g-2\">\n                    <div class=\"col-6 col-sm-3\">\n                        <div class=\"form-check\"  title=\"Set a date to stop sending scheduled report\">\n                            <input class=\"form-check-input\" type=\"checkbox\"\n                                   data-bind=\"checked: hasScheduleEnd\"\n                                   id=\"scheduleEndCheckbox\">\n                            <label class=\"form-check-label\" for=\"scheduleEndCheckbox\">\n                                Schedule End Date\n                            </label>\n                        </div>\n                    </div>\n\n                    <div class=\"col-6 col-sm-4\" data-bind=\"if: hasScheduleEnd\">\n                        <input type=\"text\" class=\"form-control\"\n                               data-bind=\"datepicker: scheduleEnd, datepickerOptions: {value: scheduleEnd}\"\n                               title=\"Scheduled Report will not be sent after this date\"\n                               required />\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n\n</script>\n\n<script type=\"text/html\" id=\"report-field-options\">\n    <div class=\"modal-dialog\" style=\"max-width: 750px;\">\n        <div class=\"modal-content\" data-bind=\"with: editFieldOptions\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\"><span data-bind=\"text: fieldName\"></span> - Setup Additional Field Options</h5>\n            </div>\n            <div class=\"modal-body needs-validation\">\n                <div class=\"card card-body\">\n                    <b>Column Format Settings</b>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pick Data Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" data-bind=\"options: ['Days', 'Hours', 'Minutes', 'Seconds'].indexOf(fieldFormat()) >= 0 ? ['Days', 'Hours', 'Minutes', 'Seconds'] : $parents[1].fieldFormatTypes, value: fieldFormat\"></select>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: $parents[1].decimalFormatTypes.indexOf($data.fieldFormat())>=0\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pick Decimal Places</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"number\" class=\"form-control\" data-bind=\"value: decimalPlaces\" placeholder=\"\" />\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: fieldFormat()=='Currency'\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pick Currency Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" required data-bind=\"options: $parents[1].currencyFormats, optionsText: 'display',optionsValue: 'value', value: currencyFormat\"></select>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: fieldFormat()=='Date'\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pick Date Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" data-bind=\"options: $parents[1].dateFormats, value: dateFormat\"></select>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible:selectedAggregate()=='Pivot' && fieldFormat()=='Date'\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Pivot Drilldown Date Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" data-bind=\"options: ['', 'Day', 'Month', 'Year', 'Month/Year'], value: drillDataFormat\"></select>\n                        </div>\n                    </div>\n\n                    <div class=\"form-group row\" data-bind=\"visible: fieldFormat()=='Date' && dateFormat()==='Custom'\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Enter Custom Date Format</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                        <div class=\"input-group\">\n                                <input type=\"text\" class=\"form-control\" data-bind=\"value: customDateFormat\" placeholder=\"dd/MM/yyyy\" />\n                                <button type=\"button\" class=\"btn btn-outline-secondary\" tabindex=\"-1\"\n                                  data-bind=\"bsPopover: { \n                                    trigger: 'focus', \n                                    placement: 'bottom', \n                                    html: true, \n                                    title: 'Date Format Tokens', \n                                    content:$root.dateFormatPopoverContent \n                                  }\">\n                                  <i class=\"fa fa-question-circle\"></i>\n                                </button>\n                            </div>\n                    </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Choose Column Label</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" data-bind=\"value: fieldLabel\" />\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Inner Column Label</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" data-bind=\"value: fieldLabel2\" />\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Choose Text Alignment</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" data-bind=\"options: $parents[1].fieldAlignments, value: fieldAlign\"></select>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Choose Width (leave blank for auto)</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" data-bind=\"value: fieldWidth\" />\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <div class=\"col-sm-12\">\n                            <div class=\"checkbox float-start\" >\n                                <label>\n                                    <input type=\"checkbox\" data-bind=\"checked: outerGroup\" />\n                                    <b>Outer Group</b> - Use this field as a group heading\n                                </label>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: $parents[1].IncludeSubTotal()\">\n                        <div class=\"col-sm-12 d-flex align-items-center\">\n                            <div class=\"checkbox\">\n                                <label>\n                                    <input type=\"checkbox\" data-bind=\"checked: dontSubTotal\" />\n                                    <b>Don't Show In Total Row</b>\n                                </label>\n                            </div>\n                            <button class=\"btn btn-sm btn-secondary ms-2\" title=\"Apply to all columns\" data-bind=\"click: function(){ applyAllDontSubTotal(!applyAllDontSubTotal()); }\">\n                                <span class=\"fa\" data-bind=\"css: applyAllDontSubTotal() ? 'fa-check' : 'fa-paste'\"></span>\n                            </button>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"visible: $parents[1].IncludeSubTotal() && !dontSubTotal()\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Total Row Aggregate</label>\n                        <div class=\"col-sm-7 col-md-7 d-flex align-items-center\">\n                            <select class=\"form-select\" data-bind=\"options: totalRowAggregateOptions, value: totalRowAggregate\"></select>\n                            <button class=\"btn btn-sm btn-secondary ms-2\" title=\"Apply to all columns\" data-bind=\"click: function(){ applyAllTotalRowAggregate(!applyAllTotalRowAggregate()); }\">\n                                <span class=\"fa\" data-bind=\"css: applyAllTotalRowAggregate() ? 'fa-check' : 'fa-paste'\"></span>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n                <br />\n                <div data-bind=\"visible:$parent.ReportType() !='Html'\">\n                <div class=\"card card-body\">\n                    <div class=\"form-row align-items-center\">\n                        <div class=\"col-auto\">\n                            <b>Header Settings</b>\n                        </div>\n                    </div>\n                    <div class=\"row mb-3\">\n                        <div class=\"col\">\n                            <div class=\"mb-3\">\n                                <label class=\"form-label\">Pick Text Color</label>\n                                <div class=\"d-flex\">\n                                    <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: headerFontColor\" />\n                                    <input type=\"text\" style=\"width: 100px\" class=\"form-control me-2\" data-bind=\"value: headerFontColor\" />\n                                    <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllHeaderFontColor(!applyAllHeaderFontColor()); }\">\n                                        <span class=\"fa\" data-bind=\"css: applyAllHeaderFontColor() ? 'fa-check' : 'fa-paste'\"></span>\n                                    </button>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col\">\n                            <div class=\"mb-3\">\n                                <label class=\"form-label\">Pick Background Color</label>\n                                <div class=\"d-flex\">\n                                    <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: headerBackColor\" />\n                                    <input type=\"text\" style=\"width: 100px\" class=\"form-control me-2\" data-bind=\"value: headerBackColor\" />\n                                    <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllHeaderBackColor(!applyAllHeaderBackColor()); }\">\n                                        <span class=\"fa\" data-bind=\"css: applyAllHeaderBackColor() ? 'fa-check' : 'fa-paste'\"></span>\n                                    </button>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col d-flex align-items-center\">\n                            <div class=\"form-check me-3\">\n                                <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: headerFontBold\" id=\"headerFontBoldCheckbox\">\n                                <label class=\"form-check-label\" for=\"headerFontBoldCheckbox\">\n                                    Bold Text\n                                </label>\n                            </div>\n                            <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllHeaderBold(!applyAllHeaderBold()); }\">\n                                <span class=\"fa\" data-bind=\"css: applyAllHeaderBold() ? 'fa-check' : 'fa-paste'\"></span>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n                <br />\n                </div>\n                <div class=\"card card-body\">\n                    <div class=\"form-row align-items-center\">\n                        <div class=\"col-auto\">\n                            <b>Text Settings</b>\n                        </div>\n                    </div>\n                    <div class=\"row mb-3\">\n                        <div class=\"col\">\n                            <div class=\"mb-3\">\n                                <label class=\"form-label\">Pick Text Color</label>\n                                <div class=\"d-flex\">\n                                    <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: fontColor\" />\n                                    <input type=\"text\" style=\"width: 100px;\" class=\"form-control me-2\" data-bind=\"value: fontColor\" />\n                                    <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllFontColor(!applyAllFontColor()); }\">\n                                        <span class=\"fa\" data-bind=\"css: applyAllFontColor() ? 'fa-check' : 'fa-paste'\"></span>\n                                    </button>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col\">\n                            <div class=\"mb-3\">\n                                <label class=\"form-label\">Pick Background Color</label>\n                                <div class=\"d-flex\">\n                                    <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: backColor\" />\n                                    <input type=\"text\" style=\"width: 100px;\" class=\"form-control me-2\" data-bind=\"value: backColor\" />\n                                    <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllBackColor(!applyAllBackColor()); }\">\n                                        <span class=\"fa\" data-bind=\"css: applyAllBackColor() ? 'fa-check' : 'fa-paste'\"></span>\n                                    </button>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col d-flex align-items-center\">\n                            <div class=\"form-check me-3\">\n                                <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: fontBold\" id=\"fontBoldCheckbox\">\n                                <label class=\"form-check-label\" for=\"fontBoldCheckbox\">\n                                    Bold Text\n                                </label>\n                            </div>\n                            <button class=\"btn btn-sm btn-secondary\" title=\"Apply to all columns\" data-bind=\"click: function(){applyAllBold(!applyAllBold()); }\">\n                                <span class=\"fa\" data-bind=\"css: applyAllBold() ? 'fa-check' : 'fa-paste'\"></span>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n                <div class=\"padded-div\">\n                    <button class=\"btn btn-sm btn-primary\" data-bind=\"click: function() {addConditionalFormatSetting(null)}\">Add Conditional Formatting</button>\n                </div>\n                <div data-bind=\"foreach: fieldCondtionalFormats\" style=\"padding-left: 40px;\">\n                    <div class=\"card card-body\">\n                        <div class=\"row m-2\">\n                            <div class=\"col d-flex justify-content-start\">\n                                <b>Conditional Format #<span data-bind=\"text: $index()+1\"></span></b>\n                            </div>\n                            <div class=\"col d-flex justify-content-end\">\n                                <button class=\"btn btn-sm btn-secondary\" data-bind=\"click: $parent.removeSetting\">Remove</button>\n                            </div>\n                        </div>\n                        <div class=\"row mb-3\">\n                            <div class=\"col\">\n                                <div class=\"mb-3\">\n                                    <label class=\"form-label\">Pick Text Color</label>\n                                    <div class=\"d-flex\">\n                                        <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: fontColor\" />\n                                        <input type=\"text\" style=\"width: 100px;\" class=\"form-control me-2\" data-bind=\"value: fontColor\" />\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col\">\n                                <div class=\"mb-3\">\n                                    <label class=\"form-label\">Pick Background Color</label>\n                                    <div class=\"d-flex\">\n                                        <input type=\"color\" style=\"width: 50px; height: 38px;\" class=\"form-control me-2\" data-bind=\"value: backColor\" />\n                                        <input type=\"text\" style=\"width: 100px;\" class=\"form-control me-2\" data-bind=\"value: backColor\" />\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col d-flex align-items-center\">\n                                <div class=\"form-check me-3\">\n                                    <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: fontBold\" id=\"fontBoldCheckbox\">\n                                    <label class=\"form-check-label\" for=\"fontBoldCheckbox\">\n                                        Bold Text\n                                    </label>\n                                </div>\n                            </div>\n                        </div>\n\n                        <div class=\"row m-2\" data-bind=\"foreach: filter.Filters\">\n                            <div class=\"col-md-2\">\n                                Value\n                            </div>\n                            <div class=\"col-md-4\">\n                                <div data-bind=\"with: Field\">\n                                    <div class=\"form-group\">\n                                        <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: fieldFilter, value: $parent.Operator\" required></select>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col-md-4\">\n                                <div data-bind=\"with: Field\" data-parentprefix=\"C\">\n                                    <div data-bind=\"template: 'report-filter', data: $data\"></div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <br />\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-danger\" data-bind=\"click: cancelFieldOptions\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: saveFieldOptions\">Save Changes</button>\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"report-link-edit\">\n    <div class=\"modal-dialog\" style=\"max-width: 750px;\">\n        <div class=\"modal-content\" data-bind=\"with: editLinkField\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\">Setup Link Field</h5>\n            </div>\n            <div class=\"modal-body needs-validation\" data-bind=\"with: linkFieldItem\">\n                <div class=\"form-group row\">\n                    <label class=\"col-sm-5 col-md-5 control-label\">This field will link to</label>\n                    <div class=\"col-sm-7 col-md-7\">\n                        <select class=\"form-select\" required data-bind=\"options: linkTypes, value: selectedLinkType\"></select>\n                    </div>\n                </div>\n                <div data-bind=\"if: LinksToReport\">\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Link to this Report</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <div class=\"d-flex gap-2 align-items-start\">\n                                <select class=\"form-select\" required data-bind=\"options: savedReportsWithFolder, optionsText: function(r) { return (r.folderName ? r.folderName + ' › ' : '') + r.reportName }, optionsValue: 'reportId', optionsCaption: '', value: LinkedToReportId, select2: { placeholder: 'Search reports or folders...', allowClear: true }\"></select>\n                                <button type=\"button\" class=\"btn btn-sm btn-outline-success text-nowrap\" title=\"Create a new report to link to\" data-bind=\"click: createNewLinkedReport\">\n                                    New\n                                </button>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"checkbox\" data-bind=\"if: LinkedToReportId\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: SendAsFilterParameter\" />\n                            Send field value as Report Filter Parameter\n                        </label>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"if: SendAsFilterParameter\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Link to this Report Filter</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <select class=\"form-select\" required data-bind=\"options: allFields, optionsText: function(f) { return (f.tableName ? f.tableName + ' › ' : '') + f.fieldName }, optionsValue: 'fieldId', value: SelectedFilterId, optionsCaption: 'Choose the Field to Filter by value'\"></select>\n                        </div>\n                    </div>\n                    <div data-bind=\"if: LinkedToReportId\">\n                        <div class=\"mt-2 mb-1\">\n                            <label class=\"form-check-label\">\n                                <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: isSubReportOnly, click: function() { toggleLinkedReportSubReportOnly(); return true; }\" />\n                                <span class=\"small\">Only use as sub/linked report</span>\n                            </label>\n                            <div class=\"small text-muted ms-4\">\n                                When checked, this report will be hidden from report folders and search results, and will only be run as a linked or sub report from the parent report.\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <div data-bind=\"ifnot: LinksToReport\">\n                    <div class=\"form-group row\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Link to this URL</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" required placeholder=\"Enter a url to open\" data-bind=\"value: LinkToUrl\" title=\"Valid URL needs to start with http:// or https://\">\n                        </div>\n                    </div>\n                    <div class=\"checkbox\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: SendAsQueryParameter\" />\n                            Send field value as Query Parameter\n                        </label>\n                    </div>\n                    <div class=\"form-group row\" data-bind=\"if: SendAsQueryParameter\">\n                        <label class=\"col-sm-5 col-md-5 control-label\">Parameter Name to use</label>\n                        <div class=\"col-sm-7 col-md-7\">\n                            <input type=\"text\" class=\"form-control\" required placeholder=\"Enter parameter name to send value as\" data-bind=\"value: QueryParameterName\">\n                        </div>\n                    </div>\n                    <br />\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-danger\" data-bind=\"click: removeLinkField\">Remove Link</button>\n                <button type=\"button\" class=\"btn btn-outline-primary\" data-bind=\"visible: linkFieldItem.LinksToReport() && linkFieldItem.LinkedToReportId(), click: function() { saveLinkField(); linkFieldItem.editLinkedReport(); }\">Edit Linked Report</button>\n                <button type=\"button\" class=\"btn btn-primary\" data-bind=\"click: saveLinkField\">Save Changes</button>\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-choose-visual\">\n    <div style=\"overflow-x: auto;\">\n    <div class=\"btn-group\" role=\"group\" aria-label=\"Visualization Options\" style=\"flex-wrap: nowrap; min-width: max-content;\">\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('List'); }, css: { active: ReportType()=='List' }, attr: { 'data-chart-id': 'List' }\">\n            <span class=\"fa fa-2x fa-list-alt\"></span>\n            <p>List</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Summary'); }, css: { active: ReportType()=='Summary',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Summary' }\">\n            <span class=\"fa fa-2x fa-table\"></span>\n            <p>Summary</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Bar'); }, css: { active: ReportType()=='Bar',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Bar' }\">\n            <span class=\"fa fa-2x fa-bar-chart\"></span>\n            <p>Bar</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Pie'); }, css: { active: ReportType()=='Pie',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Pie' }\">\n            <span class=\"fa fa-2x fa-pie-chart\"></span>\n            <p>Pie</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Line'); }, css: { active: ReportType()=='Line',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Line' }\">\n            <span class=\"fa fa-2x fa-line-chart\"></span>\n            <p>Line</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Combo'); }, css: { active: ReportType()=='Combo',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Combo' }\">\n            <span class=\"fa fa-2x fa-signal\"></span>\n            <p>Combo</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Html'); }, css: { active: ReportType()=='Html',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Html' }\">\n            <span class=\"fa fa-2x fa-code\"></span>\n            <p>Custom</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Map'); }, css: { active: ReportType().indexOf('Map')==0,disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Map' }\">\n            <span class=\"fa fa-2x fa-globe\"></span>\n            <p>Map</p>\n        </button>\n        <button class=\"btn btn-outline-secondary chart-type-btn\" data-bind=\"click: function(){ setReportType('Single'); }, css: { active: ReportType()=='Single',disabled: hasFunctionField() }, attr: { 'data-chart-id': 'Single' }\">\n            <span class=\"fa fa-2x fa-window-maximize\"></span>\n            <p>KPI</p>\n        </button>\n        <button class=\"btn btn-outline-secondary\" data-bind=\"click: showMoreCharts\" title=\"Explore more visualization options\">\n            <span class=\"fa fa-2x fa-th-large\"></span>\n            <p>More...</p>\n        </button>\n    </div>\n    </div>\n    <!-- Smart Suggestion -->\n    <div class=\"smart-suggestion mt-2\" data-bind=\"visible: smartSuggestion() && (showHints() || activeDesign())\">\n        <i class=\"fas fa-lightbulb text-warning\"></i>\n        <span data-bind=\"text: smartSuggestion\"></span>\n        <a href=\"#\" class=\"ms-2 small\" data-bind=\"click: applySuggestion\">\n            <i class=\"fa fa-check\"></i> Apply\n        </a>\n    </div>\n</script>\n\n<!-- ══════════════════ MORE CHARTS MODAL ══════════════════ -->\n<div class=\"modal\" id=\"moreChartsModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-xl modal-dialog-centered\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header py-2\">\n                <h5 class=\"modal-title\" id=\"moreChartsModalLabel\">\n                    <i class=\"fa fa-th-large\"></i> Choose a Visualization\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body p-0\" data-bind=\"stopBindings: true\">\n                <div class=\"d-flex more-charts-layout\">\n                    <!-- Left: Chart Type Grid (rendered programmatically by showMoreCharts) -->\n                    <div class=\"more-charts-grid-panel\" id=\"moreChartsGridPanel\"></div>\n                    <!-- Right: Detail Preview Panel (rendered programmatically by selectMoreChart) -->\n                    <div class=\"more-charts-detail-panel\" id=\"moreChartsDetailPanel\"></div>\n                </div>\n            </div>\n            <div class=\"modal-footer py-2\">\n                <button type=\"button\" class=\"btn btn-secondary btn-sm\" data-bs-dismiss=\"modal\">Close</button>\n            </div>\n        </div>\n    </div>\n</div>\n\n<script type=\"text/html\" id=\"designer-choose-data\">\n    <div>\n        <div class=\"float-start btn-group btn-group-toggle\" role=\"group\" data-bind=\"if: ReportID() <= 0\">\n            <label class=\"btn btn-sm btn-light\" style=\"margin-right: 0px;\" title=\"You can change the Data source only when creating a new report, changing this will clear all selections\" data-bind=\"css: { active: !useStoredProc() }\">\n                <input type=\"radio\" name=\"dataoption\" id=\"table\" checked data-bind=\"checked: useStoredProc, checkedValue: false\"> Dynamic\n            </label>\n            <label class=\"btn btn-sm btn-light\" data-bind=\"css: { active: useStoredProc() }\">\n                <input type=\"radio\" name=\"dataoption\" id=\"proc\" value=\"1\" data-bind=\"checked: useStoredProc, checkedValue: true\"> Predefined\n            </label>\n        </div>\n        <div class=\"float-end\">\n            <a href=\"#\" class=\"btn btn-sm\" style=\"font-size: 11px; padding: 3px 8px;\" title=\"Add Custom Field using Formula\" data-bind=\"hidden: isFunctionField() || useStoredProc(), click: cancelFormulaField, css: {'btn-primary': !isFormulaField(), 'btn-danger btn-sm': isFormulaField}\">\n                <!-- ko ifnot: isFormulaField() -->Custom Field<!-- /ko -->\n                <!-- ko if: isFormulaField() --><i class=\"fa fa-times\"></i><!-- /ko -->\n            </a>\n            <a href=\"#\" class=\"btn btn-sm\" style=\"font-size: 11px; padding: 3px 8px;\" title=\"Add Custom Field using Function\" data-bind=\"hidden:isFormulaField() || useStoredProc() || !ko.unwrap(appSettings.useFunctions) || ReportType() !== 'List' , click: function(){designFunctionField()}, css: {'btn-primary': !isFunctionField(), 'btn-danger btn-sm': isFunctionField}\">\n                <!-- ko ifnot: isFunctionField() -->Function Field<!-- /ko -->\n                <!-- ko if: isFunctionField() --><i class=\"fa fa-times\"></i><!-- /ko -->\n            </a>\n        </div>\n    </div>\n    <div class=\"clearfix\"></div>\n    <div class=\"row\">\n        <div class=\"col-md-12\" data-bind=\"disable: isFormulaField, hidden: useStoredProc\">\n            <div data-bind=\"with: textQuery.searchFields\">\n                <select class=\"form-control\" data-bind=\"select2: {dropdownParent: $root.activeDesign() ? $('#choose-data-design') : $('#choose-data-card'), placeholder: 'Search for a Data Field...', ajax: { url: url, dataType: 'json', data: query, processResults: processResults, headers: headers }, minimumInputLength: 2, allowClear: true }, value: selectedOption\"></select>\n            </div>\n        </div>\n\n        <div class=\"col-md-12\" data-bind=\"visible: useStoredProc\">\n            <div>\n                <select class=\"form-control\" data-bind=\"select2Value: {dropdownParent: $root.activeDesign() ? $('#choose-data-design') : $('#choose-data-card')}, options: Procs, optionsCaption: 'Choose Section...', optionsText: 'DisplayName', value: SelectedProc, visible: useStoredProc\"></select>\n            </div>\n        </div>\n        <div class=\"col-md-12\" data-bind=\"hidden: useStoredProc\">\n            <div class=\"d-flex justify-content-between align-items-center mb-2\" style=\"padding-top: 15px;\">\n                <span>\n                    Select Data to use in Report\n                    <i class=\"fa fa-info-circle text-muted\" data-toggle=\"tooltip\" title=\"Choose a table to show fields to select.\"></i>\n                </span>\n            </div>\n\n            <div class=\"data-select-tree\">\n                <!-- ko foreach: CategorizedTables -->\n                <div class=\"mb-3\">\n                    <div data-bind=\"click: function() { isExpanded(!isExpanded()); }, visible: categoryName\" style=\"cursor: pointer;\">\n                        <i class=\"fa\" data-bind=\"css: isExpanded() ? 'fa-chevron-down text-secondary' : 'fa-chevron-right text-secondary'\"></i>\n                        <i class=\"fa\" data-bind=\"css: isExpanded() ? 'fa-folder-open' : 'fa-folder'\"></i>\n                        <span data-bind=\"text: categoryName\" class=\"ml-2\"></span>\n                    </div>\n                    <div class=\"report-list\" data-bind=\"visible: isExpanded(), foreach: tables\" style=\"padding-left: 15px;\">\n                        <div class=\"row border-bottom py-2 w-100\">\n                            <div class=\"col-md-12\">\n                                <div class=\"float-start\" data-bind=\"click: function() { selectTable($data); }, css: {'text-muted': !isEnabled()}, style: {cursor: isEnabled() ? 'pointer' : ''}, attr: {title: !isEnabled() ? 'Cannot use table as joins do not exist': ''}\">\n                                    <span class=\"text-secondary fa\" data-bind=\"css: isEnabled() ? ($data === $parents[1].SelectedTable() ? 'fa-chevron-down' : 'fa-chevron-right') : 'fa-ban'\"></span>&nbsp;\n                                    <span class=\"fa fa-table\"></span>&nbsp;<span data-bind=\"text: tableName\" class=\"\"></span>\n                                </div>\n                                <div class=\"float-end\" data-bind=\"visible: $data === $parents[1].SelectedTable() && !$parents[1].isFormulaField() && !$parents[1].SelectedTable().dynamicColumns\">\n                                    <a href=\"#\" class=\"small text-muted\" data-bind=\"click: $parents[1].MoveAllFields\">Select all</a> |\n                                    <a href=\"#\" class=\"small text-muted\" data-bind=\"click: $parents[1].RemoveSelectedFields\">Remove all</a>\n                                </div>\n                            </div>\n\n                            <!-- Fields Expand Here -->\n                            <div data-bind=\"visible: $data === $parents[1].SelectedTable()\" style=\"padding-left: 30px;\">\n                                <!-- ko foreach: $parents[1].ChooseFields -->\n                                <div class=\"row border-bottom py-2 align-items-center w-100\">\n                                    <div class=\"checkbox\">\n                                        <label>\n                                            <input type=\"checkbox\" data-bind=\"checkedInArray: {array: $parents[2].isFormulaField() ? $parents[2].formulaFields : $parents[2].SelectedFields, value: $data}\">\n                                            <span data-bind=\"text: fieldName\"></span>\n                                        </label>\n                                    </div>\n                                </div>\n                                <!--/ko-->\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <!-- /ko -->\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-selected-data\">\n    <div data-bind=\"visible: SelectedFields().length == 0\">\n        Please choose data\n    </div>\n    <div data-bind=\"if: SelectedFields().length > 0\">\n        <div data-bind=\"visible: ReportType()=='Bar'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Bar Graph, the first field below will show on the x-axis. All other numeric fields will show on y-axis.\n            </div>\n            <div class=\"form-group row small\">\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: barChartHorizontal\" />\n                Horizontal Bar Chart\n                </label>\n            </div>\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: barChartStacked\" />\n                Stacked Bar Chart\n                </label>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Pie'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Pie Graph, the first field below will be grouped, and the first numeric field will show as the ratio.\n            </div>\n            <div class=\"form-group row small\">\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: pieChartDonut\" />\n                Donut Chart\n                </label>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Radar'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Radar chart, the first field is the category label. All other numeric fields become axes on the radar. Each row is a separate polygon.\n            </div>\n        </div>\n        <div data-bind=\"visible: ReportType()=='Polar'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Polar Stacked Bar, the first field is the category. Each numeric field becomes a stacked segment on the circular axis.\n            </div>\n        </div>\n        <div data-bind=\"visible: ReportType()=='Treemap'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Treemap, the data must be in a hierarchical format with 2nd column having parent and third column having a numeric value. The data must have a single root node having null as its parent as well.\n            </div>\n        </div>\n        <div data-bind=\"visible: ReportType()=='HeatMap'\" class=\"card card-body\">\n            <div class=\"alert alert-info mb-3\">\n                <span class=\"fas fa-lightbulb fa-2x\"></span>&nbsp;For HeatMap, the first two columns must be numeric values representing\n                <strong>Latitude</strong> and <strong>Longitude</strong>. At least one additional numeric column is required to provide the\n                <strong>intensity</strong> of each point.\n            </div>\n\n            <div class=\"form-group row mb-2\">\n                <div class=\"checkbox col-6\">\n                    <label>\n                        <input type=\"checkbox\" data-bind=\"checked: heatMapOptions.showMarker\" />\n                        Show Marker\n                    </label>\n                </div>\n            </div>\n\n            <div class=\"form-group row mb-3\">\n                <label class=\"col-12 fw-bold\">Heatmap Colors</label>\n\n                <div class=\"col-4 mb-2\">\n                    <input type=\"color\" class=\"color-picker\"\n                            data-bind=\"value: heatMapOptions.gradient1\" title=\"Gradient 1\" />\n                </div>\n                <div class=\"col-4 mb-2\">\n                    <input type=\"color\" class=\"color-picker\"\n                            data-bind=\"value: heatMapOptions.gradient2\" title=\"Gradient 2\" />\n                </div>\n                <div class=\"col-4 mb-2\">\n                    <input type=\"color\" class=\"color-picker\"\n                            data-bind=\"value: heatMapOptions.gradient3\" title=\"Gradient 3\" />\n                </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Line'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Line Graph, the first field below will show on the x-axis. All other fields will numeric fields will show on y-axis.\n            </div>\n            <div class=\"form-group row small\">\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: lineChartArea\" />\n                Area Chart\n                </label>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Combo'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Combo Graph, the first field below will show on the x-axis. All other numeric fields will show on y-axis, and you can choose display each series as line, bar or area.\n            </div>\n            <div class=\"form-group row small\">\n            <div class=\"col-6\">\n                <label>Default Series Type</label>\n                <select class=\"form-select form-select-sm\" data-bind=\"options: seriesTypes, optionsText: 'label', optionsValue: 'value', value: comboChartType\"></select>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Pivot'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Transpose, the first field below will be used to Transpose the rows as columns, and it must be grouped.\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Single'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-0\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;KPI is a single value report that is ideal for placing on a Dashboard. All fields except one must be hidden for Widgets.\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Html'\" class=\"card card-body\">\n            <div class=\"form-group row small\">\n            <div class=\"checkbox col-6\">\n                <label>\n                <input type=\"checkbox\" data-bind=\"checked: dontGroupCustom\" />\n                List (Don't Summarize)\n                </label>\n            </div>\n            </div>\n        </div>\n\n        <div data-bind=\"visible: ReportType()=='Map'\" class=\"card card-body\">\n            <div class=\"alert alert-info small py-1 mb-2\">\n            <span class=\"fas fa-lightbulb\"></span>&nbsp;For Map Graph, the first field below has to be a Region name (e.g. Country) or use Latitude/Longitude columns for marker mode.\n            </div>\n            <div class=\"form-group row small\">\n            <label class=\"col-sm-3 control-label\">Map Display</label>\n            <div class=\"col-sm-5\">\n                <select class=\"form-select form-select-sm\" data-bind=\"options: mapRegions, value: mapRegion\"></select>\n            </div>\n            </div>\n            <div class=\"form-group row small\" data-bind=\"visible: mapRegion() == 'Other'\">\n            <label class=\"col-sm-3 control-label\">Region Name</label>\n            <div class=\"col-sm-5\">\n                <input type=\"text\" class=\"form-control form-control-sm\" placeholder=\"e.g. Texas, United Kingdom, Australia\" data-bind=\"value: otherMapRegion, valueUpdate: 'input'\" />\n            </div>\n            <div class=\"col-sm-4 small text-muted pt-1\">Enter any country, state, or region name</div>\n            </div>\n        </div>\n    </div>\n    <ul class=\"list-group\" data-bind=\"sortable: { data: SelectedFields, options: { handle: '.sortable', cursor: 'move', placeholder: 'drop-highlight' }, strategyMove: true }\">\n        <li class=\"list-group-item\">\n            <div class=\"row\">\n                <div class=\"col-5\">\n                    <span class=\"sortable float-start\" style=\"padding-right: 15px;\" data-bind=\"ifnot: $parent.useStoredProc\">\n                        <span class=\"fa fa-ellipsis-v\" aria-hidden=\"true\" title=\"Drag to reorder\"></span>\n                    </span>\n                    <span class=\"fa fa-columns\"></span>\n                    <span data-bind=\"text: selectedFieldName()\"></span>\n                    <span data-bind=\"text: isFormulaField() ? '(' + fieldFormat() + ')' : ''\"></span>\n                    <span data-bind=\"visible: !$parent.isFieldValidForYAxis($index(), fieldType || fieldFormat(), selectedAggregate()) && $parent.ReportType() !='Treemap' && $parent.isChart()\">\n                        <span class=\"badge bg-danger\" data-bind=\"visible: !groupInGraph()\">Will not show in <span data-bind=\"text: $parent.ReportType\"></span>Chart</span>\n                    </span>\n                    <span data-bind=\"visible: $parent.IsPivotFieldLastColumn($index(),selectedAggregate())\">\n                        <span class=\"badge bg-danger\" >Pivot field cannot be the last column.</span>\n                    </span>\n                    <span data-bind=\"visible: $parent.IsDynamicFieldFirstColumn($index())\">\n                        <span class=\"badge bg-danger\" >Dynamic cannot be first column.</span>\n                    </span>\n                </div>\n                <div class=\"col-7 d-flex flex-row-reverse\">\n                    <div style=\"margin-top: -5px;\" data-bind=\"if: $parent.AggregateReport() && !$parent.useStoredProc()\">\n                        <div class=\"d-flex align-items-center\">\n                            <select class=\"form-select form-control-sm\" data-bind=\"options: $parent.canDrilldown() && $index()>0 ? fieldAggregateWithDrilldown : fieldAggregate, value: selectedAggregate\"></select>\n                            <i class=\"fa fa-info-circle ms-1 text-muted aggregate-help-tip\" style=\"cursor:help; font-size:12px;\"\n                               data-bind=\"visible: $parent.showHints(), attr: { 'data-agg-tooltip': $parent.getAggregateTooltip($data) }\"></i>\n                        </div>\n                    </div>\n\n                    <div  style=\"padding-right: 10px;\" data-bind=\"ifnot: $parent.useStoredProc\">\n                        <span class=\"fa fa-trash\" title=\"Cannot Delete Required Filter\" data-bind=\"visible: forceFilterForTable\"></span>\n                        <span class=\"fa fa-trash\" style=\"cursor: pointer;\" aria-hidden=\"true\" title=\"Delete this Field\" data-bind=\"click: $parent.RemoveField, hidden: forceFilterForTable\"></span>\n                    </div>\n                    <!--<div  style=\"padding-right: 10px;\" data-bind=\"ifnot: $parent.useStoredProc\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: function(){ filterOnFly(!filterOnFly()); }, css: {active: filterOnFly()==true}\">\n                            <span class=\"fa fa-filter\" aria-hidden=\"true\" title=\"Filter by this field on the Report\"></span>\n                        </span>\n                    </div>-->\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.ReportType()!='Pivot'\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: toggleDisable\">\n                            <span data-bind=\"\n                                css: {\n                                    'fa': true,\n                                    'fa-close': disabled(),\n                                    'fa-check': !disabled(),\n                                    'text-danger': disabled()\n                                },\n                                attr: {\n                                    title: disabled() ? 'Excluded from the Report' : 'Included in the Report'\n                                }\n                            \" aria-hidden=\"true\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.ReportType()!='Pivot' && $parent.ReportType()!='List' && !$parent.useStoredProc()\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: function(){ hideInDetail(!hideInDetail()); }, css: {active: hideInDetail()==true}\">\n                            <span class=\"fa fa-eye-slash\" aria-hidden=\"true\" title=\"Hide in Details\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.isFieldValidForYAxis($index(), fieldType || fieldFormat(), selectedAggregate())  && $parent.isChart() && $index()>0\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: function(){ groupInGraph(!groupInGraph()); }, css: {active: groupInGraph()==false}\">\n                            <span class=\"fas fa-signal\" aria-hidden=\"true\" title=\"Include in series\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.ReportType()!='Pivot'\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: setupLinkField, css: {active: linkField()==true}\">\n                            <span class=\"fa fa-link\" aria-hidden=\"true\" title=\"Link to another Report or Url\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"visible: $parent.ReportType()=='Combo' && $parent.isFieldValidForYAxis($index(), fieldType || fieldFormat(), selectedAggregate())  && $parent.isChart() && $index()>0\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: function(){ seriesType(seriesType() == 'line' ? 'area' : (seriesType()=='bars' ? 'line' : 'bars')); }\">\n                            <span class=\"fa\" aria-hidden=\"true\" data-bind=\"css: {'fa-line-chart': seriesType() == 'line', 'fa-bar-chart': seriesType() == 'bars', 'fa-area-chart': seriesType()=='area' }, attr: {title: seriesType}\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: setupFieldOptions\">\n                            <span class=\"fa fa-gear\" aria-hidden=\"true\" title=\"More Options\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"if: isFormulaField\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: editFormulaField\">\n                            <span class=\"fa fa-pencil\" aria-hidden=\"true\" title=\"Edit Formula Field\"></span>\n                        </span>\n                    </div>\n                    <div  style=\"padding-right: 10px;\" data-bind=\"if: isFormulaField\">\n                        <span class=\"button-box no-padding\" tabindex=\"0\" data-bind=\"click: duplicateFormulaField\">\n                            <span class=\"fa fa-copy\" aria-hidden=\"true\" title=\"Duplicate Formula Field\"></span>\n                        </span>\n                    </div>\n                </div>\n            </div>\n        </li>\n    </ul>\n</script>\n\n<script type=\"text/html\" id=\"designer-sub-report\">\n    <p class=\"text-muted mb-3\">\n        Linked reports are available to add as sub reports.\n        Selecting sub reports will restrict the report to <strong>one record per page</strong>.\n    </p>\n\n    <div class=\"mb-3\">\n        <select class=\"form-select\"\n                data-bind=\"options: linkedReportFields,\n                            optionsText: 'name',\n                            value: selectedSubReport,\n                            optionsCaption: 'Select a linked report...'\">\n        </select>\n    </div>\n    <ul class=\"list-group\"\n        data-bind=\"sortable: {\n                        data: subReports,\n                        options: { handle: '.sortable', cursor: 'move', placeholder: 'drop-highlight' }\n                    }\">\n        <li class=\"list-group-item\">\n            <div class=\"d-flex justify-content-between align-items-center\">\n                <span>\n                    <i class=\"fa fa-bars sortable me-2\" style=\"cursor:move;\"></i>\n                    <span data-bind=\"text: name\"></span>\n                </span>\n                <span>\n                    <button type=\"button\" class=\"btn btn-sm btn-outline-primary me-1\" title=\"Edit sub report\"\n                            data-bind=\"click: $parent.editSubReport\">\n                        <i class=\"fa fa-edit\"></i> Edit\n                    </button>\n                    <button type=\"button\" class=\"btn btn-sm btn-outline-danger\"\n                            data-bind=\"click: $parent.removeSubReport\">\n                        Delete\n                    </button>\n                </span>\n            </div>\n            <div class=\"mt-1 d-flex gap-3 align-items-center flex-wrap\">\n                <label class=\"form-check-label small\">\n                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: isSubReportOnly, click: function() { setTimeout(function() { $parent.toggleSubReportOnly($data); }, 0); return true; }\" />\n                    Sub report only\n                    <i class=\"fa fa-question-circle text-muted\" title=\"When checked, this report will be hidden from folders and search, and can only run as a child report from here\"></i>\n                </label>\n                <label class=\"form-check-label small\">\n                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: hideTitle\" />\n                    Hide title\n                </label>\n                <label class=\"form-check-label small\">\n                    <input type=\"checkbox\" class=\"form-check-input\" data-bind=\"checked: hidePager\" />\n                    Hide pager\n                </label>\n            </div>\n        </li>\n    </ul>\n</script>\n\n<script type=\"text/html\" id=\"designer-html\">\n    <div class=\"row align-items-center mb-1\">\n        <div class=\"col-md-4\">\n        <select class=\"form-select\" data-bind=\"options: SelectedFields, value: SelectFieldToInsert, optionsCaption: 'Select a field...', optionsText: 'selectedFieldName'\"></select>\n        </div>\n        <div class=\"col-auto dropdown\">\n            <button class=\"btn btn-outline-secondary btn-sm dropdown-toggle\" type=\"button\" data-bs-toggle=\"dropdown\">\n            <i class=\"fa fa-table\"></i> Insert as Table\n            </button>\n            <ul class=\"dropdown-menu\">\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertFieldTableTransposed\">Transposed</a></li>\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertFieldTableStandard\">Standard</a></li>\n                <!-- ko if: hasOuterGroupFields -->\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertGroupedTable\">Grouped</a></li>\n                <!-- /ko -->\n                <li><hr class=\"dropdown-divider\"></li>\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertHeaderBreak\">Add Header Break</a></li>\n                <li><a class=\"dropdown-item\" href=\"#\" data-bind=\"click: insertFooterBreak\">Add Footer Break</a></li>\n            </ul>\n        </div>\n        <!-- ko if: subReports().length > 0 -->\n        <div class=\"col-auto dropdown d-flex align-items-center gap-2\">\n            <button class=\"btn btn-outline-secondary btn-sm dropdown-toggle\" type=\"button\" data-bs-toggle=\"dropdown\" title=\"Insert a selected sub report inline at cursor position\">\n                <i class=\"fa fa-bookmark\"></i> Insert Sub Report\n            </button>\n            <i class=\"fa fa-info-circle text-muted\"\n               data-bs-toggle=\"tooltip\"\n               data-bs-placement=\"top\"\n               title=\"Note: If you insert Sub Reports in custom report, only inserted sub reports will show and other sub reports will not render\">\n            </i>\n\n            <ul class=\"dropdown-menu\" data-bind=\"foreach: subReports\">\n                <li>\n                    <a class=\"dropdown-item\" href=\"#\"\n                       data-bind=\"text: name, click: function() { $parent.insertSubReportPlaceholder($data); }\">\n                    </a>\n                </li>\n            </ul>\n        </div>\n        <!-- /ko -->\n        <div class=\"col-md-auto ms-auto\">\n        <label class=\"form-check-label\">\n            <input class=\"form-check-input me-2\" type=\"checkbox\" data-bind=\"checked: cardView\">\n            Card Layout\n        </label>\n        </div>\n    </div>\n    <div class=\"mb-3\">\n        <textarea data-bind=\"summernote: reportHtml\"></textarea>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-sort\">\n    <div data-bind=\"ifnot: useStoredProc\">\n         <div class=\"form-group row align-items-center flex-nowrap\">\n             <label class=\"col-auto control-label\">Sort By</label>\n             <div class=\"col\">\n                 <select class=\"form-select form-select-sm\"\n                     data-bind=\"options: FilteredFields, optionsText: 'selectedFieldName', optionsValue: 'fieldId', value: SortByField, optionsCaption: 'Select field to sort...', allowClear: true\">\n                 </select>\n             </div>\n             <div class=\"col-auto d-flex gap-1\">\n                 <button class=\"btn btn-sm btn-secondary\"\n                     data-bind=\"text: !SortDesc() ? '▲ Ascending' : 'Descending ▼', click: function() { SortDesc(!SortDesc()); return false; }\">\n                 </button>\n                 <button class=\"btn btn-sm btn-secondary\"\n                     data-bind=\"click: addSortField\">\n                     Add Sort\n                 </button>\n             </div>\n         </div>\n\n         <div data-bind=\"foreach: SortFields\">\n             <div class=\"form-group row align-items-center flex-nowrap\">\n                 <label class=\"col-auto control-label\">&nbsp;&nbsp;Then Sort By</label>\n                 <div class=\"col\">\n                     <select class=\"form-select form-select-sm\" required\n                         data-bind=\"options: $parent.FilteredFields, optionsText: 'selectedFieldName', optionsValue: 'fieldId', value: sortByFieldId\">\n                     </select>\n                 </div>\n                 <div class=\"col-auto d-flex gap-1\">\n                     <button class=\"btn btn-sm btn-secondary\"\n                         data-bind=\"click: remove\">\n                         Remove Sort\n                     </button>\n                     <button class=\"btn btn-sm btn-secondary\"\n                         data-bind=\"text: !sortDesc() ? '▲ Ascending' : 'Descending ▼', click: function() { sortDesc(!sortDesc()); return false; }\">\n                     </button>\n                     <button class=\"btn btn-sm btn-secondary\"\n                         data-bind=\"click: $parent.addSortField\">\n                         Add Sort\n                     </button>\n                 </div>\n             </div>\n         </div>\n     </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-header-footer\">\n    <div class=\"form-group mb-2\">\n        <label class=\"control-label small text-muted\"><i class=\"fa fa-window-maximize\"></i> Report Header</label>\n        <select class=\"form-select form-select-sm\" style=\"width: 100%;\"\n                data-bind=\"options: reportHeadersList, optionsText: 'label', optionsValue: 'id', value: ReportHeaderId\"></select>\n    </div>\n    <hr class=\"my-1\" />\n    <div class=\"form-group\">\n        <label class=\"control-label small text-muted\"><i class=\"fa fa-window-minimize\"></i> Report Footer</label>\n        <div class=\"form-check\">\n            <label class=\"form-check-label small\">\n                <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: UseReportFooterInReport\" />\n                Include the report footer in this report\n            </label>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"designer-options\">\n    <div class=\"row\">\n        <div class=\"col-md-5\">\n            <div data-bind=\"visible: ReportType()!='Pivot' && ReportType()!='Custom'\">\n                <div class=\"checkbox\">\n                    <label>\n                        <input type=\"checkbox\" data-bind=\"checked: IncludeSubTotal\" />\n                        Include Total Row\n                    </label>\n                </div>\n                <div data-bind=\"visible: IncludeSubTotal()\" style=\"padding-left: 20px; margin-top: 4px; margin-bottom: 4px;\">\n                    <div class=\"form-check form-check-inline\">\n                        <input class=\"form-check-input\" type=\"radio\" data-bind=\"checked: totalRowFormat\" value=\"row\" />\n                        <label class=\"form-check-label\">As Total Row</label>\n                    </div>\n                    <div class=\"form-check form-check-inline\">\n                        <input class=\"form-check-input\" type=\"radio\" data-bind=\"checked: totalRowFormat\" value=\"table\" />\n                        <label class=\"form-check-label\">As Total Table</label>\n                    </div>\n                </div>\n                <div data-bind=\"visible: IncludeSubTotal() && hasOuterGroupFields()\" style=\"padding-left: 20px; margin-top: 2px; margin-bottom: 4px;\">\n                    <div class=\"checkbox\" style=\"margin-top: 0;\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: subTotalPerGroup\" />\n                            Sub Total Per Group\n                        </label>\n                    </div>\n                </div>\n                <div class=\"checkbox\" data-bind=\"visible: hasPivotColumn()\">\n                    <label>\n                        <input type=\"checkbox\" data-bind=\"checked: IncludeColumnTotal\" />\n                        Include Total Column\n                    </label>\n                </div>            \n            </div>\n            <div class=\"checkbox\" data-bind=\"hidden: AggregateReport\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowUniqueRecords\" />\n                    Show only Unique Records\n                </label>\n            </div>\n            <div class=\"checkbox\" data-bind=\"visible: ReportType()!='List'\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowExpandOption\" />\n                    Don't Show Expand Option\n                </label>\n            </div>\n                <div class=\"checkbox\" data-bind=\"visible: isChart\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowDataWithGraph\" />\n                    Show Data along with Graph\n                </label>\n            </div>\n            <!-- ko if: adminMode() -->\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: bypassEnabled\" />\n                    Bypass Data Filters\n                </label>\n            </div>\n            <!-- ko if: bypassEnabled() -->\n            <div style=\"padding-left: 20px;\">\n                <div class=\"radio\">\n                    <label>\n                        <input type=\"radio\" name=\"bypassMode\" value=\"all\" data-bind=\"checked: bypassMode\" />\n                        Bypass All Data Filters\n                    </label>\n                </div>\n                <div class=\"radio\">\n                    <label>\n                        <input type=\"radio\" name=\"bypassMode\" value=\"specific\" data-bind=\"checked: bypassMode\" />\n                        Bypass Specific Filters\n                    </label>\n                </div>\n                <!-- ko if: bypassMode() === 'specific' -->\n                <div style=\"padding-left: 20px;\">\n                    <!-- ko if: availableDataFilterIds().length > 0 -->\n                    <!-- ko foreach: availableDataFilterIds() -->\n                    <div class=\"checkbox\">\n                        <label>\n                            <input type=\"checkbox\" data-bind=\"checked: $parent.bypassSpecificIds, checkedValue: $data\" />\n                            <span data-bind=\"text: $data\"></span>\n                        </label>\n                    </div>\n                    <!-- /ko -->\n                    <!-- /ko -->\n                    <!-- ko if: availableDataFilterIds().length === 0 -->\n                    <div class=\"form-group mt-1\">\n                        <label class=\"text-muted small\">Enter filter column names (comma-separated):</label>\n                        <input type=\"text\" class=\"form-control form-control-sm\" placeholder=\"e.g. TenantId,UserId\" data-bind=\"value: bypassSpecificIdsText, valueUpdate: 'input'\" />\n                    </div>\n                    <!-- /ko -->\n                </div>\n                <!-- /ko -->\n            </div>\n            <!-- /ko -->\n            <!-- /ko -->\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: DontExecuteOnRun\" />\n                    Wait to Select Filters before Running Report\n                </label>\n            </div>\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowFilterDetails\" />\n                    Include Filter Details on Report\n                </label>\n            </div>\n            <div class=\"form-group row\">\n                <div class=\"checkbox col-md-5\">\n                    <label>\n                        <input type=\"checkbox\" data-bind=\"checked: maxRecords\" />\n                        Max Records\n                    </label>\n                </div>\n                <div class=\"col-md-5\" data-bind=\"if: maxRecords\">\n                    <input type=\"number\" style=\"width: 150px;\" class=\"form-control\" required placeholder=\"Only top n...\" data-bind=\"value: OnlyTop, visible: maxRecords\">\n                </div>\n            </div>\n            <div class=\"form-group row\">\n                <div class=\"checkbox col-md-5\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: changePageSize, disable: subReports().length > 0\" />\n                    Change Page Size\n                </label>\n                </div>\n                <div class=\"col-md-5\"\n                    data-bind=\"visible: changePageSize,\n                                css: { 'text-muted': subReports().length > 0 }\">\n                <select style=\"width: 150px;\" class=\"form-select\"\n                        data-bind=\"options: [1,10,30,50,100,150,200,500,1000],\n                                    value: DefaultPageSize,\n                                    disable: subReports().length > 0\">\n                </select>\n                </div>\n                <!-- Force default to 1 if sub reports selected -->\n                <div class=\"col-12 mt-1\" data-bind=\"visible: subReports().length > 0\">\n                    <small class=\"text-danger\">\n                        Page size is restricted to 1 when sub reports are selected.\n                    </small>\n                </div>\n            </div>\n        </div>\n        <div class=\"col-md-7\">\n            <p><span class=\"fa fa-paint-brush\"></span> Pick Report Format</p>\n            <div>\n                <!-- ko foreach: tableStyles -->\n                <div class=\"dropdown-option\" data-bind=\"title: $data.name, click: $parent.selectStyle, css: {'dropdown-option-selected': $parent.selectedStyle() == $data.colorscheme}\">\n                    <div class=\"mini-table-preview\" data-bind=\"foreach: new Array(5)\">\n                        <div class=\"mini-table-row\" data-bind=\"foreach: new Array(5)\">\n                            <div class=\"mini-table-cell\" data-bind=\"style: { backgroundColor: $parentContext.$index() === 0 ? $parents[1].headerBg : ($parentContext.$index() % 2 === 0 ? $parents[1].altRowBg : $parents[1].rowBg), color: $parents[1].textColor }\"></div>\n\n                        </div>\n                    </div>\n                </div>\n                <!-- /ko -->\n            </div>\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: noHeaderRow\" />\n                    No Header Row\n                </label>\n            </div>\n            <div class=\"checkbox\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: noDashboardBorders\" />\n                    Borderless on Dashboard\n                </label>\n            </div>\n            <div class=\"checkbox\" data-bind=\"if: ReportType() == 'Single'\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: showPriorInKpi\" />\n                    Show previous comparision in KPI if applicable\n                </label>\n            </div>\n            <div data-bind=\"hidden: useStoredProc\" class=\"mt-2\">\n                <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: detectJoinsForReport\">\n                    <span class=\"fa fa-link\"></span> Configure Joins\n                </button>\n                <!-- ko if: customJoins().length > 0 -->\n                <span class=\"badge bg-success ms-1\"><span data-bind=\"text: customJoins().length\"></span> override(s)</span>\n                <button class=\"btn btn-sm btn-outline-danger ms-1\" data-bind=\"click: clearCustomJoins\" title=\"Remove all join overrides\">\n                    <span class=\"fa fa-times\"></span>\n                </button>\n                <!-- /ko -->\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"json-field-picker\">\n    <div data-bind=\"if: lastPickedField() && lastPickedField().fieldType == 'Json'\">\n        <br />\n        <div class=\"card\">\n            <div class=\"card-header\">\n                <h6>Select Data Fields from <span data-bind=\"text: lastPickedField().fieldName\"></span></h6>\n            </div>\n            <div class=\"card-body\">\n                <div class=\"row container-fluid\" data-bind=\"foreach: jsonFields\">\n                    <div class=\"col-md-3 col-sm-4 col-xs-6 list-group\">\n                        <div class=\"list-group-item\">\n                            <div class=\"checkbox\">\n                                <label>\n                                    <input type=\"checkbox\" data-bind=\"checkedInArray: {array: $parent.SelectedFields, value: $data}\">\n                                    <span data-bind=\"text: jsonColumnName\"></span>\n                                </label>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"custom-function-designer\">\n\n    <div class=\"row\">\n        <div class=\"col-md-12\" data-bind=\"visible: isFunctionField()\">\n            <div class=\"alert alert-info\">\n                You are now creating a Customized Field using Functions available.\n            </div>\n        </div>\n    </div>\n\n    <div class=\"form-group row\">\n        <label class=\"col-sm-2 control-label\">Field Label</label>\n        <div class=\"col-sm-10\">\n            <input type=\"text\" class=\"form-control form-control-sm\" data-bind=\"value: formulaFieldLabel\" required placeholder=\"Custom Field Label\" />\n        </div>\n    </div>\n    <div class=\"form-group row\">\n        <label class=\"col-sm-2 control-label\">Data Format</label>\n        <div class=\"col-sm-10\">\n            <select class=\"form-select form-control-sm\" data-bind=\"value: formulaDataFormat\" required>\n                <option>String</option>\n                <option>Integer</option>\n                <option>Decimal</option>\n                <option>Currency</option>\n                <option>Date</option>\n                <option value=\"DateTime\">Date and Time</option>\n            </select>\n        </div>\n    </div>\n    <div class=\"form-group row\" data-bind=\"visible: formulaDataFormat() == 'Decimal' || formulaDataFormat() == 'Currency'\">\n        <label class=\"col-sm-2 control-label\">Round to Decimal Places</label>\n        <div class=\"col-sm-10\">\n            <input type=\"number\" class=\"form-control\" data-bind=\"value: formulaDecimalPlaces\" placeholder=\"Choose Decimal places (leave blank to not use rounding)\" title=\"Choose Decimal places (leave blank to not use rounding)\" />\n        </div>\n    </div>\n\n    <div>\n        Define your Function:\n        <textarea id=\"function-code\"></textarea>\n    </div>\n    <div class=\"form-group row\" >\n        <div class=\"col-md-12 float-end\">\n            <hr />\n            <a href=\"#\" class=\"btn btn-primary btn-sm\" title=\"Save Custom Function Field\" data-bind=\"click: saveFunctionField, visible: isFunctionField\">Save</a>\n            <a href=\"#\" class=\"btn btn-sm\" title=\"Custom Field using Function\" data-bind=\"click: function(){isFunctionField(!isFunctionField())}, text: isFunctionField() ? 'Cancel': 'Function', css: {'btn-primary': !isFunctionField(), 'btn-danger': isFunctionField}\"></a>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"custom-field-designer\">\n    <div>\n        <div class=\"row\">\n            <div class=\"col-md-12\" data-bind=\"visible: isFormulaField()\">\n                <div class=\"alert alert-info\">\n                    You are now creating a Customized Field. Please select the fields you want to use in the calculation, then choose the operations you want to perform, and click \"Save\" to add your Custom field.\n                </div>\n            </div>\n        </div>\n        <div class=\"row\">\n            <div class=\"col-sm-6 small\">\n                Setup your Formula for calculating this Field\n            </div>\n            <div class=\"col-sm-6 right-align\" data-bind=\"visible: formulaType()=='build'\">\n                <a href=\"#\" class=\"btn btn-secondary btn-sm\" data-bind=\"click: addFormulaParentheses\">Add ( )</a>\n                <a href=\"#\" class=\"btn btn-secondary btn-sm\" title=\"Add Today\" data-bind=\"visible: formulaOnlyHasDateFields() || formulaFields().length == 0, click: addFormulaDateToday\">Add Today</a>\n                <a href=\"#\" class=\"btn btn-secondary btn-sm\" title=\"Add a Constant Value\" data-bind=\"click: addFormulaConstantValue\">Add Value</a>\n                <a href=\"#\" class=\"btn btn-secondary btn-sm\" data-bind=\"click: clearFormulaField\">Clear</a>\n            </div>\n        </div>\n        <div class=\"form-group-row\" data-bind=\"if: formulaOnlyHasDateFields\">\n            <div class=\"col-sm-12\">\n                <div class=\"alert alert-info\">\n                    For Dates Field calculation, you can only substract date fields and display the result as days, hours, minutes or seconds.\n                </div>\n            </div>\n        </div>\n        <div class=\"form-group row\">\n            <label class=\"col-sm-2 control-label\">Field Label</label>\n            <div class=\"col-sm-10\">\n                <input type=\"text\" class=\"form-control form-control-sm\" data-bind=\"value: formulaFieldLabel\" required placeholder=\"Custom Field Label\" />\n            </div>\n        </div>\n        <div class=\"form-group row\">\n            <label class=\"col-sm-2 control-label\">Data Format</label>\n            <div class=\"col-sm-10\">\n                <select class=\"form-select form-select-sm\" data-bind=\"value: formulaDataFormat\" required>\n                    <!-- ko ifnot: formulaOnlyHasDateFields -->\n                    <option>String</option>\n                    <option>Integer</option>\n                    <option>Decimal</option>\n                    <option>Currency</option>\n                    <!-- /ko -->\n                    <!-- ko if: formulaOnlyHasDateFields -->\n                    <option>Days</option>\n                    <option>Hours</option>\n                    <option>Minutes</option>\n                    <option>Seconds</option>\n                    <!-- /ko -->\n                </select>\n            </div>\n        </div>\n        <div class=\"form-group row\" data-bind=\"visible: formulaDataFormat() == 'Decimal' || formulaDataFormat() == 'Currency'\">\n            <label class=\"col-sm-2 control-label\">Round to Decimal Places</label>\n            <div class=\"col-sm-10\">\n                <input type=\"number\" class=\"form-control\" data-bind=\"value: formulaDecimalPlaces\" placeholder=\"Choose Decimal places (leave blank to not use rounding)\" title=\"Choose Decimal places (leave blank to not use rounding)\" />\n            </div>\n        </div>\n        <div class=\"form-group row\" data-bind=\"visible: appSettings.useSqlCustomField\">\n            <label class=\"col-sm-2 control-label\">Field Builder Type</label>\n            <div class=\"col-sm-10\">\n                <select class=\"form-select form-select-sm\" data-bind=\"value: formulaType\" required>\n                    <option value=\"build\">Simple Calculation</option>\n                    <option value=\"sql\">Advanced Expression</option>\n                </select>\n            </div>\n        </div>\n\n        <div class=\"form-group row\" data-bind=\"if: formulaType()=='build'\">\n            <label class=\"col-sm-2 control-label\">Field Formula</label>\n            <div class=\"col-sm-10\">\n                <div class=\"text-muted small\" data-bind=\"visible: formulaFields().length == 0\">Pick fields to build calculation</div>\n                <div class=\"d-flex align-items-center flex-wrap\" data-bind=\"foreach: formulaFields\">\n                    <h3 class=\"me-3\" data-bind=\"visible: setupFormula.isParenthesesStart\" style=\"margin-top: 0;\">(</h3>\n                    <div data-bind=\"if: !setupFormula.isParenthesesStart() && !setupFormula.isParenthesesEnd()\" class=\"list-group me-3\">\n                        <div class=\"list-group-item d-flex align-items-center formula-field-item\" style=\"margin-left: 15px; padding: 5px 15px\">\n                            <span data-bind=\"text: fieldName, visible: !setupFormula.isConstantValue()\"></span>\n                            <div data-bind=\"if: setupFormula.isConstantValue\" class=\"d-flex align-items-center\">\n                                <input data-bind=\"value: setupFormula.constantValue, visible: setupFormula.constantValue()!='|Today|'\" class=\"form-control form-control-sm me-2\" required />\n                                <span data-bind=\"visible: setupFormula.constantValue() == '|Today|'\"><b>Today</b></span>\n                            </div>\n                            <button class=\"btn btn-danger btn-sm ms-2\" data-bind=\"click: $parent.removeField\">\n                                <i class=\"fa fa-trash\"></i>\n                            </button>\n                        </div>\n                    </div>\n                    <h3 class=\"me-3\" data-bind=\"visible: setupFormula.isParenthesesEnd\" style=\"margin-top: 0;\">)</h3>\n                    <div class=\"me-3\" style=\"margin-left: 15px;\" data-bind=\"visible: $parent.showFormulaOperation($index())\">\n                        <select class=\"form-control form-control-sm\" style=\"max-width: 50px;\" data-bind=\"value: setupFormula.formulaOperation\">\n                            <!-- ko if: !$parent.formulaOnlyHasDateFields() || ($parent.formulaOnlyHasDateFields() && $parent.isConstantOperation($index())) -->\n                            <option>+</option>\n                            <!-- /ko -->\n                            <option>-</option>\n                            <!-- ko if: ['Integer','Money','Float','Double','Decimal','Currency'].indexOf($parent.formulaDataFormat()) != -1 -->\n                            <option>*</option>\n                            <option>/</option>\n                            <!-- /ko -->\n                        </select>\n                    </div>\n                </div>\n\n            </div>\n        </div>\n\n        <div data-bind=\"with: customSqlField, visible: formulaType()=='sql'\">\n            <div class=\"row\">\n                <div class=\"col-md-12\">\n\n                    <div class=\"mb-3\">\n                        <label class=\"form-label\">Select Data Operation:</label>\n                        <select class=\"form-select\" data-bind=\"select2: {\n                            dropdownParent: $root.activeDesign() ? $('#choose-data-design') : $('#choose-data-card'),\n                            placeholder: 'Select Function...',\n                            data: availableFunctionsGrouped(),\n                            templateResult: templateResult\n                        }, value: selectedSqlFunction\"></select>\n                    </div>\n\n                    <div class=\"mb-3\" data-bind=\"hidden: isConditionalFunction() || selectedSqlFunction() == 'Other'\">\n                        <label class=\"form-label\">Select the Data Field to use:</label>\n                        <select class=\"form-select\"\n                                data-bind=\"select2: {\n                                    dropdownParent: $root.activeDesign() ? $('#choose-data-design') : $('#choose-data-card'),\n                                    placeholder: 'Search Field...',\n                                    ajax: {\n                                        url: $parent.textQuery.searchFields.url,\n                                        dataType: 'json',\n                                        data: $parent.textQuery.searchFields.query,\n                                        processResults: $parent.textQuery.searchFields.processResults,\n                                        headers: $parent.textQuery.searchFields.headers\n                                    },\n                                    minimumInputLength: 2,\n                                    allowClear: true\n                                }, select2Text: selectedField,select2TableId:selectedFieldTableId\"></select>\n                        <div data-bind=\"with: selectedField\" class=\"small\">\n                                Selected: <span class=\"highlight\" data-bind=\"text: $data\"></span>\n                        </div>\n                    </div>\n\n                    <div class=\"mb-3\" data-bind=\"if: requiresValue\">\n                        <label for=\"inputValue\" class=\"form-label\">Provide the relevant value to use:</label>\n                        <input type=\"text\" id=\"inputValue\" class=\"form-control\" data-bind=\"value: inputValue\" required />\n                    </div>\n\n                    <div class=\"mb-3\" data-bind=\"visible: selectedSqlFunction() == 'Other'\">\n                        <label for=\"custom-sql\" class=\"form-label\">Custom SQL Expression:</label>\n                        <p class=\"text-muted\">\n                            Build your custom SQL Expression below by selecting data fields, adding calculations or using SQL keywords as needed. For string values, remember to enclose them in single quotes ('')\n                        </p>\n                        <p id=\"custom-sql\" class=\"hint-input\" contenteditable=\"true\" placeholder=\"Write your custom SQL\"></p>\n                    </div>\n                    <div data-bind=\"visible: isConditionalFunction\">\n                        <p class=\"text-muted\">\n                            Build your conditional logic below by selecting data fields, adding calculations and defining conditions as needed, and provide corresponding results. For string values, remember to enclose them in single quotes ('')\n                        </p>\n                        <div class=\"input-group mb-3\">\n                            <div class=\"flex-grow-1\">\n                                <p class=\"hint-input\" id=\"condition-field\" contenteditable=\"true\" placeholder=\"Field to compare\" title=\"Field to compare\"></p>\n                            </div>\n\n                            <div class=\"mx-2\" style=\"width: 120px;\">\n                                <select class=\"form-select form-select-sm\" data-bind=\"options: availableOperators, value: selectedOperator\"></select>\n                            </div>\n\n                            <div class=\"flex-grow-1\">\n                                <p class=\"hint-input\" id=\"condition-value\" contenteditable=\"true\" placeholder=\"Value to compare\" title=\"Value to compare\"></p>\n                            </div>\n\n                            <span class=\"input-group-text\" style=\"max-height: 32px;\">THEN</span>\n\n                            <div class=\"flex-grow-1\">\n                                <p class=\"hint-input\" id=\"condition-result\" contenteditable=\"true\" placeholder=\"Condition Result\" title=\"Condition Result\"></p>\n                            </div>\n                        </div>\n                        <button class=\"btn btn-outline-primary\" data-bind=\"click: addOrUpdateCondition,text: editingCondition() ? 'Update Condition' : 'Add Condition'\"></button>\n                        <ul class=\"list-group mt-3\" data-bind=\"foreach: conditions\">\n                            <li class=\"list-group-item d-flex justify-content-between align-items-center\">\n                                <span data-bind=\"text: conditionDisplay\"></span>\n                                <button class=\"btn btn-sm btn-secondary me-1\" data-bind=\"click: $parent.editCondition\">Edit</button>\n                                <button class=\"btn btn-sm btn-danger\" data-bind=\"click: $parent.removeCondition\">Remove</button>\n                            </li>\n                        </ul>\n\n                        <div class=\"input-group mb-3\" style=\"padding-top: 5px;\">\n                            <span class=\"input-group-text\" style=\"max-height: 32px;\">ELSE</span>\n                            <div class=\"flex-grow-1\">\n                                <p class=\"hint-input\" id=\"condition-else\" contenteditable=\"true\" placeholder=\"Default Result\" title=\"Default Result\"></p>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n        </div>\n\n        <div class=\"col-md-12\">\n            <hr />\n            <a href=\"#\" class=\"btn btn-primary btn-sm\" title=\"Save Custom Formula Field\" data-bind=\"click: saveFormulaField, visible: isFormulaField\">Save</a>\n            <a href=\"#\" class=\"btn btn-sm\" title=\"Custom Field using Formula\" data-bind=\"click: cancelFormulaField, text: isFormulaField()? 'Cancel': 'Customize', css: {'btn-primary': !isFormulaField(), 'btn-danger': isFormulaField}\"></a>\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"report-designer-compact\">\n    <div class=\"designer-container compact-designer\" id=\"choose-data-design\" style=\"font-size:12px;\">\n\n      <div class=\"alert alert-info mb-2 py-2 px-3\" style=\"border-left: 4px solid #0d6efd; font-size: 13px;\" data-bind=\"visible: editingSubReportParentId()\">\n          <!-- ko if: _editingSubReportLoading() -->\n          <div class=\"d-flex align-items-center\">\n              <span class=\"fa fa-spinner fa-spin me-2\"></span>\n              <span>Loading sub report...</span>\n          </div>\n          <!-- /ko -->\n          <!-- ko ifnot: _editingSubReportLoading() -->\n          <div class=\"d-flex align-items-center justify-content-between\">\n              <span>\n                  <i class=\"fa fa-info-circle me-1\"></i>\n                  Editing sub report from <strong data-bind=\"text: editingSubReportParentName\"></strong>.\n              </span>\n              <button type=\"button\" class=\"btn btn-sm btn-outline-primary ms-2\" data-bind=\"click: returnToParentReport\">\n                  <i class=\"fa fa-arrow-left me-1\"></i> Back to parent\n              </button>\n          </div>\n          <!-- /ko -->\n      </div>\n\n      <!-- Visualization Toolbar -->\n      <div class=\"card p-1 mb-2\">\n         <div class=\"card-header p-1 d-flex justify-content-between align-items-center\">\n          <span><i class=\"fa fa-file\"></i> Visualization</span>\n          <button id=\"aiToggleBtn\"\n                class=\"btn btn-primary position-fixed bottom-0 end-0 m-3 rounded-circle shadow\"\n                style=\"width: 50px; height: 50px; z-index: 1050;\"\n                title=\"Chat with AI Assistant\"\n                data-bind=\"click: toggleAiChat, visible: appSettings.usePromptBuilder\">\n            <i class=\"fa fa-comment fa-lg\"></i>\n          </button>\n          <div>\n              <button type=\"button\" class=\"btn btn-sm btn-outline-secondary me-1\" data-bind=\"click: function() { RunReport(false, true, ReportMode()=='dashboard'); }\" title=\"Re-run Report\">\n                  <i class=\"fa fa-play\"></i>\n              </button>\n              <!-- Close for existing reports -->\n              <button type=\"button\" class=\"btn btn-sm btn-outline-secondary\" data-bind=\"visible: ReportID(), click: function() {activeDesign(false); if (isExpanded) isExpanded(false);}\" title=\"Close Designer\">\n                  <i class=\"fa fa-times\"></i>\n              </button>\n              <!-- Cancel for new reports -->\n              <button type=\"button\" class=\"btn btn-sm btn-danger\" data-bind=\"visible: !ReportID(), click: function() { if (ReportMode()=='dashboard') $parent.removeNewReport(); else cancelCreateReport(); }\" title=\"Cancel new report\">\n                  <i class=\"fa fa-times\"></i>\n              </button>\n          </div>\n        </div>\n        <div class=\"card-body p-1\" style=\"overflow-x: auto;\">\n          <div data-bind=\"template: 'designer-choose-visual'\"></div>\n        </div>\n      </div>\n\n      <!-- Main Grid -->\n      <div class=\"d-flex flex-row flex-wrap gap-2 compact-filters needs-validation\">\n\n        <!-- Data -->\n        <div class=\"card flex-fill expandable-panel\" id=\"dataPanel\" style=\"max-width: 300px\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('dataPanel')}\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('dataPanel')}\">\n            <i class=\"fa fa-database\"></i> Available Data\n          </div>\n\n          <div class=\"card-body p-1\">\n              <div data-bind=\"template: 'designer-choose-data'\"></div>\n          </div>\n        </div>\n\n        <!-- Selected -->\n        <div class=\"card flex-fill expandable-panel\" id=\"selectedPanel\" style=\"max-width: 400px\"\n         data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('selectedPanel')}\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('selectedPanel')}\">\n            <i class=\"fa fa-table\"></i> Selected data for the Report\n            <a href=\"#\" class=\"small text-muted float-end\"\n               data-bind=\"visible: SelectedFields().length, click:function(){SelectedFields([]);}\">Clear all</a>\n          </div>\n\n          <div class=\"card-body designer-auto-update p-1\">\n                <div style=\"max-height: 300px; overflow-y: auto;\">\n                    <div data-bind=\"template: 'designer-selected-data'\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"card flex-fill expandable-panel\" id=\"subReportsPanel\"\n                data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('subReportsPanel')}, visible: linkedReportFields().length > 0\">\n            <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('subReportsPanel')}\">\n            <i class=\"fa fa-bookmark\"></i> Sub Reports\n            </div>\n            <div class=\"card-body p-1\">\n            <div data-bind=\"template: 'designer-sub-report', data: $data\"></div>\n            </div>\n        </div>\n\n        <div class=\"card flex-fill expandable-panel\" id=\"htmlReportPanel\"\n                data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('htmlReportPanel')}, visible: ReportType()=='Html'\">\n            <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('htmlReportPanel')}\">\n            <i class=\"fa fa-pencil\"></i> Custom Design\n            </div>\n            <div class=\"card-body p-1\">\n            <div data-bind=\"template: 'designer-html', data: $data\"></div>\n            </div>\n        </div>\n\n        <div class=\"card flex-fill expandable-panel\" id=\"jsonFieldsPanel\" data-bind=\"visible: lastPickedField() && lastPickedField().fieldType == 'Json'\">\n            <div class=\"card-body\" data-bind=\"template: 'json-field-picker'\"></div>\n        </div>\n\n        <!-- Field Options Panel -->\n        <div id=\"fieldOptionsPanel\" class=\"card p-2 mt-2 collapse\">\n        <!-- dynamic field settings load here -->\n        </div>\n\n        <!-- Filters -->\n        <div class=\"card flex-fill expandable-panel\" id=\"filtersPanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('filtersPanel')}\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('filtersPanel')}\">\n            <i class=\"fa fa-filter\"></i> Filters\n          </div>\n          <div class=\"card-body p-1 designer-auto-update\" style=\"max-height:300px; overflow-y:auto;\">\n            <div data-bind=\"if:useStoredProc\"><div data-bind=\"template:{name:'filter-parameters'}\"></div></div>\n            <div data-bind=\"ifnot:useStoredProc\"><div data-bind=\"template:{name:'filter-group'}\"></div></div>\n          </div>\n        </div>\n\n        <!-- Sort -->\n        <div class=\"card flex-fill expandable-panel\" id=\"sortPanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('sortPanel')}, hidden: useStoredProc()\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('sortPanel')}\">\n            <i class=\"fa fa-sort\"></i> Sort\n          </div>\n          <div class=\"card-body p-1 designer-auto-update row\">\n            <div data-bind=\"template: 'designer-sort'\"></div>\n          </div>\n        </div>\n\n        <!-- Settings -->\n        <div class=\"card flex-fill expandable-panel\" id=\"settingsPanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('settingsPanel')}\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('settingsPanel')}\">\n            <i class=\"fa fa-gear\"></i>Options\n          </div>\n          <div class=\"card-body\">\n            <div class=\"form-group row\">\n                <label class=\"col-form-label h6\">\n                    <i class=\"fa fa-file\"></i> Report Name\n                </label>\n                <div>\n                    <input type=\"text\" class=\"form-control\" required placeholder=\"Report Name\" data-bind=\"value: ReportName\">\n                </div>\n            </div>\n            <div class=\"form-group row\">\n                <label class=\"control-label h6\">\n                    <i class=\"fa fa-info-circle\"></i> Report Description\n                </label>\n                <div>\n                    <textarea class=\"form-control\" style=\"width: 100%;\" rows=\"3\" placeholder=\"Additional details (optional)\" data-bind=\"value: ReportDescription\"></textarea>\n                </div>\n            </div>\n            <div class=\"checkbox\" data-bind=\"visible: canSaveCurrentReport()\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: SaveReport\">\n                    Save Report\n                </label>\n            </div>\n            <div class=\"checkbox\" data-bind=\"visible: adminMode() && ReportID()\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: isSubReportOnly, click: function() { setTimeout(function() { toggleIsSubReportOnly(); }, 0); return true; }\">\n                    Only use as sub report\n                </label>\n            </div>\n            <div class=\"checkbox\" data-bind=\"visible: adminMode()\">\n                <label>\n                    <input type=\"checkbox\" data-bind=\"checked: ShowAdminOnly\">\n                    Hide from reports unless Admin Mode is enabled\n                </label>\n            </div>\n            <div class=\"form-group row\" data-bind=\"visible: SaveReport\">\n                <label class=\"control-label h6\">\n                    <i class=\"fa fa-folder-open\"></i> Choose Folder\n                </label>\n                <div>\n                    <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: Folders, optionsText: function(f) { return f.FolderPath || f.FolderName; }, optionsValue: 'Id', value: FolderID, valueAllowUnset: true\"></select>\n                </div>\n            </div>\n            <hr />\n            <div data-bind=\"template: 'designer-options'\"></div>\n          </div>\n        </div>\n\n        <!-- Schedule -->\n        <div class=\"card flex-fill expandable-panel\" id=\"schedulePanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('schedulePanel')}, visible: SaveReport() && !ko.unwrap(appSettings.showScheduling) && !isSubReportOnly()\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('schedulePanel')}\">\n            <i class=\"fa fa-hourglass\"></i> Schedule\n          </div>\n          <div class=\"card-body p-1 designer-auto-update row\">\n            <div data-bind=\"template: {name: 'report-schedule'}\"></div>\n          </div>\n        </div>\n\n        <!-- Access -->\n        <div class=\"card flex-fill expandable-panel\" id=\"accessPanel\"\n             data-bind=\"css:{'collapsed-vertical': panels.isCollapsed('accessPanel')}, visible: adminMode() && !isFormulaField()\">\n          <div class=\"card-header p-1\" data-bind=\"click:function(){panels.togglePanel('accessPanel')}\">\n            <i class=\"fa fa-key\"></i>Security\n          </div>\n\n          <div data-bind=\"\" class=\"card card-body\">\n            <div data-bind=\"template: {name: 'manage-access-template', data: manageAccess}\"></div>\n        </div>\n        </div>\n\n      </div>\n\n    </div>\n    <hr />\n    <!-- AI Assistant Popup -->\n    <div id=\"aiPopup\"\n         class=\"position-fixed bottom-0 end-0 m-3 shadow-lg bg-white border rounded-3 d-none d-flex flex-column\"\n         style=\"width: 340px; height: 460px; z-index: 1060; overflow: hidden;\">\n\n        <div class=\"d-flex justify-content-between align-items-center border-bottom bg-light p-2 px-3 flex-shrink-0\">\n            <h6 class=\"mb-0\">\n                <i class=\"fa fa-comments me-1\"></i> AI Report Assistant\n                <span class=\"alert alert-info\" title=\"This feature is still in intial release and might not alwways be accurate. You can turn it off from settings\" style=\"font-size: 10pt; padding: 5px; max-width: 350px; white-space: normal; margin-bottom: 0;\">\n                    <i class=\"fa fa-info-circle\"></i>\n                </span>\n            </h6>\n            <div>\n                <button class=\"btn btn-sm btn-outline-secondary me-2\" data-bind=\"click: clearAiChat\" title=\"Clear Chat\">\n                    <i class=\"fa fa-trash\"></i>\n                </button>\n                <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: toggleAiChat\" title=\"Close\">\n                    <i class=\"fa fa-times\"></i>\n                </button>\n            </div>\n        </div>\n\n        <div id=\"aiChatBody\"\n             class=\"flex-grow-1 overflow-auto p-3\"\n             style=\"background: #f8f9fa;\">\n            <div data-bind=\"foreach: aiMessages\">\n            <div class=\"mb-2\" data-bind=\"css: { 'text-end': role === 'user', 'text-start': role === 'assistant' }\">\n                <div data-bind=\"text: content, css: role === 'user' ? 'bg-primary text-white' : 'bg-light border'\"\n                     class=\"p-2 rounded-3 d-inline-block\"\n                     style=\"max-width: 85%; white-space: pre-wrap;\"></div>\n            </div>\n            </div>\n        </div>\n\n        <div class=\"border-top bg-white p-2 flex-shrink-0\">\n            <div class=\"w-100 mb-1 small text-muted\">\n                💡 Ask things like “Add a column for total orders” or “Show top salesperson this year”\n            </div>\n            <div class=\"form-check mb-2\">\n                <input type=\"checkbox\" class=\"form-check-input\"\n                       data-bind=\"checked: aiAutocompleteDisabled\">\n                <label class=\"form-check-label small text-muted\">\n                    Disable column autocomplete hints\n                    <span title=\"If you disable this, plesae select some data fields in the report designer, choosing data fields to use helps improve results\" style=\"font-size: 10pt; padding: 5px; max-width: 350px; white-space: normal; margin-bottom: 0;\">\n                        <i class=\"fa fa-info-circle\"></i>\n                    </span>\n                </label>\n            </div>\n\n            <div class=\"d-flex align-items-center w-100\">\n                <p id=\"query-input\"\n                   class=\"query-input flex-grow-1 mb-0 p-2 border rounded\"\n                   contenteditable=\"true\"\n                   style=\"min-height: 38px; overflow-y: auto;\"></p>\n                <button class=\"btn btn-primary ms-2\"\n                        data-bind=\"click: sendAiMessage\">\n                    <i class=\"fa fa-paper-plane\"></i>\n                </button>\n            </div>\n        </div>\n    </div>\n\n</script>\n\n<script type=\"text/html\" id=\"report-designer\">\n    <div class=\"modal-dialog modal-dialog-scrollable\" style=\"height: 100vh;\" id=\"report-designer-modal\">\n        <div class=\"modal-content\" style=\"display: flex; flex-direction: column; height: 100%;\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"myModalLabel\">\n                    <a title=\"Need help setting up a report?\" target=\"_blank\" href=\"https://dotnetreport.com/blogs/docs/designing-reports\"><span class=\"fa fa-question-circle\"></span></a>\n                    <!-- ko if: editingSubReportParentId() -->\n                    <i class=\"fa fa-link\"></i> Editing Sub Report\n                    <!-- /ko -->\n                    <!-- ko ifnot: editingSubReportParentId() -->\n                    Design your Report\n                    <!-- /ko -->\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" data-bind=\"click: onModalCloseClicked\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"alert alert-info mb-0 rounded-0 py-2 px-3\" style=\"border-left: 4px solid #0d6efd;\" data-bind=\"visible: editingSubReportParentId()\">\n                <!-- ko if: _editingSubReportLoading() -->\n                <div class=\"d-flex align-items-center py-1\">\n                    <span class=\"fa fa-spinner fa-spin me-2\"></span>\n                    <span>Loading sub report...</span>\n                </div>\n                <!-- /ko -->\n                <!-- ko ifnot: _editingSubReportLoading() -->\n                <div class=\"d-flex align-items-center justify-content-between\">\n                    <span>\n                        <i class=\"fa fa-info-circle me-1\"></i>\n                        You are editing a sub report linked from <strong data-bind=\"text: editingSubReportParentName\"></strong>.\n                    </span>\n                    <button type=\"button\" class=\"btn btn-sm btn-outline-primary ms-2\" data-bind=\"click: returnToParentReport\">\n                        <i class=\"fa fa-arrow-left me-1\"></i> Back to parent report\n                    </button>\n                </div>\n                <small class=\"text-muted\">When you save, you'll be returned to the parent report. You can also click \"Back to parent report\" to return without saving.</small>\n                <!-- /ko -->\n            </div>\n            <div class=\"modal-body needs-validation\" style=\"overflow-y: hidden; flex-grow: 1; display: flex; flex-direction: column;\">\n               <div class=\"row flex-grow-1\" style=\"min-height: 0;\">\n                    <!-- LEFT PANEL -->\n                    <div class=\"col-md-4 h-100\" style=\"overflow-y: auto;\">\n\n                        <!-- Designer Toolbar Toggles -->\n                        <div class=\"d-flex align-items-center flex-wrap gap-2 mb-2\">\n                            <div class=\"form-check form-switch mb-0\">\n                                <input class=\"form-check-input\" type=\"checkbox\" role=\"switch\" id=\"livePreviewSwitch\" data-bind=\"checked: activeDesign\">\n                                <label class=\"form-check-label fw-semibold\" for=\"livePreviewSwitch\">\n                                    <i class=\"fa fa-bolt text-warning\"></i> Live Preview\n                                </label>\n                            </div>\n                            <div class=\"form-check form-switch mb-0\" data-bind=\"visible: hasAiConfigured()\">\n                                <input class=\"form-check-input\" type=\"checkbox\" role=\"switch\" id=\"aiAssistSwitch\" data-bind=\"checked: aiAssistantEnabled\">\n                                <label class=\"form-check-label small\" for=\"aiAssistSwitch\">\n                                    <i class=\"fa fa-magic text-primary\"></i> AI Assist <span style=\"vertical-align: middle;\" title=\"This feature is still in intial release and might not alwways be accurate. You can turn it off from settings\" ><i class=\"fa fa-info-circle\"></i></span>\n                                </label>\n                            </div>                            \n                            <div class=\"form-check form-switch mb-0\" data-bind=\"visible: ko.unwrap(appSettings.showDesignerHints)\">\n                                <input class=\"form-check-input\" type=\"checkbox\" role=\"switch\" id=\"hintsSwitch\" data-bind=\"checked: showHints\">\n                                <label class=\"form-check-label small\" for=\"hintsSwitch\">\n                                    <i class=\"fa fa-question-circle text-info\"></i> Tips\n                                </label>\n                            </div>\n                            <button class=\"btn btn-sm btn-outline-primary ms-auto\" data-bind=\"visible: activeDesign(), click: function() { RunReport(false, true); }\" title=\"Re-run Report\">\n                                <i class=\"fa fa-play\"></i> Run\n                            </button>\n                        </div>\n\n                        <!-- AI Assistant Panel (visible in both modes) -->\n                        <div class=\"card mb-2 designer-panel ai-assistant-panel\" data-bind=\"visible: aiAssistantEnabled()\" style=\"display:none; font-size: 12px;\">\n                            <div class=\"card-header p-2 d-flex align-items-center bg-primary text-white\" style=\"cursor:pointer;\">\n                                <i class=\"fa fa-magic me-1\"></i> AI Report Builder\n                                <span class=\"badge bg-light text-primary ms-1\" data-bind=\"visible: aiReportApplied()\" style=\"font-size:9px;\">Modified</span>\n                                <button class=\"btn btn-sm btn-link text-white ms-auto p-0\" data-bind=\"click: clearAiAssistant\" title=\"Clear conversation\"><i class=\"fa fa-trash\"></i></button>\n                            </div>\n                            <div class=\"card-body p-0\">\n                                <!-- Messages -->\n                                <div class=\"ai-assist-messages\" data-bind=\"foreach: aiAssistantMessages\" style=\"max-height: 350px; overflow-y: auto; padding: 8px;\">\n                                    <div class=\"mb-2\" data-bind=\"css: { 'text-end': role === 'user', 'text-start': role !== 'user' }\">\n                                        <div class=\"ai-msg-bubble d-inline-block p-2 rounded-3\" style=\"max-width: 90%; white-space: pre-wrap; font-size: 12px;\"\n                                             data-bind=\"text: content, css: role === 'user' ? 'bg-primary text-white' : 'bg-light border'\"></div>\n                                    </div>\n                                </div>\n                                <!-- Loading -->\n                                <div class=\"text-center p-2\" data-bind=\"visible: aiAssistantLoading()\">\n                                    <div class=\"d-flex align-items-center justify-content-center gap-2\">\n                                        <i class=\"fa fa-spinner fa-spin text-primary\"></i>\n                                        <span class=\"small text-muted\">Building your report...</span>\n                                    </div>\n                                </div>\n                                <!-- Quick Actions (shown when no messages) -->\n                                <div class=\"p-2\" data-bind=\"visible: aiAssistantMessages().length === 0 && !aiAssistantLoading()\">\n                                    <div class=\"small text-muted mb-1\" style=\"font-style: italic;\">\n                                        Ask me anything about your report design, or click a quick action below.\n                                    </div>\n                                    <div class=\"small text-muted mb-2\">\n                                        <i class=\"fa fa-magic text-primary\"></i> Tell me what report to build, or try:\n                                    </div>\n                                    <div class=\"small text-muted mb-2\" style=\"background: #f0f7ff; padding: 6px 8px; border-radius: 4px; border-left: 3px solid #0d6efd;\">\n                                        <i class=\"fas fa-lightbulb text-warning\"></i> <strong>Tip:</strong> For best results, mention the data table name (e.g., \"build a report using the Orders table\")\n                                    </div>\n                                    <div class=\"d-flex flex-wrap gap-1\">\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function(){ aiAssistantInput('Build a sales summary report with a bar chart'); sendAiAssistantMessage(); }\">\n                                            <i class=\"fa fa-bar-chart\"></i> Sales summary\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function(){ aiAssistantInput('Create an invoice report using HTML template'); sendAiAssistantMessage(); }\">\n                                            <i class=\"fa fa-file-text-o\"></i> Invoice report\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function(){ aiAssistantInput('Show me a trend line chart of data over time'); sendAiAssistantMessage(); }\">\n                                            <i class=\"fa fa-line-chart\"></i> Trend analysis\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: function(){ aiAssistantInput('Create a KPI dashboard widget showing a key metric'); sendAiAssistantMessage(); }\">\n                                            <i class=\"fa fa-tachometer\"></i> KPI widget\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-secondary\" data-bind=\"click: getAiRecommendation, visible: SelectedFields().length > 0\">\n                                            <i class=\"fas fa-lightbulb\"></i> Recommend chart\n                                        </button>\n                                    </div>\n                                </div>\n                                <!-- Chat Input -->\n                                <div class=\"d-flex align-items-center p-2 border-top\">\n                                    <input type=\"text\" class=\"form-control form-control-sm me-1\"\n                                           placeholder=\"Describe the report you want to build...\"\n                                           data-bind=\"value: aiAssistantInput, valueUpdate: 'afterkeydown',\n                                                      event: { keypress: function(d,e){ if(e.keyCode===13){ sendAiAssistantMessage(); return false; } return true; } },\n                                                      attr: { disabled: aiAssistantLoading() }\">\n                                    <button class=\"btn btn-sm btn-primary\" data-bind=\"click: sendAiAssistantMessage, enable: aiAssistantInput() && !aiAssistantLoading()\">\n                                        <i class=\"fa fa-paper-plane\"></i>\n                                    </button>\n                                </div>\n                                <!-- Follow-up suggestions (shown after AI applies a report) -->\n                                <div class=\"p-2 border-top\" data-bind=\"visible: aiReportApplied() && !aiAssistantLoading() && aiAssistantMessages().length > 0\" style=\"display:none;\">\n                                    <div class=\"small text-muted mb-1\"><i class=\"fa fa-comments\"></i> Follow-up:</div>\n                                    <div class=\"d-flex flex-wrap gap-1\">\n                                        <button class=\"btn btn-sm btn-outline-primary\" data-bind=\"click: function(){ aiAssistantInput('Add a filter for this year'); sendAiAssistantMessage(); }\">\n                                            + Filter this year\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-primary\" data-bind=\"click: function(){ aiAssistantInput('Change to a bar chart'); sendAiAssistantMessage(); }\">\n                                            Change chart type\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-primary\" data-bind=\"click: function(){ aiAssistantInput('Break it down by month'); sendAiAssistantMessage(); }\">\n                                            By month\n                                        </button>\n                                        <button class=\"btn btn-sm btn-outline-primary\" data-bind=\"click: function(){ aiAssistantInput('Add a top 10 limit'); sendAiAssistantMessage(); }\">\n                                            Top 10\n                                        </button>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- ==================== STANDARD MODE (activeDesign OFF) ==================== -->\n                        <div data-bind=\"visible: !activeDesign()\">\n                            <div class=\"card card-body\" id=\"choose-data-card\" style=\"min-height: calc(100vh - 200px);\">\n                                <div class=\"form-group row align-items-center\">\n                                    <label class=\"col-sm-4 col-form-label h6\">\n                                        <i class=\"fa fa-file\"></i> Report Name\n                                    </label>\n                                    <div class=\"col-sm-8\">\n                                        <input type=\"text\" class=\"form-control\" required placeholder=\"Report Name\" data-bind=\"value: ReportName\">\n                                    </div>\n                                </div>\n                                <hr />\n                                <h5><span class=\"fa fa-database\"></span>&nbsp;Choose Data for Report</h5>\n                                <div data-bind=\"template: 'designer-choose-data'\"></div>\n                            </div>\n                            <br />\n                            <div class=\"card card-body\">\n                                <div class=\"form-group row\">\n                                    <label class=\"control-label h6\">\n                                        <i class=\"fa fa-info-circle\"></i> Report Description\n                                    </label>\n                                    <div>\n                                        <textarea class=\"form-control\" style=\"width: 100%;\" rows=\"3\" placeholder=\"Additional details (optional)\" data-bind=\"value: ReportDescription\"></textarea>\n                                    </div>\n                                </div>\n                                <div class=\"checkbox\" data-bind=\"visible: canSaveCurrentReport()\">\n                                    <label>\n                                        <input type=\"checkbox\" data-bind=\"checked: SaveReport\">\n                                        Save Report\n                                    </label>\n                                </div>\n                                <div class=\"checkbox\" data-bind=\"visible: adminMode() && ReportID()\">\n                                    <label>\n                                        <input type=\"checkbox\" data-bind=\"checked: isSubReportOnly, click: function() { setTimeout(function() { toggleIsSubReportOnly(); }, 0); return true; }\">\n                                        Only use as sub report\n                                    </label>\n                                </div>\n                                <div class=\"checkbox\" data-bind=\"visible: adminMode()\">\n                                    <label>\n                                        <input type=\"checkbox\" data-bind=\"checked: ShowAdminOnly\">\n                                        Hide from reports unless Admin Mode is enabled\n                                    </label>\n                                </div>\n                                <div class=\"form-group row\" data-bind=\"visible: SaveReport\">\n                                    <label class=\"control-label h6\">\n                                        <i class=\"fa fa-folder-open\"></i> Choose Folder\n                                    </label>\n                                    <div>\n                                        <select class=\"form-select\" style=\"width: 100%;\" data-bind=\"options: Folders, optionsText: function(f) { return f.FolderPath || f.FolderName; }, optionsValue: 'Id', value: FolderID, valueAllowUnset: true\"></select>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- ==================== LIVE PREVIEW MODE (activeDesign ON) ==================== -->\n                        <div data-bind=\"visible: activeDesign()\" class=\"live-preview-designer\" style=\"font-size: 12px; display: none;\">\n\n                            <!-- Report Name (always visible at top in live preview) -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-body p-2\">\n                                    <div class=\"form-group row align-items-center mb-0\">\n                                        <label class=\"col-sm-4 col-form-label\"><i class=\"fa fa-file\"></i> Report Name</label>\n                                        <div class=\"col-sm-8\">\n                                            <input type=\"text\" class=\"form-control form-control-sm\" required placeholder=\"Report Name\" data-bind=\"value: ReportName\">\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <!-- Data -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-dataPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-database\"></i> Available Data\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>1. Pick a Table</b> from the dropdown &mdash; this is your data source.<br><b>2. Check fields</b> to add them to your report.<br><b>3. Join Tables:</b> If you need data from multiple tables, select additional tables and they&rsquo;ll be auto-joined if relationships exist.<br><b>Dynamic vs Stored Proc:</b> Dynamic builds SQL from your selections; Stored Proc calls a predefined database procedure.\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-dataPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-dataPanel')\">\n                                    <div data-bind=\"template: 'designer-choose-data'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Visualization -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-vizPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-bar-chart\"></i> Visualization\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>List:</b> Raw data rows &mdash; detail reports, exports.<br><b>Summary:</b> Grouped with totals (needs aggregate functions like Sum/Count).<br><b>Bar:</b> Compare categories side by side. Use <i>Stacked</i> or <i>Horizontal</i> in chart options.<br><b>Pie:</b> Proportions of a whole (best with &lt;8 slices). Enable <i>Donut</i> in options.<br><b>Line:</b> Trends over time. Great with date fields on x-axis.<br><b>KPI:</b> Single big number metric (needs one numeric field with aggregate).<br><b>More...</b> opens Scatter, Gauge, Funnel, Radar, and more.\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-vizPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-vizPanel')\" style=\"overflow-x: auto;\">\n                                    <div data-bind=\"template: 'designer-choose-visual'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Selected Data -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-selectedPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-table\"></i> Selected Data\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>Aggregate Functions</b> (for Summary/Charts):<br>&bull; <b>Group:</b> Group rows by this field (e.g., by Month, by Category)<br>&bull; <b>Sum:</b> Add up all values<br>&bull; <b>Count:</b> Count number of rows<br>&bull; <b>Avg:</b> Calculate average<br>&bull; <b>Min/Max:</b> Find smallest/largest value<br><br><b>Group in Graph:</b> Creates separate series/colors in charts (e.g., one line per product).<br><b>Field Settings</b> (click column &crarr; icon): Format as Currency/Percentage, set alignment, decimal places, conditional formatting, custom labels, and more.\"></i>\n                                    <a href=\"#\" class=\"small text-muted float-end me-3\" data-bind=\"visible: SelectedFields().length, click: function(){SelectedFields([]);}\">Clear all</a>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-selectedPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-auto-update\" data-bind=\"visible: !panels.isCollapsed('lp-selectedPanel')\" style=\"max-height: 300px; overflow-y: auto;\">\n                                    <div data-bind=\"template: 'designer-selected-data'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- JSON Field Picker -->\n                            <div data-bind=\"template: 'json-field-picker'\"></div>\n\n                            <!-- Sub Reports -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: linkedReportFields().length > 0\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-subReportsPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-bookmark\"></i> Sub Reports\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-subReportsPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-subReportsPanel')\">\n                                    <div data-bind=\"template: 'designer-sub-report'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- HTML Design -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: ReportType()=='Html'\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-htmlPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-pencil\"></i> Custom Design\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-htmlPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-htmlPanel')\">\n                                    <div data-bind=\"template: 'designer-html'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Filters -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-filtersPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-filter\"></i> Filters\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>Filter Operators:</b><br>&bull; <b>=, &gt;, &lt;, &ge;, &le;:</b> Standard comparisons<br>&bull; <b>Between:</b> Range (e.g., dates from/to)<br>&bull; <b>Like:</b> Pattern match (use % as wildcard)<br>&bull; <b>In / Not In:</b> Match a list of values<br>&bull; <b>Is Blank / Is Not Blank:</b> Null checks<br><br><b>Date Shortcuts:</b> Today, This Week, This Month, This Year, Last 30 Days, Last Year<br><br><b>AND/OR Logic:</b> Combine multiple filters. Add filter groups for complex logic like (A AND B) OR (C AND D).<br><br><b>Allow Filters on Report:</b> Check this to let viewers add their own filters when viewing.\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-filtersPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-auto-update\" data-bind=\"visible: !panels.isCollapsed('lp-filtersPanel')\" style=\"max-height: 300px; overflow-y: auto;\">\n                                    <div data-bind=\"visible: useStoredProc\"><div data-bind=\"template: {name: 'filter-parameters'}\"></div></div>\n                                    <div data-bind=\"visible: !useStoredProc()\"><div data-bind=\"template: {name: 'filter-group'}\"></div></div>\n                                    <div class=\"checkbox\">\n                                        <label>\n                                            <input type=\"checkbox\" data-bind=\"checked: EditFiltersOnReport\" />\n                                            Allow setting up and saving filters on Report\n                                        </label>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <!-- Sort -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: !useStoredProc()\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-sortPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-sort\"></i> Sort\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>Sort Order:</b> Drag fields to set priority. First sort is primary, second is tie-breaker, etc.<br><b>Ascending:</b> A&rarr;Z, 1&rarr;9, oldest&rarr;newest<br><b>Descending:</b> Z&rarr;A, 9&rarr;1, newest&rarr;oldest<br><br><b>For Charts:</b> Sort controls x-axis order (e.g., sort by date for chronological, by value for ranked bars).<br><b>Top N:</b> Combine sort descending + page size to show &ldquo;Top 10&rdquo; results.\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-sortPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-auto-update\" data-bind=\"visible: !panels.isCollapsed('lp-sortPanel')\">\n                                    <div data-bind=\"template: 'designer-sort'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Settings & Options -->\n                            <div class=\"card mb-1 designer-panel\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-settingsPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-gear\"></i> Options\n                                    <i class=\"hint-tip fa fa-info-circle text-info ms-1\" data-bind=\"visible: showHints()\" data-bs-toggle=\"tooltip\" title=\"<b>Options Available:</b><br>&bull; <b>Show Total Row:</b> Adds a totals row at the bottom (Sum/Count of numeric columns)<br>&bull; <b>Page Size:</b> Number of rows per page (affects List/Summary reports)<br>&bull; <b>Show Data with Graph:</b> Display both the chart AND a data table below it<br>&bull; <b>Max Records:</b> Limit total records returned (0 = no limit)<br>&bull; <b>No Header Sort:</b> Disable column header click-to-sort on the report page<br>&bull; <b>Chart Options:</b> Colors, legend position, axis labels, gridlines, stacking, horizontal orientation\"></i>\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-settingsPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-options-wrap\" data-bind=\"visible: !panels.isCollapsed('lp-settingsPanel')\">\n                                    <div class=\"form-group row mb-2\">\n                                        <label class=\"control-label\"><i class=\"fa fa-info-circle\"></i> Description</label>\n                                        <div>\n                                            <textarea class=\"form-control form-control-sm\" rows=\"2\" placeholder=\"Optional\" data-bind=\"value: ReportDescription\"></textarea>\n                                        </div>\n                                    </div>\n                                    <div class=\"checkbox\" data-bind=\"visible: canSaveCurrentReport()\">\n                                        <label><input type=\"checkbox\" data-bind=\"checked: SaveReport\"> Save Report</label>\n                                    </div>\n                                    <div class=\"checkbox\" data-bind=\"visible: adminMode() && ReportID()\">\n                                        <label><input type=\"checkbox\" data-bind=\"checked: isSubReportOnly, click: function() { setTimeout(function() { toggleIsSubReportOnly(); }, 0); return true; }\"> Only use as sub report</label>\n                                    </div>\n                                    <div class=\"checkbox\" data-bind=\"visible: adminMode()\">\n                                       <label><input type=\"checkbox\" data-bind=\"checked: ShowAdminOnly\"> </label>\n                                        Hide from reports unless Admin Mode is enabled\n                                    </div>\n                                    <div class=\"form-group row mb-2\" data-bind=\"visible: SaveReport\">\n                                        <label class=\"control-label\"><i class=\"fa fa-folder-open\"></i> Folder</label>\n                                        <div>\n                                            <select class=\"form-select form-select-sm\" style=\"width: 100%;\" data-bind=\"options: Folders, optionsText: function(f) { return f.FolderPath || f.FolderName; }, optionsValue: 'Id', value: FolderID, valueAllowUnset: true\"></select>\n                                        </div>\n                                    </div>\n                                    <hr class=\"my-1\" />\n                                    <div data-bind=\"visible: !useStoredProc()\">\n                                        <div data-bind=\"template: 'designer-options'\"></div>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <!-- Header & Footer -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: SaveReport\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-headerFooterPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-window-maximize\"></i> Header &amp; Footer\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-headerFooterPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-headerFooterPanel')\">\n                                    <div data-bind=\"template: 'designer-header-footer'\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Schedule -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: SaveReport() && !ko.unwrap(appSettings.showScheduling) && !isSubReportOnly()\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-schedulePanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-hourglass\"></i> Schedule\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-schedulePanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2 designer-auto-update\" data-bind=\"visible: !panels.isCollapsed('lp-schedulePanel')\">\n                                    <div data-bind=\"template: {name: 'report-schedule'}\"></div>\n                                </div>\n                            </div>\n\n                            <!-- Access -->\n                            <div class=\"card mb-1 designer-panel\" data-bind=\"visible: adminMode()\">\n                                <div class=\"card-header p-2\" data-bind=\"click: function(){panels.togglePanel('lp-accessPanel')}\" style=\"cursor:pointer;\">\n                                    <i class=\"fa fa-key\"></i> Security\n                                    <i class=\"fa fa-chevron-down float-end panel-chevron\" data-bind=\"css: {'fa-chevron-right': panels.isCollapsed('lp-accessPanel')}\"></i>\n                                </div>\n                                <div class=\"card-body p-2\" data-bind=\"visible: !panels.isCollapsed('lp-accessPanel')\">\n                                    <div data-bind=\"template: {name: 'manage-access-template', data: manageAccess}\"></div>\n                                </div>\n                            </div>\n\n                        </div>\n                    </div>\n\n                    <!-- RIGHT PANEL -->\n                    <div class=\"col-md-8 h-100\" style=\"overflow-y: auto;\">\n\n                        <!-- ==================== STANDARD MODE (activeDesign OFF) ==================== -->\n                        <div data-bind=\"visible: !activeDesign()\">\n                            <div class=\"card card-body\">\n                                <h5><span class=\"fa fa-file\"></span>&nbsp;Choose Visualization</h5>\n                                <div style=\"overflow-x: auto; white-space: nowrap;\">\n                                    <div data-bind=\"template: 'designer-choose-visual'\"></div>\n                                </div>\n                            </div>\n                            <div id=\"customFunctionSection\" data-bind=\"visible: isFunctionField() && ReportType() === 'List'\" class=\"custom-field-design\">\n                                <br />\n                                <div class=\"card\">\n                                    <div class=\"card-header\"><b>Build Custom Field</b></div>\n                                    <div class=\"card-body\" data-bind=\"template: 'custom-function-designer'\"></div>\n                                </div>\n                                <div class=\"clearfix\"></div>\n                            </div>\n                            <div data-bind=\"template: 'json-field-picker'\"></div>\n                            <div id=\"customFieldSection\" data-bind=\"visible: isFormulaField\" class=\"custom-field-design\">\n                                <br />\n                                <div class=\"card\">\n                                    <div class=\"card-header\"><b>Build Custom Field</b></div>\n                                    <div class=\"card-body\" data-bind=\"template: 'custom-field-designer'\"></div>\n                                </div>\n                                <div class=\"clearfix\"></div>\n                            </div>\n                            <br />\n                            <div class=\"card card-body\">\n                                <div class=\"row\">\n                                    <h5 class=\"col-8 float-start\"><span class=\"fa fa-table\"></span>&nbsp;Selected data for the Report</h5>\n                                    <div class=\"col-4 float-end right-align\">\n                                        <a href=\"#\" class=\"small text-muted\" data-bind=\"visible: SelectedFields().length, click: function() {SelectedFields([]);}\">Clear all</a>\n                                    </div>\n                                </div>\n                                <div data-bind=\"template: 'designer-selected-data'\"></div>\n                            </div>\n                            <div data-bind=\"visible: linkedReportFields().length > 0\">\n                                <br />\n                                <div class=\"card mb-4\">\n                                    <div class=\"card-header bg-light\">\n                                        <h5 class=\"mb-0\"><i class=\"fa fa-bookmark\"></i> Include Sub Reports</h5>\n                                    </div>\n                                    <div class=\"card-body\">\n                                        <div data-bind=\"template: 'designer-sub-report'\"></div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div data-bind=\"visible: ReportType()=='Html'\">\n                                <br />\n                                <div class=\"card mb-4\">\n                                    <div class=\"card-header bg-light\">\n                                        <h5 class=\"mb-0\"><i class=\"fa fa-pencil\"></i> Design your Report</h5>\n                                    </div>\n                                    <div class=\"card-body\">\n                                        <div data-bind=\"template: 'designer-html'\"></div>\n                                    </div>\n                                </div>\n                            </div>\n                            <br />\n                            <div class=\"card card-body\">\n                                <h5><span class=\"fa fa-filter\"></span>&nbsp;Choose Filters</h5>\n                                <div class=\"row\" style=\"padding: 10px 10px; overflow-x: auto;\">\n                                    <div data-bind=\"visible: useStoredProc\" class=\"col-md-12\">\n                                        <div data-bind=\"template: {name: 'filter-parameters'}\"></div>\n                                    </div>\n                                    <div data-bind=\"visible: !useStoredProc()\" class=\"col-md-12\">\n                                        <div data-bind=\"template: {name: 'filter-group'}\"></div>\n                                    </div>\n                                    <div class=\"checkbox col-12\">\n                                        <label>\n                                            <input type=\"checkbox\" data-bind=\"checked: EditFiltersOnReport\" />\n                                            Allow setting up and saving filters on Report\n                                        </label>\n                                    </div>\n                                    <br />\n                                </div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: !useStoredProc()\" class=\"card card-body\">\n                                <h5><span class=\"fa fa-sort\"></span>&nbsp;Choose Sorting</h5>\n                                <div data-bind=\"template: 'designer-sort'\"></div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: SaveReport() && !ko.unwrap(appSettings.showScheduling) && !isSubReportOnly()\" class=\"card card-body\">\n                                <h5><span class=\"fa fa-hourglass\"></span>&nbsp;Choose Schedule</h5>\n                                <div style=\"padding: 10px 10px\" data-bind=\"visible: SaveReport\">\n                                    <div data-bind=\"template: {name: 'report-schedule'}\"></div>\n                                </div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: !useStoredProc()\">\n                                <div class=\"card card-body\">\n                                    <div data-bind=\"template: 'designer-options'\"></div>\n                                </div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: SaveReport\" class=\"card card-body\">\n                                <h5><span class=\"fa fa-window-maximize\"></span>&nbsp;Header &amp; Footer</h5>\n                                <div data-bind=\"template: 'designer-header-footer'\"></div>\n                            </div>\n                            <br />\n                            <div data-bind=\"visible: adminMode\" class=\"card card-body\">\n                                <div data-bind=\"template: {name: 'manage-access-template', data: manageAccess}\"></div>\n                            </div>\n                        </div>\n\n                        <!-- ==================== LIVE PREVIEW MODE (activeDesign ON) ==================== -->\n                        <div data-bind=\"css: {'d-flex': activeDesign(), 'd-none': !activeDesign()}\" class=\"live-preview-area flex-column\" style=\"height: 100%;\">\n                            <!-- Custom Field (shown above preview when active) -->\n                            <div data-bind=\"visible: isFormulaField()\" class=\"mb-2\">\n                                <div class=\"card custom-field-design\">\n                                    <div class=\"card-header py-1\"><i class=\"fa fa-magic\"></i> Build Custom Field</div>\n                                    <div class=\"card-body\" data-bind=\"template: 'custom-field-designer'\"></div>\n                                </div>\n                            </div>\n                            <!-- Custom Function (shown above preview when active) -->\n                            <div data-bind=\"visible: isFunctionField() && ReportType() === 'List'\" class=\"mb-2\">\n                                <div class=\"card custom-field-design\">\n                                    <div class=\"card-header py-1\"><i class=\"fa fa-magic\"></i> Build Custom Function</div>\n                                    <div class=\"card-body\" data-bind=\"template: 'custom-function-designer'\"></div>\n                                </div>\n                            </div>\n                            <div class=\"card flex-grow-1 d-flex flex-column\" style=\"min-height: 0;\">\n                                <div class=\"card-header py-2 d-flex align-items-center justify-content-between bg-light\">\n                                    <span><i class=\"fa fa-desktop\"></i> Live Preview</span>\n                                    <span class=\"text-muted small\" data-bind=\"visible: ReportName()\">\n                                        <span data-bind=\"text: ReportName\"></span>\n                                    </span>\n                                </div>\n                                <div class=\"card-body flex-grow-1\" style=\"overflow-y: auto; min-height: 0;\">\n                                    <div data-bind=\"if: typeof CanEdit === 'function' && CanEdit() && ReportType()!='Html' && ReportType()!='Single'\">\n                                        <div data-bind=\"template: 'chart-settings', data: $data\"></div>\n                                    </div>\n                                    <div data-bind=\"if: typeof CanEdit === 'function' && CanEdit() && ReportType()=='Single'\">\n                                        <div data-bind=\"template: 'kpi-settings', data: $data\"></div>\n                                    </div>\n                                    <p data-bind=\"html: ReportDescription, visible: ReportDescription\"></p>\n                                    <div data-bind=\"with: ReportResult\" class=\"small\">\n                                        <div data-bind=\"visible: !ReportData()\">\n                                            <div class=\"report-spinner\"></div>\n                                        </div>\n                                        <div data-bind=\"template: 'report-template', data: $data\"></div>\n                                    </div>\n                                </div>\n                                <div class=\"card-footer py-1\">\n                                    <div class=\"small d-flex align-items-center justify-content-between\" data-bind=\"with: pager\">\n                                        <div data-bind=\"visible: totalRecords() > 1 && $parent.ReportType() != 'Single'\">\n                                            <span data-bind=\"text: 'Total Records: ' + totalRecords()\"></span>\n                                        </div>\n                                        <div data-bind=\"visible: pages() > 1 && $parent.ReportType() != 'Single'\">\n                                            <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button class=\"btn btn-primary\" data-bind=\"visible: adminMode, click: RunReportSqlPreview\">\n                    <i class=\"fa fa-code\"></i> Preview Report Code\n                </button>\n                <button class=\"btn btn-outline-secondary\" type=\"button\" data-bind=\"visible: !SaveReport() || !ReportID(), click: startOverReport\" title=\"Clear everything and start a new report\">\n                    <i class=\"fa fa-refresh\"></i> Start Over\n                </button>\n                <a href=\"#\" class=\"btn btn-danger\" data-bind=\"click: cancelCreateReport\">Cancel editing Report</a>\n                <button class=\"btn btn-primary\" type=\"button\" data-bind=\"visible: SaveReport() && canSaveCurrentReport(), click: SaveWithoutRun, disable: savingReport() || savingAndRunning()\" style=\"padding-right: 10px;\">\n                    <!-- ko if: savingReport() --><span class=\"fa fa-spinner fa-spin me-1\"></span>Saving...<!-- /ko -->\n                    <!-- ko ifnot: savingReport() -->Save Report<!-- /ko -->\n                </button>\n                <button class=\"btn btn-primary\" type=\"button\" data-bind=\"click: SaveAndRunReport, visible: !editingSubReportParentId(), disable: savingReport() || savingAndRunning()\">\n                    <!-- ko if: savingAndRunning() --><span class=\"fa fa-spinner fa-spin me-1\"></span>Saving...<!-- /ko -->\n                    <!-- ko ifnot: savingAndRunning() --><!-- ko text: SaveReport() && canSaveCurrentReport()? 'Save & Run Report': 'Run Report' --><!-- /ko --><!-- /ko -->\n                </button>\n            </div>\n\n        </div>\n    </div>\n</script>\n\n<script type=\"text/html\" id=\"chart-settings\">\n    <div class=\"chart-container float-end\">\n        <button class=\"btn btn-light btn-sm d-flex align-items-center mt-2 chart-settings-btn\"\n                data-bind=\"click: toggleChartSettings\" title=\"Report settings\">\n            <i class=\"fa fa-cog\"></i>\n        </button>\n\n        <div class=\"chart-settings-panel border p-2 shadow-sm bg-light\" data-bind=\"visible: showSettings\">\n            <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                <button class=\"btn btn-sm btn-close\" data-bind=\"click: toggleChartSettings\"></button>\n                <h6 class=\"mb-0\">Report Settings</h6>\n            </div>\n             <ul class=\"nav nav-tabs nav-sm mb-2 small\" data-bind=\"visible: ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line'\">\n                <li class=\"nav-item\">\n                    <a class=\"nav-link\"\n                       data-bs-toggle=\"tab\"\n                       data-bind=\"attr: { href: '#chartTab-' + ReportID() }, css: { active: ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line' }\">\n                        Chart\n                    </a>\n                </li>\n                <li class=\"nav-item\">\n                    <a class=\"nav-link\"\n                       data-bs-toggle=\"tab\"\n                       data-bind=\"attr: { href: '#tableTab-' + ReportID() }, css: { active: !(ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line') }\">\n                        Table\n                    </a>\n                </li>\n            </ul>\n            <div class=\"tab-content small\">\n                <div class=\"tab-pane fade\"\n                     data-bind=\"attr: { id: 'chartTab-' + ReportID() }, css: { 'show active': ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line' }\">\n                    <div class=\"mb-2\">\n                        <div class=\"btn-group\" role=\"group\" data-bind=\"visible: ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line'\">\n                            <button type=\"button\" class=\"btn btn-light\" data-bs-toggle=\"tooltip\" title=\"Bar Chart\"\n                                    data-bind=\"css: { 'active': ReportType() === 'Bar' }, click: function() { ReportType('Bar'); }\">\n                                <span class=\"fa fa-bar-chart\"></span>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-light\" data-bs-toggle=\"tooltip\" title=\"Pie Chart\"\n                                    data-bind=\"css: { 'active': ReportType() === 'Pie' }, click: function() { ReportType('Pie'); }\">\n                                <span class=\"fa fa-pie-chart\"></span>\n                            </button>\n                            <button type=\"button\" class=\"btn btn-light\" data-bs-toggle=\"tooltip\" title=\"Line Chart\"\n                                    data-bind=\"css: { 'active': ReportType() === 'Line' }, click: function() { ReportType('Line'); }\">\n                                <span class=\"fa fa-line-chart\"></span>\n                            </button>\n                        </div>\n                    </div>\n                    <div data-bind=\"visible: ReportType()=='Bar'\">\n                        <div class=\"form-group row\">\n                            <div class=\"checkbox col-6\">\n                                <label><input type=\"checkbox\" data-bind=\"checked: barChartHorizontal\" /> Horizontal</label>\n                            </div>\n                            <div class=\"checkbox col-6\">\n                                <label><input type=\"checkbox\" data-bind=\"checked: barChartStacked\" /> Stacked</label>\n                            </div>\n                        </div>\n                    </div>\n                    <div data-bind=\"visible: ReportType()=='Pie'\">\n                        <div class=\"form-group row\">\n                            <div class=\"checkbox col-6\">\n                                <label><input type=\"checkbox\" data-bind=\"checked: pieChartDonut\" /> Donut</label>\n                            </div>\n                        </div>\n                    </div>\n                    <div data-bind=\"visible: ReportType()=='Line'\">\n                        <div class=\"form-group row\">\n                            <div class=\"checkbox col-6\">\n                                <label><input type=\"checkbox\" data-bind=\"checked: lineChartArea\" /> Area</label>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Background Color</label>\n                        <div class=\"d-flex align-items-center flex-wrap\">\n                            <input type=\"color\" class=\"color-picker\" data-bind=\"value: chartOptions().backgroundColor, attr: { placeholder: 'Select' }, event: { change: updateChart }\">\n                        </div>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Font Color</label>\n                        <div class=\"d-flex align-items-center flex-wrap\">\n                            <input type=\"color\" class=\"color-picker\" data-bind=\"value: chartOptions().fontColor, attr: { placeholder: 'Select' }, event: { change: updateChart }\">\n                        </div>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"form-label small\">Series Colors</label>\n                        <div class=\"d-flex flex-wrap\" data-bind=\"foreach: chartOptions().seriesColors\">\n                            <div class=\"color-box me-2\">\n                                <input type=\"color\" class=\"color-picker\"\n                                       data-bind=\"value: $data, event: { input: function(data, event) { $parent.updateSeriesColor($index(), event.target.value); } }\">\n                                <button class=\"btn btn-sm btn-danger remove-color\" data-bind=\"click: $parent.removeSeriesColor\">&times;</button>\n                            </div>\n                        </div>\n                        <button class=\"color-box btn btn-sm btn-secondary\" data-bind=\"click: addSeriesColor\" title=\"Add Series Color\" style=\"margin-top: -7px;\">\n                            <i class=\"fa fa-plus\"></i>\n                        </button>\n                    </div>\n                    <div class=\"d-flex justify-content-between mb-1\">\n                        <div>\n                            <label class=\"form-label small\">Legend Position</label>\n                            <select class=\"form-select form-select-sm\" data-bind=\"value: chartOptions().legendPosition, event: { change: function(data, $event) { updateLegend($event.target.value); } }\">\n                                <option value=\"top\">Top</option>\n                                <option value=\"right\">Right</option>\n                                <option value=\"bottom\">Bottom</option>\n                                <option value=\"left\">Left</option>\n                                <option value=\"none\">None</option>\n                            </select>\n                        </div>\n                        <div>\n                            <label class=\"form-label small\">Font Size</label>\n                            <input type=\"number\" class=\"form-control form-control-sm font-size-input\" data-bind=\"value: chartOptions().fontSize, event: { change: updateChart }\">\n                        </div>\n                    </div>\n                    <div data-bind=\"visible: ReportType()!='Pie'\">\n                        <div class=\"form-check form-switch small mb-1\">\n                            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: chartOptions().showXAxisLabel, event: { change: updateChart }\">\n                            <label class=\"form-check-label\">X-Axis Label</label>\n                        </div>\n                        <div class=\"form-check form-switch small mb-1\">\n                            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: chartOptions().showYAxisLabel, event: { change: updateChart }\">\n                            <label class=\"form-check-label\">Y-Axis Label</label>\n                        </div>\n                        <div class=\"form-check form-switch small mb-1\" data-bind=\"visible: ReportType() !== 'Pie'\">\n                            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: chartOptions().showGridlines, event: { change: updateChart }\">\n                            <label class=\"form-check-label\">Gridlines</label>\n                        </div>\n                        <div class=\"form-check form-switch small mb-1\">\n                            <input class=\"form-check-input\" type=\"checkbox\" data-bind=\"checked: chartOptions().showSmallValuesOnLabel, event: { change: updateChart }\">\n                            <label class=\"form-check-label\">Show Small Values On Label</label>\n                        </div>\n                        <div class=\"form-group small mb-1\">\n                            <label class=\"form-label\">Y-Axis Format</label>\n                            <select class=\"form-select form-select-sm\" data-bind=\"value: chartOptions().yAxisFormat, event: { change: function() { updateYAxisFormat(); updateChart(); } }\">\n                                <option value=\"\">Auto (from Field)</option>\n                                <option value=\"Currency\">Currency</option>\n                                <option value=\"Percentage\">Percentage</option>\n                                <option value=\"Decimal\">Decimal</option>\n                                <option value=\"Number\">Number</option>\n                            </select>\n                        </div>\n                        <div class=\"form-group small mb-1 d-flex gap-2\">\n                            <div class=\"w-50\">\n                                <label class=\"form-label\">Y-Axis Min</label>\n                                <input type=\"number\" class=\"form-control form-control-sm\" data-bind=\"value: chartOptions().yMin, event: { change: updateChart }\" />\n                            </div>\n                            <div class=\"w-50\">\n                                <label class=\"form-label\">Y-Axis Max</label>\n                                <input type=\"number\" class=\"form-control form-control-sm\" data-bind=\"value: chartOptions().yMax, event: { change: updateChart }\" />\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <div class=\"tab-pane fade\"\n                     data-bind=\"attr: { id: 'tableTab-' + ReportID() }, css: { 'show active': !(ReportType() === 'Bar' || ReportType() === 'Pie' || ReportType() === 'Line') }\">\n                    <div class=\"form-group row\">\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Header Back Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()} , value: tableSettings().headerBackColor, event: { change: updateTable }\"/>\n                        </div>\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Header Font Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()} ,value: tableSettings().headerFontColor, event: { change: updateTable }\"/>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Row Back Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()} ,value: tableSettings().rowBackColor, event: { change: updateTable }\"/>\n                        </div>\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Row Font Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()} ,value: tableSettings().rowFontColor, event: { change: updateTable }\"/>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\" style=\"display: none;\">\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Alt Row Back Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"value: tableSettings().altRowBackColor, event: { change: updateTable }\"/>\n                        </div>\n                        <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Alt Row Font Color</label>\n                            <input type=\"color\" class=\"color-picker\"\n                                   data-bind=\"value: tableSettings().altRowFontColor, event: { change: updateTable }\"/>\n                        </div>\n                    </div>\n                    <div class=\"form-group mb-2\" style=\"display: none;\">\n                        <label class=\"form-label small\">Borders</label>\n                        <div class=\"btn-group d-flex flex-wrap\">\n                            <button type=\"button\" class=\"btn btn-light btn-sm flex-fill\"\n                                    data-bind=\"click: function(){ tableSettings().border('none'); updateTable(); }, css: { active: tableSettings().border === 'none' }\">None</button>\n                            <button type=\"button\" class=\"btn btn-light btn-sm flex-fill\"\n                                    data-bind=\"click: function(){ tableSettings().border('all'); updateTable(); }, css: { active: tableSettings().border === 'all' }\">All</button>\n                            <button type=\"button\" class=\"btn btn-light btn-sm flex-fill\"\n                                    data-bind=\"click: function(){ tableSettings().border('outer'); updateTable(); }, css: { active: tableSettings().border === 'outer' }\">Outside</button>\n                            <button type=\"button\" class=\"btn btn-light btn-sm flex-fill\"\n                                    data-bind=\"click: function(){ tableSettings().border('inner'); updateTable(); }, css: { active: tableSettings().border === 'inner' }\">Inside</button>\n                        </div>\n                    </div>\n                    <div class=\"form-group row\">\n                        <div class=\"mb-2 col-6\" style=\"display: none;\">\n                            <label class=\"form-label small\">Border Color</label>\n                            <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"value: tableSettings().borderColor, event: { change: updateTable }\"/>\n                        </div>\n                         <div class=\"mb-2 col-6\">\n                            <label class=\"form-label small\">Back Color</label><br />\n                            <input type=\"color\" class=\"color-picker\"\n                               data-bind=\"attr: { id: 'tbl-color-picker-' + ReportID()},value: tableSettings().backColor, event: { change: updateTable }\"/>\n                        </div>\n                        <div class=\"mb-2 col-6 d-flex align-items-end\">\n                            <button class=\"btn btn-sm small\"\n                                    data-bind=\"click: copyTableFormat\"\n                                    title=\"Copy Format\">\n                                <i class=\"fa fa-copy\"></i>\n                            </button>\n                            <button class=\"btn btn-sm small\"\n                                    data-bind=\"click: pasteTableFormat\"\n                                    title=\"Paste Format\">\n                                <i class=\"fa fa-paste\"></i>\n                            </button>\n                            <button class=\"btn btn-sm small\" data-bind=\"click: clearTableSettings\"\n                                title=\"Clear\">\n                                <i class=\"fa fa-close\"></i>\n                            </button>\n                        </div>\n                    </div>                    \n                </div>\n            </div>\n        </div>\n    </div>\n</script>\n\n<div class=\"modal\" id=\"drilldownModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\">\n        <div class=\"modal-content\" data-bind=\"with: ChartDrillDownData\">\n            <div class=\"modal-header\">\n                <h4 class=\"modal-title\">Drilldown Data</h4>\n                <button type=\"button\" class=\"btn-close float-end\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <!-- ko if: DrillDownData -->\n            <div class=\"modal-body\">\n                <div style=\"overflow-x: auto; max-height: 500px; overflow-y: auto;\">\n                    <table class=\"table table-striped table-hover table-condensed\" data-bind=\"with: DrillDownData, attr: {class: 'table table-striped table-hover table-condensed ' + $parent.selectedStyle()}\">\n                        <thead style=\"position: sticky; top: -1px; z-index: 2;\">\n                            <tr class=\"no-highlight\">\n                                <!-- ko foreach: Columns -->\n                                <th data-bind=\"attr: { id: fieldId }, css: {'right-align': IsNumeric}, style: {'width': fieldWidth, 'background-color': headerBackColor }, hidden: outerGroup\" style=\"border-right: 1px solid;\">\n                                    <span data-bind=\"text: fieldLabel2() ? fieldLabel2() : (fieldLabel() ? fieldLabel() : fieldName), style: {'color': headerFontColor, 'font-weight': headerFontBold() ? 'bold' : 'normal'}\"></span>\n                                </th>\n                                <!-- /ko -->\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr style=\"display: none;\" data-bind=\"visible: Rows && Rows.length < 1\">\n                                <td data-bind=\"attr:{colspan: Columns.length}\">\n                                    No records found\n                                </td>\n                            </tr>\n                            <!-- ko foreach: Rows  -->\n                            <tr>\n                                <!-- ko foreach: Items -->\n                                <td data-bind=\"hidden: outerGroup, style: {'background-color': backColor, 'color': fontColor, 'font-weight': fontBold() ? 'bold' : 'normal' }\">\n                                    <div data-bind=\"style: {'width': fieldWidth }\">\n                                        <!-- ko if: LinkTo-->\n                                        <!-- ko if: $data._runLinkedReportInPlace -->\n                                        <a href=\"#\" data-bind=\"click: $data._runLinkedReportInPlace\"><span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span></a>\n                                        <!-- /ko -->\n                                        <!-- ko ifnot: $data._runLinkedReportInPlace -->\n                                        <a data-bind=\"attr: {href: LinkTo}\" target=\"_blank\"><span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span></a>\n                                        <!-- /ko -->\n                                        <!-- /ko-->\n                                        <!-- ko ifnot: LinkTo-->\n                                        <span class=\"preserve-space\" data-bind=\"html: formattedVal\"></span>\n                                        <!-- /ko-->\n                                    </div>\n                                </td>\n                                <!-- /ko-->\n                            </tr>\n                            <!-- /ko -->\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <div class=\"col-xs-12 col-centered\" data-bind=\"with: pager\">\n                    <div class=\"form-inline small text-muted\">\n                        <div class=\"float-start total-records\" data-bind=\"visible: pages()\">\n                            <span data-bind=\"text: 'Total Records: ' + totalRecords()\"></span>\n                        </div>\n                        <div class=\"float-start\">\n                            <button class=\"btn btn-xs\" title=\"Download Excel\" data-bind=\"click: $parent.exportExcel\"><span class=\"fas fa-file-excel\"></span></button>\n                            <button class=\"btn btn-secondary btn-sm\" data-bs-toggle=\"modal\" data-bs-target=\"#sqlDrillDownModal\" data-bind=\"visible: $root.adminMode\">\n                                <span class=\"fa fa-code\"></span> View Code\n                            </button>\n                        </div>\n                        <div class=\"form-group float-end\" data-bind=\"visible: pages()\">\n                            <div data-bind=\"template: 'pager-template', data: $data\"></div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <!-- /ko -->\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"sqlModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header d-flex justify-content-between align-items-center\">\n                <h4 class=\"modal-title\">Report Code</h4>\n                <button class=\"btn btn-outline-secondary btn-sm d-flex align-items-center\"\n                        data-bind=\"click: function(data, event) { copySqlToClipboard(event.target); }\">\n                    <i class=\"fa fa-clipboard\"></i>&nbsp;Copy\n                </button>\n                <button type=\"button\" class=\"btn-close float-end\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\" data-bind=\"with: ReportResult\">\n                <div id=\"reportSqlCode\" style=\"overflow-x: auto; max-height: 500px; overflow-y: scroll; border: 1px solid; padding: 10px;\" class=\"bg-dark text-light\">\n                    <pre><code data-bind=\"html: ReportSql\" style=\"white-space: pre-wrap;\"></code></pre>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n\n<div class=\"modal\" id=\"sqlDrillDownModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-lg\">\n        <div class=\"modal-content\" data-bind=\"with:ChartDrillDownData\">\n            <div class=\"modal-header d-flex justify-content-between align-items-center\">\n                <h4 class=\"modal-title\">Drill Down Report Code</h4>\n                <button class=\"btn btn-outline-secondary btn-sm d-flex align-items-center\"\n                        data-bind=\"click: function(data, event) { copySqlToClipboard(event.target); }\">\n                    <i class=\"fa fa-clipboard\"></i>&nbsp;Copy\n                </button>\n                <button type=\"button\" class=\"btn-close float-end\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\" data-bind=\"with:DrillDownData\">\n                <div id=\"reportSqlCode\" style=\"overflow-x: auto; max-height: 500px; overflow-y: scroll; border: 1px solid; padding: 10px;\" class=\"bg-dark text-light\">\n                    <pre><code data-bind=\"html: ReportSql\" style=\"white-space: pre-wrap;\"></code></pre>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n<div class=\"modal\" id=\"noaccountModal\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\n    <div class=\"modal-dialog\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n                <h4 class=\"modal-title\">Account not Setup</h4>\n            </div>\n            <div class=\"modal-body\">\n                <p class=\"alert alert-danger\">dotnet Report Account Configuration missing!</p>\n                <p>You do not have the neccessary initial configuration completed to use dotnet Report.</p>\n                <p>Please view the <a href=\"https://dotnetreport.com/blogs/getting-started-with-dotnet-report/\" target=\"_blank\">Getting Started Guide</a> to correctly configure dotnet Report.</p>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-default\" data-bs-dismiss=\"modal\">Close</button>\n            </div>\n        </div>\n    </div>\n</div>\n<script type=\"text/html\" id=\"pdf-options-schedule-template\">\n    <div class=\"modal-dialog modal-dialog-centered\">\n        <div class=\"modal-content\" data-bind=\"with: PdfPage\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"pdfOptionsScheduleModalLabel\">\n                    <i class=\"fas fa-file-pdf me-2\"></i> Set PDF Page Size\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body row g-0\">\n                <div class=\"col-md-5 d-flex justify-content-center align-items-center\">\n                    <div id=\"pagePreviewBox\" class=\"text-center\">\n                        <div data-bind=\"style: {\n                                     width: selectedWidth(),\n                                     height: selectedHeight(),\n                                     backgroundColor: selectedBackgroundStyle(),\n                                     transition: 'all 0.3s ease'\n                                 }\"\n                             class=\"shadow rounded mx-auto mb-2 border position-relative\">\n                            <span class=\"position-absolute top-50 start-50 translate-middle text-muted small\">Preview</span>\n                        </div>\n                        <div data-bind=\"text: selectedPageLabel\" class=\"fw-bold\"></div>\n                        <div data-bind=\"text: selectedPageDimension\" class=\"text-muted small\"></div>\n                    </div>\n                </div>\n                <div class=\"col-md-7\">\n                    <div class=\"mb-3\">\n                        <label for=\"pageSizeSelect\" class=\"form-label fw-bold\">Page Size:</label>\n                        <select class=\"form-select\" id=\"pageSizeSelect\"\n                                data-bind=\"options: availablePageSizes,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageSize\">\n                        </select>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"pageOrientationSelect\" class=\"form-label fw-bold\">Page Orientation:</label>\n                        <select class=\"form-select\" id=\"pageOrientationSelect\"\n                                data-bind=\"options: availablePageOrientation,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageOrientation\">\n                        </select>\n                    </div>\n                    <div class=\"alert alert-info p-2 small mt-2\">\n                        This PDF will be exported using the selected page size. Ensure your content fits well.\n                        If the content width exceeds the selected size, it will default to Letter.\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-success\" data-bs-dismiss=\"modal\" data-bind=\"click: save\">\n                     Save\n                </button>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"word-options-schedule-template\">\n    <div class=\"modal-dialog modal-dialog-centered\">\n        <div class=\"modal-content\" data-bind=\"with: WordPage\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"pdfOptionsScheduleModalLabel\">\n                    <i class=\"fas fa-file-pdf me-2\"></i> Set WORD Page Size\n                </h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body row g-0\">\n                <div class=\"col-md-5 d-flex justify-content-center align-items-center\">\n                    <div id=\"pagePreviewBox\" class=\"text-center\">\n                        <div data-bind=\"style: {\n                                     width: selectedWidth(),\n                                     height: selectedHeight(),\n                                     backgroundColor: selectedBackgroundStyle(),\n                                     transition: 'all 0.3s ease'\n                                 }\"\n                             class=\"shadow rounded mx-auto mb-2 border position-relative\">\n                            <span class=\"position-absolute top-50 start-50 translate-middle text-muted small\">Preview</span>\n                        </div>\n                        <div data-bind=\"text: selectedPageLabel\" class=\"fw-bold\"></div>\n                        <div data-bind=\"text: selectedPageDimension\" class=\"text-muted small\"></div>\n                    </div>\n                </div>\n                <div class=\"col-md-7\">\n                    <div class=\"mb-3\">\n                        <label for=\"pageSizeSelect\" class=\"form-label fw-bold\">Page Size:</label>\n                        <select class=\"form-select\" id=\"pageSizeSelect\"\n                                data-bind=\"options: availablePageSizes,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageSize\">\n                        </select>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"pageOrientationSelect\" class=\"form-label fw-bold\">Page Orientation:</label>\n                        <select class=\"form-select\" id=\"pageOrientationSelect\"\n                                data-bind=\"options: availablePageOrientation,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageOrientation\">\n                        </select>\n                    </div>\n                    <div class=\"alert alert-info p-2 small mt-2\">\n                        This WORD will be exported using the selected page size. Ensure your content fits well.\n                        If the content width exceeds the selected size, it will default to Letter.\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-success\" data-bs-dismiss=\"modal\" data-bind=\"click: save\">\n                     Save\n                </button>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"word-options-template\">\n        <div class=\"modal-dialog modal-dialog-centered\">\n        <div class=\"modal-content\" data-bind=\"with: WordPage\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"wordOptionsModalLabel\"><i class=\"fas fa-file-pdf me-2\"></i> Export to WORD</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body row g-0\">\n                <!-- Left Side: Page Preview SVG -->\n                <div class=\"col-md-5 d-flex justify-content-center align-items-center\">\n                    <div id=\"pagePreviewBox\" class=\"text-center\">\n                        <div data-bind=\"style: {\n                                     width: selectedWidth(),\n                                     height: selectedHeight(),\n                                     backgroundColor: selectedBackgroundStyle(),\n                                     transition: 'all 0.3s ease'\n                                 }\"\n                             class=\"shadow rounded mx-auto mb-2 border position-relative\">\n                            <span class=\"position-absolute top-50 start-50 translate-middle text-muted small\">Preview</span>\n                        </div>\n                        <div data-bind=\"text: selectedPageLabel\" class=\"fw-bold\"></div>\n                        <div data-bind=\"text: selectedPageDimension\" class=\"text-muted small\"></div>\n                    </div>\n                </div>\n\n                <!-- Right Side: Form Options -->\n                <div class=\"col-md-7\">\n                    <div class=\"mb-3\">\n                        <label for=\"pageSizeSelect\" class=\"form-label fw-bold\">Page Size:</label>\n                        <select class=\"form-select\" id=\"pageSizeSelect\"\n                                data-bind=\"options: availablePageSizes,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageSize\">\n                        </select>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"pageOrientationSelect\" class=\"form-label fw-bold\">Page Orientation:</label>\n                        <select class=\"form-select\" id=\"pageOrientationSelect\"\n                                data-bind=\"options: availablePageOrientation,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageOrientation\">\n                        </select>\n                    </div>\n                    <div class=\"alert alert-info p-2 small mt-2\">\n                        This Word will be exported using the selected page size. Ensure your content fits well.\n                        If the content width exceeds the selected size, it will default to Letter.\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-success\" data-bs-dismiss=\"modal\" data-bind=\"click: download\">\n                    <i class=\"fa fa-download me-1\"></i> Download Word\n                </button>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"pdf-options-template\">\n    <div class=\"modal-dialog modal-dialog-centered\">\n        <div class=\"modal-content\" data-bind=\"with: PdfPage\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"pdfOptionsModalLabel\"><i class=\"fas fa-file-pdf me-2\"></i> Export to PDF</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body row g-0\">\n                <!-- Left Side: Page Preview SVG -->\n                <div class=\"col-md-5 d-flex justify-content-center align-items-center\">\n                    <div id=\"pagePreviewBox\" class=\"text-center\">\n                        <div data-bind=\"style: {\n                                     width: selectedWidth(),\n                                     height: selectedHeight(),\n                                     backgroundColor: selectedBackgroundStyle(),\n                                     transition: 'all 0.3s ease'\n                                 }\"\n                             class=\"shadow rounded mx-auto mb-2 border position-relative\">\n                            <span class=\"position-absolute top-50 start-50 translate-middle text-muted small\">Preview</span>\n                        </div>\n                        <div data-bind=\"text: selectedPageLabel\" class=\"fw-bold\"></div>\n                        <div data-bind=\"text: selectedPageDimension\" class=\"text-muted small\"></div>\n                    </div>\n                </div>\n\n                <!-- Right Side: Form Options -->\n                <div class=\"col-md-7\">\n                    <div class=\"mb-3\">\n                        <label for=\"pageSizeSelect\" class=\"form-label fw-bold\">Page Size:</label>\n                        <select class=\"form-select\" id=\"pageSizeSelect\"\n                                data-bind=\"options: availablePageSizes,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageSize\">\n                        </select>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"pageOrientationSelect\" class=\"form-label fw-bold\">Page Orientation:</label>\n                        <select class=\"form-select\" id=\"pageOrientationSelect\"\n                                data-bind=\"options: availablePageOrientation,\n                                           optionsText: 'label',\n                                           optionsValue: 'value',\n                                           value: selectedPageOrientation\">\n                        </select>\n                    </div>\n                    <div class=\"alert alert-info p-2 small mt-2\">\n                        This PDF will be exported using the selected page size. Ensure your content fits well.\n                        If the content width exceeds the selected size, it will default to Letter.\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-light\" data-bs-dismiss=\"modal\">Cancel</button>\n                <button type=\"button\" class=\"btn btn-success\" data-bs-dismiss=\"modal\" data-bind=\"click: download\">\n                    <i class=\"fa fa-download me-1\"></i> Download PDF\n                </button>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"line-separator-template\">\n    <div class=\"grid-stack-item-content position-relative p-2\" data-bind=\"css: { card: $root.arrangeDashboard }\">\n        <hr data-bind=\"style: { borderTop: thickness() + 'px solid ' + color() }\" class=\"m-0\">\n        <div data-bind=\"visible: $root.arrangeDashboard\" class=\"dropdown position-absolute\" style=\"top:-5px; right:0; z-index:2000;\">\n            <button class=\"btn btn-sm btn-light\" type=\"button\" data-bs-toggle=\"dropdown\">\n                <i class=\"fa fa-ellipsis-v\"></i>\n            </button>\n               <ul class=\"dropdown-menu dropdown-menu-end p-2 bg-light small\">\n                    <li class=\"d-flex align-items-center gap-2 mb-2\">\n                        <label class=\"form-label small mb-0\">Line Color</label>\n                        <input type=\"color\" class=\"color-picker\" data-bind=\"value: color,valueUpdate: 'input',event: { change: () => $root.onWidgetChange($data)}\">\n                    </li>\n\n                    <li class=\"d-flex align-items-center gap-2 mb-2\">\n                        <label class=\"mb-0\">Thickness</label>\n                        <input type=\"number\"\n                               min=\"1\"\n                               max=\"10\"\n                               data-bind=\"value: thickness,valueUpdate: 'input',event: { change: () => $root.onWidgetChange($data)}\"\n                               class=\"form-control form-control-sm\"\n                               style=\"width:50px\">\n                    </li>\n\n                    <li>\n                        <button class=\"dropdown-item text-danger\" data-bind=\"click: deleteSeparator\">\n                            <i class=\"fa fa-trash me-2\"></i>\n                            Delete\n                        </button>\n                    </li>\n                </ul>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"text-widget-template\">\n    <div class=\"grid-stack-item-content position-relative p-2\" data-bind=\"css: { card: $root.arrangeDashboard }\">\n        <div data-bind=\"html: decodeURIComponent(text())\"></div>\n        <div class=\"position-absolute\" style=\"top:3px; right:4px; z-index:2000;\" data-bind=\"visible: $root.arrangeDashboard\">\n            <div class=\"dropdown\">\n                <button class=\"btn btn-sm btn-light\"\n                        type=\"button\"\n                        data-bs-toggle=\"dropdown\"\n                        aria-expanded=\"false\">\n                    <i class=\"fa fa-ellipsis-v\"></i>\n                </button>\n                <ul class=\"dropdown-menu dropdown-menu-end\">\n                    <li>\n                        <button class=\"dropdown-item\"\n                                data-bind=\"click: $root.openTextEditor\">\n                            <i class=\"fa fa-edit me-2\"></i>\n                            Edit\n                        </button>\n                    </li>\n                    <li>\n                        <button class=\"dropdown-item text-danger\"\n                                data-bind=\"click: deleteText\">\n                            <i class=\"fa fa-trash me-2\"></i>\n                            Delete\n                        </button>\n                    </li>\n                </ul>\n            </div>\n        </div>\n    </div>\n</script>\n<script type=\"text/html\" id=\"users-roles-sql-source\">\n    <!-- ko if: $parent.userSource() === 'sql' -->\n    <div class=\"mb-3\" data-bind=\"if: $parent.userSource() === 'sql'\">\n        <div class=\"d-flex align-items-center mb-2\">\n            <button class=\"btn btn-primary btn-sm\" data-bind=\"visible: savedId() === 0, click: function() { $parent.editSqlSource($data); }\">\n                <i class=\"fa fa-plus\"></i> Add <span data-bind=\"text: title\"></span>\n            </button>\n            <span class=\"ms-3 text-muted small\" data-bind=\"text: hint\"></span>\n        </div>\n        <div class=\"alert alert-info py-2 small\" data-bind=\"visible: savedId() === 0\">\n            No <span data-bind=\"text: title\"></span> yet.\n        </div>\n        <table class=\"table table-striped table-sm\" data-bind=\"visible: savedId() > 0\">\n            <thead>\n                <tr>\n                    <th style=\"width: 22%\">Name</th>\n                    <th style=\"width: 68%\">Query</th>\n                    <th style=\"width: 10%\"></th>\n                </tr>\n            </thead>\n            <tbody>\n                <tr>\n                    <td data-bind=\"text: title\"></td>\n                    <td><code class=\"small text-truncate d-inline-block\" style=\"max-width: 520px;\" data-bind=\"text: sqlQuery\"></code></td>\n                    <td class=\"text-end text-nowrap\">\n                        <button class=\"btn btn-sm btn-light\" title=\"Show the rows this query returns\" data-bind=\"click: function() { $parent.previewSqlSource($data); }\"><i class=\"fa fa-search\"></i></button>\n                        <button class=\"btn btn-sm btn-light\" title=\"Edit\" data-bind=\"click: function() { $parent.editSqlSource($data); }\"><i class=\"fa fa-pencil\"></i></button>\n                        <button class=\"btn btn-sm btn-light text-danger\" title=\"Delete\" data-bind=\"click: function() { $parent.deleteSqlSource($data); }\"><i class=\"fa fa-trash\"></i></button>\n                    </td>\n                </tr>\n            </tbody>\n        </table>\n    </div>\n    <!-- /ko -->\n</script>\n<!-- Configure Joins Modal -->\n<div class=\"modal\" id=\"weightedmodal-configure-joins\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\" data-bind=\"with: selectedReport\">\n    <div class=\"modal-dialog modal-lg \">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h5 class=\"modal-title\" id=\"configureJoinsLabel\"><i class=\"fa fa-link\"></i> Configure Joins for Report</h5>\n                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"modal-body\">\n                <p class=\"text-muted small\">Override join types and drag to reorder for this report only.</p>\n\n                <!-- ko if: detectedJoins().length === 0 -->\n                <div class=\"alert alert-info\">\n                    <i class=\"fa fa-info-circle\"></i> No joins detected. Make sure you have selected fields from multiple tables.\n                </div>\n                <!-- /ko -->\n\n                <!-- ko if: detectedJoins().length > 0 -->\n                <div class=\"mb-3 p-2 bg-light rounded d-flex align-items-center\">\n                    <label class=\"fw-bold small me-2 text-nowrap\">FROM (First Table):</label>\n                    <select class=\"form-select form-select-sm\" style=\"max-width: 250px;\"\n                            data-bind=\"options: joinBaseTables, optionsText: 'name', optionsValue: 'id', value: baseTableIdOverride\"></select>\n                </div>\n\n                <div class=\"row fw-bold border-bottom pb-2 mb-1 small text-muted\">\n                    <div class=\"col-1\"></div>\n                    <div class=\"col-2\">Table</div>\n                    <div class=\"col-2\">Field</div>\n                    <div class=\"col-1\"></div>\n                    <div class=\"col-2\">Join Type</div>\n                    <div class=\"col-2\">Joined Table</div>\n                    <div class=\"col-2\">Join Field</div>\n                </div>\n                <div data-bind=\"sortable: { data: detectedJoins, options: { handle: '.report-join-drag-handle', cursor: 'move' }, afterMove: reportJoinSorted }\">\n                    <div class=\"row align-items-center border-bottom py-2\">\n                        <div class=\"col-1\">\n                            <span class=\"btn btn-sm btn-outline-secondary report-join-drag-handle\" title=\"Drag to reorder\"><i class=\"fa fa-bars\"></i></span>\n                        </div>\n                        <div class=\"col-2\">\n                            <span data-bind=\"text: tableName\"></span>\n                            <!-- ko if: isForeignKey -->\n                            <span class=\"badge bg-info ms-1\" title=\"Foreign Key Join\">FK</span>\n                            <!-- /ko -->\n                        </div>\n                        <div class=\"col-2\"><code data-bind=\"text: fieldName\"></code></div>\n                        <div class=\"col-1 text-center\">\n                            <button class=\"btn btn-sm btn-outline-primary\" title=\"Swap Table ↔ Joined Table\" data-bind=\"click: $parent.swapJoinDirection\">\n                                <i class=\"fa fa-exchange\"></i>\n                            </button>\n                        </div>\n                        <div class=\"col-2\">\n                            <select class=\"form-select form-select-sm\"\n                                    data-bind=\"options: ['INNER','LEFT','RIGHT','CROSS'], value: joinType\"></select>\n                        </div>\n                        <div class=\"col-2\" data-bind=\"text: joinedTableName\"></div>\n                        <div class=\"col-2\"><code data-bind=\"text: joinFieldName\"></code></div>\n                    </div>\n                </div>\n                <!-- /ko -->\n            </div>\n            <div class=\"modal-footer\">\n                <button class=\"btn btn-outline-secondary btn-sm\" data-bind=\"click: clearCustomJoins\">\n                    <i class=\"fa fa-times\"></i> Clear Overrides\n                </button>\n                <button class=\"btn btn-primary btn-sm\" data-bind=\"click: saveCustomJoins\">\n                    <i class=\"fa fa-check\"></i> Apply to Report\n                </button>\n            </div>\n        </div>\n    </div>\n</div>\n\n\n<!-- Templates -->\n</div>";
export const dateFormatPopover = "\n    <table class=\"table table-sm table-borderless mb-0\" style=\"font-size:12px\">\n      <tr><td colspan=\"2\" class=\"fw-bold text-primary border-bottom pb-1\">Day</td></tr>\n      <tr><td><code>d</code></td><td>1, 2 … 31</td></tr>\n      <tr><td><code>dd</code></td><td>01, 02 … 31</td></tr>\n      <tr><td><code>ddd</code></td><td>Mon, Tue …</td></tr>\n      <tr><td><code>dddd</code></td><td>Monday, Tuesday …</td></tr>\n      <tr><td colspan=\"2\" class=\"fw-bold text-primary border-bottom pb-1 pt-2\">Month</td></tr>\n      <tr><td><code>M</code></td><td>1, 2 … 12</td></tr>\n      <tr><td><code>MM</code></td><td>01, 02 … 12</td></tr>\n      <tr><td><code>MMM</code></td><td>Jan, Feb …</td></tr>\n      <tr><td><code>MMMM</code></td><td>January, February …</td></tr>\n      <tr><td colspan=\"2\" class=\"fw-bold text-primary border-bottom pb-1 pt-2\">Year</td></tr>\n      <tr><td><code>yy</code></td><td>26, 27 …</td></tr>\n      <tr><td><code>yyyy</code></td><td>2026, 2027 …</td></tr>\n      <tr><td colspan=\"2\" class=\"fw-bold text-primary border-bottom pb-1 pt-2\">Time</td></tr>\n      <tr><td><code>h</code></td><td>1–12 (12hr)</td></tr>\n      <tr><td><code>hh</code></td><td>01–12 (12hr)</td></tr>\n      <tr><td><code>H</code></td><td>0–23 (24hr)</td></tr>\n      <tr><td><code>HH</code></td><td>00–23 (24hr)</td></tr>\n      <tr><td><code>mm</code></td><td>Minutes (00–59)</td></tr>\n      <tr><td><code>ss</code></td><td>Seconds (00–59)</td></tr>\n      <tr><td><code>tt</code></td><td>AM / PM</td></tr>\n    </table>\n    <div class=\"text-muted mt-1\" style=\"font-size:11px\">\n      <b>Examples:</b> dd/MM/yyyy • MMM dd, yyyy • yyyy-MM-dd HH:mm\n    </div>\n  ";
